window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["GEN"]={"book":"GEN","editions":{"hbo-source":[[1,1,"בְּ⁠רֵאשִׁ֖ית בָּרָ֣א אֱלֹהִ֑ים אֵ֥ת הַ⁠שָּׁמַ֖יִם וְ⁠אֵ֥ת הָ⁠אָֽרֶץ׃","bĕ̇⁠réʼşǐ֖yţ bá̇rá֣ʼ ʼèlòhi֑ym ʼé֥ţ ha⁠şá̇̌ma֖yim wĕ⁠ʼé֥ţ há⁠ʼáֽreẕ׃"],[1,2,"וְ⁠הָ⁠אָ֗רֶץ הָיְתָ֥ה תֹ֨הוּ֙ וָ⁠בֹ֔הוּ וְ⁠חֹ֖שֶׁךְ עַל־פְּנֵ֣י תְה֑וֹם וְ⁠ר֣וּחַ אֱלֹהִ֔ים מְרַחֶ֖פֶת עַל־פְּנֵ֥י הַ⁠מָּֽיִם׃","wĕ⁠há⁠ʼá֗reẕ háyĕţá֥h ţò֨hẇ֙ wá⁠bò֔hẇ wĕ⁠ẖò֖şěkĕ ʻal-pĕ̇né֣y ţĕh֑wòm wĕ⁠r֣ẇẖa ʼèlòhi֔ym mĕraẖe֖peţ ʻal-pĕ̇né֥y ha⁠máֽ̇yim׃"],[1,3,"וַ⁠יֹּ֥אמֶר אֱלֹהִ֖ים יְהִ֣י א֑וֹר וַֽ⁠יְהִי־אֽוֹר׃","wa⁠yò֥̇ʼmer ʼèlòhi֖ym yĕhi֣y ʼ֑wòr waֽ⁠yĕhiy-ʼֽwòr׃"],[1,4,"וַ⁠יַּ֧רְא אֱלֹהִ֛ים אֶת־הָ⁠א֖וֹר כִּי־ט֑וֹב וַ⁠יַּבְדֵּ֣ל אֱלֹהִ֔ים בֵּ֥ין הָ⁠א֖וֹר וּ⁠בֵ֥ין הַ⁠חֹֽשֶׁךְ׃","wa⁠yȧ֧rĕʼ ʼèlòhi֛ym ʼeţ-há⁠ʼ֖wòr ki̇y-t֑wòb wa⁠yȧbĕdé֣̇l ʼèlòhi֔ym bé֥̇yn há⁠ʼ֖wòr ẇ⁠bé֥yn ha⁠ẖòֽşěkĕ׃"],[1,5,"וַ⁠יִּקְרָ֨א אֱלֹהִ֤ים ׀ לָ⁠אוֹר֙ י֔וֹם וְ⁠לַ⁠חֹ֖שֶׁךְ קָ֣רָא לָ֑יְלָה וַֽ⁠יְהִי־עֶ֥רֶב וַֽ⁠יְהִי־בֹ֖קֶר י֥וֹם אֶחָֽד׃פ","wa⁠yi̇qĕrá֨ʼ ʼèlòhi֤ym ׀ lá⁠ʼwòr֙ y֔wòm wĕ⁠la⁠ẖò֖şěkĕ qá֣ráʼ lá֑yĕláh waֽ⁠yĕhiy-ʻe֥reb waֽ⁠yĕhiy-bò֖qer y֥wòm ʼeẖáֽd׃p"],[1,6,"וַ⁠יֹּ֣אמֶר אֱלֹהִ֔ים יְהִ֥י רָקִ֖יעַ בְּ⁠ת֣וֹךְ הַ⁠מָּ֑יִם וִ⁠יהִ֣י מַבְדִּ֔יל בֵּ֥ין מַ֖יִם לָ⁠מָֽיִם׃","wa⁠yò֣̇ʼmer ʼèlòhi֔ym yĕhi֥y ráqi֖yʻa bĕ̇⁠ţ֣wòkĕ ha⁠má֑̇yim wi⁠yhi֣y mabĕdi̇֔yl bé֥̇yn ma֖yim lá⁠máֽyim׃"],[1,7,"וַ⁠יַּ֣עַשׂ אֱלֹהִים֮ אֶת־הָ⁠רָקִיעַ֒ וַ⁠יַּבְדֵּ֗ל בֵּ֤ין הַ⁠מַּ֨יִם֙ אֲשֶׁר֙ מִ⁠תַּ֣חַת לָ⁠רָקִ֔יעַ וּ⁠בֵ֣ין הַ⁠מַּ֔יִם אֲשֶׁ֖ר מֵ⁠עַ֣ל לָ⁠רָקִ֑יעַ וַֽ⁠יְהִי־כֵֽן׃","wa⁠yȧ֣ʻaş̂ ʼèlòhiym֮ ʼeţ-há⁠ráqiyʻa֒ wa⁠yȧbĕdé̇֗l bé֤̇yn ha⁠mȧ֨yim֙ ʼàşěr֙ mi⁠ţȧ֣ẖaţ lá⁠ráqi֔yʻa ẇ⁠bé֣yn ha⁠mȧ֔yim ʼàşě֖r mé⁠ʻa֣l lá⁠ráqi֑yʻa wֽa⁠yĕhiy-kéֽn׃"],[1,8,"וַ⁠יִּקְרָ֧א אֱלֹהִ֛ים לָֽ⁠רָקִ֖יעַ שָׁמָ֑יִם וַֽ⁠יְהִי־עֶ֥רֶב וַֽ⁠יְהִי־בֹ֖קֶר י֥וֹם שֵׁנִֽי׃פ","wa⁠yi̇qĕrá֧ʼ ʼèlòhi֛ym láֽ⁠ráqi֖yʻa şá̌má֑yim waֽ⁠yĕhiy-ʻe֥reb waֽ⁠yĕhiy-bò֖qer y֥wòm şé̌niֽy׃p"],[1,9,"וַ⁠יֹּ֣אמֶר אֱלֹהִ֗ים יִקָּו֨וּ הַ⁠מַּ֜יִם מִ⁠תַּ֤חַת הַ⁠שָּׁמַ֨יִם֙ אֶל־מָק֣וֹם אֶחָ֔ד וְ⁠תֵרָאֶ֖ה הַ⁠יַּבָּשָׁ֑ה וַֽ⁠יְהִי־כֵֽן׃","wa⁠yò֣̇ʼmer ʼèlòhi֗ym yiqá̇w֨ẇ ha⁠mȧ֜yim mi⁠ţȧ֤ẖaţ ha⁠şá̇̌ma֨yim֙ ʼel-máq֣wòm ʼeẖá֔d wĕ⁠ţéráʼe֖h ha⁠yȧbá̇şá֑̌h waֽ⁠yĕhiy-kéֽn׃"],[1,10,"וַ⁠יִּקְרָ֨א אֱלֹהִ֤ים ׀ לַ⁠יַּבָּשָׁה֙ אֶ֔רֶץ וּ⁠לְ⁠מִקְוֵ֥ה הַ⁠מַּ֖יִם קָרָ֣א יַמִּ֑ים וַ⁠יַּ֥רְא אֱלֹהִ֖ים כִּי־טֽוֹב׃","wa⁠yi̇qĕrá֨ʼ ʼèlòhi֤ym ׀ la⁠yȧbá̇şá̌h֙ ʼe֔reẕ ẇ⁠lĕ⁠miqĕwé֥h ha⁠mȧ֖yim qárá֣ʼ yami֑̇ym wa⁠yȧ֥rĕʼ ʼèlòhi֖ym ki̇y-tֽwòb׃"],[1,11,"וַ⁠יֹּ֣אמֶר אֱלֹהִ֗ים תַּֽדְשֵׁ֤א הָ⁠אָ֨רֶץ֙ דֶּ֔שֶׁא עֵ֚שֶׂב מַזְרִ֣יעַ זֶ֔רַע עֵ֣ץ פְּרִ֞י עֹ֤שֶׂה פְּרִי֙ לְ⁠מִינ֔⁠וֹ אֲשֶׁ֥ר זַרְע⁠וֹ־ב֖⁠וֹ עַל־הָ⁠אָ֑רֶץ וַֽ⁠יְהִי־כֵֽן׃","wa⁠yò֣̇ʼmer ʼèlòhi֗ym ţȧֽdĕşé֤̌ʼ há⁠ʼá֨reẕ֙ dė֔şěʼ ʻé֚şêb mazĕri֣yʻa ze֔raʻ ʻé֣ẕ pĕ̇ri֞y ʻò֤şêh pĕ̇riy֙ lĕ⁠miyn֔⁠wò ʼàşě֥r zarĕʻ⁠wò-b֖⁠wò ʻal-há⁠ʼá֑reẕ waֽ⁠yĕhiy-kéֽn׃"],[1,12,"וַ⁠תּוֹצֵ֨א הָ⁠אָ֜רֶץ דֶּ֠שֶׁא עֵ֣שֶׂב מַזְרִ֤יעַ זֶ֨רַע֙ לְ⁠מִינֵ֔⁠הוּ וְ⁠עֵ֧ץ עֹֽשֶׂה־פְּרִ֛י אֲשֶׁ֥ר זַרְע⁠וֹ־ב֖⁠וֹ לְ⁠מִינֵ֑⁠הוּ וַ⁠יַּ֥רְא אֱלֹהִ֖ים כִּי־טֽוֹב׃","wa⁠ţ̇wòẕé֨ʼ há⁠ʼá֜reẕ dė֠şěʼ ʻé֣şêb mazĕri֤yʻa ze֨raʻ֙ lĕ⁠miyné֔⁠hẇ wĕ⁠ʻé֧ẕ ʻòֽşêh-pĕ̇ri֛y ʼàşě֥r zarĕʻ⁠wò-b֖⁠wò lĕ⁠miyné֑⁠hẇ wa⁠yȧ֥rĕʼ ʼèlòhi֖ym ki̇y-tֽwòb׃"],[1,13,"וַֽ⁠יְהִי־עֶ֥רֶב וַֽ⁠יְהִי־בֹ֖קֶר י֥וֹם שְׁלִישִֽׁי׃פ","wֽa⁠yĕhiy-ʻe֥reb wֽa⁠yĕhiy-bò֖qer y֥wòm şĕ̌liyşǐֽy׃p"],[1,14,"וַ⁠יֹּ֣אמֶר אֱלֹהִ֗ים יְהִ֤י מְאֹרֹת֙ בִּ⁠רְקִ֣יעַ הַ⁠שָּׁמַ֔יִם לְ⁠הַבְדִּ֕יל בֵּ֥ין הַ⁠יּ֖וֹם וּ⁠בֵ֣ין הַ⁠לָּ֑יְלָה וְ⁠הָי֤וּ לְ⁠אֹתֹת֙ וּ⁠לְ⁠מ֣וֹעֲדִ֔ים וּ⁠לְ⁠יָמִ֖ים וְ⁠שָׁנִֽים׃","wa⁠yò֣̇ʼmer ʼèlòhi֗ym yĕhi֤y mĕʼòròţ֙ bi̇⁠rĕqi֣yʻa ha⁠şá̇̌ma֔yim lĕ⁠habĕdi̇֕yl bé֥̇yn ha⁠ẏ֖wòm ẇ⁠bé֣yn ha⁠lá֑̇yĕláh wĕ⁠háy֤ẇ lĕ⁠ʼòţòţ֙ ẇ⁠lĕ⁠m֣wòʻàdi֔ym ẇ⁠lĕ⁠yámi֖ym wĕ⁠şá̌niֽym׃"],[1,15,"וְ⁠הָי֤וּ לִ⁠מְאוֹרֹת֙ בִּ⁠רְקִ֣יעַ הַ⁠שָּׁמַ֔יִם לְ⁠הָאִ֖יר עַל־הָ⁠אָ֑רֶץ וַֽ⁠יְהִי־כֵֽן׃","wĕ⁠háy֤ẇ li⁠mĕʼwòròţ֙ bi̇⁠rĕqi֣yʻa ha⁠şá̇̌ma֔yim lĕ⁠háʼi֖yr ʻal-há⁠ʼá֑reẕ wֽa⁠yĕhiy-kéֽn׃"],[1,16,"וַ⁠יַּ֣עַשׂ אֱלֹהִ֔ים אֶת־שְׁנֵ֥י הַ⁠מְּאֹרֹ֖ת הַ⁠גְּדֹלִ֑ים אֶת־הַ⁠מָּא֤וֹר הַ⁠גָּדֹל֙ לְ⁠מֶמְשֶׁ֣לֶת הַ⁠יּ֔וֹם וְ⁠אֶת־הַ⁠מָּא֤וֹר הַ⁠קָּטֹן֙ לְ⁠מֶמְשֶׁ֣לֶת הַ⁠לַּ֔יְלָה וְ⁠אֵ֖ת הַ⁠כּוֹכָבִֽים׃","wa⁠yȧ֣ʻaş̂ ʼèlòhi֔ym ʼeţ-şĕ̌né֥y ha⁠mĕ̇ʼòrò֖ţ ha⁠gĕ̇dòli֑ym ʼeţ-ha⁠má̇ʼ֤wòr ha⁠gá̇dòl֙ lĕ⁠memĕşě֣leţ ha⁠ẏ֔wòm wĕ⁠ʼeţ-ha⁠má̇ʼ֤wòr ha⁠qá̇tòn֙ lĕ⁠memĕşě֣leţ ha⁠lȧ֔yĕláh wĕ⁠ʼé֖ţ ha⁠k̇wòkábiֽym׃"],[1,17,"וַ⁠יִּתֵּ֥ן אֹתָ֛⁠ם אֱלֹהִ֖ים בִּ⁠רְקִ֣יעַ הַ⁠שָּׁמָ֑יִם לְ⁠הָאִ֖יר עַל־הָ⁠אָֽרֶץ׃","wa⁠yi̇ţé֥̇n ʼòţá֛⁠m ʼèlòhi֖ym bi̇⁠rĕqi֣yʻa ha⁠şá̇̌má֑yim lĕ⁠háʼi֖yr ʻal-há⁠ʼáֽreẕ׃"],[1,18,"וְ⁠לִ⁠מְשֹׁל֙ בַּ⁠יּ֣וֹם וּ⁠בַ⁠לַּ֔יְלָה וּֽ⁠לֲ⁠הַבְדִּ֔יל בֵּ֥ין הָ⁠א֖וֹר וּ⁠בֵ֣ין הַ⁠חֹ֑שֶׁךְ וַ⁠יַּ֥רְא אֱלֹהִ֖ים כִּי־טֽוֹב׃","wĕ⁠li⁠mĕşò̌l֙ bȧ⁠ẏ֣wòm ẇ⁠ba⁠lȧ֔yĕláh ẇֽ⁠là⁠habĕdi̇֔yl bé֥̇yn há⁠ʼ֖wòr ẇ⁠bé֣yn ha⁠ẖò֑şěkĕ wa⁠yȧ֥rĕʼ ʼèlòhi֖ym ki̇y-tֽwòb׃"],[1,19,"וַֽ⁠יְהִי־עֶ֥רֶב וַֽ⁠יְהִי־בֹ֖קֶר י֥וֹם רְבִיעִֽי׃פ","waֽ⁠yĕhiy-ʻe֥reb waֽ⁠yĕhiy-bò֖qer y֥wòm rĕbiyʻiֽy׃p"],[1,20,"וַ⁠יֹּ֣אמֶר אֱלֹהִ֔ים יִשְׁרְצ֣וּ הַ⁠מַּ֔יִם שֶׁ֖רֶץ נֶ֣פֶשׁ חַיָּ֑ה וְ⁠עוֹף֙ יְעוֹפֵ֣ף עַל־הָ⁠אָ֔רֶץ עַל־פְּנֵ֖י רְקִ֥יעַ הַ⁠שָּׁמָֽיִם׃","wa⁠yò֣̇ʼmer ʼèlòhi֔ym yişĕ̌rĕẕ֣ẇ ha⁠mȧ֔yim şě֖reẕ ne֣peş̌ ẖayá֑̇h wĕ⁠ʻwòp֙ yĕʻwòpé֣p ʻal-há⁠ʼá֔reẕ ʻal-pĕ̇né֖y rĕqi֥yʻa ha⁠şá̇̌máֽyim׃"],[1,21,"וַ⁠יִּבְרָ֣א אֱלֹהִ֔ים אֶת־הַ⁠תַּנִּינִ֖ם הַ⁠גְּדֹלִ֑ים וְ⁠אֵ֣ת כָּל־נֶ֣פֶשׁ הַֽ⁠חַיָּ֣ה ׀ הָֽ⁠רֹמֶ֡שֶׂת אֲשֶׁר֩ שָׁרְצ֨וּ הַ⁠מַּ֜יִם לְ⁠מִֽינֵ⁠הֶ֗ם וְ⁠אֵ֨ת כָּל־ע֤וֹף כָּנָף֙ לְ⁠מִינֵ֔⁠הוּ וַ⁠יַּ֥רְא אֱלֹהִ֖ים כִּי־טֽוֹב׃","wa⁠yi̇bĕrá֣ʼ ʼèlòhi֔ym ʼeţ-ha⁠ţȧni̇yni֖m ha⁠gĕ̇dòli֑ym wĕ⁠ʼé֣ţ ká̇l-ne֣peş̌ hֽa⁠ẖayá֣̇h ׀ háֽ⁠ròme֡şêţ ʼàşěr֩ şá̌rĕẕ֨ẇ ha⁠mȧ֜yim lĕ⁠miֽyné⁠he֗m wĕ⁠ʼé֨ţ ká̇l-ʻ֤wòp ká̇náp֙ lĕ⁠miyné֔⁠hẇ wa⁠yȧ֥rĕʼ ʼèlòhi֖ym ki̇y-tֽwòb׃"],[1,22,"וַ⁠יְבָ֧רֶךְ אֹתָ֛⁠ם אֱלֹהִ֖ים לֵ⁠אמֹ֑ר פְּר֣וּ וּ⁠רְב֗וּ וּ⁠מִלְא֤וּ אֶת־הַ⁠מַּ֨יִם֙ בַּ⁠יַּמִּ֔ים וְ⁠הָ⁠ע֖וֹף יִ֥רֶב בָּ⁠אָֽרֶץ׃","wa⁠yĕbá֧rekĕ ʼòţá֛⁠m ʼèlòhi֖ym lé⁠ʼmò֑r pĕ̇r֣ẇ ẇ⁠rĕb֗ẇ ẇ⁠milĕʼ֤ẇ ʼeţ-ha⁠mȧ֨yim֙ bȧ⁠yȧmi̇֔ym wĕ⁠há⁠ʻ֖wòp yi֥reb bá̇⁠ʼáֽreẕ׃"],[1,23,"וַֽ⁠יְהִי־עֶ֥רֶב וַֽ⁠יְהִי־בֹ֖קֶר י֥וֹם חֲמִישִֽׁי׃פ","waֽ⁠yĕhiy-ʻe֥reb waֽ⁠yĕhiy-bò֖qer y֥wòm ẖàmiyşǐֽy׃p"],[1,24,"וַ⁠יֹּ֣אמֶר אֱלֹהִ֗ים תּוֹצֵ֨א הָ⁠אָ֜רֶץ נֶ֤פֶשׁ חַיָּה֙ לְ⁠מִינָ֔⁠הּ בְּהֵמָ֥ה וָ⁠רֶ֛מֶשׂ וְ⁠חַֽיְתוֹ־אֶ֖רֶץ לְ⁠מִינָ֑⁠הּ וַֽ⁠יְהִי־כֵֽן׃","wa⁠yò֣̇ʼmer ʼèlòhi֗ym ţ̇wòẕé֨ʼ há⁠ʼá֜reẕ ne֤peş̌ ẖayá̇h֙ lĕ⁠miyná֔⁠ḣ bĕ̇hémá֥h wá⁠re֛meş̂ wĕ⁠ẖaֽyĕţwò-ʼe֖reẕ lĕ⁠miyná֑⁠ḣ waֽ⁠yĕhiy-kéֽn׃"],[1,25,"וַ⁠יַּ֣עַשׂ אֱלֹהִים֩ אֶת־חַיַּ֨ת הָ⁠אָ֜רֶץ לְ⁠מִינָ֗⁠הּ וְ⁠אֶת־הַ⁠בְּהֵמָה֙ לְ⁠מִינָ֔⁠הּ וְ⁠אֵ֛ת כָּל־רֶ֥מֶשׂ הָֽ⁠אֲדָמָ֖ה לְ⁠מִינֵ֑⁠הוּ וַ⁠יַּ֥רְא אֱלֹהִ֖ים כִּי־טֽוֹב׃","wa⁠yȧ֣ʻaş̂ ʼèlòhiym֩ ʼeţ-ẖayȧ֨ţ há⁠ʼá֜reẕ lĕ⁠miyná֗⁠ḣ wĕ⁠ʼeţ-ha⁠bĕ̇hémáh֙ lĕ⁠miyná֔⁠ḣ wĕ⁠ʼé֛ţ ká̇l-re֥meş̂ háֽ⁠ʼàdámá֖h lĕ⁠miyné֑⁠hẇ wa⁠yȧ֥rĕʼ ʼèlòhi֖ym ki̇y-tֽwòb׃"],[1,26,"וַ⁠יֹּ֣אמֶר אֱלֹהִ֔ים נַֽעֲשֶׂ֥ה אָדָ֛ם בְּ⁠צַלְמֵ֖⁠נוּ כִּ⁠דְמוּתֵ֑⁠נוּ וְ⁠יִרְדּוּ֩ בִ⁠דְגַ֨ת הַ⁠יָּ֜ם וּ⁠בְ⁠ע֣וֹף הַ⁠שָּׁמַ֗יִם וּ⁠בַ⁠בְּהֵמָה֙ וּ⁠בְ⁠כָל־הָ⁠אָ֔רֶץ וּ⁠בְ⁠כָל־הָ⁠רֶ֖מֶשׂ הָֽ⁠רֹמֵ֥שׂ עַל־הָ⁠אָֽרֶץ׃","wa⁠yò֣̇ʼmer ʼèlòhi֔ym naֽʻàşê֥h ʼádá֛m bĕ̇⁠ẕalĕmé֖⁠nẇ ki̇⁠dĕmẇţé֑⁠nẇ wĕ⁠yirĕḋẇ֩ bi⁠dĕga֨ţ ha⁠yá̇֜m ẇ⁠bĕ⁠ʻ֣wòp ha⁠şá̇̌ma֗yim ẇ⁠ba⁠bĕ̇hémáh֙ ẇ⁠bĕ⁠kál-há⁠ʼá֔reẕ ẇ⁠bĕ⁠kál-há⁠re֖meş̂ hֽá⁠ròmé֥ş̂ ʻal-há⁠ʼáֽreẕ׃"],[1,27,"וַ⁠יִּבְרָ֨א אֱלֹהִ֤ים ׀ אֶת־הָֽ⁠אָדָם֙ בְּ⁠צַלְמ֔⁠וֹ בְּ⁠צֶ֥לֶם אֱלֹהִ֖ים בָּרָ֣א אֹת֑⁠וֹ זָכָ֥ר וּ⁠נְקֵבָ֖ה בָּרָ֥א אֹתָֽ⁠ם׃","wa⁠yi̇bĕrá֨ʼ ʼèlòhi֤ym ׀ ʼeţ-hֽá⁠ʼádám֙ bĕ̇⁠ẕalĕm֔⁠wò bĕ̇⁠ẕe֥lem ʼèlòhi֖ym bá̇rá֣ʼ ʼòţ֑⁠wò záká֥r ẇ⁠nĕqébá֖h bá̇rá֥ʼ ʼòţáֽ⁠m׃"],[1,28,"וַ⁠יְבָ֣רֶךְ אֹתָ⁠ם֮ אֱלֹהִים֒ וַ⁠יֹּ֨אמֶר לָ⁠הֶ֜ם אֱלֹהִ֗ים פְּר֥וּ וּ⁠רְב֛וּ וּ⁠מִלְא֥וּ אֶת־הָ⁠אָ֖רֶץ וְ⁠כִבְשֻׁ֑⁠הָ וּ⁠רְד֞וּ בִּ⁠דְגַ֤ת הַ⁠יָּם֙ וּ⁠בְ⁠ע֣וֹף הַ⁠שָּׁמַ֔יִם וּ⁠בְ⁠כָל־חַיָּ֖ה הָֽ⁠רֹמֶ֥שֶׂת עַל־הָ⁠אָֽרֶץ׃","wa⁠yĕbá֣rekĕ ʼòţá⁠m֮ ʼèlòhiym֒ wa⁠yò̇֨ʼmer lá⁠he֜m ʼèlòhi֗ym pĕ̇r֥ẇ ẇ⁠rĕb֛ẇ ẇ⁠milĕʼ֥ẇ ʼeţ-há⁠ʼá֖reẕ wĕ⁠kibĕşǔ֑⁠há ẇ⁠rĕd֞ẇ bi̇⁠dĕga֤ţ ha⁠yá̇m֙ ẇ⁠bĕ⁠ʻ֣wòp ha⁠şá̇̌ma֔yim ẇ⁠bĕ⁠kál-ẖayá֖̇h hֽá⁠ròme֥şêţ ʻal-há⁠ʼáֽreẕ׃"],[1,29,"וַ⁠יֹּ֣אמֶר אֱלֹהִ֗ים הִנֵּה֩ נָתַ֨תִּי לָ⁠כֶ֜ם אֶת־כָּל־עֵ֣שֶׂב ׀ זֹרֵ֣עַ זֶ֗רַע אֲשֶׁר֙ עַל־פְּנֵ֣י כָל־הָ⁠אָ֔רֶץ וְ⁠אֶת־כָּל־הָ⁠עֵ֛ץ אֲשֶׁר־בּ֥⁠וֹ פְרִי־עֵ֖ץ זֹרֵ֣עַ זָ֑רַע לָ⁠כֶ֥ם יִֽהְיֶ֖ה לְ⁠אָכְלָֽה׃","wa⁠yò֣̇ʼmer ʼèlòhi֗ym hiné̇h֩ náţa֨ţi̇y lá⁠ke֜m ʼeţ-ká̇l-ʻé֣şêb ׀ zòré֣ʻa ze֗raʻ ʼàşěr֙ ʻal-pĕ̇né֣y kál-há⁠ʼá֔reẕ wĕ⁠ʼeţ-ká̇l-há⁠ʻé֛ẕ ʼàşěr-ḃ֥⁠wò pĕriy-ʻé֖ẕ zòré֣ʻa zá֑raʻ lá⁠ke֥m yiֽhĕye֖h lĕ⁠ʼákĕláֽh׃"],[1,30,"וּֽ⁠לְ⁠כָל־חַיַּ֣ת הָ֠⁠אָרֶץ וּ⁠לְ⁠כָל־ע֨וֹף הַ⁠שָּׁמַ֜יִם וּ⁠לְ⁠כֹ֣ל ׀ רוֹמֵ֣שׂ עַל־הָ⁠אָ֗רֶץ אֲשֶׁר־בּ⁠וֹ֙ נֶ֣פֶשׁ חַיָּ֔ה אֶת־כָּל־יֶ֥רֶק עֵ֖שֶׂב לְ⁠אָכְלָ֑ה וַֽ⁠יְהִי־כֵֽן׃","ẇֽ⁠lĕ⁠kál-ẖayȧ֣ţ há֠⁠ʼáreẕ ẇ⁠lĕ⁠kál-ʻ֨wòp ha⁠şá̇̌ma֜yim ẇ⁠lĕ⁠kò֣l ׀ rwòmé֣ş̂ ʻal-há⁠ʼá֗reẕ ʼàşěr-ḃ⁠wò֙ ne֣peş̌ ẖayá̇֔h ʼeţ-ká̇l-ye֥req ʻé֖şêb lĕ⁠ʼákĕlá֑h waֽ⁠yĕhiy-kéֽn׃"],[1,31,"וַ⁠יַּ֤רְא אֱלֹהִים֙ אֶת־כָּל־אֲשֶׁ֣ר עָשָׂ֔ה וְ⁠הִנֵּה־ט֖וֹב מְאֹ֑ד וַֽ⁠יְהִי־עֶ֥רֶב וַֽ⁠יְהִי־בֹ֖קֶר י֥וֹם הַ⁠שִּׁשִּֽׁי׃פ","wa⁠yȧ֤rĕʼ ʼèlòhiym֙ ʼeţ-ká̇l-ʼàşě֣r ʻáşá̂֔h wĕ⁠hiné̇h-t֖wòb mĕʼò֑d wֽa⁠yĕhiy-ʻe֥reb wֽa⁠yĕhiy-bò֖qer y֥wòm ha⁠şi̇̌şiֽ̇̌y׃p"],[2,1,"וַ⁠יְכֻלּ֛וּ הַ⁠שָּׁמַ֥יִם וְ⁠הָ⁠אָ֖רֶץ וְ⁠כָל־צְבָאָֽ⁠ם׃","wa⁠yĕkul֛̇ẇ ha⁠şá̇̌ma֥yim wĕ⁠há⁠ʼá֖reẕ wĕ⁠kál-ẕĕbáʼáֽ⁠m׃"],[2,2,"וַ⁠יְכַ֤ל אֱלֹהִים֙ בַּ⁠יּ֣וֹם הַ⁠שְּׁבִיעִ֔י מְלַאכְתּ֖⁠וֹ אֲשֶׁ֣ר עָשָׂ֑ה וַ⁠יִּשְׁבֹּת֙ בַּ⁠יּ֣וֹם הַ⁠שְּׁבִיעִ֔י מִ⁠כָּל־מְלַאכְתּ֖⁠וֹ אֲשֶׁ֥ר עָשָֽׂה׃","wa⁠yĕka֤l ʼèlòhiym֙ bȧ⁠ẏ֣wòm ha⁠şĕ̇̌biyʻi֔y mĕlaʼkĕţ֖̇⁠wò ʼàşě֣r ʻáşá֑̂h wa⁠yi̇şĕ̌bò̇ţ֙ bȧ⁠ẏ֣wòm ha⁠şĕ̇̌biyʻi֔y mi⁠ká̇l-mĕlaʼkĕţ֖̇⁠wò ʼàşě֥r ʻáşáֽ̂h׃"],[2,3,"וַ⁠יְבָ֤רֶךְ אֱלֹהִים֙ אֶת־י֣וֹם הַ⁠שְּׁבִיעִ֔י וַ⁠יְקַדֵּ֖שׁ אֹת֑⁠וֹ כִּ֣י ב֤⁠וֹ שָׁבַת֙ מִ⁠כָּל־מְלַאכְתּ֔⁠וֹ אֲשֶׁר־בָּרָ֥א אֱלֹהִ֖ים לַ⁠עֲשֽׂוֹת׃פ","wa⁠yĕbá֤rekĕ ʼèlòhiym֙ ʼeţ-y֣wòm ha⁠şĕ̇̌biyʻi֔y wa⁠yĕqadé֖̇ş̌ ʼòţ֑⁠wò ki֣̇y b֤⁠wò şá̌baţ֙ mi⁠ká̇l-mĕlaʼkĕţ̇֔⁠wò ʼàşěr-bá̇rá֥ʼ ʼèlòhi֖ym la⁠ʻàşֽ̂wòţ׃p"],[2,4,"אֵ֣לֶּה תוֹלְד֧וֹת הַ⁠שָּׁמַ֛יִם וְ⁠הָ⁠אָ֖רֶץ בְּ⁠הִבָּֽרְאָ֑⁠ם בְּ⁠י֗וֹם עֲשׂ֛וֹת יְהוָ֥ה אֱלֹהִ֖ים אֶ֥רֶץ וְ⁠שָׁמָֽיִם׃","ʼé֣lėh ţwòlĕd֧wòţ ha⁠şá̇̌ma֛yim wĕ⁠há⁠ʼá֖reẕ bĕ̇⁠hibáֽ̇rĕʼá֑⁠m bĕ̇⁠y֗wòm ʻàş֛̂wòţ yĕhwá֥h ʼèlòhi֖ym ʼe֥reẕ wĕ⁠şá̌máֽyim׃"],[2,5,"וְ⁠כֹ֣ל ׀ שִׂ֣יחַ הַ⁠שָּׂדֶ֗ה טֶ֚רֶם יִֽהְיֶ֣ה בָ⁠אָ֔רֶץ וְ⁠כָל־עֵ֥שֶׂב הַ⁠שָּׂדֶ֖ה טֶ֣רֶם יִצְמָ֑ח כִּי֩ לֹ֨א הִמְטִ֜יר יְהוָ֤ה אֱלֹהִים֙ עַל־הָ⁠אָ֔רֶץ וְ⁠אָדָ֣ם אַ֔יִן לַֽ⁠עֲבֹ֖ד אֶת־הָֽ⁠אֲדָמָֽה׃","wĕ⁠kò֣l ׀ şî֣yẖa ha⁠şá̇̂de֗h te֚rem yiֽhĕye֣h bá⁠ʼá֔reẕ wĕ⁠kál-ʻé֥şêb ha⁠şá̇̂de֖h te֣rem yiẕĕmá֑ẖ ki̇y֩ lò֨ʼ himĕti֜yr yĕhwá֤h ʼèlòhiym֙ ʻal-há⁠ʼá֔reẕ wĕ⁠ʼádá֣m ʼa֔yin laֽ⁠ʻàbò֖d ʼeţ-háֽ⁠ʼàdámáֽh׃"],[2,6,"וְ⁠אֵ֖ד יַֽעֲלֶ֣ה מִן־הָ⁠אָ֑רֶץ וְ⁠הִשְׁקָ֖ה אֶֽת־כָּל־פְּנֵֽי־הָֽ⁠אֲדָמָֽה׃","wĕ⁠ʼé֖d yaֽʻàle֣h min-há⁠ʼá֑reẕ wĕ⁠hişĕ̌qá֖h ʼeֽţ-ká̇l-pĕ̇néֽy-háֽ⁠ʼàdámáֽh׃"],[2,7,"וַ⁠יִּיצֶר֩ יְהוָ֨ה אֱלֹהִ֜ים אֶת־הָֽ⁠אָדָ֗ם עָפָר֙ מִן־הָ֣⁠אֲדָמָ֔ה וַ⁠יִּפַּ֥ח בְּ⁠אַפָּ֖י⁠ו נִשְׁמַ֣ת חַיִּ֑ים וַֽ⁠יְהִ֥י הָֽ⁠אָדָ֖ם לְ⁠נֶ֥פֶשׁ חַיָּֽה׃","wa⁠yi̇yẕer֩ yĕhwá֨h ʼèlòhi֜ym ʼeţ-háֽ⁠ʼádá֗m ʻápár֙ min-há֣⁠ʼàdámá֔h wa⁠yi̇pȧ֥ẖ bĕ̇⁠ʼapá֖̇y⁠w nişĕ̌ma֣ţ ẖayi֑̇ym waֽ⁠yĕhi֥y háֽ⁠ʼádá֖m lĕ⁠ne֥peş̌ ẖayáֽ̇h׃"],[2,8,"וַ⁠יִּטַּ֞ע יְהוָ֧ה אֱלֹהִ֛ים גַּן־בְ⁠עֵ֖דֶן מִ⁠קֶּ֑דֶם וַ⁠יָּ֣שֶׂם שָׁ֔ם אֶת־הָֽ⁠אָדָ֖ם אֲשֶׁ֥ר יָצָֽר׃","wa⁠yi̇tȧ֞ʻ yĕhwá֧h ʼèlòhi֛ym gȧn-bĕ⁠ʻé֖den mi⁠qė֑dem wa⁠yá֣̇şêm şá̌֔m ʼeţ-háֽ⁠ʼádá֖m ʼàşě֥r yáẕáֽr׃"],[2,9,"וַ⁠יַּצְמַ֞ח יְהוָ֤ה אֱלֹהִים֙ מִן־הָ֣⁠אֲדָמָ֔ה כָּל־עֵ֛ץ נֶחְמָ֥ד לְ⁠מַרְאֶ֖ה וְ⁠ט֣וֹב לְ⁠מַאֲכָ֑ל וְ⁠עֵ֤ץ הַֽ⁠חַיִּים֙ בְּ⁠ת֣וֹךְ הַ⁠גָּ֔ן וְ⁠עֵ֕ץ הַ⁠דַּ֖עַת ט֥וֹב וָ⁠רָֽע׃","wa⁠yȧẕĕma֞ẖ yĕhwá֤h ʼèlòhiym֙ min-há֣⁠ʼàdámá֔h ká̇l-ʻé֛ẕ neẖĕmá֥d lĕ⁠marĕʼe֖h wĕ⁠t֣wòb lĕ⁠maʼàká֑l wĕ⁠ʻé֤ẕ haֽ⁠ẖayi̇ym֙ bĕ̇⁠ţ֣wòkĕ ha⁠gá̇֔n wĕ⁠ʻé֕ẕ ha⁠dȧ֖ʻaţ t֥wòb wá⁠ráֽʻ׃"],[2,10,"וְ⁠נָהָרּ֙ יֹצֵ֣א מֵ⁠עֵ֔דֶן לְ⁠הַשְׁק֖וֹת אֶת־הַ⁠גָּ֑ן וּ⁠מִ⁠שָּׁם֙ יִפָּרֵ֔ד וְ⁠הָיָ֖ה לְ⁠אַרְבָּעָ֥ה רָאשִֽׁים׃","wĕ⁠náháṙ֙ yòẕé֣ʼ mé⁠ʻé֔den lĕ⁠haşĕ̌q֖wòţ ʼeţ-ha⁠gá֑̇n ẇ⁠mi⁠şá̇̌m֙ yipá̇ré֔d wĕ⁠háyá֖h lĕ⁠ʼarĕbá̇ʻá֥h ráʼşǐֽym׃"],[2,11,"שֵׁ֥ם הָֽ⁠אֶחָ֖ד פִּישׁ֑וֹן ה֣וּא הַ⁠סֹּבֵ֗ב אֵ֚ת כָּל־אֶ֣רֶץ הַֽ⁠חֲוִילָ֔ה אֲשֶׁר־שָׁ֖ם הַ⁠זָּהָֽב׃","şé֥̌m háֽ⁠ʼeẖá֖d pi̇yş֑̌wòn h֣ẇʼ ha⁠sò̇bé֗b ʼé֚ţ ká̇l-ʼe֣reẕ haֽ⁠ẖàwiylá֔h ʼàşěr-şá֖̌m ha⁠zá̇háֽb׃"],[2,12,"וּֽ⁠זֲהַ֛ב הָ⁠אָ֥רֶץ הַ⁠הִ֖וא ט֑וֹב שָׁ֥ם הַ⁠בְּדֹ֖לַח וְ⁠אֶ֥בֶן הַ⁠שֹּֽׁהַם׃","ẇֽ⁠zàha֛b há⁠ʼá֥reẕ ha⁠hi֖wʼ t֑wòb şá֥̌m ha⁠bĕ̇dò֖laẖ wĕ⁠ʼe֥ben ha⁠şòֽ̇̌ham׃"],[2,13,"וְ⁠שֵֽׁם־הַ⁠נָּהָ֥ר הַ⁠שֵּׁנִ֖י גִּיח֑וֹן ה֣וּא הַ⁠סּוֹבֵ֔ב אֵ֖ת כָּל־אֶ֥רֶץ כּֽוּשׁ׃","wĕ⁠şéֽ̌m-ha⁠ná̇há֥r ha⁠şé̇̌ni֖y gi̇yẖ֑wòn h֣ẇʼ ha⁠ṡwòbé֔b ʼé֖ţ ká̇l-ʼe֥reẕ kֽ̇ẇş̌׃"],[2,14,"וְ⁠שֵׁ֨ם הַ⁠נָּהָ֤ר הַ⁠שְּׁלִישִׁי֙ חִדֶּ֔קֶל ה֥וּא הַֽ⁠הֹלֵ֖ךְ קִדְמַ֣ת אַשּׁ֑וּר וְ⁠הַ⁠נָּהָ֥ר הָֽ⁠רְבִיעִ֖י ה֥וּא פְרָֽת׃","wĕ⁠şé̌֨m ha⁠ná̇há֤r ha⁠şĕ̇̌liyşǐy֙ ẖidė֔qel h֥ẇʼ haֽ⁠hòlé֖kĕ qidĕma֣ţ ʼaş֑̇̌ẇr wĕ⁠ha⁠ná̇há֥r háֽ⁠rĕbiyʻi֖y h֥ẇʼ pĕráֽţ׃"],[2,15,"וַ⁠יִּקַּ֛ח יְהוָ֥ה אֱלֹהִ֖ים אֶת־הָֽ⁠אָדָ֑ם וַ⁠יַּנִּחֵ֣⁠הוּ בְ⁠גַן־עֵ֔דֶן לְ⁠עָבְדָ֖⁠הּ וּ⁠לְ⁠שָׁמְרָֽ⁠הּ׃","wa⁠yi̇qȧ֛ẖ yĕhwá֥h ʼèlòhi֖ym ʼeţ-háֽ⁠ʼádá֑m wa⁠yȧni̇ẖé֣⁠hẇ bĕ⁠gan-ʻé֔den lĕ⁠ʻábĕdá֖⁠ḣ ẇ⁠lĕ⁠şá̌mĕráֽ⁠ḣ׃"],[2,16,"וַ⁠יְצַו֙ יְהוָ֣ה אֱלֹהִ֔ים עַל־הָֽ⁠אָדָ֖ם לֵ⁠אמֹ֑ר מִ⁠כֹּ֥ל עֵֽץ־הַ⁠גָּ֖ן אָכֹ֥ל תֹּאכֵֽל׃","wa⁠yĕẕaw֙ yĕhwá֣h ʼèlòhi֔ym ʻal-háֽ⁠ʼádá֖m lé⁠ʼmò֑r mi⁠kò֥̇l ʻéֽẕ-ha⁠gá֖̇n ʼákò֥l ţò̇ʼkéֽl׃"],[2,17,"וּ⁠מֵ⁠עֵ֗ץ הַ⁠דַּ֨עַת֙ ט֣וֹב וָ⁠רָ֔ע לֹ֥א תֹאכַ֖ל מִמֶּ֑⁠נּוּ כִּ֗י בְּ⁠י֛וֹם אֲכָלְ⁠ךָ֥ מִמֶּ֖⁠נּוּ מ֥וֹת תָּמֽוּת׃","ẇ⁠mé⁠ʻé֗ẕ ha⁠dȧ֨ʻaţ֙ t֣wòb wá⁠rá֔ʻ lò֥ʼ ţòʼka֖l mimė֑⁠ṅẇ ki̇֗y bĕ̇⁠y֛wòm ʼàkálĕ⁠ká֥ mimė֖⁠ṅẇ m֥wòţ ţá̇mֽẇţ׃"],[2,18,"וַ⁠יֹּ֨אמֶר֙ יְהוָ֣ה אֱלֹהִ֔ים לֹא־ט֛וֹב הֱי֥וֹת הָֽ⁠אָדָ֖ם לְ⁠בַדּ֑⁠וֹ אֶֽעֱשֶׂהּ־לּ֥⁠וֹ עֵ֖זֶר כְּ⁠נֶגְדּֽ⁠וֹ׃","wa⁠yò̇֨ʼmer֙ yĕhwá֣h ʼèlòhi֔ym lòʼ-t֛wòb hèy֥wòţ háֽ⁠ʼádá֖m lĕ⁠baḋ֑⁠wò ʼֽeʻèşêḣ-l֥̇⁠wò ʻé֖zer kĕ̇⁠negĕḋֽ⁠wò׃"],[2,19,"וַ⁠יִּצֶר֩ יְהוָ֨ה אֱלֹהִ֜ים מִן־הָֽ⁠אֲדָמָ֗ה כָּל־חַיַּ֤ת הַ⁠שָּׂדֶה֙ וְ⁠אֵת֙ כָּל־ע֣וֹף הַ⁠שָּׁמַ֔יִם וַ⁠יָּבֵא֙ אֶל־הָ֣⁠אָדָ֔ם לִ⁠רְא֖וֹת מַה־יִּקְרָא־ל֑⁠וֹ וְ⁠כֹל֩ אֲשֶׁ֨ר יִקְרָא־ל֧⁠וֹ הָֽ⁠אָדָ֛ם נֶ֥פֶשׁ חַיָּ֖ה ה֥וּא שְׁמֽ⁠וֹ׃","wa⁠yi̇ẕer֩ yĕhwá֨h ʼèlòhi֜ym min-háֽ⁠ʼàdámá֗h ká̇l-ẖayȧ֤ţ ha⁠şá̇̂deh֙ wĕ⁠ʼéţ֙ ká̇l-ʻ֣wòp ha⁠şá̇̌ma֔yim wa⁠yá̇béʼ֙ ʼel-há֣⁠ʼádá֔m li⁠rĕʼ֖wòţ mah-yi̇qĕráʼ-l֑⁠wò wĕ⁠kòl֩ ʼàşě֨r yiqĕráʼ-l֧⁠wò hֽá⁠ʼádá֛m ne֥peş̌ ẖayá֖̇h h֥ẇʼ şĕ̌mֽ⁠wò׃"],[2,20,"וַ⁠יִּקְרָ֨א הָֽ⁠אָדָ֜ם שֵׁמ֗וֹת לְ⁠כָל־הַ⁠בְּהֵמָה֙ וּ⁠לְ⁠ע֣וֹף הַ⁠שָּׁמַ֔יִם וּ⁠לְ⁠כֹ֖ל חַיַּ֣ת הַ⁠שָּׂדֶ֑ה וּ⁠לְ⁠אָדָ֕ם לֹֽא־מָצָ֥א עֵ֖זֶר כְּ⁠נֶגְדּֽ⁠וֹ׃","wa⁠yi̇qĕrá֨ʼ háֽ⁠ʼádá֜m şé̌m֗wòţ lĕ⁠kál-ha⁠bĕ̇hémáh֙ ẇ⁠lĕ⁠ʻ֣wòp ha⁠şá̇̌ma֔yim ẇ⁠lĕ⁠kò֖l ẖayȧ֣ţ ha⁠şá̇̂de֑h ẇ⁠lĕ⁠ʼádá֕m lòֽʼ-máẕá֥ʼ ʻé֖zer kĕ̇⁠negĕḋֽ⁠wò׃"],[2,21,"וַ⁠יַּפֵּל֩ יְהוָ֨ה אֱלֹהִ֧ים ׀ תַּרְדֵּמָ֛ה עַל־הָ⁠אָדָ֖ם וַ⁠יִּישָׁ֑ן וַ⁠יִּקַּ֗ח אַחַת֙ מִ⁠צַּלְעֹתָ֔י⁠ו וַ⁠יִּסְגֹּ֥ר בָּשָׂ֖ר תַּחְתֶּֽ⁠נָּה׃","wa⁠yȧpé̇l֩ yĕhwá֨h ʼèlòhi֧ym ׀ ţȧrĕdé̇má֛h ʻal-há⁠ʼádá֖m wa⁠yi̇yşá֑̌n wa⁠yi̇qȧ֗ẖ ʼaẖaţ֙ mi⁠ẕȧlĕʻòţá֔y⁠w wa⁠yi̇sĕgò֥̇r bá̇şá֖̂r ţȧẖĕţėֽ⁠ná̇h׃"],[2,22,"וַ⁠יִּבֶן֩ יְהוָ֨ה אֱלֹהִ֧ים ׀ אֶֽת־הַ⁠צֵּלָ֛ע אֲשֶׁר־לָקַ֥ח מִן־הָֽ⁠אָדָ֖ם לְ⁠אִשָּׁ֑ה וַ⁠יְבִאֶ֖⁠הָ אֶל־הָֽ⁠אָדָֽם׃","wa⁠yi̇ben֩ yĕhwá֨h ʼèlòhi֧ym ׀ ʼeֽţ-ha⁠ẕé̇lá֛ʻ ʼàşěr-láqa֥ẖ min-háֽ⁠ʼádá֖m lĕ⁠ʼişá֑̇̌h wa⁠yĕbiʼe֖⁠há ʼel-hֽá⁠ʼádáֽm׃"],[2,23,"וַ⁠יֹּאמֶר֮ הָֽ⁠אָדָם֒ זֹ֣את הַ⁠פַּ֗עַם עֶ֚צֶם מֵֽ⁠עֲצָמַ֔⁠י וּ⁠בָשָׂ֖ר מִ⁠בְּשָׂרִ֑⁠י לְ⁠זֹאת֙ יִקָּרֵ֣א אִשָּׁ֔ה כִּ֥י מֵ⁠אִ֖ישׁ לֻֽקֳחָה־זֹּֽאת׃","wa⁠yò̇ʼmer֮ hֽá⁠ʼádám֒ zò֣ʼţ ha⁠pȧ֗ʻam ʻe֚ẕem méֽ⁠ʻàẕáma֔⁠y ẇ⁠báşá֖̂r mi⁠bĕ̇şá̂ri֑⁠y lĕ⁠zòʼţ֙ yiqá̇ré֣ʼ ʼişá̇̌֔h ki֥̇y mé⁠ʼi֖yş̌ luֽqoẖáh-zòֽ̇ʼţ׃"],[2,24,"עַל־כֵּן֙ יַֽעֲזָב־אִ֔ישׁ אֶת־אָבִ֖י⁠ו וְ⁠אֶת־אִמּ֑⁠וֹ וְ⁠דָבַ֣ק בְּ⁠אִשְׁתּ֔⁠וֹ וְ⁠הָי֖וּ לְ⁠בָשָׂ֥ר אֶחָֽד׃","ʻal-ké̇n֙ yֽaʻàzáb-ʼi֔yş̌ ʼeţ-ʼábi֖y⁠w wĕ⁠ʼeţ-ʼiṁ֑⁠wò wĕ⁠dába֣q bĕ̇⁠ʼişĕ̌ţ̇֔⁠wò wĕ⁠háy֖ẇ lĕ⁠báşá֥̂r ʼeẖáֽd׃"],[2,25,"וַ⁠יִּֽהְי֤וּ שְׁנֵי⁠הֶם֙ עֲרוּמִּ֔ים הָֽ⁠אָדָ֖ם וְ⁠אִשְׁתּ֑⁠וֹ וְ⁠לֹ֖א יִתְבֹּשָֽׁשׁוּ׃","wa⁠yiֽ̇hĕy֤ẇ şĕ̌néy⁠hem֙ ʻàrẇmi̇֔ym háֽ⁠ʼádá֖m wĕ⁠ʼişĕ̌ţ֑̇⁠wò wĕ⁠lò֖ʼ yiţĕbò̇şáֽ̌ş̌ẇ׃"],[3,1,"וְ⁠הַ⁠נָּחָשׁ֙ הָיָ֣ה עָר֔וּם מִ⁠כֹּל֙ חַיַּ֣ת הַ⁠שָּׂדֶ֔ה אֲשֶׁ֥ר עָשָׂ֖ה יְהוָ֣ה אֱלֹהִ֑ים וַ⁠יֹּ֨אמֶר֙ אֶל־הָ֣⁠אִשָּׁ֔ה אַ֚ף כִּֽי־אָמַ֣ר אֱלֹהִ֔ים לֹ֣א תֹֽאכְל֔וּ מִ⁠כֹּ֖ל עֵ֥ץ הַ⁠גָּֽן׃","wĕ⁠ha⁠ná̇ẖáş̌֙ háyá֣h ʻár֔ẇm mi⁠kò̇l֙ ẖayȧ֣ţ ha⁠şá̇̂de֔h ʼàşě֥r ʻáşá֖̂h yĕhwá֣h ʼèlòhi֑ym wa⁠yò̇֨ʼmer֙ ʼel-há֣⁠ʼişá̇̌֔h ʼa֚p kiֽ̇y-ʼáma֣r ʼèlòhi֔ym lò֣ʼ ţòֽʼkĕl֔ẇ mi⁠kò֖̇l ʻé֥ẕ ha⁠gáֽ̇n׃"],[3,2,"וַ⁠תֹּ֥אמֶר הָֽ⁠אִשָּׁ֖ה אֶל־הַ⁠נָּחָ֑שׁ מִ⁠פְּרִ֥י עֵֽץ־הַ⁠גָּ֖ן נֹאכֵֽל׃","wa⁠ţò֥̇ʼmer háֽ⁠ʼişá֖̇̌h ʼel-ha⁠ná̇ẖá֑ş̌ mi⁠pĕ̇ri֥y ʻéֽẕ-ha⁠gá֖̇n nòʼkéֽl׃"],[3,3,"וּ⁠מִ⁠פְּרִ֣י הָ⁠עֵץ֮ אֲשֶׁ֣ר בְּ⁠תוֹךְ־הַ⁠גָּן֒ אָמַ֣ר אֱלֹהִ֗ים לֹ֤א תֹֽאכְלוּ֙ מִמֶּ֔⁠נּוּ וְ⁠לֹ֥א תִגְּע֖וּ בּ֑⁠וֹ פֶּן־תְּמֻתֽוּ⁠ן׃","ẇ⁠mi⁠pĕ̇ri֣y há⁠ʻéẕ֮ ʼàşě֣r bĕ̇⁠ţwòkĕ-ha⁠gá̇n֒ ʼáma֣r ʼèlòhi֗ym lò֤ʼ ţòֽʼkĕlẇ֙ mimė֔⁠ṅẇ wĕ⁠lò֥ʼ ţigĕ̇ʻ֖ẇ ḃ֑⁠wò pėn-ţĕ̇muţֽẇ⁠n׃"],[3,4,"וַ⁠יֹּ֥אמֶר הַ⁠נָּחָ֖שׁ אֶל־הָֽ⁠אִשָּׁ֑ה לֹֽא־מ֖וֹת תְּמֻתֽוּ⁠ן׃","wa⁠yò֥̇ʼmer ha⁠ná̇ẖá֖ş̌ ʼel-háֽ⁠ʼişá֑̇̌h lòֽʼ-m֖wòţ ţĕ̇muţֽẇ⁠n׃"],[3,5,"כִּ֚י יֹדֵ֣עַ אֱלֹהִ֔ים כִּ֗י בְּ⁠יוֹם֙ אֲכָלְ⁠כֶ֣ם מִמֶּ֔⁠נּוּ וְ⁠נִפְקְח֖וּ עֵֽינֵי⁠כֶ֑ם וִ⁠הְיִיתֶם֙ כֵּֽ⁠אלֹהִ֔ים יֹדְעֵ֖י ט֥וֹב וָ⁠רָֽע׃","ki֚̇y yòdé֣ʻa ʼèlòhi֔ym ki̇֗y bĕ̇⁠ywòm֙ ʼàkálĕ⁠ke֣m mimė֔⁠ṅẇ wĕ⁠nipĕqĕẖ֖ẇ ʻéֽynéy⁠ke֑m wi⁠hĕyiyţem֙ kéֽ̇⁠ʼlòhi֔ym yòdĕʻé֖y t֥wòb wá⁠ráֽʻ׃"],[3,6,"וַ⁠תֵּ֣רֶא הָֽ⁠אִשָּׁ֡ה כִּ֣י טוֹב֩ הָ⁠עֵ֨ץ לְ⁠מַאֲכָ֜ל וְ⁠כִ֧י תַֽאֲוָה־ה֣וּא לָ⁠עֵינַ֗יִם וְ⁠נֶחְמָ֤ד הָ⁠עֵץ֙ לְ⁠הַשְׂכִּ֔יל וַ⁠תִּקַּ֥ח מִ⁠פִּרְי֖⁠וֹ וַ⁠תֹּאכַ֑ל וַ⁠תִּתֵּ֧ן גַּם־לְ⁠אִישָׁ֛⁠הּ עִמָּ֖⁠הּ וַ⁠יֹּאכַֽל׃","wa⁠ţé֣̇reʼ háֽ⁠ʼişá̇̌֡h ki֣̇y twòb֩ há⁠ʻé֨ẕ lĕ⁠maʼàká֜l wĕ⁠ki֧y ţaֽʼàwáh-h֣ẇʼ lá⁠ʻéyna֗yim wĕ⁠neẖĕmá֤d há⁠ʻéẕ֙ lĕ⁠haşĕ̂ki̇֔yl wa⁠ţi̇qȧ֥ẖ mi⁠pi̇rĕy֖⁠wò wa⁠ţò̇ʼka֑l wa⁠ţi̇ţé֧̇n gȧm-lĕ⁠ʼiyşá֛̌⁠ḣ ʻimá֖̇⁠ḣ wa⁠yò̇ʼkaֽl׃"],[3,7,"וַ⁠תִּפָּקַ֨חְנָה֙ עֵינֵ֣י שְׁנֵי⁠הֶ֔ם וַ⁠יֵּ֣דְע֔וּ כִּ֥י עֵֽירֻמִּ֖ם הֵ֑ם וַֽ⁠יִּתְפְּרוּ֙ עֲלֵ֣ה תְאֵנָ֔ה וַ⁠יַּעֲשׂ֥וּ לָ⁠הֶ֖ם חֲגֹרֹֽת׃","wa⁠ţi̇pá̇qa֨ẖĕnáh֙ ʻéyné֣y şĕ̌néy⁠he֔m wa⁠yé֣̇dĕʻ֔ẇ ki֥̇y ʻéֽyrumi֖̇m hé֑m waֽ⁠yi̇ţĕpĕ̇rẇ֙ ʻàlé֣h ţĕʼéná֔h wa⁠yȧʻàş֥̂ẇ lá⁠he֖m ẖàgòròֽţ׃"],[3,8,"וַֽ⁠יִּשְׁמְע֞וּ אֶת־ק֨וֹל יְהוָ֧ה אֱלֹהִ֛ים מִתְהַלֵּ֥ךְ בַּ⁠גָּ֖ן לְ⁠ר֣וּחַ הַ⁠יּ֑וֹם וַ⁠יִּתְחַבֵּ֨א הָֽ⁠אָדָ֜ם וְ⁠אִשְׁתּ֗⁠וֹ מִ⁠פְּנֵי֙ יְהוָ֣ה אֱלֹהִ֔ים בְּ⁠ת֖וֹךְ עֵ֥ץ הַ⁠גָּֽן׃","waֽ⁠yi̇şĕ̌mĕʻ֞ẇ ʼeţ-q֨wòl yĕhwá֧h ʼèlòhi֛ym miţĕhalé֥̇kĕ bȧ⁠gá֖̇n lĕ⁠r֣ẇẖa ha⁠ẏ֑wòm wa⁠yi̇ţĕẖabé̇֨ʼ háֽ⁠ʼádá֜m wĕ⁠ʼişĕ̌ţ̇֗⁠wò mi⁠pĕ̇néy֙ yĕhwá֣h ʼèlòhi֔ym bĕ̇⁠ţ֖wòkĕ ʻé֥ẕ ha⁠gáֽ̇n׃"],[3,9,"וַ⁠יִּקְרָ֛א יְהוָ֥ה אֱלֹהִ֖ים אֶל־הָֽ⁠אָדָ֑ם וַ⁠יֹּ֥אמֶר ל֖⁠וֹ אַיֶּֽ⁠כָּה׃","wa⁠yi̇qĕrá֛ʼ yĕhwá֥h ʼèlòhi֖ym ʼel-háֽ⁠ʼádá֑m wa⁠yò֥̇ʼmer l֖⁠wò ʼayėֽ⁠ká̇h׃"],[3,10,"וַ⁠יֹּ֕אמֶר אֶת־קֹלְ⁠ךָ֥ שָׁמַ֖עְתִּי בַּ⁠גָּ֑ן וָ⁠אִירָ֛א כִּֽי־עֵירֹ֥ם אָנֹ֖כִי וָ⁠אֵחָבֵֽא׃","wa⁠yò̇֕ʼmer ʼeţ-qòlĕ⁠ká֥ şá̌ma֖ʻĕţi̇y bȧ⁠gá֑̇n wá⁠ʼiyrá֛ʼ kiֽ̇y-ʻéyrò֥m ʼánò֖kiy wá⁠ʼéẖábéֽʼ׃"],[3,11,"וַ⁠יֹּ֕אמֶר מִ֚י הִגִּ֣יד לְ⁠ךָ֔ כִּ֥י עֵירֹ֖ם אָ֑תָּה הֲ⁠מִן־הָ⁠עֵ֗ץ אֲשֶׁ֧ר צִוִּיתִ֛י⁠ךָ לְ⁠בִלְתִּ֥י אֲכָל־מִמֶּ֖⁠נּוּ אָכָֽלְתָּ׃","wa⁠yò̇֕ʼmer mi֚y higi֣̇yd lĕ⁠ká֔ ki֥̇y ʻéyrò֖m ʼá֑ţá̇h hà⁠min-há⁠ʻé֗ẕ ʼàşě֧r ẕiwi̇yţi֛y⁠ká lĕ⁠bilĕţi֥̇y ʼàkál-mimė֖⁠ṅẇ ʼákáֽlĕţá̇׃"],[3,12,"וַ⁠יֹּ֖אמֶר הָֽ⁠אָדָ֑ם הָֽ⁠אִשָּׁה֙ אֲשֶׁ֣ר נָתַ֣תָּה עִמָּדִ֔⁠י הִ֛וא נָֽתְנָה־לִּ֥⁠י מִן־הָ⁠עֵ֖ץ וָ⁠אֹכֵֽל׃","wa⁠yò֖̇ʼmer háֽ⁠ʼádá֑m háֽ⁠ʼişá̇̌h֙ ʼàşě֣r náţa֣ţá̇h ʻimá̇di֔⁠y hi֛wʼ náֽţĕnáh-li֥̇⁠y min-há⁠ʻé֖ẕ wá⁠ʼòkéֽl׃"],[3,13,"וַ⁠יֹּ֨אמֶר יְהוָ֧ה אֱלֹהִ֛ים לָ⁠אִשָּׁ֖ה מַה־זֹּ֣את עָשִׂ֑ית וַ⁠תֹּ֨אמֶר֙ הָֽ⁠אִשָּׁ֔ה הַ⁠נָּחָ֥שׁ הִשִּׁיאַ֖⁠נִי וָ⁠אֹכֵֽל׃","wa⁠yò̇֨ʼmer yĕhwá֧h ʼèlòhi֛ym lá⁠ʼişá֖̇̌h mah-zò֣̇ʼţ ʻáşî֑yţ wa⁠ţò̇֨ʼmer֙ háֽ⁠ʼişá̇̌֔h ha⁠ná̇ẖá֥ş̌ hişi̇̌yʼa֖⁠niy wá⁠ʼòkéֽl׃"],[3,14,"וַ⁠יֹּאמֶר֩ יְהֹוָ֨ה אֱלֹהִ֥ים ׀ אֶֽל־הַ⁠נָּחָשׁ֮ כִּ֣י עָשִׂ֣יתָ זֹּאת֒ אָר֤וּר אַתָּה֙ מִ⁠כָּל־הַ⁠בְּהֵמָ֔ה וּ⁠מִ⁠כֹּ֖ל חַיַּ֣ת הַ⁠שָּׂדֶ֑ה עַל־גְּחֹנְ⁠ךָ֣ תֵלֵ֔ךְ וְ⁠עָפָ֥ר תֹּאכַ֖ל כָּל־יְמֵ֥י חַיֶּֽי⁠ךָ׃","wa⁠yò̇ʼmer֩ yĕhòwá֨h ʼèlòhi֥ym ׀ ʼeֽl-ha⁠ná̇ẖáş֮̌ ki֣̇y ʻáşî֣yţá zò̇ʼţ֒ ʼár֤ẇr ʼaţá̇h֙ mi⁠ká̇l-ha⁠bĕ̇hémá֔h ẇ⁠mi⁠kò֖̇l ẖayȧ֣ţ ha⁠şá̇̂de֑h ʻal-gĕ̇ẖònĕ⁠ká֣ ţélé֔kĕ wĕ⁠ʻápá֥r ţò̇ʼka֖l ká̇l-yĕmé֥y ẖayėֽy⁠ká׃"],[3,15,"וְ⁠אֵיבָ֣ה ׀ אָשִׁ֗ית בֵּֽינְ⁠ךָ֙ וּ⁠בֵ֣ין הָֽ⁠אִשָּׁ֔ה וּ⁠בֵ֥ין זַרְעֲ⁠ךָ֖ וּ⁠בֵ֣ין זַרְעָ֑⁠הּ ה֚וּא יְשׁוּפְ⁠ךָ֣ רֹ֔אשׁ וְ⁠אַתָּ֖ה תְּשׁוּפֶ֥⁠נּוּ עָקֵֽב׃ס","wĕ⁠ʼéybá֣h ׀ ʼáşǐ֗yţ béֽ̇ynĕ⁠ká֙ ẇ⁠bé֣yn háֽ⁠ʼişá̇̌֔h ẇ⁠bé֥yn zarĕʻà⁠ká֖ ẇ⁠bé֣yn zarĕʻá֑⁠ḣ h֚ẇʼ yĕş̌ẇpĕ⁠ká֣ rò֔ʼş̌ wĕ⁠ʼaţá֖̇h ţĕ̇ş̌ẇpe֥⁠ṅẇ ʻáqéֽb׃s"],[3,16,"אֶֽל־הָ⁠אִשָּׁ֣ה אָמַ֗ר הַרְבָּ֤ה אַרְבֶּה֙ עִצְּבוֹנֵ֣⁠ךְ וְ⁠הֵֽרֹנֵ֔⁠ךְ בְּ⁠עֶ֖צֶב תֵּֽלְדִ֣י בָנִ֑ים וְ⁠אֶל־אִישֵׁ⁠ךְ֙ תְּשׁ֣וּקָתֵ֔⁠ךְ וְ⁠ה֖וּא יִמְשָׁל־בָּֽ⁠ךְ׃ס","ʼeֽl-há⁠ʼişá֣̇̌h ʼáma֗r harĕbá֤̇h ʼarĕbėh֙ ʻiẕĕ̇bwòné֣⁠kĕ wĕ⁠héֽròné֔⁠kĕ bĕ̇⁠ʻe֖ẕeb ţéֽ̇lĕdi֣y báni֑ym wĕ⁠ʼel-ʼiyşé̌⁠kĕ֙ ţĕ̇ş֣̌ẇqáţé֔⁠kĕ wĕ⁠h֖ẇʼ yimĕşá̌l-báֽ̇⁠kĕ׃s"],[3,17,"וּ⁠לְ⁠אָדָ֣ם אָמַ֗ר כִּֽי־שָׁמַעְתָּ֮ לְ⁠ק֣וֹל אִשְׁתֶּ⁠ךָ֒ וַ⁠תֹּ֨אכַל֙ מִן־הָ⁠עֵ֔ץ אֲשֶׁ֤ר צִוִּיתִ֨י⁠ךָ֙ לֵ⁠אמֹ֔ר לֹ֥א תֹאכַ֖ל מִמֶּ֑⁠נּוּ אֲרוּרָ֤ה הָֽ⁠אֲדָמָה֙ בַּֽ⁠עֲבוּרֶ֔⁠ךָ בְּ⁠עִצָּבוֹן֙ תֹּֽאכֲלֶ֔⁠נָּה כֹּ֖ל יְמֵ֥י חַיֶּֽי⁠ךָ׃","ẇ⁠lĕ⁠ʼádá֣m ʼáma֗r kiֽ̇y-şá̌maʻĕţá֮̇ lĕ⁠q֣wòl ʼişĕ̌ţė⁠ká֒ wa⁠ţò̇֨ʼkal֙ min-há⁠ʻé֔ẕ ʼàşě֤r ẕiwi̇yţi֨y⁠ká֙ lé⁠ʼmò֔r lò֥ʼ ţòʼka֖l mimė֑⁠ṅẇ ʼàrẇrá֤h háֽ⁠ʼàdámáh֙ bȧֽ⁠ʻàbẇre֔⁠ká bĕ̇⁠ʻiẕá̇bwòn֙ ţòֽ̇ʼkàle֔⁠ná̇h kò֖̇l yĕmé֥y ẖayėֽy⁠ká׃"],[3,18,"וְ⁠ק֥וֹץ וְ⁠דַרְדַּ֖ר תַּצְמִ֣יחַֽ לָ֑⁠ךְ וְ⁠אָכַלְתָּ֖ אֶת־עֵ֥שֶׂב הַ⁠שָּׂדֶֽה׃","wĕ⁠q֥wòẕ wĕ⁠darĕdȧ֖r ţȧẕĕmi֣yẖaֽ lá֑⁠kĕ wĕ⁠ʼákalĕţá֖̇ ʼeţ-ʻé֥şêb ha⁠şá̇̂deֽh׃"],[3,19,"בְּ⁠זֵעַ֤ת אַפֶּ֨י⁠ךָ֙ תֹּ֣אכַל לֶ֔חֶם עַ֤ד שֽׁוּבְ⁠ךָ֙ אֶל־הָ֣⁠אֲדָמָ֔ה כִּ֥י מִמֶּ֖⁠נָּה לֻקָּ֑חְתָּ כִּֽי־עָפָ֣ר אַ֔תָּה וְ⁠אֶל־עָפָ֖ר תָּשֽׁוּב׃","bĕ̇⁠zéʻa֤ţ ʼapė֨y⁠ká֙ ţò֣̇ʼkal le֔ẖem ʻa֤d şֽ̌ẇbĕ⁠ká֙ ʼel-há֣⁠ʼàdámá֔h ki֥̇y mimė֖⁠ná̇h luqá֑̇ẖĕţá̇ kiֽ̇y-ʻápá֣r ʼa֔ţá̇h wĕ⁠ʼel-ʻápá֖r ţá̇şֽ̌ẇb׃"],[3,20,"וַ⁠יִּקְרָ֧א הָֽ⁠אָדָ֛ם שֵׁ֥ם אִשְׁתּ֖⁠וֹ חַוָּ֑ה כִּ֛י הִ֥וא הָֽיְתָ֖ה אֵ֥ם כָּל־חָֽי׃","wa⁠yi̇qĕrá֧ʼ háֽ⁠ʼádá֛m şé֥̌m ʼişĕ̌ţ֖̇⁠wò ẖawá֑̇h ki֛̇y hi֥wʼ háֽyĕţá֖h ʼé֥m ká̇l-ẖáֽy׃"],[3,21,"וַ⁠יַּעַשׂ֩ יְהוָ֨ה אֱלֹהִ֜ים לְ⁠אָדָ֧ם וּ⁠לְ⁠אִשְׁתּ֛⁠וֹ כָּתְנ֥וֹת ע֖וֹר וַ⁠יַּלְבִּשֵֽׁ⁠ם׃פ","wa⁠yȧʻaş̂֩ yĕhwá֨h ʼèlòhi֜ym lĕ⁠ʼádá֧m ẇ⁠lĕ⁠ʼişĕ̌ţ֛̇⁠wò ká̇ţĕn֥wòţ ʻ֖wòr wa⁠yȧlĕbi̇şéֽ̌⁠m׃p"],[3,22,"וַ⁠יֹּ֣אמֶר ׀ יְהוָ֣ה אֱלֹהִ֗ים הֵ֤ן הָֽ⁠אָדָם֙ הָיָה֙ כְּ⁠אַחַ֣ד מִמֶּ֔⁠נּוּ לָ⁠דַ֖עַת ט֣וֹב וָ⁠רָ֑ע וְ⁠עַתָּ֣ה ׀ פֶּן־יִשְׁלַ֣ח יָד֗⁠וֹ וְ⁠לָקַח֙ גַּ֚ם מֵ⁠עֵ֣ץ הַֽ⁠חַיִּ֔ים וְ⁠אָכַ֖ל וָ⁠חַ֥י לְ⁠עֹלָֽם׃","wa⁠yò֣̇ʼmer ׀ yĕhwá֣h ʼèlòhi֗ym hé֤n háֽ⁠ʼádám֙ háyáh֙ kĕ̇⁠ʼaẖa֣d mimė֔⁠ṅẇ lá⁠da֖ʻaţ t֣wòb wá⁠rá֑ʻ wĕ⁠ʻaţá֣̇h ׀ pėn-yişĕ̌la֣ẖ yád֗⁠wò wĕ⁠láqaẖ֙ gȧ֚m mé⁠ʻé֣ẕ haֽ⁠ẖayi̇֔ym wĕ⁠ʼáka֖l wá⁠ẖa֥y lĕ⁠ʻòláֽm׃"],[3,23,"וַֽ⁠יְשַׁלְּחֵ֛⁠הוּ יְהוָ֥ה אֱלֹהִ֖ים מִ⁠גַּן־עֵ֑דֶן לַֽ⁠עֲבֹד֙ אֶת־הָ֣⁠אֲדָמָ֔ה אֲשֶׁ֥ר לֻקַּ֖ח מִ⁠שָּֽׁם׃","waֽ⁠yĕşǎlĕ̇ẖé֛⁠hẇ yĕhwá֥h ʼèlòhi֖ym mi⁠gȧn-ʻé֑den laֽ⁠ʻàbòd֙ ʼeţ-há֣⁠ʼàdámá֔h ʼàşě֥r luqȧ֖ẖ mi⁠şáֽ̇̌m׃"],[3,24,"וַ⁠יְגָ֖רֶשׁ אֶת־הָֽ⁠אָדָ֑ם וַ⁠יַּשְׁכֵּן֩ מִ⁠קֶּ֨דֶם לְ⁠גַן־עֵ֜דֶן אֶת־הַ⁠כְּרֻבִ֗ים וְ⁠אֵ֨ת לַ֤הַט הַ⁠חֶ֨רֶב֙ הַ⁠מִּתְהַפֶּ֔כֶת לִ⁠שְׁמֹ֕ר אֶת־דֶּ֖רֶךְ עֵ֥ץ הַֽ⁠חַיִּֽים׃ס","wa⁠yĕgá֖reş̌ ʼeţ-háֽ⁠ʼádá֑m wa⁠yȧşĕ̌ké̇n֩ mi⁠qė֨dem lĕ⁠gan-ʻé֜den ʼeţ-ha⁠kĕ̇rubi֗ym wĕ⁠ʼé֨ţ la֤hat ha⁠ẖe֨reb֙ ha⁠mi̇ţĕhapė֔keţ li⁠şĕ̌mò֕r ʼeţ-dė֖rekĕ ʻé֥ẕ haֽ⁠ẖayiֽ̇ym׃s"],[4,1,"וְ⁠הָ֣⁠אָדָ֔ם יָדַ֖ע אֶת־חַוָּ֣ה אִשְׁתּ֑⁠וֹ וַ⁠תַּ֨הַר֙ וַ⁠תֵּ֣לֶד אֶת־קַ֔יִן וַ⁠תֹּ֕אמֶר קָנִ֥יתִי אִ֖ישׁ אֶת־יְהוָֽה׃","wĕ⁠há֣⁠ʼádá֔m yáda֖ʻ ʼeţ-ẖawá֣̇h ʼişĕ̌ţ֑̇⁠wò wa⁠ţȧ֨har֙ wa⁠ţé֣̇led ʼeţ-qa֔yin wa⁠ţò̇֕ʼmer qáni֥yţiy ʼi֖yş̌ ʼeţ-yĕhwáֽh׃"],[4,2,"וַ⁠תֹּ֣סֶף לָ⁠לֶ֔דֶת אֶת־אָחִ֖י⁠ו אֶת־הָ֑בֶל וַֽ⁠יְהִי־הֶ֨בֶל֙ רֹ֣עֵה צֹ֔אן וְ⁠קַ֕יִן הָיָ֖ה עֹבֵ֥ד אֲדָמָֽה׃","wa⁠ţò֣̇sep lá⁠le֔deţ ʼeţ-ʼáẖi֖y⁠w ʼeţ-há֑bel waֽ⁠yĕhiy-he֨bel֙ rò֣ʻéh ẕò֔ʼn wĕ⁠qa֕yin háyá֖h ʻòbé֥d ʼàdámáֽh׃"],[4,3,"וַֽ⁠יְהִ֖י מִ⁠קֵּ֣ץ יָמִ֑ים וַ⁠יָּבֵ֨א קַ֜יִן מִ⁠פְּרִ֧י הָֽ⁠אֲדָמָ֛ה מִנְחָ֖ה לַֽ⁠יהוָֽה׃","wֽa⁠yĕhi֖y mi⁠qé֣̇ẕ yámi֑ym wa⁠yá̇bé֨ʼ qa֜yin mi⁠pĕ̇ri֧y hֽá⁠ʼàdámá֛h minĕẖá֖h laֽ⁠yhwáֽh׃"],[4,4,"וְ⁠הֶ֨בֶל הֵבִ֥יא גַם־ה֛וּא מִ⁠בְּכֹר֥וֹת צֹאנ֖⁠וֹ וּ⁠מֵֽ⁠חֶלְבֵ⁠הֶ֑ן וַ⁠יִּ֣שַׁע יְהוָ֔ה אֶל־הֶ֖בֶל וְ⁠אֶל־מִנְחָתֽ⁠וֹ׃","wĕ⁠he֨bel hébi֥yʼ gam-h֛ẇʼ mi⁠bĕ̇kòr֥wòţ ẕòʼn֖⁠wò ẇ⁠méֽ⁠ẖelĕbé⁠he֑n wa⁠yi֣̇şǎʻ yĕhwá֔h ʼel-he֖bel wĕ⁠ʼel-minĕẖáţֽ⁠wò׃"],[4,5,"וְ⁠אֶל־קַ֥יִן וְ⁠אֶל־מִנְחָת֖⁠וֹ לֹ֣א שָׁעָ֑ה וַ⁠יִּ֤חַר לְ⁠קַ֨יִן֙ מְאֹ֔ד וַֽ⁠יִּפְּל֖וּ פָּנָֽי⁠ו׃","wĕ⁠ʼel-qa֥yin wĕ⁠ʼel-minĕẖáţ֖⁠wò lò֣ʼ şá̌ʻá֑h wa⁠yi֤̇ẖar lĕ⁠qa֨yin֙ mĕʼò֔d waֽ⁠yi̇pĕ̇l֖ẇ pá̇náֽy⁠w׃"],[4,6,"וַ⁠יֹּ֥אמֶר יְהוָ֖ה אֶל־קָ֑יִן לָ֚⁠מָּה חָ֣רָה לָ֔⁠ךְ וְ⁠לָ֖⁠מָּה נָפְל֥וּ פָנֶֽי⁠ךָ׃","wa⁠yò֥̇ʼmer yĕhwá֖h ʼel-qá֑yin lá֚⁠má̇h ẖá֣ráh lá֔⁠kĕ wĕ⁠lá֖⁠má̇h nápĕl֥ẇ páneֽy⁠ká׃"],[4,7,"הֲ⁠ל֤וֹא אִם־תֵּיטִיב֙ שְׂאֵ֔ת וְ⁠אִם֙ לֹ֣א תֵיטִ֔יב לַ⁠פֶּ֖תַח חַטָּ֣את רֹבֵ֑ץ וְ⁠אֵלֶ֨י⁠ךָ֙ תְּשׁ֣וּקָת֔⁠וֹ וְ⁠אַתָּ֖ה תִּמְשָׁל־בּֽ⁠וֹ׃","hà⁠l֤wòʼ ʼim-ţé̇ytiyb֙ şĕ̂ʼé֔ţ wĕ⁠ʼim֙ lò֣ʼ ţéyti֔yb la⁠pė֖ţaẖ ẖatá֣̇ʼţ ròbé֑ẕ wĕ⁠ʼéle֨y⁠ká֙ ţĕ̇ş֣̌ẇqáţ֔⁠wò wĕ⁠ʼaţá֖̇h ţi̇mĕşá̌l-ḃֽ⁠wò׃"],[4,8,"וַ⁠יֹּ֥אמֶר קַ֖יִן אֶל־הֶ֣בֶל אָחִ֑י⁠ו וַֽ⁠יְהִי֙ בִּ⁠הְיוֹתָ֣⁠ם בַּ⁠שָּׂדֶ֔ה וַ⁠יָּ֥קָם קַ֛יִן אֶל־הֶ֥בֶל אָחִ֖י⁠ו וַ⁠יַּהַרְגֵֽ⁠הוּ׃","wa⁠yò֥̇ʼmer qa֖yin ʼel-he֣bel ʼáẖi֑y⁠w wֽa⁠yĕhiy֙ bi̇⁠hĕywòţá֣⁠m bȧ⁠şá̇̂de֔h wa⁠yá֥̇qám qa֛yin ʼel-he֥bel ʼáẖi֖y⁠w wa⁠yȧharĕgéֽ⁠hẇ׃"],[4,9,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־קַ֔יִן אֵ֖י הֶ֣בֶל אָחִ֑י⁠ךָ וַ⁠יֹּ֨אמֶר֙ לֹ֣א יָדַ֔עְתִּי הֲ⁠שֹׁמֵ֥ר אָחִ֖⁠י אָנֹֽכִי׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-qa֔yin ʼé֖y he֣bel ʼáẖi֑y⁠ká wa⁠yò̇֨ʼmer֙ lò֣ʼ yáda֔ʻĕţi̇y hà⁠şò̌mé֥r ʼáẖi֖⁠y ʼánòֽkiy׃"],[4,10,"וַ⁠יֹּ֖אמֶר מֶ֣ה עָשִׂ֑יתָ ק֚וֹל דְּמֵ֣י אָחִ֔י⁠ךָ צֹעֲקִ֥ים אֵלַ֖⁠י מִן־הָֽ⁠אֲדָמָֽה׃","wa⁠yò֖̇ʼmer me֣h ʻáşî֑yţá q֚wòl dĕ̇mé֣y ʼáẖi֔y⁠ká ẕòʻàqi֥ym ʼéla֖⁠y min-háֽ⁠ʼàdámáֽh׃"],[4,11,"וְ⁠עַתָּ֖ה אָר֣וּר אָ֑תָּה מִן־הָֽ⁠אֲדָמָה֙ אֲשֶׁ֣ר פָּצְתָ֣ה אֶת־פִּ֔י⁠הָ לָ⁠קַ֛חַת אֶת־דְּמֵ֥י אָחִ֖י⁠ךָ מִ⁠יָּדֶֽ⁠ךָ׃","wĕ⁠ʻaţá֖̇h ʼár֣ẇr ʼá֑ţá̇h min-háֽ⁠ʼàdámáh֙ ʼàşě֣r pá̇ẕĕţá֣h ʼeţ-pi̇֔y⁠há lá⁠qa֛ẖaţ ʼeţ-dĕ̇mé֥y ʼáẖi֖y⁠ká mi⁠yá̇deֽ⁠ká׃"],[4,12,"כִּ֤י תַֽעֲבֹד֙ אֶת־הָ֣⁠אֲדָמָ֔ה לֹֽא־תֹסֵ֥ף תֵּת־כֹּחָ֖⁠הּ לָ֑⁠ךְ נָ֥ע וָ⁠נָ֖ד תִּֽהְיֶ֥ה בָ⁠אָֽרֶץ׃","ki֤̇y ţaֽʻàbòd֙ ʼeţ-há֣⁠ʼàdámá֔h lòֽʼ-ţòsé֥p ţé̇ţ-kò̇ẖá֖⁠ḣ lá֑⁠kĕ ná֥ʻ wá⁠ná֖d ţiֽ̇hĕye֥h bá⁠ʼáֽreẕ׃"],[4,13,"וַ⁠יֹּ֥אמֶר קַ֖יִן אֶל־יְהוָ֑ה גָּד֥וֹל עֲוֺנִ֖⁠י מִ⁠נְּשֹֽׂא׃","wa⁠yò֥̇ʼmer qa֖yin ʼel-yĕhwá֑h gá̇d֥wòl ʻàwֺni֖⁠y mi⁠nĕ̇şòֽ̂ʼ׃"],[4,14,"הֵן֩ גֵּרַ֨שְׁתָּ אֹתִ֜⁠י הַ⁠יּ֗וֹם מֵ⁠עַל֙ פְּנֵ֣י הָֽ⁠אֲדָמָ֔ה וּ⁠מִ⁠פָּנֶ֖י⁠ךָ אֶסָּתֵ֑ר וְ⁠הָיִ֜יתִי נָ֤ע וָ⁠נָד֙ בָּ⁠אָ֔רֶץ וְ⁠הָיָ֥ה כָל־מֹצְאִ֖⁠י יַֽהַרְגֵֽ⁠נִי׃","hén֩ gé̇ra֨şĕ̌ţá̇ ʼòţi֜⁠y ha⁠ẏ֗wòm mé⁠ʻal֙ pĕ̇né֣y hֽá⁠ʼàdámá֔h ẇ⁠mi⁠pá̇ne֖y⁠ká ʼesá̇ţé֑r wĕ⁠háyi֜yţiy ná֤ʻ wá⁠nád֙ bá̇⁠ʼá֔reẕ wĕ⁠háyá֥h kál-mòẕĕʼi֖⁠y yֽaharĕgéֽ⁠niy׃"],[4,15,"וַ⁠יֹּ֧אמֶר ל֣⁠וֹ יְהוָ֗ה לָ⁠כֵן֙ כָּל־הֹרֵ֣ג קַ֔יִן שִׁבְעָתַ֖יִם יֻקָּ֑ם וַ⁠יָּ֨שֶׂם יְהוָ֤ה לְ⁠קַ֨יִן֙ א֔וֹת לְ⁠בִלְתִּ֥י הַכּוֹת־אֹת֖⁠וֹ כָּל־מֹצְאֽ⁠וֹ׃","wa⁠yò֧̇ʼmer l֣⁠wò yĕhwá֗h lá⁠kén֙ ká̇l-hòré֣g qa֔yin şǐbĕʻáţa֖yim yuqá֑̇m wa⁠yá̇֨şêm yĕhwá֤h lĕ⁠qa֨yin֙ ʼ֔wòţ lĕ⁠bilĕţi֥̇y hak̇wòţ-ʼòţ֖⁠wò ká̇l-mòẕĕʼֽ⁠wò׃"],[4,16,"וַ⁠יֵּ֥צֵא קַ֖יִן מִ⁠לִּ⁠פְנֵ֣י יְהוָ֑ה וַ⁠יֵּ֥שֶׁב בְּ⁠אֶֽרֶץ־נ֖וֹד קִדְמַת־עֵֽדֶן׃","wa⁠yé֥̇ẕéʼ qa֖yin mi⁠li̇⁠pĕné֣y yĕhwá֑h wa⁠yé֥̇şěb bĕ̇⁠ʼeֽreẕ-n֖wòd qidĕmaţ-ʻéֽden׃"],[4,17,"וַ⁠יֵּ֤דַע קַ֨יִן֙ אֶת־אִשְׁתּ֔⁠וֹ וַ⁠תַּ֖הַר וַ⁠תֵּ֣לֶד אֶת־חֲנ֑וֹךְ וַֽ⁠יְהִי֙ בֹּ֣נֶה עִ֔יר וַ⁠יִּקְרָא֙ שֵׁ֣ם הָ⁠עִ֔יר כְּ⁠שֵׁ֖ם בְּנ֥⁠וֹ חֲנֽוֹךְ׃","wa⁠yé֤̇daʻ qa֨yin֙ ʼeţ-ʼişĕ̌ţ̇֔⁠wò wa⁠ţȧ֖har wa⁠ţé֣̇led ʼeţ-ẖàn֑wòkĕ waֽ⁠yĕhiy֙ bò֣̇neh ʻi֔yr wa⁠yi̇qĕráʼ֙ şé֣̌m há⁠ʻi֔yr kĕ̇⁠şé֖̌m bĕ̇n֥⁠wò ẖànֽwòkĕ׃"],[4,18,"וַ⁠יִּוָּלֵ֤ד לַֽ⁠חֲנוֹךְ֙ אֶת־עִירָ֔ד וְ⁠עִירָ֕ד יָלַ֖ד אֶת־מְחֽוּיָאֵ֑ל וּ⁠מְחִיּיָאֵ֗ל יָלַד֙ אֶת־מְת֣וּשָׁאֵ֔ל וּ⁠מְתוּשָׁאֵ֖ל יָלַ֥ד אֶת־לָֽמֶךְ׃","wa⁠yi̇wá̇lé֤d laֽ⁠ẖànwòkĕ֙ ʼeţ-ʻiyrá֔d wĕ⁠ʻiyrá֕d yála֖d ʼeţ-mĕẖֽẇyáʼé֑l ẇ⁠mĕẖiẏyáʼé֗l yálad֙ ʼeţ-mĕţ֣ẇşá̌ʼé֔l ẇ⁠mĕţẇşá̌ʼé֖l yála֥d ʼeţ-láֽmekĕ׃"],[4,19,"וַ⁠יִּֽקַּֽח־ל֥⁠וֹ לֶ֖מֶךְ שְׁתֵּ֣י נָשִׁ֑ים שֵׁ֤ם הָֽ⁠אַחַת֙ עָדָ֔ה וְ⁠שֵׁ֥ם הַ⁠שֵּׁנִ֖ית צִלָּֽה׃","wa⁠yiֽ̇qȧֽẖ-l֥⁠wò le֖mekĕ şĕ̌ţé֣̇y náşǐ֑ym şé֤̌m háֽ⁠ʼaẖaţ֙ ʻádá֔h wĕ⁠şé֥̌m ha⁠şé̇̌ni֖yţ ẕiláֽ̇h׃"],[4,20,"וַ⁠תֵּ֥לֶד עָדָ֖ה אֶת־יָבָ֑ל ה֣וּא הָיָ֔ה אֲבִ֕י יֹשֵׁ֥ב אֹ֖הֶל וּ⁠מִקְנֶֽה׃","wa⁠ţé֥̇led ʻádá֖h ʼeţ-yábá֑l h֣ẇʼ háyá֔h ʼàbi֕y yòşé֥̌b ʼò֖hel ẇ⁠miqĕneֽh׃"],[4,21,"וְ⁠שֵׁ֥ם אָחִ֖י⁠ו יוּבָ֑ל ה֣וּא הָיָ֔ה אֲבִ֕י כָּל־תֹּפֵ֥שׂ כִּנּ֖וֹר וְ⁠עוּגָֽב׃","wĕ⁠şé֥̌m ʼáẖi֖y⁠w yẇbá֑l h֣ẇʼ háyá֔h ʼàbi֕y ká̇l-ţò̇pé֥ş̂ ki̇ṅ֖wòr wĕ⁠ʻẇgáֽb׃"],[4,22,"וְ⁠צִלָּ֣ה גַם־הִ֗וא יָֽלְדָה֙ אֶת־תּ֣וּבַל קַ֔יִן לֹטֵ֕שׁ כָּל־חֹרֵ֥שׁ נְחֹ֖שֶׁת וּ⁠בַרְזֶ֑ל וַֽ⁠אֲח֥וֹת תּֽוּבַל־קַ֖יִן נַֽעֲמָֽה׃","wĕ⁠ẕilá֣̇h gam-hi֗wʼ yáֽlĕdáh֙ ʼeţ-ţ֣̇ẇbal qa֔yin lòté֕ş̌ ká̇l-ẖòré֥ş̌ nĕẖò֖şěţ ẇ⁠barĕze֑l waֽ⁠ʼàẖ֥wòţ ţֽ̇ẇbal-qa֖yin naֽʻàmáֽh׃"],[4,23,"וַ⁠יֹּ֨אמֶר לֶ֜מֶךְ לְ⁠נָשָׁ֗י⁠ו עָדָ֤ה וְ⁠צִלָּה֙ שְׁמַ֣עַן קוֹלִ֔⁠י נְשֵׁ֣י לֶ֔מֶךְ הַאְזֵ֖נָּה אִמְרָתִ֑⁠י כִּ֣י אִ֤ישׁ הָרַ֨גְתִּי֙ לְ⁠פִצְעִ֔⁠י וְ⁠יֶ֖לֶד לְ⁠חַבֻּרָתִֽ⁠י׃","wa⁠yò̇֨ʼmer le֜mekĕ lĕ⁠náşá̌֗y⁠w ʻádá֤h wĕ⁠ẕilá̇h֙ şĕ̌ma֣ʻan qwòli֔⁠y nĕşé֣̌y le֔mekĕ haʼĕzé֖ná̇h ʼimĕráţi֑⁠y ki֣̇y ʼi֤yş̌ hára֨gĕţi̇y֙ lĕ⁠piẕĕʻi֔⁠y wĕ⁠ye֖led lĕ⁠ẖabu̇ráţiֽ⁠y׃"],[4,24,"כִּ֥י שִׁבְעָתַ֖יִם יֻקַּם־קָ֑יִן וְ⁠לֶ֖מֶךְ שִׁבְעִ֥ים וְ⁠שִׁבְעָֽה׃","ki֥̇y şǐbĕʻáţa֖yim yuqȧm-qá֑yin wĕ⁠le֖mekĕ şǐbĕʻi֥ym wĕ⁠şǐbĕʻáֽh׃"],[4,25,"וַ⁠יֵּ֨דַע אָדָ֥ם עוֹד֙ אֶת־אִשְׁתּ֔⁠וֹ וַ⁠תֵּ֣לֶד בֵּ֔ן וַ⁠תִּקְרָ֥א אֶת־שְׁמ֖⁠וֹ שֵׁ֑ת כִּ֣י שָֽׁת־לִ֤⁠י אֱלֹהִים֙ זֶ֣רַע אַחֵ֔ר תַּ֣חַת הֶ֔בֶל כִּ֥י הֲרָג֖⁠וֹ קָֽיִן׃","wa⁠yé̇֨daʻ ʼádá֥m ʻwòd֙ ʼeţ-ʼişĕ̌ţ̇֔⁠wò wa⁠ţé֣̇led bé̇֔n wa⁠ţi̇qĕrá֥ʼ ʼeţ-şĕ̌m֖⁠wò şé֑̌ţ ki֣̇y şáֽ̌ţ-li֤⁠y ʼèlòhiym֙ ze֣raʻ ʼaẖé֔r ţȧ֣ẖaţ he֔bel ki֥̇y hàrág֖⁠wò qáֽyin׃"],[4,26,"וּ⁠לְ⁠שֵׁ֤ת גַּם־הוּא֙ יֻלַּד־בֵּ֔ן וַ⁠יִּקְרָ֥א אֶת־שְׁמ֖⁠וֹ אֱנ֑וֹשׁ אָ֣ז הוּחַ֔ל לִ⁠קְרֹ֖א בְּ⁠שֵׁ֥ם יְהוָֽה׃פ","ẇ⁠lĕ⁠şé֤̌ţ gȧm-hẇʼ֙ yulȧd-bé̇֔n wa⁠yi̇qĕrá֥ʼ ʼeţ-şĕ̌m֖⁠wò ʼèn֑wòş̌ ʼá֣z hẇẖa֔l li⁠qĕrò֖ʼ bĕ̇⁠şé֥̌m yĕhwáֽh׃p"],[5,1,"זֶ֣ה סֵ֔פֶר תּוֹלְדֹ֖ת אָדָ֑ם בְּ⁠י֗וֹם בְּרֹ֤א אֱלֹהִים֙ אָדָ֔ם בִּ⁠דְמ֥וּת אֱלֹהִ֖ים עָשָׂ֥ה אֹתֽ⁠וֹ׃","ze֣h sé֔per ţ̇wòlĕdò֖ţ ʼádá֑m bĕ̇⁠y֗wòm bĕ̇rò֤ʼ ʼèlòhiym֙ ʼádá֔m bi̇⁠dĕm֥ẇţ ʼèlòhi֖ym ʻáşá֥̂h ʼòţֽ⁠wò׃"],[5,2,"זָכָ֥ר וּ⁠נְקֵבָ֖ה בְּרָאָ֑⁠ם וַ⁠יְבָ֣רֶךְ אֹתָ֗⁠ם וַ⁠יִּקְרָ֤א אֶת־שְׁמָ⁠ם֙ אָדָ֔ם בְּ⁠י֖וֹם הִבָּֽרְאָֽ⁠ם׃ס","záká֥r ẇ⁠nĕqébá֖h bĕ̇ráʼá֑⁠m wa⁠yĕbá֣rekĕ ʼòţá֗⁠m wa⁠yi̇qĕrá֤ʼ ʼeţ-şĕ̌má⁠m֙ ʼádá֔m bĕ̇⁠y֖wòm hibáֽ̇rĕʼáֽ⁠m׃s"],[5,3,"וַֽ⁠יְחִ֣י אָדָ֗ם שְׁלֹשִׁ֤ים וּ⁠מְאַת֙ שָׁנָ֔ה וַ⁠יּ֥וֹלֶד בִּ⁠דְמוּת֖⁠וֹ כְּ⁠צַלְמ֑⁠וֹ וַ⁠יִּקְרָ֥א אֶת־שְׁמ֖⁠וֹ שֵֽׁת׃","wֽa⁠yĕẖi֣y ʼádá֗m şĕ̌lòşǐ֤ym ẇ⁠mĕʼaţ֙ şá̌ná֔h wa⁠ẏ֥wòled bi̇⁠dĕmẇţ֖⁠wò kĕ̇⁠ẕalĕm֑⁠wò wa⁠yi̇qĕrá֥ʼ ʼeţ-şĕ̌m֖⁠wò şéֽ̌ţ׃"],[5,4,"וַ⁠יִּֽהְי֣וּ יְמֵי־אָדָ֗ם אַֽחֲרֵי֙ הוֹלִיד֣⁠וֹ אֶת־שֵׁ֔ת שְׁמֹנֶ֥ה מֵאֹ֖ת שָׁנָ֑ה וַ⁠יּ֥וֹלֶד בָּנִ֖ים וּ⁠בָנֽוֹת׃","wa⁠yiֽ̇hĕy֣ẇ yĕméy-ʼádá֗m ʼֽaẖàréy֙ hwòliyd֣⁠wò ʼeţ-şé̌֔ţ şĕ̌mòne֥h méʼò֖ţ şá̌ná֑h wa⁠ẏ֥wòled bá̇ni֖ym ẇ⁠bánֽwòţ׃"],[5,5,"וַ⁠יִּֽהְי֞וּ כָּל־יְמֵ֤י אָדָם֙ אֲשֶׁר־חַ֔י תְּשַׁ֤ע מֵאוֹת֙ שָׁנָ֔ה וּ⁠שְׁלֹשִׁ֖ים שָׁנָ֑ה וַ⁠יָּמֹֽת׃ס","wa⁠yiֽ̇hĕy֞ẇ ká̇l-yĕmé֤y ʼádám֙ ʼàşěr-ẖa֔y ţĕ̇şǎ֤ʻ méʼwòţ֙ şá̌ná֔h ẇ⁠şĕ̌lòşǐ֖ym şá̌ná֑h wa⁠yá̇mòֽţ׃s"],[5,6,"וַֽ⁠יְחִי־שֵׁ֕ת חָמֵ֥שׁ שָׁנִ֖ים וּ⁠מְאַ֣ת שָׁנָ֑ה וַ⁠יּ֖וֹלֶד אֶת־אֱנֽוֹשׁ׃","wֽa⁠yĕẖiy-şé̌֕ţ ẖámé֥ş̌ şá̌ni֖ym ẇ⁠mĕʼa֣ţ şá̌ná֑h wa⁠ẏ֖wòled ʼeţ-ʼènֽwòş̌׃"],[5,7,"וַֽ⁠יְחִי־שֵׁ֗ת אַֽחֲרֵי֙ הוֹלִיד֣⁠וֹ אֶת־אֱנ֔וֹשׁ שֶׁ֣בַע שָׁנִ֔ים וּ⁠שְׁמֹנֶ֥ה מֵא֖וֹת שָׁנָ֑ה וַ⁠יּ֥וֹלֶד בָּנִ֖ים וּ⁠בָנֽוֹת׃","wֽa⁠yĕẖiy-şé̌֗ţ ʼֽaẖàréy֙ hwòliyd֣⁠wò ʼeţ-ʼèn֔wòş̌ şě֣baʻ şá̌ni֔ym ẇ⁠şĕ̌mòne֥h méʼ֖wòţ şá̌ná֑h wa⁠ẏ֥wòled bá̇ni֖ym ẇ⁠bánֽwòţ׃"],[5,8,"וַ⁠יִּֽהְיוּ֙ כָּל־יְמֵי־שֵׁ֔ת שְׁתֵּ֤ים עֶשְׂרֵה֙ שָׁנָ֔ה וּ⁠תְשַׁ֥ע מֵא֖וֹת שָׁנָ֑ה וַ⁠יָּמֹֽת׃ס","wa⁠yiֽ̇hĕyẇ֙ ká̇l-yĕméy-şé̌֔ţ şĕ̌ţé֤̇ym ʻeşĕ̂réh֙ şá̌ná֔h ẇ⁠ţĕşǎ֥ʻ méʼ֖wòţ şá̌ná֑h wa⁠yá̇mòֽţ׃s"],[5,9,"וַֽ⁠יְחִ֥י אֱנ֖וֹשׁ תִּשְׁעִ֣ים שָׁנָ֑ה וַ⁠יּ֖וֹלֶד אֶת־קֵינָֽן׃","wֽa⁠yĕẖi֥y ʼèn֖wòş̌ ţi̇şĕ̌ʻi֣ym şá̌ná֑h wa⁠ẏ֖wòled ʼeţ-qéynáֽn׃"],[5,10,"וַֽ⁠יְחִ֣י אֱנ֗וֹשׁ אַֽחֲרֵי֙ הוֹלִיד֣⁠וֹ אֶת־קֵינָ֔ן חֲמֵ֤שׁ עֶשְׂרֵה֙ שָׁנָ֔ה וּ⁠שְׁמֹנֶ֥ה מֵא֖וֹת שָׁנָ֑ה וַ⁠יּ֥וֹלֶד בָּנִ֖ים וּ⁠בָנֽוֹת׃","wֽa⁠yĕẖi֣y ʼèn֗wòş̌ ʼֽaẖàréy֙ hwòliyd֣⁠wò ʼeţ-qéyná֔n ẖàmé֤ş̌ ʻeşĕ̂réh֙ şá̌ná֔h ẇ⁠şĕ̌mòne֥h méʼ֖wòţ şá̌ná֑h wa⁠ẏ֥wòled bá̇ni֖ym ẇ⁠bánֽwòţ׃"],[5,11,"וַ⁠יִּֽהְיוּ֙ כָּל־יְמֵ֣י אֱנ֔וֹשׁ חָמֵ֣שׁ שָׁנִ֔ים וּ⁠תְשַׁ֥ע מֵא֖וֹת שָׁנָ֑ה וַ⁠יָּמֹֽת׃ס","wa⁠yiֽ̇hĕyẇ֙ ká̇l-yĕmé֣y ʼèn֔wòş̌ ẖámé֣ş̌ şá̌ni֔ym ẇ⁠ţĕşǎ֥ʻ méʼ֖wòţ şá̌ná֑h wa⁠yá̇mòֽţ׃s"],[5,12,"וַֽ⁠יְחִ֥י קֵינָ֖ן שִׁבְעִ֣ים שָׁנָ֑ה וַ⁠יּ֖וֹלֶד אֶת־מַֽהֲלַלְאֵֽל׃","wֽa⁠yĕẖi֥y qéyná֖n şǐbĕʻi֣ym şá̌ná֑h wa⁠ẏ֖wòled ʼeţ-mֽahàlalĕʼéֽl׃"],[5,13,"וַ⁠יְחִ֣י קֵינָ֗ן אַחֲרֵי֙ הוֹלִיד֣⁠וֹ אֶת־מַֽהֲלַלְאֵ֔ל אַרְבָּעִ֣ים שָׁנָ֔ה וּ⁠שְׁמֹנֶ֥ה מֵא֖וֹת שָׁנָ֑ה וַ⁠יּ֥וֹלֶד בָּנִ֖ים וּ⁠בָנֽוֹת׃","wa⁠yĕẖi֣y qéyná֗n ʼaẖàréy֙ hwòliyd֣⁠wò ʼeţ-mֽahàlalĕʼé֔l ʼarĕbá̇ʻi֣ym şá̌ná֔h ẇ⁠şĕ̌mòne֥h méʼ֖wòţ şá̌ná֑h wa⁠ẏ֥wòled bá̇ni֖ym ẇ⁠bánֽwòţ׃"],[5,14,"וַ⁠יִּֽהְיוּ֙ כָּל־יְמֵ֣י קֵינָ֔ן עֶ֣שֶׂר שָׁנִ֔ים וּ⁠תְשַׁ֥ע מֵא֖וֹת שָׁנָ֑ה וַ⁠יָּמֹֽת׃ס","wa⁠yiֽ̇hĕyẇ֙ ká̇l-yĕmé֣y qéyná֔n ʻe֣şêr şá̌ni֔ym ẇ⁠ţĕşǎ֥ʻ méʼ֖wòţ şá̌ná֑h wa⁠yá̇mòֽţ׃s"],[5,15,"וַֽ⁠יְחִ֣י מַֽהֲלַלְאֵ֔ל חָמֵ֥שׁ שָׁנִ֖ים וְ⁠שִׁשִּׁ֣ים שָׁנָ֑ה וַ⁠יּ֖וֹלֶד אֶת־יָֽרֶד׃","wֽa⁠yĕẖi֣y mֽahàlalĕʼé֔l ẖámé֥ş̌ şá̌ni֖ym wĕ⁠şǐşi֣̇̌ym şá̌ná֑h wa⁠ẏ֖wòled ʼeţ-yáֽred׃"],[5,16,"וַֽ⁠יְחִ֣י מַֽהֲלַלְאֵ֗ל אַֽחֲרֵי֙ הוֹלִיד֣⁠וֹ אֶת־יֶ֔רֶד שְׁלֹשִׁ֣ים שָׁנָ֔ה וּ⁠שְׁמֹנֶ֥ה מֵא֖וֹת שָׁנָ֑ה וַ⁠יּ֥וֹלֶד בָּנִ֖ים וּ⁠בָנֽוֹת׃","wֽa⁠yĕẖi֣y mֽahàlalĕʼé֗l ʼֽaẖàréy֙ hwòliyd֣⁠wò ʼeţ-ye֔red şĕ̌lòşǐ֣ym şá̌ná֔h ẇ⁠şĕ̌mòne֥h méʼ֖wòţ şá̌ná֑h wa⁠ẏ֥wòled bá̇ni֖ym ẇ⁠bánֽwòţ׃"],[5,17,"וַ⁠יִּהְיוּ֙ כָּל־יְמֵ֣י מַהֲלַלְאֵ֔ל חָמֵ֤שׁ וְ⁠תִשְׁעִים֙ שָׁנָ֔ה וּ⁠שְׁמֹנֶ֥ה מֵא֖וֹת שָׁנָ֑ה וַ⁠יָּמֹֽת׃ס","wa⁠yi̇hĕyẇ֙ ká̇l-yĕmé֣y mahàlalĕʼé֔l ẖámé֤ş̌ wĕ⁠ţişĕ̌ʻiym֙ şá̌ná֔h ẇ⁠şĕ̌mòne֥h méʼ֖wòţ şá̌ná֑h wa⁠yá̇mòֽţ׃s"],[5,18,"וַֽ⁠יְחִי־יֶ֕רֶד שְׁתַּ֧יִם וְ⁠שִׁשִּׁ֛ים שָׁנָ֖ה וּ⁠מְאַ֣ת שָׁנָ֑ה וַ⁠יּ֖וֹלֶד אֶת־חֲנֽוֹךְ׃","wֽa⁠yĕẖiy-ye֕red şĕ̌ţȧ֧yim wĕ⁠şǐşi֛̇̌ym şá̌ná֖h ẇ⁠mĕʼa֣ţ şá̌ná֑h wa⁠ẏ֖wòled ʼeţ-ẖànֽwòkĕ׃"],[5,19,"וַֽ⁠יְחִי־יֶ֗רֶד אַֽחֲרֵי֙ הוֹלִיד֣⁠וֹ אֶת־חֲנ֔וֹךְ שְׁמֹנֶ֥ה מֵא֖וֹת שָׁנָ֑ה וַ⁠יּ֥וֹלֶד בָּנִ֖ים וּ⁠בָנֽוֹת׃","wֽa⁠yĕẖiy-ye֗red ʼֽaẖàréy֙ hwòliyd֣⁠wò ʼeţ-ẖàn֔wòkĕ şĕ̌mòne֥h méʼ֖wòţ şá̌ná֑h wa⁠ẏ֥wòled bá̇ni֖ym ẇ⁠bánֽwòţ׃"],[5,20,"וַ⁠יִּֽהְיוּ֙ כָּל־יְמֵי־יֶ֔רֶד שְׁתַּ֤יִם וְ⁠שִׁשִּׁים֙ שָׁנָ֔ה וּ⁠תְשַׁ֥ע מֵא֖וֹת שָׁנָ֑ה וַ⁠יָּמֹֽת׃פ","wa⁠yiֽ̇hĕyẇ֙ ká̇l-yĕméy-ye֔red şĕ̌ţȧ֤yim wĕ⁠şǐşi̇̌ym֙ şá̌ná֔h ẇ⁠ţĕşǎ֥ʻ méʼ֖wòţ şá̌ná֑h wa⁠yá̇mòֽţ׃p"],[5,21,"וַֽ⁠יְחִ֣י חֲנ֔וֹךְ חָמֵ֥שׁ וְ⁠שִׁשִּׁ֖ים שָׁנָ֑ה וַ⁠יּ֖וֹלֶד אֶת־מְתוּשָֽׁלַח׃","wֽa⁠yĕẖi֣y ẖàn֔wòkĕ ẖámé֥ş̌ wĕ⁠şǐşi֖̇̌ym şá̌ná֑h wa⁠ẏ֖wòled ʼeţ-mĕţẇşáֽ̌laẖ׃"],[5,22,"וַ⁠יִּתְהַלֵּ֨ךְ חֲנ֜וֹךְ אֶת־הָֽ⁠אֱלֹהִ֗ים אַֽחֲרֵי֙ הוֹלִיד֣⁠וֹ אֶת־מְתוּשֶׁ֔לַח שְׁלֹ֥שׁ מֵא֖וֹת שָׁנָ֑ה וַ⁠יּ֥וֹלֶד בָּנִ֖ים וּ⁠בָנֽוֹת׃","wa⁠yi̇ţĕhalé̇֨kĕ ẖàn֜wòkĕ ʼeţ-hֽá⁠ʼèlòhi֗ym ʼֽaẖàréy֙ hwòliyd֣⁠wò ʼeţ-mĕţẇşě֔laẖ şĕ̌lò֥ş̌ méʼ֖wòţ şá̌ná֑h wa⁠ẏ֥wòled bá̇ni֖ym ẇ⁠bánֽwòţ׃"],[5,23,"וַ⁠יְהִ֖י כָּל־יְמֵ֣י חֲנ֑וֹךְ חָמֵ֤שׁ וְ⁠שִׁשִּׁים֙ שָׁנָ֔ה וּ⁠שְׁלֹ֥שׁ מֵא֖וֹת שָׁנָֽה׃","wa⁠yĕhi֖y ká̇l-yĕmé֣y ẖàn֑wòkĕ ẖámé֤ş̌ wĕ⁠şǐşi̇̌ym֙ şá̌ná֔h ẇ⁠şĕ̌lò֥ş̌ méʼ֖wòţ şá̌náֽh׃"],[5,24,"וַ⁠יִּתְהַלֵּ֥ךְ חֲנ֖וֹךְ אֶת־הָֽ⁠אֱלֹהִ֑ים וְ⁠אֵינֶ֕⁠נּוּ כִּֽי־לָקַ֥ח אֹת֖⁠וֹ אֱלֹהִֽים׃פ","wa⁠yi̇ţĕhalé֥̇kĕ ẖàn֖wòkĕ ʼeţ-hֽá⁠ʼèlòhi֑ym wĕ⁠ʼéyne֕⁠ṅẇ kiֽ̇y-láqa֥ẖ ʼòţ֖⁠wò ʼèlòhiֽym׃p"],[5,25,"וַ⁠יְחִ֣י מְתוּשֶׁ֔לַח שֶׁ֧בַע וּ⁠שְׁמֹנִ֛ים שָׁנָ֖ה וּ⁠מְאַ֣ת שָׁנָ֑ה וַ⁠יּ֖וֹלֶד אֶת־לָֽמֶךְ׃","wa⁠yĕẖi֣y mĕţẇşě֔laẖ şě֧baʻ ẇ⁠şĕ̌mòni֛ym şá̌ná֖h ẇ⁠mĕʼa֣ţ şá̌ná֑h wa⁠ẏ֖wòled ʼeţ-láֽmekĕ׃"],[5,26,"וַֽ⁠יְחִ֣י מְתוּשֶׁ֗לַח אַֽחֲרֵי֙ הוֹלִיד֣⁠וֹ אֶת־לֶ֔מֶךְ שְׁתַּ֤יִם וּ⁠שְׁמוֹנִים֙ שָׁנָ֔ה וּ⁠שְׁבַ֥ע מֵא֖וֹת שָׁנָ֑ה וַ⁠יּ֥וֹלֶד בָּנִ֖ים וּ⁠בָנֽוֹת׃","wֽa⁠yĕẖi֣y mĕţẇşě֗laẖ ʼֽaẖàréy֙ hwòliyd֣⁠wò ʼeţ-le֔mekĕ şĕ̌ţȧ֤yim ẇ⁠şĕ̌mwòniym֙ şá̌ná֔h ẇ⁠şĕ̌ba֥ʻ méʼ֖wòţ şá̌ná֑h wa⁠ẏ֥wòled bá̇ni֖ym ẇ⁠bánֽwòţ׃"],[5,27,"וַ⁠יִּהְיוּ֙ כָּל־יְמֵ֣י מְתוּשֶׁ֔לַח תֵּ֤שַׁע וְ⁠שִׁשִּׁים֙ שָׁנָ֔ה וּ⁠תְשַׁ֥ע מֵא֖וֹת שָׁנָ֑ה וַ⁠יָּמֹֽת׃פ","wa⁠yi̇hĕyẇ֙ ká̇l-yĕmé֣y mĕţẇşě֔laẖ ţé֤̇şǎʻ wĕ⁠şǐşi̇̌ym֙ şá̌ná֔h ẇ⁠ţĕşǎ֥ʻ méʼ֖wòţ şá̌ná֑h wa⁠yá̇mòֽţ׃p"],[5,28,"וַֽ⁠יְחִי־לֶ֕מֶךְ שְׁתַּ֧יִם וּ⁠שְׁמֹנִ֛ים שָׁנָ֖ה וּ⁠מְאַ֣ת שָׁנָ֑ה וַ⁠יּ֖וֹלֶד בֵּֽן׃","wֽa⁠yĕẖiy-le֕mekĕ şĕ̌ţȧ֧yim ẇ⁠şĕ̌mòni֛ym şá̌ná֖h ẇ⁠mĕʼa֣ţ şá̌ná֑h wa⁠ẏ֖wòled béֽ̇n׃"],[5,29,"וַ⁠יִּקְרָ֧א אֶת־שְׁמ֛⁠וֹ נֹ֖חַ לֵ⁠אמֹ֑ר זֶ֞֠ה יְנַחֲמֵ֤⁠נוּ מִֽ⁠מַּעֲשֵׂ֨⁠נוּ֙ וּ⁠מֵ⁠עִצְּב֣וֹן יָדֵ֔י⁠נוּ מִן־הָ֣⁠אֲדָמָ֔ה אֲשֶׁ֥ר אֵֽרְרָ֖⁠הּ יְהוָֽה׃","wa⁠yi̇qĕrá֧ʼ ʼeţ-şĕ̌m֛⁠wò nò֖ẖa lé⁠ʼmò֑r ze֞֠h yĕnaẖàmé֤⁠nẇ miֽ⁠mȧʻàşé̂֨⁠nẇ֙ ẇ⁠mé⁠ʻiẕĕ̇b֣wòn yádé֔y⁠nẇ min-há֣⁠ʼàdámá֔h ʼàşě֥r ʼֽérĕrá֖⁠ḣ yĕhwáֽh׃"],[5,30,"וַֽ⁠יְחִי־לֶ֗מֶךְ אַֽחֲרֵי֙ הוֹלִיד֣⁠וֹ אֶת־נֹ֔חַ חָמֵ֤שׁ וְ⁠תִשְׁעִים֙ שָׁנָ֔ה וַ⁠חֲמֵ֥שׁ מֵאֹ֖ת שָׁנָ֑ה וַ⁠יּ֥וֹלֶד בָּנִ֖ים וּ⁠בָנֽוֹת׃","wֽa⁠yĕẖiy-le֗mekĕ ʼֽaẖàréy֙ hwòliyd֣⁠wò ʼeţ-nò֔ẖa ẖámé֤ş̌ wĕ⁠ţişĕ̌ʻiym֙ şá̌ná֔h wa⁠ẖàmé֥ş̌ méʼò֖ţ şá̌ná֑h wa⁠ẏ֥wòled bá̇ni֖ym ẇ⁠bánֽwòţ׃"],[5,31,"וַֽ⁠יְהִי֙ כָּל־יְמֵי־לֶ֔מֶךְ שֶׁ֤בַע וְ⁠שִׁבְעִים֙ שָׁנָ֔ה וּ⁠שְׁבַ֥ע מֵא֖וֹת שָׁנָ֑ה וַ⁠יָּמֹֽת׃ס","wֽa⁠yĕhiy֙ ká̇l-yĕméy-le֔mekĕ şě֤baʻ wĕ⁠şǐbĕʻiym֙ şá̌ná֔h ẇ⁠şĕ̌ba֥ʻ méʼ֖wòţ şá̌ná֑h wa⁠yá̇mòֽţ׃s"],[5,32,"וַֽ⁠יְהִי־נֹ֕חַ בֶּן־חֲמֵ֥שׁ מֵא֖וֹת שָׁנָ֑ה וַ⁠יּ֣וֹלֶד נֹ֔חַ אֶת־שֵׁ֖ם אֶת־חָ֥ם וְ⁠אֶת־יָֽפֶת׃","wֽa⁠yĕhiy-nò֕ẖa bėn-ẖàmé֥ş̌ méʼ֖wòţ şá̌ná֑h wa⁠ẏ֣wòled nò֔ẖa ʼeţ-şé֖̌m ʼeţ-ẖá֥m wĕ⁠ʼeţ-yáֽpeţ׃"],[6,1,"וַֽ⁠יְהִי֙ כִּֽי־הֵחֵ֣ל הָֽ⁠אָדָ֔ם לָ⁠רֹ֖ב עַל־פְּנֵ֣י הָֽ⁠אֲדָמָ֑ה וּ⁠בָנ֖וֹת יֻלְּד֥וּ לָ⁠הֶֽם׃","waֽ⁠yĕhiy֙ kiֽ̇y-héẖé֣l hֽá⁠ʼádá֔m lá⁠rò֖b ʻal-pĕ̇né֣y hֽá⁠ʼàdámá֑h ẇ⁠bán֖wòţ yulĕ̇d֥ẇ lá⁠heֽm׃"],[6,2,"וַ⁠יִּרְא֤וּ בְנֵי־הָֽ⁠אֱלֹהִים֙ אֶת־בְּנ֣וֹת הָֽ⁠אָדָ֔ם כִּ֥י טֹבֹ֖ת הֵ֑נָּה וַ⁠יִּקְח֤וּ לָ⁠הֶם֙ נָשִׁ֔ים מִ⁠כֹּ֖ל אֲשֶׁ֥ר בָּחָֽרוּ׃","wa⁠yi̇rĕʼ֤ẇ bĕnéy-háֽ⁠ʼèlòhiym֙ ʼeţ-bĕ̇n֣wòţ háֽ⁠ʼádá֔m ki֥̇y tòbò֖ţ hé֑ná̇h wa⁠yi̇qĕẖ֤ẇ lá⁠hem֙ náşǐ֔ym mi⁠kò֖̇l ʼàşě֥r bá̇ẖáֽrẇ׃"],[6,3,"וַ⁠יֹּ֣אמֶר יְהוָ֗ה לֹֽא־יָד֨וֹן רוּחִ֤⁠י בָֽ⁠אָדָם֙ לְ⁠עֹלָ֔ם בְּ⁠שַׁ⁠גַּ֖ם ה֣וּא בָשָׂ֑ר וְ⁠הָי֣וּ יָמָ֔י⁠ו מֵאָ֥ה וְ⁠עֶשְׂרִ֖ים שָׁנָֽה׃","wa⁠yò֣̇ʼmer yĕhwá֗h lòֽʼ-yád֨wòn rẇẖi֤⁠y báֽ⁠ʼádám֙ lĕ⁠ʻòlá֔m bĕ̇⁠şǎ⁠gȧ֖m h֣ẇʼ báşá֑̂r wĕ⁠háy֣ẇ yámá֔y⁠w méʼá֥h wĕ⁠ʻeşĕ̂ri֖ym şá̌náֽh׃"],[6,4,"הַ⁠נְּפִלִ֞ים הָי֣וּ בָ⁠אָרֶץ֮ בַּ⁠יָּמִ֣ים הָ⁠הֵם֒ וְ⁠גַ֣ם אַֽחֲרֵי־כֵ֗ן אֲשֶׁ֨ר יָבֹ֜אוּ בְּנֵ֤י הָֽ⁠אֱלֹהִים֙ אֶל־בְּנ֣וֹת הָֽ⁠אָדָ֔ם וְ⁠יָלְד֖וּ לָ⁠הֶ֑ם הֵ֧מָּה הַ⁠גִּבֹּרִ֛ים אֲשֶׁ֥ר מֵ⁠עוֹלָ֖ם אַנְשֵׁ֥י הַ⁠שֵּֽׁם׃פ","ha⁠nĕ̇pili֞ym háy֣ẇ bá⁠ʼáreẕ֮ bȧ⁠yá̇mi֣ym há⁠hém֒ wĕ⁠ga֣m ʼaֽẖàréy-ké֗n ʼàşě֨r yábò֜ʼẇ bĕ̇né֤y háֽ⁠ʼèlòhiym֙ ʼel-bĕ̇n֣wòţ hֽá⁠ʼádá֔m wĕ⁠yálĕd֖ẇ lá⁠he֑m hé֧má̇h ha⁠gi̇bò̇ri֛ym ʼàşě֥r mé⁠ʻwòlá֖m ʼanĕşé֥̌y ha⁠şéֽ̇̌m׃p"],[6,5,"וַ⁠יַּ֣רְא יְהוָ֔ה כִּ֥י רַבָּ֛ה רָעַ֥ת הָ⁠אָדָ֖ם בָּ⁠אָ֑רֶץ וְ⁠כָל־יֵ֨צֶר֙ מַחְשְׁבֹ֣ת לִבּ֔⁠וֹ רַ֥ק רַ֖ע כָּל־הַ⁠יּֽוֹם׃","wa⁠yȧ֣rĕʼ yĕhwá֔h ki֥̇y rabá֛̇h ráʻa֥ţ há⁠ʼádá֖m bá̇⁠ʼá֑reẕ wĕ⁠kál-yé֨ẕer֙ maẖĕşĕ̌bò֣ţ liḃ֔⁠wò ra֥q ra֖ʻ ká̇l-ha⁠ẏֽwòm׃"],[6,6,"וַ⁠יִּנָּ֣חֶם יְהוָ֔ה כִּֽי־עָשָׂ֥ה אֶת־הָֽ⁠אָדָ֖ם בָּ⁠אָ֑רֶץ וַ⁠יִּתְעַצֵּ֖ב אֶל־לִבּֽ⁠וֹ׃","wa⁠yi̇ná֣̇ẖem yĕhwá֔h kiֽ̇y-ʻáşá֥̂h ʼeţ-hֽá⁠ʼádá֖m bá̇⁠ʼá֑reẕ wa⁠yi̇ţĕʻaẕé֖̇b ʼel-liḃֽ⁠wò׃"],[6,7,"וַ⁠יֹּ֣אמֶר יְהוָ֗ה אֶמְחֶ֨ה אֶת־הָ⁠אָדָ֤ם אֲשֶׁר־בָּרָ֨אתִי֙ מֵ⁠עַל֙ פְּנֵ֣י הָֽ⁠אֲדָמָ֔ה מֵֽ⁠אָדָם֙ עַד־בְּהֵמָ֔ה עַד־רֶ֖מֶשׂ וְ⁠עַד־ע֣וֹף הַ⁠שָּׁמָ֑יִם כִּ֥י נִחַ֖מְתִּי כִּ֥י עֲשִׂיתִֽ⁠ם׃","wa⁠yò֣̇ʼmer yĕhwá֗h ʼemĕẖe֨h ʼeţ-há⁠ʼádá֤m ʼàşěr-bá̇rá֨ʼţiy֙ mé⁠ʻal֙ pĕ̇né֣y hֽá⁠ʼàdámá֔h mֽé⁠ʼádám֙ ʻad-bĕ̇hémá֔h ʻad-re֖meş̂ wĕ⁠ʻad-ʻ֣wòp ha⁠şá̇̌má֑yim ki֥̇y niẖa֖mĕţi̇y ki֥̇y ʻàşîyţiֽ⁠m׃"],[6,8,"וְ⁠נֹ֕חַ מָ֥צָא חֵ֖ן בְּ⁠עֵינֵ֥י יְהוָֽה׃פ","wĕ⁠nò֕ẖa má֥ẕáʼ ẖé֖n bĕ̇⁠ʻéyné֥y yĕhwáֽh׃p"],[6,9,"אֵ֚לֶּה תּוֹלְדֹ֣ת נֹ֔חַ נֹ֗חַ אִ֥ישׁ צַדִּ֛יק תָּמִ֥ים הָיָ֖ה בְּ⁠דֹֽרֹתָ֑י⁠ו אֶת־הָֽ⁠אֱלֹהִ֖ים הִֽתְהַלֶּךְ־נֹֽחַ׃","ʼé֚lėh ţ̇wòlĕdò֣ţ nò֔ẖa nò֗ẖa ʼi֥yş̌ ẕadi֛̇yq ţá̇mi֥ym háyá֖h bĕ̇⁠dòֽròţá֑y⁠w ʼeţ-hֽá⁠ʼèlòhi֖ym hiֽţĕhalėkĕ-nòֽẖa׃"],[6,10,"וַ⁠יּ֥וֹלֶד נֹ֖חַ שְׁלֹשָׁ֣ה בָנִ֑ים אֶת־שֵׁ֖ם אֶת־חָ֥ם וְ⁠אֶת־יָֽפֶת׃","wa⁠ẏ֥wòled nò֖ẖa şĕ̌lòşá֣̌h báni֑ym ʼeţ-şé֖̌m ʼeţ-ẖá֥m wĕ⁠ʼeţ-yáֽpeţ׃"],[6,11,"וַ⁠תִּשָּׁחֵ֥ת הָ⁠אָ֖רֶץ לִ⁠פְנֵ֣י הָֽ⁠אֱלֹהִ֑ים וַ⁠תִּמָּלֵ֥א הָ⁠אָ֖רֶץ חָמָֽס׃","wa⁠ţi̇şá̇̌ẖé֥ţ há⁠ʼá֖reẕ li⁠pĕné֣y hֽá⁠ʼèlòhi֑ym wa⁠ţi̇má̇lé֥ʼ há⁠ʼá֖reẕ ẖámáֽs׃"],[6,12,"וַ⁠יַּ֧רְא אֱלֹהִ֛ים אֶת־הָ⁠אָ֖רֶץ וְ⁠הִנֵּ֣ה נִשְׁחָ֑תָה כִּֽי־הִשְׁחִ֧ית כָּל־בָּשָׂ֛ר אֶת־דַּרְכּ֖⁠וֹ עַל־הָ⁠אָֽרֶץ׃ס","wa⁠yȧ֧rĕʼ ʼèlòhi֛ym ʼeţ-há⁠ʼá֖reẕ wĕ⁠hiné֣̇h nişĕ̌ẖá֑ţáh kiֽ̇y-hişĕ̌ẖi֧yţ ká̇l-bá̇şá֛̂r ʼeţ-dȧrĕk֖̇⁠wò ʻal-há⁠ʼáֽreẕ׃s"],[6,13,"וַ⁠יֹּ֨אמֶר אֱלֹהִ֜ים לְ⁠נֹ֗חַ קֵ֤ץ כָּל־בָּשָׂר֙ בָּ֣א לְ⁠פָנַ֔⁠י כִּֽי־מָלְאָ֥ה הָ⁠אָ֛רֶץ חָמָ֖ס מִ⁠פְּנֵי⁠הֶ֑ם וְ⁠הִנְ⁠נִ֥י מַשְׁחִיתָ֖⁠ם אֶת־הָ⁠אָֽרֶץ׃","wa⁠yò̇֨ʼmer ʼèlòhi֜ym lĕ⁠nò֗ẖa qé֤ẕ ká̇l-bá̇şá̂r֙ bá֣̇ʼ lĕ⁠pána֔⁠y kiֽ̇y-málĕʼá֥h há⁠ʼá֛reẕ ẖámá֖s mi⁠pĕ̇néy⁠he֑m wĕ⁠hinĕ⁠ni֥y maşĕ̌ẖiyţá֖⁠m ʼeţ-há⁠ʼáֽreẕ׃"],[6,14,"עֲשֵׂ֤ה לְ⁠ךָ֙ תֵּבַ֣ת עֲצֵי־גֹ֔פֶר קִנִּ֖ים תַּֽעֲשֶׂ֣ה אֶת־הַ⁠תֵּבָ֑ה וְ⁠כָֽפַרְתָּ֥ אֹתָ֛⁠הּ מִ⁠בַּ֥יִת וּ⁠מִ⁠ח֖וּץ בַּ⁠כֹּֽפֶר׃","ʻàşé֤̂h lĕ⁠ká֙ ţé̇ba֣ţ ʻàẕéy-gò֔per qini֖̇ym ţֽ̇aʻàşê֣h ʼeţ-ha⁠ţé̇bá֑h wĕ⁠káֽparĕţá֥̇ ʼòţá֛⁠ḣ mi⁠bȧ֥yiţ ẇ⁠mi⁠ẖ֖ẇẕ bȧ⁠kòֽ̇per׃"],[6,15,"וְ⁠זֶ֕ה אֲשֶׁ֥ר תַּֽעֲשֶׂ֖ה אֹתָ֑⁠הּ שְׁלֹ֧שׁ מֵא֣וֹת אַמָּ֗ה אֹ֚רֶךְ הַ⁠תֵּבָ֔ה חֲמִשִּׁ֤ים אַמָּה֙ רָחְבָּ֔⁠הּ וּ⁠שְׁלֹשִׁ֥ים אַמָּ֖ה קוֹמָתָֽ⁠הּ׃","wĕ⁠ze֕h ʼàşě֥r ţȧֽʻàşê֖h ʼòţá֑⁠ḣ şĕ̌lò֧ş̌ méʼ֣wòţ ʼamá̇֗h ʼò֚rekĕ ha⁠ţé̇bá֔h ẖàmişi֤̇̌ym ʼamá̇h֙ ráẖĕbá̇֔⁠ḣ ẇ⁠şĕ̌lòşǐ֥ym ʼamá֖̇h qwòmáţáֽ⁠ḣ׃"],[6,16,"צֹ֣הַר ׀ תַּֽעֲשֶׂ֣ה לַ⁠תֵּבָ֗ה וְ⁠אֶל־אַמָּה֙ תְּכַלֶ֣⁠נָּה מִ⁠לְ⁠מַ֔עְלָ⁠ה וּ⁠פֶ֥תַח הַ⁠תֵּבָ֖ה בְּ⁠צִדָּ֣⁠הּ תָּשִׂ֑ים תַּחְתִּיִּ֛ם שְׁנִיִּ֥ם וּ⁠שְׁלִשִׁ֖ים תַּֽעֲשֶֽׂ⁠הָ׃","ẕò֣har ׀ ţֽ̇aʻàşê֣h la⁠ţé̇bá֗h wĕ⁠ʼel-ʼamá̇h֙ ţĕ̇kale֣⁠ná̇h mi⁠lĕ⁠ma֔ʻĕlá⁠h ẇ⁠pe֥ţaẖ ha⁠ţé̇bá֖h bĕ̇⁠ẕidá֣̇⁠ḣ ţá̇şî֑ym ţȧẖĕţi̇yi֛̇m şĕ̌niyi֥̇m ẇ⁠şĕ̌lişǐ֖ym ţֽ̇aʻàşêֽ⁠há׃"],[6,17,"וַ⁠אֲנִ֗י הִנְ⁠נִי֩ מֵבִ֨יא אֶת־הַ⁠מַּבּ֥וּל מַ֨יִם֙ עַל־הָ⁠אָ֔רֶץ לְ⁠שַׁחֵ֣ת כָּל־בָּשָׂ֗ר אֲשֶׁר־בּ⁠וֹ֙ ר֣וּחַ חַיִּ֔ים מִ⁠תַּ֖חַת הַ⁠שָּׁמָ֑יִם כֹּ֥ל אֲשֶׁר־בָּ⁠אָ֖רֶץ יִגְוָֽע׃","wa⁠ʼàni֗y hinĕ⁠niy֩ mébi֨yʼ ʼeţ-ha⁠mȧḃ֥ẇl ma֨yim֙ ʻal-há⁠ʼá֔reẕ lĕ⁠şǎẖé֣ţ ká̇l-bá̇şá̂֗r ʼàşěr-ḃ⁠wò֙ r֣ẇẖa ẖayi̇֔ym mi⁠ţȧ֖ẖaţ ha⁠şá̇̌má֑yim kò֥̇l ʼàşěr-bá̇⁠ʼá֖reẕ yigĕwáֽʻ׃"],[6,18,"וַ⁠הֲקִמֹתִ֥י אֶת־בְּרִיתִ֖⁠י אִתָּ֑⁠ךְ וּ⁠בָאתָ֙ אֶל־הַ⁠תֵּבָ֔ה אַתָּ֕ה וּ⁠בָנֶ֛י⁠ךָ וְ⁠אִשְׁתְּ⁠ךָ֥ וּ⁠נְשֵֽׁי־בָנֶ֖י⁠ךָ אִתָּֽ⁠ךְ׃","wa⁠hàqimòţi֥y ʼeţ-bĕ̇riyţi֖⁠y ʼiţá֑̇⁠kĕ ẇ⁠báʼţá֙ ʼel-ha⁠ţé̇bá֔h ʼaţá̇֕h ẇ⁠báne֛y⁠ká wĕ⁠ʼişĕ̌ţĕ̇⁠ká֥ ẇ⁠nĕşéֽ̌y-báne֖y⁠ká ʼiţáֽ̇⁠kĕ׃"],[6,19,"וּ⁠מִ⁠כָּל־הָ֠⁠חַי מִֽ⁠כָּל־בָּשָׂ֞ר שְׁנַ֧יִם מִ⁠כֹּ֛ל תָּבִ֥יא אֶל־הַ⁠תֵּבָ֖ה לְ⁠הַחֲיֹ֣ת אִתָּ֑⁠ךְ זָכָ֥ר וּ⁠נְקֵבָ֖ה יִֽהְיֽוּ׃","ẇ⁠mi⁠ká̇l-há֠⁠ẖay miֽ⁠ká̇l-bá̇şá̂֞r şĕ̌na֧yim mi⁠kò֛̇l ţá̇bi֥yʼ ʼel-ha⁠ţé̇bá֖h lĕ⁠haẖàyò֣ţ ʼiţá֑̇⁠kĕ záká֥r ẇ⁠nĕqébá֖h yiֽhĕyֽẇ׃"],[6,20,"מֵ⁠הָ⁠ע֣וֹף לְ⁠מִינֵ֗⁠הוּ וּ⁠מִן־הַ⁠בְּהֵמָה֙ לְ⁠מִינָ֔⁠הּ מִ⁠כֹּ֛ל רֶ֥מֶשׂ הָֽ⁠אֲדָמָ֖ה לְ⁠מִינֵ֑⁠הוּ שְׁנַ֧יִם מִ⁠כֹּ֛ל יָבֹ֥אוּ אֵלֶ֖י⁠ךָ לְ⁠הַֽחֲיֽוֹת׃","mé⁠há⁠ʻ֣wòp lĕ⁠miyné֗⁠hẇ ẇ⁠min-ha⁠bĕ̇hémáh֙ lĕ⁠miyná֔⁠ḣ mi⁠kò֛̇l re֥meş̂ hֽá⁠ʼàdámá֖h lĕ⁠miyné֑⁠hẇ şĕ̌na֧yim mi⁠kò֛̇l yábò֥ʼẇ ʼéle֖y⁠ká lĕ⁠hֽaẖàyֽwòţ׃"],[6,21,"וְ⁠אַתָּ֣ה קַח־לְ⁠ךָ֗ מִ⁠כָּל־מַֽאֲכָל֙ אֲשֶׁ֣ר יֵֽאָכֵ֔ל וְ⁠אָסַפְתָּ֖ אֵלֶ֑י⁠ךָ וְ⁠הָיָ֥ה לְ⁠ךָ֛ וְ⁠לָ⁠הֶ֖ם לְ⁠אָכְלָֽה׃","wĕ⁠ʼaţá֣̇h qaẖ-lĕ⁠ká֗ mi⁠ká̇l-mֽaʼàkál֙ ʼàşě֣r yֽéʼáké֔l wĕ⁠ʼásapĕţá֖̇ ʼéle֑y⁠ká wĕ⁠háyá֥h lĕ⁠ká֛ wĕ⁠lá⁠he֖m lĕ⁠ʼákĕláֽh׃"],[6,22,"וַ⁠יַּ֖עַשׂ נֹ֑חַ כְּ֠⁠כֹל אֲשֶׁ֨ר צִוָּ֥ה אֹת֛⁠וֹ אֱלֹהִ֖ים כֵּ֥ן עָשָֽׂה׃ס","wa⁠yȧ֖ʻaş̂ nò֑ẖa kĕ̇֠⁠kòl ʼàşě֨r ẕiwá֥̇h ʼòţ֛⁠wò ʼèlòhi֖ym ké֥̇n ʻáşáֽ̂h׃s"],[7,1,"וַ⁠יֹּ֤אמֶר יְהוָה֙ לְ⁠נֹ֔חַ בֹּֽא־אַתָּ֥ה וְ⁠כָל־בֵּיתְ⁠ךָ֖ אֶל־הַ⁠תֵּבָ֑ה כִּֽי־אֹתְ⁠ךָ֥ רָאִ֛יתִי צַדִּ֥יק לְ⁠פָנַ֖⁠י בַּ⁠דּ֥וֹר הַ⁠זֶּֽה׃","wa⁠yò֤̇ʼmer yĕhwáh֙ lĕ⁠nò֔ẖa bòֽ̇ʼ-ʼaţá֥̇h wĕ⁠kál-bé̇yţĕ⁠ká֖ ʼel-ha⁠ţé̇bá֑h kiֽ̇y-ʼòţĕ⁠ká֥ ráʼi֛yţiy ẕadi֥̇yq lĕ⁠pána֖⁠y bȧ⁠ḋ֥wòr ha⁠zėֽh׃"],[7,2,"מִ⁠כֹּ֣ל ׀ הַ⁠בְּהֵמָ֣ה הַ⁠טְּהוֹרָ֗ה תִּֽקַּח־לְ⁠ךָ֛ שִׁבְעָ֥ה שִׁבְעָ֖ה אִ֣ישׁ וְ⁠אִשְׁתּ֑⁠וֹ וּ⁠מִן־הַ⁠בְּהֵמָ֡ה אֲ֠שֶׁר לֹ֣א טְהֹרָ֥ה הִ֛וא שְׁנַ֖יִם אִ֥ישׁ וְ⁠אִשְׁתּֽ⁠וֹ׃","mi⁠kò֣̇l ׀ ha⁠bĕ̇hémá֣h ha⁠tĕ̇hwòrá֗h ţiֽ̇qȧẖ-lĕ⁠ká֛ şǐbĕʻá֥h şǐbĕʻá֖h ʼi֣yş̌ wĕ⁠ʼişĕ̌ţ֑̇⁠wò ẇ⁠min-ha⁠bĕ̇hémá֡h ʼà֠şěr lò֣ʼ tĕhòrá֥h hi֛wʼ şĕ̌na֖yim ʼi֥yş̌ wĕ⁠ʼişĕ̌ţֽ̇⁠wò׃"],[7,3,"גַּ֣ם מֵ⁠ע֧וֹף הַ⁠שָּׁמַ֛יִם שִׁבְעָ֥ה שִׁבְעָ֖ה זָכָ֣ר וּ⁠נְקֵבָ֑ה לְ⁠חַיּ֥וֹת זֶ֖רַע עַל־פְּנֵ֥י כָל־הָ⁠אָֽרֶץ׃","gȧ֣m mé⁠ʻ֧wòp ha⁠şá̇̌ma֛yim şǐbĕʻá֥h şǐbĕʻá֖h záká֣r ẇ⁠nĕqébá֑h lĕ⁠ẖaẏ֥wòţ ze֖raʻ ʻal-pĕ̇né֥y kál-há⁠ʼáֽreẕ׃"],[7,4,"כִּי֩ לְ⁠יָמִ֨ים ע֜וֹד שִׁבְעָ֗ה אָֽנֹכִי֙ מַמְטִ֣יר עַל־הָ⁠אָ֔רֶץ אַרְבָּעִ֣ים י֔וֹם וְ⁠אַרְבָּעִ֖ים לָ֑יְלָה וּ⁠מָחִ֗יתִי אֶֽת־כָּל־הַ⁠יְקוּם֙ אֲשֶׁ֣ר עָשִׂ֔יתִי מֵ⁠עַ֖ל פְּנֵ֥י הָֽ⁠אֲדָמָֽה׃","ki̇y֩ lĕ⁠yámi֨ym ʻ֜wòd şǐbĕʻá֗h ʼáֽnòkiy֙ mamĕti֣yr ʻal-há⁠ʼá֔reẕ ʼarĕbá̇ʻi֣ym y֔wòm wĕ⁠ʼarĕbá̇ʻi֖ym lá֑yĕláh ẇ⁠máẖi֗yţiy ʼeֽţ-ká̇l-ha⁠yĕqẇm֙ ʼàşě֣r ʻáşî֔yţiy mé⁠ʻa֖l pĕ̇né֥y hֽá⁠ʼàdámáֽh׃"],[7,5,"וַ⁠יַּ֖עַשׂ נֹ֑חַ כְּ⁠כֹ֥ל אֲשֶׁר־צִוָּ֖⁠הוּ יְהוָֽה׃","wa⁠yȧ֖ʻaş̂ nò֑ẖa kĕ̇⁠kò֥l ʼàşěr-ẕiwá֖̇⁠hẇ yĕhwáֽh׃"],[7,6,"וְ⁠נֹ֕חַ בֶּן־שֵׁ֥שׁ מֵא֖וֹת שָׁנָ֑ה וְ⁠הַ⁠מַּבּ֣וּל הָיָ֔ה מַ֖יִם עַל־הָ⁠אָֽרֶץ׃","wĕ⁠nò֕ẖa bėn-şé֥̌ş̌ méʼ֖wòţ şá̌ná֑h wĕ⁠ha⁠mȧḃ֣ẇl háyá֔h ma֖yim ʻal-há⁠ʼáֽreẕ׃"],[7,7,"וַ⁠יָּ֣בֹא נֹ֗חַ וּ֠⁠בָנָי⁠ו וְ⁠אִשְׁתּ֧⁠וֹ וּ⁠נְשֵֽׁי־בָנָ֛י⁠ו אִתּ֖⁠וֹ אֶל־הַ⁠תֵּבָ֑ה מִ⁠פְּנֵ֖י מֵ֥י הַ⁠מַּבּֽוּל׃","wa⁠yá֣̇bòʼ nò֗ẖa ẇ֠⁠bánáy⁠w wĕ⁠ʼişĕ̌ţ֧̇⁠wò ẇ⁠nĕşéֽ̌y-báná֛y⁠w ʼiţ֖̇⁠wò ʼel-ha⁠ţé̇bá֑h mi⁠pĕ̇né֖y mé֥y ha⁠mȧḃֽẇl׃"],[7,8,"מִן־הַ⁠בְּהֵמָה֙ הַ⁠טְּהוֹרָ֔ה וּ⁠מִן־הַ֨⁠בְּהֵמָ֔ה אֲשֶׁ֥ר אֵינֶ֖נָּ⁠ה טְהֹרָ֑ה וּ⁠מִ֨ן־הָ⁠ע֔וֹף וְ⁠כֹ֥ל אֲשֶׁר־רֹמֵ֖שׂ עַל־הָֽ⁠אֲדָמָֽה׃","min-ha⁠bĕ̇hémáh֙ ha⁠tĕ̇hwòrá֔h ẇ⁠min-ha֨⁠bĕ̇hémá֔h ʼàşě֥r ʼéyne֖ná̇⁠h tĕhòrá֑h ẇ⁠mi֨n-há⁠ʻ֔wòp wĕ⁠kò֥l ʼàşěr-ròmé֖ş̂ ʻal-háֽ⁠ʼàdámáֽh׃"],[7,9,"שְׁנַ֨יִם שְׁנַ֜יִם בָּ֧אוּ אֶל־נֹ֛חַ אֶל־הַ⁠תֵּבָ֖ה זָכָ֣ר וּ⁠נְקֵבָ֑ה כַּֽ⁠אֲשֶׁ֛ר צִוָּ֥ה אֱלֹהִ֖ים אֶת־נֹֽחַ׃","şĕ̌na֨yim şĕ̌na֜yim bá֧̇ʼẇ ʼel-nò֛ẖa ʼel-ha⁠ţé̇bá֖h záká֣r ẇ⁠nĕqébá֑h kֽ̇a⁠ʼàşě֛r ẕiwá֥̇h ʼèlòhi֖ym ʼeţ-nòֽẖa׃"],[7,10,"וַֽ⁠יְהִ֖י לְ⁠שִׁבְעַ֣ת הַ⁠יָּמִ֑ים וּ⁠מֵ֣י הַ⁠מַּבּ֔וּל הָי֖וּ עַל־הָ⁠אָֽרֶץ׃","wֽa⁠yĕhi֖y lĕ⁠şǐbĕʻa֣ţ ha⁠yá̇mi֑ym ẇ⁠mé֣y ha⁠mȧḃ֔ẇl háy֖ẇ ʻal-há⁠ʼáֽreẕ׃"],[7,11,"בִּ⁠שְׁנַ֨ת שֵׁשׁ־מֵא֤וֹת שָׁנָה֙ לְ⁠חַיֵּי־נֹ֔חַ בַּ⁠חֹ֨דֶשׁ֙ הַ⁠שֵּׁנִ֔י בְּ⁠שִׁבְעָֽה־עָשָׂ֥ר י֖וֹם לַ⁠חֹ֑דֶשׁ בַּ⁠יּ֣וֹם הַ⁠זֶּ֗ה נִבְקְעוּ֙ כָּֽל־מַעְיְנֹת֙ תְּה֣וֹם רַבָּ֔ה וַ⁠אֲרֻבֹּ֥ת הַ⁠שָּׁמַ֖יִם נִפְתָּֽחוּ׃","bi̇⁠şĕ̌na֨ţ şé̌ş̌-méʼ֤wòţ şá̌náh֙ lĕ⁠ẖayé̇y-nò֔ẖa bȧ⁠ẖò֨deş̌֙ ha⁠şé̇̌ni֔y bĕ̇⁠şǐbĕʻáֽh-ʻáşá֥̂r y֖wòm la⁠ẖò֑deş̌ bȧ⁠ẏ֣wòm ha⁠zė֗h nibĕqĕʻẇ֙ káֽ̇l-maʻĕyĕnòţ֙ ţĕ̇h֣wòm rabá̇֔h wa⁠ʼàrubò֥̇ţ ha⁠şá̇̌ma֖yim nipĕţáֽ̇ẖẇ׃"],[7,12,"וַֽ⁠יְהִ֥י הַ⁠גֶּ֖שֶׁם עַל־הָ⁠אָ֑רֶץ אַרְבָּעִ֣ים י֔וֹם וְ⁠אַרְבָּעִ֖ים לָֽיְלָה׃","wֽa⁠yĕhi֥y ha⁠gė֖şěm ʻal-há⁠ʼá֑reẕ ʼarĕbá̇ʻi֣ym y֔wòm wĕ⁠ʼarĕbá̇ʻi֖ym láֽyĕláh׃"],[7,13,"בְּ⁠עֶ֨צֶם הַ⁠יּ֤וֹם הַ⁠זֶּה֙ בָּ֣א נֹ֔חַ וְ⁠שֵׁם־וְ⁠חָ֥ם וָ⁠יֶ֖פֶת בְּנֵי־נֹ֑חַ וְ⁠אֵ֣שֶׁת נֹ֗חַ וּ⁠שְׁלֹ֧שֶׁת נְשֵֽׁי־בָנָ֛י⁠ו אִתָּ֖⁠ם אֶל־הַ⁠תֵּבָֽה׃","bĕ̇⁠ʻe֨ẕem ha⁠ẏ֤wòm ha⁠zėh֙ bá֣̇ʼ nò֔ẖa wĕ⁠şé̌m-wĕ⁠ẖá֥m wá⁠ye֖peţ bĕ̇néy-nò֑ẖa wĕ⁠ʼé֣şěţ nò֗ẖa ẇ⁠şĕ̌lò֧şěţ nĕşéֽ̌y-báná֛y⁠w ʼiţá֖̇⁠m ʼel-ha⁠ţé̇báֽh׃"],[7,14,"הֵ֜מָּה וְ⁠כָל־הַֽ⁠חַיָּ֣ה לְ⁠מִינָ֗⁠הּ וְ⁠כָל־הַ⁠בְּהֵמָה֙ לְ⁠מִינָ֔⁠הּ וְ⁠כָל־הָ⁠רֶ֛מֶשׂ הָ⁠רֹמֵ֥שׂ עַל־הָ⁠אָ֖רֶץ לְ⁠מִינֵ֑⁠הוּ וְ⁠כָל־הָ⁠ע֣וֹף לְ⁠מִינֵ֔⁠הוּ כֹּ֖ל צִפּ֥וֹר כָּל־כָּנָֽף׃","hé֜má̇h wĕ⁠kál-hֽa⁠ẖayá֣̇h lĕ⁠miyná֗⁠ḣ wĕ⁠kál-ha⁠bĕ̇hémáh֙ lĕ⁠miyná֔⁠ḣ wĕ⁠kál-há⁠re֛meş̂ há⁠ròmé֥ş̂ ʻal-há⁠ʼá֖reẕ lĕ⁠miyné֑⁠hẇ wĕ⁠kál-há⁠ʻ֣wòp lĕ⁠miyné֔⁠hẇ kò֖̇l ẕiṗ֥wòr ká̇l-ká̇náֽp׃"],[7,15,"וַ⁠יָּבֹ֥אוּ אֶל־נֹ֖חַ אֶל־הַ⁠תֵּבָ֑ה שְׁנַ֤יִם שְׁנַ֨יִם֙ מִ⁠כָּל־הַ⁠בָּשָׂ֔ר אֲשֶׁר־בּ֖⁠וֹ ר֥וּחַ חַיִּֽים׃","wa⁠yá̇bò֥ʼẇ ʼel-nò֖ẖa ʼel-ha⁠ţé̇bá֑h şĕ̌na֤yim şĕ̌na֨yim֙ mi⁠ká̇l-ha⁠bá̇şá̂֔r ʼàşěr-ḃ֖⁠wò r֥ẇẖa ẖayiֽ̇ym׃"],[7,16,"וְ⁠הַ⁠בָּאִ֗ים זָכָ֨ר וּ⁠נְקֵבָ֤ה מִ⁠כָּל־בָּשָׂר֙ בָּ֔אוּ כַּֽ⁠אֲשֶׁ֛ר צִוָּ֥ה אֹת֖⁠וֹ אֱלֹהִ֑ים וַ⁠יִּסְגֹּ֥ר יְהוָ֖ה בַּֽעֲדֽ⁠וֹ׃","wĕ⁠ha⁠bá̇ʼi֗ym záká֨r ẇ⁠nĕqébá֤h mi⁠ká̇l-bá̇şá̂r֙ bá̇֔ʼẇ kֽ̇a⁠ʼàşě֛r ẕiwá֥̇h ʼòţ֖⁠wò ʼèlòhi֑ym wa⁠yi̇sĕgò֥̇r yĕhwá֖h ḃֽaʻàdֽ⁠wò׃"],[7,17,"וַֽ⁠יְהִ֧י הַ⁠מַּבּ֛וּל אַרְבָּעִ֥ים י֖וֹם עַל־הָ⁠אָ֑רֶץ וַ⁠יִּרְבּ֣וּ הַ⁠מַּ֗יִם וַ⁠יִּשְׂאוּ֙ אֶת־הַ⁠תֵּבָ֔ה וַ⁠תָּ֖רָם מֵ⁠עַ֥ל הָ⁠אָֽרֶץ׃","wֽa⁠yĕhi֧y ha⁠mȧḃ֛ẇl ʼarĕbá̇ʻi֥ym y֖wòm ʻal-há⁠ʼá֑reẕ wa⁠yi̇rĕḃ֣ẇ ha⁠mȧ֗yim wa⁠yi̇şĕ̂ʼẇ֙ ʼeţ-ha⁠ţé̇bá֔h wa⁠ţá֖̇rám mé⁠ʻa֥l há⁠ʼáֽreẕ׃"],[7,18,"וַ⁠יִּגְבְּר֥וּ הַ⁠מַּ֛יִם וַ⁠יִּרְבּ֥וּ מְאֹ֖ד עַל־הָ⁠אָ֑רֶץ וַ⁠תֵּ֥לֶךְ הַ⁠תֵּבָ֖ה עַל־פְּנֵ֥י הַ⁠מָּֽיִם׃","wa⁠yi̇gĕbĕ̇r֥ẇ ha⁠mȧ֛yim wa⁠yi̇rĕḃ֥ẇ mĕʼò֖d ʻal-há⁠ʼá֑reẕ wa⁠ţé֥̇lekĕ ha⁠ţé̇bá֖h ʻal-pĕ̇né֥y ha⁠máֽ̇yim׃"],[7,19,"וְ⁠הַ⁠מַּ֗יִם גָּֽבְר֛וּ מְאֹ֥ד מְאֹ֖ד עַל־הָ⁠אָ֑רֶץ וַ⁠יְכֻסּ֗וּ כָּל־הֶֽ⁠הָרִים֙ הַ⁠גְּבֹהִ֔ים אֲשֶׁר־תַּ֖חַת כָּל־הַ⁠שָּׁמָֽיִם׃","wĕ⁠ha⁠mȧ֗yim gáֽ̇bĕr֛ẇ mĕʼò֥d mĕʼò֖d ʻal-há⁠ʼá֑reẕ wa⁠yĕkuṡ֗ẇ ká̇l-hֽe⁠háriym֙ ha⁠gĕ̇bòhi֔ym ʼàşěr-ţȧ֖ẖaţ ká̇l-ha⁠şá̇̌máֽyim׃"],[7,20,"חֲמֵ֨שׁ עֶשְׂרֵ֤ה אַמָּה֙ מִ⁠לְ⁠מַ֔עְלָ⁠ה גָּבְר֖וּ הַ⁠מָּ֑יִם וַ⁠יְכֻסּ֖וּ הֶ⁠הָרִֽים׃","ẖàmé֨ş̌ ʻeşĕ̂ré֤h ʼamá̇h֙ mi⁠lĕ⁠ma֔ʻĕlá⁠h gá̇bĕr֖ẇ ha⁠má֑̇yim wa⁠yĕkuṡ֖ẇ he⁠háriֽym׃"],[7,21,"וַ⁠יִּגְוַ֞ע כָּל־בָּשָׂ֣ר ׀ הָ⁠רֹמֵ֣שׂ עַל־הָ⁠אָ֗רֶץ בָּ⁠ע֤וֹף וּ⁠בַ⁠בְּהֵמָה֙ וּ⁠בַ֣⁠חַיָּ֔ה וּ⁠בְ⁠כָל־הַ⁠שֶּׁ֖רֶץ הַ⁠שֹּׁרֵ֣ץ עַל־הָ⁠אָ֑רֶץ וְ⁠כֹ֖ל הָ⁠אָדָֽם׃","wa⁠yi̇gĕwa֞ʻ ká̇l-bá̇şá֣̂r ׀ há⁠ròmé֣ş̂ ʻal-há⁠ʼá֗reẕ bá̇⁠ʻ֤wòp ẇ⁠ba⁠bĕ̇hémáh֙ ẇ⁠ba֣⁠ẖayá̇֔h ẇ⁠bĕ⁠kál-ha⁠şė֖̌reẕ ha⁠şò̇̌ré֣ẕ ʻal-há⁠ʼá֑reẕ wĕ⁠kò֖l há⁠ʼádáֽm׃"],[7,22,"כֹּ֡ל אֲשֶׁר֩ נִשְׁמַת־ר֨וּחַ חַיִּ֜ים בְּ⁠אַפָּ֗י⁠ו מִ⁠כֹּ֛ל אֲשֶׁ֥ר בֶּ⁠חָֽרָבָ֖ה מֵֽתוּ׃","kò̇֡l ʼàşěr֩ nişĕ̌maţ-r֨ẇẖa ẖayi̇֜ym bĕ̇⁠ʼapá̇֗y⁠w mi⁠kò֛̇l ʼàşě֥r bė⁠ẖáֽrábá֖h méֽţẇ׃"],[7,23,"וַ⁠יִּ֜מַח אֶֽת־כָּל־הַ⁠יְק֣וּם ׀ אֲשֶׁ֣ר ׀ עַל־פְּנֵ֣י הָֽ⁠אֲדָמָ֗ה מֵ⁠אָדָ֤ם עַד־בְּהֵמָה֙ עַד־רֶ֨מֶשׂ֙ וְ⁠עַד־ע֣וֹף הַ⁠שָּׁמַ֔יִם וַ⁠יִּמָּח֖וּ מִן־הָ⁠אָ֑רֶץ וַ⁠יִשָּׁ֧אֶר אַךְ־נֹ֛חַ וַֽ⁠אֲשֶׁ֥ר אִתּ֖⁠וֹ בַּ⁠תֵּבָֽה׃","wa⁠yi̇֜maẖ ʼeֽţ-ká̇l-ha⁠yĕq֣ẇm ׀ ʼàşě֣r ׀ ʻal-pĕ̇né֣y hֽá⁠ʼàdámá֗h mé⁠ʼádá֤m ʻad-bĕ̇hémáh֙ ʻad-re֨meş̂֙ wĕ⁠ʻad-ʻ֣wòp ha⁠şá̇̌ma֔yim wa⁠yi̇má̇ẖ֖ẇ min-há⁠ʼá֑reẕ wa⁠yişá֧̇̌ʼer ʼakĕ-nò֛ẖa wֽa⁠ʼàşě֥r ʼiţ֖̇⁠wò bȧ⁠ţé̇báֽh׃"],[7,24,"וַ⁠יִּגְבְּר֥וּ הַ⁠מַּ֖יִם עַל־הָ⁠אָ֑רֶץ חֲמִשִּׁ֥ים וּ⁠מְאַ֖ת יֽוֹם׃","wa⁠yi̇gĕbĕ̇r֥ẇ ha⁠mȧ֖yim ʻal-há⁠ʼá֑reẕ ẖàmişi֥̇̌ym ẇ⁠mĕʼa֖ţ yֽwòm׃"],[8,1,"וַ⁠יִּזְכֹּ֤ר אֱלֹהִים֙ אֶת־נֹ֔חַ וְ⁠אֵ֤ת כָּל־הַֽ⁠חַיָּה֙ וְ⁠אֶת־כָּל־הַ⁠בְּהֵמָ֔ה אֲשֶׁ֥ר אִתּ֖⁠וֹ בַּ⁠תֵּבָ֑ה וַ⁠יַּעֲבֵ֨ר אֱלֹהִ֥ים ר֨וּחַ֙ עַל־הָ⁠אָ֔רֶץ וַ⁠יָּשֹׁ֖כּוּ הַ⁠מָּֽיִם׃","wa⁠yi̇zĕkò֤̇r ʼèlòhiym֙ ʼeţ-nò֔ẖa wĕ⁠ʼé֤ţ ká̇l-hֽa⁠ẖayá̇h֙ wĕ⁠ʼeţ-ká̇l-ha⁠bĕ̇hémá֔h ʼàşě֥r ʼiţ֖̇⁠wò bȧ⁠ţé̇bá֑h wa⁠yȧʻàbé֨r ʼèlòhi֥ym r֨ẇẖa֙ ʻal-há⁠ʼá֔reẕ wa⁠yá̇şò֖̌k̇ẇ ha⁠máֽ̇yim׃"],[8,2,"וַ⁠יִּסָּֽכְרוּ֙ מַעְיְנֹ֣ת תְּה֔וֹם וַֽ⁠אֲרֻבֹּ֖ת הַ⁠שָּׁמָ֑יִם וַ⁠יִּכָּלֵ֥א הַ⁠גֶּ֖שֶׁם מִן־הַ⁠שָּׁמָֽיִם׃","wa⁠yi̇sáֽ̇kĕrẇ֙ maʻĕyĕnò֣ţ ţĕ̇h֔wòm wֽa⁠ʼàrubò֖̇ţ ha⁠şá̇̌má֑yim wa⁠yi̇ká̇lé֥ʼ ha⁠gė֖şěm min-ha⁠şá̇̌máֽyim׃"],[8,3,"וַ⁠יָּשֻׁ֧בוּ הַ⁠מַּ֛יִם מֵ⁠עַ֥ל הָ⁠אָ֖רֶץ הָל֣וֹךְ וָ⁠שׁ֑וֹב וַ⁠יַּחְסְר֣וּ הַ⁠מַּ֔יִם מִ⁠קְצֵ֕ה חֲמִשִּׁ֥ים וּ⁠מְאַ֖ת יֽוֹם׃","wa⁠yá̇şǔ֧bẇ ha⁠mȧ֛yim mé⁠ʻa֥l há⁠ʼá֖reẕ hál֣wòkĕ wá⁠ş֑̌wòb wa⁠yȧẖĕsĕr֣ẇ ha⁠mȧ֔yim mi⁠qĕẕé֕h ẖàmişi֥̇̌ym ẇ⁠mĕʼa֖ţ yֽwòm׃"],[8,4,"וַ⁠תָּ֤נַח הַ⁠תֵּבָה֙ בַּ⁠חֹ֣דֶשׁ הַ⁠שְּׁבִיעִ֔י בְּ⁠שִׁבְעָה־עָשָׂ֥ר י֖וֹם לַ⁠חֹ֑דֶשׁ עַ֖ל הָרֵ֥י אֲרָרָֽט׃","wa⁠ţá֤̇naẖ ha⁠ţé̇báh֙ bȧ⁠ẖò֣deş̌ ha⁠şĕ̇̌biyʻi֔y bĕ̇⁠şǐbĕʻáh-ʻáşá֥̂r y֖wòm la⁠ẖò֑deş̌ ʻa֖l háré֥y ʼàráráֽt׃"],[8,5,"וְ⁠הַ⁠מַּ֗יִם הָיוּ֙ הָל֣וֹךְ וְ⁠חָס֔וֹר עַ֖ד הַ⁠חֹ֣דֶשׁ הָֽ⁠עֲשִׂירִ֑י בָּֽ⁠עֲשִׂירִי֙ בְּ⁠אֶחָ֣ד לַ⁠חֹ֔דֶשׁ נִרְא֖וּ רָאשֵׁ֥י הֶֽ⁠הָרִֽים׃","wĕ⁠ha⁠mȧ֗yim háyẇ֙ hál֣wòkĕ wĕ⁠ẖás֔wòr ʻa֖d ha⁠ẖò֣deş̌ hֽá⁠ʻàşîyri֑y ḃֽá⁠ʻàşîyriy֙ bĕ̇⁠ʼeẖá֣d la⁠ẖò֔deş̌ nirĕʼ֖ẇ ráʼşé֥̌y hֽe⁠háriֽym׃"],[8,6,"וַֽ⁠יְהִ֕י מִ⁠קֵּ֖ץ אַרְבָּעִ֣ים י֑וֹם וַ⁠יִּפְתַּ֣ח נֹ֔חַ אֶת־חַלּ֥וֹן הַ⁠תֵּבָ֖ה אֲשֶׁ֥ר עָשָֽׂה׃","wֽa⁠yĕhi֕y mi⁠qé֖̇ẕ ʼarĕbá̇ʻi֣ym y֑wòm wa⁠yi̇pĕţȧ֣ẖ nò֔ẖa ʼeţ-ẖal֥̇wòn ha⁠ţé̇bá֖h ʼàşě֥r ʻáşáֽ̂h׃"],[8,7,"וַ⁠יְשַׁלַּ֖ח אֶת־הָֽ⁠עֹרֵ֑ב וַ⁠יֵּצֵ֤א יָצוֹא֙ וָ⁠שׁ֔וֹב עַד־יְבֹ֥שֶׁת הַ⁠מַּ֖יִם מֵ⁠עַ֥ל הָ⁠אָֽרֶץ׃","wa⁠yĕşǎlȧ֖ẖ ʼeţ-hֽá⁠ʻòré֑b wa⁠yé̇ẕé֤ʼ yáẕwòʼ֙ wá⁠ş̌֔wòb ʻad-yĕbò֥şěţ ha⁠mȧ֖yim mé⁠ʻa֥l há⁠ʼáֽreẕ׃"],[8,8,"וַ⁠יְשַׁלַּ֥ח אֶת־הַ⁠יּוֹנָ֖ה מֵ⁠אִתּ֑⁠וֹ לִ⁠רְאוֹת֙ הֲ⁠קַ֣לּוּ הַ⁠מַּ֔יִם מֵ⁠עַ֖ל פְּנֵ֥י הָֽ⁠אֲדָמָֽה׃","wa⁠yĕşǎlȧ֥ẖ ʼeţ-ha⁠ẏwòná֖h mé⁠ʼiţ֑̇⁠wò li⁠rĕʼwòţ֙ hà⁠qa֣l̇ẇ ha⁠mȧ֔yim mé⁠ʻa֖l pĕ̇né֥y hֽá⁠ʼàdámáֽh׃"],[8,9,"וְ⁠לֹֽא־מָצְאָה֩ הַ⁠יּוֹנָ֨ה מָנ֜וֹחַ לְ⁠כַף־רַגְלָ֗⁠הּ וַ⁠תָּ֤שָׁב אֵלָי⁠ו֙ אֶל־הַ⁠תֵּבָ֔ה כִּי־מַ֖יִם עַל־פְּנֵ֣י כָל־הָ⁠אָ֑רֶץ וַ⁠יִּשְׁלַ֤ח יָד⁠וֹ֙ וַ⁠יִּקָּחֶ֔⁠הָ וַ⁠יָּבֵ֥א אֹתָ֛⁠הּ אֵלָ֖י⁠ו אֶל־הַ⁠תֵּבָֽה׃","wĕ⁠lòֽʼ-máẕĕʼáh֩ ha⁠ẏwòná֨h mán֜wòẖa lĕ⁠kap-ragĕlá֗⁠ḣ wa⁠ţá֤̇şá̌b ʼéláy⁠w֙ ʼel-ha⁠ţé̇bá֔h ki̇y-ma֖yim ʻal-pĕ̇né֣y kál-há⁠ʼá֑reẕ wa⁠yi̇şĕ̌la֤ẖ yád⁠wò֙ wa⁠yi̇qá̇ẖe֔⁠há wa⁠yá̇bé֥ʼ ʼòţá֛⁠ḣ ʼélá֖y⁠w ʼel-ha⁠ţé̇báֽh׃"],[8,10,"וַ⁠יָּ֣חֶל ע֔וֹד שִׁבְעַ֥ת יָמִ֖ים אֲחֵרִ֑ים וַ⁠יֹּ֛סֶף שַׁלַּ֥ח אֶת־הַ⁠יּוֹנָ֖ה מִן־הַ⁠תֵּבָֽה׃","wa⁠yá֣̇ẖel ʻ֔wòd şǐbĕʻa֥ţ yámi֖ym ʼàẖéri֑ym wa⁠yò֛̇sep şǎlȧ֥ẖ ʼeţ-ha⁠ẏwòná֖h min-ha⁠ţé̇báֽh׃"],[8,11,"וַ⁠תָּבֹ֨א אֵלָ֤י⁠ו הַ⁠יּוֹנָה֙ לְ⁠עֵ֣ת עֶ֔רֶב וְ⁠הִנֵּ֥ה עֲלֵה־זַ֖יִת טָרָ֣ף בְּ⁠פִ֑י⁠הָ וַ⁠יֵּ֣דַע נֹ֔חַ כִּי־קַ֥לּוּ הַ⁠מַּ֖יִם מֵ⁠עַ֥ל הָ⁠אָֽרֶץ׃","wa⁠ţá̇bò֨ʼ ʼélá֤y⁠w ha⁠ẏwònáh֙ lĕ⁠ʻé֣ţ ʻe֔reb wĕ⁠hiné֥̇h ʻàléh-za֖yiţ tárá֣p bĕ̇⁠pi֑y⁠há wa⁠yé֣̇daʻ nò֔ẖa ki̇y-qa֥l̇ẇ ha⁠mȧ֖yim mé⁠ʻa֥l há⁠ʼáֽreẕ׃"],[8,12,"וַ⁠יִּיָּ֣חֶל ע֔וֹד שִׁבְעַ֥ת יָמִ֖ים אֲחֵרִ֑ים וַ⁠יְשַׁלַּח֙ אֶת־הַ⁠יּוֹנָ֔ה וְ⁠לֹֽא־יָסְפָ֥ה שׁוּב־אֵלָ֖י⁠ו עֽוֹד׃","wa⁠yi̇yá֣̇ẖel ʻ֔wòd şǐbĕʻa֥ţ yámi֖ym ʼàẖéri֑ym wa⁠yĕşǎlȧẖ֙ ʼeţ-ha⁠ẏwòná֔h wĕ⁠lòֽʼ-yásĕpá֥h ş̌ẇb-ʼélá֖y⁠w ʻֽwòd׃"],[8,13,"וַֽ֠⁠יְהִי בְּ⁠אַחַ֨ת וְ⁠שֵׁשׁ־מֵא֜וֹת שָׁנָ֗ה בָּֽ⁠רִאשׁוֹן֙ בְּ⁠אֶחָ֣ד לַ⁠חֹ֔דֶשׁ חָֽרְב֥וּ הַ⁠מַּ֖יִם מֵ⁠עַ֣ל הָ⁠אָ֑רֶץ וַ⁠יָּ֤סַר נֹ֨חַ֙ אֶת־מִכְסֵ֣ה הַ⁠תֵּבָ֔ה וַ⁠יַּ֕רְא וְ⁠הִנֵּ֥ה חָֽרְב֖וּ פְּנֵ֥י הָֽ⁠אֲדָמָֽה׃","wֽa֠⁠yĕhiy bĕ̇⁠ʼaẖa֨ţ wĕ⁠şé̌ş̌-méʼ֜wòţ şá̌ná֗h ḃֽá⁠riʼş̌wòn֙ bĕ̇⁠ʼeẖá֣d la⁠ẖò֔deş̌ ẖáֽrĕb֥ẇ ha⁠mȧ֖yim mé⁠ʻa֣l há⁠ʼá֑reẕ wa⁠yá֤̇sar nò֨ẖa֙ ʼeţ-mikĕsé֣h ha⁠ţé̇bá֔h wa⁠yȧ֕rĕʼ wĕ⁠hiné֥̇h ẖֽárĕb֖ẇ pĕ̇né֥y hֽá⁠ʼàdámáֽh׃"],[8,14,"וּ⁠בַ⁠חֹ֨דֶשׁ֙ הַ⁠שֵּׁנִ֔י בְּ⁠שִׁבְעָ֧ה וְ⁠עֶשְׂרִ֛ים י֖וֹם לַ⁠חֹ֑דֶשׁ יָבְשָׁ֖ה הָ⁠אָֽרֶץ׃ס","ẇ⁠ba⁠ẖò֨deş̌֙ ha⁠şé̇̌ni֔y bĕ̇⁠şǐbĕʻá֧h wĕ⁠ʻeşĕ̂ri֛ym y֖wòm la⁠ẖò֑deş̌ yábĕşá֖̌h há⁠ʼáֽreẕ׃s"],[8,15,"וַ⁠יְדַבֵּ֥ר אֱלֹהִ֖ים אֶל־נֹ֥חַ לֵ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r ʼèlòhi֖ym ʼel-nò֥ẖa lé⁠ʼmòֽr׃"],[8,16,"צֵ֖א מִן־הַ⁠תֵּבָ֑ה אַתָּ֕ה וְ⁠אִשְׁתְּ⁠ךָ֛ וּ⁠בָנֶ֥י⁠ךָ וּ⁠נְשֵֽׁי־בָנֶ֖י⁠ךָ אִתָּֽ⁠ךְ׃","ẕé֖ʼ min-ha⁠ţé̇bá֑h ʼaţá̇֕h wĕ⁠ʼişĕ̌ţĕ̇⁠ká֛ ẇ⁠báne֥y⁠ká ẇ⁠nĕşéֽ̌y-báne֖y⁠ká ʼiţáֽ̇⁠kĕ׃"],[8,17,"כָּל־הַ⁠חַיָּ֨ה אֲשֶֽׁר־אִתְּ⁠ךָ֜ מִ⁠כָּל־בָּשָׂ֗ר בָּ⁠ע֧וֹף וּ⁠בַ⁠בְּהֵמָ֛ה וּ⁠בְ⁠כָל־הָ⁠רֶ֛מֶשׂ הָ⁠רֹמֵ֥שׂ עַל־הָ⁠אָ֖רֶץ הוצא אִתָּ֑⁠ךְ וְ⁠שָֽׁרְצ֣וּ בָ⁠אָ֔רֶץ וּ⁠פָר֥וּ וְ⁠רָב֖וּ עַל־הָ⁠אָֽרֶץ׃","ká̇l-ha⁠ẖayá̇֨h ʼàşěֽr-ʼiţĕ̇⁠ká֜ mi⁠ká̇l-bá̇şá̂֗r bá̇⁠ʻ֧wòp ẇ⁠ba⁠bĕ̇hémá֛h ẇ⁠bĕ⁠kál-há⁠re֛meş̂ há⁠ròmé֥ş̂ ʻal-há⁠ʼá֖reẕ hwẕʼ ʼiţá֑̇⁠kĕ wĕ⁠şֽ̌árĕẕ֣ẇ bá⁠ʼá֔reẕ ẇ⁠pár֥ẇ wĕ⁠ráb֖ẇ ʻal-há⁠ʼáֽreẕ׃"],[8,18,"וַ⁠יֵּ֖צֵא־נֹ֑חַ וּ⁠בָנָ֛י⁠ו וְ⁠אִשְׁתּ֥⁠וֹ וּ⁠נְשֵֽׁי־בָנָ֖י⁠ו אִתּֽ⁠וֹ׃","wa⁠yé֖̇ẕéʼ-nò֑ẖa ẇ⁠báná֛y⁠w wĕ⁠ʼişĕ̌ţ֥̇⁠wò ẇ⁠nĕşéֽ̌y-báná֖y⁠w ʼiţֽ̇⁠wò׃"],[8,19,"כָּל־הַֽ⁠חַיָּ֗ה כָּל־הָ⁠רֶ֨מֶשׂ֙ וְ⁠כָל־הָ⁠ע֔וֹף כֹּ֖ל רוֹמֵ֣שׂ עַל־הָ⁠אָ֑רֶץ לְ⁠מִשְׁפְּחֹ֣תֵי⁠הֶ֔ם יָצְא֖וּ מִן־הַ⁠תֵּבָֽה׃","ká̇l-hֽa⁠ẖayá̇֗h ká̇l-há⁠re֨meş̂֙ wĕ⁠kál-há⁠ʻ֔wòp kò֖̇l rwòmé֣ş̂ ʻal-há⁠ʼá֑reẕ lĕ⁠mişĕ̌pĕ̇ẖò֣ţéy⁠he֔m yáẕĕʼ֖ẇ min-ha⁠ţé̇báֽh׃"],[8,20,"וַ⁠יִּ֥בֶן נֹ֛חַ מִזְבֵּ֖חַ לַֽ⁠יהוָ֑ה וַ⁠יִּקַּ֞ח מִ⁠כֹּ֣ל ׀ הַ⁠בְּהֵמָ֣ה הַ⁠טְּהוֹרָ֗ה וּ⁠מִ⁠כֹּל֙ הָ⁠ע֣וֹף הַ⁠טָּהֹ֔ר וַ⁠יַּ֥עַל עֹלֹ֖ת בַּ⁠מִּזְבֵּֽחַ׃","wa⁠yi֥̇ben nò֛ẖa mizĕbé֖̇ẖa lֽa⁠yhwá֑h wa⁠yi̇qȧ֞ẖ mi⁠kò֣̇l ׀ ha⁠bĕ̇hémá֣h ha⁠tĕ̇hwòrá֗h ẇ⁠mi⁠kò̇l֙ há⁠ʻ֣wòp ha⁠tá̇hò֔r wa⁠yȧ֥ʻal ʻòlò֖ţ bȧ⁠mi̇zĕbéֽ̇ẖa׃"],[8,21,"וַ⁠יָּ֣רַח יְהוָה֮ אֶת־רֵ֣יחַ הַ⁠נִּיחֹחַ֒ וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־לִבּ֗⁠וֹ לֹֽא־אֹ֠סִף לְ⁠קַלֵּ֨ל ע֤וֹד אֶת־הָֽ⁠אֲדָמָה֙ בַּ⁠עֲב֣וּר הָֽ⁠אָדָ֔ם כִּ֠י יֵ֣צֶר לֵ֧ב הָ⁠אָדָ֛ם רַ֖ע מִ⁠נְּעֻרָ֑י⁠ו וְ⁠לֹֽא־אֹסִ֥ף ע֛וֹד לְ⁠הַכּ֥וֹת אֶת־כָּל־חַ֖י כַּֽ⁠אֲשֶׁ֥ר עָשִֽׂיתִי׃","wa⁠yá֣̇raẖ yĕhwáh֮ ʼeţ-ré֣yẖa ha⁠ni̇yẖòẖa֒ wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-liḃ֗⁠wò lòֽʼ-ʼò֠sip lĕ⁠qalé̇֨l ʻ֤wòd ʼeţ-háֽ⁠ʼàdámáh֙ bȧ⁠ʻàb֣ẇr hֽá⁠ʼádá֔m ki̇֠y yé֣ẕer lé֧b há⁠ʼádá֛m ra֖ʻ mi⁠nĕ̇ʻurá֑y⁠w wĕ⁠lòֽʼ-ʼòsi֥p ʻ֛wòd lĕ⁠hak֥̇wòţ ʼeţ-ká̇l-ẖa֖y kֽ̇a⁠ʼàşě֥r ʻáşîֽyţiy׃"],[8,22,"עֹ֖ד כָּל־יְמֵ֣י הָ⁠אָ֑רֶץ זֶ֡רַע וְ֠⁠קָצִיר וְ⁠קֹ֨ר וָ⁠חֹ֜ם וְ⁠קַ֧יִץ וָ⁠חֹ֛רֶף וְ⁠י֥וֹם וָ⁠לַ֖יְלָה לֹ֥א יִשְׁבֹּֽתוּ׃","ʻò֖d ká̇l-yĕmé֣y há⁠ʼá֑reẕ ze֡raʻ wĕ֠⁠qáẕiyr wĕ⁠qò֨r wá⁠ẖò֜m wĕ⁠qa֧yiẕ wá⁠ẖò֛rep wĕ⁠y֥wòm wá⁠la֖yĕláh lò֥ʼ yişĕ̌bòֽ̇ţẇ׃"],[9,1,"וַ⁠יְבָ֣רֶךְ אֱלֹהִ֔ים אֶת־נֹ֖חַ וְ⁠אֶת־בָּנָ֑י⁠ו וַ⁠יֹּ֧אמֶר לָ⁠הֶ֛ם פְּר֥וּ וּ⁠רְב֖וּ וּ⁠מִלְא֥וּ אֶת־הָ⁠אָֽרֶץ׃","wa⁠yĕbá֣rekĕ ʼèlòhi֔ym ʼeţ-nò֖ẖa wĕ⁠ʼeţ-bá̇ná֑y⁠w wa⁠yò֧̇ʼmer lá⁠he֛m pĕ̇r֥ẇ ẇ⁠rĕb֖ẇ ẇ⁠milĕʼ֥ẇ ʼeţ-há⁠ʼáֽreẕ׃"],[9,2,"וּ⁠מוֹרַאֲ⁠כֶ֤ם וְ⁠חִתְּ⁠כֶם֙ יִֽהְיֶ֔ה עַ֚ל כָּל־חַיַּ֣ת הָ⁠אָ֔רֶץ וְ⁠עַ֖ל כָּל־ע֣וֹף הַ⁠שָּׁמָ֑יִם בְּ⁠כֹל֩ אֲשֶׁ֨ר תִּרְמֹ֧שׂ הָֽ⁠אֲדָמָ֛ה וּֽ⁠בְ⁠כָל־דְּגֵ֥י הַ⁠יָּ֖ם בְּ⁠יֶדְ⁠כֶ֥ם נִתָּֽנוּ׃","ẇ⁠mwòraʼà⁠ke֤m wĕ⁠ẖiţĕ̇⁠kem֙ yiֽhĕye֔h ʻa֚l ká̇l-ẖayȧ֣ţ há⁠ʼá֔reẕ wĕ⁠ʻa֖l ká̇l-ʻ֣wòp ha⁠şá̇̌má֑yim bĕ̇⁠kòl֩ ʼàşě֨r ţi̇rĕmò֧ş̂ hֽá⁠ʼàdámá֛h ẇֽ⁠bĕ⁠kál-dĕ̇gé֥y ha⁠yá֖̇m bĕ̇⁠yedĕ⁠ke֥m niţáֽ̇nẇ׃"],[9,3,"כָּל־רֶ֨מֶשׂ֙ אֲשֶׁ֣ר הוּא־חַ֔י לָ⁠כֶ֥ם יִהְיֶ֖ה לְ⁠אָכְלָ֑ה כְּ⁠יֶ֣רֶק עֵ֔שֶׂב נָתַ֥תִּי לָ⁠כֶ֖ם אֶת־כֹּֽל׃","ká̇l-re֨meş̂֙ ʼàşě֣r hẇʼ-ẖa֔y lá⁠ke֥m yihĕye֖h lĕ⁠ʼákĕlá֑h kĕ̇⁠ye֣req ʻé֔şêb náţa֥ţi̇y lá⁠ke֖m ʼeţ-kòֽ̇l׃"],[9,4,"אַךְ־בָּשָׂ֕ר בְּ⁠נַפְשׁ֥⁠וֹ דָמ֖⁠וֹ לֹ֥א תֹאכֵֽלוּ׃","ʼakĕ-bá̇şá̂֕r bĕ̇⁠napĕş֥̌⁠wò dám֖⁠wò lò֥ʼ ţòʼkéֽlẇ׃"],[9,5,"וְ⁠אַ֨ךְ אֶת־דִּמְ⁠כֶ֤ם לְ⁠נַפְשֹֽׁתֵי⁠כֶם֙ אֶדְרֹ֔שׁ מִ⁠יַּ֥ד כָּל־חַיָּ֖ה אֶדְרְשֶׁ֑⁠נּוּ וּ⁠מִ⁠יַּ֣ד הָֽ⁠אָדָ֗ם מִ⁠יַּד֙ אִ֣ישׁ אָחִ֔י⁠ו אֶדְרֹ֖שׁ אֶת־נֶ֥פֶשׁ הָֽ⁠אָדָֽם׃","wĕ⁠ʼa֨kĕ ʼeţ-di̇mĕ⁠ke֤m lĕ⁠napĕşòֽ̌ţéy⁠kem֙ ʼedĕrò֔ş̌ mi⁠yȧ֥d ká̇l-ẖayá֖̇h ʼedĕrĕşě֑⁠ṅẇ ẇ⁠mi⁠yȧ֣d hֽá⁠ʼádá֗m mi⁠yȧd֙ ʼi֣yş̌ ʼáẖi֔y⁠w ʼedĕrò֖ş̌ ʼeţ-ne֥peş̌ hֽá⁠ʼádáֽm׃"],[9,6,"שֹׁפֵךְ֙ דַּ֣ם הָֽ⁠אָדָ֔ם בָּֽ⁠אָדָ֖ם דָּמ֣⁠וֹ יִשָּׁפֵ֑ךְ כִּ֚י בְּ⁠צֶ֣לֶם אֱלֹהִ֔ים עָשָׂ֖ה אֶת־הָ⁠אָדָֽם׃","şò̌pékĕ֙ dȧ֣m hֽá⁠ʼádá֔m ḃֽá⁠ʼádá֖m dá̇m֣⁠wò yişá̇̌pé֑kĕ ki֚̇y bĕ̇⁠ẕe֣lem ʼèlòhi֔ym ʻáşá֖̂h ʼeţ-há⁠ʼádáֽm׃"],[9,7,"וְ⁠אַתֶּ֖ם פְּר֣וּ וּ⁠רְב֑וּ שִׁרְצ֥וּ בָ⁠אָ֖רֶץ וּ⁠רְבוּ־בָֽ⁠הּ׃ס","wĕ⁠ʼaţė֖m pĕ̇r֣ẇ ẇ⁠rĕb֑ẇ şǐrĕẕ֥ẇ bá⁠ʼá֖reẕ ẇ⁠rĕbẇ-báֽ⁠ḣ׃s"],[9,8,"וַ⁠יֹּ֤אמֶר אֱלֹהִים֙ אֶל־נֹ֔חַ וְ⁠אֶל־בָּנָ֥י⁠ו אִתּ֖⁠וֹ לֵ⁠אמֹֽר׃","wa⁠yò֤̇ʼmer ʼèlòhiym֙ ʼel-nò֔ẖa wĕ⁠ʼel-bá̇ná֥y⁠w ʼiţ֖̇⁠wò lé⁠ʼmòֽr׃"],[9,9,"וַ⁠אֲנִ֕י הִנְנִ֥⁠י מֵקִ֛ים אֶת־בְּרִיתִ֖⁠י אִתְּ⁠כֶ֑ם וְ⁠אֶֽת־זַרְעֲ⁠כֶ֖ם אַֽחֲרֵי⁠כֶֽם׃","wa⁠ʼàni֕y hinĕni֥⁠y méqi֛ym ʼeţ-bĕ̇riyţi֖⁠y ʼiţĕ̇⁠ke֑m wĕ⁠ʼeֽţ-zarĕʻà⁠ke֖m ʼֽaẖàréy⁠keֽm׃"],[9,10,"וְ⁠אֵ֨ת כָּל־נֶ֤פֶשׁ הַֽ⁠חַיָּה֙ אֲשֶׁ֣ר אִתְּ⁠כֶ֔ם בָּ⁠ע֧וֹף בַּ⁠בְּהֵמָ֛ה וּֽ⁠בְ⁠כָל־חַיַּ֥ת הָ⁠אָ֖רֶץ אִתְּ⁠כֶ֑ם מִ⁠כֹּל֙ יֹצְאֵ֣י הַ⁠תֵּבָ֔ה לְ⁠כֹ֖ל חַיַּ֥ת הָ⁠אָֽרֶץ׃","wĕ⁠ʼé֨ţ ká̇l-ne֤peş̌ hֽa⁠ẖayá̇h֙ ʼàşě֣r ʼiţĕ̇⁠ke֔m bá̇⁠ʻ֧wòp bȧ⁠bĕ̇hémá֛h ẇֽ⁠bĕ⁠kál-ẖayȧ֥ţ há⁠ʼá֖reẕ ʼiţĕ̇⁠ke֑m mi⁠kò̇l֙ yòẕĕʼé֣y ha⁠ţé̇bá֔h lĕ⁠kò֖l ẖayȧ֥ţ há⁠ʼáֽreẕ׃"],[9,11,"וַ⁠הֲקִמֹתִ֤י אֶת־בְּרִיתִ⁠י֙ אִתְּ⁠כֶ֔ם וְ⁠לֹֽא־יִכָּרֵ֧ת כָּל־בָּשָׂ֛ר ע֖וֹד מִ⁠מֵּ֣י הַ⁠מַּבּ֑וּל וְ⁠לֹֽא־יִהְיֶ֥ה ע֛וֹד מַבּ֖וּל לְ⁠שַׁחֵ֥ת הָ⁠אָֽרֶץ׃","wa⁠hàqimòţi֤y ʼeţ-bĕ̇riyţi⁠y֙ ʼiţĕ̇⁠ke֔m wĕ⁠lòֽʼ-yiká̇ré֧ţ ká̇l-bá̇şá֛̂r ʻ֖wòd mi⁠mé֣̇y ha⁠mȧḃ֑ẇl wĕ⁠lòֽʼ-yihĕye֥h ʻ֛wòd maḃ֖ẇl lĕ⁠şǎẖé֥ţ há⁠ʼáֽreẕ׃"],[9,12,"וַ⁠יֹּ֣אמֶר אֱלֹהִ֗ים זֹ֤את אֽוֹת־הַ⁠בְּרִית֙ אֲשֶׁר־אֲנִ֣י נֹתֵ֗ן בֵּינִ⁠י֙ וּ⁠בֵ֣ינֵי⁠כֶ֔ם וּ⁠בֵ֛ין כָּל־נֶ֥פֶשׁ חַיָּ֖ה אֲשֶׁ֣ר אִתְּ⁠כֶ֑ם לְ⁠דֹרֹ֖ת עוֹלָֽם׃","wa⁠yò֣̇ʼmer ʼèlòhi֗ym zò֤ʼţ ʼֽwòţ-ha⁠bĕ̇riyţ֙ ʼàşěr-ʼàni֣y nòţé֗n bé̇yni⁠y֙ ẇ⁠bé֣ynéy⁠ke֔m ẇ⁠bé֛yn ká̇l-ne֥peş̌ ẖayá֖̇h ʼàşě֣r ʼiţĕ̇⁠ke֑m lĕ⁠dòrò֖ţ ʻwòláֽm׃"],[9,13,"אֶת־קַשְׁתִּ֕⁠י נָתַ֖תִּי בֶּֽ⁠עָנָ֑ן וְ⁠הָֽיְתָה֙ לְ⁠א֣וֹת בְּרִ֔ית בֵּינִ֖⁠י וּ⁠בֵ֥ין הָ⁠אָֽרֶץ׃","ʼeţ-qaşĕ̌ţi̇֕⁠y náţa֖ţi̇y bėֽ⁠ʻáná֑n wĕ⁠háֽyĕţáh֙ lĕ⁠ʼ֣wòţ bĕ̇ri֔yţ bé̇yni֖⁠y ẇ⁠bé֥yn há⁠ʼáֽreẕ׃"],[9,14,"וְ⁠הָיָ֕ה בְּ⁠עַֽנְנִ֥⁠י עָנָ֖ן עַל־הָ⁠אָ֑רֶץ וְ⁠נִרְאֲתָ֥ה הַ⁠קֶּ֖שֶׁת בֶּ⁠עָנָֽן׃","wĕ⁠háyá֕h bĕ̇⁠ʻֽanĕni֥⁠y ʻáná֖n ʻal-há⁠ʼá֑reẕ wĕ⁠nirĕʼàţá֥h ha⁠qė֖şěţ bė⁠ʻánáֽn׃"],[9,15,"וְ⁠זָכַרְתִּ֣י אֶת־בְּרִיתִ֗⁠י אֲשֶׁ֤ר בֵּינִ⁠י֙ וּ⁠בֵ֣ינֵי⁠כֶ֔ם וּ⁠בֵ֛ין כָּל־נֶ֥פֶשׁ חַיָּ֖ה בְּ⁠כָל־בָּשָׂ֑ר וְ⁠לֹֽא־יִֽהְיֶ֨ה ע֤וֹד הַ⁠מַּ֨יִם֙ לְ⁠מַבּ֔וּל לְ⁠שַׁחֵ֖ת כָּל־בָּשָֽׂר׃","wĕ⁠zákarĕţi֣̇y ʼeţ-bĕ̇riyţi֗⁠y ʼàşě֤r bé̇yni⁠y֙ ẇ⁠bé֣ynéy⁠ke֔m ẇ⁠bé֛yn ká̇l-ne֥peş̌ ẖayá֖̇h bĕ̇⁠kál-bá̇şá֑̂r wĕ⁠lòֽʼ-yiֽhĕye֨h ʻ֤wòd ha⁠mȧ֨yim֙ lĕ⁠maḃ֔ẇl lĕ⁠şǎẖé֖ţ ká̇l-bá̇şáֽ̂r׃"],[9,16,"וְ⁠הָיְתָ֥ה הַ⁠קֶּ֖שֶׁת בֶּֽ⁠עָנָ֑ן וּ⁠רְאִיתִ֗י⁠הָ לִ⁠זְכֹּר֙ בְּרִ֣ית עוֹלָ֔ם בֵּ֣ין אֱלֹהִ֔ים וּ⁠בֵין֙ כָּל־נֶ֣פֶשׁ חַיָּ֔ה בְּ⁠כָל־בָּשָׂ֖ר אֲשֶׁ֥ר עַל־הָ⁠אָֽרֶץ׃","wĕ⁠háyĕţá֥h ha⁠qė֖şěţ bėֽ⁠ʻáná֑n ẇ⁠rĕʼiyţi֗y⁠há li⁠zĕkò̇r֙ bĕ̇ri֣yţ ʻwòlá֔m bé֣̇yn ʼèlòhi֔ym ẇ⁠béyn֙ ká̇l-ne֣peş̌ ẖayá̇֔h bĕ̇⁠kál-bá̇şá֖̂r ʼàşě֥r ʻal-há⁠ʼáֽreẕ׃"],[9,17,"וַ⁠יֹּ֥אמֶר אֱלֹהִ֖ים אֶל־נֹ֑חַ זֹ֤את אֽוֹת־הַ⁠בְּרִית֙ אֲשֶׁ֣ר הֲקִמֹ֔תִי בֵּינִ֕⁠י וּ⁠בֵ֥ין כָּל־בָּשָׂ֖ר אֲשֶׁ֥ר עַל־הָ⁠אָֽרֶץ׃פ","wa⁠yò֥̇ʼmer ʼèlòhi֖ym ʼel-nò֑ẖa zò֤ʼţ ʼֽwòţ-ha⁠bĕ̇riyţ֙ ʼàşě֣r hàqimò֔ţiy bé̇yni֕⁠y ẇ⁠bé֥yn ká̇l-bá̇şá֖̂r ʼàşě֥r ʻal-há⁠ʼáֽreẕ׃p"],[9,18,"וַ⁠יִּֽהְי֣וּ בְנֵי־נֹ֗חַ הַ⁠יֹּֽצְאִים֙ מִן־הַ⁠תֵּבָ֔ה שֵׁ֖ם וְ⁠חָ֣ם וָ⁠יָ֑פֶת וְ⁠חָ֕ם ה֖וּא אֲבִ֥י כְנָֽעַן׃","wa⁠yiֽ̇hĕy֣ẇ bĕnéy-nò֗ẖa ha⁠yòֽ̇ẕĕʼiym֙ min-ha⁠ţé̇bá֔h şé֖̌m wĕ⁠ẖá֣m wá⁠yá֑peţ wĕ⁠ẖá֕m h֖ẇʼ ʼàbi֥y kĕnáֽʻan׃"],[9,19,"שְׁלֹשָׁ֥ה אֵ֖לֶּה בְּנֵי־נֹ֑חַ וּ⁠מֵ⁠אֵ֖לֶּה נָֽפְצָ֥ה כָל־הָ⁠אָֽרֶץ׃","şĕ̌lòşá֥̌h ʼé֖lėh bĕ̇néy-nò֑ẖa ẇ⁠mé⁠ʼé֖lėh náֽpĕẕá֥h kál-há⁠ʼáֽreẕ׃"],[9,20,"וַ⁠יָּ֥חֶל נֹ֖חַ אִ֣ישׁ הָֽ⁠אֲדָמָ֑ה וַ⁠יִּטַּ֖ע כָּֽרֶם׃","wa⁠yá֥̇ẖel nò֖ẖa ʼi֣yş̌ hֽá⁠ʼàdámá֑h wa⁠yi̇tȧ֖ʻ káֽ̇rem׃"],[9,21,"וַ⁠יֵּ֥שְׁתְּ מִן־הַ⁠יַּ֖יִן וַ⁠יִּשְׁכָּ֑ר וַ⁠יִּתְגַּ֖ל בְּ⁠ת֥וֹךְ אָהֳלֹֽ⁠ה׃","wa⁠yé֥̇şĕ̌ţĕ̇ min-ha⁠yȧ֖yin wa⁠yi̇şĕ̌ká֑̇r wa⁠yi̇ţĕgȧ֖l bĕ̇⁠ţ֥wòkĕ ʼáholòֽ⁠h׃"],[9,22,"וַ⁠יַּ֗רְא חָ֚ם אֲבִ֣י כְנַ֔עַן אֵ֖ת עֶרְוַ֣ת אָבִ֑י⁠ו וַ⁠יַּגֵּ֥ד לִ⁠שְׁנֵֽי־אֶחָ֖י⁠ו בַּ⁠חֽוּץ׃","wa⁠yȧ֗rĕʼ ẖá֚m ʼàbi֣y kĕna֔ʻan ʼé֖ţ ʻerĕwa֣ţ ʼábi֑y⁠w wa⁠yȧgé֥̇d li⁠şĕ̌néֽy-ʼeẖá֖y⁠w bȧ⁠ẖֽẇẕ׃"],[9,23,"וַ⁠יִּקַּח֩ שֵׁ֨ם וָ⁠יֶ֜פֶת אֶת־הַ⁠שִּׂמְלָ֗ה וַ⁠יָּשִׂ֨ימוּ֙ עַל־שְׁכֶ֣ם שְׁנֵי⁠הֶ֔ם וַ⁠יֵּֽלְכוּ֙ אֲחֹ֣רַנִּ֔ית וַ⁠יְכַסּ֕וּ אֵ֖ת עֶרְוַ֣ת אֲבִי⁠הֶ֑ם וּ⁠פְנֵי⁠הֶם֙ אֲחֹ֣רַנִּ֔ית וְ⁠עֶרְוַ֥ת אֲבִי⁠הֶ֖ם לֹ֥א רָאֽוּ׃","wa⁠yi̇qȧẖ֩ şé̌֨m wá⁠ye֜peţ ʼeţ-ha⁠şi̇̂mĕlá֗h wa⁠yá̇şî֨ymẇ֙ ʻal-şĕ̌ke֣m şĕ̌néy⁠he֔m wa⁠yéֽ̇lĕkẇ֙ ʼàẖò֣rani̇֔yţ wa⁠yĕkaṡ֕ẇ ʼé֖ţ ʻerĕwa֣ţ ʼàbiy⁠he֑m ẇ⁠pĕnéy⁠hem֙ ʼàẖò֣rani̇֔yţ wĕ⁠ʻerĕwa֥ţ ʼàbiy⁠he֖m lò֥ʼ ráʼֽẇ׃"],[9,24,"וַ⁠יִּ֥יקֶץ נֹ֖חַ מִ⁠יֵּינ֑⁠וֹ וַ⁠יֵּ֕דַע אֵ֛ת אֲשֶׁר־עָ֥שָׂה־ל֖⁠וֹ בְּנ֥⁠וֹ הַ⁠קָּטָֽן׃","wa⁠yi֥̇yqeẕ nò֖ẖa mi⁠yé̇yn֑⁠wò wa⁠yé̇֕daʻ ʼé֛ţ ʼàşěr-ʻá֥şá̂h-l֖⁠wò bĕ̇n֥⁠wò ha⁠qá̇táֽn׃"],[9,25,"וַ⁠יֹּ֖אמֶר אָר֣וּר כְּנָ֑עַן עֶ֥בֶד עֲבָדִ֖ים יִֽהְיֶ֥ה לְ⁠אֶחָֽי⁠ו׃","wa⁠yò֖̇ʼmer ʼár֣ẇr kĕ̇ná֑ʻan ʻe֥bed ʻàbádi֖ym yiֽhĕye֥h lĕ⁠ʼeẖáֽy⁠w׃"],[9,26,"וַ⁠יֹּ֕אמֶר בָּר֥וּךְ יְהֹוָ֖ה אֱלֹ֣הֵי שֵׁ֑ם וִ⁠יהִ֥י כְנַ֖עַן עֶ֥בֶד לָֽ⁠מוֹ׃","wa⁠yò̇֕ʼmer bá̇r֥ẇkĕ yĕhòwá֖h ʼèlò֣héy şé֑̌m wi⁠yhi֥y kĕna֖ʻan ʻe֥bed láֽ⁠mwò׃"],[9,27,"יַ֤פְתְּ אֱלֹהִים֙ לְ⁠יֶ֔פֶת וְ⁠יִשְׁכֹּ֖ן בְּ⁠אָֽהֳלֵי־שֵׁ֑ם וִ⁠יהִ֥י כְנַ֖עַן עֶ֥בֶד לָֽ⁠מוֹ׃","ya֤pĕţĕ̇ ʼèlòhiym֙ lĕ⁠ye֔peţ wĕ⁠yişĕ̌kò֖̇n bĕ̇⁠ʼáֽholéy-şé֑̌m wi⁠yhi֥y kĕna֖ʻan ʻe֥bed láֽ⁠mwò׃"],[9,28,"וַֽ⁠יְחִי־נֹ֖חַ אַחַ֣ר הַ⁠מַּבּ֑וּל שְׁלֹ֤שׁ מֵאוֹת֙ שָׁנָ֔ה וַֽ⁠חֲמִשִּׁ֖ים שָׁנָֽה׃","wֽa⁠yĕẖiy-nò֖ẖa ʼaẖa֣r ha⁠mȧḃ֑ẇl şĕ̌lò֤ş̌ méʼwòţ֙ şá̌ná֔h wֽa⁠ẖàmişi֖̇̌ym şá̌náֽh׃"],[9,29,"וַ⁠יִּֽהְיוּ֙ כָּל־יְמֵי־נֹ֔חַ תְּשַׁ֤ע מֵאוֹת֙ שָׁנָ֔ה וַ⁠חֲמִשִּׁ֖ים שָׁנָ֑ה וַ⁠יָּמֹֽת׃פ","wa⁠yiֽ̇hĕyẇ֙ ká̇l-yĕméy-nò֔ẖa ţĕ̇şǎ֤ʻ méʼwòţ֙ şá̌ná֔h wa⁠ẖàmişi֖̇̌ym şá̌ná֑h wa⁠yá̇mòֽţ׃p"],[10,1,"וְ⁠אֵ֨לֶּה֙ תּוֹלְדֹ֣ת בְּנֵי־נֹ֔חַ שֵׁ֖ם חָ֣ם וָ⁠יָ֑פֶת וַ⁠יִּוָּלְד֥וּ לָ⁠הֶ֛ם בָּנִ֖ים אַחַ֥ר הַ⁠מַּבּֽוּל׃","wĕ⁠ʼé֨lėh֙ ţ̇wòlĕdò֣ţ bĕ̇néy-nò֔ẖa şé֖̌m ẖá֣m wá⁠yá֑peţ wa⁠yi̇wá̇lĕd֥ẇ lá⁠he֛m bá̇ni֖ym ʼaẖa֥r ha⁠mȧḃֽẇl׃"],[10,2,"בְּנֵ֣י יֶ֔פֶת גֹּ֣מֶר וּ⁠מָג֔וֹג וּ⁠מָדַ֖י וְ⁠יָוָ֣ן וְ⁠תֻבָ֑ל וּ⁠מֶ֖שֶׁךְ וְ⁠תִירָֽס׃","bĕ̇né֣y ye֔peţ gò֣̇mer ẇ⁠mág֔wòg ẇ⁠máda֖y wĕ⁠yáwá֣n wĕ⁠ţubá֑l ẇ⁠me֖şěkĕ wĕ⁠ţiyráֽs׃"],[10,3,"וּ⁠בְנֵ֖י גֹּ֑מֶר אַשְׁכֲּנַ֥ז וְ⁠רִיפַ֖ת וְ⁠תֹגַרְמָֽה׃","ẇ⁠bĕné֖y gò֑̇mer ʼaşĕ̌kà̇na֥z wĕ⁠riypa֖ţ wĕ⁠ţògarĕmáֽh׃"],[10,4,"וּ⁠בְנֵ֥י יָוָ֖ן אֱלִישָׁ֣ה וְ⁠תַרְשִׁ֑ישׁ כִּתִּ֖ים וְ⁠דֹדָנִֽים׃","ẇ⁠bĕné֥y yáwá֖n ʼèliyşá֣̌h wĕ⁠ţarĕşǐ֑yş̌ ki̇ţi֖̇ym wĕ⁠dòdániֽym׃"],[10,5,"מֵ֠⁠אֵלֶּה נִפְרְד֞וּ אִיֵּ֤י הַ⁠גּוֹיִם֙ בְּ⁠אַרְצֹתָ֔⁠ם אִ֖ישׁ לִ⁠לְשֹׁנ֑⁠וֹ לְ⁠מִשְׁפְּחֹתָ֖⁠ם בְּ⁠גוֹיֵ⁠הֶֽם׃","mé֠⁠ʼélėh nipĕrĕd֞ẇ ʼiyé֤̇y ha⁠ġwòyim֙ bĕ̇⁠ʼarĕẕòţá֔⁠m ʼi֖yş̌ li⁠lĕşò̌n֑⁠wò lĕ⁠mişĕ̌pĕ̇ẖòţá֖⁠m bĕ̇⁠gwòyé⁠heֽm׃"],[10,6,"וּ⁠בְנֵ֖י חָ֑ם כּ֥וּשׁ וּ⁠מִצְרַ֖יִם וּ⁠פ֥וּט וּ⁠כְנָֽעַן׃","ẇ⁠bĕné֖y ẖá֑m k֥̇ẇş̌ ẇ⁠miẕĕra֖yim ẇ⁠p֥ẇt ẇ⁠kĕnáֽʻan׃"],[10,7,"וּ⁠בְנֵ֣י כ֔וּשׁ סְבָא֙ וַֽ⁠חֲוִילָ֔ה וְ⁠סַבְתָּ֥ה וְ⁠רַעְמָ֖ה וְ⁠סַבְתְּכָ֑א וּ⁠בְנֵ֥י רַעְמָ֖ה שְׁבָ֥א וּ⁠דְדָֽן׃","ẇ⁠bĕné֣y k֔ẇş̌ sĕbáʼ֙ wֽa⁠ẖàwiylá֔h wĕ⁠sabĕţá֥̇h wĕ⁠raʻĕmá֖h wĕ⁠sabĕţĕ̇ká֑ʼ ẇ⁠bĕné֥y raʻĕmá֖h şĕ̌bá֥ʼ ẇ⁠dĕdáֽn׃"],[10,8,"וְ⁠כ֖וּשׁ יָלַ֣ד אֶת־נִמְרֹ֑ד ה֣וּא הֵחֵ֔ל לִֽ⁠הְי֥וֹת גִּבֹּ֖ר בָּ⁠אָֽרֶץ׃","wĕ⁠k֖ẇş̌ yála֣d ʼeţ-nimĕrò֑d h֣ẇʼ héẖé֔l lֽi⁠hĕy֥wòţ gi̇bò֖̇r bá̇⁠ʼáֽreẕ׃"],[10,9,"הֽוּא־הָיָ֥ה גִבֹּֽר־צַ֖יִד לִ⁠פְנֵ֣י יְהוָ֑ה עַל־כֵּן֙ יֵֽאָמַ֔ר כְּ⁠נִמְרֹ֛ד גִּבּ֥וֹר צַ֖יִד לִ⁠פְנֵ֥י יְהוָֽה׃","hֽẇʼ-háyá֥h gibòֽ̇r-ẕa֖yid li⁠pĕné֣y yĕhwá֑h ʻal-ké̇n֙ yéֽʼáma֔r kĕ̇⁠nimĕrò֛d gi̇ḃ֥wòr ẕa֖yid li⁠pĕné֥y yĕhwáֽh׃"],[10,10,"וַ⁠תְּהִ֨י רֵאשִׁ֤ית מַמְלַכְתּ⁠וֹ֙ בָּבֶ֔ל וְ⁠אֶ֖רֶךְ וְ⁠אַכַּ֣ד וְ⁠כַלְנֵ֑ה בְּ⁠אֶ֖רֶץ שִׁנְעָֽר׃","wa⁠ţĕ̇hi֨y réʼşǐ֤yţ mamĕlakĕţ̇⁠wò֙ bá̇be֔l wĕ⁠ʼe֖rekĕ wĕ⁠ʼakȧ֣d wĕ⁠kalĕné֑h bĕ̇⁠ʼe֖reẕ şǐnĕʻáֽr׃"],[10,11,"מִן־הָ⁠אָ֥רֶץ הַ⁠הִ֖וא יָצָ֣א אַשּׁ֑וּר וַ⁠יִּ֨בֶן֙ אֶת־נִ֣ינְוֵ֔ה וְ⁠אֶת־רְחֹבֹ֥ת עִ֖יר וְ⁠אֶת־כָּֽלַח׃","min-há⁠ʼá֥reẕ ha⁠hi֖wʼ yáẕá֣ʼ ʼaş֑̇̌ẇr wa⁠yi̇֨ben֙ ʼeţ-ni֣ynĕwé֔h wĕ⁠ʼeţ-rĕẖòbò֥ţ ʻi֖yr wĕ⁠ʼeţ-káֽ̇laẖ׃"],[10,12,"וְֽ⁠אֶת־רֶ֔סֶן בֵּ֥ין נִֽינְוֵ֖ה וּ⁠בֵ֣ין כָּ֑לַח הִ֖וא הָ⁠עִ֥יר הַ⁠גְּדֹלָֽה׃","wĕֽ⁠ʼeţ-re֔sen bé֥̇yn niֽynĕwé֖h ẇ⁠bé֣yn ká֑̇laẖ hi֖wʼ há⁠ʻi֥yr ha⁠gĕ̇dòláֽh׃"],[10,13,"וּ⁠מִצְרַ֡יִם יָלַ֞ד אֶת־לוּדִ֧ים וְ⁠אֶת־עֲנָמִ֛ים וְ⁠אֶת־לְהָבִ֖ים וְ⁠אֶת־נַפְתֻּחִֽים׃","ẇ⁠miẕĕra֡yim yála֞d ʼeţ-lẇdi֧ym wĕ⁠ʼeţ-ʻànámi֛ym wĕ⁠ʼeţ-lĕhábi֖ym wĕ⁠ʼeţ-napĕţu̇ẖiֽym׃"],[10,14,"וְֽ⁠אֶת־פַּתְרֻסִ֞ים וְ⁠אֶת־כַּסְלֻחִ֗ים אֲשֶׁ֨ר יָצְא֥וּ מִ⁠שָּׁ֛ם פְּלִשְׁתִּ֖ים וְ⁠אֶת־כַּפְתֹּרִֽים׃ס","wĕֽ⁠ʼeţ-pȧţĕrusi֞ym wĕ⁠ʼeţ-kȧsĕluẖi֗ym ʼàşě֨r yáẕĕʼ֥ẇ mi⁠şá֛̇̌m pĕ̇lişĕ̌ţi֖̇ym wĕ⁠ʼeţ-kȧpĕţò̇riֽym׃s"],[10,15,"וּ⁠כְנַ֗עַן יָלַ֛ד אֶת־צִידֹ֥ן בְּכֹר֖⁠וֹ וְ⁠אֶת־חֵֽת׃","ẇ⁠kĕna֗ʻan yála֛d ʼeţ-ẕiydò֥n bĕ̇kòr֖⁠wò wĕ⁠ʼeţ-ẖéֽţ׃"],[10,16,"וְ⁠אֶת־הַ⁠יְבוּסִי֙ וְ⁠אֶת־הָ֣⁠אֱמֹרִ֔י וְ⁠אֵ֖ת הַ⁠גִּרְגָּשִֽׁי׃","wĕ⁠ʼeţ-ha⁠yĕbẇsiy֙ wĕ⁠ʼeţ-há֣⁠ʼèmòri֔y wĕ⁠ʼé֖ţ ha⁠gi̇rĕgá̇şǐֽy׃"],[10,17,"וְ⁠אֶת־הַֽ⁠חִוִּ֥י וְ⁠אֶת־הַֽ⁠עַרְקִ֖י וְ⁠אֶת־הַ⁠סִּינִֽי׃","wĕ⁠ʼeţ-hֽa⁠ẖiwi֥̇y wĕ⁠ʼeţ-hֽa⁠ʻarĕqi֖y wĕ⁠ʼeţ-ha⁠si̇yniֽy׃"],[10,18,"וְ⁠אֶת־הָֽ⁠אַרְוָדִ֥י וְ⁠אֶת־הַ⁠צְּמָרִ֖י וְ⁠אֶת־הַֽ⁠חֲמָתִ֑י וְ⁠אַחַ֣ר נָפֹ֔צוּ מִשְׁפְּח֖וֹת הַֽ⁠כְּנַעֲנִֽי׃","wĕ⁠ʼeţ-hֽá⁠ʼarĕwádi֥y wĕ⁠ʼeţ-ha⁠ẕĕ̇mári֖y wĕ⁠ʼeţ-hֽa⁠ẖàmáţi֑y wĕ⁠ʼaẖa֣r nápò֔ẕẇ mişĕ̌pĕ̇ẖ֖wòţ hֽa⁠kĕ̇naʻàniֽy׃"],[10,19,"וַֽ⁠יְהִ֞י גְּב֤וּל הַֽ⁠כְּנַעֲנִי֙ מִ⁠צִּידֹ֔ן בֹּאֲ⁠כָ֥ה גְרָ֖רָ⁠ה עַד־עַזָּ֑ה בֹּאֲ⁠כָ֞ה סְדֹ֧מָ⁠ה וַ⁠עֲמֹרָ֛ה וְ⁠אַדְמָ֥ה וּ⁠צְבֹיִ֖ם עַד־לָֽשַׁע׃","wֽa⁠yĕhi֞y gĕ̇b֤ẇl hֽa⁠kĕ̇naʻàniy֙ mi⁠ẕi̇ydò֔n bò̇ʼà⁠ká֥h gĕrá֖rá⁠h ʻad-ʻazá֑̇h bò̇ʼà⁠ká֞h sĕdò֧má⁠h wa⁠ʻàmòrá֛h wĕ⁠ʼadĕmá֥h ẇ⁠ẕĕbòyi֖m ʻad-láֽşǎʻ׃"],[10,20,"אֵ֣לֶּה בְנֵי־חָ֔ם לְ⁠מִשְׁפְּחֹתָ֖⁠ם לִ⁠לְשֹֽׁנֹתָ֑⁠ם בְּ⁠אַרְצֹתָ֖⁠ם בְּ⁠גוֹיֵ⁠הֶֽם׃ס","ʼé֣lėh bĕnéy-ẖá֔m lĕ⁠mişĕ̌pĕ̇ẖòţá֖⁠m li⁠lĕşòֽ̌nòţá֑⁠m bĕ̇⁠ʼarĕẕòţá֖⁠m bĕ̇⁠gwòyé⁠heֽm׃s"],[10,21,"וּ⁠לְ⁠שֵׁ֥ם יֻלַּ֖ד גַּם־ה֑וּא אֲבִי֙ כָּל־בְּנֵי־עֵ֔בֶר אֲחִ֖י יֶ֥פֶת הַ⁠גָּדֽוֹל׃","ẇ⁠lĕ⁠şé֥̌m yulȧ֖d gȧm-h֑ẇʼ ʼàbiy֙ ká̇l-bĕ̇néy-ʻé֔ber ʼàẖi֖y ye֥peţ ha⁠gá̇dֽwòl׃"],[10,22,"בְּנֵ֥י שֵׁ֖ם עֵילָ֣ם וְ⁠אַשּׁ֑וּר וְ⁠אַרְפַּכְשַׁ֖ד וְ⁠ל֥וּד וַֽ⁠אֲרָֽם׃","bĕ̇né֥y şé֖̌m ʻéylá֣m wĕ⁠ʼaş֑̇̌ẇr wĕ⁠ʼarĕpȧkĕşǎ֖d wĕ⁠l֥ẇd wֽa⁠ʼàráֽm׃"],[10,23,"וּ⁠בְנֵ֖י אֲרָ֑ם ע֥וּץ וְ⁠ח֖וּל וְ⁠גֶ֥תֶר וָ⁠מַֽשׁ׃","ẇ⁠bĕné֖y ʼàrá֑m ʻ֥ẇẕ wĕ⁠ẖ֖ẇl wĕ⁠ge֥ţer wá⁠maֽş̌׃"],[10,24,"וְ⁠אַרְפַּכְשַׁ֖ד יָלַ֣ד אֶת־שָׁ֑לַח וְ⁠שֶׁ֖לַח יָלַ֥ד אֶת־עֵֽבֶר׃","wĕ⁠ʼarĕpȧkĕşǎ֖d yála֣d ʼeţ-şá֑̌laẖ wĕ⁠şě֖laẖ yála֥d ʼeţ-ʻéֽber׃"],[10,25,"וּ⁠לְ⁠עֵ֥בֶר יֻלַּ֖ד שְׁנֵ֣י בָנִ֑ים שֵׁ֣ם הָֽ⁠אֶחָ֞ד פֶּ֗לֶג כִּ֤י בְ⁠יָמָי⁠ו֙ נִפְלְגָ֣ה הָ⁠אָ֔רֶץ וְ⁠שֵׁ֥ם אָחִ֖י⁠ו יָקְטָֽן׃","ẇ⁠lĕ⁠ʻé֥ber yulȧ֖d şĕ̌né֣y báni֑ym şé֣̌m hֽá⁠ʼeẖá֞d pė֗leg ki֤̇y bĕ⁠yámáy⁠w֙ nipĕlĕgá֣h há⁠ʼá֔reẕ wĕ⁠şé֥̌m ʼáẖi֖y⁠w yáqĕtáֽn׃"],[10,26,"וְ⁠יָקְטָ֣ן יָלַ֔ד אֶת־אַלְמוֹדָ֖ד וְ⁠אֶת־שָׁ֑לֶף וְ⁠אֶת־חֲצַרְמָ֖וֶת וְ⁠אֶת־יָֽרַח׃","wĕ⁠yáqĕtá֣n yála֔d ʼeţ-ʼalĕmwòdá֖d wĕ⁠ʼeţ-şá֑̌lep wĕ⁠ʼeţ-ẖàẕarĕmá֖weţ wĕ⁠ʼeţ-yáֽraẖ׃"],[10,27,"וְ⁠אֶת־הֲדוֹרָ֥ם וְ⁠אֶת־אוּזָ֖ל וְ⁠אֶת־דִּקְלָֽה׃","wĕ⁠ʼeţ-hàdwòrá֥m wĕ⁠ʼeţ-ʼẇzá֖l wĕ⁠ʼeţ-di̇qĕláֽh׃"],[10,28,"וְ⁠אֶת־עוֹבָ֥ל וְ⁠אֶת־אֲבִֽימָאֵ֖ל וְ⁠אֶת־שְׁבָֽא׃","wĕ⁠ʼeţ-ʻwòbá֥l wĕ⁠ʼeţ-ʼàbiֽymáʼé֖l wĕ⁠ʼeţ-şĕ̌báֽʼ׃"],[10,29,"וְ⁠אֶת־אוֹפִ֥ר וְ⁠אֶת־חֲוִילָ֖ה וְ⁠אֶת־יוֹבָ֑ב כָּל־אֵ֖לֶּה בְּנֵ֥י יָקְטָֽן׃","wĕ⁠ʼeţ-ʼwòpi֥r wĕ⁠ʼeţ-ẖàwiylá֖h wĕ⁠ʼeţ-ywòbá֑b ká̇l-ʼé֖lėh bĕ̇né֥y yáqĕtáֽn׃"],[10,30,"וַֽ⁠יְהִ֥י מוֹשָׁבָ֖⁠ם מִ⁠מֵּשָׁ֑א בֹּאֲ⁠כָ֥ה סְפָ֖רָ⁠ה הַ֥ר הַ⁠קֶּֽדֶם׃","wֽa⁠yĕhi֥y mwòşá̌bá֖⁠m mi⁠mé̇şá֑̌ʼ bò̇ʼà⁠ká֥h sĕpá֖rá⁠h ha֥r ha⁠qėֽdem׃"],[10,31,"אֵ֣לֶּה בְנֵי־שֵׁ֔ם לְ⁠מִשְׁפְּחֹתָ֖⁠ם לִ⁠לְשֹׁנֹתָ֑⁠ם בְּ⁠אַרְצֹתָ֖⁠ם לְ⁠גוֹיֵ⁠הֶֽם׃","ʼé֣lėh bĕnéy-şé̌֔m lĕ⁠mişĕ̌pĕ̇ẖòţá֖⁠m li⁠lĕşò̌nòţá֑⁠m bĕ̇⁠ʼarĕẕòţá֖⁠m lĕ⁠gwòyé⁠heֽm׃"],[10,32,"אֵ֣לֶּה מִשְׁפְּחֹ֧ת בְּנֵי־נֹ֛חַ לְ⁠תוֹלְדֹתָ֖⁠ם בְּ⁠גוֹיֵ⁠הֶ֑ם וּ⁠מֵ⁠אֵ֜לֶּה נִפְרְד֧וּ הַ⁠גּוֹיִ֛ם בָּ⁠אָ֖רֶץ אַחַ֥ר הַ⁠מַּבּֽוּל׃פ","ʼé֣lėh mişĕ̌pĕ̇ẖò֧ţ bĕ̇néy-nò֛ẖa lĕ⁠ţwòlĕdòţá֖⁠m bĕ̇⁠gwòyé⁠he֑m ẇ⁠mé⁠ʼé֜lėh nipĕrĕd֧ẇ ha⁠ġwòyi֛m bá̇⁠ʼá֖reẕ ʼaẖa֥r ha⁠mȧḃֽẇl׃p"],[11,1,"וַֽ⁠יְהִ֥י כָל־הָ⁠אָ֖רֶץ שָׂפָ֣ה אֶחָ֑ת וּ⁠דְבָרִ֖ים אֲחָדִֽים׃","wֽa⁠yĕhi֥y kál-há⁠ʼá֖reẕ şá̂pá֣h ʼeẖá֑ţ ẇ⁠dĕbári֖ym ʼàẖádiֽym׃"],[11,2,"וַֽ⁠יְהִ֖י בְּ⁠נָסְעָ֣⁠ם מִ⁠קֶּ֑דֶם וַֽ⁠יִּמְצְא֥וּ בִקְעָ֛ה בְּ⁠אֶ֥רֶץ שִׁנְעָ֖ר וַ⁠יֵּ֥שְׁבוּ שָֽׁם׃","wֽa⁠yĕhi֖y bĕ̇⁠násĕʻá֣⁠m mi⁠qė֑dem wֽa⁠yi̇mĕẕĕʼ֥ẇ biqĕʻá֛h bĕ̇⁠ʼe֥reẕ şǐnĕʻá֖r wa⁠yé֥̇şĕ̌bẇ şáֽ̌m׃"],[11,3,"וַ⁠יֹּאמְר֞וּ אִ֣ישׁ אֶל־רֵעֵ֗⁠הוּ הָ֚בָ⁠ה נִלְבְּנָ֣ה לְבֵנִ֔ים וְ⁠נִשְׂרְפָ֖ה לִ⁠שְׂרֵפָ֑ה וַ⁠תְּהִ֨י לָ⁠הֶ֤ם הַ⁠לְּבֵנָה֙ לְ⁠אָ֔בֶן וְ⁠הַ֣⁠חֵמָ֔ר הָיָ֥ה לָ⁠הֶ֖ם לַ⁠חֹֽמֶר׃","wa⁠yò̇ʼmĕr֞ẇ ʼi֣yş̌ ʼel-réʻé֗⁠hẇ há֚bá⁠h nilĕbĕ̇ná֣h lĕbéni֔ym wĕ⁠nişĕ̂rĕpá֖h li⁠şĕ̂répá֑h wa⁠ţĕ̇hi֨y lá⁠he֤m ha⁠lĕ̇bénáh֙ lĕ⁠ʼá֔ben wĕ⁠ha֣⁠ẖémá֔r háyá֥h lá⁠he֖m la⁠ẖòֽmer׃"],[11,4,"וַ⁠יֹּאמְר֞וּ הָ֣בָ⁠ה ׀ נִבְנֶה־לָּ֣⁠נוּ עִ֗יר וּ⁠מִגְדָּל֙ וְ⁠רֹאשׁ֣⁠וֹ בַ⁠שָּׁמַ֔יִם וְ⁠נַֽעֲשֶׂה־לָּ֖⁠נוּ שֵׁ֑ם פֶּן־נָפ֖וּץ עַל־פְּנֵ֥י כָל־הָ⁠אָֽרֶץ׃","wa⁠yò̇ʼmĕr֞ẇ há֣bá⁠h ׀ nibĕneh-lá֣̇⁠nẇ ʻi֗yr ẇ⁠migĕdá̇l֙ wĕ⁠ròʼş֣̌⁠wò ba⁠şá̇̌ma֔yim wĕ⁠naֽʻàşêh-lá֖̇⁠nẇ şé֑̌m pėn-náp֖ẇẕ ʻal-pĕ̇né֥y kál-há⁠ʼáֽreẕ׃"],[11,5,"וַ⁠יֵּ֣רֶד יְהוָ֔ה לִ⁠רְאֹ֥ת אֶת־הָ⁠עִ֖יר וְ⁠אֶת־הַ⁠מִּגְדָּ֑ל אֲשֶׁ֥ר בָּנ֖וּ בְּנֵ֥י הָ⁠אָדָֽם׃","wa⁠yé֣̇red yĕhwá֔h li⁠rĕʼò֥ţ ʼeţ-há⁠ʻi֖yr wĕ⁠ʼeţ-ha⁠mi̇gĕdá֑̇l ʼàşě֥r bá̇n֖ẇ bĕ̇né֥y há⁠ʼádáֽm׃"],[11,6,"וַ⁠יֹּ֣אמֶר יְהוָ֗ה הֵ֣ן עַ֤ם אֶחָד֙ וְ⁠שָׂפָ֤ה אַחַת֙ לְ⁠כֻלָּ֔⁠ם וְ⁠זֶ֖ה הַחִלָּ֣⁠ם לַ⁠עֲשׂ֑וֹת וְ⁠עַתָּה֙ לֹֽא־יִבָּצֵ֣ר מֵ⁠הֶ֔ם כֹּ֛ל אֲשֶׁ֥ר יָזְמ֖וּ לַֽ⁠עֲשֽׂוֹת׃","wa⁠yò֣̇ʼmer yĕhwá֗h hé֣n ʻa֤m ʼeẖád֙ wĕ⁠şá̂pá֤h ʼaẖaţ֙ lĕ⁠kulá̇֔⁠m wĕ⁠ze֖h haẖilá֣̇⁠m la⁠ʻàş֑̂wòţ wĕ⁠ʻaţá̇h֙ lòֽʼ-yibá̇ẕé֣r mé⁠he֔m kò֛̇l ʼàşě֥r yázĕm֖ẇ lֽa⁠ʻàşֽ̂wòţ׃"],[11,7,"הָ֚בָ⁠ה נֵֽרְדָ֔ה וְ⁠נָבְלָ֥ה שָׁ֖ם שְׂפָתָ֑⁠ם אֲשֶׁר֙ לֹ֣א יִשְׁמְע֔וּ אִ֖ישׁ שְׂפַ֥ת רֵעֵֽ⁠הוּ׃","há֚bá⁠h nֽérĕdá֔h wĕ⁠nábĕlá֥h şá֖̌m şĕ̂páţá֑⁠m ʼàşěr֙ lò֣ʼ yişĕ̌mĕʻ֔ẇ ʼi֖yş̌ şĕ̂pa֥ţ réʻéֽ⁠hẇ׃"],[11,8,"וַ⁠יָּ֨פֶץ יְהוָ֥ה אֹתָ֛⁠ם מִ⁠שָּׁ֖ם עַל־פְּנֵ֣י כָל־הָ⁠אָ֑רֶץ וַֽ⁠יַּחְדְּל֖וּ לִ⁠בְנֹ֥ת הָ⁠עִֽיר׃","wa⁠yá̇֨peẕ yĕhwá֥h ʼòţá֛⁠m mi⁠şá֖̇̌m ʻal-pĕ̇né֣y kál-há⁠ʼá֑reẕ wֽa⁠yȧẖĕdĕ̇l֖ẇ li⁠bĕnò֥ţ há⁠ʻiֽyr׃"],[11,9,"עַל־כֵּ֞ן קָרָ֤א שְׁמָ⁠הּ֙ בָּבֶ֔ל כִּי־שָׁ֛ם בָּלַ֥ל יְהוָ֖ה שְׂפַ֣ת כָּל־הָ⁠אָ֑רֶץ וּ⁠מִ⁠שָּׁם֙ הֱפִיצָ֣⁠ם יְהוָ֔ה עַל־פְּנֵ֖י כָּל־הָ⁠אָֽרֶץ׃פ","ʻal-ké̇֞n qárá֤ʼ şĕ̌má⁠ḣ֙ bá̇be֔l ki̇y-şá֛̌m bá̇la֥l yĕhwá֖h şĕ̂pa֣ţ ká̇l-há⁠ʼá֑reẕ ẇ⁠mi⁠şá̇̌m֙ hèpiyẕá֣⁠m yĕhwá֔h ʻal-pĕ̇né֖y ká̇l-há⁠ʼáֽreẕ׃p"],[11,10,"אֵ֚לֶּה תּוֹלְדֹ֣ת שֵׁ֔ם שֵׁ֚ם בֶּן־מְאַ֣ת שָׁנָ֔ה וַ⁠יּ֖וֹלֶד אֶת־אַרְפַּכְשָׁ֑ד שְׁנָתַ֖יִם אַחַ֥ר הַ⁠מַּבּֽוּל׃","ʼé֚lėh ţ̇wòlĕdò֣ţ şé̌֔m şé֚̌m bėn-mĕʼa֣ţ şá̌ná֔h wa⁠ẏ֖wòled ʼeţ-ʼarĕpȧkĕşá֑̌d şĕ̌náţa֖yim ʼaẖa֥r ha⁠mȧḃֽẇl׃"],[11,11,"וַֽ⁠יְחִי־שֵׁ֗ם אַֽחֲרֵי֙ הוֹלִיד֣⁠וֹ אֶת־אַרְפַּכְשָׁ֔ד חֲמֵ֥שׁ מֵא֖וֹת שָׁנָ֑ה וַ⁠יּ֥וֹלֶד בָּנִ֖ים וּ⁠בָנֽוֹת׃ס","wֽa⁠yĕẖiy-şé̌֗m ʼֽaẖàréy֙ hwòliyd֣⁠wò ʼeţ-ʼarĕpȧkĕşá̌֔d ẖàmé֥ş̌ méʼ֖wòţ şá̌ná֑h wa⁠ẏ֥wòled bá̇ni֖ym ẇ⁠bánֽwòţ׃s"],[11,12,"וְ⁠אַרְפַּכְשַׁ֣ד חַ֔י חָמֵ֥שׁ וּ⁠שְׁלֹשִׁ֖ים שָׁנָ֑ה וַ⁠יּ֖וֹלֶד אֶת־שָֽׁלַח׃","wĕ⁠ʼarĕpȧkĕşǎ֣d ẖa֔y ẖámé֥ş̌ ẇ⁠şĕ̌lòşǐ֖ym şá̌ná֑h wa⁠ẏ֖wòled ʼeţ-şáֽ̌laẖ׃"],[11,13,"וַֽ⁠יְחִ֣י אַרְפַּכְשַׁ֗ד אַֽחֲרֵי֙ הוֹלִיד֣⁠וֹ אֶת־שֶׁ֔לַח שָׁלֹ֣שׁ שָׁנִ֔ים וְ⁠אַרְבַּ֥ע מֵא֖וֹת שָׁנָ֑ה וַ⁠יּ֥וֹלֶד בָּנִ֖ים וּ⁠בָנֽוֹת׃ס","wֽa⁠yĕẖi֣y ʼarĕpȧkĕşǎ֗d ʼֽaẖàréy֙ hwòliyd֣⁠wò ʼeţ-şě֔laẖ şá̌lò֣ş̌ şá̌ni֔ym wĕ⁠ʼarĕbȧ֥ʻ méʼ֖wòţ şá̌ná֑h wa⁠ẏ֥wòled bá̇ni֖ym ẇ⁠bánֽwòţ׃s"],[11,14,"וְ⁠שֶׁ֥לַח חַ֖י שְׁלֹשִׁ֣ים שָׁנָ֑ה וַ⁠יּ֖וֹלֶד אֶת־עֵֽבֶר׃","wĕ⁠şě֥laẖ ẖa֖y şĕ̌lòşǐ֣ym şá̌ná֑h wa⁠ẏ֖wòled ʼeţ-ʻéֽber׃"],[11,15,"וַֽ⁠יְחִי־שֶׁ֗לַח אַחֲרֵי֙ הוֹלִיד֣⁠וֹ אֶת־עֵ֔בֶר שָׁלֹ֣שׁ שָׁנִ֔ים וְ⁠אַרְבַּ֥ע מֵא֖וֹת שָׁנָ֑ה וַ⁠יּ֥וֹלֶד בָּנִ֖ים וּ⁠בָנֽוֹת׃ס","wֽa⁠yĕẖiy-şě֗laẖ ʼaẖàréy֙ hwòliyd֣⁠wò ʼeţ-ʻé֔ber şá̌lò֣ş̌ şá̌ni֔ym wĕ⁠ʼarĕbȧ֥ʻ méʼ֖wòţ şá̌ná֑h wa⁠ẏ֥wòled bá̇ni֖ym ẇ⁠bánֽwòţ׃s"],[11,16,"וַֽ⁠יְחִי־עֵ֕בֶר אַרְבַּ֥ע וּ⁠שְׁלֹשִׁ֖ים שָׁנָ֑ה וַ⁠יּ֖וֹלֶד אֶת־פָּֽלֶג׃","waֽ⁠yĕẖiy-ʻé֕ber ʼarĕbȧ֥ʻ ẇ⁠şĕ̌lòşǐ֖ym şá̌ná֑h wa⁠ẏ֖wòled ʼeţ-páֽ̇leg׃"],[11,17,"וַֽ⁠יְחִי־עֵ֗בֶר אַחֲרֵי֙ הוֹלִיד֣⁠וֹ אֶת־פֶּ֔לֶג שְׁלֹשִׁ֣ים שָׁנָ֔ה וְ⁠אַרְבַּ֥ע מֵא֖וֹת שָׁנָ֑ה וַ⁠יּ֥וֹלֶד בָּנִ֖ים וּ⁠בָנֽוֹת׃ס","waֽ⁠yĕẖiy-ʻé֗ber ʼaẖàréy֙ hwòliyd֣⁠wò ʼeţ-pė֔leg şĕ̌lòşǐ֣ym şá̌ná֔h wĕ⁠ʼarĕbȧ֥ʻ méʼ֖wòţ şá̌ná֑h wa⁠ẏ֥wòled bá̇ni֖ym ẇ⁠bánֽwòţ׃s"],[11,18,"וַֽ⁠יְחִי־פֶ֖לֶג שְׁלֹשִׁ֣ים שָׁנָ֑ה וַ⁠יּ֖וֹלֶד אֶת־רְעֽוּ׃","wֽa⁠yĕẖiy-pe֖leg şĕ̌lòşǐ֣ym şá̌ná֑h wa⁠ẏ֖wòled ʼeţ-rĕʻֽẇ׃"],[11,19,"וַֽ⁠יְחִי־פֶ֗לֶג אַחֲרֵי֙ הוֹלִיד֣⁠וֹ אֶת־רְע֔וּ תֵּ֥שַׁע שָׁנִ֖ים וּ⁠מָאתַ֣יִם שָׁנָ֑ה וַ⁠יּ֥וֹלֶד בָּנִ֖ים וּ⁠בָנֽוֹת׃ס","wֽa⁠yĕẖiy-pe֗leg ʼaẖàréy֙ hwòliyd֣⁠wò ʼeţ-rĕʻ֔ẇ ţé֥̇şǎʻ şá̌ni֖ym ẇ⁠máʼţa֣yim şá̌ná֑h wa⁠ẏ֥wòled bá̇ni֖ym ẇ⁠bánֽwòţ׃s"],[11,20,"וַ⁠יְחִ֣י רְע֔וּ שְׁתַּ֥יִם וּ⁠שְׁלֹשִׁ֖ים שָׁנָ֑ה וַ⁠יּ֖וֹלֶד אֶת־שְׂרֽוּג׃","wa⁠yĕẖi֣y rĕʻ֔ẇ şĕ̌ţȧ֥yim ẇ⁠şĕ̌lòşǐ֖ym şá̌ná֑h wa⁠ẏ֖wòled ʼeţ-şĕ̂rֽẇg׃"],[11,21,"וַ⁠יְחִ֣י רְע֗וּ אַחֲרֵי֙ הוֹלִיד֣⁠וֹ אֶת־שְׂר֔וּג שֶׁ֥בַע שָׁנִ֖ים וּ⁠מָאתַ֣יִם שָׁנָ֑ה וַ⁠יּ֥וֹלֶד בָּנִ֖ים וּ⁠בָנֽוֹת׃ס","wa⁠yĕẖi֣y rĕʻ֗ẇ ʼaẖàréy֙ hwòliyd֣⁠wò ʼeţ-şĕ̂r֔ẇg şě֥baʻ şá̌ni֖ym ẇ⁠máʼţa֣yim şá̌ná֑h wa⁠ẏ֥wòled bá̇ni֖ym ẇ⁠bánֽwòţ׃s"],[11,22,"וַ⁠יְחִ֥י שְׂר֖וּג שְׁלֹשִׁ֣ים שָׁנָ֑ה וַ⁠יּ֖וֹלֶד אֶת־נָחֽוֹר׃","wa⁠yĕẖi֥y şĕ̂r֖ẇg şĕ̌lòşǐ֣ym şá̌ná֑h wa⁠ẏ֖wòled ʼeţ-náẖֽwòr׃"],[11,23,"וַ⁠יְחִ֣י שְׂר֗וּג אַחֲרֵ֛י הוֹלִיד֥⁠וֹ אֶת־נָח֖וֹר מָאתַ֣יִם שָׁנָ֑ה וַ⁠יּ֥וֹלֶד בָּנִ֖ים וּ⁠בָנֽוֹת׃ס","wa⁠yĕẖi֣y şĕ̂r֗ẇg ʼaẖàré֛y hwòliyd֥⁠wò ʼeţ-náẖ֖wòr máʼţa֣yim şá̌ná֑h wa⁠ẏ֥wòled bá̇ni֖ym ẇ⁠bánֽwòţ׃s"],[11,24,"וַ⁠יְחִ֣י נָח֔וֹר תֵּ֥שַׁע וְ⁠עֶשְׂרִ֖ים שָׁנָ֑ה וַ⁠יּ֖וֹלֶד אֶת־תָּֽרַח׃","wa⁠yĕẖi֣y náẖ֔wòr ţé֥̇şǎʻ wĕ⁠ʻeşĕ̂ri֖ym şá̌ná֑h wa⁠ẏ֖wòled ʼeţ-ţáֽ̇raẖ׃"],[11,25,"וַ⁠יְחִ֣י נָח֗וֹר אַחֲרֵי֙ הוֹלִיד֣⁠וֹ אֶת־תֶּ֔רַח תְּשַֽׁע־עֶשְׂרֵ֥ה שָׁנָ֖ה וּ⁠מְאַ֣ת שָׁנָ֑ה וַ⁠יּ֥וֹלֶד בָּנִ֖ים וּ⁠בָנֽוֹת׃ס","wa⁠yĕẖi֣y náẖ֗wòr ʼaẖàréy֙ hwòliyd֣⁠wò ʼeţ-ţė֔raẖ ţĕ̇şǎֽʻ-ʻeşĕ̂ré֥h şá̌ná֖h ẇ⁠mĕʼa֣ţ şá̌ná֑h wa⁠ẏ֥wòled bá̇ni֖ym ẇ⁠bánֽwòţ׃s"],[11,26,"וַֽ⁠יְחִי־תֶ֖רַח שִׁבְעִ֣ים שָׁנָ֑ה וַ⁠יּ֨וֹלֶד֙ אֶת־אַבְרָ֔ם אֶת־נָח֖וֹר וְ⁠אֶת־הָרָֽן׃","wֽa⁠yĕẖiy-ţe֖raẖ şǐbĕʻi֣ym şá̌ná֑h wa⁠ẏ֨wòled֙ ʼeţ-ʼabĕrá֔m ʼeţ-náẖ֖wòr wĕ⁠ʼeţ-háráֽn׃"],[11,27,"וְ⁠אֵ֨לֶּה֙ תּוֹלְדֹ֣ת תֶּ֔רַח תֶּ֚רַח הוֹלִ֣יד אֶת־אַבְרָ֔ם אֶת־נָח֖וֹר וְ⁠אֶת־הָרָ֑ן וְ⁠הָרָ֖ן הוֹלִ֥יד אֶת־לֽוֹט׃","wĕ⁠ʼé֨lėh֙ ţ̇wòlĕdò֣ţ ţė֔raẖ ţė֚raẖ hwòli֣yd ʼeţ-ʼabĕrá֔m ʼeţ-náẖ֖wòr wĕ⁠ʼeţ-hárá֑n wĕ⁠hárá֖n hwòli֥yd ʼeţ-lֽwòt׃"],[11,28,"וַ⁠יָּ֣מָת הָרָ֔ן עַל־פְּנֵ֖י תֶּ֣רַח אָבִ֑י⁠ו בְּ⁠אֶ֥רֶץ מוֹלַדְתּ֖⁠וֹ בְּ⁠א֥וּר כַּשְׂדִּֽים׃","wa⁠yá֣̇máţ hárá֔n ʻal-pĕ̇né֖y ţė֣raẖ ʼábi֑y⁠w bĕ̇⁠ʼe֥reẕ mwòladĕţ֖̇⁠wò bĕ̇⁠ʼ֥ẇr kȧşĕ̂diֽ̇ym׃"],[11,29,"וַ⁠יִּקַּ֨ח אַבְרָ֧ם וְ⁠נָח֛וֹר לָ⁠הֶ֖ם נָשִׁ֑ים שֵׁ֤ם אֵֽשֶׁת־אַבְרָם֙ שָׂרָ֔י וְ⁠שֵׁ֤ם אֵֽשֶׁת־נָחוֹר֙ מִלְכָּ֔ה בַּת־הָרָ֥ן אֲבִֽי־מִלְכָּ֖ה וַֽ⁠אֲבִ֥י יִסְכָּֽה׃","wa⁠yi̇qȧ֨ẖ ʼabĕrá֧m wĕ⁠náẖ֛wòr lá⁠he֖m náşǐ֑ym şé֤̌m ʼéֽşěţ-ʼabĕrám֙ şá̂rá֔y wĕ⁠şé֤̌m ʼéֽşěţ-náẖwòr֙ milĕká̇֔h bȧţ-hárá֥n ʼàbiֽy-milĕká֖̇h wֽa⁠ʼàbi֥y yisĕkáֽ̇h׃"],[11,30,"וַ⁠תְּהִ֥י שָׂרַ֖י עֲקָרָ֑ה אֵ֥ין לָ֖⁠הּ וָלָֽד׃","wa⁠ţĕ̇hi֥y şá̂ra֖y ʻàqárá֑h ʼé֥yn lá֖⁠ḣ wáláֽd׃"],[11,31,"וַ⁠יִּקַּ֨ח תֶּ֜רַח אֶת־אַבְרָ֣ם בְּנ֗⁠וֹ וְ⁠אֶת־ל֤וֹט בֶּן־הָרָן֙ בֶּן־בְּנ֔⁠וֹ וְ⁠אֵת֙ שָׂרַ֣י כַּלָּת֔⁠וֹ אֵ֖שֶׁת אַבְרָ֣ם בְּנ֑⁠וֹ וַ⁠יֵּצְא֨וּ אִתָּ֜⁠ם מֵ⁠א֣וּר כַּשְׂדִּ֗ים לָ⁠לֶ֨כֶת֙ אַ֣רְצָ⁠ה כְּנַ֔עַן וַ⁠יָּבֹ֥אוּ עַד־חָרָ֖ן וַ⁠יֵּ֥שְׁבוּ שָֽׁם׃","wa⁠yi̇qȧ֨ẖ ţė֜raẖ ʼeţ-ʼabĕrá֣m bĕ̇n֗⁠wò wĕ⁠ʼeţ-l֤wòt bėn-hárán֙ bėn-bĕ̇n֔⁠wò wĕ⁠ʼéţ֙ şá̂ra֣y kȧlá̇ţ֔⁠wò ʼé֖şěţ ʼabĕrá֣m bĕ̇n֑⁠wò wa⁠yé̇ẕĕʼ֨ẇ ʼiţá̇֜⁠m mé⁠ʼ֣ẇr kȧşĕ̂di̇֗ym lá⁠le֨keţ֙ ʼa֣rĕẕá⁠h kĕ̇na֔ʻan wa⁠yá̇bò֥ʼẇ ʻad-ẖárá֖n wa⁠yé֥̇şĕ̌bẇ şáֽ̌m׃"],[11,32,"וַ⁠יִּהְי֣וּ יְמֵי־תֶ֔רַח חָמֵ֥שׁ שָׁנִ֖ים וּ⁠מָאתַ֣יִם שָׁנָ֑ה וַ⁠יָּ֥מָת תֶּ֖רַח בְּ⁠חָרָֽן׃ס","wa⁠yi̇hĕy֣ẇ yĕméy-ţe֔raẖ ẖámé֥ş̌ şá̌ni֖ym ẇ⁠máʼţa֣yim şá̌ná֑h wa⁠yá֥̇máţ ţė֖raẖ bĕ̇⁠ẖáráֽn׃s"],[12,1,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־אַבְרָ֔ם לֶךְ־לְ⁠ךָ֛ מֵ⁠אַרְצְ⁠ךָ֥ וּ⁠מִ⁠מּֽוֹלַדְתְּ⁠ךָ֖ וּ⁠מִ⁠בֵּ֣ית אָבִ֑י⁠ךָ אֶל־הָ⁠אָ֖רֶץ אֲשֶׁ֥ר אַרְאֶֽ⁠ךָּ׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-ʼabĕrá֔m lekĕ-lĕ⁠ká֛ mé⁠ʼarĕẕĕ⁠ká֥ ẇ⁠mi⁠ṁֽwòladĕţĕ̇⁠ká֖ ẇ⁠mi⁠bé֣̇yţ ʼábi֑y⁠ká ʼel-há⁠ʼá֖reẕ ʼàşě֥r ʼarĕʼeֽ⁠ká̇׃"],[12,2,"וְ⁠אֶֽעֶשְׂ⁠ךָ֙ לְ⁠ג֣וֹי גָּד֔וֹל וַ⁠אֲבָ֣רֶכְ⁠ךָ֔ וַ⁠אֲגַדְּלָ֖ה שְׁמֶ֑⁠ךָ וֶ⁠הְיֵ֖ה בְּרָכָֽה׃","wĕ⁠ʼeֽʻeşĕ̂⁠ká֙ lĕ⁠g֣wòy gá̇d֔wòl wa⁠ʼàbá֣rekĕ⁠ká֔ wa⁠ʼàgadĕ̇lá֖h şĕ̌me֑⁠ká we⁠hĕyé֖h bĕ̇rákáֽh׃"],[12,3,"וַ⁠אֲבָֽרֲכָה֙ מְבָ֣רְכֶ֔י⁠ךָ וּ⁠מְקַלֶּלְ⁠ךָ֖ אָאֹ֑ר וְ⁠נִבְרְכ֣וּ בְ⁠ךָ֔ כֹּ֖ל מִשְׁפְּחֹ֥ת הָ⁠אֲדָמָֽה׃","wa⁠ʼàbáֽràkáh֙ mĕbá֣rĕke֔y⁠ká ẇ⁠mĕqalėlĕ⁠ká֖ ʼáʼò֑r wĕ⁠nibĕrĕk֣ẇ bĕ⁠ká֔ kò֖̇l mişĕ̌pĕ̇ẖò֥ţ há⁠ʼàdámáֽh׃"],[12,4,"וַ⁠יֵּ֣לֶךְ אַבְרָ֗ם כַּ⁠אֲשֶׁ֨ר דִּבֶּ֤ר אֵלָי⁠ו֙ יְהוָ֔ה וַ⁠יֵּ֥לֶךְ אִתּ֖⁠וֹ ל֑וֹט וְ⁠אַבְרָ֗ם בֶּן־חָמֵ֤שׁ שָׁנִים֙ וְ⁠שִׁבְעִ֣ים שָׁנָ֔ה בְּ⁠צֵאת֖⁠וֹ מֵ⁠חָרָֽן׃","wa⁠yé֣̇lekĕ ʼabĕrá֗m kȧ⁠ʼàşě֨r di̇bė֤r ʼéláy⁠w֙ yĕhwá֔h wa⁠yé֥̇lekĕ ʼiţ֖̇⁠wò l֑wòt wĕ⁠ʼabĕrá֗m bėn-ẖámé֤ş̌ şá̌niym֙ wĕ⁠şǐbĕʻi֣ym şá̌ná֔h bĕ̇⁠ẕéʼţ֖⁠wò mé⁠ẖáráֽn׃"],[12,5,"וַ⁠יִּקַּ֣ח אַבְרָם֩ אֶת־שָׂרַ֨י אִשְׁתּ֜⁠וֹ וְ⁠אֶת־ל֣וֹט בֶּן־אָחִ֗י⁠ו וְ⁠אֶת־כָּל־רְכוּשָׁ⁠ם֙ אֲשֶׁ֣ר רָכָ֔שׁוּ וְ⁠אֶת־הַ⁠נֶּ֖פֶשׁ אֲשֶׁר־עָשׂ֣וּ בְ⁠חָרָ֑ן וַ⁠יֵּצְא֗וּ לָ⁠לֶ֨כֶת֙ אַ֣רְצָ⁠ה כְּנַ֔עַן וַ⁠יָּבֹ֖אוּ אַ֥רְצָ⁠ה כְּנָֽעַן׃","wa⁠yi̇qȧ֣ẖ ʼabĕrám֩ ʼeţ-şá̂ra֨y ʼişĕ̌ţ̇֜⁠wò wĕ⁠ʼeţ-l֣wòt bėn-ʼáẖi֗y⁠w wĕ⁠ʼeţ-ká̇l-rĕkẇşá̌⁠m֙ ʼàşě֣r ráká֔ş̌ẇ wĕ⁠ʼeţ-ha⁠nė֖peş̌ ʼàşěr-ʻáş֣̂ẇ bĕ⁠ẖárá֑n wa⁠yé̇ẕĕʼ֗ẇ lá⁠le֨keţ֙ ʼa֣rĕẕá⁠h kĕ̇na֔ʻan wa⁠yá̇bò֖ʼẇ ʼa֥rĕẕá⁠h kĕ̇náֽʻan׃"],[12,6,"וַ⁠יַּעֲבֹ֤ר אַבְרָם֙ בָּ⁠אָ֔רֶץ עַ֚ד מְק֣וֹם שְׁכֶ֔ם עַ֖ד אֵל֣וֹן מוֹרֶ֑ה וְ⁠הַֽ⁠כְּנַעֲנִ֖י אָ֥ז בָּ⁠אָֽרֶץ׃","wa⁠yȧʻàbò֤r ʼabĕrám֙ bá̇⁠ʼá֔reẕ ʻa֚d mĕq֣wòm şĕ̌ke֔m ʻa֖d ʼél֣wòn mwòre֑h wĕ⁠hֽa⁠kĕ̇naʻàni֖y ʼá֥z bá̇⁠ʼáֽreẕ׃"],[12,7,"וַ⁠יֵּרָ֤א יְהוָה֙ אֶל־אַבְרָ֔ם וַ⁠יֹּ֕אמֶר לְ⁠זַ֨רְעֲ⁠ךָ֔ אֶתֵּ֖ן אֶת־הָ⁠אָ֣רֶץ הַ⁠זֹּ֑את וַ⁠יִּ֤בֶן שָׁם֙ מִזְבֵּ֔חַ לַ⁠יהוָ֖ה הַ⁠נִּרְאֶ֥ה אֵלָֽי⁠ו׃","wa⁠yé̇rá֤ʼ yĕhwáh֙ ʼel-ʼabĕrá֔m wa⁠yò̇֕ʼmer lĕ⁠za֨rĕʻà⁠ká֔ ʼeţé֖̇n ʼeţ-há⁠ʼá֣reẕ ha⁠zò֑̇ʼţ wa⁠yi֤̇ben şá̌m֙ mizĕbé̇֔ẖa la⁠yhwá֖h ha⁠ni̇rĕʼe֥h ʼéláֽy⁠w׃"],[12,8,"וַ⁠יַּעְתֵּ֨ק מִ⁠שָּׁ֜ם הָ⁠הָ֗רָ⁠ה מִ⁠קֶּ֛דֶם לְ⁠בֵֽית־אֵ֖ל וַ⁠יֵּ֣ט אָהֳלֹ֑⁠ה בֵּֽית־אֵ֤ל מִ⁠יָּם֙ וְ⁠הָ⁠עַ֣י מִ⁠קֶּ֔דֶם וַ⁠יִּֽבֶן־שָׁ֤ם מִזְבֵּ֨חַ֙ לַֽ⁠יהוָ֔ה וַ⁠יִּקְרָ֖א בְּ⁠שֵׁ֥ם יְהוָֽה׃","wa⁠yȧʻĕţé̇֨q mi⁠şá̇̌֜m há⁠há֗rá⁠h mi⁠qė֛dem lĕ⁠béֽyţ-ʼé֖l wa⁠yé֣̇t ʼáholò֑⁠h béֽ̇yţ-ʼé֤l mi⁠yá̇m֙ wĕ⁠há⁠ʻa֣y mi⁠qė֔dem wa⁠yiֽ̇ben-şá֤̌m mizĕbé̇֨ẖa֙ lֽa⁠yhwá֔h wa⁠yi̇qĕrá֖ʼ bĕ̇⁠şé֥̌m yĕhwáֽh׃"],[12,9,"וַ⁠יִּסַּ֣ע אַבְרָ֔ם הָל֥וֹךְ וְ⁠נָס֖וֹעַ הַ⁠נֶּֽגְבָּ⁠ה׃פ","wa⁠yi̇sȧ֣ʻ ʼabĕrá֔m hál֥wòkĕ wĕ⁠nás֖wòʻa ha⁠nėֽgĕbá̇⁠h׃p"],[12,10,"וַ⁠יְהִ֥י רָעָ֖ב בָּ⁠אָ֑רֶץ וַ⁠יֵּ֨רֶד אַבְרָ֤ם מִצְרַ֨יְמָ⁠ה֙ לָ⁠ג֣וּר שָׁ֔ם כִּֽי־כָבֵ֥ד הָ⁠רָעָ֖ב בָּ⁠אָֽרֶץ׃","wa⁠yĕhi֥y ráʻá֖b bá̇⁠ʼá֑reẕ wa⁠yé̇֨red ʼabĕrá֤m miẕĕra֨yĕmá⁠h֙ lá⁠g֣ẇr şá̌֔m kiֽ̇y-kábé֥d há⁠ráʻá֖b bá̇⁠ʼáֽreẕ׃"],[12,11,"וַ⁠יְהִ֕י כַּ⁠אֲשֶׁ֥ר הִקְרִ֖יב לָ⁠ב֣וֹא מִצְרָ֑יְמָ⁠ה וַ⁠יֹּ֨אמֶר֙ אֶל־שָׂרַ֣י אִשְׁתּ֔⁠וֹ הִנֵּה־נָ֣א יָדַ֔עְתִּי כִּ֛י אִשָּׁ֥ה יְפַת־מַרְאֶ֖ה אָֽתְּ׃","wa⁠yĕhi֕y kȧ⁠ʼàşě֥r hiqĕri֖yb lá⁠b֣wòʼ miẕĕrá֑yĕmá⁠h wa⁠yò̇֨ʼmer֙ ʼel-şá̂ra֣y ʼişĕ̌ţ̇֔⁠wò hiné̇h-ná֣ʼ yáda֔ʻĕţi̇y ki֛̇y ʼişá֥̇̌h yĕpaţ-marĕʼe֖h ʼáֽţĕ̇׃"],[12,12,"וְ⁠הָיָ֗ה כִּֽי־יִרְא֤וּ אֹתָ⁠ךְ֙ הַ⁠מִּצְרִ֔ים וְ⁠אָמְר֖וּ אִשְׁתּ֣⁠וֹ זֹ֑את וְ⁠הָרְג֥וּ אֹתִ֖⁠י וְ⁠אֹתָ֥⁠ךְ יְחַיּֽוּ׃","wĕ⁠háyá֗h kiֽ̇y-yirĕʼ֤ẇ ʼòţá⁠kĕ֙ ha⁠mi̇ẕĕri֔ym wĕ⁠ʼámĕr֖ẇ ʼişĕ̌ţ֣̇⁠wò zò֑ʼţ wĕ⁠hárĕg֥ẇ ʼòţi֖⁠y wĕ⁠ʼòţá֥⁠kĕ yĕẖaẏֽẇ׃"],[12,13,"אִמְרִי־נָ֖א אֲחֹ֣תִ⁠י אָ֑תְּ לְמַ֨עַן֙ יִֽיטַב־לִ֣⁠י בַ⁠עֲבוּרֵ֔⁠ךְ וְ⁠חָיְתָ֥ה נַפְשִׁ֖⁠י בִּ⁠גְלָלֵֽ⁠ךְ׃","ʼimĕriy-ná֖ʼ ʼàẖò֣ţi⁠y ʼá֑ţĕ̇ lĕma֨ʻan֙ yiֽytab-li֣⁠y ba⁠ʻàbẇré֔⁠kĕ wĕ⁠ẖáyĕţá֥h napĕşǐ֖⁠y bi̇⁠gĕláléֽ⁠kĕ׃"],[12,14,"וַ⁠יְהִ֕י כְּ⁠ב֥וֹא אַבְרָ֖ם מִצְרָ֑יְמָ⁠ה וַ⁠יִּרְא֤וּ הַ⁠מִּצְרִים֙ אֶת־הָ֣⁠אִשָּׁ֔ה כִּֽי־יָפָ֥ה הִ֖וא מְאֹֽד׃","wa⁠yĕhi֕y kĕ̇⁠b֥wòʼ ʼabĕrá֖m miẕĕrá֑yĕmá⁠h wa⁠yi̇rĕʼ֤ẇ ha⁠mi̇ẕĕriym֙ ʼeţ-há֣⁠ʼişá̇̌֔h kiֽ̇y-yápá֥h hi֖wʼ mĕʼòֽd׃"],[12,15,"וַ⁠יִּרְא֤וּ אֹתָ⁠הּ֙ שָׂרֵ֣י פַרְעֹ֔ה וַ⁠יְהַֽלְל֥וּ אֹתָ֖⁠הּ אֶל־פַּרְעֹ֑ה וַ⁠תֻּקַּ֥ח הָ⁠אִשָּׁ֖ה בֵּ֥ית פַּרְעֹֽה׃","wa⁠yi̇rĕʼ֤ẇ ʼòţá⁠ḣ֙ şá̂ré֣y parĕʻò֔h wa⁠yĕhaֽlĕl֥ẇ ʼòţá֖⁠ḣ ʼel-pȧrĕʻò֑h wa⁠ţu̇qȧ֥ẖ há⁠ʼişá֖̇̌h bé֥̇yţ pȧrĕʻòֽh׃"],[12,16,"וּ⁠לְ⁠אַבְרָ֥ם הֵיטִ֖יב בַּ⁠עֲבוּרָ֑⁠הּ וַֽ⁠יְהִי־ל֤⁠וֹ צֹאן־וּ⁠בָקָר֙ וַ⁠חֲמֹרִ֔ים וַ⁠עֲבָדִים֙ וּ⁠שְׁפָחֹ֔ת וַ⁠אֲתֹנֹ֖ת וּ⁠גְמַלִּֽים׃","ẇ⁠lĕ⁠ʼabĕrá֥m héyti֖yb bȧ⁠ʻàbẇrá֑⁠ḣ wֽa⁠yĕhiy-l֤⁠wò ẕòʼn-ẇ⁠báqár֙ wa⁠ẖàmòri֔ym wa⁠ʻàbádiym֙ ẇ⁠şĕ̌páẖò֔ţ wa⁠ʼàţònò֖ţ ẇ⁠gĕmaliֽ̇ym׃"],[12,17,"וַ⁠יְנַגַּ֨ע יְהוָ֧ה ׀ אֶת־פַּרְעֹ֛ה נְגָעִ֥ים גְּדֹלִ֖ים וְ⁠אֶת־בֵּית֑⁠וֹ עַל־דְּבַ֥ר שָׂרַ֖י אֵ֥שֶׁת אַבְרָֽם׃","wa⁠yĕnagȧ֨ʻ yĕhwá֧h ׀ ʼeţ-pȧrĕʻò֛h nĕgáʻi֥ym gĕ̇dòli֖ym wĕ⁠ʼeţ-bé̇yţ֑⁠wò ʻal-dĕ̇ba֥r şá̂ra֖y ʼé֥şěţ ʼabĕráֽm׃"],[12,18,"וַ⁠יִּקְרָ֤א פַרְעֹה֙ לְ⁠אַבְרָ֔ם וַ⁠יֹּ֕אמֶר מַה־זֹּ֖את עָשִׂ֣יתָ לִּ֑⁠י לָ֚⁠מָּה לֹא־הִגַּ֣דְתָּ לִּ֔⁠י כִּ֥י אִשְׁתְּ⁠ךָ֖ הִֽוא׃","wa⁠yi̇qĕrá֤ʼ parĕʻòh֙ lĕ⁠ʼabĕrá֔m wa⁠yò̇֕ʼmer mah-zò֖̇ʼţ ʻáşî֣yţá li֑̇⁠y lá֚⁠má̇h lòʼ-higȧ֣dĕţá̇ li̇֔⁠y ki֥̇y ʼişĕ̌ţĕ̇⁠ká֖ hiֽwʼ׃"],[12,19,"לָ⁠מָ֤ה אָמַ֨רְתָּ֙ אֲחֹ֣תִ⁠י הִ֔וא וָ⁠אֶקַּ֥ח אֹתָ֛⁠הּ לִ֖⁠י לְ⁠אִשָּׁ֑ה וְ⁠עַתָּ֕ה הִנֵּ֥ה אִשְׁתְּ⁠ךָ֖ קַ֥ח וָ⁠לֵֽךְ׃","lá⁠má֤h ʼáma֨rĕţá̇֙ ʼàẖò֣ţi⁠y hi֔wʼ wá⁠ʼeqȧ֥ẖ ʼòţá֛⁠ḣ li֖⁠y lĕ⁠ʼişá֑̇̌h wĕ⁠ʻaţá̇֕h hiné֥̇h ʼişĕ̌ţĕ̇⁠ká֖ qa֥ẖ wá⁠léֽkĕ׃"],[12,20,"וַ⁠יְצַ֥ו עָלָ֛י⁠ו פַּרְעֹ֖ה אֲנָשִׁ֑ים וַֽ⁠יְשַׁלְּח֥וּ אֹת֛⁠וֹ וְ⁠אֶת־אִשְׁתּ֖⁠וֹ וְ⁠אֶת־כָּל־אֲשֶׁר־לֽ⁠וֹ׃","wa⁠yĕẕa֥w ʻálá֛y⁠w pȧrĕʻò֖h ʼànáşǐ֑ym wֽa⁠yĕşǎlĕ̇ẖ֥ẇ ʼòţ֛⁠wò wĕ⁠ʼeţ-ʼişĕ̌ţ֖̇⁠wò wĕ⁠ʼeţ-ká̇l-ʼàşěr-lֽ⁠wò׃"],[13,1,"וַ⁠יַּעַל֩ אַבְרָ֨ם מִ⁠מִּצְרַ֜יִם ה֠וּא וְ⁠אִשְׁתּ֧⁠וֹ וְ⁠כָל־אֲשֶׁר־ל֛⁠וֹ וְ⁠ל֥וֹט עִמּ֖⁠וֹ הַ⁠נֶּֽגְבָּ⁠ה׃","wa⁠yȧʻal֩ ʼabĕrá֨m mi⁠mi̇ẕĕra֜yim h֠ẇʼ wĕ⁠ʼişĕ̌ţ֧̇⁠wò wĕ⁠kál-ʼàşěr-l֛⁠wò wĕ⁠l֥wòt ʻiṁ֖⁠wò ha⁠nėֽgĕbá̇⁠h׃"],[13,2,"וְ⁠אַבְרָ֖ם כָּבֵ֣ד מְאֹ֑ד בַּ⁠מִּקְנֶ֕ה בַּ⁠כֶּ֖סֶף וּ⁠בַ⁠זָּהָֽב׃","wĕ⁠ʼabĕrá֖m ká̇bé֣d mĕʼò֑d bȧ⁠mi̇qĕne֕h bȧ⁠kė֖sep ẇ⁠ba⁠zá̇háֽb׃"],[13,3,"וַ⁠יֵּ֨לֶךְ֙ לְ⁠מַסָּעָ֔י⁠ו מִ⁠נֶּ֖גֶב וְ⁠עַד־בֵּֽית־אֵ֑ל עַד־הַ⁠מָּק֗וֹם אֲשֶׁר־הָ֨יָה שָׁ֤ם אהל⁠ה בַּ⁠תְּחִלָּ֔ה בֵּ֥ין בֵּֽית־אֵ֖ל וּ⁠בֵ֥ין הָ⁠עָֽי׃","wa⁠yé̇֨lekĕ֙ lĕ⁠masá̇ʻá֔y⁠w mi⁠nė֖geb wĕ⁠ʻad-béֽ̇yţ-ʼé֑l ʻad-ha⁠má̇q֗wòm ʼàşěr-há֨yáh şá֤̌m ʼhl⁠h bȧ⁠ţĕ̇ẖilá̇֔h bé֥̇yn béֽ̇yţ-ʼé֖l ẇ⁠bé֥yn há⁠ʻáֽy׃"],[13,4,"אֶל־מְקוֹם֙ הַ⁠מִּזְבֵּ֔חַ אֲשֶׁר־עָ֥שָׂה שָׁ֖ם בָּ⁠רִאשֹׁנָ֑ה וַ⁠יִּקְרָ֥א שָׁ֛ם אַבְרָ֖ם בְּ⁠שֵׁ֥ם יְהוָֽה׃","ʼel-mĕqwòm֙ ha⁠mi̇zĕbé̇֔ẖa ʼàşěr-ʻá֥şá̂h şá֖̌m bá̇⁠riʼşò̌ná֑h wa⁠yi̇qĕrá֥ʼ şá֛̌m ʼabĕrá֖m bĕ̇⁠şé֥̌m yĕhwáֽh׃"],[13,5,"וְ⁠גַם־לְ⁠ל֔וֹט הַ⁠הֹלֵ֖ךְ אֶת־אַבְרָ֑ם הָיָ֥ה צֹאן־וּ⁠בָקָ֖ר וְ⁠אֹהָלִֽים׃","wĕ⁠gam-lĕ⁠l֔wòt ha⁠hòlé֖kĕ ʼeţ-ʼabĕrá֑m háyá֥h ẕòʼn-ẇ⁠báqá֖r wĕ⁠ʼòháliֽym׃"],[13,6,"וְ⁠לֹא־נָשָׂ֥א אֹתָ֛⁠ם הָ⁠אָ֖רֶץ לָ⁠שֶׁ֣בֶת יַחְדָּ֑ו כִּֽי־הָיָ֤ה רְכוּשָׁ⁠ם֙ רָ֔ב וְ⁠לֹ֥א יָֽכְל֖וּ לָ⁠שֶׁ֥בֶת יַחְדָּֽו׃","wĕ⁠lòʼ-náşá֥̂ʼ ʼòţá֛⁠m há⁠ʼá֖reẕ lá⁠şě֣beţ yaẖĕdá֑̇w kiֽ̇y-háyá֤h rĕkẇşá̌⁠m֙ rá֔b wĕ⁠lò֥ʼ yáֽkĕl֖ẇ lá⁠şě֥beţ yaẖĕdáֽ̇w׃"],[13,7,"וַֽ⁠יְהִי־רִ֗יב בֵּ֚ין רֹעֵ֣י מִקְנֵֽה־אַבְרָ֔ם וּ⁠בֵ֖ין רֹעֵ֣י מִקְנֵה־ל֑וֹט וְ⁠הַֽ⁠כְּנַעֲנִי֙ וְ⁠הַ⁠פְּרִזִּ֔י אָ֖ז יֹשֵׁ֥ב בָּ⁠אָֽרֶץ׃","wֽa⁠yĕhiy-ri֗yb bé֚̇yn ròʻé֣y miqĕnéֽh-ʼabĕrá֔m ẇ⁠bé֖yn ròʻé֣y miqĕnéh-l֑wòt wĕ⁠haֽ⁠kĕ̇naʻàniy֙ wĕ⁠ha⁠pĕ̇rizi̇֔y ʼá֖z yòşé֥̌b bá̇⁠ʼáֽreẕ׃"],[13,8,"וַ⁠יֹּ֨אמֶר אַבְרָ֜ם אֶל־ל֗וֹט אַל־נָ֨א תְהִ֤י מְרִיבָה֙ בֵּינִ֣⁠י וּ⁠בֵינֶ֔י⁠ךָ וּ⁠בֵ֥ין רֹעַ֖⁠י וּ⁠בֵ֣ין רֹעֶ֑י⁠ךָ כִּֽי־אֲנָשִׁ֥ים אַחִ֖ים אֲנָֽחְנוּ׃","wa⁠yò̇֨ʼmer ʼabĕrá֜m ʼel-l֗wòt ʼal-ná֨ʼ ţĕhi֤y mĕriybáh֙ bé̇yni֣⁠y ẇ⁠béyne֔y⁠ká ẇ⁠bé֥yn ròʻa֖⁠y ẇ⁠bé֣yn ròʻe֑y⁠ká kiֽ̇y-ʼànáşǐ֥ym ʼaẖi֖ym ʼànáֽẖĕnẇ׃"],[13,9,"הֲ⁠לֹ֤א כָל־הָ⁠אָ֨רֶץ֙ לְ⁠פָנֶ֔י⁠ךָ הִפָּ֥רֶד נָ֖א מֵ⁠עָלָ֑⁠י אִם־הַ⁠שְּׂמֹ֣אל וְ⁠אֵימִ֔נָה וְ⁠אִם־הַ⁠יָּמִ֖ין וְ⁠אַשְׂמְאִֽילָה׃","hà⁠lò֤ʼ kál-há⁠ʼá֨reẕ֙ lĕ⁠páne֔y⁠ká hipá֥̇red ná֖ʼ mé⁠ʻálá֑⁠y ʼim-ha⁠şĕ̇̂mò֣ʼl wĕ⁠ʼéymi֔náh wĕ⁠ʼim-ha⁠yá̇mi֖yn wĕ⁠ʼaşĕ̂mĕʼiֽyláh׃"],[13,10,"וַ⁠יִּשָּׂא־ל֣וֹט אֶת־עֵינָ֗י⁠ו וַ⁠יַּרְא֙ אֶת־כָּל־כִּכַּ֣ר הַ⁠יַּרְדֵּ֔ן כִּ֥י כֻלָּ֖⁠הּ מַשְׁקֶ֑ה לִ⁠פְנֵ֣י ׀ שַׁחֵ֣ת יְהוָ֗ה אֶת־סְדֹם֙ וְ⁠אֶת־עֲמֹרָ֔ה כְּ⁠גַן־יְהוָה֙ כְּ⁠אֶ֣רֶץ מִצְרַ֔יִם בֹּאֲ⁠כָ֖ה צֹֽעַר׃","wa⁠yi̇şá̇̂ʼ-l֣wòt ʼeţ-ʻéyná֗y⁠w wa⁠yȧrĕʼ֙ ʼeţ-ká̇l-ki̇kȧ֣r ha⁠yȧrĕdé̇֔n ki֥̇y kulá֖̇⁠ḣ maşĕ̌qe֑h li⁠pĕné֣y ׀ şǎẖé֣ţ yĕhwá֗h ʼeţ-sĕdòm֙ wĕ⁠ʼeţ-ʻàmòrá֔h kĕ̇⁠gan-yĕhwáh֙ kĕ̇⁠ʼe֣reẕ miẕĕra֔yim bò̇ʼà⁠ká֖h ẕòֽʻar׃"],[13,11,"וַ⁠יִּבְחַר־ל֣⁠וֹ ל֗וֹט אֵ֚ת כָּל־כִּכַּ֣ר הַ⁠יַּרְדֵּ֔ן וַ⁠יִּסַּ֥ע ל֖וֹט מִ⁠קֶּ֑דֶם וַ⁠יִּפָּ֣רְד֔וּ אִ֖ישׁ מֵ⁠עַ֥ל אָחִֽי⁠ו׃","wa⁠yi̇bĕẖar-l֣⁠wò l֗wòt ʼé֚ţ ká̇l-ki̇kȧ֣r ha⁠yȧrĕdé̇֔n wa⁠yi̇sȧ֥ʻ l֖wòt mi⁠qė֑dem wa⁠yi̇pá֣̇rĕd֔ẇ ʼi֖yş̌ mé⁠ʻa֥l ʼáẖiֽy⁠w׃"],[13,12,"אַבְרָ֖ם יָשַׁ֣ב בְּ⁠אֶֽרֶץ־כְּנָ֑עַן וְ⁠ל֗וֹט יָשַׁב֙ בְּ⁠עָרֵ֣י הַ⁠כִּכָּ֔ר וַ⁠יֶּאֱהַ֖ל עַד־סְדֹֽם׃","ʼabĕrá֖m yáşǎ֣b bĕ̇⁠ʼeֽreẕ-kĕ̇ná֑ʻan wĕ⁠l֗wòt yáşǎb֙ bĕ̇⁠ʻáré֣y ha⁠ki̇ká̇֔r wa⁠yėʼèha֖l ʻad-sĕdòֽm׃"],[13,13,"וְ⁠אַנְשֵׁ֣י סְדֹ֔ם רָעִ֖ים וְ⁠חַטָּאִ֑ים לַ⁠יהוָ֖ה מְאֹֽד׃","wĕ⁠ʼanĕşé֣̌y sĕdò֔m ráʻi֖ym wĕ⁠ẖatá̇ʼi֑ym la⁠yhwá֖h mĕʼòֽd׃"],[13,14,"וַֽ⁠יהוָ֞ה אָמַ֣ר אֶל־אַבְרָ֗ם אַחֲרֵי֙ הִפָּֽרֶד־ל֣וֹט מֵֽ⁠עִמּ֔⁠וֹ שָׂ֣א נָ֤א עֵינֶ֨י⁠ךָ֙ וּ⁠רְאֵ֔ה מִן־הַ⁠מָּק֖וֹם אֲשֶׁר־אַתָּ֣ה שָׁ֑ם צָפֹ֥נָ⁠ה וָ⁠נֶ֖גְבָּ⁠ה וָ⁠קֵ֥דְמָ⁠ה וָ⁠יָֽמָּ⁠ה׃","wֽa⁠yhwá֞h ʼáma֣r ʼel-ʼabĕrá֗m ʼaẖàréy֙ hipáֽ̇red-l֣wòt mֽé⁠ʻiṁ֔⁠wò şá֣̂ʼ ná֤ʼ ʻéyne֨y⁠ká֙ ẇ⁠rĕʼé֔h min-ha⁠má̇q֖wòm ʼàşěr-ʼaţá֣̇h şá֑̌m ẕápò֥ná⁠h wá⁠ne֖gĕbá̇⁠h wá⁠qé֥dĕmá⁠h wá⁠yáֽmá̇⁠h׃"],[13,15,"כִּ֧י אֶת־כָּל־הָ⁠אָ֛רֶץ אֲשֶׁר־אַתָּ֥ה רֹאֶ֖ה לְ⁠ךָ֣ אֶתְּנֶ֑⁠נָּה וּֽ⁠לְ⁠זַרְעֲ⁠ךָ֖ עַד־עוֹלָֽם׃","ki֧̇y ʼeţ-ká̇l-há⁠ʼá֛reẕ ʼàşěr-ʼaţá֥̇h ròʼe֖h lĕ⁠ká֣ ʼeţĕ̇ne֑⁠ná̇h ẇֽ⁠lĕ⁠zarĕʻà⁠ká֖ ʻad-ʻwòláֽm׃"],[13,16,"וְ⁠שַׂמְתִּ֥י אֶֽת־זַרְעֲ⁠ךָ֖ כַּ⁠עֲפַ֣ר הָ⁠אָ֑רֶץ אֲשֶׁ֣ר ׀ אִם־יוּכַ֣ל אִ֗ישׁ לִ⁠מְנוֹת֙ אֶת־עֲפַ֣ר הָ⁠אָ֔רֶץ גַּֽם־זַרְעֲ⁠ךָ֖ יִמָּנֶֽה׃","wĕ⁠şâmĕţi֥̇y ʼeֽţ-zarĕʻà⁠ká֖ kȧ⁠ʻàpa֣r há⁠ʼá֑reẕ ʼàşě֣r ׀ ʼim-yẇka֣l ʼi֗yş̌ li⁠mĕnwòţ֙ ʼeţ-ʻàpa֣r há⁠ʼá֔reẕ gȧֽm-zarĕʻà⁠ká֖ yimá̇neֽh׃"],[13,17,"ק֚וּם הִתְהַלֵּ֣ךְ בָּ⁠אָ֔רֶץ לְ⁠אָרְכָּ֖⁠הּ וּ⁠לְ⁠רָחְבָּ֑⁠הּ כִּ֥י לְ⁠ךָ֖ אֶתְּנֶֽ⁠נָּה׃","q֚ẇm hiţĕhalé֣̇kĕ bá̇⁠ʼá֔reẕ lĕ⁠ʼárĕká֖̇⁠ḣ ẇ⁠lĕ⁠ráẖĕbá֑̇⁠ḣ ki֥̇y lĕ⁠ká֖ ʼeţĕ̇neֽ⁠ná̇h׃"],[13,18,"וַ⁠יֶּאֱהַ֣ל אַבְרָ֗ם וַ⁠יָּבֹ֛א וַ⁠יֵּ֛שֶׁב בְּ⁠אֵלֹנֵ֥י מַמְרֵ֖א אֲשֶׁ֣ר בְּ⁠חֶבְר֑וֹן וַ⁠יִּֽבֶן־שָׁ֥ם מִזְבֵּ֖חַ לַֽ⁠יהוָֽה׃פ","wa⁠yėʼèha֣l ʼabĕrá֗m wa⁠yá̇bò֛ʼ wa⁠yé֛̇şěb bĕ̇⁠ʼélòné֥y mamĕré֖ʼ ʼàşě֣r bĕ̇⁠ẖebĕr֑wòn wa⁠yiֽ̇ben-şá֥̌m mizĕbé֖̇ẖa lֽa⁠yhwáֽh׃p"],[14,1,"וַ⁠יְהִ֗י בִּ⁠ימֵי֙ אַמְרָפֶ֣ל מֶֽלֶךְ־שִׁנְעָ֔ר אַרְי֖וֹךְ מֶ֣לֶךְ אֶלָּסָ֑ר כְּדָרְלָעֹ֨מֶר֙ מֶ֣לֶךְ עֵילָ֔ם וְ⁠תִדְעָ֖ל מֶ֥לֶךְ גּוֹיִֽם׃","wa⁠yĕhi֗y bi̇⁠yméy֙ ʼamĕrápe֣l meֽlekĕ-şǐnĕʻá֔r ʼarĕy֖wòkĕ me֣lekĕ ʼelá̇sá֑r kĕ̇dárĕláʻò֨mer֙ me֣lekĕ ʻéylá֔m wĕ⁠ţidĕʻá֖l me֥lekĕ ġwòyiֽm׃"],[14,2,"עָשׂ֣וּ מִלְחָמָ֗ה אֶת־בֶּ֨רַע֙ מֶ֣לֶךְ סְדֹ֔ם וְ⁠אֶת־בִּרְשַׁ֖ע מֶ֣לֶךְ עֲמֹרָ֑ה שִׁנְאָ֣ב ׀ מֶ֣לֶךְ אַדְמָ֗ה וְ⁠שֶׁמְאֵ֨בֶר֙ מֶ֣לֶךְ צביים וּ⁠מֶ֥לֶךְ בֶּ֖לַע הִיא־צֹֽעַר׃","ʻáş֣̂ẇ milĕẖámá֗h ʼeţ-bė֨raʻ֙ me֣lekĕ sĕdò֔m wĕ⁠ʼeţ-bi̇rĕşǎ֖ʻ me֣lekĕ ʻàmòrá֑h şǐnĕʼá֣b ׀ me֣lekĕ ʼadĕmá֗h wĕ⁠şěmĕʼé֨ber֙ me֣lekĕ ẕbyym ẇ⁠me֥lekĕ bė֖laʻ hiyʼ-ẕòֽʻar׃"],[14,3,"כָּל־אֵ֨לֶּה֙ חָֽבְר֔וּ אֶל־עֵ֖מֶק הַ⁠שִּׂדִּ֑ים ה֖וּא יָ֥ם הַ⁠מֶּֽלַח׃","ká̇l-ʼé֨lėh֙ ẖáֽbĕr֔ẇ ʼel-ʻé֖meq ha⁠şi̇̂di֑̇ym h֖ẇʼ yá֥m ha⁠mėֽlaẖ׃"],[14,4,"שְׁתֵּ֤ים עֶשְׂרֵה֙ שָׁנָ֔ה עָבְד֖וּ אֶת־כְּדָרְלָעֹ֑מֶר וּ⁠שְׁלֹשׁ־עֶשְׂרֵ֥ה שָׁנָ֖ה מָרָֽדוּ׃","şĕ̌ţé֤̇ym ʻeşĕ̂réh֙ şá̌ná֔h ʻábĕd֖ẇ ʼeţ-kĕ̇dárĕláʻò֑mer ẇ⁠şĕ̌lòş̌-ʻeşĕ̂ré֥h şá̌ná֖h máráֽdẇ׃"],[14,5,"וּ⁠בְ⁠אַרְבַּע֩ עֶשְׂרֵ֨ה שָׁנָ֜ה בָּ֣א כְדָרְלָעֹ֗מֶר וְ⁠הַ⁠מְּלָכִים֙ אֲשֶׁ֣ר אִתּ֔⁠וֹ וַ⁠יַּכּ֤וּ אֶת־רְפָאִים֙ בְּ⁠עַשְׁתְּרֹ֣ת קַרְנַ֔יִם וְ⁠אֶת־הַ⁠זּוּזִ֖ים בְּ⁠הָ֑ם וְ⁠אֵת֙ הָֽ⁠אֵימִ֔ים בְּ⁠שָׁוֵ֖ה קִרְיָתָֽיִם׃","ẇ⁠bĕ⁠ʼarĕbȧʻ֩ ʻeşĕ̂ré֨h şá̌ná֜h bá֣̇ʼ kĕdárĕláʻò֗mer wĕ⁠ha⁠mĕ̇lákiym֙ ʼàşě֣r ʼiţ̇֔⁠wò wa⁠yȧk֤̇ẇ ʼeţ-rĕpáʼiym֙ bĕ̇⁠ʻaşĕ̌ţĕ̇rò֣ţ qarĕna֔yim wĕ⁠ʼeţ-ha⁠żẇzi֖ym bĕ̇⁠há֑m wĕ⁠ʼéţ֙ hֽá⁠ʼéymi֔ym bĕ̇⁠şá̌wé֖h qirĕyáţáֽyim׃"],[14,6,"וְ⁠אֶת־הַ⁠חֹרִ֖י בְּ⁠הַרְרָ֣⁠ם שֵׂעִ֑יר עַ֚ד אֵ֣יל פָּארָ֔ן אֲשֶׁ֖ר עַל־הַ⁠מִּדְבָּֽר׃","wĕ⁠ʼeţ-ha⁠ẖòri֖y bĕ̇⁠harĕrá֣⁠m şé̂ʻi֑yr ʻa֚d ʼé֣yl pá̇ʼrá֔n ʼàşě֖r ʻal-ha⁠mi̇dĕbáֽ̇r׃"],[14,7,"וַ֠⁠יָּשֻׁבוּ וַ⁠יָּבֹ֜אוּ אֶל־עֵ֤ין מִשְׁפָּט֙ הִ֣וא קָדֵ֔שׁ וַ⁠יַּכּ֕וּ אֶֽת־כָּל־שְׂדֵ֖ה הָ⁠עֲמָלֵקִ֑י וְ⁠גַם֙ אֶת־הָ֣⁠אֱמֹרִ֔י הַ⁠יֹּשֵׁ֖ב בְּ⁠חַֽצְצֹ֥ן תָּמָֽר׃","wa֠⁠yá̇şǔbẇ wa⁠yá̇bò֜ʼẇ ʼel-ʻé֤yn mişĕ̌pá̇t֙ hi֣wʼ qádé֔ş̌ wa⁠yȧk̇֕ẇ ʼeֽţ-ká̇l-şĕ̂dé֖h há⁠ʻàmáléqi֑y wĕ⁠gam֙ ʼeţ-há֣⁠ʼèmòri֔y ha⁠yò̇şé֖̌b bĕ̇⁠ẖaֽẕĕẕò֥n ţá̇máֽr׃"],[14,8,"וַ⁠יֵּצֵ֨א מֶֽלֶךְ־סְדֹ֜ם וּ⁠מֶ֣לֶךְ עֲמֹרָ֗ה וּ⁠מֶ֤לֶךְ אַדְמָה֙ וּ⁠מֶ֣לֶךְ צביים וּ⁠מֶ֥לֶךְ בֶּ֖לַע הִוא־צֹ֑עַר וַ⁠יַּֽעַרְכ֤וּ אִתָּ⁠ם֙ מִלְחָמָ֔ה בְּ⁠עֵ֖מֶק הַ⁠שִּׂדִּֽים׃","wa⁠yé̇ẕé֨ʼ meֽlekĕ-sĕdò֜m ẇ⁠me֣lekĕ ʻàmòrá֗h ẇ⁠me֤lekĕ ʼadĕmáh֙ ẇ⁠me֣lekĕ ẕbyym ẇ⁠me֥lekĕ bė֖laʻ hiwʼ-ẕò֑ʻar wa⁠yȧֽʻarĕk֤ẇ ʼiţá̇⁠m֙ milĕẖámá֔h bĕ̇⁠ʻé֖meq ha⁠şi̇̂diֽ̇ym׃"],[14,9,"אֵ֣ת כְּדָרְלָעֹ֜מֶר מֶ֣לֶךְ עֵילָ֗ם וְ⁠תִדְעָל֙ מֶ֣לֶךְ גּוֹיִ֔ם וְ⁠אַמְרָפֶל֙ מֶ֣לֶךְ שִׁנְעָ֔ר וְ⁠אַרְי֖וֹךְ מֶ֣לֶךְ אֶלָּסָ֑ר אַרְבָּעָ֥ה מְלָכִ֖ים אֶת־הַ⁠חֲמִשָּֽׁה׃","ʼé֣ţ kĕ̇dárĕláʻò֜mer me֣lekĕ ʻéylá֗m wĕ⁠ţidĕʻál֙ me֣lekĕ ġwòyi֔m wĕ⁠ʼamĕrápel֙ me֣lekĕ şǐnĕʻá֔r wĕ⁠ʼarĕy֖wòkĕ me֣lekĕ ʼelá̇sá֑r ʼarĕbá̇ʻá֥h mĕláki֖ym ʼeţ-ha⁠ẖàmişáֽ̇̌h׃"],[14,10,"וְ⁠עֵ֣מֶק הַ⁠שִׂדִּ֗ים בֶּֽאֱרֹ֤ת בֶּאֱרֹת֙ חֵמָ֔ר וַ⁠יָּנֻ֛סוּ מֶֽלֶךְ־סְדֹ֥ם וַ⁠עֲמֹרָ֖ה וַ⁠יִּפְּלוּ־שָׁ֑מָּ⁠ה וְ⁠הַ⁠נִּשְׁאָרִ֖ים הֶ֥רָ⁠ה נָּֽסוּ׃","wĕ⁠ʻé֣meq ha⁠şîdi̇֗ym ḃֽeʼèrò֤ţ bėʼèròţ֙ ẖémá֔r wa⁠yá̇nu֛sẇ meֽlekĕ-sĕdò֥m wa⁠ʻàmòrá֖h wa⁠yi̇pĕ̇lẇ-şá֑̌má̇⁠h wĕ⁠ha⁠ni̇şĕ̌ʼári֖ym he֥rá⁠h náֽ̇sẇ׃"],[14,11,"וַ֠⁠יִּקְחוּ אֶת־כָּל־רְכֻ֨שׁ סְדֹ֧ם וַ⁠עֲמֹרָ֛ה וְ⁠אֶת־כָּל־אָכְלָ֖⁠ם וַ⁠יֵּלֵֽכוּ׃","wa֠⁠yi̇qĕẖẇ ʼeţ-ká̇l-rĕku֨ş̌ sĕdò֧m wa⁠ʻàmòrá֛h wĕ⁠ʼeţ-ká̇l-ʼákĕlá֖⁠m wa⁠yé̇léֽkẇ׃"],[14,12,"וַ⁠יִּקְח֨וּ אֶת־ל֧וֹט וְ⁠אֶת־רְכֻשׁ֛⁠וֹ בֶּן־אֲחִ֥י אַבְרָ֖ם וַ⁠יֵּלֵ֑כוּ וְ⁠ה֥וּא יֹשֵׁ֖ב בִּ⁠סְדֹֽם׃","wa⁠yi̇qĕẖ֨ẇ ʼeţ-l֧wòt wĕ⁠ʼeţ-rĕkuş֛̌⁠wò bėn-ʼàẖi֥y ʼabĕrá֖m wa⁠yé̇lé֑kẇ wĕ⁠h֥ẇʼ yòşé֖̌b bi̇⁠sĕdòֽm׃"],[14,13,"וַ⁠יָּבֹא֙ הַ⁠פָּלִ֔יט וַ⁠יַּגֵּ֖ד לְ⁠אַבְרָ֣ם הָ⁠עִבְרִ֑י וְ⁠הוּא֩ שֹׁכֵ֨ן בְּ⁠אֵֽלֹנֵ֜י מַמְרֵ֣א הָ⁠אֱמֹרִ֗י אֲחִ֤י אֶשְׁכֹּל֙ וַ⁠אֲחִ֣י עָנֵ֔ר וְ⁠הֵ֖ם בַּעֲלֵ֥י בְרִית־אַבְרָֽם׃","wa⁠yá̇bòʼ֙ ha⁠pá̇li֔yt wa⁠yȧgé֖̇d lĕ⁠ʼabĕrá֣m há⁠ʻibĕri֑y wĕ⁠hẇʼ֩ şò̌ké֨n bĕ̇⁠ʼéֽlòné֜y mamĕré֣ʼ há⁠ʼèmòri֗y ʼàẖi֤y ʼeşĕ̌kò̇l֙ wa⁠ʼàẖi֣y ʻáné֔r wĕ⁠hé֖m bȧʻàlé֥y bĕriyţ-ʼabĕráֽm׃"],[14,14,"וַ⁠יִּשְׁמַ֣ע אַבְרָ֔ם כִּ֥י נִשְׁבָּ֖ה אָחִ֑י⁠ו וַ⁠יָּ֨רֶק אֶת־חֲנִיכָ֜י⁠ו יְלִידֵ֣י בֵית֗⁠וֹ שְׁמֹנָ֤ה עָשָׂר֙ וּ⁠שְׁלֹ֣שׁ מֵא֔וֹת וַ⁠יִּרְדֹּ֖ף עַד־דָּֽן׃","wa⁠yi̇şĕ̌ma֣ʻ ʼabĕrá֔m ki֥̇y nişĕ̌bá֖̇h ʼáẖi֑y⁠w wa⁠yá̇֨req ʼeţ-ẖàniyká֜y⁠w yĕliydé֣y béyţ֗⁠wò şĕ̌mòná֤h ʻáşá̂r֙ ẇ⁠şĕ̌lò֣ş̌ méʼ֔wòţ wa⁠yi̇rĕdò֖̇p ʻad-dáֽ̇n׃"],[14,15,"וַ⁠יֵּחָלֵ֨ק עֲלֵי⁠הֶ֧ם ׀ לַ֛יְלָה ה֥וּא וַ⁠עֲבָדָ֖י⁠ו וַ⁠יַּכֵּ֑⁠ם וַֽ⁠יִּרְדְּפֵ⁠ם֙ עַד־חוֹבָ֔ה אֲשֶׁ֥ר מִ⁠שְּׂמֹ֖אל לְ⁠דַמָּֽשֶׂק׃","wa⁠yé̇ẖálé֨q ʻàléy⁠he֧m ׀ la֛yĕláh h֥ẇʼ wa⁠ʻàbádá֖y⁠w wa⁠yȧké֑̇⁠m wֽa⁠yi̇rĕdĕ̇pé⁠m֙ ʻad-ẖwòbá֔h ʼàşě֥r mi⁠şĕ̇̂mò֖ʼl lĕ⁠damáֽ̇şêq׃"],[14,16,"וַ⁠יָּ֕שֶׁב אֵ֖ת כָּל־הָ⁠רְכֻ֑שׁ וְ⁠גַם֩ אֶת־ל֨וֹט אָחִ֤י⁠ו וּ⁠רְכֻשׁ⁠וֹ֙ הֵשִׁ֔יב וְ⁠גַ֥ם אֶת־הַ⁠נָּשִׁ֖ים וְ⁠אֶת־הָ⁠עָֽם׃","wa⁠yá̇֕şěb ʼé֖ţ ká̇l-há⁠rĕku֑ş̌ wĕ⁠gam֩ ʼeţ-l֨wòt ʼáẖi֤y⁠w ẇ⁠rĕkuş̌⁠wò֙ héşǐ֔yb wĕ⁠ga֥m ʼeţ-ha⁠ná̇şǐ֖ym wĕ⁠ʼeţ-há⁠ʻáֽm׃"],[14,17,"וַ⁠יֵּצֵ֣א מֶֽלֶךְ־סְדֹם֮ לִ⁠קְרָאת⁠וֹ֒ אַחֲרֵ֣י שׁוּב֗⁠וֹ מֵֽ⁠הַכּוֹת֙ אֶת־כְּדָרלָעֹ֔מֶר וְ⁠אֶת־הַ⁠מְּלָכִ֖ים אֲשֶׁ֣ר אִתּ֑⁠וֹ אֶל־עֵ֣מֶק שָׁוֵ֔ה ה֖וּא עֵ֥מֶק הַ⁠מֶּֽלֶךְ׃","wa⁠yé̇ẕé֣ʼ meֽlekĕ-sĕdòm֮ li⁠qĕráʼţ⁠wò֒ ʼaẖàré֣y ş̌ẇb֗⁠wò mֽé⁠hak̇wòţ֙ ʼeţ-kĕ̇dárláʻò֔mer wĕ⁠ʼeţ-ha⁠mĕ̇láki֖ym ʼàşě֣r ʼiţ֑̇⁠wò ʼel-ʻé֣meq şá̌wé֔h h֖ẇʼ ʻé֥meq ha⁠mėֽlekĕ׃"],[14,18,"וּ⁠מַלְכִּי־צֶ֨דֶק֙ מֶ֣לֶךְ שָׁלֵ֔ם הוֹצִ֖יא לֶ֣חֶם וָ⁠יָ֑יִן וְ⁠ה֥וּא כֹהֵ֖ן לְ⁠אֵ֥ל עֶלְיֽוֹן׃","ẇ⁠malĕki̇y-ẕe֨deq֙ me֣lekĕ şá̌lé֔m hwòẕi֖yʼ le֣ẖem wá⁠yá֑yin wĕ⁠h֥ẇʼ kòhé֖n lĕ⁠ʼé֥l ʻelĕyֽwòn׃"],[14,19,"וַֽ⁠יְבָרְכֵ֖⁠הוּ וַ⁠יֹּאמַ֑ר בָּר֤וּךְ אַבְרָם֙ לְ⁠אֵ֣ל עֶלְי֔וֹן קֹנֵ֖ה שָׁמַ֥יִם וָ⁠אָֽרֶץ׃","wֽa⁠yĕbárĕké֖⁠hẇ wa⁠yò̇ʼma֑r bá̇r֤ẇkĕ ʼabĕrám֙ lĕ⁠ʼé֣l ʻelĕy֔wòn qòné֖h şá̌ma֥yim wá⁠ʼáֽreẕ׃"],[14,20,"וּ⁠בָרוּךְ֙ אֵ֣ל עֶלְי֔וֹן אֲשֶׁר־מִגֵּ֥ן צָרֶ֖י⁠ךָ בְּ⁠יָדֶ֑⁠ךָ וַ⁠יִּתֶּן־ל֥⁠וֹ מַעֲשֵׂ֖ר מִ⁠כֹּֽל׃","ẇ⁠bárẇkĕ֙ ʼé֣l ʻelĕy֔wòn ʼàşěr-migé֥̇n ẕáre֖y⁠ká bĕ̇⁠yáde֑⁠ká wa⁠yi̇ţėn-l֥⁠wò maʻàşé֖̂r mi⁠kòֽ̇l׃"],[14,21,"וַ⁠יֹּ֥אמֶר מֶֽלֶךְ־סְדֹ֖ם אֶל־אַבְרָ֑ם תֶּן־לִ֣⁠י הַ⁠נֶּ֔פֶשׁ וְ⁠הָ⁠רְכֻ֖שׁ קַֽח־לָֽ⁠ךְ׃","wa⁠yò֥̇ʼmer meֽlekĕ-sĕdò֖m ʼel-ʼabĕrá֑m ţėn-li֣⁠y ha⁠nė֔peş̌ wĕ⁠há⁠rĕku֖ş̌ qaֽẖ-láֽ⁠kĕ׃"],[14,22,"וַ⁠יֹּ֥אמֶר אַבְרָ֖ם אֶל־מֶ֣לֶךְ סְדֹ֑ם הֲרִימֹ֨תִי יָדִ֤⁠י אֶל־יְהוָה֙ אֵ֣ל עֶלְי֔וֹן קֹנֵ֖ה שָׁמַ֥יִם וָ⁠אָֽרֶץ׃","wa⁠yò֥̇ʼmer ʼabĕrá֖m ʼel-me֣lekĕ sĕdò֑m hàriymò֨ţiy yádi֤⁠y ʼel-yĕhwáh֙ ʼé֣l ʻelĕy֔wòn qòné֖h şá̌ma֥yim wá⁠ʼáֽreẕ׃"],[14,23,"אִם־מִ⁠חוּט֙ וְ⁠עַ֣ד שְׂרֽוֹךְ־נַ֔עַל וְ⁠אִם־אֶקַּ֖ח מִ⁠כָּל־אֲשֶׁר־לָ֑⁠ךְ וְ⁠לֹ֣א תֹאמַ֔ר אֲנִ֖י הֶעֱשַׁ֥רְתִּי אֶת־אַבְרָֽם׃","ʼim-mi⁠ẖẇt֙ wĕ⁠ʻa֣d şĕ̂rֽwòkĕ-na֔ʻal wĕ⁠ʼim-ʼeqȧ֖ẖ mi⁠ká̇l-ʼàşěr-lá֑⁠kĕ wĕ⁠lò֣ʼ ţòʼma֔r ʼàni֖y heʻèşǎ֥rĕţi̇y ʼeţ-ʼabĕráֽm׃"],[14,24,"בִּלְעָדַ֗⁠י רַ֚ק אֲשֶׁ֣ר אָֽכְל֣וּ הַ⁠נְּעָרִ֔ים וְ⁠חֵ֨לֶק֙ הָֽ⁠אֲנָשִׁ֔ים אֲשֶׁ֥ר הָלְכ֖וּ אִתִּ֑⁠י עָנֵר֙ אֶשְׁכֹּ֣ל וּ⁠מַמְרֵ֔א הֵ֖ם יִקְח֥וּ חֶלְקָֽ⁠ם׃ס","bi̇lĕʻáda֗⁠y ra֚q ʼàşě֣r ʼֽákĕl֣ẇ ha⁠nĕ̇ʻári֔ym wĕ⁠ẖé֨leq֙ hֽá⁠ʼànáşǐ֔ym ʼàşě֥r hálĕk֖ẇ ʼiţi֑̇⁠y ʻánér֙ ʼeşĕ̌kò֣̇l ẇ⁠mamĕré֔ʼ hé֖m yiqĕẖ֥ẇ ẖelĕqáֽ⁠m׃s"],[15,1,"אַחַ֣ר ׀ הַ⁠דְּבָרִ֣ים הָ⁠אֵ֗לֶּה הָיָ֤ה דְבַר־יְהוָה֙ אֶל־אַבְרָ֔ם בַּֽ⁠מַּחֲזֶ֖ה לֵ⁠אמֹ֑ר אַל־תִּירָ֣א אַבְרָ֗ם אָנֹכִי֙ מָגֵ֣ן לָ֔⁠ךְ שְׂכָרְ⁠ךָ֖ הַרְבֵּ֥ה מְאֹֽד׃","ʼaẖa֣r ׀ ha⁠dĕ̇bári֣ym há⁠ʼé֗lėh háyá֤h dĕbar-yĕhwáh֙ ʼel-ʼabĕrá֔m ḃֽa⁠mȧẖàze֖h lé⁠ʼmò֑r ʼal-ţi̇yrá֣ʼ ʼabĕrá֗m ʼánòkiy֙ mágé֣n lá֔⁠kĕ şĕ̂kárĕ⁠ká֖ harĕbé֥̇h mĕʼòֽd׃"],[15,2,"וַ⁠יֹּ֣אמֶר אַבְרָ֗ם אֲדֹנָ֤⁠י יֱהוִה֙ מַה־תִּתֶּן־לִ֔⁠י וְ⁠אָנֹכִ֖י הוֹלֵ֣ךְ עֲרִירִ֑י וּ⁠בֶן־מֶ֣שֶׁק בֵּיתִ֔⁠י ה֖וּא דַּמֶּ֥שֶׂק אֱלִיעֶֽזֶר׃","wa⁠yò֣̇ʼmer ʼabĕrá֗m ʼàdòná֤⁠y yèhwih֙ mah-ţi̇ţėn-li֔⁠y wĕ⁠ʼánòki֖y hwòlé֣kĕ ʻàriyri֑y ẇ⁠ben-me֣şěq bé̇yţi֔⁠y h֖ẇʼ dȧmė֥şêq ʼèliyʻeֽzer׃"],[15,3,"וַ⁠יֹּ֣אמֶר אַבְרָ֔ם הֵ֣ן לִ֔⁠י לֹ֥א נָתַ֖תָּה זָ֑רַע וְ⁠הִנֵּ֥ה בֶן־בֵּיתִ֖⁠י יוֹרֵ֥שׁ אֹתִֽ⁠י׃","wa⁠yò֣̇ʼmer ʼabĕrá֔m hé֣n li֔⁠y lò֥ʼ náţa֖ţá̇h zá֑raʻ wĕ⁠hiné֥̇h ben-bé̇yţi֖⁠y ywòré֥ş̌ ʼòţiֽ⁠y׃"],[15,4,"וְ⁠הִנֵּ֨ה דְבַר־יְהוָ֤ה אֵלָי⁠ו֙ לֵ⁠אמֹ֔ר לֹ֥א יִֽירָשְׁ⁠ךָ֖ זֶ֑ה כִּי־אִם֙ אֲשֶׁ֣ר יֵצֵ֣א מִ⁠מֵּעֶ֔י⁠ךָ ה֖וּא יִֽירָשֶֽׁ⁠ךָ׃","wĕ⁠hiné̇֨h dĕbar-yĕhwá֤h ʼéláy⁠w֙ lé⁠ʼmò֔r lò֥ʼ yiֽyráşĕ̌⁠ká֖ ze֑h ki̇y-ʼim֙ ʼàşě֣r yéẕé֣ʼ mi⁠mé̇ʻe֔y⁠ká h֖ẇʼ yiֽyráşěֽ⁠ká׃"],[15,5,"וַ⁠יּוֹצֵ֨א אֹת֜⁠וֹ הַ⁠ח֗וּצָ⁠ה וַ⁠יֹּ֨אמֶר֙ הַבֶּט־נָ֣א הַ⁠שָּׁמַ֗יְמָ⁠ה וּ⁠סְפֹר֙ הַ⁠כּ֣וֹכָבִ֔ים אִם־תּוּכַ֖ל לִ⁠סְפֹּ֣ר אֹתָ֑⁠ם וַ⁠יֹּ֣אמֶר ל֔⁠וֹ כֹּ֥ה יִהְיֶ֖ה זַרְעֶֽ⁠ךָ׃","wa⁠ẏwòẕé֨ʼ ʼòţ֜⁠wò ha⁠ẖ֗ẇẕá⁠h wa⁠yò̇֨ʼmer֙ habėt-ná֣ʼ ha⁠şá̇̌ma֗yĕmá⁠h ẇ⁠sĕpòr֙ ha⁠k֣̇wòkábi֔ym ʼim-ţ̇ẇka֖l li⁠sĕpò֣̇r ʼòţá֑⁠m wa⁠yò֣̇ʼmer l֔⁠wò kò֥̇h yihĕye֖h zarĕʻeֽ⁠ká׃"],[15,6,"וְ⁠הֶאֱמִ֖ן בַּֽ⁠יהוָ֑ה וַ⁠יַּחְשְׁבֶ֥⁠הָ לּ֖⁠וֹ צְדָקָֽה׃","wĕ⁠heʼèmi֖n ḃֽa⁠yhwá֑h wa⁠yȧẖĕşĕ̌be֥⁠há l֖̇⁠wò ẕĕdáqáֽh׃"],[15,7,"וַ⁠יֹּ֖אמֶר אֵלָ֑י⁠ו אֲנִ֣י יְהוָ֗ה אֲשֶׁ֤ר הוֹצֵאתִ֨י⁠ךָ֙ מֵ⁠א֣וּר כַּשְׂדִּ֔ים לָ֧⁠תֶת לְ⁠ךָ֛ אֶת־הָ⁠אָ֥רֶץ הַ⁠זֹּ֖את לְ⁠רִשְׁתָּֽ⁠הּ׃","wa⁠yò֖̇ʼmer ʼélá֑y⁠w ʼàni֣y yĕhwá֗h ʼàşě֤r hwòẕéʼţi֨y⁠ká֙ mé⁠ʼ֣ẇr kȧşĕ̂di̇֔ym lá֧⁠ţeţ lĕ⁠ká֛ ʼeţ-há⁠ʼá֥reẕ ha⁠zò֖̇ʼţ lĕ⁠rişĕ̌ţáֽ̇⁠ḣ׃"],[15,8,"וַ⁠יֹּאמַ֑ר אֲדֹנָ֣⁠י יֱהוִ֔ה בַּ⁠מָּ֥ה אֵדַ֖ע כִּ֥י אִֽירָשֶֽׁ⁠נָּה׃","wa⁠yò̇ʼma֑r ʼàdòná֣⁠y yèhwi֔h bȧ⁠má֥̇h ʼéda֖ʻ ki֥̇y ʼֽiyráşěֽ⁠ná̇h׃"],[15,9,"וַ⁠יֹּ֣אמֶר אֵלָ֗י⁠ו קְחָ֥⁠ה לִ⁠י֙ עֶגְלָ֣ה מְשֻׁלֶּ֔שֶׁת וְ⁠עֵ֥ז מְשֻׁלֶּ֖שֶׁת וְ⁠אַ֣יִל מְשֻׁלָּ֑שׁ וְ⁠תֹ֖ר וְ⁠גוֹזָֽל׃","wa⁠yò֣̇ʼmer ʼélá֗y⁠w qĕẖá֥⁠h li⁠y֙ ʻegĕlá֣h mĕşǔlė֔şěţ wĕ⁠ʻé֥z mĕşǔlė֖şěţ wĕ⁠ʼa֣yil mĕşǔlá֑̇ş̌ wĕ⁠ţò֖r wĕ⁠gwòzáֽl׃"],[15,10,"וַ⁠יִּֽקַּֽח־ל֣⁠וֹ אֶת־כָּל־אֵ֗לֶּה וַ⁠יְבַתֵּ֤ר אֹתָ⁠ם֙ בַּ⁠תָּ֔וֶךְ וַ⁠יִּתֵּ֥ן אִישׁ־בִּתְר֖⁠וֹ לִ⁠קְרַ֣את רֵעֵ֑⁠הוּ וְ⁠אֶת־הַ⁠צִפֹּ֖ר לֹ֥א בָתָֽר׃","wa⁠yiֽ̇qȧֽẖ-l֣⁠wò ʼeţ-ká̇l-ʼé֗lėh wa⁠yĕbaţé֤̇r ʼòţá⁠m֙ bȧ⁠ţá̇֔wekĕ wa⁠yi̇ţé֥̇n ʼiyş̌-bi̇ţĕr֖⁠wò li⁠qĕra֣ʼţ réʻé֑⁠hẇ wĕ⁠ʼeţ-ha⁠ẕipò֖̇r lò֥ʼ báţáֽr׃"],[15,11,"וַ⁠יֵּ֥רֶד הָ⁠עַ֖יִט עַל־הַ⁠פְּגָרִ֑ים וַ⁠יַּשֵּׁ֥ב אֹתָ֖⁠ם אַבְרָֽם׃","wa⁠yé֥̇red há⁠ʻa֖yit ʻal-ha⁠pĕ̇gári֑ym wa⁠yȧşé֥̇̌b ʼòţá֖⁠m ʼabĕráֽm׃"],[15,12,"וַ⁠יְהִ֤י הַ⁠שֶּׁ֨מֶשׁ֙ לָ⁠ב֔וֹא וְ⁠תַרְדֵּמָ֖ה נָפְלָ֣ה עַל־אַבְרָ֑ם וְ⁠הִנֵּ֥ה אֵימָ֛ה חֲשֵׁכָ֥ה גְדֹלָ֖ה נֹפֶ֥לֶת עָלָֽי⁠ו׃","wa⁠yĕhi֤y ha⁠şė̌֨meş̌֙ lá⁠b֔wòʼ wĕ⁠ţarĕdé̇má֖h nápĕlá֣h ʻal-ʼabĕrá֑m wĕ⁠hiné֥̇h ʼéymá֛h ẖàşé̌ká֥h gĕdòlá֖h nòpe֥leţ ʻáláֽy⁠w׃"],[15,13,"וַ⁠יֹּ֣אמֶר לְ⁠אַבְרָ֗ם יָדֹ֨עַ תֵּדַ֜ע כִּי־גֵ֣ר ׀ יִהְיֶ֣ה זַרְעֲ⁠ךָ֗ בְּ⁠אֶ֨רֶץ֙ לֹ֣א לָ⁠הֶ֔ם וַ⁠עֲבָד֖וּ⁠ם וְ⁠עִנּ֣וּ אֹתָ֑⁠ם אַרְבַּ֥ע מֵא֖וֹת שָׁנָֽה׃","wa⁠yò֣̇ʼmer lĕ⁠ʼabĕrá֗m yádò֨ʻa ţé̇da֜ʻ ki̇y-gé֣r ׀ yihĕye֣h zarĕʻà⁠ká֗ bĕ̇⁠ʼe֨reẕ֙ lò֣ʼ lá⁠he֔m wa⁠ʻàbád֖ẇ⁠m wĕ⁠ʻiṅ֣ẇ ʼòţá֑⁠m ʼarĕbȧ֥ʻ méʼ֖wòţ şá̌náֽh׃"],[15,14,"וְ⁠גַ֧ם אֶת־הַ⁠גּ֛וֹי אֲשֶׁ֥ר יַעֲבֹ֖דוּ דָּ֣ן אָנֹ֑כִי וְ⁠אַחֲרֵי־כֵ֥ן יֵצְא֖וּ בִּ⁠רְכֻ֥שׁ גָּדֽוֹל׃","wĕ⁠ga֧m ʼeţ-ha⁠ġ֛wòy ʼàşě֥r yaʻàbò֖dẇ dá֣̇n ʼánò֑kiy wĕ⁠ʼaẖàréy-ké֥n yéẕĕʼ֖ẇ bi̇⁠rĕku֥ş̌ gá̇dֽwòl׃"],[15,15,"וְ⁠אַתָּ֛ה תָּב֥וֹא אֶל־אֲבֹתֶ֖י⁠ךָ בְּ⁠שָׁל֑וֹם תִּקָּבֵ֖ר בְּ⁠שֵׂיבָ֥ה טוֹבָֽה׃","wĕ⁠ʼaţá֛̇h ţá̇b֥wòʼ ʼel-ʼàbòţe֖y⁠ká bĕ̇⁠şá̌l֑wòm ţi̇qá̇bé֖r bĕ̇⁠şé̂ybá֥h twòbáֽh׃"],[15,16,"וְ⁠ד֥וֹר רְבִיעִ֖י יָשׁ֣וּבוּ הֵ֑נָּה כִּ֧י לֹא־שָׁלֵ֛ם עֲוֺ֥ן הָ⁠אֱמֹרִ֖י עַד־הֵֽנָּה׃","wĕ⁠d֥wòr rĕbiyʻi֖y yáş֣̌ẇbẇ hé֑ná̇h ki֧̇y lòʼ-şá̌lé֛m ʻàwֺ֥n há⁠ʼèmòri֖y ʻad-héֽná̇h׃"],[15,17,"וַ⁠יְהִ֤י הַ⁠שֶּׁ֨מֶשׁ֙ בָּ֔אָה וַ⁠עֲלָטָ֖ה הָיָ֑ה וְ⁠הִנֵּ֨ה תַנּ֤וּר עָשָׁן֙ וְ⁠לַפִּ֣יד אֵ֔שׁ אֲשֶׁ֣ר עָבַ֔ר בֵּ֖ין הַ⁠גְּזָרִ֥ים הָ⁠אֵֽלֶּה׃","wa⁠yĕhi֤y ha⁠şė̌֨meş̌֙ bá̇֔ʼáh wa⁠ʻàlátá֖h háyá֑h wĕ⁠hiné̇֨h ţaṅ֤ẇr ʻáşá̌n֙ wĕ⁠lapi֣̇yd ʼé֔ş̌ ʼàşě֣r ʻába֔r bé֖̇yn ha⁠gĕ̇zári֥ym há⁠ʼéֽlėh׃"],[15,18,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא כָּרַ֧ת יְהוָ֛ה אֶת־אַבְרָ֖ם בְּרִ֣ית לֵ⁠אמֹ֑ר לְ⁠זַרְעֲ⁠ךָ֗ נָתַ֨תִּי֙ אֶת־הָ⁠אָ֣רֶץ הַ⁠זֹּ֔את מִ⁠נְּהַ֣ר מִצְרַ֔יִם עַד־הַ⁠נָּהָ֥ר הַ⁠גָּדֹ֖ל נְהַר־פְּרָֽת׃","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ ká̇ra֧ţ yĕhwá֛h ʼeţ-ʼabĕrá֖m bĕ̇ri֣yţ lé⁠ʼmò֑r lĕ⁠zarĕʻà⁠ká֗ náţa֨ţi̇y֙ ʼeţ-há⁠ʼá֣reẕ ha⁠zò̇֔ʼţ mi⁠nĕ̇ha֣r miẕĕra֔yim ʻad-ha⁠ná̇há֥r ha⁠gá̇dò֖l nĕhar-pĕ̇ráֽţ׃"],[15,19,"אֶת־הַ⁠קֵּינִי֙ וְ⁠אֶת־הַ⁠קְּנִזִּ֔י וְ⁠אֵ֖ת הַ⁠קַּדְמֹנִֽי׃","ʼeţ-ha⁠qé̇yniy֙ wĕ⁠ʼeţ-ha⁠qĕ̇nizi̇֔y wĕ⁠ʼé֖ţ ha⁠qȧdĕmòniֽy׃"],[15,20,"וְ⁠אֶת־הַ⁠חִתִּ֥י וְ⁠אֶת־הַ⁠פְּרִזִּ֖י וְ⁠אֶת־הָ⁠רְפָאִֽים׃","wĕ⁠ʼeţ-ha⁠ẖiţi֥̇y wĕ⁠ʼeţ-ha⁠pĕ̇rizi֖̇y wĕ⁠ʼeţ-há⁠rĕpáʼiֽym׃"],[15,21,"וְ⁠אֶת־הָֽ⁠אֱמֹרִי֙ וְ⁠אֶת־הַֽ⁠כְּנַעֲנִ֔י וְ⁠אֶת־הַ⁠גִּרְגָּשִׁ֖י וְ⁠אֶת־הַ⁠יְבוּסִֽי׃ס","wĕ⁠ʼeţ-hֽá⁠ʼèmòriy֙ wĕ⁠ʼeţ-hֽa⁠kĕ̇naʻàni֔y wĕ⁠ʼeţ-ha⁠gi̇rĕgá̇şǐ֖y wĕ⁠ʼeţ-ha⁠yĕbẇsiֽy׃s"],[16,1,"וְ⁠שָׂרַי֙ אֵ֣שֶׁת אַבְרָ֔ם לֹ֥א יָלְדָ֖ה ל֑⁠וֹ וְ⁠לָ֛⁠הּ שִׁפְחָ֥ה מִצְרִ֖ית וּ⁠שְׁמָ֥⁠הּ הָגָֽר׃","wĕ⁠şá̂ray֙ ʼé֣şěţ ʼabĕrá֔m lò֥ʼ yálĕdá֖h l֑⁠wò wĕ⁠lá֛⁠ḣ şǐpĕẖá֥h miẕĕri֖yţ ẇ⁠şĕ̌má֥⁠ḣ hágáֽr׃"],[16,2,"וַ⁠תֹּ֨אמֶר שָׂרַ֜י אֶל־אַבְרָ֗ם הִנֵּה־נָ֞א עֲצָרַ֤⁠נִי יְהוָה֙ מִ⁠לֶּ֔דֶת בֹּא־נָא֙ אֶל־שִׁפְחָתִ֔⁠י אוּלַ֥י אִבָּנֶ֖ה מִמֶּ֑⁠נָּה וַ⁠יִּשְׁמַ֥ע אַבְרָ֖ם לְ⁠ק֥וֹל שָׂרָֽי׃","wa⁠ţò̇֨ʼmer şá̂ra֜y ʼel-ʼabĕrá֗m hiné̇h-ná֞ʼ ʻàẕára֤⁠niy yĕhwáh֙ mi⁠lė֔deţ bò̇ʼ-náʼ֙ ʼel-şǐpĕẖáţi֔⁠y ʼẇla֥y ʼibá̇ne֖h mimė֑⁠ná̇h wa⁠yi̇şĕ̌ma֥ʻ ʼabĕrá֖m lĕ⁠q֥wòl şá̂ráֽy׃"],[16,3,"וַ⁠תִּקַּ֞ח שָׂרַ֣י אֵֽשֶׁת־אַבְרָ֗ם אֶת־הָגָ֤ר הַ⁠מִּצְרִית֙ שִׁפְחָתָ֔⁠הּ מִ⁠קֵּץ֙ עֶ֣שֶׂר שָׁנִ֔ים לְ⁠שֶׁ֥בֶת אַבְרָ֖ם בְּ⁠אֶ֣רֶץ כְּנָ֑עַן וַ⁠תִּתֵּ֥ן אֹתָ֛⁠הּ לְ⁠אַבְרָ֥ם אִישָׁ֖⁠הּ ל֥⁠וֹ לְ⁠אִשָּֽׁה׃","wa⁠ţi̇qȧ֞ẖ şá̂ra֣y ʼéֽşěţ-ʼabĕrá֗m ʼeţ-hágá֤r ha⁠mi̇ẕĕriyţ֙ şǐpĕẖáţá֔⁠ḣ mi⁠qé̇ẕ֙ ʻe֣şêr şá̌ni֔ym lĕ⁠şě֥beţ ʼabĕrá֖m bĕ̇⁠ʼe֣reẕ kĕ̇ná֑ʻan wa⁠ţi̇ţé֥̇n ʼòţá֛⁠ḣ lĕ⁠ʼabĕrá֥m ʼiyşá֖̌⁠ḣ l֥⁠wò lĕ⁠ʼişáֽ̇̌h׃"],[16,4,"וַ⁠יָּבֹ֥א אֶל־הָגָ֖ר וַ⁠תַּ֑הַר וַ⁠תֵּ֨רֶא֙ כִּ֣י הָרָ֔תָה וַ⁠תֵּקַ֥ל גְּבִרְתָּ֖⁠הּ בְּ⁠עֵינֶֽי⁠הָ׃","wa⁠yá̇bò֥ʼ ʼel-hágá֖r wa⁠ţȧ֑har wa⁠ţé̇֨reʼ֙ ki֣̇y hárá֔ţáh wa⁠ţé̇qa֥l gĕ̇birĕţá֖̇⁠ḣ bĕ̇⁠ʻéyneֽy⁠há׃"],[16,5,"וַ⁠תֹּ֨אמֶר שָׂרַ֣י אֶל־אַבְרָם֮ חֲמָסִ֣⁠י עָלֶי⁠ךָ֒ אָנֹכִ֗י נָתַ֤תִּי שִׁפְחָתִ⁠י֙ בְּ⁠חֵיקֶ֔⁠ךָ וַ⁠תֵּ֨רֶא֙ כִּ֣י הָרָ֔תָה וָ⁠אֵקַ֖ל בְּ⁠עֵינֶ֑י⁠הָ יִשְׁפֹּ֥ט יְהוָ֖ה בֵּינִ֥⁠י וּ⁠בֵינֶֽיׄ⁠ךָ׃","wa⁠ţò̇֨ʼmer şá̂ra֣y ʼel-ʼabĕrám֮ ẖàmási֣⁠y ʻáley⁠ká֒ ʼánòki֗y náţa֤ţi̇y şǐpĕẖáţi⁠y֙ bĕ̇⁠ẖéyqe֔⁠ká wa⁠ţé̇֨reʼ֙ ki֣̇y hárá֔ţáh wá⁠ʼéqa֖l bĕ̇⁠ʻéyne֑y⁠há yişĕ̌pò֥̇t yĕhwá֖h bé̇yni֥⁠y ẇ⁠béyneֽyׄ⁠ká׃"],[16,6,"וַ⁠יֹּ֨אמֶר אַבְרָ֜ם אֶל־שָׂרַ֗י הִנֵּ֤ה שִׁפְחָתֵ⁠ךְ֙ בְּ⁠יָדֵ֔⁠ךְ עֲשִׂי־לָ֖⁠הּ הַ⁠טּ֣וֹב בְּ⁠עֵינָ֑יִ⁠ךְ וַ⁠תְּעַנֶּ֣⁠הָ שָׂרַ֔י וַ⁠תִּבְרַ֖ח מִ⁠פָּנֶֽי⁠הָ׃","wa⁠yò̇֨ʼmer ʼabĕrá֜m ʼel-şá̂ra֗y hiné֤̇h şǐpĕẖáţé⁠kĕ֙ bĕ̇⁠yádé֔⁠kĕ ʻàşîy-lá֖⁠ḣ ha⁠ṫ֣wòb bĕ̇⁠ʻéyná֑yi⁠kĕ wa⁠ţĕ̇ʻanė֣⁠há şá̂ra֔y wa⁠ţi̇bĕra֖ẖ mi⁠pá̇neֽy⁠há׃"],[16,7,"וַֽ⁠יִּמְצָאָ֞⁠הּ מַלְאַ֧ךְ יְהוָ֛ה עַל־עֵ֥ין הַ⁠מַּ֖יִם בַּ⁠מִּדְבָּ֑ר עַל־הָ⁠עַ֖יִן בְּ⁠דֶ֥רֶךְ שֽׁוּר׃","waֽ⁠yi̇mĕẕáʼá֞⁠ḣ malĕʼa֧kĕ yĕhwá֛h ʻal-ʻé֥yn ha⁠mȧ֖yim bȧ⁠mi̇dĕbá֑̇r ʻal-há⁠ʻa֖yin bĕ̇⁠de֥rekĕ şֽ̌ẇr׃"],[16,8,"וַ⁠יֹּאמַ֗ר הָגָ֞ר שִׁפְחַ֥ת שָׂרַ֛י אֵֽי־מִ⁠זֶּ֥ה בָ֖את וְ⁠אָ֣נָה תֵלֵ֑כִי וַ⁠תֹּ֕אמֶר מִ⁠פְּנֵי֙ שָׂרַ֣י גְּבִרְתִּ֔⁠י אָנֹכִ֖י בֹּרַֽחַת׃","wa⁠yò̇ʼma֗r hágá֞r şǐpĕẖa֥ţ şá̂ra֛y ʼéֽy-mi⁠zė֥h bá֖ʼţ wĕ⁠ʼá֣náh ţélé֑kiy wa⁠ţò̇֕ʼmer mi⁠pĕ̇néy֙ şá̂ra֣y gĕ̇birĕţi̇֔⁠y ʼánòki֖y bò̇raֽẖaţ׃"],[16,9,"וַ⁠יֹּ֤אמֶר לָ⁠הּ֙ מַלְאַ֣ךְ יְהוָ֔ה שׁ֖וּבִי אֶל־גְּבִרְתֵּ֑⁠ךְ וְ⁠הִתְעַנִּ֖י תַּ֥חַת יָדֶֽי⁠הָ׃","wa⁠yò֤̇ʼmer lá⁠ḣ֙ malĕʼa֣kĕ yĕhwá֔h ş֖̌ẇbiy ʼel-gĕ̇birĕţé֑̇⁠kĕ wĕ⁠hiţĕʻani֖̇y ţȧ֥ẖaţ yádeֽy⁠há׃"],[16,10,"וַ⁠יֹּ֤אמֶר לָ⁠הּ֙ מַלְאַ֣ךְ יְהוָ֔ה הַרְבָּ֥ה אַרְבֶּ֖ה אֶת־זַרְעֵ֑⁠ךְ וְ⁠לֹ֥א יִסָּפֵ֖ר מֵ⁠רֹֽב׃","wa⁠yò֤̇ʼmer lá⁠ḣ֙ malĕʼa֣kĕ yĕhwá֔h harĕbá֥̇h ʼarĕbė֖h ʼeţ-zarĕʻé֑⁠kĕ wĕ⁠lò֥ʼ yisá̇pé֖r mé⁠ròֽb׃"],[16,11,"וַ⁠יֹּ֤אמֶר לָ⁠הּ֙ מַלְאַ֣ךְ יְהוָ֔ה הִנָּ֥⁠ךְ הָרָ֖ה וְ⁠יֹלַ֣דְתְּ בֵּ֑ן וְ⁠קָרָ֤את שְׁמ⁠וֹ֙ יִשְׁמָעֵ֔אל כִּֽי־שָׁמַ֥ע יְהוָ֖ה אֶל־עָנְיֵֽ⁠ךְ׃","wa⁠yò֤̇ʼmer lá⁠ḣ֙ malĕʼa֣kĕ yĕhwá֔h hiná֥̇⁠kĕ hárá֖h wĕ⁠yòla֣dĕţĕ̇ bé֑̇n wĕ⁠qárá֤ʼţ şĕ̌m⁠wò֙ yişĕ̌máʻé֔ʼl kiֽ̇y-şá̌ma֥ʻ yĕhwá֖h ʼel-ʻánĕyéֽ⁠kĕ׃"],[16,12,"וְ⁠ה֤וּא יִהְיֶה֙ פֶּ֣רֶא אָדָ֔ם יָד֣⁠וֹ בַ⁠כֹּ֔ל וְ⁠יַ֥ד כֹּ֖ל בּ֑⁠וֹ וְ⁠עַל־פְּנֵ֥י כָל־אֶחָ֖י⁠ו יִשְׁכֹּֽן׃","wĕ⁠h֤ẇʼ yihĕyeh֙ pė֣reʼ ʼádá֔m yád֣⁠wò ba⁠kò̇֔l wĕ⁠ya֥d kò֖̇l ḃ֑⁠wò wĕ⁠ʻal-pĕ̇né֥y kál-ʼeẖá֖y⁠w yişĕ̌kòֽ̇n׃"],[16,13,"וַ⁠תִּקְרָ֤א שֵׁם־יְהוָה֙ הַ⁠דֹּבֵ֣ר אֵלֶ֔י⁠הָ אַתָּ֖ה אֵ֣ל רֳאִ֑י כִּ֣י אָֽמְרָ֗ה הֲ⁠גַ֥ם הֲלֹ֛ם רָאִ֖יתִי אַחֲרֵ֥י רֹאִֽ⁠י׃","wa⁠ţi̇qĕrá֤ʼ şé̌m-yĕhwáh֙ ha⁠dò̇bé֣r ʼéle֔y⁠há ʼaţá֖̇h ʼé֣l roʼi֑y ki֣̇y ʼֽámĕrá֗h hà⁠ga֥m hàlò֛m ráʼi֖yţiy ʼaẖàré֥y ròʼiֽ⁠y׃"],[16,14,"עַל־כֵּן֙ קָרָ֣א לַ⁠בְּאֵ֔ר בְּאֵ֥ר לַחַ֖י רֹאִ֑י הִנֵּ֥ה בֵין־קָדֵ֖שׁ וּ⁠בֵ֥ין בָּֽרֶד׃","ʻal-ké̇n֙ qárá֣ʼ la⁠bĕ̇ʼé֔r bĕ̇ʼé֥r laẖa֖y ròʼi֑y hiné֥̇h béyn-qádé֖ş̌ ẇ⁠bé֥yn báֽ̇red׃"],[16,15,"וַ⁠תֵּ֧לֶד הָגָ֛ר לְ⁠אַבְרָ֖ם בֵּ֑ן וַ⁠יִּקְרָ֨א אַבְרָ֧ם שֶׁם־בְּנ֛⁠וֹ אֲשֶׁר־יָלְדָ֥ה הָגָ֖ר יִשְׁמָעֵֽאל׃","wa⁠ţé֧̇led hágá֛r lĕ⁠ʼabĕrá֖m bé֑̇n wa⁠yi̇qĕrá֨ʼ ʼabĕrá֧m şěm-bĕ̇n֛⁠wò ʼàşěr-yálĕdá֥h hágá֖r yişĕ̌máʻéֽʼl׃"],[16,16,"וְ⁠אַבְרָ֕ם בֶּן־שְׁמֹנִ֥ים שָׁנָ֖ה וְ⁠שֵׁ֣שׁ שָׁנִ֑ים בְּ⁠לֶֽדֶת־הָגָ֥ר אֶת־יִשְׁמָעֵ֖אל לְ⁠אַבְרָֽם׃ס","wĕ⁠ʼabĕrá֕m bėn-şĕ̌mòni֥ym şá̌ná֖h wĕ⁠şé֣̌ş̌ şá̌ni֑ym bĕ̇⁠leֽdeţ-hágá֥r ʼeţ-yişĕ̌máʻé֖ʼl lĕ⁠ʼabĕráֽm׃s"],[17,1,"וַ⁠יְהִ֣י אַבְרָ֔ם בֶּן־תִּשְׁעִ֥ים שָׁנָ֖ה וְ⁠תֵ֣שַׁע שָׁנִ֑ים וַ⁠יֵּרָ֨א יְהוָ֜ה אֶל־אַבְרָ֗ם וַ⁠יֹּ֤אמֶר אֵלָי⁠ו֙ אֲנִי־אֵ֣ל שַׁדַּ֔י הִתְהַלֵּ֥ךְ לְ⁠פָנַ֖⁠י וֶ⁠הְיֵ֥ה תָמִֽים׃","wa⁠yĕhi֣y ʼabĕrá֔m bėn-ţi̇şĕ̌ʻi֥ym şá̌ná֖h wĕ⁠ţé֣şǎʻ şá̌ni֑ym wa⁠yé̇rá֨ʼ yĕhwá֜h ʼel-ʼabĕrá֗m wa⁠yò֤̇ʼmer ʼéláy⁠w֙ ʼàniy-ʼé֣l şǎdȧ֔y hiţĕhalé֥̇kĕ lĕ⁠pána֖⁠y we⁠hĕyé֥h ţámiֽym׃"],[17,2,"וְ⁠אֶתְּנָ֥ה בְרִיתִ֖⁠י בֵּינִ֣⁠י וּ⁠בֵינֶ֑⁠ךָ וְ⁠אַרְבֶּ֥ה אוֹתְ⁠ךָ֖ בִּ⁠מְאֹ֥ד מְאֹֽד׃","wĕ⁠ʼeţĕ̇ná֥h bĕriyţi֖⁠y bé̇yni֣⁠y ẇ⁠béyne֑⁠ká wĕ⁠ʼarĕbė֥h ʼwòţĕ⁠ká֖ bi̇⁠mĕʼò֥d mĕʼòֽd׃"],[17,3,"וַ⁠יִּפֹּ֥ל אַבְרָ֖ם עַל־פָּנָ֑י⁠ו וַ⁠יְדַבֵּ֥ר אִתּ֛⁠וֹ אֱלֹהִ֖ים לֵ⁠אמֹֽר׃","wa⁠yi̇pò֥̇l ʼabĕrá֖m ʻal-pá̇ná֑y⁠w wa⁠yĕdabé֥̇r ʼiţ֛̇⁠wò ʼèlòhi֖ym lé⁠ʼmòֽr׃"],[17,4,"אֲנִ֕י הִנֵּ֥ה בְרִיתִ֖⁠י אִתָּ֑⁠ךְ וְ⁠הָיִ֕יתָ לְ⁠אַ֖ב הֲמ֥וֹן גּוֹיִֽם׃","ʼàni֕y hiné֥̇h bĕriyţi֖⁠y ʼiţá֑̇⁠kĕ wĕ⁠háyi֕yţá lĕ⁠ʼa֖b hàm֥wòn ġwòyiֽm׃"],[17,5,"וְ⁠לֹא־יִקָּרֵ֥א ע֛וֹד אֶת־שִׁמְ⁠ךָ֖ אַבְרָ֑ם וְ⁠הָיָ֤ה שִׁמְ⁠ךָ֙ אַבְרָהָ֔ם כִּ֛י אַב־הֲמ֥וֹן גּוֹיִ֖ם נְתַתִּֽי⁠ךָ׃","wĕ⁠lòʼ-yiqá̇ré֥ʼ ʻ֛wòd ʼeţ-şǐmĕ⁠ká֖ ʼabĕrá֑m wĕ⁠háyá֤h şǐmĕ⁠ká֙ ʼabĕráhá֔m ki֛̇y ʼab-hàm֥wòn ġwòyi֖m nĕţaţiֽ̇y⁠ká׃"],[17,6,"וְ⁠הִפְרֵתִ֤י אֹֽתְ⁠ךָ֙ בִּ⁠מְאֹ֣ד מְאֹ֔ד וּ⁠נְתַתִּ֖י⁠ךָ לְ⁠גוֹיִ֑ם וּ⁠מְלָכִ֖ים מִמְּ⁠ךָ֥ יֵצֵֽאוּ׃","wĕ⁠hipĕréţi֤y ʼòֽţĕ⁠ká֙ bi̇⁠mĕʼò֣d mĕʼò֔d ẇ⁠nĕţaţi֖̇y⁠ká lĕ⁠gwòyi֑m ẇ⁠mĕláki֖ym mimĕ̇⁠ká֥ yéẕéֽʼẇ׃"],[17,7,"וַ⁠הֲקִמֹתִ֨י אֶת־בְּרִיתִ֜⁠י בֵּינִ֣⁠י וּ⁠בֵינֶ֗⁠ךָ וּ⁠בֵ֨ין זַרְעֲ⁠ךָ֧ אַחֲרֶ֛י⁠ךָ לְ⁠דֹרֹתָ֖⁠ם לִ⁠בְרִ֣ית עוֹלָ֑ם לִ⁠הְי֤וֹת לְ⁠ךָ֙ לֵֽ⁠אלֹהִ֔ים וּֽ⁠לְ⁠זַרְעֲ⁠ךָ֖ אַחֲרֶֽי⁠ךָ׃","wa⁠hàqimòţi֨y ʼeţ-bĕ̇riyţi֜⁠y bé̇yni֣⁠y ẇ⁠béyne֗⁠ká ẇ⁠bé֨yn zarĕʻà⁠ká֧ ʼaẖàre֛y⁠ká lĕ⁠dòròţá֖⁠m li⁠bĕri֣yţ ʻwòlá֑m li⁠hĕy֤wòţ lĕ⁠ká֙ léֽ⁠ʼlòhi֔ym ẇֽ⁠lĕ⁠zarĕʻà⁠ká֖ ʼaẖàreֽy⁠ká׃"],[17,8,"וְ⁠נָתַתִּ֣י לְ֠⁠ךָ וּ⁠לְ⁠זַרְעֲ⁠ךָ֨ אַחֲרֶ֜י⁠ךָ אֵ֣ת ׀ אֶ֣רֶץ מְגֻרֶ֗י⁠ךָ אֵ֚ת כָּל־אֶ֣רֶץ כְּנַ֔עַן לַ⁠אֲחֻזַּ֖ת עוֹלָ֑ם וְ⁠הָיִ֥יתִי לָ⁠הֶ֖ם לֵ⁠אלֹהִֽים׃","wĕ⁠náţaţi֣̇y lĕ֠⁠ká ẇ⁠lĕ⁠zarĕʻà⁠ká֨ ʼaẖàre֜y⁠ká ʼé֣ţ ׀ ʼe֣reẕ mĕgure֗y⁠ká ʼé֚ţ ká̇l-ʼe֣reẕ kĕ̇na֔ʻan la⁠ʼàẖuzȧ֖ţ ʻwòlá֑m wĕ⁠háyi֥yţiy lá⁠he֖m lé⁠ʼlòhiֽym׃"],[17,9,"וַ⁠יֹּ֤אמֶר אֱלֹהִים֙ אֶל־אַבְרָהָ֔ם וְ⁠אַתָּ֖ה אֶת־בְּרִיתִ֣⁠י תִשְׁמֹ֑ר אַתָּ֛ה וְ⁠זַרְעֲ⁠ךָ֥ אַֽחֲרֶ֖י⁠ךָ לְ⁠דֹרֹתָֽ⁠ם׃","wa⁠yò֤̇ʼmer ʼèlòhiym֙ ʼel-ʼabĕráhá֔m wĕ⁠ʼaţá֖̇h ʼeţ-bĕ̇riyţi֣⁠y ţişĕ̌mò֑r ʼaţá֛̇h wĕ⁠zarĕʻà⁠ká֥ ʼֽaẖàre֖y⁠ká lĕ⁠dòròţáֽ⁠m׃"],[17,10,"זֹ֣את בְּרִיתִ֞⁠י אֲשֶׁ֣ר תִּשְׁמְר֗וּ בֵּינִ⁠י֙ וּ⁠בֵ֣ינֵי⁠כֶ֔ם וּ⁠בֵ֥ין זַרְעֲ⁠ךָ֖ אַחֲרֶ֑י⁠ךָ הִמּ֥וֹל לָ⁠כֶ֖ם כָּל־זָכָֽר׃","zò֣ʼţ bĕ̇riyţi֞⁠y ʼàşě֣r ţi̇şĕ̌mĕr֗ẇ bé̇yni⁠y֙ ẇ⁠bé֣ynéy⁠ke֔m ẇ⁠bé֥yn zarĕʻà⁠ká֖ ʼaẖàre֑y⁠ká hiṁ֥wòl lá⁠ke֖m ká̇l-zákáֽr׃"],[17,11,"וּ⁠נְמַלְתֶּ֕ם אֵ֖ת בְּשַׂ֣ר עָרְלַתְ⁠כֶ֑ם וְ⁠הָיָה֙ לְ⁠א֣וֹת בְּרִ֔ית בֵּינִ֖⁠י וּ⁠בֵינֵי⁠כֶֽם׃","ẇ⁠nĕmalĕţė֕m ʼé֖ţ bĕ̇şâ֣r ʻárĕlaţĕ⁠ke֑m wĕ⁠háyáh֙ lĕ⁠ʼ֣wòţ bĕ̇ri֔yţ bé̇yni֖⁠y ẇ⁠béynéy⁠keֽm׃"],[17,12,"וּ⁠בֶן־שְׁמֹנַ֣ת יָמִ֗ים יִמּ֥וֹל לָ⁠כֶ֛ם כָּל־זָכָ֖ר לְ⁠דֹרֹתֵי⁠כֶ֑ם יְלִ֣יד בָּ֔יִת וּ⁠מִקְנַת־כֶּ֨סֶף֙ מִ⁠כֹּ֣ל בֶּן־נֵכָ֔ר אֲשֶׁ֛ר לֹ֥א מִֽ⁠זַּרְעֲ⁠ךָ֖ הֽוּא׃","ẇ⁠ben-şĕ̌mòna֣ţ yámi֗ym yiṁ֥wòl lá⁠ke֛m ká̇l-záká֖r lĕ⁠dòròţéy⁠ke֑m yĕli֣yd bá̇֔yiţ ẇ⁠miqĕnaţ-kė֨sep֙ mi⁠kò֣̇l bėn-néká֔r ʼàşě֛r lò֥ʼ miֽ⁠zȧrĕʻà⁠ká֖ hֽẇʼ׃"],[17,13,"הִמּ֧וֹל ׀ יִמּ֛וֹל יְלִ֥יד בֵּֽיתְ⁠ךָ֖ וּ⁠מִקְנַ֣ת כַּסְפֶּ֑⁠ךָ וְ⁠הָיְתָ֧ה בְרִיתִ֛⁠י בִּ⁠בְשַׂרְ⁠כֶ֖ם לִ⁠בְרִ֥ית עוֹלָֽם׃","hiṁ֧wòl ׀ yiṁ֛wòl yĕli֥yd ḃֽéyţĕ⁠ká֖ ẇ⁠miqĕna֣ţ kȧsĕpė֑⁠ká wĕ⁠háyĕţá֧h bĕriyţi֛⁠y bi̇⁠bĕşârĕ⁠ke֖m li⁠bĕri֥yţ ʻwòláֽm׃"],[17,14,"וְ⁠עָרֵ֣ל ׀ זָכָ֗ר אֲשֶׁ֤ר לֹֽא־יִמּוֹל֙ אֶת־בְּשַׂ֣ר עָרְלָת֔⁠וֹ וְ⁠נִכְרְתָ֛ה הַ⁠נֶּ֥פֶשׁ הַ⁠הִ֖וא מֵ⁠עַמֶּ֑י⁠הָ אֶת־בְּרִיתִ֖⁠י הֵפַֽר׃ס","wĕ⁠ʻáré֣l ׀ záká֗r ʼàşě֤r lòֽʼ-yiṁwòl֙ ʼeţ-bĕ̇şâ֣r ʻárĕláţ֔⁠wò wĕ⁠nikĕrĕţá֛h ha⁠nė֥peş̌ ha⁠hi֖wʼ mé⁠ʻamė֑y⁠há ʼeţ-bĕ̇riyţi֖⁠y hépaֽr׃s"],[17,15,"וַ⁠יֹּ֤אמֶר אֱלֹהִים֙ אֶל־אַבְרָהָ֔ם שָׂרַ֣י אִשְׁתְּ⁠ךָ֔ לֹא־תִקְרָ֥א אֶת־שְׁמָ֖⁠הּ שָׂרָ֑י כִּ֥י שָׂרָ֖ה שְׁמָֽ⁠הּ׃","wa⁠yò֤̇ʼmer ʼèlòhiym֙ ʼel-ʼabĕráhá֔m şá̂ra֣y ʼişĕ̌ţĕ̇⁠ká֔ lòʼ-ţiqĕrá֥ʼ ʼeţ-şĕ̌má֖⁠ḣ şá̂rá֑y ki֥̇y şá̂rá֖h şĕ̌máֽ⁠ḣ׃"],[17,16,"וּ⁠בֵרַכְתִּ֣י אֹתָ֔⁠הּ וְ⁠גַ֨ם נָתַ֧תִּי מִמֶּ֛⁠נָּה לְ⁠ךָ֖ בֵּ֑ן וּ⁠בֵֽרַכְתִּ֨י⁠הָ֙ וְ⁠הָֽיְתָ֣ה לְ⁠גוֹיִ֔ם מַלְכֵ֥י עַמִּ֖ים מִמֶּ֥⁠נָּה יִהְיֽוּ׃","ẇ⁠bérakĕţi֣̇y ʼòţá֔⁠ḣ wĕ⁠ga֨m náţa֧ţi̇y mimė֛⁠ná̇h lĕ⁠ká֖ bé֑̇n ẇ⁠béֽrakĕţi̇֨y⁠há֙ wĕ⁠háֽyĕţá֣h lĕ⁠gwòyi֔m malĕké֥y ʻami֖̇ym mimė֥⁠ná̇h yihĕyֽẇ׃"],[17,17,"וַ⁠יִּפֹּ֧ל אַבְרָהָ֛ם עַל־פָּנָ֖י⁠ו וַ⁠יִּצְחָ֑ק וַ⁠יֹּ֣אמֶר בְּ⁠לִבּ֗⁠וֹ הַ⁠לְּ⁠בֶ֤ן מֵאָֽה־שָׁנָה֙ יִוָּלֵ֔ד וְ⁠אִ֨ם־שָׂרָ֔ה הֲ⁠בַת־תִּשְׁעִ֥ים שָׁנָ֖ה תֵּלֵֽד׃","wa⁠yi̇pò֧̇l ʼabĕráhá֛m ʻal-pá̇ná֖y⁠w wa⁠yi̇ẕĕẖá֑q wa⁠yò֣̇ʼmer bĕ̇⁠liḃ֗⁠wò ha⁠lĕ̇⁠be֤n méʼáֽh-şá̌náh֙ yiwá̇lé֔d wĕ⁠ʼi֨m-şá̂rá֔h hà⁠baţ-ţi̇şĕ̌ʻi֥ym şá̌ná֖h ţé̇léֽd׃"],[17,18,"וַ⁠יֹּ֥אמֶר אַבְרָהָ֖ם אֶל־הָֽ⁠אֱלֹהִ֑ים ל֥וּ יִשְׁמָעֵ֖אל יִחְיֶ֥ה לְ⁠פָנֶֽי⁠ךָ׃","wa⁠yò֥̇ʼmer ʼabĕráhá֖m ʼel-hֽá⁠ʼèlòhi֑ym l֥ẇ yişĕ̌máʻé֖ʼl yiẖĕye֥h lĕ⁠páneֽy⁠ká׃"],[17,19,"וַ⁠יֹּ֣אמֶר אֱלֹהִ֗ים אֲבָל֙ שָׂרָ֣ה אִשְׁתְּ⁠ךָ֗ יֹלֶ֤דֶת לְ⁠ךָ֙ בֵּ֔ן וְ⁠קָרָ֥אתָ אֶת־שְׁמ֖⁠וֹ יִצְחָ֑ק וַ⁠הֲקִמֹתִ֨י אֶת־בְּרִיתִ֥⁠י אִתּ֛⁠וֹ לִ⁠בְרִ֥ית עוֹלָ֖ם לְ⁠זַרְע֥⁠וֹ אַחֲרָֽי⁠ו׃","wa⁠yò֣̇ʼmer ʼèlòhi֗ym ʼàbál֙ şá̂rá֣h ʼişĕ̌ţĕ̇⁠ká֗ yòle֤deţ lĕ⁠ká֙ bé̇֔n wĕ⁠qárá֥ʼţá ʼeţ-şĕ̌m֖⁠wò yiẕĕẖá֑q wa⁠hàqimòţi֨y ʼeţ-bĕ̇riyţi֥⁠y ʼiţ֛̇⁠wò li⁠bĕri֥yţ ʻwòlá֖m lĕ⁠zarĕʻ֥⁠wò ʼaẖàráֽy⁠w׃"],[17,20,"וּֽ⁠לְ⁠יִשְׁמָעֵ֘אל שְׁמַעְתִּי⁠ךָ֒ הִנֵּ֣ה ׀ בֵּרַ֣כְתִּי אֹת֗⁠וֹ וְ⁠הִפְרֵיתִ֥י אֹת֛⁠וֹ וְ⁠הִרְבֵּיתִ֥י אֹת֖⁠וֹ בִּ⁠מְאֹ֣ד מְאֹ֑ד שְׁנֵים־עָשָׂ֤ר נְשִׂיאִם֙ יוֹלִ֔יד וּ⁠נְתַתִּ֖י⁠ו לְ⁠ג֥וֹי גָּדֽוֹל׃","ẇֽ⁠lĕ⁠yişĕ̌máʻé֘ʼl şĕ̌maʻĕţi̇y⁠ká֒ hiné֣̇h ׀ bé̇ra֣kĕţi̇y ʼòţ֗⁠wò wĕ⁠hipĕréyţi֥y ʼòţ֛⁠wò wĕ⁠hirĕbé̇yţi֥y ʼòţ֖⁠wò bi̇⁠mĕʼò֣d mĕʼò֑d şĕ̌néym-ʻáşá֤̂r nĕşîyʼim֙ ywòli֔yd ẇ⁠nĕţaţi֖̇y⁠w lĕ⁠g֥wòy gá̇dֽwòl׃"],[17,21,"וְ⁠אֶת־בְּרִיתִ֖⁠י אָקִ֣ים אֶת־יִצְחָ֑ק אֲשֶׁר֩ תֵּלֵ֨ד לְ⁠ךָ֤ שָׂרָה֙ לַ⁠מּוֹעֵ֣ד הַ⁠זֶּ֔ה בַּ⁠שָּׁנָ֖ה הָ⁠אַחֶֽרֶת׃","wĕ⁠ʼeţ-bĕ̇riyţi֖⁠y ʼáqi֣ym ʼeţ-yiẕĕẖá֑q ʼàşěr֩ ţé̇lé֨d lĕ⁠ká֤ şá̂ráh֙ la⁠ṁwòʻé֣d ha⁠zė֔h bȧ⁠şá̇̌ná֖h há⁠ʼaẖeֽreţ׃"],[17,22,"וַ⁠יְכַ֖ל לְ⁠דַבֵּ֣ר אִתּ֑⁠וֹ וַ⁠יַּ֣עַל אֱלֹהִ֔ים מֵ⁠עַ֖ל אַבְרָהָֽם׃","wa⁠yĕka֖l lĕ⁠dabé֣̇r ʼiţ֑̇⁠wò wa⁠yȧ֣ʻal ʼèlòhi֔ym mé⁠ʻa֖l ʼabĕráháֽm׃"],[17,23,"וַ⁠יִּקַּ֨ח אַבְרָהָ֜ם אֶת־יִשְׁמָעֵ֣אל בְּנ֗⁠וֹ וְ⁠אֵ֨ת כָּל־יְלִידֵ֤י בֵית⁠וֹ֙ וְ⁠אֵת֙ כָּל־מִקְנַ֣ת כַּסְפּ֔⁠וֹ כָּל־זָכָ֕ר בְּ⁠אַנְשֵׁ֖י בֵּ֣ית אַבְרָהָ֑ם וַ⁠יָּ֜מָל אֶת־בְּשַׂ֣ר עָרְלָתָ֗⁠ם בְּ⁠עֶ֨צֶם֙ הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה כַּ⁠אֲשֶׁ֛ר דִּבֶּ֥ר אִתּ֖⁠וֹ אֱלֹהִֽים׃","wa⁠yi̇qȧ֨ẖ ʼabĕráhá֜m ʼeţ-yişĕ̌máʻé֣ʼl bĕ̇n֗⁠wò wĕ⁠ʼé֨ţ ká̇l-yĕliydé֤y béyţ⁠wò֙ wĕ⁠ʼéţ֙ ká̇l-miqĕna֣ţ kȧsĕṗ֔⁠wò ká̇l-záká֕r bĕ̇⁠ʼanĕşé֖̌y bé֣̇yţ ʼabĕráhá֑m wa⁠yá̇֜mál ʼeţ-bĕ̇şâ֣r ʻárĕláţá֗⁠m bĕ̇⁠ʻe֨ẕem֙ ha⁠ẏ֣wòm ha⁠zė֔h kȧ⁠ʼàşě֛r di̇bė֥r ʼiţ֖̇⁠wò ʼèlòhiֽym׃"],[17,24,"וְ⁠אַ֨בְרָהָ֔ם בֶּן־תִּשְׁעִ֥ים וָ⁠תֵ֖שַׁע שָׁנָ֑ה בְּ⁠הִמֹּל֖⁠וֹ בְּשַׂ֥ר עָרְלָתֽ⁠וֹ׃","wĕ⁠ʼa֨bĕráhá֔m bėn-ţi̇şĕ̌ʻi֥ym wá⁠ţé֖şǎʻ şá̌ná֑h bĕ̇⁠himò̇l֖⁠wò bĕ̇şâ֥r ʻárĕláţֽ⁠wò׃"],[17,25,"וְ⁠יִשְׁמָעֵ֣אל בְּנ֔⁠וֹ בֶּן־שְׁלֹ֥שׁ עֶשְׂרֵ֖ה שָׁנָ֑ה בְּ⁠הִ֨מֹּל֔⁠וֹ אֵ֖ת בְּשַׂ֥ר עָרְלָתֽ⁠וֹ׃","wĕ⁠yişĕ̌máʻé֣ʼl bĕ̇n֔⁠wò bėn-şĕ̌lò֥ş̌ ʻeşĕ̂ré֖h şá̌ná֑h bĕ̇⁠hi֨mò̇l֔⁠wò ʼé֖ţ bĕ̇şâ֥r ʻárĕláţֽ⁠wò׃"],[17,26,"בְּ⁠עֶ֨צֶם֙ הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה נִמּ֖וֹל אַבְרָהָ֑ם וְ⁠יִשְׁמָעֵ֖אל בְּנֽ⁠וֹ׃","bĕ̇⁠ʻe֨ẕem֙ ha⁠ẏ֣wòm ha⁠zė֔h niṁ֖wòl ʼabĕráhá֑m wĕ⁠yişĕ̌máʻé֖ʼl bĕ̇nֽ⁠wò׃"],[17,27,"וְ⁠כָל־אַנְשֵׁ֤י בֵית⁠וֹ֙ יְלִ֣יד בָּ֔יִת וּ⁠מִקְנַת־כֶּ֖סֶף מֵ⁠אֵ֣ת בֶּן־נֵכָ֑ר נִמֹּ֖לוּ אִתּֽ⁠וֹ׃פ","wĕ⁠kál-ʼanĕşé֤̌y béyţ⁠wò֙ yĕli֣yd bá̇֔yiţ ẇ⁠miqĕnaţ-kė֖sep mé⁠ʼé֣ţ bėn-néká֑r nimò֖̇lẇ ʼiţֽ̇⁠wò׃p"],[18,1,"וַ⁠יֵּרָ֤א אֵלָי⁠ו֙ יְהוָ֔ה בְּ⁠אֵלֹנֵ֖י מַמְרֵ֑א וְ⁠ה֛וּא יֹשֵׁ֥ב פֶּֽתַח־הָ⁠אֹ֖הֶל כְּ⁠חֹ֥ם הַ⁠יּֽוֹם׃","wa⁠yé̇rá֤ʼ ʼéláy⁠w֙ yĕhwá֔h bĕ̇⁠ʼélòné֖y mamĕré֑ʼ wĕ⁠h֛ẇʼ yòşé֥̌b pėֽţaẖ-há⁠ʼò֖hel kĕ̇⁠ẖò֥m ha⁠ẏֽwòm׃"],[18,2,"וַ⁠יִּשָּׂ֤א עֵינָי⁠ו֙ וַ⁠יַּ֔רְא וְ⁠הִנֵּה֙ שְׁלֹשָׁ֣ה אֲנָשִׁ֔ים נִצָּבִ֖ים עָלָ֑י⁠ו וַ⁠יַּ֗רְא וַ⁠יָּ֤רָץ לִ⁠קְרָאתָ⁠ם֙ מִ⁠פֶּ֣תַח הָ⁠אֹ֔הֶל וַ⁠יִּשְׁתַּ֖חוּ אָֽרְצָ⁠ה׃","wa⁠yi̇şá֤̇̂ʼ ʻéynáy⁠w֙ wa⁠yȧ֔rĕʼ wĕ⁠hiné̇h֙ şĕ̌lòşá֣̌h ʼànáşǐ֔ym niẕá̇bi֖ym ʻálá֑y⁠w wa⁠yȧ֗rĕʼ wa⁠yá֤̇ráẕ li⁠qĕráʼţá⁠m֙ mi⁠pė֣ţaẖ há⁠ʼò֔hel wa⁠yi̇şĕ̌ţȧ֖ẖẇ ʼáֽrĕẕá⁠h׃"],[18,3,"וַ⁠יֹּאמַ֑ר אֲדֹנָ֗⁠י אִם־נָ֨א מָצָ֤אתִי חֵן֙ בְּ⁠עֵינֶ֔י⁠ךָ אַל־נָ֥א תַעֲבֹ֖ר מֵ⁠עַ֥ל עַבְדֶּֽ⁠ךָ׃","wa⁠yò̇ʼma֑r ʼàdòná֗⁠y ʼim-ná֨ʼ máẕá֤ʼţiy ẖén֙ bĕ̇⁠ʻéyne֔y⁠ká ʼal-ná֥ʼ ţaʻàbò֖r mé⁠ʻa֥l ʻabĕdėֽ⁠ká׃"],[18,4,"יֻקַּֽח־נָ֣א מְעַט־מַ֔יִם וְ⁠רַחֲצ֖וּ רַגְלֵי⁠כֶ֑ם וְ⁠הִֽשָּׁעֲנ֖וּ תַּ֥חַת הָ⁠עֵֽץ׃","yuqȧֽẖ-ná֣ʼ mĕʻat-ma֔yim wĕ⁠raẖàẕ֖ẇ ragĕléy⁠ke֑m wĕ⁠hiֽşá̇̌ʻàn֖ẇ ţȧ֥ẖaţ há⁠ʻéֽẕ׃"],[18,5,"וְ⁠אֶקְחָ֨ה פַת־לֶ֜חֶם וְ⁠סַעֲד֤וּ לִבְּ⁠כֶם֙ אַחַ֣ר תַּעֲבֹ֔רוּ כִּֽי־עַל־כֵּ֥ן עֲבַרְתֶּ֖ם עַֽל־עַבְדְּ⁠כֶ֑ם וַ⁠יֹּ֣אמְר֔וּ כֵּ֥ן תַּעֲשֶׂ֖ה כַּ⁠אֲשֶׁ֥ר דִּבַּֽרְתָּ׃","wĕ⁠ʼeqĕẖá֨h paţ-le֜ẖem wĕ⁠saʻàd֤ẇ libĕ̇⁠kem֙ ʼaẖa֣r ţȧʻàbò֔rẇ kiֽ̇y-ʻal-ké֥̇n ʻàbarĕţė֖m ʻaֽl-ʻabĕdĕ̇⁠ke֑m wa⁠yò֣̇ʼmĕr֔ẇ ké֥̇n ţȧʻàşê֖h kȧ⁠ʼàşě֥r di̇bȧֽrĕţá̇׃"],[18,6,"וַ⁠יְמַהֵ֧ר אַבְרָהָ֛ם הָ⁠אֹ֖הֱלָ⁠ה אֶל־שָׂרָ֑ה וַ⁠יֹּ֗אמֶר מַהֲרִ֞י שְׁלֹ֤שׁ סְאִים֙ קֶ֣מַח סֹ֔לֶת ל֖וּשִׁי וַ⁠עֲשִׂ֥י עֻגֽוֹת׃","wa⁠yĕmahé֧r ʼabĕráhá֛m há⁠ʼò֖hèlá⁠h ʼel-şá̂rá֑h wa⁠yò̇֗ʼmer mahàri֞y şĕ̌lò֤ş̌ sĕʼiym֙ qe֣maẖ sò֔leţ l֖ẇşǐy wa⁠ʻàşî֥y ʻugֽwòţ׃"],[18,7,"וְ⁠אֶל־הַ⁠בָּקָ֖ר רָ֣ץ אַבְרָהָ֑ם וַ⁠יִּקַּ֨ח בֶּן־בָּקָ֜ר רַ֤ךְ וָ⁠טוֹב֙ וַ⁠יִּתֵּ֣ן אֶל־הַ⁠נַּ֔עַר וַ⁠יְמַהֵ֖ר לַ⁠עֲשׂ֥וֹת אֹתֽ⁠וֹ׃","wĕ⁠ʼel-ha⁠bá̇qá֖r rá֣ẕ ʼabĕráhá֑m wa⁠yi̇qȧ֨ẖ bėn-bá̇qá֜r ra֤kĕ wá⁠twòb֙ wa⁠yi̇ţé֣̇n ʼel-ha⁠nȧ֔ʻar wa⁠yĕmahé֖r la⁠ʻàş֥̂wòţ ʼòţֽ⁠wò׃"],[18,8,"וַ⁠יִּקַּ֨ח חֶמְאָ֜ה וְ⁠חָלָ֗ב וּ⁠בֶן־הַ⁠בָּקָר֙ אֲשֶׁ֣ר עָשָׂ֔ה וַ⁠יִּתֵּ֖ן לִ⁠פְנֵי⁠הֶ֑ם וְ⁠הֽוּא־עֹמֵ֧ד עֲלֵי⁠הֶ֛ם תַּ֥חַת הָ⁠עֵ֖ץ וַ⁠יֹּאכֵֽלוּ׃","wa⁠yi̇qȧ֨ẖ ẖemĕʼá֜h wĕ⁠ẖálá֗b ẇ⁠ben-ha⁠bá̇qár֙ ʼàşě֣r ʻáşá̂֔h wa⁠yi̇ţé֖̇n li⁠pĕnéy⁠he֑m wĕ⁠hֽẇʼ-ʻòmé֧d ʻàléy⁠he֛m ţȧ֥ẖaţ há⁠ʻé֖ẕ wa⁠yò̇ʼkéֽlẇ׃"],[18,9,"וַ⁠יֹּאמְר֣וּ אֵׄלָׄ֔יׄ⁠וׄ אַיֵּ֖ה שָׂרָ֣ה אִשְׁתֶּ֑⁠ךָ וַ⁠יֹּ֖אמֶר הִנֵּ֥ה בָ⁠אֹֽהֶל׃","wa⁠yò̇ʼmĕr֣ẇ ʼéׄláׄ֔yׄ⁠wׄ ʼayé֖̇h şá̂rá֣h ʼişĕ̌ţė֑⁠ká wa⁠yò֖̇ʼmer hiné֥̇h bá⁠ʼòֽhel׃"],[18,10,"וַ⁠יֹּ֗אמֶר שׁ֣וֹב אָשׁ֤וּב אֵלֶ֨י⁠ךָ֙ כָּ⁠עֵ֣ת חַיָּ֔ה וְ⁠הִנֵּה־בֵ֖ן לְ⁠שָׂרָ֣ה אִשְׁתֶּ֑⁠ךָ וְ⁠שָׂרָ֥ה שֹׁמַ֛עַת פֶּ֥תַח הָ⁠אֹ֖הֶל וְ⁠ה֥וּא אַחֲרָֽי⁠ו׃","wa⁠yò̇֗ʼmer ş֣̌wòb ʼáş֤̌ẇb ʼéle֨y⁠ká֙ ká̇⁠ʻé֣ţ ẖayá̇֔h wĕ⁠hiné̇h-bé֖n lĕ⁠şá̂rá֣h ʼişĕ̌ţė֑⁠ká wĕ⁠şá̂rá֥h şò̌ma֛ʻaţ pė֥ţaẖ há⁠ʼò֖hel wĕ⁠h֥ẇʼ ʼaẖàráֽy⁠w׃"],[18,11,"וְ⁠אַבְרָהָ֤ם וְ⁠שָׂרָה֙ זְקֵנִ֔ים בָּאִ֖ים בַּ⁠יָּמִ֑ים חָדַל֙ לִ⁠הְי֣וֹת לְ⁠שָׂרָ֔ה אֹ֖רַח כַּ⁠נָּשִֽׁים׃","wĕ⁠ʼabĕráhá֤m wĕ⁠şá̂ráh֙ zĕqéni֔ym bá̇ʼi֖ym bȧ⁠yá̇mi֑ym ẖádal֙ li⁠hĕy֣wòţ lĕ⁠şá̂rá֔h ʼò֖raẖ kȧ⁠ná̇şǐֽym׃"],[18,12,"וַ⁠תִּצְחַ֥ק שָׂרָ֖ה בְּ⁠קִרְבָּ֣⁠הּ לֵ⁠אמֹ֑ר אַחֲרֵ֤י בְלֹתִ⁠י֙ הָֽיְתָה־לִּ֣⁠י עֶדְנָ֔ה וַֽ⁠אדֹנִ֖⁠י זָקֵֽן׃","wa⁠ţi̇ẕĕẖa֥q şá̂rá֖h bĕ̇⁠qirĕbá֣̇⁠ḣ lé⁠ʼmò֑r ʼaẖàré֤y bĕlòţi⁠y֙ hֽáyĕţáh-li֣̇⁠y ʻedĕná֔h wֽa⁠ʼdòni֖⁠y záqéֽn׃"],[18,13,"וַ⁠יֹּ֥אמֶר יְהוָ֖ה אֶל־אַבְרָהָ֑ם לָ֣⁠מָּה זֶּה֩ צָחֲקָ֨ה שָׂרָ֜ה לֵ⁠אמֹ֗ר הַ⁠אַ֥ף אֻמְנָ֛ם אֵלֵ֖ד וַ⁠אֲנִ֥י זָקַֽנְתִּי׃","wa⁠yò֥̇ʼmer yĕhwá֖h ʼel-ʼabĕráhá֑m lá֣⁠má̇h zėh֩ ẕáẖàqá֨h şá̂rá֜h lé⁠ʼmò֗r ha⁠ʼa֥p ʼumĕná֛m ʼélé֖d wa⁠ʼàni֥y záqaֽnĕţi̇y׃"],[18,14,"הֲ⁠יִפָּלֵ֥א מֵ⁠יְהוָ֖ה דָּבָ֑ר לַ⁠מּוֹעֵ֞ד אָשׁ֥וּב אֵלֶ֛י⁠ךָ כָּ⁠עֵ֥ת חַיָּ֖ה וּ⁠לְ⁠שָׂרָ֥ה בֵֽן׃","hà⁠yipá̇lé֥ʼ mé⁠yĕhwá֖h dá̇bá֑r la⁠ṁwòʻé֞d ʼáş֥̌ẇb ʼéle֛y⁠ká ká̇⁠ʻé֥ţ ẖayá֖̇h ẇ⁠lĕ⁠şá̂rá֥h béֽn׃"],[18,15,"וַ⁠תְּכַחֵ֨שׁ שָׂרָ֧ה ׀ לֵ⁠אמֹ֛ר לֹ֥א צָחַ֖קְתִּי כִּ֣י ׀ יָרֵ֑אָה וַ⁠יֹּ֥אמֶר ׀ לֹ֖א כִּ֥י צָחָֽקְתְּ׃","wa⁠ţĕ̇kaẖé֨ş̌ şá̂rá֧h ׀ lé⁠ʼmò֛r lò֥ʼ ẕáẖa֖qĕţi̇y ki֣̇y ׀ yáré֑ʼáh wa⁠yò֥̇ʼmer ׀ lò֖ʼ ki֥̇y ẕáẖáֽqĕţĕ̇׃"],[18,16,"וַ⁠יָּקֻ֤מוּ מִ⁠שָּׁם֙ הָֽ⁠אֲנָשִׁ֔ים וַ⁠יַּשְׁקִ֖פוּ עַל־פְּנֵ֣י סְדֹ֑ם וְ⁠אַ֨בְרָהָ֔ם הֹלֵ֥ךְ עִמָּ֖⁠ם לְ⁠שַׁלְּחָֽ⁠ם׃","wa⁠yá̇qu֤mẇ mi⁠şá̇̌m֙ hֽá⁠ʼànáşǐ֔ym wa⁠yȧşĕ̌qi֖pẇ ʻal-pĕ̇né֣y sĕdò֑m wĕ⁠ʼa֨bĕráhá֔m hòlé֥kĕ ʻimá֖̇⁠m lĕ⁠şǎlĕ̇ẖáֽ⁠m׃"],[18,17,"וַֽ⁠יהֹוָ֖ה אָמָ֑ר הַֽ⁠מְכַסֶּ֤ה אֲנִי֙ מֵֽ⁠אַבְרָהָ֔ם אֲשֶׁ֖ר אֲנִ֥י עֹשֶֽׂה׃","waֽ⁠yhòwá֖h ʼámá֑r hֽa⁠mĕkasė֤h ʼàniy֙ mֽé⁠ʼabĕráhá֔m ʼàşě֖r ʼàni֥y ʻòşêֽh׃"],[18,18,"וְ⁠אַ֨בְרָהָ֔ם הָי֧וֹ יִֽהְיֶ֛ה לְ⁠ג֥וֹי גָּד֖וֹל וְ⁠עָצ֑וּם וְ⁠נִ֨בְרְכוּ ב֔⁠וֹ כֹּ֖ל גּוֹיֵ֥י הָ⁠אָֽרֶץ׃","wĕ⁠ʼa֨bĕráhá֔m háy֧wò yiֽhĕye֛h lĕ⁠g֥wòy gá̇d֖wòl wĕ⁠ʻáẕ֑ẇm wĕ⁠ni֨bĕrĕkẇ b֔⁠wò kò֖̇l ġwòyé֥y há⁠ʼáֽreẕ׃"],[18,19,"כִּ֣י יְדַעְתִּ֗י⁠ו לְמַעַן֩ אֲשֶׁ֨ר יְצַוֶּ֜ה אֶת־בָּנָ֤י⁠ו וְ⁠אֶת־בֵּית⁠וֹ֙ אַחֲרָ֔י⁠ו וְ⁠שָֽׁמְרוּ֙ דֶּ֣רֶךְ יְהוָ֔ה לַ⁠עֲשׂ֥וֹת צְדָקָ֖ה וּ⁠מִשְׁפָּ֑ט לְמַ֗עַן הָבִ֤יא יְהוָה֙ עַל־אַבְרָהָ֔ם אֵ֥ת אֲשֶׁר־דִּבֶּ֖ר עָלָֽי⁠ו׃","ki֣̇y yĕdaʻĕţi̇֗y⁠w lĕmaʻan֩ ʼàşě֨r yĕẕawė֜h ʼeţ-bá̇ná֤y⁠w wĕ⁠ʼeţ-bé̇yţ⁠wò֙ ʼaẖàrá֔y⁠w wĕ⁠şáֽ̌mĕrẇ֙ dė֣rekĕ yĕhwá֔h la⁠ʻàş֥̂wòţ ẕĕdáqá֖h ẇ⁠mişĕ̌pá֑̇t lĕma֗ʻan hábi֤yʼ yĕhwáh֙ ʻal-ʼabĕráhá֔m ʼé֥ţ ʼàşěr-di̇bė֖r ʻáláֽy⁠w׃"],[18,20,"וַ⁠יֹּ֣אמֶר יְהוָ֔ה זַעֲקַ֛ת סְדֹ֥ם וַ⁠עֲמֹרָ֖ה כִּי־רָ֑בָּה וְ⁠חַ֨טָּאתָ֔⁠ם כִּ֥י כָבְדָ֖ה מְאֹֽד׃","wa⁠yò֣̇ʼmer yĕhwá֔h zaʻàqa֛ţ sĕdò֥m wa⁠ʻàmòrá֖h ki̇y-rá֑bá̇h wĕ⁠ẖa֨tá̇ʼţá֔⁠m ki֥̇y kábĕdá֖h mĕʼòֽd׃"],[18,21,"אֵֽרֲדָה־נָּ֣א וְ⁠אֶרְאֶ֔ה הַ⁠כְּ⁠צַעֲקָתָ֛⁠הּ הַ⁠בָּ֥אָה אֵלַ֖⁠י עָשׂ֣וּ ׀ כָּלָ֑ה וְ⁠אִם־לֹ֖א אֵדָֽעָה׃","ʼéֽràdáh-ná֣̇ʼ wĕ⁠ʼerĕʼe֔h ha⁠kĕ̇⁠ẕaʻàqáţá֛⁠ḣ ha⁠bá֥̇ʼáh ʼéla֖⁠y ʻáş֣̂ẇ ׀ ká̇lá֑h wĕ⁠ʼim-lò֖ʼ ʼédáֽʻáh׃"],[18,22,"וַ⁠יִּפְנ֤וּ מִ⁠שָּׁם֙ הָֽ⁠אֲנָשִׁ֔ים וַ⁠יֵּלְכ֖וּ סְדֹ֑מָ⁠ה וְ⁠אַ֨בְרָהָ֔ם עוֹדֶ֥⁠נּוּ עֹמֵ֖ד לִ⁠פְנֵ֥י יְהוָֽה׃","wa⁠yi̇pĕn֤ẇ mi⁠şá̇̌m֙ hֽá⁠ʼànáşǐ֔ym wa⁠yé̇lĕk֖ẇ sĕdò֑má⁠h wĕ⁠ʼa֨bĕráhá֔m ʻwòde֥⁠ṅẇ ʻòmé֖d li⁠pĕné֥y yĕhwáֽh׃"],[18,23,"וַ⁠יִּגַּ֥שׁ אַבְרָהָ֖ם וַ⁠יֹּאמַ֑ר הַ⁠אַ֣ף תִּסְפֶּ֔ה צַדִּ֖יק עִם־רָשָֽׁע׃","wa⁠yi̇gȧ֥ş̌ ʼabĕráhá֖m wa⁠yò̇ʼma֑r ha⁠ʼa֣p ţi̇sĕpė֔h ẕadi֖̇yq ʻim-ráşáֽ̌ʻ׃"],[18,24,"אוּלַ֥י יֵ֛שׁ חֲמִשִּׁ֥ים צַדִּיקִ֖ם בְּ⁠ת֣וֹךְ הָ⁠עִ֑יר הַ⁠אַ֤ף תִּסְפֶּה֙ וְ⁠לֹא־תִשָּׂ֣א לַ⁠מָּק֔וֹם לְמַ֛עַן חֲמִשִּׁ֥ים הַ⁠צַּדִּיקִ֖ם אֲשֶׁ֥ר בְּ⁠קִרְבָּֽ⁠הּ׃","ʼẇla֥y yé֛ş̌ ẖàmişi֥̇̌ym ẕadi̇yqi֖m bĕ̇⁠ţ֣wòkĕ há⁠ʻi֑yr ha⁠ʼa֤p ţi̇sĕpėh֙ wĕ⁠lòʼ-ţişá֣̇̂ʼ la⁠má̇q֔wòm lĕma֛ʻan ẖàmişi֥̇̌ym ha⁠ẕȧdi̇yqi֖m ʼàşě֥r bĕ̇⁠qirĕbáֽ̇⁠ḣ׃"],[18,25,"חָלִ֨לָ⁠ה לְּ⁠ךָ֜ מֵ⁠עֲשֹׂ֣ת ׀ כַּ⁠דָּבָ֣ר הַ⁠זֶּ֗ה לְ⁠הָמִ֤ית צַדִּיק֙ עִם־רָשָׁ֔ע וְ⁠הָיָ֥ה כַ⁠צַּדִּ֖יק כָּ⁠רָשָׁ֑ע חָלִ֣לָ⁠ה לָּ֔⁠ךְ הֲ⁠שֹׁפֵט֙ כָּל־הָ⁠אָ֔רֶץ לֹ֥א יַעֲשֶׂ֖ה מִשְׁפָּֽט׃","ẖáli֨lá⁠h lĕ̇⁠ká֜ mé⁠ʻàşò֣̂ţ ׀ kȧ⁠dá̇bá֣r ha⁠zė֗h lĕ⁠hámi֤yţ ẕadi̇yq֙ ʻim-ráşá̌֔ʻ wĕ⁠háyá֥h ka⁠ẕȧdi֖̇yq ká̇⁠ráşá֑̌ʻ ẖáli֣lá⁠h lá̇֔⁠kĕ hà⁠şò̌pét֙ ká̇l-há⁠ʼá֔reẕ lò֥ʼ yaʻàşê֖h mişĕ̌páֽ̇t׃"],[18,26,"וַ⁠יֹּ֣אמֶר יְהוָ֔ה אִם־אֶמְצָ֥א בִ⁠סְדֹ֛ם חֲמִשִּׁ֥ים צַדִּיקִ֖ם בְּ⁠ת֣וֹךְ הָ⁠עִ֑יר וְ⁠נָשָׂ֥אתִי לְ⁠כָל־הַ⁠מָּק֖וֹם בַּ⁠עֲבוּרָֽ⁠ם׃","wa⁠yò֣̇ʼmer yĕhwá֔h ʼim-ʼemĕẕá֥ʼ bi⁠sĕdò֛m ẖàmişi֥̇̌ym ẕadi̇yqi֖m bĕ̇⁠ţ֣wòkĕ há⁠ʻi֑yr wĕ⁠náşá֥̂ʼţiy lĕ⁠kál-ha⁠má̇q֖wòm bȧ⁠ʻàbẇráֽ⁠m׃"],[18,27,"וַ⁠יַּ֥עַן אַבְרָהָ֖ם וַ⁠יֹּאמַ֑ר הִנֵּה־נָ֤א הוֹאַ֨לְתִּי֙ לְ⁠דַבֵּ֣ר אֶל־אֲדֹנָ֔⁠י וְ⁠אָנֹכִ֖י עָפָ֥ר וָ⁠אֵֽפֶר׃","wa⁠yȧ֥ʻan ʼabĕráhá֖m wa⁠yò̇ʼma֑r hiné̇h-ná֤ʼ hwòʼa֨lĕţi̇y֙ lĕ⁠dabé֣̇r ʼel-ʼàdòná֔⁠y wĕ⁠ʼánòki֖y ʻápá֥r wá⁠ʼéֽper׃"],[18,28,"א֠וּלַי יַחְסְר֞וּ⁠ן חֲמִשִּׁ֤ים הַ⁠צַּדִּיקִם֙ חֲמִשָּׁ֔ה הֲ⁠תַשְׁחִ֥ית בַּ⁠חֲמִשָּׁ֖ה אֶת־כָּל־הָ⁠עִ֑יר וַ⁠יֹּ֨אמֶר֙ לֹ֣א אַשְׁחִ֔ית אִם־אֶמְצָ֣א שָׁ֔ם אַרְבָּעִ֖ים וַ⁠חֲמִשָּֽׁה׃","ʼ֠ẇlay yaẖĕsĕr֞ẇ⁠n ẖàmişi֤̇̌ym ha⁠ẕȧdi̇yqim֙ ẖàmişá̇̌֔h hà⁠ţaşĕ̌ẖi֥yţ bȧ⁠ẖàmişá֖̇̌h ʼeţ-ká̇l-há⁠ʻi֑yr wa⁠yò̇֨ʼmer֙ lò֣ʼ ʼaşĕ̌ẖi֔yţ ʼim-ʼemĕẕá֣ʼ şá̌֔m ʼarĕbá̇ʻi֖ym wa⁠ẖàmişáֽ̇̌h׃"],[18,29,"וַ⁠יֹּ֨סֶף ע֜וֹד לְ⁠דַבֵּ֤ר אֵלָי⁠ו֙ וַ⁠יֹּאמַ֔ר אוּלַ֛י יִמָּצְא֥וּ⁠ן שָׁ֖ם אַרְבָּעִ֑ים וַ⁠יֹּ֨אמֶר֙ לֹ֣א אֶֽעֱשֶׂ֔ה בַּ⁠עֲב֖וּר הָ⁠אַרְבָּעִֽים׃","wa⁠yò̇֨sep ʻ֜wòd lĕ⁠dabé֤̇r ʼéláy⁠w֙ wa⁠yò̇ʼma֔r ʼẇla֛y yimá̇ẕĕʼ֥ẇ⁠n şá֖̌m ʼarĕbá̇ʻi֑ym wa⁠yò̇֨ʼmer֙ lò֣ʼ ʼֽeʻèşê֔h bȧ⁠ʻàb֖ẇr há⁠ʼarĕbá̇ʻiֽym׃"],[18,30,"וַ֠⁠יֹּאמֶר אַל־נָ֞א יִ֤חַר לַֽ⁠אדֹנָ⁠י֙ וַ⁠אֲדַבֵּ֔רָה אוּלַ֛י יִמָּצְא֥וּ⁠ן שָׁ֖ם שְׁלֹשִׁ֑ים וַ⁠יֹּ֨אמֶר֙ לֹ֣א אֶֽעֱשֶׂ֔ה אִם־אֶמְצָ֥א שָׁ֖ם שְׁלֹשִֽׁים׃","wa֠⁠yò̇ʼmer ʼal-ná֞ʼ yi֤ẖar lֽa⁠ʼdòná⁠y֙ wa⁠ʼàdabé̇֔ráh ʼẇla֛y yimá̇ẕĕʼ֥ẇ⁠n şá֖̌m şĕ̌lòşǐ֑ym wa⁠yò̇֨ʼmer֙ lò֣ʼ ʼֽeʻèşê֔h ʼim-ʼemĕẕá֥ʼ şá֖̌m şĕ̌lòşǐֽym׃"],[18,31,"וַ⁠יֹּ֗אמֶר הִנֵּֽה־נָ֤א הוֹאַ֨לְתִּי֙ לְ⁠דַבֵּ֣ר אֶל־אֲדֹנָ֔⁠י אוּלַ֛י יִמָּצְא֥וּ⁠ן שָׁ֖ם עֶשְׂרִ֑ים וַ⁠יֹּ֨אמֶר֙ לֹ֣א אַשְׁחִ֔ית בַּ⁠עֲב֖וּר הָֽ⁠עֶשְׂרִֽים׃","wa⁠yò̇֗ʼmer hinéֽ̇h-ná֤ʼ hwòʼa֨lĕţi̇y֙ lĕ⁠dabé֣̇r ʼel-ʼàdòná֔⁠y ʼẇla֛y yimá̇ẕĕʼ֥ẇ⁠n şá֖̌m ʻeşĕ̂ri֑ym wa⁠yò̇֨ʼmer֙ lò֣ʼ ʼaşĕ̌ẖi֔yţ bȧ⁠ʻàb֖ẇr hֽá⁠ʻeşĕ̂riֽym׃"],[18,32,"וַ֠⁠יֹּאמֶר אַל־נָ֞א יִ֤חַר לַֽ⁠אדֹנָ⁠י֙ וַ⁠אֲדַבְּרָ֣ה אַךְ־הַ⁠פַּ֔עַם אוּלַ֛י יִמָּצְא֥וּ⁠ן שָׁ֖ם עֲשָׂרָ֑ה וַ⁠יֹּ֨אמֶר֙ לֹ֣א אַשְׁחִ֔ית בַּ⁠עֲב֖וּר הָ⁠עֲשָׂרָֽה׃","wa֠⁠yò̇ʼmer ʼal-ná֞ʼ yi֤ẖar laֽ⁠ʼdòná⁠y֙ wa⁠ʼàdabĕ̇rá֣h ʼakĕ-ha⁠pȧ֔ʻam ʼẇla֛y yimá̇ẕĕʼ֥ẇ⁠n şá֖̌m ʻàşá̂rá֑h wa⁠yò̇֨ʼmer֙ lò֣ʼ ʼaşĕ̌ẖi֔yţ bȧ⁠ʻàb֖ẇr há⁠ʻàşá̂ráֽh׃"],[18,33,"וַ⁠יֵּ֣לֶךְ יְהוָ֔ה כַּ⁠אֲשֶׁ֣ר כִּלָּ֔ה לְ⁠דַבֵּ֖ר אֶל־אַבְרָהָ֑ם וְ⁠אַבְרָהָ֖ם שָׁ֥ב לִ⁠מְקֹמֽ⁠וֹ׃","wa⁠yé֣̇lekĕ yĕhwá֔h kȧ⁠ʼàşě֣r ki̇lá̇֔h lĕ⁠dabé֖̇r ʼel-ʼabĕráhá֑m wĕ⁠ʼabĕráhá֖m şá֥̌b li⁠mĕqòmֽ⁠wò׃"],[19,1,"וַ֠⁠יָּבֹאוּ שְׁנֵ֨י הַ⁠מַּלְאָכִ֤ים סְדֹ֨מָ⁠ה֙ בָּ⁠עֶ֔רֶב וְ⁠ל֖וֹט יֹשֵׁ֣ב בְּ⁠שַֽׁעַר־סְדֹ֑ם וַ⁠יַּרְא־לוֹט֙ וַ⁠יָּ֣קָם לִ⁠קְרָאתָ֔⁠ם וַ⁠יִּשְׁתַּ֥חוּ אַפַּ֖יִם אָֽרְצָ⁠ה׃","wa֠⁠yá̇bòʼẇ şĕ̌né֨y ha⁠mȧlĕʼáki֤ym sĕdò֨má⁠h֙ bá̇⁠ʻe֔reb wĕ⁠l֖wòt yòşé֣̌b bĕ̇⁠şǎֽʻar-sĕdò֑m wa⁠yȧrĕʼ-lwòt֙ wa⁠yá֣̇qám li⁠qĕráʼţá֔⁠m wa⁠yi̇şĕ̌ţȧ֥ẖẇ ʼapȧ֖yim ʼáֽrĕẕá⁠h׃"],[19,2,"וַ⁠יֹּ֜אמֶר הִנֶּ֣ה נָּא־אֲדֹנַ֗⁠י ס֣וּרוּ נָ֠א אֶל־בֵּ֨ית עַבְדְּ⁠כֶ֤ם וְ⁠לִ֨ינוּ֙ וְ⁠רַחֲצ֣וּ רַגְלֵי⁠כֶ֔ם וְ⁠הִשְׁכַּמְתֶּ֖ם וַ⁠הֲלַכְתֶּ֣ם לְ⁠דַרְכְּ⁠כֶ֑ם וַ⁠יֹּאמְר֣וּ לֹּ֔א כִּ֥י בָ⁠רְח֖וֹב נָלִֽין׃","wa⁠yò̇֜ʼmer hinė֣h ná̇ʼ-ʼàdòna֗⁠y s֣ẇrẇ ná֠ʼ ʼel-bé̇֨yţ ʻabĕdĕ̇⁠ke֤m wĕ⁠li֨ynẇ֙ wĕ⁠raẖàẕ֣ẇ ragĕléy⁠ke֔m wĕ⁠hişĕ̌kȧmĕţė֖m wa⁠hàlakĕţė֣m lĕ⁠darĕkĕ̇⁠ke֑m wa⁠yò̇ʼmĕr֣ẇ lò̇֔ʼ ki֥̇y bá⁠rĕẖ֖wòb náliֽyn׃"],[19,3,"וַ⁠יִּפְצַר־בָּ֣⁠ם מְאֹ֔ד וַ⁠יָּסֻ֣רוּ אֵלָ֔י⁠ו וַ⁠יָּבֹ֖אוּ אֶל־בֵּית֑⁠וֹ וַ⁠יַּ֤עַשׂ לָ⁠הֶם֙ מִשְׁתֶּ֔ה וּ⁠מַצּ֥וֹת אָפָ֖ה וַ⁠יֹּאכֵֽלוּ׃","wa⁠yi̇pĕẕar-bá֣̇⁠m mĕʼò֔d wa⁠yá̇su֣rẇ ʼélá֔y⁠w wa⁠yá̇bò֖ʼẇ ʼel-bé̇yţ֑⁠wò wa⁠yȧ֤ʻaş̂ lá⁠hem֙ mişĕ̌ţė֔h ẇ⁠maẕ֥̇wòţ ʼápá֖h wa⁠yò̇ʼkéֽlẇ׃"],[19,4,"טֶרֶם֮ יִשְׁכָּבוּ֒ וְ⁠אַנְשֵׁ֨י הָ⁠עִ֜יר אַנְשֵׁ֤י סְדֹם֙ נָסַ֣בּוּ עַל־הַ⁠בַּ֔יִת מִ⁠נַּ֖עַר וְ⁠עַד־זָקֵ֑ן כָּל־הָ⁠עָ֖ם מִ⁠קָּצֶֽה׃","terem֮ yişĕ̌ká̇bẇ֒ wĕ⁠ʼanĕşé̌֨y há⁠ʻi֜yr ʼanĕşé֤̌y sĕdòm֙ nása֣ḃẇ ʻal-ha⁠bȧ֔yiţ mi⁠nȧ֖ʻar wĕ⁠ʻad-záqé֑n ká̇l-há⁠ʻá֖m mi⁠qá̇ẕeֽh׃"],[19,5,"וַ⁠יִּקְרְא֤וּ אֶל־לוֹט֙ וַ⁠יֹּ֣אמְרוּ ל֔⁠וֹ אַיֵּ֧ה הָ⁠אֲנָשִׁ֛ים אֲשֶׁר־בָּ֥אוּ אֵלֶ֖י⁠ךָ הַ⁠לָּ֑יְלָה הוֹצִיאֵ֣⁠ם אֵלֵ֔י⁠נוּ וְ⁠נֵדְעָ֖ה אֹתָֽ⁠ם׃","wa⁠yi̇qĕrĕʼ֤ẇ ʼel-lwòt֙ wa⁠yò֣̇ʼmĕrẇ l֔⁠wò ʼayé֧̇h há⁠ʼànáşǐ֛ym ʼàşěr-bá֥̇ʼẇ ʼéle֖y⁠ká ha⁠lá֑̇yĕláh hwòẕiyʼé֣⁠m ʼélé֔y⁠nẇ wĕ⁠nédĕʻá֖h ʼòţáֽ⁠m׃"],[19,6,"וַ⁠יֵּצֵ֧א אֲלֵ⁠הֶ֛ם ל֖וֹט הַ⁠פֶּ֑תְחָ⁠ה וְ⁠הַ⁠דֶּ֖לֶת סָגַ֥ר אַחֲרָֽי⁠ו׃","wa⁠yé̇ẕé֧ʼ ʼàlé⁠he֛m l֖wòt ha⁠pė֑ţĕẖá⁠h wĕ⁠ha⁠dė֖leţ sága֥r ʼaẖàráֽy⁠w׃"],[19,7,"וַ⁠יֹּאמַ֑ר אַל־נָ֥א אַחַ֖⁠י תָּרֵֽעוּ׃","wa⁠yò̇ʼma֑r ʼal-ná֥ʼ ʼaẖa֖⁠y ţá̇réֽʻẇ׃"],[19,8,"הִנֵּה־נָ֨א לִ֜⁠י שְׁתֵּ֣י בָנ֗וֹת אֲשֶׁ֤ר לֹֽא־יָדְעוּ֙ אִ֔ישׁ אוֹצִֽיאָה־נָּ֤א אֶתְ⁠הֶן֙ אֲלֵי⁠כֶ֔ם וַ⁠עֲשׂ֣וּ לָ⁠הֶ֔ן כַּ⁠טּ֖וֹב בְּ⁠עֵינֵי⁠כֶ֑ם רַ֠ק לָֽ⁠אֲנָשִׁ֤ים הָ⁠אֵל֙ אַל־תַּעֲשׂ֣וּ דָבָ֔ר כִּֽי־עַל־כֵּ֥ן בָּ֖אוּ בְּ⁠צֵ֥ל קֹרָתִֽ⁠י׃","hiné̇h-ná֨ʼ li֜⁠y şĕ̌ţé֣̇y bán֗wòţ ʼàşě֤r lòֽʼ-yádĕʻẇ֙ ʼi֔yş̌ ʼwòẕiֽyʼáh-ná֤̇ʼ ʼeţĕ⁠hen֙ ʼàléy⁠ke֔m wa⁠ʻàş֣̂ẇ lá⁠he֔n kȧ⁠ṫ֖wòb bĕ̇⁠ʻéynéy⁠ke֑m ra֠q láֽ⁠ʼànáşǐ֤ym há⁠ʼél֙ ʼal-ţȧʻàş֣̂ẇ dábá֔r kiֽ̇y-ʻal-ké֥̇n bá֖̇ʼẇ bĕ̇⁠ẕé֥l qòráţiֽ⁠y׃"],[19,9,"וַ⁠יֹּאמְר֣וּ ׀ גֶּשׁ־הָ֗לְאָה וַ⁠יֹּֽאמְרוּ֙ הָ⁠אֶחָ֤ד בָּֽא־לָ⁠גוּר֙ וַ⁠יִּשְׁפֹּ֣ט שָׁפ֔וֹט עַתָּ֕ה נָרַ֥ע לְ⁠ךָ֖ מֵ⁠הֶ֑ם וַ⁠יִּפְצְר֨וּ בָ⁠אִ֤ישׁ בְּ⁠לוֹט֙ מְאֹ֔ד וַֽ⁠יִּגְּשׁ֖וּ לִ⁠שְׁבֹּ֥ר הַ⁠דָּֽלֶת׃","wa⁠yò̇ʼmĕr֣ẇ ׀ gėş̌-há֗lĕʼáh wa⁠yòֽ̇ʼmĕrẇ֙ há⁠ʼeẖá֤d báֽ̇ʼ-lá⁠gẇr֙ wa⁠yi̇şĕ̌pò֣̇t şá̌p֔wòt ʻaţá̇֕h nára֥ʻ lĕ⁠ká֖ mé⁠he֑m wa⁠yi̇pĕẕĕr֨ẇ bá⁠ʼi֤yş̌ bĕ̇⁠lwòt֙ mĕʼò֔d waֽ⁠yi̇gĕ̇ş֖̌ẇ li⁠şĕ̌bò֥̇r ha⁠dáֽ̇leţ׃"],[19,10,"וַ⁠יִּשְׁלְח֤וּ הָֽ⁠אֲנָשִׁים֙ אֶת־יָדָ֔⁠ם וַ⁠יָּבִ֧יאוּ אֶת־ל֛וֹט אֲלֵי⁠הֶ֖ם הַ⁠בָּ֑יְתָ⁠ה וְ⁠אֶת־הַ⁠דֶּ֖לֶת סָגָֽרוּ׃","wa⁠yi̇şĕ̌lĕẖ֤ẇ hֽá⁠ʼànáşǐym֙ ʼeţ-yádá֔⁠m wa⁠yá̇bi֧yʼẇ ʼeţ-l֛wòt ʼàléy⁠he֖m ha⁠bá֑̇yĕţá⁠h wĕ⁠ʼeţ-ha⁠dė֖leţ ságáֽrẇ׃"],[19,11,"וְֽ⁠אֶת־הָ⁠אֲנָשִׁ֞ים אֲשֶׁר־פֶּ֣תַח הַ⁠בַּ֗יִת הִכּוּ֙ בַּ⁠סַּנְוֵרִ֔ים מִ⁠קָּטֹ֖ן וְ⁠עַד־גָּד֑וֹל וַ⁠יִּלְא֖וּ לִ⁠מְצֹ֥א הַ⁠פָּֽתַח׃","wĕֽ⁠ʼeţ-há⁠ʼànáşǐ֞ym ʼàşěr-pė֣ţaẖ ha⁠bȧ֗yiţ hik̇ẇ֙ bȧ⁠sȧnĕwéri֔ym mi⁠qá̇tò֖n wĕ⁠ʻad-gá̇d֑wòl wa⁠yi̇lĕʼ֖ẇ li⁠mĕẕò֥ʼ ha⁠páֽ̇ţaẖ׃"],[19,12,"וַ⁠יֹּאמְר֨וּ הָ⁠אֲנָשִׁ֜ים אֶל־ל֗וֹט עֹ֚ד מִֽי־לְ⁠ךָ֣ פֹ֔ה חָתָן֙ וּ⁠בָנֶ֣י⁠ךָ וּ⁠בְנֹתֶ֔י⁠ךָ וְ⁠כֹ֥ל אֲשֶׁר־לְ⁠ךָ֖ בָּ⁠עִ֑יר הוֹצֵ֖א מִן־הַ⁠מָּקֽוֹם׃","wa⁠yò̇ʼmĕr֨ẇ há⁠ʼànáşǐ֜ym ʼel-l֗wòt ʻò֚d miֽy-lĕ⁠ká֣ pò֔h ẖáţán֙ ẇ⁠báne֣y⁠ká ẇ⁠bĕnòţe֔y⁠ká wĕ⁠kò֥l ʼàşěr-lĕ⁠ká֖ bá̇⁠ʻi֑yr hwòẕé֖ʼ min-ha⁠má̇qֽwòm׃"],[19,13,"כִּֽי־מַשְׁחִתִ֣ים אֲנַ֔חְנוּ אֶת־הַ⁠מָּק֖וֹם הַ⁠זֶּ֑ה כִּֽי־גָֽדְלָ֤ה צַעֲקָתָ⁠ם֙ אֶת־פְּנֵ֣י יְהוָ֔ה וַ⁠יְשַׁלְּחֵ֥⁠נוּ יְהוָ֖ה לְ⁠שַׁחֲתָֽ⁠הּ׃","kiֽ̇y-maşĕ̌ẖiţi֣ym ʼàna֔ẖĕnẇ ʼeţ-ha⁠má̇q֖wòm ha⁠zė֑h kiֽ̇y-gֽádĕlá֤h ẕaʻàqáţá⁠m֙ ʼeţ-pĕ̇né֣y yĕhwá֔h wa⁠yĕşǎlĕ̇ẖé֥⁠nẇ yĕhwá֖h lĕ⁠şǎẖàţáֽ⁠ḣ׃"],[19,14,"וַ⁠יֵּצֵ֨א ל֜וֹט וַ⁠יְדַבֵּ֣ר ׀ אֶל־חֲתָנָ֣י⁠ו ׀ לֹקְחֵ֣י בְנֹתָ֗י⁠ו וַ⁠יֹּ֨אמֶר֙ ק֤וּמוּ צְּאוּ֙ מִן־הַ⁠מָּק֣וֹם הַ⁠זֶּ֔ה כִּֽי־מַשְׁחִ֥ית יְהוָ֖ה אֶת־הָ⁠עִ֑יר וַ⁠יְהִ֥י כִ⁠מְצַחֵ֖ק בְּ⁠עֵינֵ֥י חֲתָנָֽי⁠ו׃","wa⁠yé̇ẕé֨ʼ l֜wòt wa⁠yĕdabé֣̇r ׀ ʼel-ẖàţáná֣y⁠w ׀ lòqĕẖé֣y bĕnòţá֗y⁠w wa⁠yò̇֨ʼmer֙ q֤ẇmẇ ẕĕ̇ʼẇ֙ min-ha⁠má̇q֣wòm ha⁠zė֔h kiֽ̇y-maşĕ̌ẖi֥yţ yĕhwá֖h ʼeţ-há⁠ʻi֑yr wa⁠yĕhi֥y ki⁠mĕẕaẖé֖q bĕ̇⁠ʻéyné֥y ẖàţánáֽy⁠w׃"],[19,15,"וּ⁠כְמוֹ֙ הַ⁠שַּׁ֣חַר עָלָ֔ה וַ⁠יָּאִ֥יצוּ הַ⁠מַּלְאָכִ֖ים בְּ⁠ל֣וֹט לֵ⁠אמֹ֑ר קוּם֩ קַ֨ח אֶֽת־אִשְׁתְּ⁠ךָ֜ וְ⁠אֶת־שְׁתֵּ֤י בְנֹתֶ֨י⁠ךָ֙ הַ⁠נִּמְצָאֹ֔ת פֶּן־תִּסָּפֶ֖ה בַּ⁠עֲוֺ֥ן הָ⁠עִֽיר׃","ẇ⁠kĕmwò֙ ha⁠şȧ֣̌ẖar ʻálá֔h wa⁠yá̇ʼi֥yẕẇ ha⁠mȧlĕʼáki֖ym bĕ̇⁠l֣wòt lé⁠ʼmò֑r qẇm֩ qa֨ẖ ʼeֽţ-ʼişĕ̌ţĕ̇⁠ká֜ wĕ⁠ʼeţ-şĕ̌ţé֤̇y bĕnòţe֨y⁠ká֙ ha⁠ni̇mĕẕáʼò֔ţ pėn-ţi̇sá̇pe֖h bȧ⁠ʻàwֺ֥n há⁠ʻiֽyr׃"],[19,16,"וַֽ⁠יִּתְמַהְמָ֓הּ ׀ וַ⁠יַּחֲזִ֨קוּ הָ⁠אֲנָשִׁ֜ים בְּ⁠יָד֣⁠וֹ וּ⁠בְ⁠יַד־אִשְׁתּ֗⁠וֹ וּ⁠בְ⁠יַד֙ שְׁתֵּ֣י בְנֹתָ֔י⁠ו בְּ⁠חֶמְלַ֥ת יְהוָ֖ה עָלָ֑י⁠ו וַ⁠יֹּצִאֻ֥⁠הוּ וַ⁠יַּנִּחֻ֖⁠הוּ מִ⁠ח֥וּץ לָ⁠עִֽיר׃","wֽa⁠yi̇ţĕmahĕmá֓ḣ ׀ wa⁠yȧẖàzi֨qẇ há⁠ʼànáşǐ֜ym bĕ̇⁠yád֣⁠wò ẇ⁠bĕ⁠yad-ʼişĕ̌ţ̇֗⁠wò ẇ⁠bĕ⁠yad֙ şĕ̌ţé֣̇y bĕnòţá֔y⁠w bĕ̇⁠ẖemĕla֥ţ yĕhwá֖h ʻálá֑y⁠w wa⁠yò̇ẕiʼu֥⁠hẇ wa⁠yȧni̇ẖu֖⁠hẇ mi⁠ẖ֥ẇẕ lá⁠ʻiֽyr׃"],[19,17,"וַ⁠יְהִי֩ כְ⁠הוֹצִיאָ֨⁠ם אֹתָ֜⁠ם הַ⁠ח֗וּצָ⁠ה וַ⁠יֹּ֨אמֶר֙ הִמָּלֵ֣ט עַל־נַפְשֶׁ֔⁠ךָ אַל־תַּבִּ֣יט אַחֲרֶ֔י⁠ךָ וְ⁠אַֽל־תַּעֲמֹ֖ד בְּ⁠כָל־הַ⁠כִּכָּ֑ר הָ⁠הָ֥רָ⁠ה הִמָּלֵ֖ט פֶּן־תִּסָּפֶֽה׃","wa⁠yĕhiy֩ kĕ⁠hwòẕiyʼá֨⁠m ʼòţá֜⁠m ha⁠ẖ֗ẇẕá⁠h wa⁠yò̇֨ʼmer֙ himá̇lé֣t ʻal-napĕşě֔⁠ká ʼal-ţȧbi֣̇yt ʼaẖàre֔y⁠ká wĕ⁠ʼaֽl-ţȧʻàmò֖d bĕ̇⁠kál-ha⁠ki̇ká֑̇r há⁠há֥rá⁠h himá̇lé֖t pėn-ţi̇sá̇peֽh׃"],[19,18,"וַ⁠יֹּ֥אמֶר ל֖וֹט אֲלֵ⁠הֶ֑ם אַל־נָ֖א אֲדֹנָֽ⁠י׃","wa⁠yò֥̇ʼmer l֖wòt ʼàlé⁠he֑m ʼal-ná֖ʼ ʼàdònáֽ⁠y׃"],[19,19,"הִנֵּה־נָ֠א מָצָ֨א עַבְדְּ⁠ךָ֣ חֵן֮ בְּ⁠עֵינֶי⁠ךָ֒ וַ⁠תַּגְדֵּ֣ל חַסְדְּ⁠ךָ֗ אֲשֶׁ֤ר עָשִׂ֨יתָ֙ עִמָּדִ֔⁠י לְ⁠הַחֲי֖וֹת אֶת־נַפְשִׁ֑⁠י וְ⁠אָנֹכִ֗י לֹ֤א אוּכַל֙ לְ⁠הִמָּלֵ֣ט הָ⁠הָ֔רָ⁠ה פֶּן־תִּדְבָּקַ֥⁠נִי הָ⁠רָעָ֖ה וָ⁠מַֽתִּי׃","hiné̇h-ná֠ʼ máẕá֨ʼ ʻabĕdĕ̇⁠ká֣ ẖén֮ bĕ̇⁠ʻéyney⁠ká֒ wa⁠ţȧgĕdé֣̇l ẖasĕdĕ̇⁠ká֗ ʼàşě֤r ʻáşî֨yţá֙ ʻimá̇di֔⁠y lĕ⁠haẖày֖wòţ ʼeţ-napĕşǐ֑⁠y wĕ⁠ʼánòki֗y lò֤ʼ ʼẇkal֙ lĕ⁠himá̇lé֣t há⁠há֔rá⁠h pėn-ţi̇dĕbá̇qa֥⁠niy há⁠ráʻá֖h wá⁠maֽţi̇y׃"],[19,20,"הִנֵּה־נָ֠א הָ⁠עִ֨יר הַ⁠זֹּ֧את קְרֹבָ֛ה לָ⁠נ֥וּס שָׁ֖מָּ⁠ה וְ⁠הִ֣יא מִצְעָ֑ר אִמָּלְטָ֨ה נָּ֜א שָׁ֗מָּ⁠ה הֲ⁠לֹ֥א מִצְעָ֛ר הִ֖וא וּ⁠תְחִ֥י נַפְשִֽׁ⁠י׃","hiné̇h-ná֠ʼ há⁠ʻi֨yr ha⁠zò֧̇ʼţ qĕròbá֛h lá⁠n֥ẇs şá֖̌má̇⁠h wĕ⁠hi֣yʼ miẕĕʻá֑r ʼimá̇lĕtá֨h ná̇֜ʼ şá̌֗má̇⁠h hà⁠lò֥ʼ miẕĕʻá֛r hi֖wʼ ẇ⁠ţĕẖi֥y napĕşǐֽ⁠y׃"],[19,21,"וַ⁠יֹּ֣אמֶר אֵלָ֔י⁠ו הִנֵּה֙ נָשָׂ֣אתִי פָנֶ֔י⁠ךָ גַּ֖ם לַ⁠דָּבָ֣ר הַ⁠זֶּ֑ה לְ⁠בִלְתִּ֛י הָפְכִּ֥⁠י אֶת־הָ⁠עִ֖יר אֲשֶׁ֥ר דִּבַּֽרְתָּ׃","wa⁠yò֣̇ʼmer ʼélá֔y⁠w hiné̇h֙ náşá֣̂ʼţiy páne֔y⁠ká gȧ֖m la⁠dá̇bá֣r ha⁠zė֑h lĕ⁠bilĕţi֛̇y hápĕki֥̇⁠y ʼeţ-há⁠ʻi֖yr ʼàşě֥r di̇bȧֽrĕţá̇׃"],[19,22,"מַהֵר֙ הִמָּלֵ֣ט שָׁ֔מָּ⁠ה כִּ֣י לֹ֤א אוּכַל֙ לַ⁠עֲשׂ֣וֹת דָּבָ֔ר עַד־בֹּאֲ⁠ךָ֖ שָׁ֑מָּ⁠ה עַל־כֵּ֛ן קָרָ֥א שֵׁם־הָ⁠עִ֖יר צֽוֹעַר׃","mahér֙ himá̇lé֣t şá̌֔má̇⁠h ki֣̇y lò֤ʼ ʼẇkal֙ la⁠ʻàş֣̂wòţ dá̇bá֔r ʻad-bò̇ʼà⁠ká֖ şá֑̌má̇⁠h ʻal-ké֛̇n qárá֥ʼ şé̌m-há⁠ʻi֖yr ẕֽwòʻar׃"],[19,23,"הַ⁠שֶּׁ֖מֶשׁ יָצָ֣א עַל־הָ⁠אָ֑רֶץ וְ⁠ל֖וֹט בָּ֥א צֹֽעֲרָ⁠ה׃","ha⁠şė֖̌meş̌ yáẕá֣ʼ ʻal-há⁠ʼá֑reẕ wĕ⁠l֖wòt bá֥̇ʼ ẕòֽʻàrá⁠h׃"],[19,24,"וַֽ⁠יהוָ֗ה הִמְטִ֧יר עַל־סְדֹ֛ם וְ⁠עַל־עֲמֹרָ֖ה גָּפְרִ֣ית וָ⁠אֵ֑שׁ מֵ⁠אֵ֥ת יְהוָ֖ה מִן־הַ⁠שָּׁמָֽיִם׃","wֽa⁠yhwá֗h himĕti֧yr ʻal-sĕdò֛m wĕ⁠ʻal-ʻàmòrá֖h gá̇pĕri֣yţ wá⁠ʼé֑ş̌ mé⁠ʼé֥ţ yĕhwá֖h min-ha⁠şá̇̌máֽyim׃"],[19,25,"וַֽ⁠יַּהֲפֹךְ֙ אֶת־הֶ⁠עָרִ֣ים הָ⁠אֵ֔ל וְ⁠אֵ֖ת כָּל־הַ⁠כִּכָּ֑ר וְ⁠אֵת֙ כָּל־יֹשְׁבֵ֣י הֶ⁠עָרִ֔ים וְ⁠צֶ֖מַח הָ⁠אֲדָמָֽה׃","wֽa⁠yȧhàpòkĕ֙ ʼeţ-he⁠ʻári֣ym há⁠ʼé֔l wĕ⁠ʼé֖ţ ká̇l-ha⁠ki̇ká֑̇r wĕ⁠ʼéţ֙ ká̇l-yòşĕ̌bé֣y he⁠ʻári֔ym wĕ⁠ẕe֖maẖ há⁠ʼàdámáֽh׃"],[19,26,"וַ⁠תַּבֵּ֥ט אִשְׁתּ֖⁠וֹ מֵ⁠אַחֲרָ֑י⁠ו וַ⁠תְּהִ֖י נְצִ֥יב מֶֽלַח׃","wa⁠ţȧbé֥̇t ʼişĕ̌ţ֖̇⁠wò mé⁠ʼaẖàrá֑y⁠w wa⁠ţĕ̇hi֖y nĕẕi֥yb meֽlaẖ׃"],[19,27,"וַ⁠יַּשְׁכֵּ֥ם אַבְרָהָ֖ם בַּ⁠בֹּ֑קֶר אֶל־הַ֨⁠מָּק֔וֹם אֲשֶׁר־עָ֥מַד שָׁ֖ם אֶת־פְּנֵ֥י יְהוָֽה׃","wa⁠yȧşĕ̌ké֥̇m ʼabĕráhá֖m bȧ⁠bò֑̇qer ʼel-ha֨⁠má̇q֔wòm ʼàşěr-ʻá֥mad şá֖̌m ʼeţ-pĕ̇né֥y yĕhwáֽh׃"],[19,28,"וַ⁠יַּשְׁקֵ֗ף עַל־פְּנֵ֤י סְדֹם֙ וַ⁠עֲמֹרָ֔ה וְ⁠עַֽל־כָּל־פְּנֵ֖י אֶ֣רֶץ הַ⁠כִּכָּ֑ר וַ⁠יַּ֗רְא וְ⁠הִנֵּ֤ה עָלָה֙ קִיטֹ֣ר הָ⁠אָ֔רֶץ כְּ⁠קִיטֹ֖ר הַ⁠כִּבְשָֽׁן׃","wa⁠yȧşĕ̌qé֗p ʻal-pĕ̇né֤y sĕdòm֙ wa⁠ʻàmòrá֔h wĕ⁠ʻaֽl-ká̇l-pĕ̇né֖y ʼe֣reẕ ha⁠ki̇ká֑̇r wa⁠yȧ֗rĕʼ wĕ⁠hiné֤̇h ʻáláh֙ qiytò֣r há⁠ʼá֔reẕ kĕ̇⁠qiytò֖r ha⁠ki̇bĕşáֽ̌n׃"],[19,29,"וַ⁠יְהִ֗י בְּ⁠שַׁחֵ֤ת אֱלֹהִים֙ אֶת־עָרֵ֣י הַ⁠כִּכָּ֔ר וַ⁠יִּזְכֹּ֥ר אֱלֹהִ֖ים אֶת־אַבְרָהָ֑ם וַ⁠יְשַׁלַּ֤ח אֶת־לוֹט֙ מִ⁠תּ֣וֹךְ הַ⁠הֲפֵכָ֔ה בַּ⁠הֲפֹךְ֙ אֶת־הֶ֣⁠עָרִ֔ים אֲשֶׁר־יָשַׁ֥ב בָּ⁠הֵ֖ן לֽוֹט׃","wa⁠yĕhi֗y bĕ̇⁠şǎẖé֤ţ ʼèlòhiym֙ ʼeţ-ʻáré֣y ha⁠ki̇ká̇֔r wa⁠yi̇zĕkò֥̇r ʼèlòhi֖ym ʼeţ-ʼabĕráhá֑m wa⁠yĕşǎlȧ֤ẖ ʼeţ-lwòt֙ mi⁠ţ֣̇wòkĕ ha⁠hàpéká֔h bȧ⁠hàpòkĕ֙ ʼeţ-he֣⁠ʻári֔ym ʼàşěr-yáşǎ֥b bá̇⁠hé֖n lֽwòt׃"],[19,30,"וַ⁠יַּעַל֩ ל֨וֹט מִ⁠צּ֜וֹעַר וַ⁠יֵּ֣שֶׁב בָּ⁠הָ֗ר וּ⁠שְׁתֵּ֤י בְנֹתָי⁠ו֙ עִמּ֔⁠וֹ כִּ֥י יָרֵ֖א לָ⁠שֶׁ֣בֶת בְּ⁠צ֑וֹעַר וַ⁠יֵּ֨שֶׁב֙ בַּ⁠מְּעָרָ֔ה ה֖וּא וּ⁠שְׁתֵּ֥י בְנֹתָֽי⁠ו׃","wa⁠yȧʻal֩ l֨wòt mi⁠ẕ̇֜wòʻar wa⁠yé֣̇şěb bá̇⁠há֗r ẇ⁠şĕ̌ţé֤̇y bĕnòţáy⁠w֙ ʻiṁ֔⁠wò ki֥̇y yáré֖ʼ lá⁠şě֣beţ bĕ̇⁠ẕ֑wòʻar wa⁠yé̇֨şěb֙ bȧ⁠mĕ̇ʻárá֔h h֖ẇʼ ẇ⁠şĕ̌ţé֥̇y bĕnòţáֽy⁠w׃"],[19,31,"וַ⁠תֹּ֧אמֶר הַ⁠בְּכִירָ֛ה אֶל־הַ⁠צְּעִירָ֖ה אָבִ֣י⁠נוּ זָקֵ֑ן וְ⁠אִ֨ישׁ אֵ֤ין בָּ⁠אָ֨רֶץ֙ לָ⁠ב֣וֹא עָלֵ֔י⁠נוּ כְּ⁠דֶ֖רֶךְ כָּל־הָ⁠אָֽרֶץ׃","wa⁠ţò֧̇ʼmer ha⁠bĕ̇kiyrá֛h ʼel-ha⁠ẕĕ̇ʻiyrá֖h ʼábi֣y⁠nẇ záqé֑n wĕ⁠ʼi֨yş̌ ʼé֤yn bá̇⁠ʼá֨reẕ֙ lá⁠b֣wòʼ ʻálé֔y⁠nẇ kĕ̇⁠de֖rekĕ ká̇l-há⁠ʼáֽreẕ׃"],[19,32,"לְכָ֨⁠ה נַשְׁקֶ֧ה אֶת־אָבִ֛י⁠נוּ יַ֖יִן וְ⁠נִשְׁכְּבָ֣ה עִמּ֑⁠וֹ וּ⁠נְחַיֶּ֥ה מֵ⁠אָבִ֖י⁠נוּ זָֽרַע׃","lĕká֨⁠h naşĕ̌qe֧h ʼeţ-ʼábi֛y⁠nẇ ya֖yin wĕ⁠nişĕ̌kĕ̇bá֣h ʻiṁ֑⁠wò ẇ⁠nĕẖayė֥h mé⁠ʼábi֖y⁠nẇ záֽraʻ׃"],[19,33,"וַ⁠תַּשְׁקֶ֧יןָ אֶת־אֲבִי⁠הֶ֛ן יַ֖יִן בַּ⁠לַּ֣יְלָה ה֑וּא וַ⁠תָּבֹ֤א הַ⁠בְּכִירָה֙ וַ⁠תִּשְׁכַּ֣ב אֶת־אָבִ֔י⁠הָ וְ⁠לֹֽא־יָדַ֥ע בְּ⁠שִׁכְבָ֖⁠הּ וּ⁠בְ⁠קׄוּמָֽ⁠הּ׃","wa⁠ţȧşĕ̌qe֧yná ʼeţ-ʼàbiy⁠he֛n ya֖yin bȧ⁠lȧ֣yĕláh h֑ẇʼ wa⁠ţá̇bò֤ʼ ha⁠bĕ̇kiyráh֙ wa⁠ţi̇şĕ̌kȧ֣b ʼeţ-ʼábi֔y⁠há wĕ⁠lòֽʼ-yáda֥ʻ bĕ̇⁠şǐkĕbá֖⁠ḣ ẇ⁠bĕ⁠qׄẇmáֽ⁠ḣ׃"],[19,34,"וַֽ⁠יְהִי֙ מִֽ⁠מָּחֳרָ֔ת וַ⁠תֹּ֤אמֶר הַ⁠בְּכִירָה֙ אֶל־הַ⁠צְּעִירָ֔ה הֵן־שָׁכַ֥בְתִּי אֶ֖מֶשׁ אֶת־אָבִ֑⁠י נַשְׁקֶ֨⁠נּוּ יַ֜יִן גַּם־הַ⁠לַּ֗יְלָה וּ⁠בֹ֨אִי֙ שִׁכְבִ֣י עִמּ֔⁠וֹ וּ⁠נְחַיֶּ֥ה מֵ⁠אָבִ֖י⁠נוּ זָֽרַע׃","wֽa⁠yĕhiy֙ miֽ⁠má̇ẖorá֔ţ wa⁠ţò֤̇ʼmer ha⁠bĕ̇kiyráh֙ ʼel-ha⁠ẕĕ̇ʻiyrá֔h hén-şá̌ka֥bĕţi̇y ʼe֖meş̌ ʼeţ-ʼábi֑⁠y naşĕ̌qe֨⁠ṅẇ ya֜yin gȧm-ha⁠lȧ֗yĕláh ẇ⁠bò֨ʼiy֙ şǐkĕbi֣y ʻiṁ֔⁠wò ẇ⁠nĕẖayė֥h mé⁠ʼábi֖y⁠nẇ záֽraʻ׃"],[19,35,"וַ⁠תַּשְׁקֶ֜יןָ גַּ֣ם בַּ⁠לַּ֧יְלָה הַ⁠ה֛וּא אֶת־אֲבִי⁠הֶ֖ן יָ֑יִן וַ⁠תָּ֤קָם הַ⁠צְּעִירָה֙ וַ⁠תִּשְׁכַּ֣ב עִמּ֔⁠וֹ וְ⁠לֹֽא־יָדַ֥ע בְּ⁠שִׁכְבָ֖⁠הּ וּ⁠בְ⁠קֻמָֽ⁠הּ׃","wa⁠ţȧşĕ̌qe֜yná gȧ֣m bȧ⁠lȧ֧yĕláh ha⁠h֛ẇʼ ʼeţ-ʼàbiy⁠he֖n yá֑yin wa⁠ţá֤̇qám ha⁠ẕĕ̇ʻiyráh֙ wa⁠ţi̇şĕ̌kȧ֣b ʻiṁ֔⁠wò wĕ⁠lòֽʼ-yáda֥ʻ bĕ̇⁠şǐkĕbá֖⁠ḣ ẇ⁠bĕ⁠qumáֽ⁠ḣ׃"],[19,36,"וַֽ⁠תַּהֲרֶ֛יןָ שְׁתֵּ֥י בְנֽוֹת־ל֖וֹט מֵ⁠אֲבִי⁠הֶֽן׃","wֽa⁠ţȧhàre֛yná şĕ̌ţé֥̇y bĕnֽwòţ-l֖wòt mé⁠ʼàbiy⁠heֽn׃"],[19,37,"וַ⁠תֵּ֤לֶד הַ⁠בְּכִירָה֙ בֵּ֔ן וַ⁠תִּקְרָ֥א שְׁמ֖⁠וֹ מוֹאָ֑ב ה֥וּא אֲבִֽי־מוֹאָ֖ב עַד־הַ⁠יּֽוֹם׃","wa⁠ţé֤̇led ha⁠bĕ̇kiyráh֙ bé̇֔n wa⁠ţi̇qĕrá֥ʼ şĕ̌m֖⁠wò mwòʼá֑b h֥ẇʼ ʼàbiֽy-mwòʼá֖b ʻad-ha⁠ẏֽwòm׃"],[19,38,"וְ⁠הַ⁠צְּעִירָ֤ה גַם־הִוא֙ יָ֣לְדָה בֵּ֔ן וַ⁠תִּקְרָ֥א שְׁמ֖⁠וֹ בֶּן־עַמִּ֑י ה֛וּא אֲבִ֥י בְנֵֽי־עַמּ֖וֹן עַד־הַ⁠יּֽוֹם׃ס","wĕ⁠ha⁠ẕĕ̇ʻiyrá֤h gam-hiwʼ֙ yá֣lĕdáh bé̇֔n wa⁠ţi̇qĕrá֥ʼ şĕ̌m֖⁠wò bėn-ʻami֑̇y h֛ẇʼ ʼàbi֥y bĕnéֽy-ʻaṁ֖wòn ʻad-ha⁠ẏֽwòm׃s"],[20,1,"וַ⁠יִּסַּ֨ע מִ⁠שָּׁ֤ם אַבְרָהָם֙ אַ֣רְצָ⁠ה הַ⁠נֶּ֔גֶב וַ⁠יֵּ֥שֶׁב בֵּין־קָדֵ֖שׁ וּ⁠בֵ֣ין שׁ֑וּר וַ⁠יָּ֖גָר בִּ⁠גְרָֽר׃","wa⁠yi̇sȧ֨ʻ mi⁠şá֤̇̌m ʼabĕráhám֙ ʼa֣rĕẕá⁠h ha⁠nė֔geb wa⁠yé֥̇şěb bé̇yn-qádé֖ş̌ ẇ⁠bé֣yn ş֑̌ẇr wa⁠yá֖̇gár bi̇⁠gĕráֽr׃"],[20,2,"וַ⁠יֹּ֧אמֶר אַבְרָהָ֛ם אֶל־שָׂרָ֥ה אִשְׁתּ֖⁠וֹ אֲחֹ֣תִ⁠י הִ֑וא וַ⁠יִּשְׁלַ֗ח אֲבִימֶ֨לֶךְ֙ מֶ֣לֶךְ גְּרָ֔ר וַ⁠יִּקַּ֖ח אֶת־שָׂרָֽה׃","wa⁠yò֧̇ʼmer ʼabĕráhá֛m ʼel-şá̂rá֥h ʼişĕ̌ţ֖̇⁠wò ʼàẖò֣ţi⁠y hi֑wʼ wa⁠yi̇şĕ̌la֗ẖ ʼàbiyme֨lekĕ֙ me֣lekĕ gĕ̇rá֔r wa⁠yi̇qȧ֖ẖ ʼeţ-şá̂ráֽh׃"],[20,3,"וַ⁠יָּבֹ֧א אֱלֹהִ֛ים אֶל־אֲבִימֶ֖לֶךְ בַּ⁠חֲל֣וֹם הַ⁠לָּ֑יְלָה וַ⁠יֹּ֣אמֶר ל֗⁠וֹ הִנְּ⁠ךָ֥ מֵת֙ עַל־הָ⁠אִשָּׁ֣ה אֲשֶׁר־לָקַ֔חְתָּ וְ⁠הִ֖וא בְּעֻ֥לַת בָּֽעַל׃","wa⁠yá̇bò֧ʼ ʼèlòhi֛ym ʼel-ʼàbiyme֖lekĕ bȧ⁠ẖàl֣wòm ha⁠lá֑̇yĕláh wa⁠yò֣̇ʼmer l֗⁠wò hinĕ̇⁠ká֥ méţ֙ ʻal-há⁠ʼişá֣̇̌h ʼàşěr-láqa֔ẖĕţá̇ wĕ⁠hi֖wʼ bĕ̇ʻu֥laţ báֽ̇ʻal׃"],[20,4,"וַ⁠אֲבִימֶ֕לֶךְ לֹ֥א קָרַ֖ב אֵלֶ֑י⁠הָ וַ⁠יֹּאמַ֕ר אֲדֹנָ֕⁠י הֲ⁠ג֥וֹי גַּם־צַדִּ֖יק תַּהֲרֹֽג׃","wa⁠ʼàbiyme֕lekĕ lò֥ʼ qára֖b ʼéle֑y⁠há wa⁠yò̇ʼma֕r ʼàdòná֕⁠y hà⁠g֥wòy gȧm-ẕadi֖̇yq ţȧhàròֽg׃"],[20,5,"הֲ⁠לֹ֨א ה֤וּא אָֽמַר־לִ⁠י֙ אֲחֹ֣תִ⁠י הִ֔וא וְ⁠הִֽיא־גַם־הִ֥וא אָֽמְרָ֖ה אָחִ֣⁠י ה֑וּא בְּ⁠תָם־לְבָבִ֛⁠י וּ⁠בְ⁠נִקְיֹ֥ן כַּפַּ֖⁠י עָשִׂ֥יתִי זֹֽאת׃","hà⁠lò֨ʼ h֤ẇʼ ʼáֽmar-li⁠y֙ ʼàẖò֣ţi⁠y hi֔wʼ wĕ⁠hiֽyʼ-gam-hi֥wʼ ʼֽámĕrá֖h ʼáẖi֣⁠y h֑ẇʼ bĕ̇⁠ţám-lĕbábi֛⁠y ẇ⁠bĕ⁠niqĕyò֥n kȧpȧ֖⁠y ʻáşî֥yţiy zòֽʼţ׃"],[20,6,"וַ⁠יֹּאמֶר֩ אֵלָ֨י⁠ו הָֽ⁠אֱלֹהִ֜ים בַּ⁠חֲלֹ֗ם גַּ֣ם אָנֹכִ֤י יָדַ֨עְתִּי֙ כִּ֤י בְ⁠תָם־לְבָבְ⁠ךָ֙ עָשִׂ֣יתָ זֹּ֔את וָ⁠אֶחְשֹׂ֧ךְ גַּם־אָנֹכִ֛י אֽוֹתְ⁠ךָ֖ מֵ⁠חֲטוֹ־לִ֑⁠י עַל־כֵּ֥ן לֹא־נְתַתִּ֖י⁠ךָ לִ⁠נְגֹּ֥עַ אֵלֶֽי⁠הָ׃","wa⁠yò̇ʼmer֩ ʼélá֨y⁠w hֽá⁠ʼèlòhi֜ym bȧ⁠ẖàlò֗m gȧ֣m ʼánòki֤y yáda֨ʻĕţi̇y֙ ki֤̇y bĕ⁠ţám-lĕbábĕ⁠ká֙ ʻáşî֣yţá zò̇֔ʼţ wá⁠ʼeẖĕşò֧̂kĕ gȧm-ʼánòki֛y ʼֽwòţĕ⁠ká֖ mé⁠ẖàtwò-li֑⁠y ʻal-ké֥̇n lòʼ-nĕţaţi֖̇y⁠ká li⁠nĕgò֥̇ʻa ʼéleֽy⁠há׃"],[20,7,"וְ⁠עַתָּ֗ה הָשֵׁ֤ב אֵֽשֶׁת־הָ⁠אִישׁ֙ כִּֽי־נָבִ֣יא ה֔וּא וְ⁠יִתְפַּלֵּ֥ל בַּֽעַדְ⁠ךָ֖ וֶֽ⁠חְיֵ֑ה וְ⁠אִם־אֵֽינְ⁠ךָ֣ מֵשִׁ֗יב דַּ֚ע כִּי־מ֣וֹת תָּמ֔וּת אַתָּ֖ה וְ⁠כָל־אֲשֶׁר־לָֽ⁠ךְ׃","wĕ⁠ʻaţá̇֗h háşé֤̌b ʼéֽşěţ-há⁠ʼiyş̌֙ kiֽ̇y-nábi֣yʼ h֔ẇʼ wĕ⁠yiţĕpȧlé֥̇l ḃֽaʻadĕ⁠ká֖ weֽ⁠ẖĕyé֑h wĕ⁠ʼim-ʼéֽynĕ⁠ká֣ méşǐ֗yb dȧ֚ʻ ki̇y-m֣wòţ ţá̇m֔ẇţ ʼaţá֖̇h wĕ⁠kál-ʼàşěr-láֽ⁠kĕ׃"],[20,8,"וַ⁠יַּשְׁכֵּ֨ם אֲבִימֶ֜לֶךְ בַּ⁠בֹּ֗קֶר וַ⁠יִּקְרָא֙ לְ⁠כָל־עֲבָדָ֔י⁠ו וַ⁠יְדַבֵּ֛ר אֶת־כָּל־הַ⁠דְּבָרִ֥ים הָ⁠אֵ֖לֶּה בְּ⁠אָזְנֵי⁠הֶ֑ם וַ⁠יִּֽירְא֥וּ הָ⁠אֲנָשִׁ֖ים מְאֹֽד׃","wa⁠yȧşĕ̌ké̇֨m ʼàbiyme֜lekĕ bȧ⁠bò̇֗qer wa⁠yi̇qĕráʼ֙ lĕ⁠kál-ʻàbádá֔y⁠w wa⁠yĕdabé֛̇r ʼeţ-ká̇l-ha⁠dĕ̇bári֥ym há⁠ʼé֖lėh bĕ̇⁠ʼázĕnéy⁠he֑m wa⁠yiֽ̇yrĕʼ֥ẇ há⁠ʼànáşǐ֖ym mĕʼòֽd׃"],[20,9,"וַ⁠יִּקְרָ֨א אֲבִימֶ֜לֶךְ לְ⁠אַבְרָהָ֗ם וַ⁠יֹּ֨אמֶר ל֜⁠וֹ מֶֽה־עָשִׂ֤יתָ לָּ֨⁠נוּ֙ וּ⁠מֶֽה־חָטָ֣אתִי לָ֔⁠ךְ כִּֽי־הֵבֵ֧אתָ עָלַ֛⁠י וְ⁠עַל־מַמְלַכְתִּ֖⁠י חֲטָאָ֣ה גְדֹלָ֑ה מַעֲשִׂים֙ אֲשֶׁ֣ר לֹא־יֵֽעָשׂ֔וּ עָשִׂ֖יתָ עִמָּדִֽ⁠י׃","wa⁠yi̇qĕrá֨ʼ ʼàbiyme֜lekĕ lĕ⁠ʼabĕráhá֗m wa⁠yò̇֨ʼmer l֜⁠wò meֽh-ʻáşî֤yţá lá̇֨⁠nẇ֙ ẇ⁠meֽh-ẖátá֣ʼţiy lá֔⁠kĕ kiֽ̇y-hébé֧ʼţá ʻála֛⁠y wĕ⁠ʻal-mamĕlakĕţi֖̇⁠y ẖàtáʼá֣h gĕdòlá֑h maʻàşîym֙ ʼàşě֣r lòʼ-yéֽʻáş̂֔ẇ ʻáşî֖yţá ʻimá̇diֽ⁠y׃"],[20,10,"וַ⁠יֹּ֥אמֶר אֲבִימֶ֖לֶךְ אֶל־אַבְרָהָ֑ם מָ֣ה רָאִ֔יתָ כִּ֥י עָשִׂ֖יתָ אֶת־הַ⁠דָּבָ֥ר הַ⁠זֶּֽה׃","wa⁠yò֥̇ʼmer ʼàbiyme֖lekĕ ʼel-ʼabĕráhá֑m má֣h ráʼi֔yţá ki֥̇y ʻáşî֖yţá ʼeţ-ha⁠dá̇bá֥r ha⁠zėֽh׃"],[20,11,"וַ⁠יֹּ֨אמֶר֙ אַבְרָהָ֔ם כִּ֣י אָמַ֗רְתִּי רַ֚ק אֵין־יִרְאַ֣ת אֱלֹהִ֔ים בַּ⁠מָּק֖וֹם הַ⁠זֶּ֑ה וַ⁠הֲרָג֖וּ⁠נִי עַל־דְּבַ֥ר אִשְׁתִּֽ⁠י׃","wa⁠yò̇֨ʼmer֙ ʼabĕráhá֔m ki֣̇y ʼáma֗rĕţi̇y ra֚q ʼéyn-yirĕʼa֣ţ ʼèlòhi֔ym bȧ⁠má̇q֖wòm ha⁠zė֑h wa⁠hàrág֖ẇ⁠niy ʻal-dĕ̇ba֥r ʼişĕ̌ţiֽ̇⁠y׃"],[20,12,"וְ⁠גַם־אָמְנָ֗ה אֲחֹתִ֤⁠י בַת־אָבִ⁠י֙ הִ֔וא אַ֖ךְ לֹ֣א בַת־אִמִּ֑⁠י וַ⁠תְּהִי־לִ֖⁠י לְ⁠אִשָּֽׁה׃","wĕ⁠gam-ʼámĕná֗h ʼàẖòţi֤⁠y baţ-ʼábi⁠y֙ hi֔wʼ ʼa֖kĕ lò֣ʼ baţ-ʼimi֑̇⁠y wa⁠ţĕ̇hiy-li֖⁠y lĕ⁠ʼişáֽ̇̌h׃"],[20,13,"וַ⁠יְהִ֞י כַּ⁠אֲשֶׁ֧ר הִתְע֣וּ אֹתִ֗⁠י אֱלֹהִים֮ מִ⁠בֵּ֣ית אָבִ⁠י֒ וָ⁠אֹמַ֣ר לָ֔⁠הּ זֶ֣ה חַסְדֵּ֔⁠ךְ אֲשֶׁ֥ר תַּעֲשִׂ֖י עִמָּדִ֑⁠י אֶ֤ל כָּל־הַ⁠מָּקוֹם֙ אֲשֶׁ֣ר נָב֣וֹא שָׁ֔מָּ⁠ה אִמְרִי־לִ֖⁠י אָחִ֥⁠י הֽוּא׃","wa⁠yĕhi֞y kȧ⁠ʼàşě֧r hiţĕʻ֣ẇ ʼòţi֗⁠y ʼèlòhiym֮ mi⁠bé֣̇yţ ʼábi⁠y֒ wá⁠ʼòma֣r lá֔⁠ḣ ze֣h ẖasĕdé̇֔⁠kĕ ʼàşě֥r ţȧʻàşî֖y ʻimá̇di֑⁠y ʼe֤l ká̇l-ha⁠má̇qwòm֙ ʼàşě֣r náb֣wòʼ şá̌֔má̇⁠h ʼimĕriy-li֖⁠y ʼáẖi֥⁠y hֽẇʼ׃"],[20,14,"וַ⁠יִּקַּ֨ח אֲבִימֶ֜לֶךְ צֹ֣אן וּ⁠בָקָ֗ר וַ⁠עֲבָדִים֙ וּ⁠שְׁפָחֹ֔ת וַ⁠יִּתֵּ֖ן לְ⁠אַבְרָהָ֑ם וַ⁠יָּ֣שֶׁב ל֔⁠וֹ אֵ֖ת שָׂרָ֥ה אִשְׁתּֽ⁠וֹ׃","wa⁠yi̇qȧ֨ẖ ʼàbiyme֜lekĕ ẕò֣ʼn ẇ⁠báqá֗r wa⁠ʻàbádiym֙ ẇ⁠şĕ̌páẖò֔ţ wa⁠yi̇ţé֖̇n lĕ⁠ʼabĕráhá֑m wa⁠yá֣̇şěb l֔⁠wò ʼé֖ţ şá̂rá֥h ʼişĕ̌ţֽ̇⁠wò׃"],[20,15,"וַ⁠יֹּ֣אמֶר אֲבִימֶ֔לֶךְ הִנֵּ֥ה אַרְצִ֖⁠י לְ⁠פָנֶ֑י⁠ךָ בַּ⁠טּ֥וֹב בְּ⁠עֵינֶ֖י⁠ךָ שֵֽׁב׃","wa⁠yò֣̇ʼmer ʼàbiyme֔lekĕ hiné֥̇h ʼarĕẕi֖⁠y lĕ⁠páne֑y⁠ká bȧ⁠ṫ֥wòb bĕ̇⁠ʻéyne֖y⁠ká şéֽ̌b׃"],[20,16,"וּ⁠לְ⁠שָׂרָ֣ה אָמַ֗ר הִנֵּ֨ה נָתַ֜תִּי אֶ֤לֶף כֶּ֨סֶף֙ לְ⁠אָחִ֔י⁠ךְ הִנֵּ֤ה הוּא־לָ⁠ךְ֙ כְּס֣וּת עֵינַ֔יִם לְ⁠כֹ֖ל אֲשֶׁ֣ר אִתָּ֑⁠ךְ וְ⁠אֵ֥ת כֹּ֖ל וְ⁠נֹכָֽחַת׃","ẇ⁠lĕ⁠şá̂rá֣h ʼáma֗r hiné̇֨h náţa֜ţi̇y ʼe֤lep kė֨sep֙ lĕ⁠ʼáẖi֔y⁠kĕ hiné֤̇h hẇʼ-lá⁠kĕ֙ kĕ̇s֣ẇţ ʻéyna֔yim lĕ⁠kò֖l ʼàşě֣r ʼiţá֑̇⁠kĕ wĕ⁠ʼé֥ţ kò֖̇l wĕ⁠nòkáֽẖaţ׃"],[20,17,"וַ⁠יִּתְפַּלֵּ֥ל אַבְרָהָ֖ם אֶל־הָ⁠אֱלֹהִ֑ים וַ⁠יִּרְפָּ֨א אֱלֹהִ֜ים אֶת־אֲבִימֶ֧לֶךְ וְ⁠אֶת־אִשְׁתּ֛⁠וֹ וְ⁠אַמְהֹתָ֖י⁠ו וַ⁠יֵּלֵֽדוּ׃","wa⁠yi̇ţĕpȧlé֥̇l ʼabĕráhá֖m ʼel-há⁠ʼèlòhi֑ym wa⁠yi̇rĕpá̇֨ʼ ʼèlòhi֜ym ʼeţ-ʼàbiyme֧lekĕ wĕ⁠ʼeţ-ʼişĕ̌ţ֛̇⁠wò wĕ⁠ʼamĕhòţá֖y⁠w wa⁠yé̇léֽdẇ׃"],[20,18,"כִּֽי־עָצֹ֤ר עָצַר֙ יְהוָ֔ה בְּעַ֥ד כָּל־רֶ֖חֶם לְ⁠בֵ֣ית אֲבִימֶ֑לֶךְ עַל־דְּבַ֥ר שָׂרָ֖ה אֵ֥שֶׁת אַבְרָהָֽם׃ס","kiֽ̇y-ʻáẕò֤r ʻáẕar֙ yĕhwá֔h bĕ̇ʻa֥d ká̇l-re֖ẖem lĕ⁠bé֣yţ ʼàbiyme֑lekĕ ʻal-dĕ̇ba֥r şá̂rá֖h ʼé֥şěţ ʼabĕráháֽm׃s"],[21,1,"וַֽ⁠יהוָ֛ה פָּקַ֥ד אֶת־שָׂרָ֖ה כַּ⁠אֲשֶׁ֣ר אָמָ֑ר וַ⁠יַּ֧עַשׂ יְהוָ֛ה לְ⁠שָׂרָ֖ה כַּ⁠אֲשֶׁ֥ר דִּבֵּֽר׃","wֽa⁠yhwá֛h pá̇qa֥d ʼeţ-şá̂rá֖h kȧ⁠ʼàşě֣r ʼámá֑r wa⁠yȧ֧ʻaş̂ yĕhwá֛h lĕ⁠şá̂rá֖h kȧ⁠ʼàşě֥r di̇béֽ̇r׃"],[21,2,"וַ⁠תַּהַר֩ וַ⁠תֵּ֨לֶד שָׂרָ֧ה לְ⁠אַבְרָהָ֛ם בֵּ֖ן לִ⁠זְקֻנָ֑י⁠ו לַ⁠מּוֹעֵ֕ד אֲשֶׁר־דִּבֶּ֥ר אֹת֖⁠וֹ אֱלֹהִֽים׃","wa⁠ţȧhar֩ wa⁠ţé̇֨led şá̂rá֧h lĕ⁠ʼabĕráhá֛m bé֖̇n li⁠zĕquná֑y⁠w la⁠ṁwòʻé֕d ʼàşěr-di̇bė֥r ʼòţ֖⁠wò ʼèlòhiֽym׃"],[21,3,"וַ⁠יִּקְרָ֨א אַבְרָהָ֜ם אֶֽת־שֶׁם־בְּנ֧⁠וֹ הַ⁠נּֽוֹלַד־ל֛⁠וֹ אֲשֶׁר־יָלְדָה־לּ֥⁠וֹ שָׂרָ֖ה יִצְחָֽק׃","wa⁠yi̇qĕrá֨ʼ ʼabĕráhá֜m ʼeֽţ-şěm-bĕ̇n֧⁠wò ha⁠ṅֽwòlad-l֛⁠wò ʼàşěr-yálĕdáh-l֥̇⁠wò şá̂rá֖h yiẕĕẖáֽq׃"],[21,4,"וַ⁠יָּ֤מָל אַבְרָהָם֙ אֶת־יִצְחָ֣ק בְּנ֔⁠וֹ בֶּן־שְׁמֹנַ֖ת יָמִ֑ים כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה אֹת֖⁠וֹ אֱלֹהִֽים׃","wa⁠yá֤̇mál ʼabĕráhám֙ ʼeţ-yiẕĕẖá֣q bĕ̇n֔⁠wò bėn-şĕ̌mòna֖ţ yámi֑ym kȧ⁠ʼàşě֛r ẕiwá֥̇h ʼòţ֖⁠wò ʼèlòhiֽym׃"],[21,5,"וְ⁠אַבְרָהָ֖ם בֶּן־מְאַ֣ת שָׁנָ֑ה בְּ⁠הִוָּ֣לֶד ל֔⁠וֹ אֵ֖ת יִצְחָ֥ק בְּנֽ⁠וֹ׃","wĕ⁠ʼabĕráhá֖m bėn-mĕʼa֣ţ şá̌ná֑h bĕ̇⁠hiwá֣̇led l֔⁠wò ʼé֖ţ yiẕĕẖá֥q bĕ̇nֽ⁠wò׃"],[21,6,"וַ⁠תֹּ֣אמֶר שָׂרָ֔ה צְחֹ֕ק עָ֥שָׂה לִ֖⁠י אֱלֹהִ֑ים כָּל־הַ⁠שֹּׁמֵ֖עַ יִֽצְחַק־לִֽ⁠י׃","wa⁠ţò֣̇ʼmer şá̂rá֔h ẕĕẖò֕q ʻá֥şá̂h li֖⁠y ʼèlòhi֑ym ká̇l-ha⁠şò̇̌mé֖ʻa yiֽẕĕẖaq-liֽ⁠y׃"],[21,7,"וַ⁠תֹּ֗אמֶר מִ֤י מִלֵּל֙ לְ⁠אַבְרָהָ֔ם הֵינִ֥יקָה בָנִ֖ים שָׂרָ֑ה כִּֽי־יָלַ֥דְתִּי בֵ֖ן לִ⁠זְקֻנָֽי⁠ו׃","wa⁠ţò̇֗ʼmer mi֤y milé̇l֙ lĕ⁠ʼabĕráhá֔m héyni֥yqáh báni֖ym şá̂rá֑h kiֽ̇y-yála֥dĕţi̇y bé֖n li⁠zĕqunáֽy⁠w׃"],[21,8,"וַ⁠יִּגְדַּ֥ל הַ⁠יֶּ֖לֶד וַ⁠יִּגָּמַ֑ל וַ⁠יַּ֤עַשׂ אַבְרָהָם֙ מִשְׁתֶּ֣ה גָד֔וֹל בְּ⁠י֖וֹם הִגָּמֵ֥ל אֶת־יִצְחָֽק׃","wa⁠yi̇gĕdȧ֥l ha⁠yė֖led wa⁠yi̇gá̇ma֑l wa⁠yȧ֤ʻaş̂ ʼabĕráhám֙ mişĕ̌ţė֣h gád֔wòl bĕ̇⁠y֖wòm higá̇mé֥l ʼeţ-yiẕĕẖáֽq׃"],[21,9,"וַ⁠תֵּ֨רֶא שָׂרָ֜ה אֶֽת־בֶּן־הָגָ֧ר הַ⁠מִּצְרִ֛ית אֲשֶׁר־יָלְדָ֥ה לְ⁠אַבְרָהָ֖ם מְצַחֵֽק׃","wa⁠ţé̇֨reʼ şá̂rá֜h ʼeֽţ-bėn-hágá֧r ha⁠mi̇ẕĕri֛yţ ʼàşěr-yálĕdá֥h lĕ⁠ʼabĕráhá֖m mĕẕaẖéֽq׃"],[21,10,"וַ⁠תֹּ֨אמֶר֙ לְ⁠אַבְרָהָ֔ם גָּרֵ֛שׁ הָ⁠אָמָ֥ה הַ⁠זֹּ֖את וְ⁠אֶת־בְּנָ֑⁠הּ כִּ֣י לֹ֤א יִירַשׁ֙ בֶּן־הָ⁠אָמָ֣ה הַ⁠זֹּ֔את עִם־בְּנִ֖⁠י עִם־יִצְחָֽק׃","wa⁠ţò̇֨ʼmer֙ lĕ⁠ʼabĕráhá֔m gá̇ré֛ş̌ há⁠ʼámá֥h ha⁠zò֖̇ʼţ wĕ⁠ʼeţ-bĕ̇ná֑⁠ḣ ki֣̇y lò֤ʼ yiyraş̌֙ bėn-há⁠ʼámá֣h ha⁠zò̇֔ʼţ ʻim-bĕ̇ni֖⁠y ʻim-yiẕĕẖáֽq׃"],[21,11,"וַ⁠יֵּ֧רַע הַ⁠דָּבָ֛ר מְאֹ֖ד בְּ⁠עֵינֵ֣י אַבְרָהָ֑ם עַ֖ל אוֹדֹ֥ת בְּנֽ⁠וֹ׃","wa⁠yé֧̇raʻ ha⁠dá̇bá֛r mĕʼò֖d bĕ̇⁠ʻéyné֣y ʼabĕráhá֑m ʻa֖l ʼwòdò֥ţ bĕ̇nֽ⁠wò׃"],[21,12,"וַ⁠יֹּ֨אמֶר אֱלֹהִ֜ים אֶל־אַבְרָהָ֗ם אַל־יֵרַ֤ע בְּ⁠עֵינֶ֨י⁠ךָ֙ עַל־הַ⁠נַּ֣עַר וְ⁠עַל־אֲמָתֶ֔⁠ךָ כֹּל֩ אֲשֶׁ֨ר תֹּאמַ֥ר אֵלֶ֛י⁠ךָ שָׂרָ֖ה שְׁמַ֣ע בְּ⁠קֹלָ֑⁠הּ כִּ֣י בְ⁠יִצְחָ֔ק יִקָּרֵ֥א לְ⁠ךָ֖ זָֽרַע׃","wa⁠yò̇֨ʼmer ʼèlòhi֜ym ʼel-ʼabĕráhá֗m ʼal-yéra֤ʻ bĕ̇⁠ʻéyne֨y⁠ká֙ ʻal-ha⁠nȧ֣ʻar wĕ⁠ʻal-ʼàmáţe֔⁠ká kò̇l֩ ʼàşě֨r ţò̇ʼma֥r ʼéle֛y⁠ká şá̂rá֖h şĕ̌ma֣ʻ bĕ̇⁠qòlá֑⁠ḣ ki֣̇y bĕ⁠yiẕĕẖá֔q yiqá̇ré֥ʼ lĕ⁠ká֖ záֽraʻ׃"],[21,13,"וְ⁠גַ֥ם אֶת־בֶּן־הָ⁠אָמָ֖ה לְ⁠ג֣וֹי אֲשִׂימֶ֑⁠נּוּ כִּ֥י זַרְעֲ⁠ךָ֖ הֽוּא׃","wĕ⁠ga֥m ʼeţ-bėn-há⁠ʼámá֖h lĕ⁠g֣wòy ʼàşîyme֑⁠ṅẇ ki֥̇y zarĕʻà⁠ká֖ hֽẇʼ׃"],[21,14,"וַ⁠יַּשְׁכֵּ֣ם אַבְרָהָ֣ם ׀ בַּ⁠בֹּ֡קֶר וַ⁠יִּֽקַּֽח־לֶחֶם֩ וְ⁠חֵ֨מַת מַ֜יִם וַ⁠יִּתֵּ֣ן אֶל־הָ֠גָר שָׂ֧ם עַל־שִׁכְמָ֛⁠הּ וְ⁠אֶת־הַ⁠יֶּ֖לֶד וַֽ⁠יְשַׁלְּחֶ֑⁠הָ וַ⁠תֵּ֣לֶךְ וַ⁠תֵּ֔תַע בְּ⁠מִדְבַּ֖ר בְּאֵ֥ר שָֽׁבַע׃","wa⁠yȧşĕ̌ké֣̇m ʼabĕráhá֣m ׀ bȧ⁠bò̇֡qer wa⁠yiֽ̇qȧֽẖ-leẖem֩ wĕ⁠ẖé֨maţ ma֜yim wa⁠yi̇ţé֣̇n ʼel-há֠gár şá֧̂m ʻal-şǐkĕmá֛⁠ḣ wĕ⁠ʼeţ-ha⁠yė֖led waֽ⁠yĕşǎlĕ̇ẖe֑⁠há wa⁠ţé֣̇lekĕ wa⁠ţé̇֔ţaʻ bĕ̇⁠midĕbȧ֖r bĕ̇ʼé֥r şáֽ̌baʻ׃"],[21,15,"וַ⁠יִּכְל֥וּ הַ⁠מַּ֖יִם מִן־הַ⁠חֵ֑מֶת וַ⁠תַּשְׁלֵ֣ךְ אֶת־הַ⁠יֶּ֔לֶד תַּ֖חַת אַחַ֥ד הַ⁠שִּׂיחִֽם׃","wa⁠yi̇kĕl֥ẇ ha⁠mȧ֖yim min-ha⁠ẖé֑meţ wa⁠ţȧşĕ̌lé֣kĕ ʼeţ-ha⁠yė֔led ţȧ֖ẖaţ ʼaẖa֥d ha⁠şi̇̂yẖiֽm׃"],[21,16,"וַ⁠תֵּלֶךְ֩ וַ⁠תֵּ֨שֶׁב לָ֜⁠הּ מִ⁠נֶּ֗גֶד הַרְחֵק֙ כִּ⁠מְטַחֲוֵ֣י קֶ֔שֶׁת כִּ֣י אָֽמְרָ֔ה אַל־אֶרְאֶ֖ה בְּ⁠מ֣וֹת הַ⁠יָּ֑לֶד וַ⁠תֵּ֣שֶׁב מִ⁠נֶּ֔גֶד וַ⁠תִּשָּׂ֥א אֶת־קֹלָ֖⁠הּ וַ⁠תֵּֽבְךְּ׃","wa⁠ţé̇lekĕ֩ wa⁠ţé̇֨şěb lá֜⁠ḣ mi⁠nė֗ged harĕẖéq֙ ki̇⁠mĕtaẖàwé֣y qe֔şěţ ki֣̇y ʼֽámĕrá֔h ʼal-ʼerĕʼe֖h bĕ̇⁠m֣wòţ ha⁠yá֑̇led wa⁠ţé֣̇şěb mi⁠nė֔ged wa⁠ţi̇şá֥̇̂ʼ ʼeţ-qòlá֖⁠ḣ wa⁠ţéֽ̇bĕkĕ̇׃"],[21,17,"וַ⁠יִּשְׁמַ֣ע אֱלֹהִים֮ אֶת־ק֣וֹל הַ⁠נַּעַר֒ וַ⁠יִּקְרָא֩ מַלְאַ֨ךְ אֱלֹהִ֤ים ׀ אֶל־הָגָר֙ מִן־הַ⁠שָּׁמַ֔יִם וַ⁠יֹּ֥אמֶר לָ֖⁠הּ מַה־לָּ֣⁠ךְ הָגָ֑ר אַל־תִּ֣ירְאִ֔י כִּֽי־שָׁמַ֧ע אֱלֹהִ֛ים אֶל־ק֥וֹל הַ⁠נַּ֖עַר בַּ⁠אֲשֶׁ֥ר הוּא־שָֽׁם׃","wa⁠yi̇şĕ̌ma֣ʻ ʼèlòhiym֮ ʼeţ-q֣wòl ha⁠nȧʻar֒ wa⁠yi̇qĕráʼ֩ malĕʼa֨kĕ ʼèlòhi֤ym ׀ ʼel-hágár֙ min-ha⁠şá̇̌ma֔yim wa⁠yò֥̇ʼmer lá֖⁠ḣ mah-lá֣̇⁠kĕ hágá֑r ʼal-ţi֣̇yrĕʼi֔y kiֽ̇y-şá̌ma֧ʻ ʼèlòhi֛ym ʼel-q֥wòl ha⁠nȧ֖ʻar bȧ⁠ʼàşě֥r hẇʼ-şáֽ̌m׃"],[21,18,"ק֚וּמִי שְׂאִ֣י אֶת־הַ⁠נַּ֔עַר וְ⁠הַחֲזִ֥יקִי אֶת־יָדֵ֖⁠ךְ בּ֑⁠וֹ כִּֽי־לְ⁠ג֥וֹי גָּד֖וֹל אֲשִׂימֶֽ⁠נּוּ׃","q֚ẇmiy şĕ̂ʼi֣y ʼeţ-ha⁠nȧ֔ʻar wĕ⁠haẖàzi֥yqiy ʼeţ-yádé֖⁠kĕ ḃ֑⁠wò kiֽ̇y-lĕ⁠g֥wòy gá̇d֖wòl ʼàşîymeֽ⁠ṅẇ׃"],[21,19,"וַ⁠יִּפְקַ֤ח אֱלֹהִים֙ אֶת־עֵינֶ֔י⁠הָ וַ⁠תֵּ֖רֶא בְּאֵ֣ר מָ֑יִם וַ⁠תֵּ֜לֶךְ וַ⁠תְּמַלֵּ֤א אֶת־הַ⁠חֵ֨מֶת֙ מַ֔יִם וַ⁠תַּ֖שְׁקְ אֶת־הַ⁠נָּֽעַר׃","wa⁠yi̇pĕqa֤ẖ ʼèlòhiym֙ ʼeţ-ʻéyne֔y⁠há wa⁠ţé֖̇reʼ bĕ̇ʼé֣r má֑yim wa⁠ţé̇֜lekĕ wa⁠ţĕ̇malé֤̇ʼ ʼeţ-ha⁠ẖé֨meţ֙ ma֔yim wa⁠ţȧ֖şĕ̌qĕ ʼeţ-ha⁠náֽ̇ʻar׃"],[21,20,"וַ⁠יְהִ֧י אֱלֹהִ֛ים אֶת־הַ⁠נַּ֖עַר וַ⁠יִּגְדָּ֑ל וַ⁠יֵּ֨שֶׁב֙ בַּ⁠מִּדְבָּ֔ר וַ⁠יְהִ֖י רֹבֶ֥ה קַשָּֽׁת׃","wa⁠yĕhi֧y ʼèlòhi֛ym ʼeţ-ha⁠nȧ֖ʻar wa⁠yi̇gĕdá֑̇l wa⁠yé̇֨şěb֙ bȧ⁠mi̇dĕbá̇֔r wa⁠yĕhi֖y ròbe֥h qaşáֽ̇̌ţ׃"],[21,21,"וַ⁠יֵּ֖שֶׁב בְּ⁠מִדְבַּ֣ר פָּארָ֑ן וַ⁠תִּֽקַּֽח־ל֥⁠וֹ אִמּ֛⁠וֹ אִשָּׁ֖ה מֵ⁠אֶ֥רֶץ מִצְרָֽיִם׃פ","wa⁠yé֖̇şěb bĕ̇⁠midĕbȧ֣r pá̇ʼrá֑n wa⁠ţiֽ̇qȧֽẖ-l֥⁠wò ʼiṁ֛⁠wò ʼişá֖̇̌h mé⁠ʼe֥reẕ miẕĕráֽyim׃p"],[21,22,"וַֽ⁠יְהִי֙ בָּ⁠עֵ֣ת הַ⁠הִ֔וא וַ⁠יֹּ֣אמֶר אֲבִימֶ֗לֶךְ וּ⁠פִיכֹל֙ שַׂר־צְבָא֔⁠וֹ אֶל־אַבְרָהָ֖ם לֵ⁠אמֹ֑ר אֱלֹהִ֣ים עִמְּ⁠ךָ֔ בְּ⁠כֹ֥ל אֲשֶׁר־אַתָּ֖ה עֹשֶֽׂה׃","wֽa⁠yĕhiy֙ bá̇⁠ʻé֣ţ ha⁠hi֔wʼ wa⁠yò֣̇ʼmer ʼàbiyme֗lekĕ ẇ⁠piykòl֙ şâr-ẕĕbáʼ֔⁠wò ʼel-ʼabĕráhá֖m lé⁠ʼmò֑r ʼèlòhi֣ym ʻimĕ̇⁠ká֔ bĕ̇⁠kò֥l ʼàşěr-ʼaţá֖̇h ʻòşêֽh׃"],[21,23,"וְ⁠עַתָּ֗ה הִשָּׁ֨בְעָ⁠ה לִּ֤⁠י בֵֽ⁠אלֹהִים֙ הֵ֔נָּה אִם־תִּשְׁקֹ֣ר לִ֔⁠י וּ⁠לְ⁠נִינִ֖⁠י וּ⁠לְ⁠נֶכְדִּ֑⁠י כַּ⁠חֶ֜סֶד אֲשֶׁר־עָשִׂ֤יתִי עִמְּ⁠ךָ֙ תַּעֲשֶׂ֣ה עִמָּדִ֔⁠י וְ⁠עִם־הָ⁠אָ֖רֶץ אֲשֶׁר־גַּ֥רְתָּה בָּֽ⁠הּ׃","wĕ⁠ʻaţá̇֗h hişá̇̌֨bĕʻá⁠h li֤̇⁠y béֽ⁠ʼlòhiym֙ hé֔ná̇h ʼim-ţi̇şĕ̌qò֣r li֔⁠y ẇ⁠lĕ⁠niyni֖⁠y ẇ⁠lĕ⁠nekĕdi֑̇⁠y kȧ⁠ẖe֜sed ʼàşěr-ʻáşî֤yţiy ʻimĕ̇⁠ká֙ ţȧʻàşê֣h ʻimá̇di֔⁠y wĕ⁠ʻim-há⁠ʼá֖reẕ ʼàşěr-gȧ֥rĕţá̇h báֽ̇⁠ḣ׃"],[21,24,"וַ⁠יֹּ֨אמֶר֙ אַבְרָהָ֔ם אָנֹכִ֖י אִשָּׁבֵֽעַ׃","wa⁠yò̇֨ʼmer֙ ʼabĕráhá֔m ʼánòki֖y ʼişá̇̌béֽʻa׃"],[21,25,"וְ⁠הוֹכִ֥חַ אַבְרָהָ֖ם אֶת־אֲבִימֶ֑לֶךְ עַל־אֹדוֹת֙ בְּאֵ֣ר הַ⁠מַּ֔יִם אֲשֶׁ֥ר גָּזְל֖וּ עַבְדֵ֥י אֲבִימֶֽלֶךְ׃","wĕ⁠hwòki֥ẖa ʼabĕráhá֖m ʼeţ-ʼàbiyme֑lekĕ ʻal-ʼòdwòţ֙ bĕ̇ʼé֣r ha⁠mȧ֔yim ʼàşě֥r gá̇zĕl֖ẇ ʻabĕdé֥y ʼàbiymeֽlekĕ׃"],[21,26,"וַ⁠יֹּ֣אמֶר אֲבִימֶ֔לֶךְ לֹ֣א יָדַ֔עְתִּי מִ֥י עָשָׂ֖ה אֶת־הַ⁠דָּבָ֣ר הַ⁠זֶּ֑ה וְ⁠גַם־אַתָּ֞ה לֹא־הִגַּ֣דְתָּ לִּ֗⁠י וְ⁠גַ֧ם אָנֹכִ֛י לֹ֥א שָׁמַ֖עְתִּי בִּלְתִּ֥י הַ⁠יּֽוֹם׃","wa⁠yò֣̇ʼmer ʼàbiyme֔lekĕ lò֣ʼ yáda֔ʻĕţi̇y mi֥y ʻáşá֖̂h ʼeţ-ha⁠dá̇bá֣r ha⁠zė֑h wĕ⁠gam-ʼaţá̇֞h lòʼ-higȧ֣dĕţá̇ li̇֗⁠y wĕ⁠ga֧m ʼánòki֛y lò֥ʼ şá̌ma֖ʻĕţi̇y bi̇lĕţi֥̇y ha⁠ẏֽwòm׃"],[21,27,"וַ⁠יִּקַּ֤ח אַבְרָהָם֙ צֹ֣אן וּ⁠בָקָ֔ר וַ⁠יִּתֵּ֖ן לַ⁠אֲבִימֶ֑לֶךְ וַ⁠יִּכְרְת֥וּ שְׁנֵי⁠הֶ֖ם בְּרִֽית׃","wa⁠yi̇qȧ֤ẖ ʼabĕráhám֙ ẕò֣ʼn ẇ⁠báqá֔r wa⁠yi̇ţé֖̇n la⁠ʼàbiyme֑lekĕ wa⁠yi̇kĕrĕţ֥ẇ şĕ̌néy⁠he֖m bĕ̇riֽyţ׃"],[21,28,"וַ⁠יַּצֵּ֣ב אַבְרָהָ֗ם אֶת־שֶׁ֛בַע כִּבְשֹׂ֥ת הַ⁠צֹּ֖אן לְ⁠בַדְּ⁠הֶֽן׃","wa⁠yȧẕé֣̇b ʼabĕráhá֗m ʼeţ-şě֛baʻ ki̇bĕşò֥̂ţ ha⁠ẕò֖̇ʼn lĕ⁠badĕ̇⁠heֽn׃"],[21,29,"וַ⁠יֹּ֥אמֶר אֲבִימֶ֖לֶךְ אֶל־אַבְרָהָ֑ם מָ֣ה הֵ֗נָּה שֶׁ֤בַע כְּבָשֹׂת֙ הָ⁠אֵ֔לֶּה אֲשֶׁ֥ר הִצַּ֖בְתָּ לְ⁠בַדָּֽ⁠נָה׃","wa⁠yò֥̇ʼmer ʼàbiyme֖lekĕ ʼel-ʼabĕráhá֑m má֣h hé֗ná̇h şě֤baʻ kĕ̇báşò̂ţ֙ há⁠ʼé֔lėh ʼàşě֥r hiẕȧ֖bĕţá̇ lĕ⁠badáֽ̇⁠náh׃"],[21,30,"וַ⁠יֹּ֕אמֶר כִּ֚י אֶת־שֶׁ֣בַע כְּבָשֹׂ֔ת תִּקַּ֖ח מִ⁠יָּדִ֑⁠י בַּ⁠עֲבוּר֙ תִּֽהְיֶה־לִּ֣⁠י לְ⁠עֵדָ֔ה כִּ֥י חָפַ֖רְתִּי אֶת־הַ⁠בְּאֵ֥ר הַ⁠זֹּֽאת׃","wa⁠yò̇֕ʼmer ki֚̇y ʼeţ-şě֣baʻ kĕ̇báşò̂֔ţ ţi̇qȧ֖ẖ mi⁠yá̇di֑⁠y bȧ⁠ʻàbẇr֙ ţiֽ̇hĕyeh-li֣̇⁠y lĕ⁠ʻédá֔h ki֥̇y ẖápa֖rĕţi̇y ʼeţ-ha⁠bĕ̇ʼé֥r ha⁠zòֽ̇ʼţ׃"],[21,31,"עַל־כֵּ֗ן קָרָ֛א לַ⁠מָּק֥וֹם הַ⁠ה֖וּא בְּאֵ֣ר שָׁ֑בַע כִּ֛י שָׁ֥ם נִשְׁבְּע֖וּ שְׁנֵי⁠הֶֽם׃","ʻal-ké̇֗n qárá֛ʼ la⁠má̇q֥wòm ha⁠h֖ẇʼ bĕ̇ʼé֣r şá֑̌baʻ ki֛̇y şá֥̌m nişĕ̌bĕ̇ʻ֖ẇ şĕ̌néy⁠heֽm׃"],[21,32,"וַ⁠יִּכְרְת֥וּ בְרִ֖ית בִּ⁠בְאֵ֣ר שָׁ֑בַע וַ⁠יָּ֣קָם אֲבִימֶ֗לֶךְ וּ⁠פִיכֹל֙ שַׂר־צְבָא֔⁠וֹ וַ⁠יָּשֻׁ֖בוּ אֶל־אֶ֥רֶץ פְּלִשְׁתִּֽים׃","wa⁠yi̇kĕrĕţ֥ẇ bĕri֖yţ bi̇⁠bĕʼé֣r şá֑̌baʻ wa⁠yá֣̇qám ʼàbiyme֗lekĕ ẇ⁠piykòl֙ şâr-ẕĕbáʼ֔⁠wò wa⁠yá̇şǔ֖bẇ ʼel-ʼe֥reẕ pĕ̇lişĕ̌ţiֽ̇ym׃"],[21,33,"וַ⁠יִּטַּ֥ע אֶ֖שֶׁל בִּ⁠בְאֵ֣ר שָׁ֑בַע וַ⁠יִּ֨קְרָא־שָׁ֔ם בְּ⁠שֵׁ֥ם יְהוָ֖ה אֵ֥ל עוֹלָֽם׃","wa⁠yi̇tȧ֥ʻ ʼe֖şěl bi̇⁠bĕʼé֣r şá֑̌baʻ wa⁠yi̇֨qĕráʼ-şá̌֔m bĕ̇⁠şé֥̌m yĕhwá֖h ʼé֥l ʻwòláֽm׃"],[21,34,"וַ⁠יָּ֧גָר אַבְרָהָ֛ם בְּ⁠אֶ֥רֶץ פְּלִשְׁתִּ֖ים יָמִ֥ים רַבִּֽים׃פ","wa⁠yá֧̇gár ʼabĕráhá֛m bĕ̇⁠ʼe֥reẕ pĕ̇lişĕ̌ţi֖̇ym yámi֥ym rabiֽ̇ym׃p"],[22,1,"וַ⁠יְהִ֗י אַחַר֙ הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה וְ⁠הָ֣⁠אֱלֹהִ֔ים נִסָּ֖ה אֶת־אַבְרָהָ֑ם וַ⁠יֹּ֣אמֶר אֵלָ֔י⁠ו אַבְרָהָ֖ם וַ⁠יֹּ֥אמֶר הִנֵּֽנִ⁠י׃","wa⁠yĕhi֗y ʼaẖar֙ ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh wĕ⁠há֣⁠ʼèlòhi֔ym nisá֖̇h ʼeţ-ʼabĕráhá֑m wa⁠yò֣̇ʼmer ʼélá֔y⁠w ʼabĕráhá֖m wa⁠yò֥̇ʼmer hinéֽ̇ni⁠y׃"],[22,2,"וַ⁠יֹּ֡אמֶר קַח־נָ֠א אֶת־בִּנְ⁠ךָ֨ אֶת־יְחִֽידְ⁠ךָ֤ אֲשֶׁר־אָהַ֨בְתָּ֙ אֶת־יִצְחָ֔ק וְ⁠לֶךְ־לְ⁠ךָ֔ אֶל־אֶ֖רֶץ הַ⁠מֹּרִיָּ֑ה וְ⁠הַעֲלֵ֤⁠הוּ שָׁם֙ לְ⁠עֹלָ֔ה עַ֚ל אַחַ֣ד הֶֽ⁠הָרִ֔ים אֲשֶׁ֖ר אֹמַ֥ר אֵלֶֽי⁠ךָ׃","wa⁠yò̇֡ʼmer qaẖ-ná֠ʼ ʼeţ-bi̇nĕ⁠ká֨ ʼeţ-yĕẖiֽydĕ⁠ká֤ ʼàşěr-ʼáha֨bĕţá̇֙ ʼeţ-yiẕĕẖá֔q wĕ⁠lekĕ-lĕ⁠ká֔ ʼel-ʼe֖reẕ ha⁠mò̇riyá֑̇h wĕ⁠haʻàlé֤⁠hẇ şá̌m֙ lĕ⁠ʻòlá֔h ʻa֚l ʼaẖa֣d heֽ⁠hári֔ym ʼàşě֖r ʼòma֥r ʼéleֽy⁠ká׃"],[22,3,"וַ⁠יַּשְׁכֵּ֨ם אַבְרָהָ֜ם בַּ⁠בֹּ֗קֶר וַֽ⁠יַּחֲבֹשׁ֙ אֶת־חֲמֹר֔⁠וֹ וַ⁠יִּקַּ֞ח אֶת־שְׁנֵ֤י נְעָרָי⁠ו֙ אִתּ֔⁠וֹ וְ⁠אֵ֖ת יִצְחָ֣ק בְּנ֑⁠וֹ וַ⁠יְבַקַּע֙ עֲצֵ֣י עֹלָ֔ה וַ⁠יָּ֣קָם וַ⁠יֵּ֔לֶךְ אֶל־הַ⁠מָּק֖וֹם אֲשֶׁר־אָֽמַר־ל֥⁠וֹ הָ⁠אֱלֹהִֽים׃","wa⁠yȧşĕ̌ké̇֨m ʼabĕráhá֜m bȧ⁠bò̇֗qer waֽ⁠yȧẖàbòş̌֙ ʼeţ-ẖàmòr֔⁠wò wa⁠yi̇qȧ֞ẖ ʼeţ-şĕ̌né֤y nĕʻáráy⁠w֙ ʼiţ̇֔⁠wò wĕ⁠ʼé֖ţ yiẕĕẖá֣q bĕ̇n֑⁠wò wa⁠yĕbaqȧʻ֙ ʻàẕé֣y ʻòlá֔h wa⁠yá֣̇qám wa⁠yé̇֔lekĕ ʼel-ha⁠má̇q֖wòm ʼàşěr-ʼáֽmar-l֥⁠wò há⁠ʼèlòhiֽym׃"],[22,4,"בַּ⁠יּ֣וֹם הַ⁠שְּׁלִישִׁ֗י וַ⁠יִּשָּׂ֨א אַבְרָהָ֧ם אֶת־עֵינָ֛י⁠ו וַ⁠יַּ֥רְא אֶת־הַ⁠מָּק֖וֹם מֵ⁠רָחֹֽק׃","bȧ⁠ẏ֣wòm ha⁠şĕ̇̌liyşǐ֗y wa⁠yi̇şá̇̂֨ʼ ʼabĕráhá֧m ʼeţ-ʻéyná֛y⁠w wa⁠yȧ֥rĕʼ ʼeţ-ha⁠má̇q֖wòm mé⁠ráẖòֽq׃"],[22,5,"וַ⁠יֹּ֨אמֶר אַבְרָהָ֜ם אֶל־נְעָרָ֗י⁠ו שְׁבוּ־לָ⁠כֶ֥ם פֹּה֙ עִֽם־הַ⁠חֲמ֔וֹר וַ⁠אֲנִ֣י וְ⁠הַ⁠נַּ֔עַר נֵלְכָ֖ה עַד־כֹּ֑ה וְ⁠נִֽשְׁתַּחֲוֶ֖ה וְ⁠נָשׁ֥וּבָה אֲלֵי⁠כֶֽם׃","wa⁠yò̇֨ʼmer ʼabĕráhá֜m ʼel-nĕʻárá֗y⁠w şĕ̌bẇ-lá⁠ke֥m pò̇h֙ ʻiֽm-ha⁠ẖàm֔wòr wa⁠ʼàni֣y wĕ⁠ha⁠nȧ֔ʻar nélĕká֖h ʻad-kò֑̇h wĕ⁠niֽşĕ̌ţȧẖàwe֖h wĕ⁠náş֥̌ẇbáh ʼàléy⁠keֽm׃"],[22,6,"וַ⁠יִּקַּ֨ח אַבְרָהָ֜ם אֶת־עֲצֵ֣י הָ⁠עֹלָ֗ה וַ⁠יָּ֨שֶׂם֙ עַל־יִצְחָ֣ק בְּנ֔⁠וֹ וַ⁠יִּקַּ֣ח בְּ⁠יָד֔⁠וֹ אֶת־הָ⁠אֵ֖שׁ וְ⁠אֶת־הַֽ⁠מַּאֲכֶ֑לֶת וַ⁠יֵּלְכ֥וּ שְׁנֵי⁠הֶ֖ם יַחְדָּֽו׃","wa⁠yi̇qȧ֨ẖ ʼabĕráhá֜m ʼeţ-ʻàẕé֣y há⁠ʻòlá֗h wa⁠yá̇֨şêm֙ ʻal-yiẕĕẖá֣q bĕ̇n֔⁠wò wa⁠yi̇qȧ֣ẖ bĕ̇⁠yád֔⁠wò ʼeţ-há⁠ʼé֖ş̌ wĕ⁠ʼeţ-haֽ⁠mȧʼàke֑leţ wa⁠yé̇lĕk֥ẇ şĕ̌néy⁠he֖m yaẖĕdáֽ̇w׃"],[22,7,"וַ⁠יֹּ֨אמֶר יִצְחָ֜ק אֶל־אַבְרָהָ֤ם אָבִי⁠ו֙ וַ⁠יֹּ֣אמֶר אָבִ֔⁠י וַ⁠יֹּ֖אמֶר הִנֶּ֣נִּֽ⁠י בְנִ֑⁠י וַ⁠יֹּ֗אמֶר הִנֵּ֤ה הָ⁠אֵשׁ֙ וְ⁠הָ֣⁠עֵצִ֔ים וְ⁠אַיֵּ֥ה הַ⁠שֶּׂ֖ה לְ⁠עֹלָֽה׃","wa⁠yò̇֨ʼmer yiẕĕẖá֜q ʼel-ʼabĕráhá֤m ʼábiy⁠w֙ wa⁠yò֣̇ʼmer ʼábi֔⁠y wa⁠yò֖̇ʼmer hinė֣niֽ̇⁠y bĕni֑⁠y wa⁠yò̇֗ʼmer hiné֤̇h há⁠ʼéş̌֙ wĕ⁠há֣⁠ʻéẕi֔ym wĕ⁠ʼayé֥̇h ha⁠şė֖̂h lĕ⁠ʻòláֽh׃"],[22,8,"וַ⁠יֹּ֨אמֶר֙ אַבְרָהָ֔ם אֱלֹהִ֞ים יִרְאֶה־לּ֥⁠וֹ הַ⁠שֶּׂ֛ה לְ⁠עֹלָ֖ה בְּנִ֑⁠י וַ⁠יֵּלְכ֥וּ שְׁנֵי⁠הֶ֖ם יַחְדָּֽו׃","wa⁠yò̇֨ʼmer֙ ʼabĕráhá֔m ʼèlòhi֞ym yirĕʼeh-l֥̇⁠wò ha⁠şė֛̂h lĕ⁠ʻòlá֖h bĕ̇ni֑⁠y wa⁠yé̇lĕk֥ẇ şĕ̌néy⁠he֖m yaẖĕdáֽ̇w׃"],[22,9,"וַ⁠יָּבֹ֗אוּ אֶֽל־הַ⁠מָּקוֹם֮ אֲשֶׁ֣ר אָֽמַר־ל֣⁠וֹ הָ⁠אֱלֹהִים֒ וַ⁠יִּ֨בֶן שָׁ֤ם אַבְרָהָם֙ אֶת־הַ⁠מִּזְבֵּ֔חַ וַֽ⁠יַּעֲרֹ֖ךְ אֶת־הָ⁠עֵצִ֑ים וַֽ⁠יַּעֲקֹד֙ אֶת־יִצְחָ֣ק בְּנ֔⁠וֹ וַ⁠יָּ֤שֶׂם אֹת⁠וֹ֙ עַל־הַ⁠מִּזְבֵּ֔חַ מִ⁠מַּ֖עַל לָ⁠עֵצִֽים׃","wa⁠yá̇bò֗ʼẇ ʼeֽl-ha⁠má̇qwòm֮ ʼàşě֣r ʼáֽmar-l֣⁠wò há⁠ʼèlòhiym֒ wa⁠yi̇֨ben şá֤̌m ʼabĕráhám֙ ʼeţ-ha⁠mi̇zĕbé̇֔ẖa waֽ⁠yȧʻàrò֖kĕ ʼeţ-há⁠ʻéẕi֑ym waֽ⁠yȧʻàqòd֙ ʼeţ-yiẕĕẖá֣q bĕ̇n֔⁠wò wa⁠yá֤̇şêm ʼòţ⁠wò֙ ʻal-ha⁠mi̇zĕbé̇֔ẖa mi⁠mȧ֖ʻal lá⁠ʻéẕiֽym׃"],[22,10,"וַ⁠יִּשְׁלַ֤ח אַבְרָהָם֙ אֶת־יָד֔⁠וֹ וַ⁠יִּקַּ֖ח אֶת־הַֽ⁠מַּאֲכֶ֑לֶת לִ⁠שְׁחֹ֖ט אֶת־בְּנֽ⁠וֹ׃","wa⁠yi̇şĕ̌la֤ẖ ʼabĕráhám֙ ʼeţ-yád֔⁠wò wa⁠yi̇qȧ֖ẖ ʼeţ-haֽ⁠mȧʼàke֑leţ li⁠şĕ̌ẖò֖t ʼeţ-bĕ̇nֽ⁠wò׃"],[22,11,"וַ⁠יִּקְרָ֨א אֵלָ֜י⁠ו מַלְאַ֤ךְ יְהוָה֙ מִן־הַ⁠שָּׁמַ֔יִם וַ⁠יֹּ֖אמֶר אַבְרָהָ֣ם ׀ אַבְרָהָ֑ם וַ⁠יֹּ֖אמֶר הִנֵּֽנִ⁠י׃","wa⁠yi̇qĕrá֨ʼ ʼélá֜y⁠w malĕʼa֤kĕ yĕhwáh֙ min-ha⁠şá̇̌ma֔yim wa⁠yò֖̇ʼmer ʼabĕráhá֣m ׀ ʼabĕráhá֑m wa⁠yò֖̇ʼmer hinéֽ̇ni⁠y׃"],[22,12,"וַ⁠יֹּ֗אמֶר אַל־תִּשְׁלַ֤ח יָֽדְ⁠ךָ֙ אֶל־הַ⁠נַּ֔עַר וְ⁠אַל־תַּ֥עַשׂ ל֖⁠וֹ מְא֑וּמָּה כִּ֣י ׀ עַתָּ֣ה יָדַ֗עְתִּי כִּֽי־יְרֵ֤א אֱלֹהִים֙ אַ֔תָּה וְ⁠לֹ֥א חָשַׂ֛כְתָּ אֶת־בִּנְ⁠ךָ֥ אֶת־יְחִידְ⁠ךָ֖ מִמֶּֽ⁠נִּי׃","wa⁠yò̇֗ʼmer ʼal-ţi̇şĕ̌la֤ẖ yáֽdĕ⁠ká֙ ʼel-ha⁠nȧ֔ʻar wĕ⁠ʼal-ţȧ֥ʻaş̂ l֖⁠wò mĕʼ֑ẇmá̇h ki֣̇y ׀ ʻaţá֣̇h yáda֗ʻĕţi̇y kiֽ̇y-yĕré֤ʼ ʼèlòhiym֙ ʼa֔ţá̇h wĕ⁠lò֥ʼ ẖáşâ֛kĕţá̇ ʼeţ-bi̇nĕ⁠ká֥ ʼeţ-yĕẖiydĕ⁠ká֖ mimėֽ⁠ni̇y׃"],[22,13,"וַ⁠יִּשָּׂ֨א אַבְרָהָ֜ם אֶת־עֵינָ֗י⁠ו וַ⁠יַּרְא֙ וְ⁠הִנֵּה־אַ֔יִל אַחַ֕ר נֶאֱחַ֥ז בַּ⁠סְּבַ֖ךְ בְּ⁠קַרְנָ֑י⁠ו וַ⁠יֵּ֤לֶךְ אַבְרָהָם֙ וַ⁠יִּקַּ֣ח אֶת־הָ⁠אַ֔יִל וַ⁠יַּעֲלֵ֥⁠הוּ לְ⁠עֹלָ֖ה תַּ֥חַת בְּנֽ⁠וֹ׃","wa⁠yi̇şá̇̂֨ʼ ʼabĕráhá֜m ʼeţ-ʻéyná֗y⁠w wa⁠yȧrĕʼ֙ wĕ⁠hiné̇h-ʼa֔yil ʼaẖa֕r neʼèẖa֥z bȧ⁠sĕ̇ba֖kĕ bĕ̇⁠qarĕná֑y⁠w wa⁠yé֤̇lekĕ ʼabĕráhám֙ wa⁠yi̇qȧ֣ẖ ʼeţ-há⁠ʼa֔yil wa⁠yȧʻàlé֥⁠hẇ lĕ⁠ʻòlá֖h ţȧ֥ẖaţ bĕ̇nֽ⁠wò׃"],[22,14,"וַ⁠יִּקְרָ֧א אַבְרָהָ֛ם שֵֽׁם־הַ⁠מָּק֥וֹם הַ⁠ה֖וּא יְהוָ֣ה ׀ יִרְאֶ֑ה אֲשֶׁר֙ יֵאָמֵ֣ר הַ⁠יּ֔וֹם בְּ⁠הַ֥ר יְהוָ֖ה יֵרָאֶֽה׃","wa⁠yi̇qĕrá֧ʼ ʼabĕráhá֛m şéֽ̌m-ha⁠má̇q֥wòm ha⁠h֖ẇʼ yĕhwá֣h ׀ yirĕʼe֑h ʼàşěr֙ yéʼámé֣r ha⁠ẏ֔wòm bĕ̇⁠ha֥r yĕhwá֖h yéráʼeֽh׃"],[22,15,"וַ⁠יִּקְרָ֛א מַלְאַ֥ךְ יְהוָ֖ה אֶל־אַבְרָהָ֑ם שֵׁנִ֖ית מִן־הַ⁠שָּׁמָֽיִם׃","wa⁠yi̇qĕrá֛ʼ malĕʼa֥kĕ yĕhwá֖h ʼel-ʼabĕráhá֑m şé̌ni֖yţ min-ha⁠şá̇̌máֽyim׃"],[22,16,"וַ⁠יֹּ֕אמֶר בִּ֥⁠י נִשְׁבַּ֖עְתִּי נְאֻם־יְהוָ֑ה כִּ֗י יַ֚עַן אֲשֶׁ֤ר עָשִׂ֨יתָ֙ אֶת־הַ⁠דָּבָ֣ר הַ⁠זֶּ֔ה וְ⁠לֹ֥א חָשַׂ֖כְתָּ אֶת־בִּנְ⁠ךָ֥ אֶת־יְחִידֶֽ⁠ךָ׃","wa⁠yò̇֕ʼmer bi֥̇⁠y nişĕ̌bȧ֖ʻĕţi̇y nĕʼum-yĕhwá֑h ki̇֗y ya֚ʻan ʼàşě֤r ʻáşî֨yţá֙ ʼeţ-ha⁠dá̇bá֣r ha⁠zė֔h wĕ⁠lò֥ʼ ẖáşâ֖kĕţá̇ ʼeţ-bi̇nĕ⁠ká֥ ʼeţ-yĕẖiydeֽ⁠ká׃"],[22,17,"כִּֽי־בָרֵ֣ךְ אֲבָרֶכְ⁠ךָ֗ וְ⁠הַרְבָּ֨ה אַרְבֶּ֤ה אֶֽת־זַרְעֲ⁠ךָ֙ כְּ⁠כוֹכְבֵ֣י הַ⁠שָּׁמַ֔יִם וְ⁠כַ⁠ח֕וֹל אֲשֶׁ֖ר עַל־שְׂפַ֣ת הַ⁠יָּ֑ם וְ⁠יִרַ֣שׁ זַרְעֲ⁠ךָ֔ אֵ֖ת שַׁ֥עַר אֹיְבָֽי⁠ו׃","kiֽ̇y-báré֣kĕ ʼàbárekĕ⁠ká֗ wĕ⁠harĕbá̇֨h ʼarĕbė֤h ʼeֽţ-zarĕʻà⁠ká֙ kĕ̇⁠kwòkĕbé֣y ha⁠şá̇̌ma֔yim wĕ⁠ka⁠ẖ֕wòl ʼàşě֖r ʻal-şĕ̂pa֣ţ ha⁠yá֑̇m wĕ⁠yira֣ş̌ zarĕʻà⁠ká֔ ʼé֖ţ şǎ֥ʻar ʼòyĕbáֽy⁠w׃"],[22,18,"וְ⁠הִתְבָּרֲכ֣וּ בְ⁠זַרְעֲ⁠ךָ֔ כֹּ֖ל גּוֹיֵ֣י הָ⁠אָ֑רֶץ עֵ֕קֶב אֲשֶׁ֥ר שָׁמַ֖עְתָּ בְּ⁠קֹלִֽ⁠י׃","wĕ⁠hiţĕbá̇ràk֣ẇ bĕ⁠zarĕʻà⁠ká֔ kò֖̇l ġwòyé֣y há⁠ʼá֑reẕ ʻé֕qeb ʼàşě֥r şá̌ma֖ʻĕţá̇ bĕ̇⁠qòliֽ⁠y׃"],[22,19,"וַ⁠יָּ֤שָׁב אַבְרָהָם֙ אֶל־נְעָרָ֔י⁠ו וַ⁠יָּקֻ֛מוּ וַ⁠יֵּלְכ֥וּ יַחְדָּ֖ו אֶל־בְּאֵ֣ר שָׁ֑בַע וַ⁠יֵּ֥שֶׁב אַבְרָהָ֖ם בִּ⁠בְאֵ֥ר שָֽׁבַע׃פ","wa⁠yá֤̇şá̌b ʼabĕráhám֙ ʼel-nĕʻárá֔y⁠w wa⁠yá̇qu֛mẇ wa⁠yé̇lĕk֥ẇ yaẖĕdá֖̇w ʼel-bĕ̇ʼé֣r şá֑̌baʻ wa⁠yé֥̇şěb ʼabĕráhá֖m bi̇⁠bĕʼé֥r şáֽ̌baʻ׃p"],[22,20,"וַ⁠יְהִ֗י אַחֲרֵי֙ הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה וַ⁠יֻּגַּ֥ד לְ⁠אַבְרָהָ֖ם לֵ⁠אמֹ֑ר הִ֠נֵּה יָלְדָ֨ה מִלְכָּ֥ה גַם־הִ֛וא בָּנִ֖ים לְ⁠נָח֥וֹר אָחִֽי⁠ךָ׃","wa⁠yĕhi֗y ʼaẖàréy֙ ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh wa⁠yu̇gȧ֥d lĕ⁠ʼabĕráhá֖m lé⁠ʼmò֑r hi֠né̇h yálĕdá֨h milĕká֥̇h gam-hi֛wʼ bá̇ni֖ym lĕ⁠náẖ֥wòr ʼáẖiֽy⁠ká׃"],[22,21,"אֶת־ע֥וּץ בְּכֹר֖⁠וֹ וְ⁠אֶת־בּ֣וּז אָחִ֑י⁠ו וְ⁠אֶת־קְמוּאֵ֖ל אֲבִ֥י אֲרָֽם׃","ʼeţ-ʻ֥ẇẕ bĕ̇kòr֖⁠wò wĕ⁠ʼeţ-ḃ֣ẇz ʼáẖi֑y⁠w wĕ⁠ʼeţ-qĕmẇʼé֖l ʼàbi֥y ʼàráֽm׃"],[22,22,"וְ⁠אֶת־כֶּ֣שֶׂד וְ⁠אֶת־חֲז֔וֹ וְ⁠אֶת־פִּלְדָּ֖שׁ וְ⁠אֶת־יִדְלָ֑ף וְ⁠אֵ֖ת בְּתוּאֵֽל׃","wĕ⁠ʼeţ-kė֣şêd wĕ⁠ʼeţ-ẖàz֔wò wĕ⁠ʼeţ-pi̇lĕdá֖̇ş̌ wĕ⁠ʼeţ-yidĕlá֑p wĕ⁠ʼé֖ţ bĕ̇ţẇʼéֽl׃"],[22,23,"וּ⁠בְתוּאֵ֖ל יָלַ֣ד אֶת־רִבְקָ֑ה שְׁמֹנָ֥ה אֵ֨לֶּה֙ יָלְדָ֣ה מִלְכָּ֔ה לְ⁠נָח֖וֹר אֲחִ֥י אַבְרָהָֽם׃","ẇ⁠bĕţẇʼé֖l yála֣d ʼeţ-ribĕqá֑h şĕ̌mòná֥h ʼé֨lėh֙ yálĕdá֣h milĕká̇֔h lĕ⁠náẖ֖wòr ʼàẖi֥y ʼabĕráháֽm׃"],[22,24,"וּ⁠פִֽילַגְשׁ֖⁠וֹ וּ⁠שְׁמָ֣⁠הּ רְאוּמָ֑ה וַ⁠תֵּ֤לֶד גַּם־הִוא֙ אֶת־טֶ֣בַח וְ⁠אֶת־גַּ֔חַם וְ⁠אֶת־תַּ֖חַשׁ וְ⁠אֶֽת־מַעֲכָֽה׃ס","ẇ⁠piֽylagĕş֖̌⁠wò ẇ⁠şĕ̌má֣⁠ḣ rĕʼẇmá֑h wa⁠ţé֤̇led gȧm-hiwʼ֙ ʼeţ-te֣baẖ wĕ⁠ʼeţ-gȧ֔ẖam wĕ⁠ʼeţ-ţȧ֖ẖaş̌ wĕ⁠ʼeֽţ-maʻàkáֽh׃s"],[23,1,"וַ⁠יִּהְיוּ֙ חַיֵּ֣י שָׂרָ֔ה מֵאָ֥ה שָׁנָ֛ה וְ⁠עֶשְׂרִ֥ים שָׁנָ֖ה וְ⁠שֶׁ֣בַע שָׁנִ֑ים שְׁנֵ֖י חַיֵּ֥י שָׂרָֽה׃","wa⁠yi̇hĕyẇ֙ ẖayé֣̇y şá̂rá֔h méʼá֥h şá̌ná֛h wĕ⁠ʻeşĕ̂ri֥ym şá̌ná֖h wĕ⁠şě֣baʻ şá̌ni֑ym şĕ̌né֖y ẖayé֥̇y şá̂ráֽh׃"],[23,2,"וַ⁠תָּ֣מָת שָׂרָ֗ה בְּ⁠קִרְיַ֥ת אַרְבַּ֛ע הִ֥וא חֶבְר֖וֹן בְּ⁠אֶ֣רֶץ כְּנָ֑עַן וַ⁠יָּבֹא֙ אַבְרָהָ֔ם לִ⁠סְפֹּ֥ד לְ⁠שָׂרָ֖ה וְ⁠לִ⁠בְכֹּתָֽ⁠הּ׃","wa⁠ţá֣̇máţ şá̂rá֗h bĕ̇⁠qirĕya֥ţ ʼarĕbȧ֛ʻ hi֥wʼ ẖebĕr֖wòn bĕ̇⁠ʼe֣reẕ kĕ̇ná֑ʻan wa⁠yá̇bòʼ֙ ʼabĕráhá֔m li⁠sĕpò֥̇d lĕ⁠şá̂rá֖h wĕ⁠li⁠bĕkò̇ţáֽ⁠ḣ׃"],[23,3,"וַ⁠יָּ֨קָם֙ אַבְרָהָ֔ם מֵ⁠עַ֖ל פְּנֵ֣י מֵת֑⁠וֹ וַ⁠יְדַבֵּ֥ר אֶל־בְּנֵי־חֵ֖ת לֵ⁠אמֹֽר׃","wa⁠yá̇֨qám֙ ʼabĕráhá֔m mé⁠ʻa֖l pĕ̇né֣y méţ֑⁠wò wa⁠yĕdabé֥̇r ʼel-bĕ̇néy-ẖé֖ţ lé⁠ʼmòֽr׃"],[23,4,"גֵּר־וְ⁠תוֹשָׁ֥ב אָנֹכִ֖י עִמָּ⁠כֶ֑ם תְּנ֨וּ לִ֤⁠י אֲחֻזַּת־קֶ֨בֶר֙ עִמָּ⁠כֶ֔ם וְ⁠אֶקְבְּרָ֥ה מֵתִ֖⁠י מִ⁠לְּ⁠פָנָֽ⁠י׃","gé̇r-wĕ⁠ţwòşá֥̌b ʼánòki֖y ʻimá̇⁠ke֑m ţĕ̇n֨ẇ li֤⁠y ʼàẖuzȧţ-qe֨ber֙ ʻimá̇⁠ke֔m wĕ⁠ʼeqĕbĕ̇rá֥h méţi֖⁠y mi⁠lĕ̇⁠pánáֽ⁠y׃"],[23,5,"וַ⁠יַּעֲנ֧וּ בְנֵי־חֵ֛ת אֶת־אַבְרָהָ֖ם לֵ⁠אמֹ֥ר לֽ⁠וֹ׃","wa⁠yȧʻàn֧ẇ bĕnéy-ẖé֛ţ ʼeţ-ʼabĕráhá֖m lé⁠ʼmò֥r lֽ⁠wò׃"],[23,6,"שְׁמָעֵ֣⁠נוּ ׀ אֲדֹנִ֗⁠י נְשִׂ֨יא אֱלֹהִ֤ים אַתָּה֙ בְּ⁠תוֹכֵ֔⁠נוּ בְּ⁠מִבְחַ֣ר קְבָרֵ֔י⁠נוּ קְבֹ֖ר אֶת־מֵתֶ֑⁠ךָ אִ֣ישׁ מִמֶּ֔⁠נּוּ אֶת־קִבְר֛⁠וֹ לֹֽא־יִכְלֶ֥ה מִמְּ⁠ךָ֖ מִ⁠קְּבֹ֥ר מֵתֶֽ⁠ךָ׃","şĕ̌máʻé֣⁠nẇ ׀ ʼàdòni֗⁠y nĕşî֨yʼ ʼèlòhi֤ym ʼaţá̇h֙ bĕ̇⁠ţwòké֔⁠nẇ bĕ̇⁠mibĕẖa֣r qĕbáré֔y⁠nẇ qĕbò֖r ʼeţ-méţe֑⁠ká ʼi֣yş̌ mimė֔⁠ṅẇ ʼeţ-qibĕr֛⁠wò lòֽʼ-yikĕle֥h mimĕ̇⁠ká֖ mi⁠qĕ̇bò֥r méţeֽ⁠ká׃"],[23,7,"וַ⁠יָּ֧קָם אַבְרָהָ֛ם וַ⁠יִּשְׁתַּ֥חוּ לְ⁠עַם־הָ⁠אָ֖רֶץ לִ⁠בְנֵי־חֵֽת׃","wa⁠yá֧̇qám ʼabĕráhá֛m wa⁠yi̇şĕ̌ţȧ֥ẖẇ lĕ⁠ʻam-há⁠ʼá֖reẕ li⁠bĕnéy-ẖéֽţ׃"],[23,8,"וַ⁠יְדַבֵּ֥ר אִתָּ֖⁠ם לֵ⁠אמֹ֑ר אִם־יֵ֣שׁ אֶֽת־נַפְשְׁ⁠כֶ֗ם לִ⁠קְבֹּ֤ר אֶת־מֵתִ⁠י֙ מִ⁠לְּ⁠פָנַ֔⁠י שְׁמָע֕וּ⁠נִי וּ⁠פִגְעוּ־לִ֖⁠י בְּ⁠עֶפְר֥וֹן בֶּן־צֹֽחַר׃","wa⁠yĕdabé֥̇r ʼiţá֖̇⁠m lé⁠ʼmò֑r ʼim-yé֣ş̌ ʼeֽţ-napĕşĕ̌⁠ke֗m li⁠qĕbò֤̇r ʼeţ-méţi⁠y֙ mi⁠lĕ̇⁠pána֔⁠y şĕ̌máʻ֕ẇ⁠niy ẇ⁠pigĕʻẇ-li֖⁠y bĕ̇⁠ʻepĕr֥wòn bėn-ẕòֽẖar׃"],[23,9,"וְ⁠יִתֶּן־לִ֗⁠י אֶת־מְעָרַ֤ת הַ⁠מַּכְפֵּלָה֙ אֲשֶׁר־ל֔⁠וֹ אֲשֶׁ֖ר בִּ⁠קְצֵ֣ה שָׂדֵ֑⁠הוּ בְּ⁠כֶ֨סֶף מָלֵ֜א יִתְּנֶ֥⁠נָּה לִ֛⁠י בְּ⁠תוֹכְ⁠כֶ֖ם לַ⁠אֲחֻזַּת־קָֽבֶר׃","wĕ⁠yiţėn-li֗⁠y ʼeţ-mĕʻára֤ţ ha⁠mȧkĕpé̇láh֙ ʼàşěr-l֔⁠wò ʼàşě֖r bi̇⁠qĕẕé֣h şá̂dé֑⁠hẇ bĕ̇⁠ke֨sep málé֜ʼ yiţĕ̇ne֥⁠ná̇h li֛⁠y bĕ̇⁠ţwòkĕ⁠ke֖m la⁠ʼàẖuzȧţ-qáֽber׃"],[23,10,"וְ⁠עֶפְר֥וֹן יֹשֵׁ֖ב בְּ⁠ת֣וֹךְ בְּנֵי־חֵ֑ת וַ⁠יַּעַן֩ עֶפְר֨וֹן הַ⁠חִתִּ֤י אֶת־אַבְרָהָם֙ בְּ⁠אָזְנֵ֣י בְנֵי־חֵ֔ת לְ⁠כֹ֛ל בָּאֵ֥י שַֽׁעַר־עִיר֖⁠וֹ לֵ⁠אמֹֽר׃","wĕ⁠ʻepĕr֥wòn yòşé֖̌b bĕ̇⁠ţ֣wòkĕ bĕ̇néy-ẖé֑ţ wa⁠yȧʻan֩ ʻepĕr֨wòn ha⁠ẖiţi֤̇y ʼeţ-ʼabĕráhám֙ bĕ̇⁠ʼázĕné֣y bĕnéy-ẖé֔ţ lĕ⁠kò֛l bá̇ʼé֥y şǎֽʻar-ʻiyr֖⁠wò lé⁠ʼmòֽr׃"],[23,11,"לֹֽא־אֲדֹנִ֣⁠י שְׁמָעֵ֔⁠נִי הַ⁠שָּׂדֶה֙ נָתַ֣תִּי לָ֔⁠ךְ וְ⁠הַ⁠מְּעָרָ֥ה אֲשֶׁר־בּ֖⁠וֹ לְ⁠ךָ֣ נְתַתִּ֑י⁠הָ לְ⁠עֵינֵ֧י בְנֵי־עַמִּ֛⁠י נְתַתִּ֥י⁠הָ לָּ֖⁠ךְ קְבֹ֥ר מֵתֶֽ⁠ךָ׃","lòֽʼ-ʼàdòni֣⁠y şĕ̌máʻé֔⁠niy ha⁠şá̇̂deh֙ náţa֣ţi̇y lá֔⁠kĕ wĕ⁠ha⁠mĕ̇ʻárá֥h ʼàşěr-ḃ֖⁠wò lĕ⁠ká֣ nĕţaţi֑̇y⁠há lĕ⁠ʻéyné֧y bĕnéy-ʻami֛̇⁠y nĕţaţi֥̇y⁠há lá֖̇⁠kĕ qĕbò֥r méţeֽ⁠ká׃"],[23,12,"וַ⁠יִּשְׁתַּ֨חוּ֙ אַבְרָהָ֔ם לִ⁠פְנֵ֖י עַ֥ם הָ⁠אָֽרֶץ׃","wa⁠yi̇şĕ̌ţȧ֨ẖẇ֙ ʼabĕráhá֔m li⁠pĕné֖y ʻa֥m há⁠ʼáֽreẕ׃"],[23,13,"וַ⁠יְדַבֵּ֨ר אֶל־עֶפְר֜וֹן בְּ⁠אָזְנֵ֤י עַם־הָ⁠אָ֨רֶץ֙ לֵ⁠אמֹ֔ר אַ֛ךְ אִם־אַתָּ֥ה ל֖וּ שְׁמָעֵ֑⁠נִי נָתַ֜תִּי כֶּ֤סֶף הַ⁠שָּׂדֶה֙ קַ֣ח מִמֶּ֔⁠נִּי וְ⁠אֶקְבְּרָ֥ה אֶת־מֵתִ֖⁠י שָֽׁמָּ⁠ה׃","wa⁠yĕdabé̇֨r ʼel-ʻepĕr֜wòn bĕ̇⁠ʼázĕné֤y ʻam-há⁠ʼá֨reẕ֙ lé⁠ʼmò֔r ʼa֛kĕ ʼim-ʼaţá֥̇h l֖ẇ şĕ̌máʻé֑⁠niy náţa֜ţi̇y kė֤sep ha⁠şá̇̂deh֙ qa֣ẖ mimė֔⁠ni̇y wĕ⁠ʼeqĕbĕ̇rá֥h ʼeţ-méţi֖⁠y şáֽ̌má̇⁠h׃"],[23,14,"וַ⁠יַּ֧עַן עֶפְר֛וֹן אֶת־אַבְרָהָ֖ם לֵ⁠אמֹ֥ר לֽ⁠וֹ׃","wa⁠yȧ֧ʻan ʻepĕr֛wòn ʼeţ-ʼabĕráhá֖m lé⁠ʼmò֥r lֽ⁠wò׃"],[23,15,"אֲדֹנִ֣⁠י שְׁמָעֵ֔⁠נִי אֶרֶץ֩ אַרְבַּ֨ע מֵאֹ֧ת שֶֽׁקֶל־כֶּ֛סֶף בֵּינִ֥⁠י וּ⁠בֵֽינְ⁠ךָ֖ מַה־הִ֑וא וְ⁠אֶת־מֵתְ⁠ךָ֖ קְבֹֽר׃","ʼàdòni֣⁠y şĕ̌máʻé֔⁠niy ʼereẕ֩ ʼarĕbȧ֨ʻ méʼò֧ţ şěֽqel-kė֛sep bé̇yni֥⁠y ẇ⁠béֽynĕ⁠ká֖ mah-hi֑wʼ wĕ⁠ʼeţ-méţĕ⁠ká֖ qĕbòֽr׃"],[23,16,"וַ⁠יִּשְׁמַ֣ע אַבְרָהָם֮ אֶל־עֶפְרוֹן֒ וַ⁠יִּשְׁקֹ֤ל אַבְרָהָם֙ לְ⁠עֶפְרֹ֔ן אֶת־הַ⁠כֶּ֕סֶף אֲשֶׁ֥ר דִּבֶּ֖ר בְּ⁠אָזְנֵ֣י בְנֵי־חֵ֑ת אַרְבַּ֤ע מֵאוֹת֙ שֶׁ֣קֶל כֶּ֔סֶף עֹבֵ֖ר לַ⁠סֹּחֵֽר׃","wa⁠yi̇şĕ̌ma֣ʻ ʼabĕráhám֮ ʼel-ʻepĕrwòn֒ wa⁠yi̇şĕ̌qò֤l ʼabĕráhám֙ lĕ⁠ʻepĕrò֔n ʼeţ-ha⁠kė֕sep ʼàşě֥r di̇bė֖r bĕ̇⁠ʼázĕné֣y bĕnéy-ẖé֑ţ ʼarĕbȧ֤ʻ méʼwòţ֙ şě֣qel kė֔sep ʻòbé֖r la⁠sò̇ẖéֽr׃"],[23,17,"וַ⁠יָּ֣קָם ׀ שְׂדֵ֣ה עֶפְר֗וֹן אֲשֶׁר֙ בַּ⁠מַּכְפֵּלָ֔ה אֲשֶׁ֖ר לִ⁠פְנֵ֣י מַמְרֵ֑א הַ⁠שָּׂדֶה֙ וְ⁠הַ⁠מְּעָרָ֣ה אֲשֶׁר־בּ֔⁠וֹ וְ⁠כָל־הָ⁠עֵץ֙ אֲשֶׁ֣ר בַּ⁠שָּׂדֶ֔ה אֲשֶׁ֥ר בְּ⁠כָל־גְּבֻל֖⁠וֹ סָבִֽיב׃","wa⁠yá֣̇qám ׀ şĕ̂dé֣h ʻepĕr֗wòn ʼàşěr֙ bȧ⁠mȧkĕpé̇lá֔h ʼàşě֖r li⁠pĕné֣y mamĕré֑ʼ ha⁠şá̇̂deh֙ wĕ⁠ha⁠mĕ̇ʻárá֣h ʼàşěr-ḃ֔⁠wò wĕ⁠kál-há⁠ʻéẕ֙ ʼàşě֣r bȧ⁠şá̇̂de֔h ʼàşě֥r bĕ̇⁠kál-gĕ̇bul֖⁠wò sábiֽyb׃"],[23,18,"לְ⁠אַבְרָהָ֥ם לְ⁠מִקְנָ֖ה לְ⁠עֵינֵ֣י בְנֵי־חֵ֑ת בְּ⁠כֹ֖ל בָּאֵ֥י שַֽׁעַר־עִירֽ⁠וֹ׃","lĕ⁠ʼabĕráhá֥m lĕ⁠miqĕná֖h lĕ⁠ʻéyné֣y bĕnéy-ẖé֑ţ bĕ̇⁠kò֖l bá̇ʼé֥y şǎֽʻar-ʻiyrֽ⁠wò׃"],[23,19,"וְ⁠אַחֲרֵי־כֵן֩ קָבַ֨ר אַבְרָהָ֜ם אֶת־שָׂרָ֣ה אִשְׁתּ֗⁠וֹ אֶל־מְעָרַ֞ת שְׂדֵ֧ה הַ⁠מַּכְפֵּלָ֛ה עַל־פְּנֵ֥י מַמְרֵ֖א הִ֣וא חֶבְר֑וֹן בְּ⁠אֶ֖רֶץ כְּנָֽעַן׃","wĕ⁠ʼaẖàréy-kén֩ qába֨r ʼabĕráhá֜m ʼeţ-şá̂rá֣h ʼişĕ̌ţ̇֗⁠wò ʼel-mĕʻára֞ţ şĕ̂dé֧h ha⁠mȧkĕpé̇lá֛h ʻal-pĕ̇né֥y mamĕré֖ʼ hi֣wʼ ẖebĕr֑wòn bĕ̇⁠ʼe֖reẕ kĕ̇náֽʻan׃"],[23,20,"וַ⁠יָּ֨קָם הַ⁠שָּׂדֶ֜ה וְ⁠הַ⁠מְּעָרָ֧ה אֲשֶׁר־בּ֛⁠וֹ לְ⁠אַבְרָהָ֖ם לַ⁠אֲחֻזַּת־קָ֑בֶר מֵ⁠אֵ֖ת בְּנֵי־חֵֽת׃ס","wa⁠yá̇֨qám ha⁠şá̇̂de֜h wĕ⁠ha⁠mĕ̇ʻárá֧h ʼàşěr-ḃ֛⁠wò lĕ⁠ʼabĕráhá֖m la⁠ʼàẖuzȧţ-qá֑ber mé⁠ʼé֖ţ bĕ̇néy-ẖéֽţ׃s"],[24,1,"וְ⁠אַבְרָהָ֣ם זָקֵ֔ן בָּ֖א בַּ⁠יָּמִ֑ים וַֽ⁠יהוָ֛ה בֵּרַ֥ךְ אֶת־אַבְרָהָ֖ם בַּ⁠כֹּֽל׃","wĕ⁠ʼabĕráhá֣m záqé֔n bá֖̇ʼ bȧ⁠yá̇mi֑ym wֽa⁠yhwá֛h bé̇ra֥kĕ ʼeţ-ʼabĕráhá֖m bȧ⁠kòֽ̇l׃"],[24,2,"וַ⁠יֹּ֣אמֶר אַבְרָהָ֗ם אֶל־עַבְדּ⁠וֹ֙ זְקַ֣ן בֵּית֔⁠וֹ הַ⁠מֹּשֵׁ֖ל בְּ⁠כָל־אֲשֶׁר־ל֑⁠וֹ שִֽׂים־נָ֥א יָדְ⁠ךָ֖ תַּ֥חַת יְרֵכִֽ⁠י׃","wa⁠yò֣̇ʼmer ʼabĕráhá֗m ʼel-ʻabĕḋ⁠wò֙ zĕqa֣n bé̇yţ֔⁠wò ha⁠mò̇şé֖̌l bĕ̇⁠kál-ʼàşěr-l֑⁠wò şîֽym-ná֥ʼ yádĕ⁠ká֖ ţȧ֥ẖaţ yĕrékiֽ⁠y׃"],[24,3,"וְ⁠אַשְׁבִּ֣יעֲ⁠ךָ֔ בַּֽ⁠יהוָה֙ אֱלֹהֵ֣י הַ⁠שָּׁמַ֔יִם וֵֽ⁠אלֹהֵ֖י הָ⁠אָ֑רֶץ אֲשֶׁ֨ר לֹֽא־תִקַּ֤ח אִשָּׁה֙ לִ⁠בְנִ֔⁠י מִ⁠בְּנוֹת֙ הַֽ⁠כְּנַעֲנִ֔י אֲשֶׁ֥ר אָנֹכִ֖י יוֹשֵׁ֥ב בְּ⁠קִרְבּֽ⁠וֹ׃","wĕ⁠ʼaşĕ̌bi֣̇yʻà⁠ká֔ ḃֽa⁠yhwáh֙ ʼèlòhé֣y ha⁠şá̇̌ma֔yim wֽé⁠ʼlòhé֖y há⁠ʼá֑reẕ ʼàşě֨r lòֽʼ-ţiqȧ֤ẖ ʼişá̇̌h֙ li⁠bĕni֔⁠y mi⁠bĕ̇nwòţ֙ haֽ⁠kĕ̇naʻàni֔y ʼàşě֥r ʼánòki֖y ywòşé֥̌b bĕ̇⁠qirĕḃֽ⁠wò׃"],[24,4,"כִּ֧י אֶל־אַרְצִ֛⁠י וְ⁠אֶל־מוֹלַדְתִּ֖⁠י תֵּלֵ֑ךְ וְ⁠לָקַחְתָּ֥ אִשָּׁ֖ה לִ⁠בְנִ֥⁠י לְ⁠יִצְחָֽק׃","ki֧̇y ʼel-ʼarĕẕi֛⁠y wĕ⁠ʼel-mwòladĕţi֖̇⁠y ţé̇lé֑kĕ wĕ⁠láqaẖĕţá֥̇ ʼişá֖̇̌h li⁠bĕni֥⁠y lĕ⁠yiẕĕẖáֽq׃"],[24,5,"וַ⁠יֹּ֤אמֶר אֵלָי⁠ו֙ הָ⁠עֶ֔בֶד אוּלַי֙ לֹא־תֹאבֶ֣ה הָֽ⁠אִשָּׁ֔ה לָ⁠לֶ֥כֶת אַחֲרַ֖⁠י אֶל־הָ⁠אָ֣רֶץ הַ⁠זֹּ֑את הֶֽ⁠הָשֵׁ֤ב אָשִׁיב֙ אֶת־בִּנְ⁠ךָ֔ אֶל־הָ⁠אָ֖רֶץ אֲשֶׁר־יָצָ֥אתָ מִ⁠שָּֽׁם׃","wa⁠yò֤̇ʼmer ʼéláy⁠w֙ há⁠ʻe֔bed ʼẇlay֙ lòʼ-ţòʼbe֣h háֽ⁠ʼişá̇̌֔h lá⁠le֥keţ ʼaẖàra֖⁠y ʼel-há⁠ʼá֣reẕ ha⁠zò֑̇ʼţ heֽ⁠háşé֤̌b ʼáşǐyb֙ ʼeţ-bi̇nĕ⁠ká֔ ʼel-há⁠ʼá֖reẕ ʼàşěr-yáẕá֥ʼţá mi⁠şáֽ̇̌m׃"],[24,6,"וַ⁠יֹּ֥אמֶר אֵלָ֖י⁠ו אַבְרָהָ֑ם הִשָּׁ֣מֶר לְ⁠ךָ֔ פֶּן־תָּשִׁ֥יב אֶת־בְּנִ֖⁠י שָֽׁמָּ⁠ה׃","wa⁠yò֥̇ʼmer ʼélá֖y⁠w ʼabĕráhá֑m hişá֣̇̌mer lĕ⁠ká֔ pėn-ţá̇şǐ֥yb ʼeţ-bĕ̇ni֖⁠y şáֽ̌má̇⁠h׃"],[24,7,"יְהוָ֣ה ׀ אֱלֹהֵ֣י הַ⁠שָּׁמַ֗יִם אֲשֶׁ֨ר לְקָחַ֜⁠נִי מִ⁠בֵּ֣ית אָבִ⁠י֮ וּ⁠מֵ⁠אֶ֣רֶץ מֽוֹלַדְתִּ⁠י֒ וַ⁠אֲשֶׁ֨ר דִּבֶּר־לִ֜⁠י וַ⁠אֲשֶׁ֤ר נִֽשְׁבַּֽע־לִ⁠י֙ לֵ⁠אמֹ֔ר לְ⁠זַ֨רְעֲ⁠ךָ֔ אֶתֵּ֖ן אֶת־הָ⁠אָ֣רֶץ הַ⁠זֹּ֑את ה֗וּא יִשְׁלַ֤ח מַלְאָכ⁠וֹ֙ לְ⁠פָנֶ֔י⁠ךָ וְ⁠לָקַחְתָּ֥ אִשָּׁ֛ה לִ⁠בְנִ֖⁠י מִ⁠שָּֽׁם׃","yĕhwá֣h ׀ ʼèlòhé֣y ha⁠şá̇̌ma֗yim ʼàşě֨r lĕqáẖa֜⁠niy mi⁠bé֣̇yţ ʼábi⁠y֮ ẇ⁠mé⁠ʼe֣reẕ mֽwòladĕţi̇⁠y֒ wa⁠ʼàşě֨r di̇bėr-li֜⁠y wa⁠ʼàşě֤r niֽşĕ̌bȧֽʻ-li⁠y֙ lé⁠ʼmò֔r lĕ⁠za֨rĕʻà⁠ká֔ ʼeţé֖̇n ʼeţ-há⁠ʼá֣reẕ ha⁠zò֑̇ʼţ h֗ẇʼ yişĕ̌la֤ẖ malĕʼák⁠wò֙ lĕ⁠páne֔y⁠ká wĕ⁠láqaẖĕţá֥̇ ʼişá֛̇̌h li⁠bĕni֖⁠y mi⁠şáֽ̇̌m׃"],[24,8,"וְ⁠אִם־לֹ֨א תֹאבֶ֤ה הָֽ⁠אִשָּׁה֙ לָ⁠לֶ֣כֶת אַחֲרֶ֔י⁠ךָ וְ⁠נִקִּ֕יתָ מִ⁠שְּׁבֻעָתִ֖⁠י זֹ֑את רַ֣ק אֶת־בְּנִ֔⁠י לֹ֥א תָשֵׁ֖ב שָֽׁמָּ⁠ה׃","wĕ⁠ʼim-lò֨ʼ ţòʼbe֤h háֽ⁠ʼişá̇̌h֙ lá⁠le֣keţ ʼaẖàre֔y⁠ká wĕ⁠niqi̇֕yţá mi⁠şĕ̇̌buʻáţi֖⁠y zò֑ʼţ ra֣q ʼeţ-bĕ̇ni֔⁠y lò֥ʼ ţáşé֖̌b şáֽ̌má̇⁠h׃"],[24,9,"וַ⁠יָּ֤שֶׂם הָ⁠עֶ֨בֶד֙ אֶת־יָד֔⁠וֹ תַּ֛חַת יֶ֥רֶךְ אַבְרָהָ֖ם אֲדֹנָ֑י⁠ו וַ⁠יִּשָּׁ֣בַֽע ל֔⁠וֹ עַל־הַ⁠דָּבָ֖ר הַ⁠זֶּֽה׃","wa⁠yá֤̇şêm há⁠ʻe֨bed֙ ʼeţ-yád֔⁠wò ţȧ֛ẖaţ ye֥rekĕ ʼabĕráhá֖m ʼàdòná֑y⁠w wa⁠yi̇şá֣̇̌baֽʻ l֔⁠wò ʻal-ha⁠dá̇bá֖r ha⁠zėֽh׃"],[24,10,"וַ⁠יִּקַּ֣ח הָ֠⁠עֶבֶד עֲשָׂרָ֨ה גְמַלִּ֜ים מִ⁠גְּמַלֵּ֤י אֲדֹנָי⁠ו֙ וַ⁠יֵּ֔לֶךְ וְ⁠כָל־ט֥וּב אֲדֹנָ֖י⁠ו בְּ⁠יָד֑⁠וֹ וַ⁠יָּ֗קָם וַ⁠יֵּ֛לֶךְ אֶל־אֲרַ֥ם נַֽהֲרַ֖יִם אֶל־עִ֥יר נָחֽוֹר׃","wa⁠yi̇qȧ֣ẖ há֠⁠ʻebed ʻàşá̂rá֨h gĕmali̇֜ym mi⁠gĕ̇malé֤̇y ʼàdònáy⁠w֙ wa⁠yé̇֔lekĕ wĕ⁠kál-t֥ẇb ʼàdòná֖y⁠w bĕ̇⁠yád֑⁠wò wa⁠yá̇֗qám wa⁠yé֛̇lekĕ ʼel-ʼàra֥m nֽahàra֖yim ʼel-ʻi֥yr náẖֽwòr׃"],[24,11,"וַ⁠יַּבְרֵ֧ךְ הַ⁠גְּמַלִּ֛ים מִ⁠ח֥וּץ לָ⁠עִ֖יר אֶל־בְּאֵ֣ר הַ⁠מָּ֑יִם לְ⁠עֵ֣ת עֶ֔רֶב לְ⁠עֵ֖ת צֵ֥את הַ⁠שֹּׁאֲבֹֽת׃","wa⁠yȧbĕré֧kĕ ha⁠gĕ̇mali֛̇ym mi⁠ẖ֥ẇẕ lá⁠ʻi֖yr ʼel-bĕ̇ʼé֣r ha⁠má֑̇yim lĕ⁠ʻé֣ţ ʻe֔reb lĕ⁠ʻé֖ţ ẕé֥ʼţ ha⁠şò̇̌ʼàbòֽţ׃"],[24,12,"וַ⁠יֹּאמַ֓ר ׀ יְהוָ֗ה אֱלֹהֵי֙ אֲדֹנִ֣⁠י אַבְרָהָ֔ם הַקְרֵה־נָ֥א לְ⁠פָנַ֖⁠י הַ⁠יּ֑וֹם וַ⁠עֲשֵׂה־חֶ֕סֶד עִ֖ם אֲדֹנִ֥⁠י אַבְרָהָֽם׃","wa⁠yò̇ʼma֓r ׀ yĕhwá֗h ʼèlòhéy֙ ʼàdòni֣⁠y ʼabĕráhá֔m haqĕréh-ná֥ʼ lĕ⁠pána֖⁠y ha⁠ẏ֑wòm wa⁠ʻàşé̂h-ẖe֕sed ʻi֖m ʼàdòni֥⁠y ʼabĕráháֽm׃"],[24,13,"הִנֵּ֛ה אָנֹכִ֥י נִצָּ֖ב עַל־עֵ֣ין הַ⁠מָּ֑יִם וּ⁠בְנוֹת֙ אַנְשֵׁ֣י הָ⁠עִ֔יר יֹצְאֹ֖ת לִ⁠שְׁאֹ֥ב מָֽיִם׃","hiné֛̇h ʼánòki֥y niẕá֖̇b ʻal-ʻé֣yn ha⁠má֑̇yim ẇ⁠bĕnwòţ֙ ʼanĕşé֣̌y há⁠ʻi֔yr yòẕĕʼò֖ţ li⁠şĕ̌ʼò֥b máֽyim׃"],[24,14,"וְ⁠הָיָ֣ה הַֽ⁠נַּעֲרָ֗ אֲשֶׁ֨ר אֹמַ֤ר אֵלֶ֨י⁠הָ֙ הַטִּי־נָ֤א כַדֵּ⁠ךְ֙ וְ⁠אֶשְׁתֶּ֔ה וְ⁠אָמְרָ֣ה שְׁתֵ֔ה וְ⁠גַם־גְּמַלֶּ֖י⁠ךָ אַשְׁקֶ֑ה אֹתָ֤⁠הּ הֹכַ֨חְתָּ֙ לְ⁠עַבְדְּ⁠ךָ֣ לְ⁠יִצְחָ֔ק וּ⁠בָ֣⁠הּ אֵדַ֔ע כִּי־עָשִׂ֥יתָ חֶ֖סֶד עִם־אֲדֹנִֽ⁠י׃","wĕ⁠háyá֣h haֽ⁠nȧʻàrá֗ ʼàşě֨r ʼòma֤r ʼéle֨y⁠há֙ hati̇y-ná֤ʼ kadé̇⁠kĕ֙ wĕ⁠ʼeşĕ̌ţė֔h wĕ⁠ʼámĕrá֣h şĕ̌ţé֔h wĕ⁠gam-gĕ̇malė֖y⁠ká ʼaşĕ̌qe֑h ʼòţá֤⁠ḣ hòka֨ẖĕţá̇֙ lĕ⁠ʻabĕdĕ̇⁠ká֣ lĕ⁠yiẕĕẖá֔q ẇ⁠bá֣⁠ḣ ʼéda֔ʻ ki̇y-ʻáşî֥yţá ẖe֖sed ʻim-ʼàdòniֽ⁠y׃"],[24,15,"וַֽ⁠יְהִי־ה֗וּא טֶרֶם֮ כִּלָּ֣ה לְ⁠דַבֵּר֒ וְ⁠הִנֵּ֧ה רִבְקָ֣ה יֹצֵ֗את אֲשֶׁ֤ר יֻלְּדָה֙ לִ⁠בְתוּאֵ֣ל בֶּן־מִלְכָּ֔ה אֵ֥שֶׁת נָח֖וֹר אֲחִ֣י אַבְרָהָ֑ם וְ⁠כַדָּ֖⁠הּ עַל־שִׁכְמָֽ⁠הּ׃","waֽ⁠yĕhiy-h֗ẇʼ terem֮ ki̇lá֣̇h lĕ⁠dabé̇r֒ wĕ⁠hiné֧̇h ribĕqá֣h yòẕé֗ʼţ ʼàşě֤r yulĕ̇dáh֙ li⁠bĕţẇʼé֣l bėn-milĕká̇֔h ʼé֥şěţ náẖ֖wòr ʼàẖi֣y ʼabĕráhá֑m wĕ⁠kadá֖̇⁠ḣ ʻal-şǐkĕmáֽ⁠ḣ׃"],[24,16,"וְ⁠הַֽ⁠נַּעֲרָ֗ טֹבַ֤ת מַרְאֶה֙ מְאֹ֔ד בְּתוּלָ֕ה וְ⁠אִ֖ישׁ לֹ֣א יְדָעָ֑⁠הּ וַ⁠תֵּ֣רֶד הָ⁠עַ֔יְנָ⁠ה וַ⁠תְּמַלֵּ֥א כַדָּ֖⁠הּ וַ⁠תָּֽעַל׃","wĕ⁠haֽ⁠nȧʻàrá֗ tòba֤ţ marĕʼeh֙ mĕʼò֔d bĕ̇ţẇlá֕h wĕ⁠ʼi֖yş̌ lò֣ʼ yĕdáʻá֑⁠ḣ wa⁠ţé֣̇red há⁠ʻa֔yĕná⁠h wa⁠ţĕ̇malé֥̇ʼ kadá֖̇⁠ḣ wa⁠ţáֽ̇ʻal׃"],[24,17,"וַ⁠יָּ֥רָץ הָ⁠עֶ֖בֶד לִ⁠קְרָאתָ֑⁠הּ וַ⁠יֹּ֕אמֶר הַגְמִיאִ֥י⁠נִי נָ֛א מְעַט־מַ֖יִם מִ⁠כַּדֵּֽ⁠ךְ׃","wa⁠yá֥̇ráẕ há⁠ʻe֖bed li⁠qĕráʼţá֑⁠ḣ wa⁠yò̇֕ʼmer hagĕmiyʼi֥y⁠niy ná֛ʼ mĕʻat-ma֖yim mi⁠kȧdéֽ̇⁠kĕ׃"],[24,18,"וַ⁠תֹּ֖אמֶר שְׁתֵ֣ה אֲדֹנִ֑⁠י וַ⁠תְּמַהֵ֗ר וַ⁠תֹּ֧רֶד כַּדָּ֛⁠הּ עַל־יָדָ֖⁠הּ וַ⁠תַּשְׁקֵֽ⁠הוּ׃","wa⁠ţò֖̇ʼmer şĕ̌ţé֣h ʼàdòni֑⁠y wa⁠ţĕ̇mahé֗r wa⁠ţò֧̇red kȧdá֛̇⁠ḣ ʻal-yádá֖⁠ḣ wa⁠ţȧşĕ̌qéֽ⁠hẇ׃"],[24,19,"וַ⁠תְּכַ֖ל לְ⁠הַשְׁקֹת֑⁠וֹ וַ⁠תֹּ֗אמֶר גַּ֤ם לִ⁠גְמַלֶּ֨י⁠ךָ֙ אֶשְׁאָ֔ב עַ֥ד אִם־כִּלּ֖וּ לִ⁠שְׁתֹּֽת׃","wa⁠ţĕ̇ka֖l lĕ⁠haşĕ̌qòţ֑⁠wò wa⁠ţò̇֗ʼmer gȧ֤m li⁠gĕmalė֨y⁠ká֙ ʼeşĕ̌ʼá֔b ʻa֥d ʼim-ki̇l֖̇ẇ li⁠şĕ̌ţòֽ̇ţ׃"],[24,20,"וַ⁠תְּמַהֵ֗ר וַ⁠תְּעַ֤ר כַּדָּ⁠הּ֙ אֶל־הַ⁠שֹּׁ֔קֶת וַ⁠תָּ֥רָץ ע֛וֹד אֶֽל־הַ⁠בְּאֵ֖ר לִ⁠שְׁאֹ֑ב וַ⁠תִּשְׁאַ֖ב לְ⁠כָל־גְּמַלָּֽי⁠ו׃","wa⁠ţĕ̇mahé֗r wa⁠ţĕ̇ʻa֤r kȧdá̇⁠ḣ֙ ʼel-ha⁠şò̇̌֔qeţ wa⁠ţá֥̇ráẕ ʻ֛wòd ʼeֽl-ha⁠bĕ̇ʼé֖r li⁠şĕ̌ʼò֑b wa⁠ţi̇şĕ̌ʼa֖b lĕ⁠kál-gĕ̇maláֽ̇y⁠w׃"],[24,21,"וְ⁠הָ⁠אִ֥ישׁ מִשְׁתָּאֵ֖ה לָ֑⁠הּ מַחֲרִ֕ישׁ לָ⁠דַ֗עַת הַֽ⁠הִצְלִ֧יחַ יְהוָ֛ה דַּרְכּ֖⁠וֹ אִם־לֹֽא׃","wĕ⁠há⁠ʼi֥yş̌ mişĕ̌ţá̇ʼé֖h lá֑⁠ḣ maẖàri֕yş̌ lá⁠da֗ʻaţ hֽa⁠hiẕĕli֧yẖa yĕhwá֛h dȧrĕk֖̇⁠wò ʼim-lòֽʼ׃"],[24,22,"וַ⁠יְהִ֗י כַּ⁠אֲשֶׁ֨ר כִּלּ֤וּ הַ⁠גְּמַלִּים֙ לִ⁠שְׁתּ֔וֹת וַ⁠יִּקַּ֤ח הָ⁠אִישׁ֙ נֶ֣זֶם זָהָ֔ב בֶּ֖קַע מִשְׁקָל֑⁠וֹ וּ⁠שְׁנֵ֤י צְמִידִים֙ עַל־יָדֶ֔י⁠הָ עֲשָׂרָ֥ה זָהָ֖ב מִשְׁקָלָֽ⁠ם׃","wa⁠yĕhi֗y kȧ⁠ʼàşě֨r ki̇l֤̇ẇ ha⁠gĕ̇mali̇ym֙ li⁠şĕ̌ţ̇֔wòţ wa⁠yi̇qȧ֤ẖ há⁠ʼiyş̌֙ ne֣zem záhá֔b bė֖qaʻ mişĕ̌qál֑⁠wò ẇ⁠şĕ̌né֤y ẕĕmiydiym֙ ʻal-yáde֔y⁠há ʻàşá̂rá֥h záhá֖b mişĕ̌qáláֽ⁠m׃"],[24,23,"וַ⁠יֹּ֨אמֶר֙ בַּת־מִ֣י אַ֔תְּ הַגִּ֥ידִי נָ֖א לִ֑⁠י הֲ⁠יֵ֧שׁ בֵּית־אָבִ֛י⁠ךְ מָק֥וֹם לָ֖⁠נוּ לָ⁠לִֽין׃","wa⁠yò̇֨ʼmer֙ bȧţ-mi֣y ʼa֔ţĕ̇ hagi֥̇ydiy ná֖ʼ li֑⁠y hà⁠yé֧ş̌ bé̇yţ-ʼábi֛y⁠kĕ máq֥wòm lá֖⁠nẇ lá⁠liֽyn׃"],[24,24,"וַ⁠תֹּ֣אמֶר אֵלָ֔י⁠ו בַּת־בְּתוּאֵ֖ל אָנֹ֑כִי בֶּן־מִלְכָּ֕ה אֲשֶׁ֥ר יָלְדָ֖ה לְ⁠נָחֽוֹר׃","wa⁠ţò֣̇ʼmer ʼélá֔y⁠w bȧţ-bĕ̇ţẇʼé֖l ʼánò֑kiy bėn-milĕká̇֕h ʼàşě֥r yálĕdá֖h lĕ⁠náẖֽwòr׃"],[24,25,"וַ⁠תֹּ֣אמֶר אֵלָ֔י⁠ו גַּם־תֶּ֥בֶן גַּם־מִסְפּ֖וֹא רַ֣ב עִמָּ֑⁠נוּ גַּם־מָק֖וֹם לָ⁠לֽוּן׃","wa⁠ţò֣̇ʼmer ʼélá֔y⁠w gȧm-ţė֥ben gȧm-misĕṗ֖wòʼ ra֣b ʻimá֑̇⁠nẇ gȧm-máq֖wòm lá⁠lֽẇn׃"],[24,26,"וַ⁠יִּקֹּ֣ד הָ⁠אִ֔ישׁ וַ⁠יִּשְׁתַּ֖חוּ לַֽ⁠יהוָֽה׃","wa⁠yi̇qò֣̇d há⁠ʼi֔yş̌ wa⁠yi̇şĕ̌ţȧ֖ẖẇ lֽa⁠yhwáֽh׃"],[24,27,"וַ⁠יֹּ֗אמֶר בָּר֤וּךְ יְהוָה֙ אֱלֹהֵי֙ אֲדֹנִ֣⁠י אַבְרָהָ֔ם אֲ֠שֶׁר לֹֽא־עָזַ֥ב חַסְדּ֛⁠וֹ וַ⁠אֲמִתּ֖⁠וֹ מֵ⁠עִ֣ם אֲדֹנִ֑⁠י אָנֹכִ֗י בַּ⁠דֶּ֨רֶךְ֙ נָחַ֣⁠נִי יְהוָ֔ה בֵּ֖ית אֲחֵ֥י אֲדֹנִֽ⁠י׃","wa⁠yò̇֗ʼmer bá̇r֤ẇkĕ yĕhwáh֙ ʼèlòhéy֙ ʼàdòni֣⁠y ʼabĕráhá֔m ʼà֠şěr lòֽʼ-ʻáza֥b ẖasĕḋ֛⁠wò wa⁠ʼàmiţ֖̇⁠wò mé⁠ʻi֣m ʼàdòni֑⁠y ʼánòki֗y bȧ⁠dė֨rekĕ֙ náẖa֣⁠niy yĕhwá֔h bé֖̇yţ ʼàẖé֥y ʼàdòniֽ⁠y׃"],[24,28,"וַ⁠תָּ֨רָץ֙ הַֽ⁠נַּעֲרָ֔ וַ⁠תַּגֵּ֖ד לְ⁠בֵ֣ית אִמָּ֑⁠הּ כַּ⁠דְּבָרִ֖ים הָ⁠אֵֽלֶּה׃","wa⁠ţá̇֨ráẕ֙ haֽ⁠nȧʻàrá֔ wa⁠ţȧgé֖̇d lĕ⁠bé֣yţ ʼimá֑̇⁠ḣ kȧ⁠dĕ̇bári֖ym há⁠ʼéֽlėh׃"],[24,29,"וּ⁠לְ⁠רִבְקָ֥ה אָ֖ח וּ⁠שְׁמ֣⁠וֹ לָבָ֑ן וַ⁠יָּ֨רָץ לָבָ֧ן אֶל־הָ⁠אִ֛ישׁ הַ⁠ח֖וּצָ⁠ה אֶל־הָ⁠עָֽיִן׃","ẇ⁠lĕ⁠ribĕqá֥h ʼá֖ẖ ẇ⁠şĕ̌m֣⁠wò lábá֑n wa⁠yá̇֨ráẕ lábá֧n ʼel-há⁠ʼi֛yş̌ ha⁠ẖ֖ẇẕá⁠h ʼel-há⁠ʻáֽyin׃"],[24,30,"וַ⁠יְהִ֣י ׀ כִּ⁠רְאֹ֣ת אֶת־הַ⁠נֶּ֗זֶם וְֽ⁠אֶת־הַ⁠צְּמִדִים֮ עַל־יְדֵ֣י אֲחֹת⁠וֹ֒ וּ⁠כְ⁠שָׁמְע֗⁠וֹ אֶת־דִּבְרֵ֞י רִבְקָ֤ה אֲחֹת⁠וֹ֙ לֵ⁠אמֹ֔ר כֹּֽה־דִבֶּ֥ר אֵלַ֖⁠י הָ⁠אִ֑ישׁ וַ⁠יָּבֹא֙ אֶל־הָ⁠אִ֔ישׁ וְ⁠הִנֵּ֛ה עֹמֵ֥ד עַל־הַ⁠גְּמַלִּ֖ים עַל־הָ⁠עָֽיִן׃","wa⁠yĕhi֣y ׀ ki̇⁠rĕʼò֣ţ ʼeţ-ha⁠nė֗zem wĕֽ⁠ʼeţ-ha⁠ẕĕ̇midiym֮ ʻal-yĕdé֣y ʼàẖòţ⁠wò֒ ẇ⁠kĕ⁠şá̌mĕʻ֗⁠wò ʼeţ-di̇bĕré֞y ribĕqá֤h ʼàẖòţ⁠wò֙ lé⁠ʼmò֔r kòֽ̇h-dibė֥r ʼéla֖⁠y há⁠ʼi֑yş̌ wa⁠yá̇bòʼ֙ ʼel-há⁠ʼi֔yş̌ wĕ⁠hiné֛̇h ʻòmé֥d ʻal-ha⁠gĕ̇mali֖̇ym ʻal-há⁠ʻáֽyin׃"],[24,31,"וַ⁠יֹּ֕אמֶר בּ֖וֹא בְּר֣וּךְ יְהוָ֑ה לָ֤⁠מָּה תַעֲמֹד֙ בַּ⁠ח֔וּץ וְ⁠אָנֹכִי֙ פִּנִּ֣יתִי הַ⁠בַּ֔יִת וּ⁠מָק֖וֹם לַ⁠גְּמַלִּֽים׃","wa⁠yò̇֕ʼmer ḃ֖wòʼ bĕ̇r֣ẇkĕ yĕhwá֑h lá֤⁠má̇h ţaʻàmòd֙ bȧ⁠ẖ֔ẇẕ wĕ⁠ʼánòkiy֙ pi̇ni֣̇yţiy ha⁠bȧ֔yiţ ẇ⁠máq֖wòm la⁠gĕ̇maliֽ̇ym׃"],[24,32,"וַ⁠יָּבֹ֤א הָ⁠אִישׁ֙ הַ⁠בַּ֔יְתָ⁠ה וַ⁠יְפַתַּ֖ח הַ⁠גְּמַלִּ֑ים וַ⁠יִּתֵּ֨ן תֶּ֤בֶן וּ⁠מִסְפּוֹא֙ לַ⁠גְּמַלִּ֔ים וּ⁠מַ֨יִם֙ לִ⁠רְחֹ֣ץ רַגְלָ֔י⁠ו וְ⁠רַגְלֵ֥י הָ⁠אֲנָשִׁ֖ים אֲשֶׁ֥ר אִתּֽ⁠וֹ׃","wa⁠yá̇bò֤ʼ há⁠ʼiyş̌֙ ha⁠bȧ֔yĕţá⁠h wa⁠yĕpaţȧ֖ẖ ha⁠gĕ̇mali֑̇ym wa⁠yi̇ţé̇֨n ţė֤ben ẇ⁠misĕṗwòʼ֙ la⁠gĕ̇mali̇֔ym ẇ⁠ma֨yim֙ li⁠rĕẖò֣ẕ ragĕlá֔y⁠w wĕ⁠ragĕlé֥y há⁠ʼànáşǐ֖ym ʼàşě֥r ʼiţֽ̇⁠wò׃"],[24,33,"ו⁠יישם לְ⁠פָנָי⁠ו֙ לֶ⁠אֱכֹ֔ל וַ⁠יֹּ֨אמֶר֙ לֹ֣א אֹכַ֔ל עַ֥ד אִם־דִּבַּ֖רְתִּי דְּבָרָ֑⁠י וַ⁠יֹּ֖אמֶר דַּבֵּֽר׃","w⁠yyşm lĕ⁠pánáy⁠w֙ le⁠ʼèkò֔l wa⁠yò̇֨ʼmer֙ lò֣ʼ ʼòka֔l ʻa֥d ʼim-di̇bȧ֖rĕţi̇y dĕ̇bárá֑⁠y wa⁠yò֖̇ʼmer dȧbéֽ̇r׃"],[24,34,"וַ⁠יֹּאמַ֑ר עֶ֥בֶד אַבְרָהָ֖ם אָנֹֽכִי׃","wa⁠yò̇ʼma֑r ʻe֥bed ʼabĕráhá֖m ʼánòֽkiy׃"],[24,35,"וַ⁠יהוָ֞ה בֵּרַ֧ךְ אֶת־אֲדֹנִ֛⁠י מְאֹ֖ד וַ⁠יִּגְדָּ֑ל וַ⁠יִּתֶּן־ל֞⁠וֹ צֹ֤אן וּ⁠בָקָר֙ וְ⁠כֶ֣סֶף וְ⁠זָהָ֔ב וַ⁠עֲבָדִם֙ וּ⁠שְׁפָחֹ֔ת וּ⁠גְמַלִּ֖ים וַ⁠חֲמֹרִֽים׃","wa⁠yhwá֞h bé̇ra֧kĕ ʼeţ-ʼàdòni֛⁠y mĕʼò֖d wa⁠yi̇gĕdá֑̇l wa⁠yi̇ţėn-l֞⁠wò ẕò֤ʼn ẇ⁠báqár֙ wĕ⁠ke֣sep wĕ⁠záhá֔b wa⁠ʻàbádim֙ ẇ⁠şĕ̌páẖò֔ţ ẇ⁠gĕmali֖̇ym wa⁠ẖàmòriֽym׃"],[24,36,"וַ⁠תֵּ֡לֶד שָׂרָה֩ אֵ֨שֶׁת אֲדֹנִ֥⁠י בֵן֙ לַֽ⁠אדֹנִ֔⁠י אַחֲרֵ֖י זִקְנָתָ֑⁠הּ וַ⁠יִּתֶּן־לּ֖⁠וֹ אֶת־כָּל־אֲשֶׁר־לֽ⁠וֹ׃","wa⁠ţé̇֡led şá̂ráh֩ ʼé֨şěţ ʼàdòni֥⁠y bén֙ lֽa⁠ʼdòni֔⁠y ʼaẖàré֖y ziqĕnáţá֑⁠ḣ wa⁠yi̇ţėn-l֖̇⁠wò ʼeţ-ká̇l-ʼàşěr-lֽ⁠wò׃"],[24,37,"וַ⁠יַּשְׁבִּעֵ֥⁠נִי אֲדֹנִ֖⁠י לֵ⁠אמֹ֑ר לֹא־תִקַּ֤ח אִשָּׁה֙ לִ⁠בְנִ֔⁠י מִ⁠בְּנוֹת֙ הַֽ⁠כְּנַעֲנִ֔י אֲשֶׁ֥ר אָנֹכִ֖י יֹשֵׁ֥ב בְּ⁠אַרְצֽ⁠וֹ׃","wa⁠yȧşĕ̌bi̇ʻé֥⁠niy ʼàdòni֖⁠y lé⁠ʼmò֑r lòʼ-ţiqȧ֤ẖ ʼişá̇̌h֙ li⁠bĕni֔⁠y mi⁠bĕ̇nwòţ֙ haֽ⁠kĕ̇naʻàni֔y ʼàşě֥r ʼánòki֖y yòşé֥̌b bĕ̇⁠ʼarĕẕֽ⁠wò׃"],[24,38,"אִם־לֹ֧א אֶל־בֵּית־אָבִ֛⁠י תֵּלֵ֖ךְ וְ⁠אֶל־מִשְׁפַּחְתִּ֑⁠י וְ⁠לָקַחְתָּ֥ אִשָּׁ֖ה לִ⁠בְנִֽ⁠י׃","ʼim-lò֧ʼ ʼel-bé̇yţ-ʼábi֛⁠y ţé̇lé֖kĕ wĕ⁠ʼel-mişĕ̌pȧẖĕţi֑̇⁠y wĕ⁠láqaẖĕţá֥̇ ʼişá֖̇̌h li⁠bĕniֽ⁠y׃"],[24,39,"וָ⁠אֹמַ֖ר אֶל־אֲדֹנִ֑⁠י אֻלַ֛י לֹא־תֵלֵ֥ךְ הָ⁠אִשָּׁ֖ה אַחֲרָֽ⁠י׃","wá⁠ʼòma֖r ʼel-ʼàdòni֑⁠y ʼula֛y lòʼ-ţélé֥kĕ há⁠ʼişá֖̇̌h ʼaẖàráֽ⁠y׃"],[24,40,"וַ⁠יֹּ֖אמֶר אֵלָ֑⁠י יְהוָ֞ה אֲשֶׁר־הִתְהַלַּ֣כְתִּי לְ⁠פָנָ֗י⁠ו יִשְׁלַ֨ח מַלְאָכ֤⁠וֹ אִתָּ⁠ךְ֙ וְ⁠הִצְלִ֣יחַ דַּרְכֶּ֔⁠ךָ וְ⁠לָקַחְתָּ֤ אִשָּׁה֙ לִ⁠בְנִ֔⁠י מִ⁠מִּשְׁפַּחְתִּ֖⁠י וּ⁠מִ⁠בֵּ֥ית אָבִֽ⁠י׃","wa⁠yò֖̇ʼmer ʼélá֑⁠y yĕhwá֞h ʼàşěr-hiţĕhalȧ֣kĕţi̇y lĕ⁠páná֗y⁠w yişĕ̌la֨ẖ malĕʼák֤⁠wò ʼiţá̇⁠kĕ֙ wĕ⁠hiẕĕli֣yẖa dȧrĕkė֔⁠ká wĕ⁠láqaẖĕţá֤̇ ʼişá̇̌h֙ li⁠bĕni֔⁠y mi⁠mi̇şĕ̌pȧẖĕţi֖̇⁠y ẇ⁠mi⁠bé֥̇yţ ʼábiֽ⁠y׃"],[24,41,"אָ֤ז תִּנָּקֶה֙ מֵ⁠אָ֣לָתִ֔⁠י כִּ֥י תָב֖וֹא אֶל־מִשְׁפַּחְתִּ֑⁠י וְ⁠אִם־לֹ֤א יִתְּנוּ֙ לָ֔⁠ךְ וְ⁠הָיִ֥יתָ נָקִ֖י מֵ⁠אָלָתִֽ⁠י׃","ʼá֤z ţi̇ná̇qeh֙ mé⁠ʼá֣láţi֔⁠y ki֥̇y ţáb֖wòʼ ʼel-mişĕ̌pȧẖĕţi֑̇⁠y wĕ⁠ʼim-lò֤ʼ yiţĕ̇nẇ֙ lá֔⁠kĕ wĕ⁠háyi֥yţá náqi֖y mé⁠ʼáláţiֽ⁠y׃"],[24,42,"וָ⁠אָבֹ֥א הַ⁠יּ֖וֹם אֶל־הָ⁠עָ֑יִן וָ⁠אֹמַ֗ר יְהוָה֙ אֱלֹהֵי֙ אֲדֹנִ֣⁠י אַבְרָהָ֔ם אִם־יֶשְׁ⁠ךָ־נָּא֙ מַצְלִ֣יחַ דַּרְכִּ֔⁠י אֲשֶׁ֥ר אָנֹכִ֖י הֹלֵ֥ךְ עָלֶֽי⁠הָ׃","wá⁠ʼábò֥ʼ ha⁠ẏ֖wòm ʼel-há⁠ʻá֑yin wá⁠ʼòma֗r yĕhwáh֙ ʼèlòhéy֙ ʼàdòni֣⁠y ʼabĕráhá֔m ʼim-yeşĕ̌⁠ká-ná̇ʼ֙ maẕĕli֣yẖa dȧrĕki̇֔⁠y ʼàşě֥r ʼánòki֖y hòlé֥kĕ ʻáleֽy⁠há׃"],[24,43,"הִנֵּ֛ה אָנֹכִ֥י נִצָּ֖ב עַל־עֵ֣ין הַ⁠מָּ֑יִם וְ⁠הָיָ֤ה הָֽ⁠עַלְמָה֙ הַ⁠יֹּצֵ֣את לִ⁠שְׁאֹ֔ב וְ⁠אָמַרְתִּ֣י אֵלֶ֔י⁠הָ הַשְׁקִֽי⁠נִי־נָ֥א מְעַט־מַ֖יִם מִ⁠כַּדֵּֽ⁠ךְ׃","hiné֛̇h ʼánòki֥y niẕá֖̇b ʻal-ʻé֣yn ha⁠má֑̇yim wĕ⁠háyá֤h háֽ⁠ʻalĕmáh֙ ha⁠yò̇ẕé֣ʼţ li⁠şĕ̌ʼò֔b wĕ⁠ʼámarĕţi֣̇y ʼéle֔y⁠há haşĕ̌qiֽy⁠niy-ná֥ʼ mĕʻat-ma֖yim mi⁠kȧdéֽ̇⁠kĕ׃"],[24,44,"וְ⁠אָמְרָ֤ה אֵלַ⁠י֙ גַּם־אַתָּ֣ה שְׁתֵ֔ה וְ⁠גַ֥ם לִ⁠גְמַלֶּ֖י⁠ךָ אֶשְׁאָ֑ב הִ֣וא הָֽ⁠אִשָּׁ֔ה אֲשֶׁר־הֹכִ֥יחַ יְהוָ֖ה לְ⁠בֶן־אֲדֹנִֽ⁠י׃","wĕ⁠ʼámĕrá֤h ʼéla⁠y֙ gȧm-ʼaţá֣̇h şĕ̌ţé֔h wĕ⁠ga֥m li⁠gĕmalė֖y⁠ká ʼeşĕ̌ʼá֑b hi֣wʼ hֽá⁠ʼişá̇̌֔h ʼàşěr-hòki֥yẖa yĕhwá֖h lĕ⁠ben-ʼàdòniֽ⁠y׃"],[24,45,"אֲנִי֩ טֶ֨רֶם אֲכַלֶּ֜ה לְ⁠דַבֵּ֣ר אֶל־לִבִּ֗⁠י וְ⁠הִנֵּ֨ה רִבְקָ֤ה יֹצֵאת֙ וְ⁠כַדָּ֣⁠הּ עַל־שִׁכְמָ֔⁠הּ וַ⁠תֵּ֥רֶד הָ⁠עַ֖יְנָ⁠ה וַ⁠תִּשְׁאָ֑ב וָ⁠אֹמַ֥ר אֵלֶ֖י⁠הָ הַשְׁקִ֥י⁠נִי נָֽא׃","ʼàniy֩ te֨rem ʼàkalė֜h lĕ⁠dabé֣̇r ʼel-libi̇֗⁠y wĕ⁠hiné̇֨h ribĕqá֤h yòẕéʼţ֙ wĕ⁠kadá֣̇⁠ḣ ʻal-şǐkĕmá֔⁠ḣ wa⁠ţé֥̇red há⁠ʻa֖yĕná⁠h wa⁠ţi̇şĕ̌ʼá֑b wá⁠ʼòma֥r ʼéle֖y⁠há haşĕ̌qi֥y⁠niy náֽʼ׃"],[24,46,"וַ⁠תְּמַהֵ֗ר וַ⁠תּ֤וֹרֶד כַּדָּ⁠הּ֙ מֵֽ⁠עָלֶ֔י⁠הָ וַ⁠תֹּ֣אמֶר שְׁתֵ֔ה וְ⁠גַם־גְּמַלֶּ֖י⁠ךָ אַשְׁקֶ֑ה וָ⁠אֵ֕שְׁתְּ וְ⁠גַ֥ם הַ⁠גְּמַלִּ֖ים הִשְׁקָֽתָה׃","wa⁠ţĕ̇mahé֗r wa⁠ţ֤̇wòred kȧdá̇⁠ḣ֙ méֽ⁠ʻále֔y⁠há wa⁠ţò֣̇ʼmer şĕ̌ţé֔h wĕ⁠gam-gĕ̇malė֖y⁠ká ʼaşĕ̌qe֑h wá⁠ʼé֕şĕ̌ţĕ̇ wĕ⁠ga֥m ha⁠gĕ̇mali֖̇ym hişĕ̌qáֽţáh׃"],[24,47,"וָ⁠אֶשְׁאַ֣ל אֹתָ֗⁠הּ וָ⁠אֹמַר֮ בַּת־מִ֣י אַתְּ֒ וַ⁠תֹּ֗אמֶר בַּת־בְּתוּאֵל֙ בֶּן־נָח֔וֹר אֲשֶׁ֥ר יָֽלְדָה־לּ֖⁠וֹ מִלְכָּ֑ה וָ⁠אָשִׂ֤ם הַ⁠נֶּ֨זֶם֙ עַל־אַפָּ֔⁠הּ וְ⁠הַ⁠צְּמִידִ֖ים עַל־יָדֶֽי⁠הָ׃","wá⁠ʼeşĕ̌ʼa֣l ʼòţá֗⁠ḣ wá⁠ʼòmar֮ bȧţ-mi֣y ʼaţĕ̇֒ wa⁠ţò̇֗ʼmer bȧţ-bĕ̇ţẇʼél֙ bėn-náẖ֔wòr ʼàşě֥r yáֽlĕdáh-l֖̇⁠wò milĕká֑̇h wá⁠ʼáşî֤m ha⁠nė֨zem֙ ʻal-ʼapá̇֔⁠ḣ wĕ⁠ha⁠ẕĕ̇miydi֖ym ʻal-yádeֽy⁠há׃"],[24,48,"וָ⁠אֶקֹּ֥ד וָֽ⁠אֶשְׁתַּחֲוֶ֖ה לַ⁠יהוָ֑ה וָ⁠אֲבָרֵ֗ךְ אֶת־יְהוָה֙ אֱלֹהֵי֙ אֲדֹנִ֣⁠י אַבְרָהָ֔ם אֲשֶׁ֤ר הִנְחַ֨⁠נִי֙ בְּ⁠דֶ֣רֶךְ אֱמֶ֔ת לָ⁠קַ֛חַת אֶת־בַּת־אֲחִ֥י אֲדֹנִ֖⁠י לִ⁠בְנֽ⁠וֹ׃","wá⁠ʼeqò֥̇d wáֽ⁠ʼeşĕ̌ţȧẖàwe֖h la⁠yhwá֑h wá⁠ʼàbáré֗kĕ ʼeţ-yĕhwáh֙ ʼèlòhéy֙ ʼàdòni֣⁠y ʼabĕráhá֔m ʼàşě֤r hinĕẖa֨⁠niy֙ bĕ̇⁠de֣rekĕ ʼème֔ţ lá⁠qa֛ẖaţ ʼeţ-bȧţ-ʼàẖi֥y ʼàdòni֖⁠y li⁠bĕnֽ⁠wò׃"],[24,49,"וְ֠⁠עַתָּה אִם־יֶשְׁ⁠כֶ֨ם עֹשִׂ֜ים חֶ֧סֶד וֶֽ⁠אֱמֶ֛ת אֶת־אֲדֹנִ֖⁠י הַגִּ֣ידוּ לִ֑⁠י וְ⁠אִם־לֹ֕א הַגִּ֣ידוּ לִ֔⁠י וְ⁠אֶפְנֶ֥ה עַל־יָמִ֖ין א֥וֹ עַל־שְׂמֹֽאל׃","wĕ֠⁠ʻaţá̇h ʼim-yeşĕ̌⁠ke֨m ʻòşî֜ym ẖe֧sed wֽe⁠ʼème֛ţ ʼeţ-ʼàdòni֖⁠y hagi֣̇ydẇ li֑⁠y wĕ⁠ʼim-lò֕ʼ hagi֣̇ydẇ li֔⁠y wĕ⁠ʼepĕne֥h ʻal-yámi֖yn ʼ֥wò ʻal-şĕ̂mòֽʼl׃"],[24,50,"וַ⁠יַּ֨עַן לָבָ֤ן וּ⁠בְתוּאֵל֙ וַ⁠יֹּ֣אמְר֔וּ מֵ⁠יְהוָ֖ה יָצָ֣א הַ⁠דָּבָ֑ר לֹ֥א נוּכַ֛ל דַּבֵּ֥ר אֵלֶ֖י⁠ךָ רַ֥ע אוֹ־טֽוֹב׃","wa⁠yȧ֨ʻan lábá֤n ẇ⁠bĕţẇʼél֙ wa⁠yò֣̇ʼmĕr֔ẇ mé⁠yĕhwá֖h yáẕá֣ʼ ha⁠dá̇bá֑r lò֥ʼ nẇka֛l dȧbé֥̇r ʼéle֖y⁠ká ra֥ʻ ʼwò-tֽwòb׃"],[24,51,"הִנֵּֽה־רִבְקָ֥ה לְ⁠פָנֶ֖י⁠ךָ קַ֣ח וָ⁠לֵ֑ךְ וּ⁠תְהִ֤י אִשָּׁה֙ לְ⁠בֶן־אֲדֹנֶ֔י⁠ךָ כַּ⁠אֲשֶׁ֖ר דִּבֶּ֥ר יְהוָֽה׃","hinéֽ̇h-ribĕqá֥h lĕ⁠páne֖y⁠ká qa֣ẖ wá⁠lé֑kĕ ẇ⁠ţĕhi֤y ʼişá̇̌h֙ lĕ⁠ben-ʼàdòne֔y⁠ká kȧ⁠ʼàşě֖r di̇bė֥r yĕhwáֽh׃"],[24,52,"וַ⁠יְהִ֕י כַּ⁠אֲשֶׁ֥ר שָׁמַ֛ע עֶ֥בֶד אַבְרָהָ֖ם אֶת־דִּבְרֵי⁠הֶ֑ם וַ⁠יִּשְׁתַּ֥חוּ אַ֖רְצָ⁠ה לַֽ⁠יהוָֽה׃","wa⁠yĕhi֕y kȧ⁠ʼàşě֥r şá̌ma֛ʻ ʻe֥bed ʼabĕráhá֖m ʼeţ-di̇bĕréy⁠he֑m wa⁠yi̇şĕ̌ţȧ֥ẖẇ ʼa֖rĕẕá⁠h lֽa⁠yhwáֽh׃"],[24,53,"וַ⁠יּוֹצֵ֨א הָ⁠עֶ֜בֶד כְּלֵי־כֶ֨סֶף וּ⁠כְלֵ֤י זָהָב֙ וּ⁠בְגָדִ֔ים וַ⁠יִּתֵּ֖ן לְ⁠רִבְקָ֑ה וּ⁠מִ֨גְדָּנֹ֔ת נָתַ֥ן לְ⁠אָחִ֖י⁠הָ וּ⁠לְ⁠אִמָּֽ⁠הּ׃","wa⁠ẏwòẕé֨ʼ há⁠ʻe֜bed kĕ̇léy-ke֨sep ẇ⁠kĕlé֤y záháb֙ ẇ⁠bĕgádi֔ym wa⁠yi̇ţé֖̇n lĕ⁠ribĕqá֑h ẇ⁠mi֨gĕdá̇nò֔ţ náţa֥n lĕ⁠ʼáẖi֖y⁠há ẇ⁠lĕ⁠ʼimáֽ̇⁠ḣ׃"],[24,54,"וַ⁠יֹּאכְל֣וּ וַ⁠יִּשְׁתּ֗וּ ה֛וּא וְ⁠הָ⁠אֲנָשִׁ֥ים אֲשֶׁר־עִמּ֖⁠וֹ וַ⁠יָּלִ֑ינוּ וַ⁠יָּק֣וּמוּ בַ⁠בֹּ֔קֶר וַ⁠יֹּ֖אמֶר שַׁלְּחֻ֥⁠נִי לַֽ⁠אדֹנִֽ⁠י׃","wa⁠yò̇ʼkĕl֣ẇ wa⁠yi̇şĕ̌ţ̇֗ẇ h֛ẇʼ wĕ⁠há⁠ʼànáşǐ֥ym ʼàşěr-ʻiṁ֖⁠wò wa⁠yá̇li֑ynẇ wa⁠yá̇q֣ẇmẇ ba⁠bò̇֔qer wa⁠yò֖̇ʼmer şǎlĕ̇ẖu֥⁠niy lֽa⁠ʼdòniֽ⁠y׃"],[24,55,"וַ⁠יֹּ֤אמֶר אָחִ֨י⁠הָ֙ וְ⁠אִמָּ֔⁠הּ תֵּשֵׁ֨ב הַ⁠נַּעֲרָ֥ אִתָּ֛⁠נוּ יָמִ֖ים א֣וֹ עָשׂ֑וֹר אַחַ֖ר תֵּלֵֽךְ׃","wa⁠yò֤̇ʼmer ʼáẖi֨y⁠há֙ wĕ⁠ʼimá̇֔⁠ḣ ţé̇şé̌֨b ha⁠nȧʻàrá֥ ʼiţá֛̇⁠nẇ yámi֖ym ʼ֣wò ʻáş֑̂wòr ʼaẖa֖r ţé̇léֽkĕ׃"],[24,56,"וַ⁠יֹּ֤אמֶר אֲלֵ⁠הֶם֙ אַל־תְּאַחֲר֣וּ אֹתִ֔⁠י וַֽ⁠יהוָ֖ה הִצְלִ֣יחַ דַּרְכִּ֑⁠י שַׁלְּח֕וּ⁠נִי וְ⁠אֵלְכָ֖ה לַֽ⁠אדֹנִֽ⁠י׃","wa⁠yò֤̇ʼmer ʼàlé⁠hem֙ ʼal-ţĕ̇ʼaẖàr֣ẇ ʼòţi֔⁠y wֽa⁠yhwá֖h hiẕĕli֣yẖa dȧrĕki֑̇⁠y şǎlĕ̇ẖ֕ẇ⁠niy wĕ⁠ʼélĕká֖h lֽa⁠ʼdòniֽ⁠y׃"],[24,57,"וַ⁠יֹּאמְר֖וּ נִקְרָ֣א לַֽ⁠נַּעֲרָ֑ וְ⁠נִשְׁאֲלָ֖ה אֶת־פִּֽי⁠הָ׃","wa⁠yò̇ʼmĕr֖ẇ niqĕrá֣ʼ laֽ⁠nȧʻàrá֑ wĕ⁠nişĕ̌ʼàlá֖h ʼeţ-piֽ̇y⁠há׃"],[24,58,"וַ⁠יִּקְרְא֤וּ לְ⁠רִבְקָה֙ וַ⁠יֹּאמְר֣וּ אֵלֶ֔י⁠הָ הֲ⁠תֵלְכִ֖י עִם־הָ⁠אִ֣ישׁ הַ⁠זֶּ֑ה וַ⁠תֹּ֖אמֶר אֵלֵֽךְ׃","wa⁠yi̇qĕrĕʼ֤ẇ lĕ⁠ribĕqáh֙ wa⁠yò̇ʼmĕr֣ẇ ʼéle֔y⁠há hà⁠ţélĕki֖y ʻim-há⁠ʼi֣yş̌ ha⁠zė֑h wa⁠ţò֖̇ʼmer ʼéléֽkĕ׃"],[24,59,"וַֽ⁠יְשַׁלְּח֛וּ אֶת־רִבְקָ֥ה אֲחֹתָ֖⁠ם וְ⁠אֶת־מֵנִקְתָּ֑⁠הּ וְ⁠אֶת־עֶ֥בֶד אַבְרָהָ֖ם וְ⁠אֶת־אֲנָשָֽׁי⁠ו׃","waֽ⁠yĕşǎlĕ̇ẖ֛ẇ ʼeţ-ribĕqá֥h ʼàẖòţá֖⁠m wĕ⁠ʼeţ-méniqĕţá֑̇⁠ḣ wĕ⁠ʼeţ-ʻe֥bed ʼabĕráhá֖m wĕ⁠ʼeţ-ʼànáşáֽ̌y⁠w׃"],[24,60,"וַ⁠יְבָרֲכ֤וּ אֶת־רִבְקָה֙ וַ⁠יֹּ֣אמְרוּ לָ֔⁠הּ אֲחֹתֵ֕⁠נוּ אַ֥תְּ הֲיִ֖י לְ⁠אַלְפֵ֣י רְבָבָ֑ה וְ⁠יִירַ֣שׁ זַרְעֵ֔⁠ךְ אֵ֖ת שַׁ֥עַר שֹׂנְאָֽי⁠ו׃","wa⁠yĕbáràk֤ẇ ʼeţ-ribĕqáh֙ wa⁠yò֣̇ʼmĕrẇ lá֔⁠ḣ ʼàẖòţé֕⁠nẇ ʼa֥ţĕ̇ hàyi֖y lĕ⁠ʼalĕpé֣y rĕbábá֑h wĕ⁠yiyra֣ş̌ zarĕʻé֔⁠kĕ ʼé֖ţ şǎ֥ʻar şò̂nĕʼáֽy⁠w׃"],[24,61,"וַ⁠תָּ֨קָם רִבְקָ֜ה וְ⁠נַעֲרֹתֶ֗י⁠הָ וַ⁠תִּרְכַּ֨בְנָה֙ עַל־הַ⁠גְּמַלִּ֔ים וַ⁠תֵּלַ֖כְנָה אַחֲרֵ֣י הָ⁠אִ֑ישׁ וַ⁠יִּקַּ֥ח הָ⁠עֶ֛בֶד אֶת־רִבְקָ֖ה וַ⁠יֵּלַֽךְ׃","wa⁠ţá̇֨qám ribĕqá֜h wĕ⁠naʻàròţe֗y⁠há wa⁠ţi̇rĕkȧ֨bĕnáh֙ ʻal-ha⁠gĕ̇mali̇֔ym wa⁠ţé̇la֖kĕnáh ʼaẖàré֣y há⁠ʼi֑yş̌ wa⁠yi̇qȧ֥ẖ há⁠ʻe֛bed ʼeţ-ribĕqá֖h wa⁠yé̇laֽkĕ׃"],[24,62,"וְ⁠יִצְחָק֙ בָּ֣א מִ⁠בּ֔וֹא בְּאֵ֥ר לַחַ֖י רֹאִ֑י וְ⁠ה֥וּא יוֹשֵׁ֖ב בְּ⁠אֶ֥רֶץ הַ⁠נֶּֽגֶב׃","wĕ⁠yiẕĕẖáq֙ bá֣̇ʼ mi⁠ḃ֔wòʼ bĕ̇ʼé֥r laẖa֖y ròʼi֑y wĕ⁠h֥ẇʼ ywòşé֖̌b bĕ̇⁠ʼe֥reẕ ha⁠nėֽgeb׃"],[24,63,"וַ⁠יֵּצֵ֥א יִצְחָ֛ק לָ⁠שׂ֥וּחַ בַּ⁠שָּׂדֶ֖ה לִ⁠פְנ֣וֹת עָ֑רֶב וַ⁠יִּשָּׂ֤א עֵינָי⁠ו֙ וַ⁠יַּ֔רְא וְ⁠הִנֵּ֥ה גְמַלִּ֖ים בָּאִֽים׃","wa⁠yé̇ẕé֥ʼ yiẕĕẖá֛q lá⁠ş֥̂ẇẖa bȧ⁠şá̇̂de֖h li⁠pĕn֣wòţ ʻá֑reb wa⁠yi̇şá֤̇̂ʼ ʻéynáy⁠w֙ wa⁠yȧ֔rĕʼ wĕ⁠hiné֥̇h gĕmali֖̇ym bá̇ʼiֽym׃"],[24,64,"וַ⁠תִּשָּׂ֤א רִבְקָה֙ אֶת־עֵינֶ֔י⁠הָ וַ⁠תֵּ֖רֶא אֶת־יִצְחָ֑ק וַ⁠תִּפֹּ֖ל מֵ⁠עַ֥ל הַ⁠גָּמָֽל׃","wa⁠ţi̇şá֤̇̂ʼ ribĕqáh֙ ʼeţ-ʻéyne֔y⁠há wa⁠ţé֖̇reʼ ʼeţ-yiẕĕẖá֑q wa⁠ţi̇pò֖̇l mé⁠ʻa֥l ha⁠gá̇máֽl׃"],[24,65,"וַ⁠תֹּ֣אמֶר אֶל־הָ⁠עֶ֗בֶד מִֽי־הָ⁠אִ֤ישׁ הַלָּזֶה֙ הַ⁠הֹלֵ֤ךְ בַּ⁠שָּׂדֶה֙ לִ⁠קְרָאתֵ֔⁠נוּ וַ⁠יֹּ֥אמֶר הָ⁠עֶ֖בֶד ה֣וּא אֲדֹנִ֑⁠י וַ⁠תִּקַּ֥ח הַ⁠צָּעִ֖יף וַ⁠תִּתְכָּֽס׃","wa⁠ţò֣̇ʼmer ʼel-há⁠ʻe֗bed miֽy-há⁠ʼi֤yş̌ halá̇zeh֙ ha⁠hòlé֤kĕ bȧ⁠şá̇̂deh֙ li⁠qĕráʼţé֔⁠nẇ wa⁠yò֥̇ʼmer há⁠ʻe֖bed h֣ẇʼ ʼàdòni֑⁠y wa⁠ţi̇qȧ֥ẖ ha⁠ẕá̇ʻi֖yp wa⁠ţi̇ţĕkáֽ̇s׃"],[24,66,"וַ⁠יְסַפֵּ֥ר הָ⁠עֶ֖בֶד לְ⁠יִצְחָ֑ק אֵ֥ת כָּל־הַ⁠דְּבָרִ֖ים אֲשֶׁ֥ר עָשָֽׂה׃","wa⁠yĕsapé֥̇r há⁠ʻe֖bed lĕ⁠yiẕĕẖá֑q ʼé֥ţ ká̇l-ha⁠dĕ̇bári֖ym ʼàşě֥r ʻáşáֽ̂h׃"],[24,67,"וַ⁠יְבִאֶ֣⁠הָ יִצְחָ֗ק הָ⁠אֹ֨הֱלָ⁠ה֙ שָׂרָ֣ה אִמּ֔⁠וֹ וַ⁠יִּקַּ֧ח אֶת־רִבְקָ֛ה וַ⁠תְּהִי־ל֥⁠וֹ לְ⁠אִשָּׁ֖ה וַ⁠יֶּאֱהָבֶ֑⁠הָ וַ⁠יִּנָּחֵ֥ם יִצְחָ֖ק אַחֲרֵ֥י אִמּֽ⁠וֹ׃פ","wa⁠yĕbiʼe֣⁠há yiẕĕẖá֗q há⁠ʼò֨hèlá⁠h֙ şá̂rá֣h ʼiṁ֔⁠wò wa⁠yi̇qȧ֧ẖ ʼeţ-ribĕqá֛h wa⁠ţĕ̇hiy-l֥⁠wò lĕ⁠ʼişá֖̇̌h wa⁠yėʼèhábe֑⁠há wa⁠yi̇ná̇ẖé֥m yiẕĕẖá֖q ʼaẖàré֥y ʼiṁֽ⁠wò׃p"],[25,1,"וַ⁠יֹּ֧סֶף אַבְרָהָ֛ם וַ⁠יִּקַּ֥ח אִשָּׁ֖ה וּ⁠שְׁמָ֥⁠הּ קְטוּרָֽה׃","wa⁠yò֧̇sep ʼabĕráhá֛m wa⁠yi̇qȧ֥ẖ ʼişá֖̇̌h ẇ⁠şĕ̌má֥⁠ḣ qĕtẇráֽh׃"],[25,2,"וַ⁠תֵּ֣לֶד ל֗⁠וֹ אֶת־זִמְרָן֙ וְ⁠אֶת־יָקְשָׁ֔ן וְ⁠אֶת־מְדָ֖ן וְ⁠אֶת־מִדְיָ֑ן וְ⁠אֶת־יִשְׁבָּ֖ק וְ⁠אֶת־שֽׁוּחַ׃","wa⁠ţé֣̇led l֗⁠wò ʼeţ-zimĕrán֙ wĕ⁠ʼeţ-yáqĕşá̌֔n wĕ⁠ʼeţ-mĕdá֖n wĕ⁠ʼeţ-midĕyá֑n wĕ⁠ʼeţ-yişĕ̌bá֖̇q wĕ⁠ʼeţ-şֽ̌ẇẖa׃"],[25,3,"וְ⁠יָקְשָׁ֣ן יָלַ֔ד אֶת־שְׁבָ֖א וְ⁠אֶת־דְּדָ֑ן וּ⁠בְנֵ֣י דְדָ֔ן הָי֛וּ אַשּׁוּרִ֥ם וּ⁠לְטוּשִׁ֖ים וּ⁠לְאֻמִּֽים׃","wĕ⁠yáqĕşá֣̌n yála֔d ʼeţ-şĕ̌bá֖ʼ wĕ⁠ʼeţ-dĕ̇dá֑n ẇ⁠bĕné֣y dĕdá֔n háy֛ẇ ʼaş̇̌ẇri֥m ẇ⁠lĕtẇşǐ֖ym ẇ⁠lĕʼumiֽ̇ym׃"],[25,4,"וּ⁠בְנֵ֣י מִדְיָ֗ן עֵיפָ֤ה וָ⁠עֵ֨פֶר֙ וַ⁠חֲנֹ֔ךְ וַ⁠אֲבִידָ֖ע וְ⁠אֶלְדָּעָ֑ה כָּל־אֵ֖לֶּה בְּנֵ֥י קְטוּרָֽה׃","ẇ⁠bĕné֣y midĕyá֗n ʻéypá֤h wá⁠ʻé֨per֙ wa⁠ẖànò֔kĕ wa⁠ʼàbiydá֖ʻ wĕ⁠ʼelĕdá̇ʻá֑h ká̇l-ʼé֖lėh bĕ̇né֥y qĕtẇráֽh׃"],[25,5,"וַ⁠יִּתֵּ֧ן אַבְרָהָ֛ם אֶת־כָּל־אֲשֶׁר־ל֖⁠וֹ לְ⁠יִצְחָֽק׃","wa⁠yi̇ţé֧̇n ʼabĕráhá֛m ʼeţ-ká̇l-ʼàşěr-l֖⁠wò lĕ⁠yiẕĕẖáֽq׃"],[25,6,"וְ⁠לִ⁠בְנֵ֤י הַ⁠פִּֽילַגְשִׁים֙ אֲשֶׁ֣ר לְ⁠אַבְרָהָ֔ם נָתַ֥ן אַבְרָהָ֖ם מַתָּנֹ֑ת וַֽ⁠יְשַׁלְּחֵ֞⁠ם מֵ⁠עַ֨ל יִצְחָ֤ק בְּנ⁠וֹ֙ בְּ⁠עוֹדֶ֣⁠נּוּ חַ֔י קֵ֖דְמָ⁠ה אֶל־אֶ֥רֶץ קֶֽדֶם׃","wĕ⁠li⁠bĕné֤y ha⁠piֽ̇ylagĕşǐym֙ ʼàşě֣r lĕ⁠ʼabĕráhá֔m náţa֥n ʼabĕráhá֖m maţá̇nò֑ţ waֽ⁠yĕşǎlĕ̇ẖé֞⁠m mé⁠ʻa֨l yiẕĕẖá֤q bĕ̇n⁠wò֙ bĕ̇⁠ʻwòde֣⁠ṅẇ ẖa֔y qé֖dĕmá⁠h ʼel-ʼe֥reẕ qeֽdem׃"],[25,7,"וְ⁠אֵ֗לֶּה יְמֵ֛י שְׁנֵֽי־חַיֵּ֥י אַבְרָהָ֖ם אֲשֶׁר־חָ֑י מְאַ֥ת שָׁנָ֛ה וְ⁠שִׁבְעִ֥ים שָׁנָ֖ה וְ⁠חָמֵ֥שׁ שָׁנִֽים׃","wĕ⁠ʼé֗lėh yĕmé֛y şĕ̌néֽy-ẖayé֥̇y ʼabĕráhá֖m ʼàşěr-ẖá֑y mĕʼa֥ţ şá̌ná֛h wĕ⁠şǐbĕʻi֥ym şá̌ná֖h wĕ⁠ẖámé֥ş̌ şá̌niֽym׃"],[25,8,"וַ⁠יִּגְוַ֨ע וַ⁠יָּ֧מָת אַבְרָהָ֛ם בְּ⁠שֵׂיבָ֥ה טוֹבָ֖ה זָקֵ֣ן וְ⁠שָׂבֵ֑עַ וַ⁠יֵּאָ֖סֶף אֶל־עַמָּֽי⁠ו׃","wa⁠yi̇gĕwa֨ʻ wa⁠yá֧̇máţ ʼabĕráhá֛m bĕ̇⁠şé̂ybá֥h twòbá֖h záqé֣n wĕ⁠şá̂bé֑ʻa wa⁠yé̇ʼá֖sep ʼel-ʻamáֽ̇y⁠w׃"],[25,9,"וַ⁠יִּקְבְּר֨וּ אֹת֜⁠וֹ יִצְחָ֤ק וְ⁠יִשְׁמָעֵאל֙ בָּנָ֔י⁠ו אֶל־מְעָרַ֖ת הַ⁠מַּכְפֵּלָ֑ה אֶל־שְׂדֵ֞ה עֶפְרֹ֤ן בֶּן־צֹ֨חַר֙ הַֽ⁠חִתִּ֔י אֲשֶׁ֖ר עַל־פְּנֵ֥י מַמְרֵֽא׃","wa⁠yi̇qĕbĕ̇r֨ẇ ʼòţ֜⁠wò yiẕĕẖá֤q wĕ⁠yişĕ̌máʻéʼl֙ bá̇ná֔y⁠w ʼel-mĕʻára֖ţ ha⁠mȧkĕpé̇lá֑h ʼel-şĕ̂dé֞h ʻepĕrò֤n bėn-ẕò֨ẖar֙ haֽ⁠ẖiţi̇֔y ʼàşě֖r ʻal-pĕ̇né֥y mamĕréֽʼ׃"],[25,10,"הַ⁠שָּׂדֶ֛ה אֲשֶׁר־קָנָ֥ה אַבְרָהָ֖ם מֵ⁠אֵ֣ת בְּנֵי־חֵ֑ת שָׁ֛מָּ⁠ה קֻבַּ֥ר אַבְרָהָ֖ם וְ⁠שָׂרָ֥ה אִשְׁתּֽ⁠וֹ׃","ha⁠şá̇̂de֛h ʼàşěr-qáná֥h ʼabĕráhá֖m mé⁠ʼé֣ţ bĕ̇néy-ẖé֑ţ şá֛̌má̇⁠h qubȧ֥r ʼabĕráhá֖m wĕ⁠şá̂rá֥h ʼişĕ̌ţֽ̇⁠wò׃"],[25,11,"וַ⁠יְהִ֗י אַחֲרֵי֙ מ֣וֹת אַבְרָהָ֔ם וַ⁠יְבָ֥רֶךְ אֱלֹהִ֖ים אֶת־יִצְחָ֣ק בְּנ֑⁠וֹ וַ⁠יֵּ֣שֶׁב יִצְחָ֔ק עִם־בְּאֵ֥ר לַחַ֖י רֹאִֽי׃ס","wa⁠yĕhi֗y ʼaẖàréy֙ m֣wòţ ʼabĕráhá֔m wa⁠yĕbá֥rekĕ ʼèlòhi֖ym ʼeţ-yiẕĕẖá֣q bĕ̇n֑⁠wò wa⁠yé֣̇şěb yiẕĕẖá֔q ʻim-bĕ̇ʼé֥r laẖa֖y ròʼiֽy׃s"],[25,12,"וְ⁠אֵ֛לֶּה תֹּלְדֹ֥ת יִשְׁמָעֵ֖אל בֶּן־אַבְרָהָ֑ם אֲשֶׁ֨ר יָלְדָ֜ה הָגָ֧ר הַ⁠מִּצְרִ֛ית שִׁפְחַ֥ת שָׂרָ֖ה לְ⁠אַבְרָהָֽם׃","wĕ⁠ʼé֛lėh ţò̇lĕdò֥ţ yişĕ̌máʻé֖ʼl bėn-ʼabĕráhá֑m ʼàşě֨r yálĕdá֜h hágá֧r ha⁠mi̇ẕĕri֛yţ şǐpĕẖa֥ţ şá̂rá֖h lĕ⁠ʼabĕráháֽm׃"],[25,13,"וְ⁠אֵ֗לֶּה שְׁמוֹת֙ בְּנֵ֣י יִשְׁמָעֵ֔אל בִּ⁠שְׁמֹתָ֖⁠ם לְ⁠תוֹלְדֹתָ֑⁠ם בְּכֹ֤ר יִשְׁמָעֵאל֙ נְבָיֹ֔ת וְ⁠קֵדָ֥ר וְ⁠אַדְבְּאֵ֖ל וּ⁠מִבְשָֽׂם׃","wĕ⁠ʼé֗lėh şĕ̌mwòţ֙ bĕ̇né֣y yişĕ̌máʻé֔ʼl bi̇⁠şĕ̌mòţá֖⁠m lĕ⁠ţwòlĕdòţá֑⁠m bĕ̇kò֤r yişĕ̌máʻéʼl֙ nĕbáyò֔ţ wĕ⁠qédá֥r wĕ⁠ʼadĕbĕ̇ʼé֖l ẇ⁠mibĕşáֽ̂m׃"],[25,14,"וּ⁠מִשְׁמָ֥ע וְ⁠דוּמָ֖ה וּ⁠מַשָּֽׂא׃","ẇ⁠mişĕ̌má֥ʻ wĕ⁠dẇmá֖h ẇ⁠maşáֽ̇̂ʼ׃"],[25,15,"חֲדַ֣ד וְ⁠תֵימָ֔א יְט֥וּר נָפִ֖ישׁ וָ⁠קֵֽדְמָה׃","ẖàda֣d wĕ⁠ţéymá֔ʼ yĕt֥ẇr nápi֖yş̌ wá⁠qéֽdĕmáh׃"],[25,16,"אֵ֣לֶּה הֵ֞ם בְּנֵ֤י יִשְׁמָעֵאל֙ וְ⁠אֵ֣לֶּה שְׁמֹתָ֔⁠ם בְּ⁠חַצְרֵי⁠הֶ֖ם וּ⁠בְ⁠טִֽירֹתָ֑⁠ם שְׁנֵים־עָשָׂ֥ר נְשִׂיאִ֖ם לְ⁠אֻמֹּתָֽ⁠ם׃","ʼé֣lėh hé֞m bĕ̇né֤y yişĕ̌máʻéʼl֙ wĕ⁠ʼé֣lėh şĕ̌mòţá֔⁠m bĕ̇⁠ẖaẕĕréy⁠he֖m ẇ⁠bĕ⁠tiֽyròţá֑⁠m şĕ̌néym-ʻáşá֥̂r nĕşîyʼi֖m lĕ⁠ʼumò̇ţáֽ⁠m׃"],[25,17,"וְ⁠אֵ֗לֶּה שְׁנֵי֙ חַיֵּ֣י יִשְׁמָעֵ֔אל מְאַ֥ת שָׁנָ֛ה וּ⁠שְׁלֹשִׁ֥ים שָׁנָ֖ה וְ⁠שֶׁ֣בַע שָׁנִ֑ים וַ⁠יִּגְוַ֣ע וַ⁠יָּ֔מָת וַ⁠יֵּאָ֖סֶף אֶל־עַמָּֽי⁠ו׃","wĕ⁠ʼé֗lėh şĕ̌néy֙ ẖayé֣̇y yişĕ̌máʻé֔ʼl mĕʼa֥ţ şá̌ná֛h ẇ⁠şĕ̌lòşǐ֥ym şá̌ná֖h wĕ⁠şě֣baʻ şá̌ni֑ym wa⁠yi̇gĕwa֣ʻ wa⁠yá̇֔máţ wa⁠yé̇ʼá֖sep ʼel-ʻamáֽ̇y⁠w׃"],[25,18,"וַ⁠יִּשְׁכְּנ֨וּ מֵֽ⁠חֲוִילָ֜ה עַד־שׁ֗וּר אֲשֶׁר֙ עַל־פְּנֵ֣י מִצְרַ֔יִם בֹּאֲ⁠כָ֖ה אַשּׁ֑וּרָ⁠ה עַל־פְּנֵ֥י כָל־אֶחָ֖י⁠ו נָפָֽל׃פ","wa⁠yi̇şĕ̌kĕ̇n֨ẇ mֽé⁠ẖàwiylá֜h ʻad-ş̌֗ẇr ʼàşěr֙ ʻal-pĕ̇né֣y miẕĕra֔yim bò̇ʼà⁠ká֖h ʼaş֑̇̌ẇrá⁠h ʻal-pĕ̇né֥y kál-ʼeẖá֖y⁠w nápáֽl׃p"],[25,19,"וְ⁠אֵ֛לֶּה תּוֹלְדֹ֥ת יִצְחָ֖ק בֶּן־אַבְרָהָ֑ם אַבְרָהָ֖ם הוֹלִ֥יד אֶת־יִצְחָֽק׃","wĕ⁠ʼé֛lėh ţ̇wòlĕdò֥ţ yiẕĕẖá֖q bėn-ʼabĕráhá֑m ʼabĕráhá֖m hwòli֥yd ʼeţ-yiẕĕẖáֽq׃"],[25,20,"וַ⁠יְהִ֤י יִצְחָק֙ בֶּן־אַרְבָּעִ֣ים שָׁנָ֔ה בְּ⁠קַחְתּ֣⁠וֹ אֶת־רִבְקָ֗ה בַּת־בְּתוּאֵל֙ הָֽ⁠אֲרַמִּ֔י מִ⁠פַּדַּ֖ן אֲרָ֑ם אֲח֛וֹת לָבָ֥ן הָ⁠אֲרַמִּ֖י ל֥⁠וֹ לְ⁠אִשָּֽׁה׃","wa⁠yĕhi֤y yiẕĕẖáq֙ bėn-ʼarĕbá̇ʻi֣ym şá̌ná֔h bĕ̇⁠qaẖĕţ֣̇⁠wò ʼeţ-ribĕqá֗h bȧţ-bĕ̇ţẇʼél֙ hֽá⁠ʼàrami̇֔y mi⁠pȧdȧ֖n ʼàrá֑m ʼàẖ֛wòţ lábá֥n há⁠ʼàrami֖̇y l֥⁠wò lĕ⁠ʼişáֽ̇̌h׃"],[25,21,"וַ⁠יֶּעְתַּ֨ר יִצְחָ֤ק לַֽ⁠יהוָה֙ לְ⁠נֹ֣כַח אִשְׁתּ֔⁠וֹ כִּ֥י עֲקָרָ֖ה הִ֑וא וַ⁠יֵּעָ֤תֶר ל⁠וֹ֙ יְהוָ֔ה וַ⁠תַּ֖הַר רִבְקָ֥ה אִשְׁתּֽ⁠וֹ׃","wa⁠yėʻĕţȧ֨r yiẕĕẖá֤q lֽa⁠yhwáh֙ lĕ⁠nò֣kaẖ ʼişĕ̌ţ̇֔⁠wò ki֥̇y ʻàqárá֖h hi֑wʼ wa⁠yé̇ʻá֤ţer l⁠wò֙ yĕhwá֔h wa⁠ţȧ֖har ribĕqá֥h ʼişĕ̌ţֽ̇⁠wò׃"],[25,22,"וַ⁠יִּתְרֹֽצֲצ֤וּ הַ⁠בָּנִים֙ בְּ⁠קִרְבָּ֔⁠הּ וַ⁠תֹּ֣אמֶר אִם־כֵּ֔ן לָ֥⁠מָּה זֶּ֖ה אָנֹ֑כִי וַ⁠תֵּ֖לֶךְ לִ⁠דְרֹ֥שׁ אֶת־יְהוָֽה׃","wa⁠yi̇ţĕròֽẕàẕ֤ẇ ha⁠bá̇niym֙ bĕ̇⁠qirĕbá̇֔⁠ḣ wa⁠ţò֣̇ʼmer ʼim-ké̇֔n lá֥⁠má̇h zė֖h ʼánò֑kiy wa⁠ţé֖̇lekĕ li⁠dĕrò֥ş̌ ʼeţ-yĕhwáֽh׃"],[25,23,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה לָ֗⁠הּ שְׁנֵ֤י גיים בְּ⁠בִטְנֵ֔⁠ךְ וּ⁠שְׁנֵ֣י לְאֻמִּ֔ים מִ⁠מֵּעַ֖יִ⁠ךְ יִפָּרֵ֑דוּ וּ⁠לְאֹם֙ מִ⁠לְאֹ֣ם יֶֽאֱמָ֔ץ וְ⁠רַ֖ב יַעֲבֹ֥ד צָעִֽיר׃","wa⁠yò̇֨ʼmer yĕhwá֜h lá֗⁠ḣ şĕ̌né֤y gyym bĕ̇⁠bitĕné֔⁠kĕ ẇ⁠şĕ̌né֣y lĕʼumi̇֔ym mi⁠mé̇ʻa֖yi⁠kĕ yipá̇ré֑dẇ ẇ⁠lĕʼòm֙ mi⁠lĕʼò֣m yeֽʼèmá֔ẕ wĕ⁠ra֖b yaʻàbò֥d ẕáʻiֽyr׃"],[25,24,"וַ⁠יִּמְלְא֥וּ יָמֶ֖י⁠הָ לָ⁠לֶ֑דֶת וְ⁠הִנֵּ֥ה תוֹמִ֖ם בְּ⁠בִטְנָֽ⁠הּ׃","wa⁠yi̇mĕlĕʼ֥ẇ yáme֖y⁠há lá⁠le֑deţ wĕ⁠hiné֥̇h ţwòmi֖m bĕ̇⁠bitĕnáֽ⁠ḣ׃"],[25,25,"וַ⁠יֵּצֵ֤א הָ⁠רִאשׁוֹן֙ אַדְמוֹנִ֔י כֻּלּ֖⁠וֹ כְּ⁠אַדֶּ֣רֶת שֵׂעָ֑ר וַ⁠יִּקְרְא֥וּ שְׁמ֖⁠וֹ עֵשָֽׂו׃","wa⁠yé̇ẕé֤ʼ há⁠riʼş̌wòn֙ ʼadĕmwòni֔y ku̇l֖̇⁠wò kĕ̇⁠ʼadė֣reţ şé̂ʻá֑r wa⁠yi̇qĕrĕʼ֥ẇ şĕ̌m֖⁠wò ʻéşáֽ̂w׃"],[25,26,"וְ⁠אַֽחֲרֵי־כֵ֞ן יָצָ֣א אָחִ֗י⁠ו וְ⁠יָד֤⁠וֹ אֹחֶ֨זֶת֙ בַּ⁠עֲקֵ֣ב עֵשָׂ֔ו וַ⁠יִּקְרָ֥א שְׁמ֖⁠וֹ יַעֲקֹ֑ב וְ⁠יִצְחָ֛ק בֶּן־שִׁשִּׁ֥ים שָׁנָ֖ה בְּ⁠לֶ֥דֶת אֹתָֽ⁠ם׃","wĕ⁠ʼaֽẖàréy-ké֞n yáẕá֣ʼ ʼáẖi֗y⁠w wĕ⁠yád֤⁠wò ʼòẖe֨zeţ֙ bȧ⁠ʻàqé֣b ʻéşá̂֔w wa⁠yi̇qĕrá֥ʼ şĕ̌m֖⁠wò yaʻàqò֑b wĕ⁠yiẕĕẖá֛q bėn-şǐşi֥̇̌ym şá̌ná֖h bĕ̇⁠le֥deţ ʼòţáֽ⁠m׃"],[25,27,"וַֽ⁠יִּגְדְּלוּ֙ הַ⁠נְּעָרִ֔ים וַ⁠יְהִ֣י עֵשָׂ֗ו אִ֛ישׁ יֹדֵ֥עַ צַ֖יִד אִ֣ישׁ שָׂדֶ֑ה וְ⁠יַעֲקֹב֙ אִ֣ישׁ תָּ֔ם יֹשֵׁ֖ב אֹהָלִֽים׃","wֽa⁠yi̇gĕdĕ̇lẇ֙ ha⁠nĕ̇ʻári֔ym wa⁠yĕhi֣y ʻéşá̂֗w ʼi֛yş̌ yòdé֥ʻa ẕa֖yid ʼi֣yş̌ şá̂de֑h wĕ⁠yaʻàqòb֙ ʼi֣yş̌ ţá̇֔m yòşé֖̌b ʼòháliֽym׃"],[25,28,"וַ⁠יֶּאֱהַ֥ב יִצְחָ֛ק אֶת־עֵשָׂ֖ו כִּי־צַ֣יִד בְּ⁠פִ֑י⁠ו וְ⁠רִבְקָ֖ה אֹהֶ֥בֶת אֶֽת־יַעֲקֹֽב׃","wa⁠yėʼèha֥b yiẕĕẖá֛q ʼeţ-ʻéşá֖̂w ki̇y-ẕa֣yid bĕ̇⁠pi֑y⁠w wĕ⁠ribĕqá֖h ʼòhe֥beţ ʼeֽţ-yaʻàqòֽb׃"],[25,29,"וַ⁠יָּ֥זֶד יַעֲקֹ֖ב נָזִ֑יד וַ⁠יָּבֹ֥א עֵשָׂ֛ו מִן־הַ⁠שָּׂדֶ֖ה וְ⁠ה֥וּא עָיֵֽף׃","wa⁠yá֥̇zed yaʻàqò֖b názi֑yd wa⁠yá̇bò֥ʼ ʻéşá֛̂w min-ha⁠şá̇̂de֖h wĕ⁠h֥ẇʼ ʻáyéֽp׃"],[25,30,"וַ⁠יֹּ֨אמֶר עֵשָׂ֜ו אֶֽל־יַעֲקֹ֗ב הַלְעִיטֵ֤⁠נִי נָא֙ מִן־הָ⁠אָדֹ֤ם הָ⁠אָדֹם֙ הַ⁠זֶּ֔ה כִּ֥י עָיֵ֖ף אָנֹ֑כִי עַל־כֵּ֥ן קָרָֽא־שְׁמ֖⁠וֹ אֱדֽוֹם׃","wa⁠yò̇֨ʼmer ʻéşá̂֜w ʼeֽl-yaʻàqò֗b halĕʻiyté֤⁠niy náʼ֙ min-há⁠ʼádò֤m há⁠ʼádòm֙ ha⁠zė֔h ki֥̇y ʻáyé֖p ʼánò֑kiy ʻal-ké֥̇n qáráֽʼ-şĕ̌m֖⁠wò ʼèdֽwòm׃"],[25,31,"וַ⁠יֹּ֖אמֶר יַעֲקֹ֑ב מִכְרָ֥⁠ה כַ⁠יּ֛וֹם אֶת־בְּכֹֽרָתְ⁠ךָ֖ לִֽ⁠י׃","wa⁠yò֖̇ʼmer yaʻàqò֑b mikĕrá֥⁠h ka⁠ẏ֛wòm ʼeţ-bĕ̇kòֽráţĕ⁠ká֖ liֽ⁠y׃"],[25,32,"וַ⁠יֹּ֣אמֶר עֵשָׂ֔ו הִנֵּ֛ה אָנֹכִ֥י הוֹלֵ֖ךְ לָ⁠מ֑וּת וְ⁠לָ⁠מָּה־זֶּ֥ה לִ֖⁠י בְּכֹרָֽה׃","wa⁠yò֣̇ʼmer ʻéşá̂֔w hiné֛̇h ʼánòki֥y hwòlé֖kĕ lá⁠m֑ẇţ wĕ⁠lá⁠má̇h-zė֥h li֖⁠y bĕ̇kòráֽh׃"],[25,33,"וַ⁠יֹּ֣אמֶר יַעֲקֹ֗ב הִשָּׁ֤בְעָ⁠ה לִּ⁠י֙ כַּ⁠יּ֔וֹם וַ⁠יִּשָּׁבַ֖ע ל֑⁠וֹ וַ⁠יִּמְכֹּ֥ר אֶת־בְּכֹרָת֖⁠וֹ לְ⁠יַעֲקֹֽב׃","wa⁠yò֣̇ʼmer yaʻàqò֗b hişá֤̇̌bĕʻá⁠h li̇⁠y֙ kȧ⁠ẏ֔wòm wa⁠yi̇şá̇̌ba֖ʻ l֑⁠wò wa⁠yi̇mĕkò֥̇r ʼeţ-bĕ̇kòráţ֖⁠wò lĕ⁠yaʻàqòֽb׃"],[25,34,"וְ⁠יַעֲקֹ֞ב נָתַ֣ן לְ⁠עֵשָׂ֗ו לֶ֚חֶם וּ⁠נְזִ֣יד עֲדָשִׁ֔ים וַ⁠יֹּ֣אכַל וַ⁠יֵּ֔שְׁתְּ וַ⁠יָּ֖קָם וַ⁠יֵּלַ֑ךְ וַ⁠יִּ֥בֶז עֵשָׂ֖ו אֶת־הַ⁠בְּכֹרָֽה׃ס","wĕ⁠yaʻàqò֞b náţa֣n lĕ⁠ʻéşá̂֗w le֚ẖem ẇ⁠nĕzi֣yd ʻàdáşǐ֔ym wa⁠yò֣̇ʼkal wa⁠yé̇֔şĕ̌ţĕ̇ wa⁠yá֖̇qám wa⁠yé̇la֑kĕ wa⁠yi֥̇bez ʻéşá֖̂w ʼeţ-ha⁠bĕ̇kòráֽh׃s"],[26,1,"וַ⁠יְהִ֤י רָעָב֙ בָּ⁠אָ֔רֶץ מִ⁠לְּ⁠בַד֙ הָ⁠רָעָ֣ב הָ⁠רִאשׁ֔וֹן אֲשֶׁ֥ר הָיָ֖ה בִּ⁠ימֵ֣י אַבְרָהָ֑ם וַ⁠יֵּ֧לֶךְ יִצְחָ֛ק אֶל־אֲבִימֶּ֥לֶךְ מֶֽלֶךְ־פְּלִשְׁתִּ֖ים גְּרָֽרָ⁠ה׃","wa⁠yĕhi֤y ráʻáb֙ bá̇⁠ʼá֔reẕ mi⁠lĕ̇⁠bad֙ há⁠ráʻá֣b há⁠riʼş̌֔wòn ʼàşě֥r háyá֖h bi̇⁠ymé֣y ʼabĕráhá֑m wa⁠yé֧̇lekĕ yiẕĕẖá֛q ʼel-ʼàbiymė֥lekĕ meֽlekĕ-pĕ̇lişĕ̌ţi֖̇ym gĕ̇ráֽrá⁠h׃"],[26,2,"וַ⁠יֵּרָ֤א אֵלָי⁠ו֙ יְהוָ֔ה וַ⁠יֹּ֖אמֶר אַל־תֵּרֵ֣ד מִצְרָ֑יְמָ⁠ה שְׁכֹ֣ן בָּ⁠אָ֔רֶץ אֲשֶׁ֖ר אֹמַ֥ר אֵלֶֽי⁠ךָ׃","wa⁠yé̇rá֤ʼ ʼéláy⁠w֙ yĕhwá֔h wa⁠yò֖̇ʼmer ʼal-ţé̇ré֣d miẕĕrá֑yĕmá⁠h şĕ̌kò֣n bá̇⁠ʼá֔reẕ ʼàşě֖r ʼòma֥r ʼéleֽy⁠ká׃"],[26,3,"גּ֚וּר בָּ⁠אָ֣רֶץ הַ⁠זֹּ֔את וְ⁠אֶֽהְיֶ֥ה עִמְּ⁠ךָ֖ וַ⁠אֲבָרְכֶ֑⁠ךָּ כִּֽי־לְ⁠ךָ֣ וּֽ⁠לְ⁠זַרְעֲ⁠ךָ֗ אֶתֵּן֙ אֶת־כָּל־הָֽ⁠אֲרָצֹ֣ת הָ⁠אֵ֔ל וַ⁠הֲקִֽמֹתִי֙ אֶת־הַ⁠שְּׁבֻעָ֔ה אֲשֶׁ֥ר נִשְׁבַּ֖עְתִּי לְ⁠אַבְרָהָ֥ם אָבִֽי⁠ךָ׃","ġ֚ẇr bá̇⁠ʼá֣reẕ ha⁠zò̇֔ʼţ wĕ⁠ʼeֽhĕye֥h ʻimĕ̇⁠ká֖ wa⁠ʼàbárĕke֑⁠ká̇ kiֽ̇y-lĕ⁠ká֣ ẇֽ⁠lĕ⁠zarĕʻà⁠ká֗ ʼeţé̇n֙ ʼeţ-ká̇l-háֽ⁠ʼàráẕò֣ţ há⁠ʼé֔l wa⁠hàqiֽmòţiy֙ ʼeţ-ha⁠şĕ̇̌buʻá֔h ʼàşě֥r nişĕ̌bȧ֖ʻĕţi̇y lĕ⁠ʼabĕráhá֥m ʼábiֽy⁠ká׃"],[26,4,"וְ⁠הִרְבֵּיתִ֤י אֶֽת־זַרְעֲ⁠ךָ֙ כְּ⁠כוֹכְבֵ֣י הַ⁠שָּׁמַ֔יִם וְ⁠נָתַתִּ֣י לְ⁠זַרְעֲ⁠ךָ֔ אֵ֥ת כָּל־הָ⁠אֲרָצֹ֖ת הָ⁠אֵ֑ל וְ⁠הִתְבָּרֲכ֣וּ בְ⁠זַרְעֲ⁠ךָ֔ כֹּ֖ל גּוֹיֵ֥י הָ⁠אָֽרֶץ׃","wĕ⁠hirĕbé̇yţi֤y ʼeֽţ-zarĕʻà⁠ká֙ kĕ̇⁠kwòkĕbé֣y ha⁠şá̇̌ma֔yim wĕ⁠náţaţi֣̇y lĕ⁠zarĕʻà⁠ká֔ ʼé֥ţ ká̇l-há⁠ʼàráẕò֖ţ há⁠ʼé֑l wĕ⁠hiţĕbá̇ràk֣ẇ bĕ⁠zarĕʻà⁠ká֔ kò֖̇l ġwòyé֥y há⁠ʼáֽreẕ׃"],[26,5,"עֵ֕קֶב אֲשֶׁר־שָׁמַ֥ע אַבְרָהָ֖ם בְּ⁠קֹלִ֑⁠י וַ⁠יִּשְׁמֹר֙ מִשְׁמַרְתִּ֔⁠י מִצְוֺתַ֖⁠י חֻקּוֹתַ֥⁠י וְ⁠תוֹרֹתָֽ⁠י׃","ʻé֕qeb ʼàşěr-şá̌ma֥ʻ ʼabĕráhá֖m bĕ̇⁠qòli֑⁠y wa⁠yi̇şĕ̌mòr֙ mişĕ̌marĕţi̇֔⁠y miẕĕwֺţa֖⁠y ẖuq̇wòţa֥⁠y wĕ⁠ţwòròţáֽ⁠y׃"],[26,6,"וַ⁠יֵּ֥שֶׁב יִצְחָ֖ק בִּ⁠גְרָֽר׃","wa⁠yé֥̇şěb yiẕĕẖá֖q bi̇⁠gĕráֽr׃"],[26,7,"וַֽ⁠יִּשְׁאֲל֞וּ אַנְשֵׁ֤י הַ⁠מָּקוֹם֙ לְ⁠אִשְׁתּ֔⁠וֹ וַ⁠יֹּ֖אמֶר אֲחֹ֣תִ⁠י הִ֑וא כִּ֤י יָרֵא֙ לֵ⁠אמֹ֣ר אִשְׁתִּ֔⁠י פֶּן־יַֽהַרְגֻ֜⁠נִי אַנְשֵׁ֤י הַ⁠מָּקוֹם֙ עַל־רִבְקָ֔ה כִּֽי־טוֹבַ֥ת מַרְאֶ֖ה הִֽיא׃","waֽ⁠yi̇şĕ̌ʼàl֞ẇ ʼanĕşé֤̌y ha⁠má̇qwòm֙ lĕ⁠ʼişĕ̌ţ̇֔⁠wò wa⁠yò֖̇ʼmer ʼàẖò֣ţi⁠y hi֑wʼ ki֤̇y yáréʼ֙ lé⁠ʼmò֣r ʼişĕ̌ţi̇֔⁠y pėn-yaֽharĕgu֜⁠niy ʼanĕşé֤̌y ha⁠má̇qwòm֙ ʻal-ribĕqá֔h kiֽ̇y-twòba֥ţ marĕʼe֖h hiֽyʼ׃"],[26,8,"וַ⁠יְהִ֗י כִּ֣י אָֽרְכוּ־ל֥⁠וֹ שָׁם֙ הַ⁠יָּמִ֔ים וַ⁠יַּשְׁקֵ֗ף אֲבִימֶ֨לֶךְ֙ מֶ֣לֶךְ פְּלִשְׁתִּ֔ים בְּעַ֖ד הַֽ⁠חַלּ֑וֹן וַ⁠יַּ֗רְא וְ⁠הִנֵּ֤ה יִצְחָק֙ מְצַחֵ֔ק אֵ֖ת רִבְקָ֥ה אִשְׁתּֽ⁠וֹ׃","wa⁠yĕhi֗y ki֣̇y ʼáֽrĕkẇ-l֥⁠wò şá̌m֙ ha⁠yá̇mi֔ym wa⁠yȧşĕ̌qé֗p ʼàbiyme֨lekĕ֙ me֣lekĕ pĕ̇lişĕ̌ţi̇֔ym bĕ̇ʻa֖d hֽa⁠ẖal֑̇wòn wa⁠yȧ֗rĕʼ wĕ⁠hiné֤̇h yiẕĕẖáq֙ mĕẕaẖé֔q ʼé֖ţ ribĕqá֥h ʼişĕ̌ţֽ̇⁠wò׃"],[26,9,"וַ⁠יִּקְרָ֨א אֲבִימֶ֜לֶךְ לְ⁠יִצְחָ֗ק וַ⁠יֹּ֨אמֶר֙ אַ֣ךְ הִנֵּ֤ה אִשְׁתְּ⁠ךָ֙ הִ֔וא וְ⁠אֵ֥יךְ אָמַ֖רְתָּ אֲחֹ֣תִ⁠י הִ֑וא וַ⁠יֹּ֤אמֶר אֵלָי⁠ו֙ יִצְחָ֔ק כִּ֣י אָמַ֔רְתִּי פֶּן־אָמ֖וּת עָלֶֽי⁠הָ׃","wa⁠yi̇qĕrá֨ʼ ʼàbiyme֜lekĕ lĕ⁠yiẕĕẖá֗q wa⁠yò̇֨ʼmer֙ ʼa֣kĕ hiné֤̇h ʼişĕ̌ţĕ̇⁠ká֙ hi֔wʼ wĕ⁠ʼé֥ykĕ ʼáma֖rĕţá̇ ʼàẖò֣ţi⁠y hi֑wʼ wa⁠yò֤̇ʼmer ʼéláy⁠w֙ yiẕĕẖá֔q ki֣̇y ʼáma֔rĕţi̇y pėn-ʼám֖ẇţ ʻáleֽy⁠há׃"],[26,10,"וַ⁠יֹּ֣אמֶר אֲבִימֶ֔לֶךְ מַה־זֹּ֖את עָשִׂ֣יתָ לָּ֑⁠נוּ כִּ֠⁠מְעַט שָׁכַ֞ב אַחַ֤ד הָ⁠עָם֙ אֶת־אִשְׁתֶּ֔⁠ךָ וְ⁠הֵבֵאתָ֥ עָלֵ֖י⁠נוּ אָשָֽׁם׃","wa⁠yò֣̇ʼmer ʼàbiyme֔lekĕ mah-zò֖̇ʼţ ʻáşî֣yţá lá֑̇⁠nẇ ki̇֠⁠mĕʻat şá̌ka֞b ʼaẖa֤d há⁠ʻám֙ ʼeţ-ʼişĕ̌ţė֔⁠ká wĕ⁠hébéʼţá֥ ʻálé֖y⁠nẇ ʼáşáֽ̌m׃"],[26,11,"וַ⁠יְצַ֣ו אֲבִימֶ֔לֶךְ אֶת־כָּל־הָ⁠עָ֖ם לֵ⁠אמֹ֑ר הַ⁠נֹּגֵ֜עַ בָּ⁠אִ֥ישׁ הַ⁠זֶּ֛ה וּ⁠בְ⁠אִשְׁתּ֖⁠וֹ מ֥וֹת יוּמָֽת׃","wa⁠yĕẕa֣w ʼàbiyme֔lekĕ ʼeţ-ká̇l-há⁠ʻá֖m lé⁠ʼmò֑r ha⁠nò̇gé֜ʻa bá̇⁠ʼi֥yş̌ ha⁠zė֛h ẇ⁠bĕ⁠ʼişĕ̌ţ֖̇⁠wò m֥wòţ yẇmáֽţ׃"],[26,12,"וַ⁠יִּזְרַ֤ע יִצְחָק֙ בָּ⁠אָ֣רֶץ הַ⁠הִ֔וא וַ⁠יִּמְצָ֛א בַּ⁠שָּׁנָ֥ה הַ⁠הִ֖וא מֵאָ֣ה שְׁעָרִ֑ים וַֽ⁠יְבָרֲכֵ֖⁠הוּ יְהוָֽה׃","wa⁠yi̇zĕra֤ʻ yiẕĕẖáq֙ bá̇⁠ʼá֣reẕ ha⁠hi֔wʼ wa⁠yi̇mĕẕá֛ʼ bȧ⁠şá̇̌ná֥h ha⁠hi֖wʼ méʼá֣h şĕ̌ʻári֑ym wֽa⁠yĕbáràké֖⁠hẇ yĕhwáֽh׃"],[26,13,"וַ⁠יִּגְדַּ֖ל הָ⁠אִ֑ישׁ וַ⁠יֵּ֤לֶךְ הָלוֹךְ֙ וְ⁠גָדֵ֔ל עַ֥ד כִּֽי־גָדַ֖ל מְאֹֽד׃","wa⁠yi̇gĕdȧ֖l há⁠ʼi֑yş̌ wa⁠yé֤̇lekĕ hálwòkĕ֙ wĕ⁠gádé֔l ʻa֥d kiֽ̇y-gáda֖l mĕʼòֽd׃"],[26,14,"וַֽ⁠יְהִי־ל֤⁠וֹ מִקְנֵה־צֹאן֙ וּ⁠מִקְנֵ֣ה בָקָ֔ר וַ⁠עֲבֻדָּ֖ה רַבָּ֑ה וַ⁠יְקַנְא֥וּ אֹת֖⁠וֹ פְּלִשְׁתִּֽים׃","wֽa⁠yĕhiy-l֤⁠wò miqĕnéh-ẕòʼn֙ ẇ⁠miqĕné֣h báqá֔r wa⁠ʻàbudá֖̇h rabá֑̇h wa⁠yĕqanĕʼ֥ẇ ʼòţ֖⁠wò pĕ̇lişĕ̌ţiֽ̇ym׃"],[26,15,"וְ⁠כָל־הַ⁠בְּאֵרֹ֗ת אֲשֶׁ֤ר חָֽפְרוּ֙ עַבְדֵ֣י אָבִ֔י⁠ו בִּ⁠ימֵ֖י אַבְרָהָ֣ם אָבִ֑י⁠ו סִתְּמ֣וּ⁠ם פְּלִשְׁתִּ֔ים וַ⁠יְמַלְא֖וּ⁠ם עָפָֽר׃","wĕ⁠kál-ha⁠bĕ̇ʼérò֗ţ ʼàşě֤r ẖáֽpĕrẇ֙ ʻabĕdé֣y ʼábi֔y⁠w bi̇⁠ymé֖y ʼabĕráhá֣m ʼábi֑y⁠w siţĕ̇m֣ẇ⁠m pĕ̇lişĕ̌ţi̇֔ym wa⁠yĕmalĕʼ֖ẇ⁠m ʻápáֽr׃"],[26,16,"וַ⁠יֹּ֥אמֶר אֲבִימֶ֖לֶךְ אֶל־יִצְחָ֑ק לֵ֚ךְ מֵֽ⁠עִמָּ֔⁠נוּ כִּֽי־עָצַֽמְתָּ־מִמֶּ֖⁠נּוּ מְאֹֽד׃","wa⁠yò֥̇ʼmer ʼàbiyme֖lekĕ ʼel-yiẕĕẖá֑q lé֚kĕ mֽé⁠ʻimá̇֔⁠nẇ kiֽ̇y-ʻáẕaֽmĕţá̇-mimė֖⁠ṅẇ mĕʼòֽd׃"],[26,17,"וַ⁠יֵּ֥לֶךְ מִ⁠שָּׁ֖ם יִצְחָ֑ק וַ⁠יִּ֥חַן בְּ⁠נַֽחַל־גְּרָ֖ר וַ⁠יֵּ֥שֶׁב שָֽׁם׃","wa⁠yé֥̇lekĕ mi⁠şá֖̇̌m yiẕĕẖá֑q wa⁠yi֥̇ẖan bĕ̇⁠naֽẖal-gĕ̇rá֖r wa⁠yé֥̇şěb şáֽ̌m׃"],[26,18,"וַ⁠יָּ֨שָׁב יִצְחָ֜ק וַ⁠יַּחְפֹּ֣ר ׀ אֶת־בְּאֵרֹ֣ת הַ⁠מַּ֗יִם אֲשֶׁ֤ר חָֽפְרוּ֙ בִּ⁠ימֵי֙ אַבְרָהָ֣ם אָבִ֔י⁠ו וַ⁠יְסַתְּמ֣וּ⁠ם פְּלִשְׁתִּ֔ים אַחֲרֵ֖י מ֣וֹת אַבְרָהָ֑ם וַ⁠יִּקְרָ֤א לָ⁠הֶן֙ שֵׁמ֔וֹת כַּ⁠שֵּׁמֹ֕ת אֲשֶׁר־קָרָ֥א לָ⁠הֶ֖ן אָבִֽי⁠ו׃","wa⁠yá̇֨şá̌b yiẕĕẖá֜q wa⁠yȧẖĕpò֣̇r ׀ ʼeţ-bĕ̇ʼérò֣ţ ha⁠mȧ֗yim ʼàşě֤r ẖáֽpĕrẇ֙ bi̇⁠yméy֙ ʼabĕráhá֣m ʼábi֔y⁠w wa⁠yĕsaţĕ̇m֣ẇ⁠m pĕ̇lişĕ̌ţi̇֔ym ʼaẖàré֖y m֣wòţ ʼabĕráhá֑m wa⁠yi̇qĕrá֤ʼ lá⁠hen֙ şé̌m֔wòţ kȧ⁠şé̇̌mò֕ţ ʼàşěr-qárá֥ʼ lá⁠he֖n ʼábiֽy⁠w׃"],[26,19,"וַ⁠יַּחְפְּר֥וּ עַבְדֵֽי־יִצְחָ֖ק בַּ⁠נָּ֑חַל וַ⁠יִּ֨מְצְאוּ־שָׁ֔ם בְּאֵ֖ר מַ֥יִם חַיִּֽים׃","wa⁠yȧẖĕpĕ̇r֥ẇ ʻabĕdéֽy-yiẕĕẖá֖q bȧ⁠ná֑̇ẖal wa⁠yi̇֨mĕẕĕʼẇ-şá̌֔m bĕ̇ʼé֖r ma֥yim ẖayiֽ̇ym׃"],[26,20,"וַ⁠יָּרִ֜יבוּ רֹעֵ֣י גְרָ֗ר עִם־רֹעֵ֥י יִצְחָ֛ק לֵ⁠אמֹ֖ר לָ֣⁠נוּ הַ⁠מָּ֑יִם וַ⁠יִּקְרָ֤א שֵֽׁם־הַ⁠בְּאֵר֙ עֵ֔שֶׂק כִּ֥י הִֽתְעַשְּׂק֖וּ עִמּֽ⁠וֹ׃","wa⁠yá̇ri֜ybẇ ròʻé֣y gĕrá֗r ʻim-ròʻé֥y yiẕĕẖá֛q lé⁠ʼmò֖r lá֣⁠nẇ ha⁠má֑̇yim wa⁠yi̇qĕrá֤ʼ şéֽ̌m-ha⁠bĕ̇ʼér֙ ʻé֔şêq ki֥̇y hiֽţĕʻaşĕ̇̂q֖ẇ ʻiṁֽ⁠wò׃"],[26,21,"וַֽ⁠יַּחְפְּרוּ֙ בְּאֵ֣ר אַחֶ֔רֶת וַ⁠יָּרִ֖יבוּ גַּם־עָלֶ֑י⁠הָ וַ⁠יִּקְרָ֥א שְׁמָ֖⁠הּ שִׂטְנָֽה׃","waֽ⁠yȧẖĕpĕ̇rẇ֙ bĕ̇ʼé֣r ʼaẖe֔reţ wa⁠yá̇ri֖ybẇ gȧm-ʻále֑y⁠há wa⁠yi̇qĕrá֥ʼ şĕ̌má֖⁠ḣ şîtĕnáֽh׃"],[26,22,"וַ⁠יַּעְתֵּ֣ק מִ⁠שָּׁ֗ם וַ⁠יַּחְפֹּר֙ בְּאֵ֣ר אַחֶ֔רֶת וְ⁠לֹ֥א רָב֖וּ עָלֶ֑י⁠הָ וַ⁠יִּקְרָ֤א שְׁמָ⁠הּ֙ רְחֹב֔וֹת וַ⁠יֹּ֗אמֶר כִּֽי־עַתָּ֞ה הִרְחִ֧יב יְהוָ֛ה לָ֖⁠נוּ וּ⁠פָרִ֥ינוּ בָ⁠אָֽרֶץ׃","wa⁠yȧʻĕţé֣̇q mi⁠şá̇̌֗m wa⁠yȧẖĕpò̇r֙ bĕ̇ʼé֣r ʼaẖe֔reţ wĕ⁠lò֥ʼ ráb֖ẇ ʻále֑y⁠há wa⁠yi̇qĕrá֤ʼ şĕ̌má⁠ḣ֙ rĕẖòb֔wòţ wa⁠yò̇֗ʼmer kiֽ̇y-ʻaţá̇֞h hirĕẖi֧yb yĕhwá֛h lá֖⁠nẇ ẇ⁠pári֥ynẇ bá⁠ʼáֽreẕ׃"],[26,23,"וַ⁠יַּ֥עַל מִ⁠שָּׁ֖ם בְּאֵ֥ר שָֽׁבַע׃","wa⁠yȧ֥ʻal mi⁠şá֖̇̌m bĕ̇ʼé֥r şáֽ̌baʻ׃"],[26,24,"וַ⁠יֵּרָ֨א אֵלָ֤י⁠ו יְהוָה֙ בַּ⁠לַּ֣יְלָה הַ⁠ה֔וּא וַ⁠יֹּ֕אמֶר אָנֹכִ֕י אֱלֹהֵ֖י אַבְרָהָ֣ם אָבִ֑י⁠ךָ אַל־תִּירָא֙ כִּֽי־אִתְּ⁠ךָ֣ אָנֹ֔כִי וּ⁠בֵֽרַכְתִּ֨י⁠ךָ֙ וְ⁠הִרְבֵּיתִ֣י אֶֽת־זַרְעֲ⁠ךָ֔ בַּ⁠עֲב֖וּר אַבְרָהָ֥ם עַבְדִּֽ⁠י׃","wa⁠yé̇rá֨ʼ ʼélá֤y⁠w yĕhwáh֙ bȧ⁠lȧ֣yĕláh ha⁠h֔ẇʼ wa⁠yò̇֕ʼmer ʼánòki֕y ʼèlòhé֖y ʼabĕráhá֣m ʼábi֑y⁠ká ʼal-ţi̇yráʼ֙ kiֽ̇y-ʼiţĕ̇⁠ká֣ ʼánò֔kiy ẇ⁠béֽrakĕţi̇֨y⁠ká֙ wĕ⁠hirĕbé̇yţi֣y ʼeֽţ-zarĕʻà⁠ká֔ bȧ⁠ʻàb֖ẇr ʼabĕráhá֥m ʻabĕdiֽ̇⁠y׃"],[26,25,"וַ⁠יִּ֧בֶן שָׁ֣ם מִזְבֵּ֗חַ וַ⁠יִּקְרָא֙ בְּ⁠שֵׁ֣ם יְהוָ֔ה וַ⁠יֶּט־שָׁ֖ם אָהֳל֑⁠וֹ וַ⁠יִּכְרוּ־שָׁ֥ם עַבְדֵי־יִצְחָ֖ק בְּאֵֽר׃","wa⁠yi֧̇ben şá֣̌m mizĕbé̇֗ẖa wa⁠yi̇qĕráʼ֙ bĕ̇⁠şé֣̌m yĕhwá֔h wa⁠yėt-şá֖̌m ʼáhol֑⁠wò wa⁠yi̇kĕrẇ-şá֥̌m ʻabĕdéy-yiẕĕẖá֖q bĕ̇ʼéֽr׃"],[26,26,"וַ⁠אֲבִימֶ֕לֶךְ הָלַ֥ךְ אֵלָ֖י⁠ו מִ⁠גְּרָ֑ר וַ⁠אֲחֻזַּת֙ מֵֽרֵעֵ֔⁠הוּ וּ⁠פִיכֹ֖ל שַׂר־צְבָאֽ⁠וֹ׃","wa⁠ʼàbiyme֕lekĕ hála֥kĕ ʼélá֖y⁠w mi⁠gĕ̇rá֑r wa⁠ʼàẖuzȧţ֙ méֽréʻé֔⁠hẇ ẇ⁠piykò֖l şâr-ẕĕbáʼֽ⁠wò׃"],[26,27,"וַ⁠יֹּ֤אמֶר אֲלֵ⁠הֶם֙ יִצְחָ֔ק מַדּ֖וּעַ בָּאתֶ֣ם אֵלָ֑⁠י וְ⁠אַתֶּם֙ שְׂנֵאתֶ֣ם אֹתִ֔⁠י וַ⁠תְּשַׁלְּח֖וּ⁠נִי מֵ⁠אִתְּ⁠כֶֽם׃","wa⁠yò֤̇ʼmer ʼàlé⁠hem֙ yiẕĕẖá֔q maḋ֖ẇʻa bá̇ʼţe֣m ʼélá֑⁠y wĕ⁠ʼaţėm֙ şĕ̂néʼţe֣m ʼòţi֔⁠y wa⁠ţĕ̇şǎlĕ̇ẖ֖ẇ⁠niy mé⁠ʼiţĕ̇⁠keֽm׃"],[26,28,"וַ⁠יֹּאמְר֗וּ רָא֣וֹ רָאִינוּ֮ כִּֽי־הָיָ֣ה יְהוָ֣ה ׀ עִמָּ⁠ךְ֒ וַ⁠נֹּ֗אמֶר תְּהִ֨י נָ֥א אָלָ֛ה בֵּינוֹתֵ֖י⁠נוּ בֵּינֵ֣י⁠נוּ וּ⁠בֵינֶ֑⁠ךָ וְ⁠נִכְרְתָ֥ה בְרִ֖ית עִמָּֽ⁠ךְ׃","wa⁠yò̇ʼmĕr֗ẇ ráʼ֣wò ráʼiynẇ֮ kiֽ̇y-háyá֣h yĕhwá֣h ׀ ʻimá̇⁠kĕ֒ wa⁠nò̇֗ʼmer ţĕ̇hi֨y ná֥ʼ ʼálá֛h bé̇ynwòţé֖y⁠nẇ bé̇yné֣y⁠nẇ ẇ⁠béyne֑⁠ká wĕ⁠nikĕrĕţá֥h bĕri֖yţ ʻimáֽ̇⁠kĕ׃"],[26,29,"אִם־תַּעֲשֵׂ֨ה עִמָּ֜⁠נוּ רָעָ֗ה כַּ⁠אֲשֶׁר֙ לֹ֣א נְגַֽעֲנ֔וּ⁠ךָ וְ⁠כַ⁠אֲשֶׁ֨ר עָשִׂ֤ינוּ עִמְּ⁠ךָ֙ רַק־ט֔וֹב וַ⁠נְּשַׁלֵּֽחֲ⁠ךָ֖ בְּ⁠שָׁל֑וֹם אַתָּ֥ה עַתָּ֖ה בְּר֥וּךְ יְהוָֽה׃","ʼim-ţȧʻàşé̂֨h ʻimá̇֜⁠nẇ ráʻá֗h kȧ⁠ʼàşěr֙ lò֣ʼ nĕgaֽʻàn֔ẇ⁠ká wĕ⁠ka⁠ʼàşě֨r ʻáşî֤ynẇ ʻimĕ̇⁠ká֙ raq-t֔wòb wa⁠nĕ̇şǎléֽ̇ẖà⁠ká֖ bĕ̇⁠şá̌l֑wòm ʼaţá֥̇h ʻaţá֖̇h bĕ̇r֥ẇkĕ yĕhwáֽh׃"],[26,30,"וַ⁠יַּ֤עַשׂ לָ⁠הֶם֙ מִשְׁתֶּ֔ה וַ⁠יֹּאכְל֖וּ וַ⁠יִּשְׁתּֽוּ׃","wa⁠yȧ֤ʻaş̂ lá⁠hem֙ mişĕ̌ţė֔h wa⁠yò̇ʼkĕl֖ẇ wa⁠yi̇şĕ̌ţֽ̇ẇ׃"],[26,31,"וַ⁠יַּשְׁכִּ֣ימוּ בַ⁠בֹּ֔קֶר וַ⁠יִּשָּׁבְע֖וּ אִ֣ישׁ לְ⁠אָחִ֑י⁠ו וַ⁠יְשַׁלְּחֵ֣⁠ם יִצְחָ֔ק וַ⁠יֵּלְכ֥וּ מֵ⁠אִתּ֖⁠וֹ בְּ⁠שָׁלֽוֹם׃","wa⁠yȧşĕ̌ki֣̇ymẇ ba⁠bò̇֔qer wa⁠yi̇şá̇̌bĕʻ֖ẇ ʼi֣yş̌ lĕ⁠ʼáẖi֑y⁠w wa⁠yĕşǎlĕ̇ẖé֣⁠m yiẕĕẖá֔q wa⁠yé̇lĕk֥ẇ mé⁠ʼiţ֖̇⁠wò bĕ̇⁠şá̌lֽwòm׃"],[26,32,"וַ⁠יְהִ֣י ׀ בַּ⁠יּ֣וֹם הַ⁠ה֗וּא וַ⁠יָּבֹ֨אוּ֙ עַבְדֵ֣י יִצְחָ֔ק וַ⁠יַּגִּ֣דוּ ל֔⁠וֹ עַל־אֹד֥וֹת הַ⁠בְּאֵ֖ר אֲשֶׁ֣ר חָפָ֑רוּ וַ⁠יֹּ֥אמְרוּ ל֖⁠וֹ מָצָ֥אנוּ מָֽיִם׃","wa⁠yĕhi֣y ׀ bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ wa⁠yá̇bò֨ʼẇ֙ ʻabĕdé֣y yiẕĕẖá֔q wa⁠yȧgi֣̇dẇ l֔⁠wò ʻal-ʼòd֥wòţ ha⁠bĕ̇ʼé֖r ʼàşě֣r ẖápá֑rẇ wa⁠yò֥̇ʼmĕrẇ l֖⁠wò máẕá֥ʼnẇ máֽyim׃"],[26,33,"וַ⁠יִּקְרָ֥א אֹתָ֖⁠הּ שִׁבְעָ֑ה עַל־כֵּ֤ן שֵׁם־הָ⁠עִיר֙ בְּאֵ֣ר שֶׁ֔בַע עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃ס","wa⁠yi̇qĕrá֥ʼ ʼòţá֖⁠ḣ şǐbĕʻá֑h ʻal-ké֤̇n şé̌m-há⁠ʻiyr֙ bĕ̇ʼé֣r şě֔baʻ ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃s"],[26,34,"וַ⁠יְהִ֤י עֵשָׂו֙ בֶּן־אַרְבָּעִ֣ים שָׁנָ֔ה וַ⁠יִּקַּ֤ח אִשָּׁה֙ אֶת־יְהוּדִ֔ית בַּת־בְּאֵרִ֖י הַֽ⁠חִתִּ֑י וְ⁠אֶת־בָּ֣שְׂמַ֔ת בַּת־אֵילֹ֖ן הַֽ⁠חִתִּֽי׃","wa⁠yĕhi֤y ʻéşá̂w֙ bėn-ʼarĕbá̇ʻi֣ym şá̌ná֔h wa⁠yi̇qȧ֤ẖ ʼişá̇̌h֙ ʼeţ-yĕhẇdi֔yţ bȧţ-bĕ̇ʼéri֖y haֽ⁠ẖiţi֑̇y wĕ⁠ʼeţ-bá֣̇şĕ̂ma֔ţ bȧţ-ʼéylò֖n hֽa⁠ẖiţiֽ̇y׃"],[26,35,"וַ⁠תִּהְיֶ֖יןָ מֹ֣רַת ר֑וּחַ לְ⁠יִצְחָ֖ק וּ⁠לְ⁠רִבְקָֽה׃ס","wa⁠ţi̇hĕye֖yná mò֣raţ r֑ẇẖa lĕ⁠yiẕĕẖá֖q ẇ⁠lĕ⁠ribĕqáֽh׃s"],[27,1,"וַ⁠יְהִי֙ כִּֽי־זָקֵ֣ן יִצְחָ֔ק וַ⁠תִּכְהֶ֥יןָ עֵינָ֖י⁠ו מֵ⁠רְאֹ֑ת וַ⁠יִּקְרָ֞א אֶת־עֵשָׂ֣ו ׀ בְּנ֣⁠וֹ הַ⁠גָּדֹ֗ל וַ⁠יֹּ֤אמֶר אֵלָי⁠ו֙ בְּנִ֔⁠י וַ⁠יֹּ֥אמֶר אֵלָ֖י⁠ו הִנֵּֽנִ⁠י׃","wa⁠yĕhiy֙ kiֽ̇y-záqé֣n yiẕĕẖá֔q wa⁠ţi̇kĕhe֥yná ʻéyná֖y⁠w mé⁠rĕʼò֑ţ wa⁠yi̇qĕrá֞ʼ ʼeţ-ʻéşá֣̂w ׀ bĕ̇n֣⁠wò ha⁠gá̇dò֗l wa⁠yò֤̇ʼmer ʼéláy⁠w֙ bĕ̇ni֔⁠y wa⁠yò֥̇ʼmer ʼélá֖y⁠w hinéֽ̇ni⁠y׃"],[27,2,"וַ⁠יֹּ֕אמֶר הִנֵּה־נָ֖א זָקַ֑נְתִּי לֹ֥א יָדַ֖עְתִּי י֥וֹם מוֹתִֽ⁠י׃","wa⁠yò̇֕ʼmer hiné̇h-ná֖ʼ záqa֑nĕţi̇y lò֥ʼ yáda֖ʻĕţi̇y y֥wòm mwòţiֽ⁠y׃"],[27,3,"וְ⁠עַתָּה֙ שָׂא־נָ֣א כֵלֶ֔י⁠ךָ תֶּלְיְ⁠ךָ֖ וְ⁠קַשְׁתֶּ֑⁠ךָ וְ⁠צֵא֙ הַ⁠שָּׂדֶ֔ה וְ⁠צ֥וּדָ⁠ה לִּ֖⁠י צידה׃","wĕ⁠ʻaţá̇h֙ şá̂ʼ-ná֣ʼ kéle֔y⁠ká ţėlĕyĕ⁠ká֖ wĕ⁠qaşĕ̌ţė֑⁠ká wĕ⁠ẕéʼ֙ ha⁠şá̇̂de֔h wĕ⁠ẕ֥ẇdá⁠h li֖̇⁠y ẕydh׃"],[27,4,"וַ⁠עֲשֵׂה־לִ֨⁠י מַטְעַמִּ֜ים כַּ⁠אֲשֶׁ֥ר אָהַ֛בְתִּי וְ⁠הָבִ֥יאָ⁠ה לִּ֖⁠י וְ⁠אֹכֵ֑לָה בַּ⁠עֲב֛וּר תְּבָרֶכְ⁠ךָ֥ נַפְשִׁ֖⁠י בְּ⁠טֶ֥רֶם אָמֽוּת׃","wa⁠ʻàşé̂h-li֨⁠y matĕʻami̇֜ym kȧ⁠ʼàşě֥r ʼáha֛bĕţi̇y wĕ⁠hábi֥yʼá⁠h li֖̇⁠y wĕ⁠ʼòké֑láh bȧ⁠ʻàb֛ẇr ţĕ̇bárekĕ⁠ká֥ napĕşǐ֖⁠y bĕ̇⁠te֥rem ʼámֽẇţ׃"],[27,5,"וְ⁠רִבְקָ֣ה שֹׁמַ֔עַת בְּ⁠דַבֵּ֣ר יִצְחָ֔ק אֶל־עֵשָׂ֖ו בְּנ֑⁠וֹ וַ⁠יֵּ֤לֶךְ עֵשָׂו֙ הַ⁠שָּׂדֶ֔ה לָ⁠צ֥וּד צַ֖יִד לְ⁠הָבִֽיא׃","wĕ⁠ribĕqá֣h şò̌ma֔ʻaţ bĕ̇⁠dabé֣̇r yiẕĕẖá֔q ʼel-ʻéşá֖̂w bĕ̇n֑⁠wò wa⁠yé֤̇lekĕ ʻéşá̂w֙ ha⁠şá̇̂de֔h lá⁠ẕ֥ẇd ẕa֖yid lĕ⁠hábiֽyʼ׃"],[27,6,"וְ⁠רִבְקָה֙ אָֽמְרָ֔ה אֶל־יַעֲקֹ֥ב בְּנָ֖⁠הּ לֵ⁠אמֹ֑ר הִנֵּ֤ה שָׁמַ֨עְתִּי֙ אֶת־אָבִ֔י⁠ךָ מְדַבֵּ֛ר אֶל־עֵשָׂ֥ו אָחִ֖י⁠ךָ לֵ⁠אמֹֽר׃","wĕ⁠ribĕqáh֙ ʼáֽmĕrá֔h ʼel-yaʻàqò֥b bĕ̇ná֖⁠ḣ lé⁠ʼmò֑r hiné֤̇h şá̌ma֨ʻĕţi̇y֙ ʼeţ-ʼábi֔y⁠ká mĕdabé֛̇r ʼel-ʻéşá֥̂w ʼáẖi֖y⁠ká lé⁠ʼmòֽr׃"],[27,7,"הָבִ֨יאָ⁠ה לִּ֥⁠י צַ֛יִד וַ⁠עֲשֵׂה־לִ֥⁠י מַטְעַמִּ֖ים וְ⁠אֹכֵ֑לָה וַ⁠אֲבָרֶכְ⁠כָ֛ה לִ⁠פְנֵ֥י יְהוָ֖ה לִ⁠פְנֵ֥י מוֹתִֽ⁠י׃","hábi֨yʼá⁠h li֥̇⁠y ẕa֛yid wa⁠ʻàşé̂h-li֥⁠y matĕʻami֖̇ym wĕ⁠ʼòké֑láh wa⁠ʼàbárekĕ⁠ká֛h li⁠pĕné֥y yĕhwá֖h li⁠pĕné֥y mwòţiֽ⁠y׃"],[27,8,"וְ⁠עַתָּ֥ה בְנִ֖⁠י שְׁמַ֣ע בְּ⁠קֹלִ֑⁠י לַ⁠אֲשֶׁ֥ר אֲנִ֖י מְצַוָּ֥ה אֹתָֽ⁠ךְ׃","wĕ⁠ʻaţá֥̇h bĕni֖⁠y şĕ̌ma֣ʻ bĕ̇⁠qòli֑⁠y la⁠ʼàşě֥r ʼàni֖y mĕẕawá֥̇h ʼòţáֽ⁠kĕ׃"],[27,9,"לֶךְ־נָא֙ אֶל־הַ⁠צֹּ֔אן וְ⁠קַֽח־לִ֣⁠י מִ⁠שָּׁ֗ם שְׁנֵ֛י גְּדָיֵ֥י עִזִּ֖ים טֹבִ֑ים וְ⁠אֶֽעֱשֶׂ֨ה אֹתָ֧⁠ם מַטְעַמִּ֛ים לְ⁠אָבִ֖י⁠ךָ כַּ⁠אֲשֶׁ֥ר אָהֵֽב׃","lekĕ-náʼ֙ ʼel-ha⁠ẕò̇֔ʼn wĕ⁠qaֽẖ-li֣⁠y mi⁠şá̇̌֗m şĕ̌né֛y gĕ̇dáyé֥y ʻizi֖̇ym tòbi֑ym wĕ⁠ʼֽeʻèşê֨h ʼòţá֧⁠m matĕʻami֛̇ym lĕ⁠ʼábi֖y⁠ká kȧ⁠ʼàşě֥r ʼáhéֽb׃"],[27,10,"וְ⁠הֵבֵאתָ֥ לְ⁠אָבִ֖י⁠ךָ וְ⁠אָכָ֑ל בַּ⁠עֲבֻ֛ר אֲשֶׁ֥ר יְבָרֶכְ⁠ךָ֖ לִ⁠פְנֵ֥י מוֹתֽ⁠וֹ׃","wĕ⁠hébéʼţá֥ lĕ⁠ʼábi֖y⁠ká wĕ⁠ʼáká֑l bȧ⁠ʻàbu֛r ʼàşě֥r yĕbárekĕ⁠ká֖ li⁠pĕné֥y mwòţֽ⁠wò׃"],[27,11,"וַ⁠יֹּ֣אמֶר יַעֲקֹ֔ב אֶל־רִבְקָ֖ה אִמּ֑⁠וֹ הֵ֣ן עֵשָׂ֤ו אָחִ⁠י֙ אִ֣ישׁ שָׂעִ֔ר וְ⁠אָנֹכִ֖י אִ֥ישׁ חָלָֽק׃","wa⁠yò֣̇ʼmer yaʻàqò֔b ʼel-ribĕqá֖h ʼiṁ֑⁠wò hé֣n ʻéşá֤̂w ʼáẖi⁠y֙ ʼi֣yş̌ şá̂ʻi֔r wĕ⁠ʼánòki֖y ʼi֥yş̌ ẖáláֽq׃"],[27,12,"אוּלַ֤י יְמֻשֵּׁ֨⁠נִי֙ אָבִ֔⁠י וְ⁠הָיִ֥יתִי בְ⁠עֵינָ֖י⁠ו כִּ⁠מְתַעְתֵּ֑עַ וְ⁠הֵבֵאתִ֥י עָלַ֛⁠י קְלָלָ֖ה וְ⁠לֹ֥א בְרָכָֽה׃","ʼẇla֤y yĕmuşé̇̌֨⁠niy֙ ʼábi֔⁠y wĕ⁠háyi֥yţiy bĕ⁠ʻéyná֖y⁠w ki̇⁠mĕţaʻĕţé֑̇ʻa wĕ⁠hébéʼţi֥y ʻála֛⁠y qĕlálá֖h wĕ⁠lò֥ʼ bĕrákáֽh׃"],[27,13,"וַ⁠תֹּ֤אמֶר ל⁠וֹ֙ אִמּ֔⁠וֹ עָלַ֥⁠י קִלְלָתְ⁠ךָ֖ בְּנִ֑⁠י אַ֛ךְ שְׁמַ֥ע בְּ⁠קֹלִ֖⁠י וְ⁠לֵ֥ךְ קַֽח־לִֽ⁠י׃","wa⁠ţò֤̇ʼmer l⁠wò֙ ʼiṁ֔⁠wò ʻála֥⁠y qilĕláţĕ⁠ká֖ bĕ̇ni֑⁠y ʼa֛kĕ şĕ̌ma֥ʻ bĕ̇⁠qòli֖⁠y wĕ⁠lé֥kĕ qaֽẖ-liֽ⁠y׃"],[27,14,"וַ⁠יֵּ֨לֶךְ֙ וַ⁠יִּקַּ֔ח וַ⁠יָּבֵ֖א לְ⁠אִמּ֑⁠וֹ וַ⁠תַּ֤עַשׂ אִמּ⁠וֹ֙ מַטְעַמִּ֔ים כַּ⁠אֲשֶׁ֖ר אָהֵ֥ב אָבִֽי⁠ו׃","wa⁠yé̇֨lekĕ֙ wa⁠yi̇qȧ֔ẖ wa⁠yá̇bé֖ʼ lĕ⁠ʼiṁ֑⁠wò wa⁠ţȧ֤ʻaş̂ ʼiṁ⁠wò֙ matĕʻami̇֔ym kȧ⁠ʼàşě֖r ʼáhé֥b ʼábiֽy⁠w׃"],[27,15,"וַ⁠תִּקַּ֣ח רִ֠בְקָה אֶת־בִּגְדֵ֨י עֵשָׂ֜ו בְּנָ֤⁠הּ הַ⁠גָּדֹל֙ הַ⁠חֲמֻדֹ֔ת אֲשֶׁ֥ר אִתָּ֖⁠הּ בַּ⁠בָּ֑יִת וַ⁠תַּלְבֵּ֥שׁ אֶֽת־יַעֲקֹ֖ב בְּנָ֥⁠הּ הַ⁠קָּטָֽן׃","wa⁠ţi̇qȧ֣ẖ ri֠bĕqáh ʼeţ-bi̇gĕdé֨y ʻéşá̂֜w bĕ̇ná֤⁠ḣ ha⁠gá̇dòl֙ ha⁠ẖàmudò֔ţ ʼàşě֥r ʼiţá֖̇⁠ḣ bȧ⁠bá֑̇yiţ wa⁠ţȧlĕbé֥̇ş̌ ʼeֽţ-yaʻàqò֖b bĕ̇ná֥⁠ḣ ha⁠qá̇táֽn׃"],[27,16,"וְ⁠אֵ֗ת עֹרֹת֙ גְּדָיֵ֣י הָֽ⁠עִזִּ֔ים הִלְבִּ֖ישָׁה עַל־יָדָ֑י⁠ו וְ⁠עַ֖ל חֶלְקַ֥ת צַוָּארָֽי⁠ו׃","wĕ⁠ʼé֗ţ ʻòròţ֙ gĕ̇dáyé֣y háֽ⁠ʻizi̇֔ym hilĕbi֖̇yşá̌h ʻal-yádá֑y⁠w wĕ⁠ʻa֖l ẖelĕqa֥ţ ẕawá̇ʼráֽy⁠w׃"],[27,17,"וַ⁠תִּתֵּ֧ן אֶת־הַ⁠מַּטְעַמִּ֛ים וְ⁠אֶת־הַ⁠לֶּ֖חֶם אֲשֶׁ֣ר עָשָׂ֑תָה בְּ⁠יַ֖ד יַעֲקֹ֥ב בְּנָֽ⁠הּ׃","wa⁠ţi̇ţé֧̇n ʼeţ-ha⁠mȧtĕʻami֛̇ym wĕ⁠ʼeţ-ha⁠lė֖ẖem ʼàşě֣r ʻáşá֑̂ţáh bĕ̇⁠ya֖d yaʻàqò֥b bĕ̇náֽ⁠ḣ׃"],[27,18,"וַ⁠יָּבֹ֥א אֶל־אָבִ֖י⁠ו וַ⁠יֹּ֣אמֶר אָבִ֑⁠י וַ⁠יֹּ֣אמֶר הִנֶּ֔נִּ⁠י מִ֥י אַתָּ֖ה בְּנִֽ⁠י׃","wa⁠yá̇bò֥ʼ ʼel-ʼábi֖y⁠w wa⁠yò֣̇ʼmer ʼábi֑⁠y wa⁠yò֣̇ʼmer hinė֔ni̇⁠y mi֥y ʼaţá֖̇h bĕ̇niֽ⁠y׃"],[27,19,"וַ⁠יֹּ֨אמֶר יַעֲקֹ֜ב אֶל־אָבִ֗י⁠ו אָנֹכִי֙ עֵשָׂ֣ו בְּכֹרֶ֔⁠ךָ עָשִׂ֕יתִי כַּ⁠אֲשֶׁ֥ר דִּבַּ֖רְתָּ אֵלָ֑⁠י קֽוּם־נָ֣א שְׁבָ֗⁠ה וְ⁠אָכְלָ⁠ה֙ מִ⁠צֵּידִ֔⁠י בַּ⁠עֲב֖וּר תְּבָרֲכַ֥⁠נִּי נַפְשֶֽׁ⁠ךָ׃","wa⁠yò̇֨ʼmer yaʻàqò֜b ʼel-ʼábi֗y⁠w ʼánòkiy֙ ʻéşá֣̂w bĕ̇kòre֔⁠ká ʻáşî֕yţiy kȧ⁠ʼàşě֥r di̇bȧ֖rĕţá̇ ʼélá֑⁠y qֽẇm-ná֣ʼ şĕ̌bá֗⁠h wĕ⁠ʼákĕlá⁠h֙ mi⁠ẕé̇ydi֔⁠y bȧ⁠ʻàb֖ẇr ţĕ̇báràka֥⁠ni̇y napĕşěֽ⁠ká׃"],[27,20,"וַ⁠יֹּ֤אמֶר יִצְחָק֙ אֶל־בְּנ֔⁠וֹ מַה־זֶּ֛ה מִהַ֥רְתָּ לִ⁠מְצֹ֖א בְּנִ֑⁠י וַ⁠יֹּ֕אמֶר כִּ֥י הִקְרָ֛ה יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ לְ⁠פָנָֽ⁠י׃","wa⁠yò֤̇ʼmer yiẕĕẖáq֙ ʼel-bĕ̇n֔⁠wò mah-zė֛h miha֥rĕţá̇ li⁠mĕẕò֖ʼ bĕ̇ni֑⁠y wa⁠yò̇֕ʼmer ki֥̇y hiqĕrá֛h yĕhwá֥h ʼèlòhe֖y⁠ká lĕ⁠pánáֽ⁠y׃"],[27,21,"וַ⁠יֹּ֤אמֶר יִצְחָק֙ אֶֽל־יַעֲקֹ֔ב גְּשָׁ⁠ה־נָּ֥א וַ⁠אֲמֻֽשְׁ⁠ךָ֖ בְּנִ֑⁠י הַֽ⁠אַתָּ֥ה זֶ֛ה בְּנִ֥⁠י עֵשָׂ֖ו אִם־לֹֽא׃","wa⁠yò֤̇ʼmer yiẕĕẖáq֙ ʼeֽl-yaʻàqò֔b gĕ̇şá̌⁠h-ná֥̇ʼ wa⁠ʼàmuֽşĕ̌⁠ká֖ bĕ̇ni֑⁠y haֽ⁠ʼaţá֥̇h ze֛h bĕ̇ni֥⁠y ʻéşá֖̂w ʼim-lòֽʼ׃"],[27,22,"וַ⁠יִּגַּ֧שׁ יַעֲקֹ֛ב אֶל־יִצְחָ֥ק אָבִ֖י⁠ו וַ⁠יְמֻשֵּׁ֑⁠הוּ וַ⁠יֹּ֗אמֶר הַ⁠קֹּל֙ ק֣וֹל יַעֲקֹ֔ב וְ⁠הַ⁠יָּדַ֖יִם יְדֵ֥י עֵשָֽׂו׃","wa⁠yi̇gȧ֧ş̌ yaʻàqò֛b ʼel-yiẕĕẖá֥q ʼábi֖y⁠w wa⁠yĕmuşé֑̇̌⁠hẇ wa⁠yò̇֗ʼmer ha⁠qò̇l֙ q֣wòl yaʻàqò֔b wĕ⁠ha⁠yá̇da֖yim yĕdé֥y ʻéşáֽ̂w׃"],[27,23,"וְ⁠לֹ֣א הִכִּיר֔⁠וֹ כִּֽי־הָי֣וּ יָדָ֗י⁠ו כִּ⁠ידֵ֛י עֵשָׂ֥ו אָחִ֖י⁠ו שְׂעִרֹ֑ת וַֽ⁠יְבָרְכֵֽ⁠הוּ׃","wĕ⁠lò֣ʼ hiki̇yr֔⁠wò kiֽ̇y-háy֣ẇ yádá֗y⁠w ki̇⁠ydé֛y ʻéşá֥̂w ʼáẖi֖y⁠w şĕ̂ʻirò֑ţ waֽ⁠yĕbárĕkéֽ⁠hẇ׃"],[27,24,"וַ⁠יֹּ֕אמֶר אַתָּ֥ה זֶ֖ה בְּנִ֣⁠י עֵשָׂ֑ו וַ⁠יֹּ֖אמֶר אָֽנִי׃","wa⁠yò̇֕ʼmer ʼaţá֥̇h ze֖h bĕ̇ni֣⁠y ʻéşá֑̂w wa⁠yò֖̇ʼmer ʼáֽniy׃"],[27,25,"וַ⁠יֹּ֗אמֶר הַגִּ֤שָׁ⁠ה לִּ⁠י֙ וְ⁠אֹֽכְלָה֙ מִ⁠צֵּ֣יד בְּנִ֔⁠י לְמַ֥עַן תְּבָֽרֶכְ⁠ךָ֖ נַפְשִׁ֑⁠י וַ⁠יַּגֶּשׁ־ל⁠וֹ֙ וַ⁠יֹּאכַ֔ל וַ⁠יָּ֧בֵא ל֦⁠וֹ יַ֖יִן וַ⁠יֵּֽשְׁתְּ׃","wa⁠yò̇֗ʼmer hagi֤̇şá̌⁠h li̇⁠y֙ wĕ⁠ʼòֽkĕláh֙ mi⁠ẕé֣̇yd bĕ̇ni֔⁠y lĕma֥ʻan ţĕ̇báֽrekĕ⁠ká֖ napĕşǐ֑⁠y wa⁠yȧgėş̌-l⁠wò֙ wa⁠yò̇ʼka֔l wa⁠yá֧̇béʼ l֦⁠wò ya֖yin wa⁠yéֽ̇şĕ̌ţĕ̇׃"],[27,26,"וַ⁠יֹּ֥אמֶר אֵלָ֖י⁠ו יִצְחָ֣ק אָבִ֑י⁠ו גְּשָׁ⁠ה־נָּ֥א וּ⁠שְׁקָ⁠ה־לִּ֖⁠י בְּנִֽ⁠י׃","wa⁠yò֥̇ʼmer ʼélá֖y⁠w yiẕĕẖá֣q ʼábi֑y⁠w gĕ̇şá̌⁠h-ná֥̇ʼ ẇ⁠şĕ̌qá⁠h-li֖̇⁠y bĕ̇niֽ⁠y׃"],[27,27,"וַ⁠יִּגַּשׁ֙ וַ⁠יִּשַּׁק־ל֔⁠וֹ וַ⁠יָּ֛רַח אֶת־רֵ֥יחַ בְּגָדָ֖י⁠ו וַֽ⁠יְבָרֲכֵ֑⁠הוּ וַ⁠יֹּ֗אמֶר רְאֵה֙ רֵ֣יחַ בְּנִ֔⁠י כְּ⁠רֵ֣יחַ שָׂדֶ֔ה אֲשֶׁ֥ר בֵּרֲכ֖⁠וֹ יְהוָֽה׃","wa⁠yi̇gȧş̌֙ wa⁠yi̇şȧ̌q-l֔⁠wò wa⁠yá֛̇raẖ ʼeţ-ré֥yẖa bĕ̇gádá֖y⁠w wֽa⁠yĕbáràké֑⁠hẇ wa⁠yò̇֗ʼmer rĕʼéh֙ ré֣yẖa bĕ̇ni֔⁠y kĕ̇⁠ré֣yẖa şá̂de֔h ʼàşě֥r bé̇ràk֖⁠wò yĕhwáֽh׃"],[27,28,"וְ⁠יִֽתֶּן־לְ⁠ךָ֙ הָ⁠אֱלֹהִ֔ים מִ⁠טַּל֙ הַ⁠שָּׁמַ֔יִם וּ⁠מִ⁠שְׁמַנֵּ֖י הָ⁠אָ֑רֶץ וְ⁠רֹ֥ב דָּגָ֖ן וְ⁠תִירֹֽשׁ׃","wĕ⁠yiֽţėn-lĕ⁠ká֙ há⁠ʼèlòhi֔ym mi⁠tȧl֙ ha⁠şá̇̌ma֔yim ẇ⁠mi⁠şĕ̌mané֖̇y há⁠ʼá֑reẕ wĕ⁠rò֥b dá̇gá֖n wĕ⁠ţiyròֽş̌׃"],[27,29,"יַֽעַבְד֣וּ⁠ךָ עַמִּ֗ים ו⁠ישתחו לְ⁠ךָ֙ לְאֻמִּ֔ים הֱוֵ֤ה גְבִיר֙ לְ⁠אַחֶ֔י⁠ךָ וְ⁠יִשְׁתַּחֲוּ֥וּ לְ⁠ךָ֖ בְּנֵ֣י אִמֶּ֑⁠ךָ אֹרְרֶ֣י⁠ךָ אָר֔וּר וּֽ⁠מְבָרֲכֶ֖י⁠ךָ בָּרֽוּךְ׃","yֽaʻabĕd֣ẇ⁠ká ʻami̇֗ym w⁠yşţẖw lĕ⁠ká֙ lĕʼumi̇֔ym hèwé֤h gĕbiyr֙ lĕ⁠ʼaẖe֔y⁠ká wĕ⁠yişĕ̌ţȧẖàẇ֥ẇ lĕ⁠ká֖ bĕ̇né֣y ʼimė֑⁠ká ʼòrĕre֣y⁠ká ʼár֔ẇr ẇֽ⁠mĕbáràke֖y⁠ká bá̇rֽẇkĕ׃"],[27,30,"וַ⁠יְהִ֗י כַּ⁠אֲשֶׁ֨ר כִּלָּ֣ה יִצְחָק֮ לְ⁠בָרֵ֣ךְ אֶֽת־יַעֲקֹב֒ וַ⁠יְהִ֗י אַ֣ךְ יָצֹ֤א יָצָא֙ יַעֲקֹ֔ב מֵ⁠אֵ֥ת פְּנֵ֖י יִצְחָ֣ק אָבִ֑י⁠ו וְ⁠עֵשָׂ֣ו אָחִ֔י⁠ו בָּ֖א מִ⁠צֵּידֽ⁠וֹ׃","wa⁠yĕhi֗y kȧ⁠ʼàşě֨r ki̇lá֣̇h yiẕĕẖáq֮ lĕ⁠báré֣kĕ ʼeֽţ-yaʻàqòb֒ wa⁠yĕhi֗y ʼa֣kĕ yáẕò֤ʼ yáẕáʼ֙ yaʻàqò֔b mé⁠ʼé֥ţ pĕ̇né֖y yiẕĕẖá֣q ʼábi֑y⁠w wĕ⁠ʻéşá֣̂w ʼáẖi֔y⁠w bá֖̇ʼ mi⁠ẕé̇ydֽ⁠wò׃"],[27,31,"וַ⁠יַּ֤עַשׂ גַּם־הוּא֙ מַטְעַמִּ֔ים וַ⁠יָּבֵ֖א לְ⁠אָבִ֑י⁠ו וַ⁠יֹּ֣אמֶר לְ⁠אָבִ֗י⁠ו יָקֻ֤ם אָבִ⁠י֙ וְ⁠יֹאכַל֙ מִ⁠צֵּ֣יד בְּנ֔⁠וֹ בַּ⁠עֲב֖וּר תְּבָרֲכַ֥⁠נִּי נַפְשֶֽׁ⁠ךָ׃","wa⁠yȧ֤ʻaş̂ gȧm-hẇʼ֙ matĕʻami̇֔ym wa⁠yá̇bé֖ʼ lĕ⁠ʼábi֑y⁠w wa⁠yò֣̇ʼmer lĕ⁠ʼábi֗y⁠w yáqu֤m ʼábi⁠y֙ wĕ⁠yòʼkal֙ mi⁠ẕé֣̇yd bĕ̇n֔⁠wò bȧ⁠ʻàb֖ẇr ţĕ̇báràka֥⁠ni̇y napĕşěֽ⁠ká׃"],[27,32,"וַ⁠יֹּ֥אמֶר ל֛⁠וֹ יִצְחָ֥ק אָבִ֖י⁠ו מִי־אָ֑תָּה וַ⁠יֹּ֕אמֶר אֲנִ֛י בִּנְ⁠ךָ֥ בְכֹֽרְ⁠ךָ֖ עֵשָֽׂו׃","wa⁠yò֥̇ʼmer l֛⁠wò yiẕĕẖá֥q ʼábi֖y⁠w miy-ʼá֑ţá̇h wa⁠yò̇֕ʼmer ʼàni֛y bi̇nĕ⁠ká֥ bĕkòֽrĕ⁠ká֖ ʻéşáֽ̂w׃"],[27,33,"וַ⁠יֶּחֱרַ֨ד יִצְחָ֣ק חֲרָדָה֮ גְּדֹלָ֣ה עַד־מְאֹד֒ וַ⁠יֹּ֡אמֶר מִֽי־אֵפ֡וֹא ה֣וּא הַ⁠צָּֽד־צַיִד֩ וַ⁠יָּ֨בֵא לִ֜⁠י וָ⁠אֹכַ֥ל מִ⁠כֹּ֛ל בְּ⁠טֶ֥רֶם תָּב֖וֹא וָ⁠אֲבָרֲכֵ֑⁠הוּ גַּם־בָּר֖וּךְ יִהְיֶֽה׃","wa⁠yėẖèra֨d yiẕĕẖá֣q ẖàrádáh֮ gĕ̇dòlá֣h ʻad-mĕʼòd֒ wa⁠yò̇֡ʼmer miֽy-ʼép֡wòʼ h֣ẇʼ ha⁠ẕáֽ̇d-ẕayid֩ wa⁠yá̇֨béʼ li֜⁠y wá⁠ʼòka֥l mi⁠kò֛̇l bĕ̇⁠te֥rem ţá̇b֖wòʼ wá⁠ʼàbáràké֑⁠hẇ gȧm-bá̇r֖ẇkĕ yihĕyeֽh׃"],[27,34,"כִּ⁠שְׁמֹ֤עַ עֵשָׂו֙ אֶת־דִּבְרֵ֣י אָבִ֔י⁠ו וַ⁠יִּצְעַ֣ק צְעָקָ֔ה גְּדֹלָ֥ה וּ⁠מָרָ֖ה עַד־מְאֹ֑ד וַ⁠יֹּ֣אמֶר לְ⁠אָבִ֔י⁠ו בָּרֲכֵ֥⁠נִי גַם־אָ֖נִי אָבִֽ⁠י׃","ki̇⁠şĕ̌mò֤ʻa ʻéşá̂w֙ ʼeţ-di̇bĕré֣y ʼábi֔y⁠w wa⁠yi̇ẕĕʻa֣q ẕĕʻáqá֔h gĕ̇dòlá֥h ẇ⁠márá֖h ʻad-mĕʼò֑d wa⁠yò֣̇ʼmer lĕ⁠ʼábi֔y⁠w bá̇ràké֥⁠niy gam-ʼá֖niy ʼábiֽ⁠y׃"],[27,35,"וַ⁠יֹּ֕אמֶר בָּ֥א אָחִ֖י⁠ךָ בְּ⁠מִרְמָ֑ה וַ⁠יִּקַּ֖ח בִּרְכָתֶֽ⁠ךָ׃","wa⁠yò̇֕ʼmer bá֥̇ʼ ʼáẖi֖y⁠ká bĕ̇⁠mirĕmá֑h wa⁠yi̇qȧ֖ẖ bi̇rĕkáţeֽ⁠ká׃"],[27,36,"וַ⁠יֹּ֡אמֶר הֲ⁠כִי֩ קָרָ֨א שְׁמ֜⁠וֹ יַעֲקֹ֗ב וַֽ⁠יַּעְקְבֵ֨⁠נִי֙ זֶ֣ה פַעֲמַ֔יִם אֶת־בְּכֹרָתִ֣⁠י לָקָ֔ח וְ⁠הִנֵּ֥ה עַתָּ֖ה לָקַ֣ח בִּרְכָתִ֑⁠י וַ⁠יֹּאמַ֕ר הֲ⁠לֹא־אָצַ֥לְתָּ לִּ֖⁠י בְּרָכָֽה׃","wa⁠yò̇֡ʼmer hà⁠kiy֩ qárá֨ʼ şĕ̌m֜⁠wò yaʻàqò֗b wֽa⁠yȧʻĕqĕbé֨⁠niy֙ ze֣h paʻàma֔yim ʼeţ-bĕ̇kòráţi֣⁠y láqá֔ẖ wĕ⁠hiné֥̇h ʻaţá֖̇h láqa֣ẖ bi̇rĕkáţi֑⁠y wa⁠yò̇ʼma֕r hà⁠lòʼ-ʼáẕa֥lĕţá̇ li֖̇⁠y bĕ̇rákáֽh׃"],[27,37,"וַ⁠יַּ֨עַן יִצְחָ֜ק וַ⁠יֹּ֣אמֶר לְ⁠עֵשָׂ֗ו הֵ֣ן גְּבִ֞יר שַׂמְתִּ֥י⁠ו לָ⁠ךְ֙ וְ⁠אֶת־כָּל־אֶחָ֗י⁠ו נָתַ֤תִּי ל⁠וֹ֙ לַ⁠עֲבָדִ֔ים וְ⁠דָגָ֥ן וְ⁠תִירֹ֖שׁ סְמַכְתִּ֑י⁠ו וּ⁠לְ⁠כָ֣ה אֵפ֔וֹא מָ֥ה אֶֽעֱשֶׂ֖ה בְּנִֽ⁠י׃","wa⁠yȧ֨ʻan yiẕĕẖá֜q wa⁠yò֣̇ʼmer lĕ⁠ʻéşá̂֗w hé֣n gĕ̇bi֞yr şâmĕţi֥̇y⁠w lá⁠kĕ֙ wĕ⁠ʼeţ-ká̇l-ʼeẖá֗y⁠w náţa֤ţi̇y l⁠wò֙ la⁠ʻàbádi֔ym wĕ⁠dágá֥n wĕ⁠ţiyrò֖ş̌ sĕmakĕţi֑̇y⁠w ẇ⁠lĕ⁠ká֣h ʼép֔wòʼ má֥h ʼֽeʻèşê֖h bĕ̇niֽ⁠y׃"],[27,38,"וַ⁠יֹּ֨אמֶר עֵשָׂ֜ו אֶל־אָבִ֗י⁠ו הַֽ⁠בְרָכָ֨ה אַחַ֤ת הִֽוא־לְ⁠ךָ֙ אָבִ֔⁠י בָּרֲכֵ֥⁠נִי גַם־אָ֖נִי אָבִ֑⁠י וַ⁠יִּשָּׂ֥א עֵשָׂ֛ו קֹל֖⁠וֹ וַ⁠יֵּֽבְךְּ׃","wa⁠yò̇֨ʼmer ʻéşá̂֜w ʼel-ʼábi֗y⁠w haֽ⁠bĕráká֨h ʼaẖa֤ţ hiֽwʼ-lĕ⁠ká֙ ʼábi֔⁠y bá̇ràké֥⁠niy gam-ʼá֖niy ʼábi֑⁠y wa⁠yi̇şá֥̇̂ʼ ʻéşá֛̂w qòl֖⁠wò wa⁠yéֽ̇bĕkĕ̇׃"],[27,39,"וַ⁠יַּ֛עַן יִצְחָ֥ק אָבִ֖י⁠ו וַ⁠יֹּ֣אמֶר אֵלָ֑י⁠ו הִנֵּ֞ה מִ⁠שְׁמַנֵּ֤י הָ⁠אָ֨רֶץ֙ יִהְיֶ֣ה מֽוֹשָׁבֶ֔⁠ךָ וּ⁠מִ⁠טַּ֥ל הַ⁠שָּׁמַ֖יִם מֵ⁠עָֽל׃","wa⁠yȧ֛ʻan yiẕĕẖá֥q ʼábi֖y⁠w wa⁠yò֣̇ʼmer ʼélá֑y⁠w hiné̇֞h mi⁠şĕ̌mané֤̇y há⁠ʼá֨reẕ֙ yihĕye֣h mֽwòşá̌be֔⁠ká ẇ⁠mi⁠tȧ֥l ha⁠şá̇̌ma֖yim mé⁠ʻáֽl׃"],[27,40,"וְ⁠עַל־חַרְבְּ⁠ךָ֣ תִֽחְיֶ֔ה וְ⁠אֶת־אָחִ֖י⁠ךָ תַּעֲבֹ֑ד וְ⁠הָיָה֙ כַּ⁠אֲשֶׁ֣ר תָּרִ֔יד וּ⁠פָרַקְתָּ֥ עֻלּ֖⁠וֹ מֵ⁠עַ֥ל צַוָּארֶֽ⁠ךָ׃","wĕ⁠ʻal-ẖarĕbĕ̇⁠ká֣ ţiֽẖĕye֔h wĕ⁠ʼeţ-ʼáẖi֖y⁠ká ţȧʻàbò֑d wĕ⁠háyáh֙ kȧ⁠ʼàşě֣r ţá̇ri֔yd ẇ⁠páraqĕţá֥̇ ʻul֖̇⁠wò mé⁠ʻa֥l ẕawá̇ʼreֽ⁠ká׃"],[27,41,"וַ⁠יִּשְׂטֹ֤ם עֵשָׂו֙ אֶֽת־יַעֲקֹ֔ב עַל־הַ֨⁠בְּרָכָ֔ה אֲשֶׁ֥ר בֵּרֲכ֖⁠וֹ אָבִ֑י⁠ו וַ⁠יֹּ֨אמֶר עֵשָׂ֜ו בְּ⁠לִבּ֗⁠וֹ יִקְרְבוּ֙ יְמֵי֙ אֵ֣בֶל אָבִ֔⁠י וְ⁠אַֽהַרְגָ֖ה אֶת־יַעֲקֹ֥ב אָחִֽ⁠י׃","wa⁠yi̇şĕ̂tò֤m ʻéşá̂w֙ ʼeֽţ-yaʻàqò֔b ʻal-ha֨⁠bĕ̇ráká֔h ʼàşě֥r bé̇ràk֖⁠wò ʼábi֑y⁠w wa⁠yò̇֨ʼmer ʻéşá̂֜w bĕ̇⁠liḃ֗⁠wò yiqĕrĕbẇ֙ yĕméy֙ ʼé֣bel ʼábi֔⁠y wĕ⁠ʼaֽharĕgá֖h ʼeţ-yaʻàqò֥b ʼáẖiֽ⁠y׃"],[27,42,"וַ⁠יֻּגַּ֣ד לְ⁠רִבְקָ֔ה אֶת־דִּבְרֵ֥י עֵשָׂ֖ו בְּנָ֣⁠הּ הַ⁠גָּדֹ֑ל וַ⁠תִּשְׁלַ֞ח וַ⁠תִּקְרָ֤א לְ⁠יַעֲקֹב֙ בְּנָ֣⁠הּ הַ⁠קָּטָ֔ן וַ⁠תֹּ֣אמֶר אֵלָ֔י⁠ו הִנֵּה֙ עֵשָׂ֣ו אָחִ֔י⁠ךָ מִתְנַחֵ֥ם לְ⁠ךָ֖ לְ⁠הָרְגֶֽ⁠ךָ׃","wa⁠yu̇gȧ֣d lĕ⁠ribĕqá֔h ʼeţ-di̇bĕré֥y ʻéşá֖̂w bĕ̇ná֣⁠ḣ ha⁠gá̇dò֑l wa⁠ţi̇şĕ̌la֞ẖ wa⁠ţi̇qĕrá֤ʼ lĕ⁠yaʻàqòb֙ bĕ̇ná֣⁠ḣ ha⁠qá̇tá֔n wa⁠ţò֣̇ʼmer ʼélá֔y⁠w hiné̇h֙ ʻéşá֣̂w ʼáẖi֔y⁠ká miţĕnaẖé֥m lĕ⁠ká֖ lĕ⁠hárĕgeֽ⁠ká׃"],[27,43,"וְ⁠עַתָּ֥ה בְנִ֖⁠י שְׁמַ֣ע בְּ⁠קֹלִ֑⁠י וְ⁠ק֧וּם בְּרַח־לְ⁠ךָ֛ אֶל־לָבָ֥ן אָחִ֖⁠י חָרָֽנָ⁠ה׃","wĕ⁠ʻaţá֥̇h bĕni֖⁠y şĕ̌ma֣ʻ bĕ̇⁠qòli֑⁠y wĕ⁠q֧ẇm bĕ̇raẖ-lĕ⁠ká֛ ʼel-lábá֥n ʼáẖi֖⁠y ẖáráֽná⁠h׃"],[27,44,"וְ⁠יָשַׁבְתָּ֥ עִמּ֖⁠וֹ יָמִ֣ים אֲחָדִ֑ים עַ֥ד אֲשֶׁר־תָּשׁ֖וּב חֲמַ֥ת אָחִֽי⁠ךָ׃","wĕ⁠yáşǎbĕţá֥̇ ʻiṁ֖⁠wò yámi֣ym ʼàẖádi֑ym ʻa֥d ʼàşěr-ţá̇ş֖̌ẇb ẖàma֥ţ ʼáẖiֽy⁠ká׃"],[27,45,"עַד־שׁ֨וּב אַף־אָחִ֜י⁠ךָ מִמְּ⁠ךָ֗ וְ⁠שָׁכַח֙ אֵ֣ת אֲשֶׁר־עָשִׂ֣יתָ לּ֔⁠וֹ וְ⁠שָׁלַחְתִּ֖י וּ⁠לְקַחְתִּ֣י⁠ךָ מִ⁠שָּׁ֑ם לָ⁠מָ֥ה אֶשְׁכַּ֛ל גַּם־שְׁנֵי⁠כֶ֖ם י֥וֹם אֶחָֽד׃","ʻad-ş̌֨ẇb ʼap-ʼáẖi֜y⁠ká mimĕ̇⁠ká֗ wĕ⁠şá̌kaẖ֙ ʼé֣ţ ʼàşěr-ʻáşî֣yţá l̇֔⁠wò wĕ⁠şá̌laẖĕţi֖̇y ẇ⁠lĕqaẖĕţi֣̇y⁠ká mi⁠şá֑̇̌m lá⁠má֥h ʼeşĕ̌kȧ֛l gȧm-şĕ̌néy⁠ke֖m y֥wòm ʼeẖáֽd׃"],[27,46,"וַ⁠תֹּ֤אמֶר רִבְקָה֙ אֶל־יִצְחָ֔ק קַ֣צְתִּי בְ⁠חַיַּ֔⁠י מִ⁠פְּנֵ֖י בְּנ֣וֹת חֵ֑ת אִם־לֹקֵ֣חַ יַ֠עֲקֹב אִשָּׁ֨ה מִ⁠בְּנֽוֹת־חֵ֤ת כָּ⁠אֵ֨לֶּה֙ מִ⁠בְּנ֣וֹת הָ⁠אָ֔רֶץ לָ֥⁠מָּה לִּ֖⁠י חַיִּֽים׃","wa⁠ţò֤̇ʼmer ribĕqáh֙ ʼel-yiẕĕẖá֔q qa֣ẕĕţi̇y bĕ⁠ẖayȧ֔⁠y mi⁠pĕ̇né֖y bĕ̇n֣wòţ ẖé֑ţ ʼim-lòqé֣ẖa ya֠ʻàqòb ʼişá̇̌֨h mi⁠bĕ̇nֽwòţ-ẖé֤ţ ká̇⁠ʼé֨lėh֙ mi⁠bĕ̇n֣wòţ há⁠ʼá֔reẕ lá֥⁠má̇h li֖̇⁠y ẖayiֽ̇ym׃"],[28,1,"וַ⁠יִּקְרָ֥א יִצְחָ֛ק אֶֽל־יַעֲקֹ֖ב וַ⁠יְבָ֣רֶךְ אֹת֑⁠וֹ וַ⁠יְצַוֵּ֨⁠הוּ֙ וַ⁠יֹּ֣אמֶר ל֔⁠וֹ לֹֽא־תִקַּ֥ח אִשָּׁ֖ה מִ⁠בְּנ֥וֹת כְּנָֽעַן׃","wa⁠yi̇qĕrá֥ʼ yiẕĕẖá֛q ʼeֽl-yaʻàqò֖b wa⁠yĕbá֣rekĕ ʼòţ֑⁠wò wa⁠yĕẕawé̇֨⁠hẇ֙ wa⁠yò֣̇ʼmer l֔⁠wò lòֽʼ-ţiqȧ֥ẖ ʼişá֖̇̌h mi⁠bĕ̇n֥wòţ kĕ̇náֽʻan׃"],[28,2,"ק֥וּם לֵךְ֙ פַּדֶּ֣נָֽ⁠ה אֲרָ֔ם בֵּ֥יתָ⁠ה בְתוּאֵ֖ל אֲבִ֣י אִמֶּ֑⁠ךָ וְ⁠קַח־לְ⁠ךָ֤ מִ⁠שָּׁם֙ אִשָּׁ֔ה מִ⁠בְּנ֥וֹת לָבָ֖ן אֲחִ֥י אִמֶּֽ⁠ךָ׃","q֥ẇm lékĕ֙ pȧdė֣náֽ⁠h ʼàrá֔m bé֥̇yţá⁠h bĕţẇʼé֖l ʼàbi֣y ʼimė֑⁠ká wĕ⁠qaẖ-lĕ⁠ká֤ mi⁠şá̇̌m֙ ʼişá̇̌֔h mi⁠bĕ̇n֥wòţ lábá֖n ʼàẖi֥y ʼimėֽ⁠ká׃"],[28,3,"וְ⁠אֵ֤ל שַׁדַּי֙ יְבָרֵ֣ךְ אֹֽתְ⁠ךָ֔ וְ⁠יַפְרְ⁠ךָ֖ וְ⁠יַרְבֶּ֑⁠ךָ וְ⁠הָיִ֖יתָ לִ⁠קְהַ֥ל עַמִּֽים׃","wĕ⁠ʼé֤l şǎdȧy֙ yĕbáré֣kĕ ʼòֽţĕ⁠ká֔ wĕ⁠yapĕrĕ⁠ká֖ wĕ⁠yarĕbė֑⁠ká wĕ⁠háyi֖yţá li⁠qĕha֥l ʻamiֽ̇ym׃"],[28,4,"וְ⁠יִֽתֶּן־לְ⁠ךָ֙ אֶת־בִּרְכַּ֣ת אַבְרָהָ֔ם לְ⁠ךָ֖ וּ⁠לְ⁠זַרְעֲ⁠ךָ֣ אִתָּ֑⁠ךְ לְ⁠רִשְׁתְּ⁠ךָ֙ אֶת־אֶ֣רֶץ מְגֻרֶ֔י⁠ךָ אֲשֶׁר־נָתַ֥ן אֱלֹהִ֖ים לְ⁠אַבְרָהָֽם׃","wĕ⁠yiֽţėn-lĕ⁠ká֙ ʼeţ-bi̇rĕkȧ֣ţ ʼabĕráhá֔m lĕ⁠ká֖ ẇ⁠lĕ⁠zarĕʻà⁠ká֣ ʼiţá֑̇⁠kĕ lĕ⁠rişĕ̌ţĕ̇⁠ká֙ ʼeţ-ʼe֣reẕ mĕgure֔y⁠ká ʼàşěr-náţa֥n ʼèlòhi֖ym lĕ⁠ʼabĕráháֽm׃"],[28,5,"וַ⁠יִּשְׁלַ֤ח יִצְחָק֙ אֶֽת־יַעֲקֹ֔ב וַ⁠יֵּ֖לֶךְ פַּדֶּ֣נָֽ⁠ה אֲרָ֑ם אֶל־לָבָ֤ן בֶּן־בְּתוּאֵל֙ הָֽ⁠אֲרַמִּ֔י אֲחִ֣י רִבְקָ֔ה אֵ֥ם יַעֲקֹ֖ב וְ⁠עֵשָֽׂו׃","wa⁠yi̇şĕ̌la֤ẖ yiẕĕẖáq֙ ʼeֽţ-yaʻàqò֔b wa⁠yé֖̇lekĕ pȧdė֣náֽ⁠h ʼàrá֑m ʼel-lábá֤n bėn-bĕ̇ţẇʼél֙ háֽ⁠ʼàrami̇֔y ʼàẖi֣y ribĕqá֔h ʼé֥m yaʻàqò֖b wĕ⁠ʻéşáֽ̂w׃"],[28,6,"וַ⁠יַּ֣רְא עֵשָׂ֗ו כִּֽי־בֵרַ֣ךְ יִצְחָק֮ אֶֽת־יַעֲקֹב֒ וְ⁠שִׁלַּ֤ח אֹת⁠וֹ֙ פַּדֶּ֣נָֽ⁠ה אֲרָ֔ם לָ⁠קַֽחַת־ל֥⁠וֹ מִ⁠שָּׁ֖ם אִשָּׁ֑ה בְּ⁠בָרֲכ֣⁠וֹ אֹת֔⁠וֹ וַ⁠יְצַ֤ו עָלָי⁠ו֙ לֵ⁠אמֹ֔ר לֹֽא־תִקַּ֥ח אִשָּׁ֖ה מִ⁠בְּנ֥וֹת כְּנָֽעַן׃","wa⁠yȧ֣rĕʼ ʻéşá̂֗w kiֽ̇y-béra֣kĕ yiẕĕẖáq֮ ʼeֽţ-yaʻàqòb֒ wĕ⁠şǐlȧ֤ẖ ʼòţ⁠wò֙ pȧdė֣náֽ⁠h ʼàrá֔m lá⁠qaֽẖaţ-l֥⁠wò mi⁠şá֖̇̌m ʼişá֑̇̌h bĕ̇⁠báràk֣⁠wò ʼòţ֔⁠wò wa⁠yĕẕa֤w ʻáláy⁠w֙ lé⁠ʼmò֔r lòֽʼ-ţiqȧ֥ẖ ʼişá֖̇̌h mi⁠bĕ̇n֥wòţ kĕ̇náֽʻan׃"],[28,7,"וַ⁠יִּשְׁמַ֣ע יַעֲקֹ֔ב אֶל־אָבִ֖י⁠ו וְ⁠אֶל־אִמּ֑⁠וֹ וַ⁠יֵּ֖לֶךְ פַּדֶּ֥נָֽ⁠ה אֲרָֽם׃","wa⁠yi̇şĕ̌ma֣ʻ yaʻàqò֔b ʼel-ʼábi֖y⁠w wĕ⁠ʼel-ʼiṁ֑⁠wò wa⁠yé֖̇lekĕ pȧdė֥náֽ⁠h ʼàráֽm׃"],[28,8,"וַ⁠יַּ֣רְא עֵשָׂ֔ו כִּ֥י רָע֖וֹת בְּנ֣וֹת כְּנָ֑עַן בְּ⁠עֵינֵ֖י יִצְחָ֥ק אָבִֽי⁠ו׃","wa⁠yȧ֣rĕʼ ʻéşá̂֔w ki֥̇y ráʻ֖wòţ bĕ̇n֣wòţ kĕ̇ná֑ʻan bĕ̇⁠ʻéyné֖y yiẕĕẖá֥q ʼábiֽy⁠w׃"],[28,9,"וַ⁠יֵּ֥לֶךְ עֵשָׂ֖ו אֶל־יִשְׁמָעֵ֑אל וַ⁠יִּקַּ֡ח אֶֽת־מָחֲלַ֣ת ׀ בַּת־יִשְׁמָעֵ֨אל בֶּן־אַבְרָהָ֜ם אֲח֧וֹת נְבָי֛וֹת עַל־נָשָׁ֖י⁠ו ל֥⁠וֹ לְ⁠אִשָּֽׁה׃ס","wa⁠yé֥̇lekĕ ʻéşá֖̂w ʼel-yişĕ̌máʻé֑ʼl wa⁠yi̇qȧ֡ẖ ʼeֽţ-máẖàla֣ţ ׀ bȧţ-yişĕ̌máʻé֨ʼl bėn-ʼabĕráhá֜m ʼàẖ֧wòţ nĕbáy֛wòţ ʻal-náşá֖̌y⁠w l֥⁠wò lĕ⁠ʼişáֽ̇̌h׃s"],[28,10,"וַ⁠יֵּצֵ֥א יַעֲקֹ֖ב מִ⁠בְּאֵ֣ר שָׁ֑בַע וַ⁠יֵּ֖לֶךְ חָרָֽנָ⁠ה׃","wa⁠yé̇ẕé֥ʼ yaʻàqò֖b mi⁠bĕ̇ʼé֣r şá֑̌baʻ wa⁠yé֖̇lekĕ ẖáráֽná⁠h׃"],[28,11,"וַ⁠יִּפְגַּ֨ע בַּ⁠מָּק֜וֹם וַ⁠יָּ֤לֶן שָׁם֙ כִּי־בָ֣א הַ⁠שֶּׁ֔מֶשׁ וַ⁠יִּקַּח֙ מֵ⁠אַבְנֵ֣י הַ⁠מָּק֔וֹם וַ⁠יָּ֖שֶׂם מְרַֽאֲשֹׁתָ֑י⁠ו וַ⁠יִּשְׁכַּ֖ב בַּ⁠מָּק֥וֹם הַ⁠הֽוּא׃","wa⁠yi̇pĕgȧ֨ʻ bȧ⁠má̇q֜wòm wa⁠yá֤̇len şá̌m֙ ki̇y-bá֣ʼ ha⁠şė̌֔meş̌ wa⁠yi̇qȧẖ֙ mé⁠ʼabĕné֣y ha⁠má̇q֔wòm wa⁠yá֖̇şêm mĕraֽʼàşò̌ţá֑y⁠w wa⁠yi̇şĕ̌kȧ֖b bȧ⁠má̇q֥wòm ha⁠hֽẇʼ׃"],[28,12,"וַֽ⁠יַּחֲלֹ֗ם וְ⁠הִנֵּ֤ה סֻלָּם֙ מֻצָּ֣ב אַ֔רְצָ⁠ה וְ⁠רֹאשׁ֖⁠וֹ מַגִּ֣יעַ הַ⁠שָּׁמָ֑יְמָ⁠ה וְ⁠הִנֵּה֙ מַלְאֲכֵ֣י אֱלֹהִ֔ים עֹלִ֥ים וְ⁠יֹרְדִ֖ים בּֽ⁠וֹ׃","wֽa⁠yȧẖàlò֗m wĕ⁠hiné֤̇h sulá̇m֙ muẕá֣̇b ʼa֔rĕẕá⁠h wĕ⁠ròʼş֖̌⁠wò magi֣̇yʻa ha⁠şá̇̌má֑yĕmá⁠h wĕ⁠hiné̇h֙ malĕʼàké֣y ʼèlòhi֔ym ʻòli֥ym wĕ⁠yòrĕdi֖ym ḃֽ⁠wò׃"],[28,13,"וְ⁠הִנֵּ֨ה יְהוָ֜ה נִצָּ֣ב עָלָי⁠ו֮ וַ⁠יֹּאמַר֒ אֲנִ֣י יְהוָ֗ה אֱלֹהֵי֙ אַבְרָהָ֣ם אָבִ֔י⁠ךָ וֵ⁠אלֹהֵ֖י יִצְחָ֑ק הָ⁠אָ֗רֶץ אֲשֶׁ֤ר אַתָּה֙ שֹׁכֵ֣ב עָלֶ֔י⁠הָ לְ⁠ךָ֥ אֶתְּנֶ֖⁠נָּה וּ⁠לְ⁠זַרְעֶֽ⁠ךָ׃","wĕ⁠hiné̇֨h yĕhwá֜h niẕá֣̇b ʻáláy⁠w֮ wa⁠yò̇ʼmar֒ ʼàni֣y yĕhwá֗h ʼèlòhéy֙ ʼabĕráhá֣m ʼábi֔y⁠ká wé⁠ʼlòhé֖y yiẕĕẖá֑q há⁠ʼá֗reẕ ʼàşě֤r ʼaţá̇h֙ şò̌ké֣b ʻále֔y⁠há lĕ⁠ká֥ ʼeţĕ̇ne֖⁠ná̇h ẇ⁠lĕ⁠zarĕʻeֽ⁠ká׃"],[28,14,"וְ⁠הָיָ֤ה זַרְעֲ⁠ךָ֙ כַּ⁠עֲפַ֣ר הָ⁠אָ֔רֶץ וּ⁠פָרַצְתָּ֛ יָ֥מָּ⁠ה וָ⁠קֵ֖דְמָ⁠ה וְ⁠צָפֹ֣נָ⁠ה וָ⁠נֶ֑גְבָּ⁠ה וְ⁠נִבְרֲכ֥וּ בְ⁠ךָ֛ כָּל־מִשְׁפְּחֹ֥ת הָ⁠אֲדָמָ֖ה וּ⁠בְ⁠זַרְעֶֽ⁠ךָ׃","wĕ⁠háyá֤h zarĕʻà⁠ká֙ kȧ⁠ʻàpa֣r há⁠ʼá֔reẕ ẇ⁠páraẕĕţá֛̇ yá֥má̇⁠h wá⁠qé֖dĕmá⁠h wĕ⁠ẕápò֣ná⁠h wá⁠ne֑gĕbá̇⁠h wĕ⁠nibĕràk֥ẇ bĕ⁠ká֛ ká̇l-mişĕ̌pĕ̇ẖò֥ţ há⁠ʼàdámá֖h ẇ⁠bĕ⁠zarĕʻeֽ⁠ká׃"],[28,15,"וְ⁠הִנֵּ֨ה אָנֹכִ֜י עִמָּ֗⁠ךְ וּ⁠שְׁמַרְתִּ֨י⁠ךָ֙ בְּ⁠כֹ֣ל אֲשֶׁר־תֵּלֵ֔ךְ וַ⁠הֲשִׁ֣בֹתִ֔י⁠ךָ אֶל־הָ⁠אֲדָמָ֖ה הַ⁠זֹּ֑את כִּ֚י לֹ֣א אֶֽעֱזָבְ⁠ךָ֔ עַ֚ד אֲשֶׁ֣ר אִם־עָשִׂ֔יתִי אֵ֥ת אֲשֶׁר־דִּבַּ֖רְתִּי לָֽ⁠ךְ׃","wĕ⁠hiné̇֨h ʼánòki֜y ʻimá̇֗⁠kĕ ẇ⁠şĕ̌marĕţi̇֨y⁠ká֙ bĕ̇⁠kò֣l ʼàşěr-ţé̇lé֔kĕ wa⁠hàşǐ֣bòţi֔y⁠ká ʼel-há⁠ʼàdámá֖h ha⁠zò֑̇ʼţ ki֚̇y lò֣ʼ ʼֽeʻèzábĕ⁠ká֔ ʻa֚d ʼàşě֣r ʼim-ʻáşî֔yţiy ʼé֥ţ ʼàşěr-di̇bȧ֖rĕţi̇y láֽ⁠kĕ׃"],[28,16,"וַ⁠יִּיקַ֣ץ יַעֲקֹב֮ מִ⁠שְּׁנָת⁠וֹ֒ וַ⁠יֹּ֕אמֶר אָכֵן֙ יֵ֣שׁ יְהוָ֔ה בַּ⁠מָּק֖וֹם הַ⁠זֶּ֑ה וְ⁠אָנֹכִ֖י לֹ֥א יָדָֽעְתִּי׃","wa⁠yi̇yqa֣ẕ yaʻàqòb֮ mi⁠şĕ̇̌náţ⁠wò֒ wa⁠yò̇֕ʼmer ʼákén֙ yé֣ş̌ yĕhwá֔h bȧ⁠má̇q֖wòm ha⁠zė֑h wĕ⁠ʼánòki֖y lò֥ʼ yádáֽʻĕţi̇y׃"],[28,17,"וַ⁠יִּירָא֙ וַ⁠יֹּאמַ֔ר מַה־נּוֹרָ֖א הַ⁠מָּק֣וֹם הַ⁠זֶּ֑ה אֵ֣ין זֶ֗ה כִּ֚י אִם־בֵּ֣ית אֱלֹהִ֔ים וְ⁠זֶ֖ה שַׁ֥עַר הַ⁠שָּׁמָֽיִם׃","wa⁠yi̇yráʼ֙ wa⁠yò̇ʼma֔r mah-ṅwòrá֖ʼ ha⁠má̇q֣wòm ha⁠zė֑h ʼé֣yn ze֗h ki֚̇y ʼim-bé֣̇yţ ʼèlòhi֔ym wĕ⁠ze֖h şǎ֥ʻar ha⁠şá̇̌máֽyim׃"],[28,18,"וַ⁠יַּשְׁכֵּ֨ם יַעֲקֹ֜ב בַּ⁠בֹּ֗קֶר וַ⁠יִּקַּ֤ח אֶת־הָ⁠אֶ֨בֶן֙ אֲשֶׁר־שָׂ֣ם מְרַֽאֲשֹׁתָ֔י⁠ו וַ⁠יָּ֥שֶׂם אֹתָ֖⁠הּ מַצֵּבָ֑ה וַ⁠יִּצֹ֥ק שֶׁ֖מֶן עַל־רֹאשָֽׁ⁠הּ׃","wa⁠yȧşĕ̌ké̇֨m yaʻàqò֜b bȧ⁠bò̇֗qer wa⁠yi̇qȧ֤ẖ ʼeţ-há⁠ʼe֨ben֙ ʼàşěr-şá֣̂m mĕraֽʼàşò̌ţá֔y⁠w wa⁠yá֥̇şêm ʼòţá֖⁠ḣ maẕé̇bá֑h wa⁠yi̇ẕò֥q şě֖men ʻal-ròʼşáֽ̌⁠ḣ׃"],[28,19,"וַ⁠יִּקְרָ֛א אֶת־שֵֽׁם־הַ⁠מָּק֥וֹם הַ⁠ה֖וּא בֵּֽית־אֵ֑ל וְ⁠אוּלָ֛ם ל֥וּז שֵׁם־הָ⁠עִ֖יר לָ⁠רִאשֹׁנָֽה׃","wa⁠yi̇qĕrá֛ʼ ʼeţ-şéֽ̌m-ha⁠má̇q֥wòm ha⁠h֖ẇʼ béֽ̇yţ-ʼé֑l wĕ⁠ʼẇlá֛m l֥ẇz şé̌m-há⁠ʻi֖yr lá⁠riʼşò̌náֽh׃"],[28,20,"וַ⁠יִּדַּ֥ר יַעֲקֹ֖ב נֶ֣דֶר לֵ⁠אמֹ֑ר אִם־יִהְיֶ֨ה אֱלֹהִ֜ים עִמָּדִ֗⁠י וּ⁠שְׁמָרַ֨⁠נִי֙ בַּ⁠דֶּ֤רֶךְ הַ⁠זֶּה֙ אֲשֶׁ֣ר אָנֹכִ֣י הוֹלֵ֔ךְ וְ⁠נָֽתַן־לִ֥⁠י לֶ֛חֶם לֶ⁠אֱכֹ֖ל וּ⁠בֶ֥גֶד לִ⁠לְבֹּֽשׁ׃","wa⁠yi̇dȧ֥r yaʻàqò֖b ne֣der lé⁠ʼmò֑r ʼim-yihĕye֨h ʼèlòhi֜ym ʻimá̇di֗⁠y ẇ⁠şĕ̌mára֨⁠niy֙ bȧ⁠dė֤rekĕ ha⁠zėh֙ ʼàşě֣r ʼánòki֣y hwòlé֔kĕ wĕ⁠náֽţan-li֥⁠y le֛ẖem le⁠ʼèkò֖l ẇ⁠be֥ged li⁠lĕbòֽ̇ş̌׃"],[28,21,"וְ⁠שַׁבְתִּ֥י בְ⁠שָׁל֖וֹם אֶל־בֵּ֣ית אָבִ֑⁠י וְ⁠הָיָ֧ה יְהוָ֛ה לִ֖⁠י לֵ⁠אלֹהִֽים׃","wĕ⁠şǎbĕţi֥̇y bĕ⁠şá̌l֖wòm ʼel-bé֣̇yţ ʼábi֑⁠y wĕ⁠háyá֧h yĕhwá֛h li֖⁠y lé⁠ʼlòhiֽym׃"],[28,22,"וְ⁠הָ⁠אֶ֣בֶן הַ⁠זֹּ֗את אֲשֶׁר־שַׂ֨מְתִּי֙ מַצֵּבָ֔ה יִהְיֶ֖ה בֵּ֣ית אֱלֹהִ֑ים וְ⁠כֹל֙ אֲשֶׁ֣ר תִּתֶּן־לִ֔⁠י עַשֵּׂ֖ר אֲעַשְּׂרֶ֥⁠נּוּ לָֽ⁠ךְ׃","wĕ⁠há⁠ʼe֣ben ha⁠zò̇֗ʼţ ʼàşěr-şâ֨mĕţi̇y֙ maẕé̇bá֔h yihĕye֖h bé֣̇yţ ʼèlòhi֑ym wĕ⁠kòl֙ ʼàşě֣r ţi̇ţėn-li֔⁠y ʻaşé֖̇̂r ʼàʻaşĕ̇̂re֥⁠ṅẇ láֽ⁠kĕ׃"],[29,1,"וַ⁠יִּשָּׂ֥א יַעֲקֹ֖ב רַגְלָ֑י⁠ו וַ⁠יֵּ֖לֶךְ אַ֥רְצָ⁠ה בְנֵי־קֶֽדֶם׃","wa⁠yi̇şá֥̇̂ʼ yaʻàqò֖b ragĕlá֑y⁠w wa⁠yé֖̇lekĕ ʼa֥rĕẕá⁠h bĕnéy-qeֽdem׃"],[29,2,"וַ⁠יַּ֞רְא וְ⁠הִנֵּ֧ה בְאֵ֣ר בַּ⁠שָּׂדֶ֗ה וְ⁠הִנֵּה־שָׁ֞ם שְׁלֹשָׁ֤ה עֶדְרֵי־צֹאן֙ רֹבְצִ֣ים עָלֶ֔י⁠הָ כִּ֚י מִן־הַ⁠בְּאֵ֣ר הַ⁠הִ֔וא יַשְׁק֖וּ הָ⁠עֲדָרִ֑ים וְ⁠הָ⁠אֶ֥בֶן גְּדֹלָ֖ה עַל־פִּ֥י הַ⁠בְּאֵֽר׃","wa⁠yȧ֞rĕʼ wĕ⁠hiné֧̇h bĕʼé֣r bȧ⁠şá̇̂de֗h wĕ⁠hiné̇h-şá̌֞m şĕ̌lòşá֤̌h ʻedĕréy-ẕòʼn֙ ròbĕẕi֣ym ʻále֔y⁠há ki֚̇y min-ha⁠bĕ̇ʼé֣r ha⁠hi֔wʼ yaşĕ̌q֖ẇ há⁠ʻàdári֑ym wĕ⁠há⁠ʼe֥ben gĕ̇dòlá֖h ʻal-pi֥̇y ha⁠bĕ̇ʼéֽr׃"],[29,3,"וְ⁠נֶאֶסְפוּ־שָׁ֣מָּ⁠ה כָל־הָ⁠עֲדָרִ֗ים וְ⁠גָלֲל֤וּ אֶת־הָ⁠אֶ֨בֶן֙ מֵ⁠עַל֙ פִּ֣י הַ⁠בְּאֵ֔ר וְ⁠הִשְׁק֖וּ אֶת־הַ⁠צֹּ֑אן וְ⁠הֵשִׁ֧יבוּ אֶת־הָ⁠אֶ֛בֶן עַל־פִּ֥י הַ⁠בְּאֵ֖ר לִ⁠מְקֹמָֽ⁠הּ׃","wĕ⁠neʼesĕpẇ-şá֣̌má̇⁠h kál-há⁠ʻàdári֗ym wĕ⁠gálàl֤ẇ ʼeţ-há⁠ʼe֨ben֙ mé⁠ʻal֙ pi֣̇y ha⁠bĕ̇ʼé֔r wĕ⁠hişĕ̌q֖ẇ ʼeţ-ha⁠ẕò֑̇ʼn wĕ⁠héşǐ֧ybẇ ʼeţ-há⁠ʼe֛ben ʻal-pi֥̇y ha⁠bĕ̇ʼé֖r li⁠mĕqòmáֽ⁠ḣ׃"],[29,4,"וַ⁠יֹּ֤אמֶר לָ⁠הֶם֙ יַעֲקֹ֔ב אַחַ֖⁠י מֵ⁠אַ֣יִן אַתֶּ֑ם וַ⁠יֹּ֣אמְר֔וּ מֵ⁠חָרָ֖ן אֲנָֽחְנוּ׃","wa⁠yò֤̇ʼmer lá⁠hem֙ yaʻàqò֔b ʼaẖa֖⁠y mé⁠ʼa֣yin ʼaţė֑m wa⁠yò֣̇ʼmĕr֔ẇ mé⁠ẖárá֖n ʼànáֽẖĕnẇ׃"],[29,5,"וַ⁠יֹּ֣אמֶר לָ⁠הֶ֔ם הַ⁠יְדַעְתֶּ֖ם אֶת־לָבָ֣ן בֶּן־נָח֑וֹר וַ⁠יֹּאמְר֖וּ יָדָֽעְנוּ׃","wa⁠yò֣̇ʼmer lá⁠he֔m ha⁠yĕdaʻĕţė֖m ʼeţ-lábá֣n bėn-náẖ֑wòr wa⁠yò̇ʼmĕr֖ẇ yádáֽʻĕnẇ׃"],[29,6,"וַ⁠יֹּ֥אמֶר לָ⁠הֶ֖ם הֲ⁠שָׁל֣וֹם ל֑⁠וֹ וַ⁠יֹּאמְר֣וּ שָׁל֔וֹם וְ⁠הִנֵּה֙ רָחֵ֣ל בִּתּ֔⁠וֹ בָּאָ֖ה עִם־הַ⁠צֹּֽאן׃","wa⁠yò֥̇ʼmer lá⁠he֖m hà⁠şá̌l֣wòm l֑⁠wò wa⁠yò̇ʼmĕr֣ẇ şá̌l֔wòm wĕ⁠hiné̇h֙ ráẖé֣l bi̇ţ̇֔⁠wò bá̇ʼá֖h ʻim-ha⁠ẕòֽ̇ʼn׃"],[29,7,"וַ⁠יֹּ֗אמֶר הֵ֥ן עוֹד֙ הַ⁠יּ֣וֹם גָּד֔וֹל לֹא־עֵ֖ת הֵאָסֵ֣ף הַ⁠מִּקְנֶ֑ה הַשְׁק֥וּ הַ⁠צֹּ֖אן וּ⁠לְכ֥וּ רְעֽוּ׃","wa⁠yò̇֗ʼmer hé֥n ʻwòd֙ ha⁠ẏ֣wòm gá̇d֔wòl lòʼ-ʻé֖ţ héʼásé֣p ha⁠mi̇qĕne֑h haşĕ̌q֥ẇ ha⁠ẕò֖̇ʼn ẇ⁠lĕk֥ẇ rĕʻֽẇ׃"],[29,8,"וַ⁠יֹּאמְרוּ֮ לֹ֣א נוּכַל֒ עַ֣ד אֲשֶׁ֤ר יֵאָֽסְפוּ֙ כָּל־הָ֣⁠עֲדָרִ֔ים וְ⁠גָֽלֲלוּ֙ אֶת־הָ⁠אֶ֔בֶן מֵ⁠עַ֖ל פִּ֣י הַ⁠בְּאֵ֑ר וְ⁠הִשְׁקִ֖ינוּ הַ⁠צֹּֽאן׃","wa⁠yò̇ʼmĕrẇ֮ lò֣ʼ nẇkal֒ ʻa֣d ʼàşě֤r yéʼáֽsĕpẇ֙ ká̇l-há֣⁠ʻàdári֔ym wĕ⁠gáֽlàlẇ֙ ʼeţ-há⁠ʼe֔ben mé⁠ʻa֖l pi֣̇y ha⁠bĕ̇ʼé֑r wĕ⁠hişĕ̌qi֖ynẇ ha⁠ẕòֽ̇ʼn׃"],[29,9,"עוֹדֶ֖⁠נּוּ מְדַבֵּ֣ר עִמָּ֑⁠ם וְ⁠רָחֵ֣ל ׀ בָּ֗אָה עִם־הַ⁠צֹּאן֙ אֲשֶׁ֣ר לְ⁠אָבִ֔י⁠הָ כִּ֥י רֹעָ֖ה הִֽוא׃","ʻwòde֖⁠ṅẇ mĕdabé֣̇r ʻimá֑̇⁠m wĕ⁠ráẖé֣l ׀ bá̇֗ʼáh ʻim-ha⁠ẕò̇ʼn֙ ʼàşě֣r lĕ⁠ʼábi֔y⁠há ki֥̇y ròʻá֖h hiֽwʼ׃"],[29,10,"וַ⁠יְהִ֡י כַּ⁠אֲשֶׁר֩ רָאָ֨ה יַעֲקֹ֜ב אֶת־רָחֵ֗ל בַּת־לָבָן֙ אֲחִ֣י אִמּ֔⁠וֹ וְ⁠אֶת־צֹ֥אן לָבָ֖ן אֲחִ֣י אִמּ֑⁠וֹ וַ⁠יִּגַּ֣שׁ יַעֲקֹ֗ב וַ⁠יָּ֤גֶל אֶת־הָ⁠אֶ֨בֶן֙ מֵ⁠עַל֙ פִּ֣י הַ⁠בְּאֵ֔ר וַ⁠יַּ֕שְׁקְ אֶת־צֹ֥אן לָבָ֖ן אֲחִ֥י אִמּֽ⁠וֹ׃","wa⁠yĕhi֡y kȧ⁠ʼàşěr֩ ráʼá֨h yaʻàqò֜b ʼeţ-ráẖé֗l bȧţ-lábán֙ ʼàẖi֣y ʼiṁ֔⁠wò wĕ⁠ʼeţ-ẕò֥ʼn lábá֖n ʼàẖi֣y ʼiṁ֑⁠wò wa⁠yi̇gȧ֣ş̌ yaʻàqò֗b wa⁠yá֤̇gel ʼeţ-há⁠ʼe֨ben֙ mé⁠ʻal֙ pi֣̇y ha⁠bĕ̇ʼé֔r wa⁠yȧ֕şĕ̌qĕ ʼeţ-ẕò֥ʼn lábá֖n ʼàẖi֥y ʼiṁֽ⁠wò׃"],[29,11,"וַ⁠יִּשַּׁ֥ק יַעֲקֹ֖ב לְ⁠רָחֵ֑ל וַ⁠יִּשָּׂ֥א אֶת־קֹל֖⁠וֹ וַ⁠יֵּֽבְךְּ׃","wa⁠yi̇şȧ֥̌q yaʻàqò֖b lĕ⁠ráẖé֑l wa⁠yi̇şá֥̇̂ʼ ʼeţ-qòl֖⁠wò wa⁠yéֽ̇bĕkĕ̇׃"],[29,12,"וַ⁠יַּגֵּ֨ד יַעֲקֹ֜ב לְ⁠רָחֵ֗ל כִּ֣י אֲחִ֤י אָבִ֨י⁠הָ֙ ה֔וּא וְ⁠כִ֥י בֶן־רִבְקָ֖ה ה֑וּא וַ⁠תָּ֖רָץ וַ⁠תַּגֵּ֥ד לְ⁠אָבִֽי⁠הָ׃","wa⁠yȧgé̇֨d yaʻàqò֜b lĕ⁠ráẖé֗l ki֣̇y ʼàẖi֤y ʼábi֨y⁠há֙ h֔ẇʼ wĕ⁠ki֥y ben-ribĕqá֖h h֑ẇʼ wa⁠ţá֖̇ráẕ wa⁠ţȧgé֥̇d lĕ⁠ʼábiֽy⁠há׃"],[29,13,"וַ⁠יְהִי֩ כִ⁠שְׁמֹ֨עַ לָבָ֜ן אֶת־שֵׁ֣מַע ׀ יַעֲקֹ֣ב בֶּן־אֲחֹת֗⁠וֹ וַ⁠יָּ֤רָץ לִ⁠קְרָאת⁠וֹ֙ וַ⁠יְחַבֶּק־ל⁠וֹ֙ וַ⁠יְנַשֶּׁק־ל֔⁠וֹ וַ⁠יְבִיאֵ֖⁠הוּ אֶל־בֵּית֑⁠וֹ וַ⁠יְסַפֵּ֣ר לְ⁠לָבָ֔ן אֵ֥ת כָּל־הַ⁠דְּבָרִ֖ים הָ⁠אֵֽלֶּה׃","wa⁠yĕhiy֩ ki⁠şĕ̌mò֨ʻa lábá֜n ʼeţ-şé֣̌maʻ ׀ yaʻàqò֣b bėn-ʼàẖòţ֗⁠wò wa⁠yá֤̇ráẕ li⁠qĕráʼţ⁠wò֙ wa⁠yĕẖabėq-l⁠wò֙ wa⁠yĕnaşė̌q-l֔⁠wò wa⁠yĕbiyʼé֖⁠hẇ ʼel-bé̇yţ֑⁠wò wa⁠yĕsapé֣̇r lĕ⁠lábá֔n ʼé֥ţ ká̇l-ha⁠dĕ̇bári֖ym há⁠ʼéֽlėh׃"],[29,14,"וַ⁠יֹּ֤אמֶר ל⁠וֹ֙ לָבָ֔ן אַ֛ךְ עַצְמִ֥⁠י וּ⁠בְשָׂרִ֖⁠י אָ֑תָּה וַ⁠יֵּ֥שֶׁב עִמּ֖⁠וֹ חֹ֥דֶשׁ יָמִֽים׃","wa⁠yò֤̇ʼmer l⁠wò֙ lábá֔n ʼa֛kĕ ʻaẕĕmi֥⁠y ẇ⁠bĕşá̂ri֖⁠y ʼá֑ţá̇h wa⁠yé֥̇şěb ʻiṁ֖⁠wò ẖò֥deş̌ yámiֽym׃"],[29,15,"וַ⁠יֹּ֤אמֶר לָבָן֙ לְ⁠יַעֲקֹ֔ב הֲ⁠כִי־אָחִ֣⁠י אַ֔תָּה וַ⁠עֲבַדְתַּ֖⁠נִי חִנָּ֑ם הַגִּ֥ידָ⁠ה לִּ֖⁠י מַה־מַּשְׂכֻּרְתֶּֽ⁠ךָ׃","wa⁠yò֤̇ʼmer lábán֙ lĕ⁠yaʻàqò֔b hà⁠kiy-ʼáẖi֣⁠y ʼa֔ţá̇h wa⁠ʻàbadĕţȧ֖⁠niy ẖiná֑̇m hagi֥̇ydá⁠h li֖̇⁠y mah-mȧşĕ̂ku̇rĕţėֽ⁠ká׃"],[29,16,"וּ⁠לְ⁠לָבָ֖ן שְׁתֵּ֣י בָנ֑וֹת שֵׁ֤ם הַ⁠גְּדֹלָה֙ לֵאָ֔ה וְ⁠שֵׁ֥ם הַ⁠קְּטַנָּ֖ה רָחֵֽל׃","ẇ⁠lĕ⁠lábá֖n şĕ̌ţé֣̇y bán֑wòţ şé֤̌m ha⁠gĕ̇dòláh֙ léʼá֔h wĕ⁠şé֥̌m ha⁠qĕ̇taná֖̇h ráẖéֽl׃"],[29,17,"וְ⁠עֵינֵ֥י לֵאָ֖ה רַכּ֑וֹת וְ⁠רָחֵל֙ הָֽיְתָ֔ה יְפַת־תֹּ֖אַר וִ⁠יפַ֥ת מַרְאֶֽה׃","wĕ⁠ʻéyné֥y léʼá֖h rak֑̇wòţ wĕ⁠ráẖél֙ háֽyĕţá֔h yĕpaţ-ţò֖̇ʼar wi⁠ypa֥ţ marĕʼeֽh׃"],[29,18,"וַ⁠יֶּאֱהַ֥ב יַעֲקֹ֖ב אֶת־רָחֵ֑ל וַ⁠יֹּ֗אמֶר אֶֽעֱבָדְ⁠ךָ֙ שֶׁ֣בַע שָׁנִ֔ים בְּ⁠רָחֵ֥ל בִּתְּ⁠ךָ֖ הַ⁠קְּטַנָּֽה׃","wa⁠yėʼèha֥b yaʻàqò֖b ʼeţ-ráẖé֑l wa⁠yò̇֗ʼmer ʼֽeʻèbádĕ⁠ká֙ şě֣baʻ şá̌ni֔ym bĕ̇⁠ráẖé֥l bi̇ţĕ̇⁠ká֖ ha⁠qĕ̇tanáֽ̇h׃"],[29,19,"וַ⁠יֹּ֣אמֶר לָבָ֗ן ט֚וֹב תִּתִּ֣⁠י אֹתָ֣⁠הּ לָ֔⁠ךְ מִ⁠תִּתִּ֥⁠י אֹתָ֖⁠הּ לְ⁠אִ֣ישׁ אַחֵ֑ר שְׁבָ֖⁠ה עִמָּדִֽ⁠י׃","wa⁠yò֣̇ʼmer lábá֗n t֚wòb ţi̇ţi֣̇⁠y ʼòţá֣⁠ḣ lá֔⁠kĕ mi⁠ţi̇ţi֥̇⁠y ʼòţá֖⁠ḣ lĕ⁠ʼi֣yş̌ ʼaẖé֑r şĕ̌bá֖⁠h ʻimá̇diֽ⁠y׃"],[29,20,"וַ⁠יַּעֲבֹ֧ד יַעֲקֹ֛ב בְּ⁠רָחֵ֖ל שֶׁ֣בַע שָׁנִ֑ים וַ⁠יִּהְי֤וּ בְ⁠עֵינָי⁠ו֙ כְּ⁠יָמִ֣ים אֲחָדִ֔ים בְּ⁠אַהֲבָת֖⁠וֹ אֹתָֽ⁠הּ׃","wa⁠yȧʻàbò֧d yaʻàqò֛b bĕ̇⁠ráẖé֖l şě֣baʻ şá̌ni֑ym wa⁠yi̇hĕy֤ẇ bĕ⁠ʻéynáy⁠w֙ kĕ̇⁠yámi֣ym ʼàẖádi֔ym bĕ̇⁠ʼahàbáţ֖⁠wò ʼòţáֽ⁠ḣ׃"],[29,21,"וַ⁠יֹּ֨אמֶר יַעֲקֹ֤ב אֶל־לָבָן֙ הָבָ֣⁠ה אֶת־אִשְׁתִּ֔⁠י כִּ֥י מָלְא֖וּ יָמָ֑⁠י וְ⁠אָב֖וֹאָה אֵלֶֽי⁠הָ׃","wa⁠yò̇֨ʼmer yaʻàqò֤b ʼel-lábán֙ hábá֣⁠h ʼeţ-ʼişĕ̌ţi̇֔⁠y ki֥̇y málĕʼ֖ẇ yámá֑⁠y wĕ⁠ʼáb֖wòʼáh ʼéleֽy⁠há׃"],[29,22,"וַ⁠יֶּאֱסֹ֥ף לָבָ֛ן אֶת־כָּל־אַנְשֵׁ֥י הַ⁠מָּק֖וֹם וַ⁠יַּ֥עַשׂ מִשְׁתֶּֽה׃","wa⁠yėʼèsò֥p lábá֛n ʼeţ-ká̇l-ʼanĕşé֥̌y ha⁠má̇q֖wòm wa⁠yȧ֥ʻaş̂ mişĕ̌ţėֽh׃"],[29,23,"וַ⁠יְהִ֣י בָ⁠עֶ֔רֶב וַ⁠יִּקַּח֙ אֶת־לֵאָ֣ה בִתּ֔⁠וֹ וַ⁠יָּבֵ֥א אֹתָ֖⁠הּ אֵלָ֑י⁠ו וַ⁠יָּבֹ֖א אֵלֶֽי⁠הָ׃","wa⁠yĕhi֣y bá⁠ʻe֔reb wa⁠yi̇qȧẖ֙ ʼeţ-léʼá֣h biţ̇֔⁠wò wa⁠yá̇bé֥ʼ ʼòţá֖⁠ḣ ʼélá֑y⁠w wa⁠yá̇bò֖ʼ ʼéleֽy⁠há׃"],[29,24,"וַ⁠יִּתֵּ֤ן לָבָן֙ לָ֔⁠הּ אֶת־זִלְפָּ֖ה שִׁפְחָת֑⁠וֹ לְ⁠לֵאָ֥ה בִתּ֖⁠וֹ שִׁפְחָֽה׃","wa⁠yi̇ţé֤̇n lábán֙ lá֔⁠ḣ ʼeţ-zilĕpá֖̇h şǐpĕẖáţ֑⁠wò lĕ⁠léʼá֥h biţ֖̇⁠wò şǐpĕẖáֽh׃"],[29,25,"וַ⁠יְהִ֣י בַ⁠בֹּ֔קֶר וְ⁠הִנֵּה־הִ֖וא לֵאָ֑ה וַ⁠יֹּ֣אמֶר אֶל־לָבָ֗ן מַה־זֹּאת֙ עָשִׂ֣יתָ לִּ֔⁠י הֲ⁠לֹ֤א בְ⁠רָחֵל֙ עָבַ֣דְתִּי עִמָּ֔⁠ךְ וְ⁠לָ֖⁠מָּה רִמִּיתָֽ⁠נִי׃","wa⁠yĕhi֣y ba⁠bò̇֔qer wĕ⁠hiné̇h-hi֖wʼ léʼá֑h wa⁠yò֣̇ʼmer ʼel-lábá֗n mah-zò̇ʼţ֙ ʻáşî֣yţá li̇֔⁠y hà⁠lò֤ʼ bĕ⁠ráẖél֙ ʻába֣dĕţi̇y ʻimá̇֔⁠kĕ wĕ⁠lá֖⁠má̇h rimi̇yţáֽ⁠niy׃"],[29,26,"וַ⁠יֹּ֣אמֶר לָבָ֔ן לֹא־יֵעָשֶׂ֥ה כֵ֖ן בִּ⁠מְקוֹמֵ֑⁠נוּ לָ⁠תֵ֥ת הַ⁠צְּעִירָ֖ה לִ⁠פְנֵ֥י הַ⁠בְּכִירָֽה׃","wa⁠yò֣̇ʼmer lábá֔n lòʼ-yéʻáşê֥h ké֖n bi̇⁠mĕqwòmé֑⁠nẇ lá⁠ţé֥ţ ha⁠ẕĕ̇ʻiyrá֖h li⁠pĕné֥y ha⁠bĕ̇kiyráֽh׃"],[29,27,"מַלֵּ֖א שְׁבֻ֣עַ זֹ֑את וְ⁠נִתְּנָ֨ה לְ⁠ךָ֜ גַּם־אֶת־זֹ֗את בַּ⁠עֲבֹדָה֙ אֲשֶׁ֣ר תַּעֲבֹ֣ד עִמָּדִ֔⁠י ע֖וֹד שֶֽׁבַע־שָׁנִ֥ים אֲחֵרֽוֹת׃","malé֖̇ʼ şĕ̌bu֣ʻa zò֑ʼţ wĕ⁠niţĕ̇ná֨h lĕ⁠ká֜ gȧm-ʼeţ-zò֗ʼţ bȧ⁠ʻàbòdáh֙ ʼàşě֣r ţȧʻàbò֣d ʻimá̇di֔⁠y ʻ֖wòd şěֽbaʻ-şá̌ni֥ym ʼàẖérֽwòţ׃"],[29,28,"וַ⁠יַּ֤עַשׂ יַעֲקֹב֙ כֵּ֔ן וַ⁠יְמַלֵּ֖א שְׁבֻ֣עַ זֹ֑את וַ⁠יִּתֶּן־ל֛⁠וֹ אֶת־רָחֵ֥ל בִּתּ֖⁠וֹ ל֥⁠וֹ לְ⁠אִשָּֽׁה׃","wa⁠yȧ֤ʻaş̂ yaʻàqòb֙ ké̇֔n wa⁠yĕmalé֖̇ʼ şĕ̌bu֣ʻa zò֑ʼţ wa⁠yi̇ţėn-l֛⁠wò ʼeţ-ráẖé֥l bi̇ţ֖̇⁠wò l֥⁠wò lĕ⁠ʼişáֽ̇̌h׃"],[29,29,"וַ⁠יִּתֵּ֤ן לָבָן֙ לְ⁠רָחֵ֣ל בִּתּ֔⁠וֹ אֶת־בִּלְהָ֖ה שִׁפְחָת֑⁠וֹ לָ֖⁠הּ לְ⁠שִׁפְחָֽה׃","wa⁠yi̇ţé֤̇n lábán֙ lĕ⁠ráẖé֣l bi̇ţ̇֔⁠wò ʼeţ-bi̇lĕhá֖h şǐpĕẖáţ֑⁠wò lá֖⁠ḣ lĕ⁠şǐpĕẖáֽh׃"],[29,30,"וַ⁠יָּבֹא֙ גַּ֣ם אֶל־רָחֵ֔ל וַ⁠יֶּאֱהַ֥ב גַּֽם־אֶת־רָחֵ֖ל מִ⁠לֵּאָ֑ה וַ⁠יַּעֲבֹ֣ד עִמּ֔⁠וֹ ע֖וֹד שֶֽׁבַע־שָׁנִ֥ים אֲחֵרֽוֹת׃","wa⁠yá̇bòʼ֙ gȧ֣m ʼel-ráẖé֔l wa⁠yėʼèha֥b gȧֽm-ʼeţ-ráẖé֖l mi⁠lé̇ʼá֑h wa⁠yȧʻàbò֣d ʻiṁ֔⁠wò ʻ֖wòd şěֽbaʻ-şá̌ni֥ym ʼàẖérֽwòţ׃"],[29,31,"וַ⁠יַּ֤רְא יְהוָה֙ כִּֽי־שְׂנוּאָ֣ה לֵאָ֔ה וַ⁠יִּפְתַּ֖ח אֶת־רַחְמָ֑⁠הּ וְ⁠רָחֵ֖ל עֲקָרָֽה׃","wa⁠yȧ֤rĕʼ yĕhwáh֙ kiֽ̇y-şĕ̂nẇʼá֣h léʼá֔h wa⁠yi̇pĕţȧ֖ẖ ʼeţ-raẖĕmá֑⁠ḣ wĕ⁠ráẖé֖l ʻàqáráֽh׃"],[29,32,"וַ⁠תַּ֤הַר לֵאָה֙ וַ⁠תֵּ֣לֶד בֵּ֔ן וַ⁠תִּקְרָ֥א שְׁמ֖⁠וֹ רְאוּבֵ֑ן כִּ֣י אָֽמְרָ֗ה כִּֽי־רָאָ֤ה יְהוָה֙ בְּ⁠עָנְיִ֔⁠י כִּ֥י עַתָּ֖ה יֶאֱהָבַ֥⁠נִי אִישִֽׁ⁠י׃","wa⁠ţȧ֤har léʼáh֙ wa⁠ţé֣̇led bé̇֔n wa⁠ţi̇qĕrá֥ʼ şĕ̌m֖⁠wò rĕʼẇbé֑n ki֣̇y ʼáֽmĕrá֗h kiֽ̇y-ráʼá֤h yĕhwáh֙ bĕ̇⁠ʻánĕyi֔⁠y ki֥̇y ʻaţá֖̇h yeʼèhába֥⁠niy ʼiyşǐֽ⁠y׃"],[29,33,"וַ⁠תַּ֣הַר עוֹד֮ וַ⁠תֵּ֣לֶד בֵּן֒ וַ⁠תֹּ֗אמֶר כִּֽי־שָׁמַ֤ע יְהוָה֙ כִּֽי־שְׂנוּאָ֣ה אָנֹ֔כִי וַ⁠יִּתֶּן־לִ֖⁠י גַּם־אֶת־זֶ֑ה וַ⁠תִּקְרָ֥א שְׁמ֖⁠וֹ שִׁמְעֽוֹן׃","wa⁠ţȧ֣har ʻwòd֮ wa⁠ţé֣̇led bé̇n֒ wa⁠ţò̇֗ʼmer kiֽ̇y-şá̌ma֤ʻ yĕhwáh֙ kiֽ̇y-şĕ̂nẇʼá֣h ʼánò֔kiy wa⁠yi̇ţėn-li֖⁠y gȧm-ʼeţ-ze֑h wa⁠ţi̇qĕrá֥ʼ şĕ̌m֖⁠wò şǐmĕʻֽwòn׃"],[29,34,"וַ⁠תַּ֣הַר עוֹד֮ וַ⁠תֵּ֣לֶד בֵּן֒ וַ⁠תֹּ֗אמֶר עַתָּ֤ה הַ⁠פַּ֨עַם֙ יִלָּוֶ֤ה אִישִׁ⁠י֙ אֵלַ֔⁠י כִּֽי־יָלַ֥דְתִּי ל֖⁠וֹ שְׁלֹשָׁ֣ה בָנִ֑ים עַל־כֵּ֥ן קָרָֽא־שְׁמ֖⁠וֹ לֵוִֽי׃","wa⁠ţȧ֣har ʻwòd֮ wa⁠ţé֣̇led bé̇n֒ wa⁠ţò̇֗ʼmer ʻaţá֤̇h ha⁠pȧ֨ʻam֙ yilá̇we֤h ʼiyşǐ⁠y֙ ʼéla֔⁠y kiֽ̇y-yála֥dĕţi̇y l֖⁠wò şĕ̌lòşá֣̌h báni֑ym ʻal-ké֥̇n qáráֽʼ-şĕ̌m֖⁠wò léwiֽy׃"],[29,35,"וַ⁠תַּ֨הַר ע֜וֹד וַ⁠תֵּ֣לֶד בֵּ֗ן וַ⁠תֹּ֨אמֶר֙ הַ⁠פַּ֨עַם֙ אוֹדֶ֣ה אֶת־יְהוָ֔ה עַל־כֵּ֛ן קָרְאָ֥ה שְׁמ֖⁠וֹ יְהוּדָ֑ה וַֽ⁠תַּעֲמֹ֖ד מִ⁠לֶּֽדֶת׃","wa⁠ţȧ֨har ʻ֜wòd wa⁠ţé֣̇led bé̇֗n wa⁠ţò̇֨ʼmer֙ ha⁠pȧ֨ʻam֙ ʼwòde֣h ʼeţ-yĕhwá֔h ʻal-ké֛̇n qárĕʼá֥h şĕ̌m֖⁠wò yĕhẇdá֑h waֽ⁠ţȧʻàmò֖d mi⁠lėֽdeţ׃"],[30,1,"וַ⁠תֵּ֣רֶא רָחֵ֗ל כִּ֣י לֹ֤א יָֽלְדָה֙ לְ⁠יַעֲקֹ֔ב וַ⁠תְּקַנֵּ֥א רָחֵ֖ל בַּ⁠אֲחֹתָ֑⁠הּ וַ⁠תֹּ֤אמֶר אֶֽל־יַעֲקֹב֙ הָֽבָ⁠ה־לִּ֣⁠י בָנִ֔ים וְ⁠אִם־אַ֖יִן מֵתָ֥ה אָנֹֽכִי׃","wa⁠ţé֣̇reʼ ráẖé֗l ki֣̇y lò֤ʼ yáֽlĕdáh֙ lĕ⁠yaʻàqò֔b wa⁠ţĕ̇qané֥̇ʼ ráẖé֖l bȧ⁠ʼàẖòţá֑⁠ḣ wa⁠ţò֤̇ʼmer ʼeֽl-yaʻàqòb֙ háֽbá⁠h-li֣̇⁠y báni֔ym wĕ⁠ʼim-ʼa֖yin méţá֥h ʼánòֽkiy׃"],[30,2,"וַ⁠יִּֽחַר־אַ֥ף יַעֲקֹ֖ב בְּ⁠רָחֵ֑ל וַ⁠יֹּ֗אמֶר הֲ⁠תַ֤חַת אֱלֹהִים֙ אָנֹ֔כִי אֲשֶׁר־מָנַ֥ע מִמֵּ֖⁠ךְ פְּרִי־בָֽטֶן׃","wa⁠yiֽ̇ẖar-ʼa֥p yaʻàqò֖b bĕ̇⁠ráẖé֑l wa⁠yò̇֗ʼmer hà⁠ţa֤ẖaţ ʼèlòhiym֙ ʼánò֔kiy ʼàşěr-mána֥ʻ mimé֖̇⁠kĕ pĕ̇riy-báֽten׃"],[30,3,"וַ⁠תֹּ֕אמֶר הִנֵּ֛ה אֲמָתִ֥⁠י בִלְהָ֖ה בֹּ֣א אֵלֶ֑י⁠הָ וְ⁠תֵלֵד֙ עַל־בִּרְכַּ֔⁠י וְ⁠אִבָּנֶ֥ה גַם־אָנֹכִ֖י מִמֶּֽ⁠נָּה׃","wa⁠ţò̇֕ʼmer hiné֛̇h ʼàmáţi֥⁠y bilĕhá֖h bò֣̇ʼ ʼéle֑y⁠há wĕ⁠ţéléd֙ ʻal-bi̇rĕkȧ֔⁠y wĕ⁠ʼibá̇ne֥h gam-ʼánòki֖y mimėֽ⁠ná̇h׃"],[30,4,"וַ⁠תִּתֶּן־ל֛⁠וֹ אֶת־בִּלְהָ֥ה שִׁפְחָתָ֖⁠הּ לְ⁠אִשָּׁ֑ה וַ⁠יָּבֹ֥א אֵלֶ֖י⁠הָ יַעֲקֹֽב׃","wa⁠ţi̇ţėn-l֛⁠wò ʼeţ-bi̇lĕhá֥h şǐpĕẖáţá֖⁠ḣ lĕ⁠ʼişá֑̇̌h wa⁠yá̇bò֥ʼ ʼéle֖y⁠há yaʻàqòֽb׃"],[30,5,"וַ⁠תַּ֣הַר בִּלְהָ֔ה וַ⁠תֵּ֥לֶד לְ⁠יַעֲקֹ֖ב בֵּֽן׃","wa⁠ţȧ֣har bi̇lĕhá֔h wa⁠ţé֥̇led lĕ⁠yaʻàqò֖b béֽ̇n׃"],[30,6,"וַ⁠תֹּ֤אמֶר רָחֵל֙ דָּנַ֣⁠נִּי אֱלֹהִ֔ים וְ⁠גַם֙ שָׁמַ֣ע בְּ⁠קֹלִ֔⁠י וַ⁠יִּתֶּן־לִ֖⁠י בֵּ֑ן עַל־כֵּ֛ן קָרְאָ֥ה שְׁמ֖⁠וֹ דָּֽן׃","wa⁠ţò֤̇ʼmer ráẖél֙ dá̇na֣⁠ni̇y ʼèlòhi֔ym wĕ⁠gam֙ şá̌ma֣ʻ bĕ̇⁠qòli֔⁠y wa⁠yi̇ţėn-li֖⁠y bé֑̇n ʻal-ké֛̇n qárĕʼá֥h şĕ̌m֖⁠wò dáֽ̇n׃"],[30,7,"וַ⁠תַּ֣הַר ע֔וֹד וַ⁠תֵּ֕לֶד בִּלְהָ֖ה שִׁפְחַ֣ת רָחֵ֑ל בֵּ֥ן שֵׁנִ֖י לְ⁠יַעֲקֹֽב׃","wa⁠ţȧ֣har ʻ֔wòd wa⁠ţé̇֕led bi̇lĕhá֖h şǐpĕẖa֣ţ ráẖé֑l bé֥̇n şé̌ni֖y lĕ⁠yaʻàqòֽb׃"],[30,8,"וַ⁠תֹּ֣אמֶר רָחֵ֗ל נַפְתּוּלֵ֨י אֱלֹהִ֧ים ׀ נִפְתַּ֛לְתִּי עִם־אֲחֹתִ֖⁠י גַּם־יָכֹ֑לְתִּי וַ⁠תִּקְרָ֥א שְׁמ֖⁠וֹ נַפְתָּלִֽי׃","wa⁠ţò֣̇ʼmer ráẖé֗l napĕţ̇ẇlé֨y ʼèlòhi֧ym ׀ nipĕţȧ֛lĕţi̇y ʻim-ʼàẖòţi֖⁠y gȧm-yákò֑lĕţi̇y wa⁠ţi̇qĕrá֥ʼ şĕ̌m֖⁠wò napĕţá̇liֽy׃"],[30,9,"וַ⁠תֵּ֣רֶא לֵאָ֔ה כִּ֥י עָמְדָ֖ה מִ⁠לֶּ֑דֶת וַ⁠תִּקַּח֙ אֶת־זִלְפָּ֣ה שִׁפְחָתָ֔⁠הּ וַ⁠תִּתֵּ֥ן אֹתָ֛⁠הּ לְ⁠יַעֲקֹ֖ב לְ⁠אִשָּֽׁה׃","wa⁠ţé֣̇reʼ léʼá֔h ki֥̇y ʻámĕdá֖h mi⁠lė֑deţ wa⁠ţi̇qȧẖ֙ ʼeţ-zilĕpá֣̇h şǐpĕẖáţá֔⁠ḣ wa⁠ţi̇ţé֥̇n ʼòţá֛⁠ḣ lĕ⁠yaʻàqò֖b lĕ⁠ʼişáֽ̇̌h׃"],[30,10,"וַ⁠תֵּ֗לֶד זִלְפָּ֛ה שִׁפְחַ֥ת לֵאָ֖ה לְ⁠יַעֲקֹ֥ב בֵּֽן׃","wa⁠ţé̇֗led zilĕpá֛̇h şǐpĕẖa֥ţ léʼá֖h lĕ⁠yaʻàqò֥b béֽ̇n׃"],[30,11,"וַ⁠תֹּ֥אמֶר לֵאָ֖ה ב⁠גד וַ⁠תִּקְרָ֥א אֶת־שְׁמ֖⁠וֹ גָּֽד׃","wa⁠ţò֥̇ʼmer léʼá֖h b⁠gd wa⁠ţi̇qĕrá֥ʼ ʼeţ-şĕ̌m֖⁠wò gáֽ̇d׃"],[30,12,"וַ⁠תֵּ֗לֶד זִלְפָּה֙ שִׁפְחַ֣ת לֵאָ֔ה בֵּ֥ן שֵׁנִ֖י לְ⁠יַעֲקֹֽב׃","wa⁠ţé̇֗led zilĕpá̇h֙ şǐpĕẖa֣ţ léʼá֔h bé֥̇n şé̌ni֖y lĕ⁠yaʻàqòֽb׃"],[30,13,"וַ⁠תֹּ֣אמֶר לֵאָ֔ה בְּ⁠אָשְׁרִ֕⁠י כִּ֥י אִשְּׁר֖וּ⁠נִי בָּנ֑וֹת וַ⁠תִּקְרָ֥א אֶת־שְׁמ֖⁠וֹ אָשֵֽׁר׃","wa⁠ţò֣̇ʼmer léʼá֔h bĕ̇⁠ʼáşĕ̌ri֕⁠y ki֥̇y ʼişĕ̇̌r֖ẇ⁠niy bá̇n֑wòţ wa⁠ţi̇qĕrá֥ʼ ʼeţ-şĕ̌m֖⁠wò ʼáşéֽ̌r׃"],[30,14,"וַ⁠יֵּ֨לֶךְ רְאוּבֵ֜ן בִּ⁠ימֵ֣י קְצִיר־חִטִּ֗ים וַ⁠יִּמְצָ֤א דֽוּדָאִים֙ בַּ⁠שָּׂדֶ֔ה וַ⁠יָּבֵ֣א אֹתָ֔⁠ם אֶל־לֵאָ֖ה אִמּ֑⁠וֹ וַ⁠תֹּ֤אמֶר רָחֵל֙ אֶל־לֵאָ֔ה תְּנִי־נָ֣א לִ֔⁠י מִ⁠דּוּדָאֵ֖י בְּנֵֽ⁠ךְ׃","wa⁠yé̇֨lekĕ rĕʼẇbé֜n bi̇⁠ymé֣y qĕẕiyr-ẖiti̇֗ym wa⁠yi̇mĕẕá֤ʼ dֽẇdáʼiym֙ bȧ⁠şá̇̂de֔h wa⁠yá̇bé֣ʼ ʼòţá֔⁠m ʼel-léʼá֖h ʼiṁ֑⁠wò wa⁠ţò֤̇ʼmer ráẖél֙ ʼel-léʼá֔h ţĕ̇niy-ná֣ʼ li֔⁠y mi⁠ḋẇdáʼé֖y bĕ̇néֽ⁠kĕ׃"],[30,15,"וַ⁠תֹּ֣אמֶר לָ֗⁠הּ הַ⁠מְעַט֙ קַחְתֵּ֣⁠ךְ אֶת־אִישִׁ֔⁠י וְ⁠לָ⁠קַ֕חַת גַּ֥ם אֶת־דּוּדָאֵ֖י בְּנִ֑⁠י וַ⁠תֹּ֣אמֶר רָחֵ֗ל לָ⁠כֵן֙ יִשְׁכַּ֤ב עִמָּ⁠ךְ֙ הַ⁠לַּ֔יְלָה תַּ֖חַת דּוּדָאֵ֥י בְנֵֽ⁠ךְ׃","wa⁠ţò֣̇ʼmer lá֗⁠ḣ ha⁠mĕʻat֙ qaẖĕţé֣̇⁠kĕ ʼeţ-ʼiyşǐ֔⁠y wĕ⁠lá⁠qa֕ẖaţ gȧ֥m ʼeţ-ḋẇdáʼé֖y bĕ̇ni֑⁠y wa⁠ţò֣̇ʼmer ráẖé֗l lá⁠kén֙ yişĕ̌kȧ֤b ʻimá̇⁠kĕ֙ ha⁠lȧ֔yĕláh ţȧ֖ẖaţ ḋẇdáʼé֥y bĕnéֽ⁠kĕ׃"],[30,16,"וַ⁠יָּבֹ֨א יַעֲקֹ֣ב מִן־הַ⁠שָּׂדֶה֮ בָּ⁠עֶרֶב֒ וַ⁠תֵּצֵ֨א לֵאָ֜ה לִ⁠קְרָאת֗⁠וֹ וַ⁠תֹּ֨אמֶר֙ אֵלַ֣⁠י תָּב֔וֹא כִּ֚י שָׂכֹ֣ר שְׂכַרְתִּ֔י⁠ךָ בְּ⁠דוּדָאֵ֖י בְּנִ֑⁠י וַ⁠יִּשְׁכַּ֥ב עִמָּ֖⁠הּ בַּ⁠לַּ֥יְלָה הֽוּא׃","wa⁠yá̇bò֨ʼ yaʻàqò֣b min-ha⁠şá̇̂deh֮ bá̇⁠ʻereb֒ wa⁠ţé̇ẕé֨ʼ léʼá֜h li⁠qĕráʼţ֗⁠wò wa⁠ţò̇֨ʼmer֙ ʼéla֣⁠y ţá̇b֔wòʼ ki֚̇y şá̂kò֣r şĕ̂karĕţi̇֔y⁠ká bĕ̇⁠dẇdáʼé֖y bĕ̇ni֑⁠y wa⁠yi̇şĕ̌kȧ֥b ʻimá֖̇⁠ḣ bȧ⁠lȧ֥yĕláh hֽẇʼ׃"],[30,17,"וַ⁠יִּשְׁמַ֥ע אֱלֹהִ֖ים אֶל־לֵאָ֑ה וַ⁠תַּ֛הַר וַ⁠תֵּ֥לֶד לְ⁠יַעֲקֹ֖ב בֵּ֥ן חֲמִישִֽׁי׃","wa⁠yi̇şĕ̌ma֥ʻ ʼèlòhi֖ym ʼel-léʼá֑h wa⁠ţȧ֛har wa⁠ţé֥̇led lĕ⁠yaʻàqò֖b bé֥̇n ẖàmiyşǐֽy׃"],[30,18,"וַ⁠תֹּ֣אמֶר לֵאָ֗ה נָתַ֤ן אֱלֹהִים֙ שְׂכָרִ֔⁠י אֲשֶׁר־נָתַ֥תִּי שִׁפְחָתִ֖⁠י לְ⁠אִישִׁ֑⁠י וַ⁠תִּקְרָ֥א שְׁמ֖⁠וֹ יִשָּׂשכָֽר׃","wa⁠ţò֣̇ʼmer léʼá֗h náţa֤n ʼèlòhiym֙ şĕ̂kári֔⁠y ʼàşěr-náţa֥ţi̇y şǐpĕẖáţi֖⁠y lĕ⁠ʼiyşǐ֑⁠y wa⁠ţi̇qĕrá֥ʼ şĕ̌m֖⁠wò yişá̇̂şkáֽr׃"],[30,19,"וַ⁠תַּ֤הַר עוֹד֙ לֵאָ֔ה וַ⁠תֵּ֥לֶד בֵּן־שִׁשִּׁ֖י לְּ⁠יַעֲקֹֽב׃","wa⁠ţȧ֤har ʻwòd֙ léʼá֔h wa⁠ţé֥̇led bé̇n-şǐşi֖̇̌y lĕ̇⁠yaʻàqòֽb׃"],[30,20,"וַ⁠תֹּ֣אמֶר לֵאָ֗ה זְבָדַ֨⁠נִי אֱלֹהִ֥ים ׀ אֹתִ⁠י֮ זֵ֣בֶד טוֹב֒ הַ⁠פַּ֨עַם֙ יִזְבְּלֵ֣⁠נִי אִישִׁ֔⁠י כִּֽי־יָלַ֥דְתִּי ל֖⁠וֹ שִׁשָּׁ֣ה בָנִ֑ים וַ⁠תִּקְרָ֥א אֶת־שְׁמ֖⁠וֹ זְבֻלֽוּן׃","wa⁠ţò֣̇ʼmer léʼá֗h zĕbáda֨⁠niy ʼèlòhi֥ym ׀ ʼòţi⁠y֮ zé֣bed twòb֒ ha⁠pȧ֨ʻam֙ yizĕbĕ̇lé֣⁠niy ʼiyşǐ֔⁠y kiֽ̇y-yála֥dĕţi̇y l֖⁠wò şǐşá֣̇̌h báni֑ym wa⁠ţi̇qĕrá֥ʼ ʼeţ-şĕ̌m֖⁠wò zĕbulֽẇn׃"],[30,21,"וְ⁠אַחַ֖ר יָ֣לְדָה בַּ֑ת וַ⁠תִּקְרָ֥א אֶת־שְׁמָ֖⁠הּ דִּינָֽה׃","wĕ⁠ʼaẖa֖r yá֣lĕdáh bȧ֑ţ wa⁠ţi̇qĕrá֥ʼ ʼeţ-şĕ̌má֖⁠ḣ di̇ynáֽh׃"],[30,22,"וַ⁠יִּזְכֹּ֥ר אֱלֹהִ֖ים אֶת־רָחֵ֑ל וַ⁠יִּשְׁמַ֤ע אֵלֶ֨י⁠הָ֙ אֱלֹהִ֔ים וַ⁠יִּפְתַּ֖ח אֶת־רַחְמָֽ⁠הּ׃","wa⁠yi̇zĕkò֥̇r ʼèlòhi֖ym ʼeţ-ráẖé֑l wa⁠yi̇şĕ̌ma֤ʻ ʼéle֨y⁠há֙ ʼèlòhi֔ym wa⁠yi̇pĕţȧ֖ẖ ʼeţ-raẖĕmáֽ⁠ḣ׃"],[30,23,"וַ⁠תַּ֖הַר וַ⁠תֵּ֣לֶד בֵּ֑ן וַ⁠תֹּ֕אמֶר אָסַ֥ף אֱלֹהִ֖ים אֶת־חֶרְפָּתִֽ⁠י׃","wa⁠ţȧ֖har wa⁠ţé֣̇led bé֑̇n wa⁠ţò̇֕ʼmer ʼása֥p ʼèlòhi֖ym ʼeţ-ẖerĕpá̇ţiֽ⁠y׃"],[30,24,"וַ⁠תִּקְרָ֧א אֶת־שְׁמ֛⁠וֹ יוֹסֵ֖ף לֵ⁠אמֹ֑ר יֹסֵ֧ף יְהוָ֛ה לִ֖⁠י בֵּ֥ן אַחֵֽר׃","wa⁠ţi̇qĕrá֧ʼ ʼeţ-şĕ̌m֛⁠wò ywòsé֖p lé⁠ʼmò֑r yòsé֧p yĕhwá֛h li֖⁠y bé֥̇n ʼaẖéֽr׃"],[30,25,"וַ⁠יְהִ֕י כַּ⁠אֲשֶׁ֛ר יָלְדָ֥ה רָחֵ֖ל אֶת־יוֹסֵ֑ף וַ⁠יֹּ֤אמֶר יַעֲקֹב֙ אֶל־לָבָ֔ן שַׁלְּחֵ֨⁠נִי֙ וְ⁠אֵ֣לְכָ֔ה אֶל־מְקוֹמִ֖⁠י וּ⁠לְ⁠אַרְצִֽ⁠י׃","wa⁠yĕhi֕y kȧ⁠ʼàşě֛r yálĕdá֥h ráẖé֖l ʼeţ-ywòsé֑p wa⁠yò֤̇ʼmer yaʻàqòb֙ ʼel-lábá֔n şǎlĕ̇ẖé֨⁠niy֙ wĕ⁠ʼé֣lĕká֔h ʼel-mĕqwòmi֖⁠y ẇ⁠lĕ⁠ʼarĕẕiֽ⁠y׃"],[30,26,"תְּנָ֞⁠ה אֶת־נָשַׁ֣⁠י וְ⁠אֶת־יְלָדַ֗⁠י אֲשֶׁ֨ר עָבַ֧דְתִּי אֹֽתְ⁠ךָ֛ בָּ⁠הֵ֖ן וְ⁠אֵלֵ֑כָה כִּ֚י אַתָּ֣ה יָדַ֔עְתָּ אֶת־עֲבֹדָתִ֖⁠י אֲשֶׁ֥ר עֲבַדְתִּֽי⁠ךָ׃","ţĕ̇ná֞⁠h ʼeţ-náşǎ֣⁠y wĕ⁠ʼeţ-yĕláda֗⁠y ʼàşě֨r ʻába֧dĕţi̇y ʼòֽţĕ⁠ká֛ bá̇⁠hé֖n wĕ⁠ʼélé֑káh ki֚̇y ʼaţá֣̇h yáda֔ʻĕţá̇ ʼeţ-ʻàbòdáţi֖⁠y ʼàşě֥r ʻàbadĕţiֽ̇y⁠ká׃"],[30,27,"וַ⁠יֹּ֤אמֶר אֵלָי⁠ו֙ לָבָ֔ן אִם־נָ֛א מָצָ֥אתִי חֵ֖ן בְּ⁠עֵינֶ֑י⁠ךָ נִחַ֕שְׁתִּי וַ⁠יְבָרֲכֵ֥⁠נִי יְהוָ֖ה בִּ⁠גְלָלֶֽ⁠ךָ׃","wa⁠yò֤̇ʼmer ʼéláy⁠w֙ lábá֔n ʼim-ná֛ʼ máẕá֥ʼţiy ẖé֖n bĕ̇⁠ʻéyne֑y⁠ká niẖa֕şĕ̌ţi̇y wa⁠yĕbáràké֥⁠niy yĕhwá֖h bi̇⁠gĕláleֽ⁠ká׃"],[30,28,"וַ⁠יֹּאמַ֑ר נָקְבָ֧⁠ה שְׂכָרְ⁠ךָ֛ עָלַ֖⁠י וְ⁠אֶתֵּֽנָה׃","wa⁠yò̇ʼma֑r náqĕbá֧⁠h şĕ̂kárĕ⁠ká֛ ʻála֖⁠y wĕ⁠ʼeţéֽ̇náh׃"],[30,29,"וַ⁠יֹּ֣אמֶר אֵלָ֔י⁠ו אַתָּ֣ה יָדַ֔עְתָּ אֵ֖ת אֲשֶׁ֣ר עֲבַדְתִּ֑י⁠ךָ וְ⁠אֵ֛ת אֲשֶׁר־הָיָ֥ה מִקְנְ⁠ךָ֖ אִתִּֽ⁠י׃","wa⁠yò֣̇ʼmer ʼélá֔y⁠w ʼaţá֣̇h yáda֔ʻĕţá̇ ʼé֖ţ ʼàşě֣r ʻàbadĕţi֑̇y⁠ká wĕ⁠ʼé֛ţ ʼàşěr-háyá֥h miqĕnĕ⁠ká֖ ʼiţiֽ̇⁠y׃"],[30,30,"כִּ֡י מְעַט֩ אֲשֶׁר־הָיָ֨ה לְ⁠ךָ֤ לְ⁠פָנַ⁠י֙ וַ⁠יִּפְרֹ֣ץ לָ⁠רֹ֔ב וַ⁠יְבָ֧רֶךְ יְהוָ֛ה אֹתְ⁠ךָ֖ לְ⁠רַגְלִ֑⁠י וְ⁠עַתָּ֗ה מָתַ֛י אֶֽעֱשֶׂ֥ה גַם־אָנֹכִ֖י לְ⁠בֵיתִֽ⁠י׃","ki̇֡y mĕʻat֩ ʼàşěr-háyá֨h lĕ⁠ká֤ lĕ⁠pána⁠y֙ wa⁠yi̇pĕrò֣ẕ lá⁠rò֔b wa⁠yĕbá֧rekĕ yĕhwá֛h ʼòţĕ⁠ká֖ lĕ⁠ragĕli֑⁠y wĕ⁠ʻaţá̇֗h máţa֛y ʼֽeʻèşê֥h gam-ʼánòki֖y lĕ⁠béyţiֽ⁠y׃"],[30,31,"וַ⁠יֹּ֖אמֶר מָ֣ה אֶתֶּן־לָ֑⁠ךְ וַ⁠יֹּ֤אמֶר יַעֲקֹב֙ לֹא־תִתֶּן־לִ֣⁠י מְא֔וּמָה אִם־תַּֽעֲשֶׂה־לִּ⁠י֙ הַ⁠דָּבָ֣ר הַ⁠זֶּ֔ה אָשׁ֛וּבָה אֶרְעֶ֥ה צֹֽאנְ⁠ךָ֖ אֶשְׁמֹֽר׃","wa⁠yò֖̇ʼmer má֣h ʼeţėn-lá֑⁠kĕ wa⁠yò֤̇ʼmer yaʻàqòb֙ lòʼ-ţiţėn-li֣⁠y mĕʼ֔ẇmáh ʼim-ţֽ̇aʻàşêh-li̇⁠y֙ ha⁠dá̇bá֣r ha⁠zė֔h ʼáş֛̌ẇbáh ʼerĕʻe֥h ẕòֽʼnĕ⁠ká֖ ʼeşĕ̌mòֽr׃"],[30,32,"אֶֽעֱבֹ֨ר בְּ⁠כָל־צֹֽאנְ⁠ךָ֜ הַ⁠יּ֗וֹם הָסֵ֨ר מִ⁠שָּׁ֜ם כָּל־שֶׂ֣ה ׀ נָקֹ֣ד וְ⁠טָל֗וּא וְ⁠כָל־שֶׂה־חוּם֙ בַּ⁠כְּשָׂבִ֔ים וְ⁠טָל֥וּא וְ⁠נָקֹ֖ד בָּ⁠עִזִּ֑ים וְ⁠הָיָ֖ה שְׂכָרִֽ⁠י׃","ʼֽeʻèbò֨r bĕ̇⁠kál-ẕòֽʼnĕ⁠ká֜ ha⁠ẏ֗wòm hásé֨r mi⁠şá̇̌֜m ká̇l-şê֣h ׀ náqò֣d wĕ⁠tál֗ẇʼ wĕ⁠kál-şêh-ẖẇm֙ bȧ⁠kĕ̇şá̂bi֔ym wĕ⁠tál֥ẇʼ wĕ⁠náqò֖d bá̇⁠ʻizi֑̇ym wĕ⁠háyá֖h şĕ̂káriֽ⁠y׃"],[30,33,"וְ⁠עָֽנְתָה־בִּ֤⁠י צִדְקָתִ⁠י֙ בְּ⁠י֣וֹם מָחָ֔ר כִּֽי־תָב֥וֹא עַל־שְׂכָרִ֖⁠י לְ⁠פָנֶ֑י⁠ךָ כֹּ֣ל אֲשֶׁר־אֵינֶ⁠נּוּ֩ נָקֹ֨ד וְ⁠טָל֜וּא בָּֽ⁠עִזִּ֗ים וְ⁠חוּם֙ בַּ⁠כְּשָׂבִ֔ים גָּנ֥וּב ה֖וּא אִתִּֽ⁠י׃","wĕ⁠ʻáֽnĕţáh-bi֤̇⁠y ẕidĕqáţi⁠y֙ bĕ̇⁠y֣wòm máẖá֔r kiֽ̇y-ţáb֥wòʼ ʻal-şĕ̂kári֖⁠y lĕ⁠páne֑y⁠ká kò֣̇l ʼàşěr-ʼéyne⁠ṅẇ֩ náqò֨d wĕ⁠tál֜ẇʼ báֽ̇⁠ʻizi̇֗ym wĕ⁠ẖẇm֙ bȧ⁠kĕ̇şá̂bi֔ym gá̇n֥ẇb h֖ẇʼ ʼiţiֽ̇⁠y׃"],[30,34,"וַ⁠יֹּ֥אמֶר לָבָ֖ן הֵ֑ן ל֖וּ יְהִ֥י כִ⁠דְבָרֶֽ⁠ךָ׃","wa⁠yò֥̇ʼmer lábá֖n hé֑n l֖ẇ yĕhi֥y ki⁠dĕbáreֽ⁠ká׃"],[30,35,"וַ⁠יָּ֣סַר בַּ⁠יּוֹם֩ הַ⁠ה֨וּא אֶת־הַ⁠תְּיָשִׁ֜ים הָֽ⁠עֲקֻדִּ֣ים וְ⁠הַ⁠טְּלֻאִ֗ים וְ⁠אֵ֤ת כָּל־הָֽ⁠עִזִּים֙ הַ⁠נְּקֻדּ֣וֹת וְ⁠הַ⁠טְּלֻאֹ֔ת כֹּ֤ל אֲשֶׁר־לָבָן֙ בּ֔⁠וֹ וְ⁠כָל־ח֖וּם בַּ⁠כְּשָׂבִ֑ים וַ⁠יִּתֵּ֖ן בְּ⁠יַד־בָּנָֽי⁠ו׃","wa⁠yá֣̇sar bȧ⁠ẏwòm֩ ha⁠h֨ẇʼ ʼeţ-ha⁠ţĕ̇yáşǐ֜ym háֽ⁠ʻàqudi֣̇ym wĕ⁠ha⁠tĕ̇luʼi֗ym wĕ⁠ʼé֤ţ ká̇l-hֽá⁠ʻizi̇ym֙ ha⁠nĕ̇quḋ֣wòţ wĕ⁠ha⁠tĕ̇luʼò֔ţ kò֤̇l ʼàşěr-lábán֙ ḃ֔⁠wò wĕ⁠kál-ẖ֖ẇm bȧ⁠kĕ̇şá̂bi֑ym wa⁠yi̇ţé֖̇n bĕ̇⁠yad-bá̇náֽy⁠w׃"],[30,36,"וַ⁠יָּ֗שֶׂם דֶּ֚רֶךְ שְׁלֹ֣שֶׁת יָמִ֔ים בֵּינ֖⁠וֹ וּ⁠בֵ֣ין יַעֲקֹ֑ב וְ⁠יַעֲקֹ֗ב רֹעֶ֛ה אֶת־צֹ֥אן לָבָ֖ן הַ⁠נּוֹתָרֹֽת׃","wa⁠yá̇֗şêm dė֚rekĕ şĕ̌lò֣şěţ yámi֔ym bé̇yn֖⁠wò ẇ⁠bé֣yn yaʻàqò֑b wĕ⁠yaʻàqò֗b ròʻe֛h ʼeţ-ẕò֥ʼn lábá֖n ha⁠ṅwòţáròֽţ׃"],[30,37,"וַ⁠יִּֽקַּֽח־ל֣⁠וֹ יַעֲקֹ֗ב מַקַּ֥ל לִבְנֶ֛ה לַ֖ח וְ⁠ל֣וּז וְ⁠עֶרְמ֑וֹן וַ⁠יְפַצֵּ֤ל בָּ⁠הֵן֙ פְּצָל֣וֹת לְבָנ֔וֹת מַחְשֹׂף֙ הַ⁠לָּבָ֔ן אֲשֶׁ֖ר עַל־הַ⁠מַּקְלֽוֹת׃","wa⁠yiֽ̇qȧֽẖ-l֣⁠wò yaʻàqò֗b maqȧ֥l libĕne֛h la֖ẖ wĕ⁠l֣ẇz wĕ⁠ʻerĕm֑wòn wa⁠yĕpaẕé֤̇l bá̇⁠hén֙ pĕ̇ẕál֣wòţ lĕbán֔wòţ maẖĕşò̂p֙ ha⁠lá̇bá֔n ʼàşě֖r ʻal-ha⁠mȧqĕlֽwòţ׃"],[30,38,"וַ⁠יַּצֵּ֗ג אֶת־הַ⁠מַּקְלוֹת֙ אֲשֶׁ֣ר פִּצֵּ֔ל בָּ⁠רֳהָטִ֖ים בְּ⁠שִֽׁקֲת֣וֹת הַ⁠מָּ֑יִם אֲשֶׁר֩ תָּבֹ֨אןָ הַ⁠צֹּ֤אן לִ⁠שְׁתּוֹת֙ לְ⁠נֹ֣כַח הַ⁠צֹּ֔אן וַ⁠יֵּחַ֖מְנָה בְּ⁠בֹאָ֥⁠ן לִ⁠שְׁתּֽוֹת׃","wa⁠yȧẕé̇֗g ʼeţ-ha⁠mȧqĕlwòţ֙ ʼàşě֣r pi̇ẕé̇֔l bá̇⁠roháti֖ym bĕ̇⁠şǐֽqàţ֣wòţ ha⁠má֑̇yim ʼàşěr֩ ţá̇bò֨ʼná ha⁠ẕò֤̇ʼn li⁠şĕ̌ţ̇wòţ֙ lĕ⁠nò֣kaẖ ha⁠ẕò̇֔ʼn wa⁠yé̇ẖa֖mĕnáh bĕ̇⁠bòʼá֥⁠n li⁠şĕ̌ţֽ̇wòţ׃"],[30,39,"וַ⁠יֶּחֱמ֥וּ הַ⁠צֹּ֖אן אֶל־הַ⁠מַּקְל֑וֹת וַ⁠תֵּלַ֣דְןָ הַ⁠צֹּ֔אן עֲקֻדִּ֥ים נְקֻדִּ֖ים וּ⁠טְלֻאִֽים׃","wa⁠yėẖèm֥ẇ ha⁠ẕò֖̇ʼn ʼel-ha⁠mȧqĕl֑wòţ wa⁠ţé̇la֣dĕná ha⁠ẕò̇֔ʼn ʻàqudi֥̇ym nĕqudi֖̇ym ẇ⁠tĕluʼiֽym׃"],[30,40,"וְ⁠הַ⁠כְּשָׂבִים֮ הִפְרִ֣יד יַעֲקֹב֒ וַ֠⁠יִּתֵּן פְּנֵ֨י הַ⁠צֹּ֧אן אֶל־עָקֹ֛ד וְ⁠כָל־ח֖וּם בְּ⁠צֹ֣אן לָבָ֑ן וַ⁠יָּֽשֶׁת־ל֤⁠וֹ עֲדָרִים֙ לְ⁠בַדּ֔⁠וֹ וְ⁠לֹ֥א שָׁתָ֖⁠ם עַל־צֹ֥אן לָבָֽן׃","wĕ⁠ha⁠kĕ̇şá̂biym֮ hipĕri֣yd yaʻàqòb֒ wa֠⁠yi̇ţé̇n pĕ̇né֨y ha⁠ẕò֧̇ʼn ʼel-ʻáqò֛d wĕ⁠kál-ẖ֖ẇm bĕ̇⁠ẕò֣ʼn lábá֑n wa⁠yáֽ̇şěţ-l֤⁠wò ʻàdáriym֙ lĕ⁠baḋ֔⁠wò wĕ⁠lò֥ʼ şá̌ţá֖⁠m ʻal-ẕò֥ʼn lábáֽn׃"],[30,41,"וְ⁠הָיָ֗ה בְּ⁠כָל־יַחֵם֮ הַ⁠צֹּ֣אן הַ⁠מְקֻשָּׁרוֹת֒ וְ⁠שָׂ֨ם יַעֲקֹ֧ב אֶת־הַ⁠מַּקְל֛וֹת לְ⁠עֵינֵ֥י הַ⁠צֹּ֖אן בָּ⁠רֳהָטִ֑ים לְ⁠יַחְמֵ֖⁠נָּה בַּ⁠מַּקְלֽוֹת׃","wĕ⁠háyá֗h bĕ̇⁠kál-yaẖém֮ ha⁠ẕò֣̇ʼn ha⁠mĕquşá̇̌rwòţ֒ wĕ⁠şá̂֨m yaʻàqò֧b ʼeţ-ha⁠mȧqĕl֛wòţ lĕ⁠ʻéyné֥y ha⁠ẕò֖̇ʼn bá̇⁠roháti֑ym lĕ⁠yaẖĕmé֖⁠ná̇h bȧ⁠mȧqĕlֽwòţ׃"],[30,42,"וּ⁠בְ⁠הַעֲטִ֥יף הַ⁠צֹּ֖אן לֹ֣א יָשִׂ֑ים וְ⁠הָיָ֤ה הָ⁠עֲטֻפִים֙ לְ⁠לָבָ֔ן וְ⁠הַ⁠קְּשֻׁרִ֖ים לְ⁠יַעֲקֹֽב׃","ẇ⁠bĕ⁠haʻàti֥yp ha⁠ẕò֖̇ʼn lò֣ʼ yáşî֑ym wĕ⁠háyá֤h há⁠ʻàtupiym֙ lĕ⁠lábá֔n wĕ⁠ha⁠qĕ̇şǔri֖ym lĕ⁠yaʻàqòֽb׃"],[30,43,"וַ⁠יִּפְרֹ֥ץ הָ⁠אִ֖ישׁ מְאֹ֣ד מְאֹ֑ד וַֽ⁠יְהִי־ל⁠וֹ֙ צֹ֣אן רַבּ֔וֹת וּ⁠שְׁפָחוֹת֙ וַ⁠עֲבָדִ֔ים וּ⁠גְמַלִּ֖ים וַ⁠חֲמֹרִֽים׃","wa⁠yi̇pĕrò֥ẕ há⁠ʼi֖yş̌ mĕʼò֣d mĕʼò֑d wֽa⁠yĕhiy-l⁠wò֙ ẕò֣ʼn raḃ֔wòţ ẇ⁠şĕ̌páẖwòţ֙ wa⁠ʻàbádi֔ym ẇ⁠gĕmali֖̇ym wa⁠ẖàmòriֽym׃"],[31,1,"וַ⁠יִּשְׁמַ֗ע אֶת־דִּבְרֵ֤י בְנֵֽי־לָבָן֙ לֵ⁠אמֹ֔ר לָקַ֣ח יַעֲקֹ֔ב אֵ֖ת כָּל־אֲשֶׁ֣ר לְ⁠אָבִ֑י⁠נוּ וּ⁠מֵ⁠אֲשֶׁ֣ר לְ⁠אָבִ֔י⁠נוּ עָשָׂ֕ה אֵ֥ת כָּל־הַ⁠כָּבֹ֖ד הַ⁠זֶּֽה׃","wa⁠yi̇şĕ̌ma֗ʻ ʼeţ-di̇bĕré֤y bĕnéֽy-lábán֙ lé⁠ʼmò֔r láqa֣ẖ yaʻàqò֔b ʼé֖ţ ká̇l-ʼàşě֣r lĕ⁠ʼábi֑y⁠nẇ ẇ⁠mé⁠ʼàşě֣r lĕ⁠ʼábi֔y⁠nẇ ʻáşá̂֕h ʼé֥ţ ká̇l-ha⁠ká̇bò֖d ha⁠zėֽh׃"],[31,2,"וַ⁠יַּ֥רְא יַעֲקֹ֖ב אֶת־פְּנֵ֣י לָבָ֑ן וְ⁠הִנֵּ֥ה אֵינֶ֛⁠נּוּ עִמּ֖⁠וֹ כִּ⁠תְמ֥וֹל שִׁלְשֽׁוֹם׃","wa⁠yȧ֥rĕʼ yaʻàqò֖b ʼeţ-pĕ̇né֣y lábá֑n wĕ⁠hiné֥̇h ʼéyne֛⁠ṅẇ ʻiṁ֖⁠wò ki̇⁠ţĕm֥wòl şǐlĕşֽ̌wòm׃"],[31,3,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶֽל־יַעֲקֹ֔ב שׁ֛וּב אֶל־אֶ֥רֶץ אֲבוֹתֶ֖י⁠ךָ וּ⁠לְ⁠מוֹלַדְתֶּ֑⁠ךָ וְ⁠אֶֽהְיֶ֖ה עִמָּֽ⁠ךְ׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼeֽl-yaʻàqò֔b ş֛̌ẇb ʼel-ʼe֥reẕ ʼàbwòţe֖y⁠ká ẇ⁠lĕ⁠mwòladĕţė֑⁠ká wĕ⁠ʼeֽhĕye֖h ʻimáֽ̇⁠kĕ׃"],[31,4,"וַ⁠יִּשְׁלַ֣ח יַעֲקֹ֔ב וַ⁠יִּקְרָ֖א לְ⁠רָחֵ֣ל וּ⁠לְ⁠לֵאָ֑ה הַ⁠שָּׂדֶ֖ה אֶל־צֹאנֽ⁠וֹ׃","wa⁠yi̇şĕ̌la֣ẖ yaʻàqò֔b wa⁠yi̇qĕrá֖ʼ lĕ⁠ráẖé֣l ẇ⁠lĕ⁠léʼá֑h ha⁠şá̇̂de֖h ʼel-ẕòʼnֽ⁠wò׃"],[31,5,"וַ⁠יֹּ֣אמֶר לָ⁠הֶ֗ן רֹאֶ֤ה אָנֹכִי֙ אֶת־פְּנֵ֣י אֲבִי⁠כֶ֔ן כִּֽי־אֵינֶ֥⁠נּוּ אֵלַ֖⁠י כִּ⁠תְמֹ֣ל שִׁלְשֹׁ֑ם וֵֽ⁠אלֹהֵ֣י אָבִ֔⁠י הָיָ֖ה עִמָּדִֽ⁠י׃","wa⁠yò֣̇ʼmer lá⁠he֗n ròʼe֤h ʼánòkiy֙ ʼeţ-pĕ̇né֣y ʼàbiy⁠ke֔n kiֽ̇y-ʼéyne֥⁠ṅẇ ʼéla֖⁠y ki̇⁠ţĕmò֣l şǐlĕşò֑̌m wֽé⁠ʼlòhé֣y ʼábi֔⁠y háyá֖h ʻimá̇diֽ⁠y׃"],[31,6,"וְ⁠אַתֵּ֖נָה יְדַעְתֶּ֑ן כִּ֚י בְּ⁠כָל־כֹּחִ֔⁠י עָבַ֖דְתִּי אֶת־אֲבִי⁠כֶֽן׃","wĕ⁠ʼaţé֖̇náh yĕdaʻĕţė֑n ki֚̇y bĕ̇⁠kál-kò̇ẖi֔⁠y ʻába֖dĕţi̇y ʼeţ-ʼàbiy⁠keֽn׃"],[31,7,"וַ⁠אֲבִי⁠כֶן֙ הֵ֣תֶל בִּ֔⁠י וְ⁠הֶחֱלִ֥ף אֶת־מַשְׂכֻּרְתִּ֖⁠י עֲשֶׂ֣רֶת מֹנִ֑ים וְ⁠לֹֽא־נְתָנ֣⁠וֹ אֱלֹהִ֔ים לְ⁠הָרַ֖ע עִמָּדִֽ⁠י׃","wa⁠ʼàbiy⁠ken֙ hé֣ţel bi̇֔⁠y wĕ⁠heẖèli֥p ʼeţ-maşĕ̂ku̇rĕţi֖̇⁠y ʻàşê֣reţ mòni֑ym wĕ⁠lòֽʼ-nĕţán֣⁠wò ʼèlòhi֔ym lĕ⁠hára֖ʻ ʻimá̇diֽ⁠y׃"],[31,8,"אִם־כֹּ֣ה יֹאמַ֗ר נְקֻדִּים֙ יִהְיֶ֣ה שְׂכָרֶ֔⁠ךָ וְ⁠יָלְד֥וּ כָל־הַ⁠צֹּ֖אן נְקֻדִּ֑ים וְ⁠אִם־כֹּ֣ה יֹאמַ֗ר עֲקֻדִּים֙ יִהְיֶ֣ה שְׂכָרֶ֔⁠ךָ וְ⁠יָלְד֥וּ כָל־הַ⁠צֹּ֖אן עֲקֻדִּֽים׃","ʼim-kò֣̇h yòʼma֗r nĕqudi̇ym֙ yihĕye֣h şĕ̂káre֔⁠ká wĕ⁠yálĕd֥ẇ kál-ha⁠ẕò֖̇ʼn nĕqudi֑̇ym wĕ⁠ʼim-kò֣̇h yòʼma֗r ʻàqudi̇ym֙ yihĕye֣h şĕ̂káre֔⁠ká wĕ⁠yálĕd֥ẇ kál-ha⁠ẕò֖̇ʼn ʻàqudiֽ̇ym׃"],[31,9,"וַ⁠יַּצֵּ֧ל אֱלֹהִ֛ים אֶת־מִקְנֵ֥ה אֲבִי⁠כֶ֖ם וַ⁠יִּתֶּן־לִֽ⁠י׃","wa⁠yȧẕé֧̇l ʼèlòhi֛ym ʼeţ-miqĕné֥h ʼàbiy⁠ke֖m wa⁠yi̇ţėn-liֽ⁠y׃"],[31,10,"וַ⁠יְהִ֗י בְּ⁠עֵת֙ יַחֵ֣ם הַ⁠צֹּ֔אן וָ⁠אֶשָּׂ֥א עֵינַ֛⁠י וָ⁠אֵ֖רֶא בַּ⁠חֲל֑וֹם וְ⁠הִנֵּ֤ה הָֽ⁠עַתֻּדִים֙ הָ⁠עֹלִ֣ים עַל־הַ⁠צֹּ֔אן עֲקֻדִּ֥ים נְקֻדִּ֖ים וּ⁠בְרֻדִּֽים׃","wa⁠yĕhi֗y bĕ̇⁠ʻéţ֙ yaẖé֣m ha⁠ẕò̇֔ʼn wá⁠ʼeşá֥̇̂ʼ ʻéyna֛⁠y wá⁠ʼé֖reʼ bȧ⁠ẖàl֑wòm wĕ⁠hiné֤̇h háֽ⁠ʻaţu̇diym֙ há⁠ʻòli֣ym ʻal-ha⁠ẕò̇֔ʼn ʻàqudi֥̇ym nĕqudi֖̇ym ẇ⁠bĕrudiֽ̇ym׃"],[31,11,"וַ⁠יֹּ֨אמֶר אֵלַ֜⁠י מַלְאַ֧ךְ הָ⁠אֱלֹהִ֛ים בַּ⁠חֲל֖וֹם יַֽעֲקֹ֑ב וָ⁠אֹמַ֖ר הִנֵּֽנִ⁠י׃","wa⁠yò̇֨ʼmer ʼéla֜⁠y malĕʼa֧kĕ há⁠ʼèlòhi֛ym bȧ⁠ẖàl֖wòm yֽaʻàqò֑b wá⁠ʼòma֖r hinéֽ̇ni⁠y׃"],[31,12,"וַ⁠יֹּ֗אמֶר שָׂא־נָ֨א עֵינֶ֤י⁠ךָ וּ⁠רְאֵה֙ כָּל־הָֽ⁠עַתֻּדִים֙ הָ⁠עֹלִ֣ים עַל־הַ⁠צֹּ֔אן עֲקֻדִּ֥ים נְקֻדִּ֖ים וּ⁠בְרֻדִּ֑ים כִּ֣י רָאִ֔יתִי אֵ֛ת כָּל־אֲשֶׁ֥ר לָבָ֖ן עֹ֥שֶׂה לָּֽ⁠ךְ׃","wa⁠yò̇֗ʼmer şá̂ʼ-ná֨ʼ ʻéyne֤y⁠ká ẇ⁠rĕʼéh֙ ká̇l-háֽ⁠ʻaţu̇diym֙ há⁠ʻòli֣ym ʻal-ha⁠ẕò̇֔ʼn ʻàqudi֥̇ym nĕqudi֖̇ym ẇ⁠bĕrudi֑̇ym ki֣̇y ráʼi֔yţiy ʼé֛ţ ká̇l-ʼàşě֥r lábá֖n ʻò֥şêh láֽ̇⁠kĕ׃"],[31,13,"אָנֹכִ֤י הָ⁠אֵל֙ בֵּֽית־אֵ֔ל אֲשֶׁ֨ר מָשַׁ֤חְתָּ שָּׁם֙ מַצֵּבָ֔ה אֲשֶׁ֨ר נָדַ֥רְתָּ לִּ֛⁠י שָׁ֖ם נֶ֑דֶר עַתָּ֗ה ק֥וּם צֵא֙ מִן־הָ⁠אָ֣רֶץ הַ⁠זֹּ֔את וְ⁠שׁ֖וּב אֶל־אֶ֥רֶץ מוֹלַדְתֶּֽ⁠ךָ׃","ʼánòki֤y há⁠ʼél֙ béֽ̇yţ-ʼé֔l ʼàşě֨r máşǎ֤ẖĕţá̇ şá̇̌m֙ maẕé̇bá֔h ʼàşě֨r náda֥rĕţá̇ li֛̇⁠y şá֖̌m ne֑der ʻaţá̇֗h q֥ẇm ẕéʼ֙ min-há⁠ʼá֣reẕ ha⁠zò̇֔ʼţ wĕ⁠ş֖̌ẇb ʼel-ʼe֥reẕ mwòladĕţėֽ⁠ká׃"],[31,14,"וַ⁠תַּ֤עַן רָחֵל֙ וְ⁠לֵאָ֔ה וַ⁠תֹּאמַ֖רְנָה ל֑⁠וֹ הַ⁠ע֥וֹד לָ֛⁠נוּ חֵ֥לֶק וְ⁠נַחֲלָ֖ה בְּ⁠בֵ֥ית אָבִֽי⁠נוּ׃","wa⁠ţȧ֤ʻan ráẖél֙ wĕ⁠léʼá֔h wa⁠ţò̇ʼma֖rĕnáh l֑⁠wò ha⁠ʻ֥wòd lá֛⁠nẇ ẖé֥leq wĕ⁠naẖàlá֖h bĕ̇⁠bé֥yţ ʼábiֽy⁠nẇ׃"],[31,15,"הֲ⁠ל֧וֹא נָכְרִיּ֛וֹת נֶחְשַׁ֥בְנוּ ל֖⁠וֹ כִּ֣י מְכָרָ֑⁠נוּ וַ⁠יֹּ֥אכַל גַּם־אָכ֖וֹל אֶת־כַּסְפֵּֽ⁠נוּ׃","hà⁠l֧wòʼ nákĕriẏ֛wòţ neẖĕşǎ֥bĕnẇ l֖⁠wò ki֣̇y mĕkárá֑⁠nẇ wa⁠yò֥̇ʼkal gȧm-ʼák֖wòl ʼeţ-kȧsĕpéֽ̇⁠nẇ׃"],[31,16,"כִּ֣י כָל־הָ⁠עֹ֗שֶׁר אֲשֶׁ֨ר הִצִּ֤יל אֱלֹהִים֙ מֵֽ⁠אָבִ֔י⁠נוּ לָ֥⁠נוּ ה֖וּא וּ⁠לְ⁠בָנֵ֑י⁠נוּ וְ⁠עַתָּ֗ה כֹּל֩ אֲשֶׁ֨ר אָמַ֧ר אֱלֹהִ֛ים אֵלֶ֖י⁠ךָ עֲשֵֽׂה׃","ki֣̇y kál-há⁠ʻò֗şěr ʼàşě֨r hiẕi֤̇yl ʼèlòhiym֙ méֽ⁠ʼábi֔y⁠nẇ lá֥⁠nẇ h֖ẇʼ ẇ⁠lĕ⁠báné֑y⁠nẇ wĕ⁠ʻaţá̇֗h kò̇l֩ ʼàşě֨r ʼáma֧r ʼèlòhi֛ym ʼéle֖y⁠ká ʻàşéֽ̂h׃"],[31,17,"וַ⁠יָּ֖קָם יַעֲקֹ֑ב וַ⁠יִּשָּׂ֛א אֶת־בָּנָ֥י⁠ו וְ⁠אֶת־נָשָׁ֖י⁠ו עַל־הַ⁠גְּמַלִּֽים׃","wa⁠yá֖̇qám yaʻàqò֑b wa⁠yi̇şá֛̇̂ʼ ʼeţ-bá̇ná֥y⁠w wĕ⁠ʼeţ-náşá֖̌y⁠w ʻal-ha⁠gĕ̇maliֽ̇ym׃"],[31,18,"וַ⁠יִּנְהַ֣ג אֶת־כָּל־מִקְנֵ֗⁠הוּ וְ⁠אֶת־כָּל־רְכֻשׁ⁠וֹ֙ אֲשֶׁ֣ר רָכָ֔שׁ מִקְנֵה֙ קִנְיָנ֔⁠וֹ אֲשֶׁ֥ר רָכַ֖שׁ בְּ⁠פַדַּ֣ן אֲרָ֑ם לָ⁠ב֛וֹא אֶל־יִצְחָ֥ק אָבִ֖י⁠ו אַ֥רְצָ⁠ה כְּנָֽעַן׃","wa⁠yi̇nĕha֣g ʼeţ-ká̇l-miqĕné֗⁠hẇ wĕ⁠ʼeţ-ká̇l-rĕkuş̌⁠wò֙ ʼàşě֣r ráká֔ş̌ miqĕnéh֙ qinĕyán֔⁠wò ʼàşě֥r ráka֖ş̌ bĕ̇⁠padȧ֣n ʼàrá֑m lá⁠b֛wòʼ ʼel-yiẕĕẖá֥q ʼábi֖y⁠w ʼa֥rĕẕá⁠h kĕ̇náֽʻan׃"],[31,19,"וְ⁠לָבָ֣ן הָלַ֔ךְ לִ⁠גְזֹ֖ז אֶת־צֹאנ֑⁠וֹ וַ⁠תִּגְנֹ֣ב רָחֵ֔ל אֶת־הַ⁠תְּרָפִ֖ים אֲשֶׁ֥ר לְ⁠אָבִֽי⁠הָ׃","wĕ⁠lábá֣n hála֔kĕ li⁠gĕzò֖z ʼeţ-ẕòʼn֑⁠wò wa⁠ţi̇gĕnò֣b ráẖé֔l ʼeţ-ha⁠ţĕ̇rápi֖ym ʼàşě֥r lĕ⁠ʼábiֽy⁠há׃"],[31,20,"וַ⁠יִּגְנֹ֣ב יַעֲקֹ֔ב אֶת־לֵ֥ב לָבָ֖ן הָ⁠אֲרַמִּ֑י עַל־בְּלִי֙ הִגִּ֣יד ל֔⁠וֹ כִּ֥י בֹרֵ֖חַ הֽוּא׃","wa⁠yi̇gĕnò֣b yaʻàqò֔b ʼeţ-lé֥b lábá֖n há⁠ʼàrami֑̇y ʻal-bĕ̇liy֙ higi֣̇yd l֔⁠wò ki֥̇y bòré֖ẖa hֽẇʼ׃"],[31,21,"וַ⁠יִּבְרַ֥ח הוּא֙ וְ⁠כָל־אֲשֶׁר־ל֔⁠וֹ וַ⁠יָּ֖קָם וַ⁠יַּעֲבֹ֣ר אֶת־הַ⁠נָּהָ֑ר וַ⁠יָּ֥שֶׂם אֶת־פָּנָ֖י⁠ו הַ֥ר הַ⁠גִּלְעָֽד׃","wa⁠yi̇bĕra֥ẖ hẇʼ֙ wĕ⁠kál-ʼàşěr-l֔⁠wò wa⁠yá֖̇qám wa⁠yȧʻàbò֣r ʼeţ-ha⁠ná̇há֑r wa⁠yá֥̇şêm ʼeţ-pá̇ná֖y⁠w ha֥r ha⁠gi̇lĕʻáֽd׃"],[31,22,"וַ⁠יֻּגַּ֥ד לְ⁠לָבָ֖ן בַּ⁠יּ֣וֹם הַ⁠שְּׁלִישִׁ֑י כִּ֥י בָרַ֖ח יַעֲקֹֽב׃","wa⁠yu̇gȧ֥d lĕ⁠lábá֖n bȧ⁠ẏ֣wòm ha⁠şĕ̇̌liyşǐ֑y ki֥̇y bára֖ẖ yaʻàqòֽb׃"],[31,23,"וַ⁠יִּקַּ֤ח אֶת־אֶחָי⁠ו֙ עִמּ֔⁠וֹ וַ⁠יִּרְדֹּ֣ף אַחֲרָ֔י⁠ו דֶּ֖רֶךְ שִׁבְעַ֣ת יָמִ֑ים וַ⁠יַּדְבֵּ֥ק אֹת֖⁠וֹ בְּ⁠הַ֥ר הַ⁠גִּלְעָֽד׃","wa⁠yi̇qȧ֤ẖ ʼeţ-ʼeẖáy⁠w֙ ʻiṁ֔⁠wò wa⁠yi̇rĕdò֣̇p ʼaẖàrá֔y⁠w dė֖rekĕ şǐbĕʻa֣ţ yámi֑ym wa⁠yȧdĕbé֥̇q ʼòţ֖⁠wò bĕ̇⁠ha֥r ha⁠gi̇lĕʻáֽd׃"],[31,24,"וַ⁠יָּבֹ֧א אֱלֹהִ֛ים אֶל־לָבָ֥ן הָ⁠אֲרַמִּ֖י בַּ⁠חֲלֹ֣ם הַ⁠לָּ֑יְלָה וַ⁠יֹּ֣אמֶר ל֗⁠וֹ הִשָּׁ֧מֶר לְ⁠ךָ֛ פֶּן־תְּדַבֵּ֥ר עִֽם־יַעֲקֹ֖ב מִ⁠טּ֥וֹב עַד־רָֽע׃","wa⁠yá̇bò֧ʼ ʼèlòhi֛ym ʼel-lábá֥n há⁠ʼàrami֖̇y bȧ⁠ẖàlò֣m ha⁠lá֑̇yĕláh wa⁠yò֣̇ʼmer l֗⁠wò hişá֧̇̌mer lĕ⁠ká֛ pėn-ţĕ̇dabé֥̇r ʻiֽm-yaʻàqò֖b mi⁠ṫ֥wòb ʻad-ráֽʻ׃"],[31,25,"וַ⁠יַּשֵּׂ֥ג לָבָ֖ן אֶֽת־יַעֲקֹ֑ב וְ⁠יַעֲקֹ֗ב תָּקַ֤ע אֶֽת־אָהֳל⁠וֹ֙ בָּ⁠הָ֔ר וְ⁠לָבָ֛ן תָּקַ֥ע אֶת־אֶחָ֖י⁠ו בְּ⁠הַ֥ר הַ⁠גִּלְעָֽד׃","wa⁠yȧşé֥̇̂g lábá֖n ʼeֽţ-yaʻàqò֑b wĕ⁠yaʻàqò֗b ţá̇qa֤ʻ ʼeֽţ-ʼáhol⁠wò֙ bá̇⁠há֔r wĕ⁠lábá֛n ţá̇qa֥ʻ ʼeţ-ʼeẖá֖y⁠w bĕ̇⁠ha֥r ha⁠gi̇lĕʻáֽd׃"],[31,26,"וַ⁠יֹּ֤אמֶר לָבָן֙ לְ⁠יַעֲקֹ֔ב מֶ֣ה עָשִׂ֔יתָ וַ⁠תִּגְנֹ֖ב אֶת־לְבָבִ֑⁠י וַ⁠תְּנַהֵג֙ אֶת־בְּנֹתַ֔⁠י כִּ⁠שְׁבֻי֖וֹת חָֽרֶב׃","wa⁠yò֤̇ʼmer lábán֙ lĕ⁠yaʻàqò֔b me֣h ʻáşî֔yţá wa⁠ţi̇gĕnò֖b ʼeţ-lĕbábi֑⁠y wa⁠ţĕ̇nahég֙ ʼeţ-bĕ̇nòţa֔⁠y ki̇⁠şĕ̌buy֖wòţ ẖáֽreb׃"],[31,27,"לָ֤⁠מָּה נַחְבֵּ֨אתָ֙ לִ⁠בְרֹ֔חַ וַ⁠תִּגְנֹ֖ב אֹתִ֑⁠י וְ⁠לֹא־הִגַּ֣דְתָּ לִּ֔⁠י וָֽ⁠אֲשַׁלֵּחֲ⁠ךָ֛ בְּ⁠שִׂמְחָ֥ה וּ⁠בְ⁠שִׁרִ֖ים בְּ⁠תֹ֥ף וּ⁠בְ⁠כִנּֽוֹר׃","lá֤⁠má̇h naẖĕbé̇֨ʼţá֙ li⁠bĕrò֔ẖa wa⁠ţi̇gĕnò֖b ʼòţi֑⁠y wĕ⁠lòʼ-higȧ֣dĕţá̇ li̇֔⁠y wáֽ⁠ʼàşǎlé̇ẖà⁠ká֛ bĕ̇⁠şîmĕẖá֥h ẇ⁠bĕ⁠şǐri֖ym bĕ̇⁠ţò֥p ẇ⁠bĕ⁠kiṅֽwòr׃"],[31,28,"וְ⁠לֹ֣א נְטַשְׁתַּ֔⁠נִי לְ⁠נַשֵּׁ֥ק לְ⁠בָנַ֖⁠י וְ⁠לִ⁠בְנֹתָ֑⁠י עַתָּ֖ה הִסְכַּ֥לְתָּֽ עֲשֽׂוֹ׃","wĕ⁠lò֣ʼ nĕtaşĕ̌ţȧ֔⁠niy lĕ⁠naşé֥̇̌q lĕ⁠bána֖⁠y wĕ⁠li⁠bĕnòţá֑⁠y ʻaţá֖̇h hisĕkȧ֥lĕţáֽ̇ ʻàşֽ̂wò׃"],[31,29,"יֶשׁ־לְ⁠אֵ֣ל יָדִ֔⁠י לַ⁠עֲשׂ֥וֹת עִמָּ⁠כֶ֖ם רָ֑ע וֵֽ⁠אלֹהֵ֨י אֲבִי⁠כֶ֜ם אֶ֣מֶשׁ ׀ אָמַ֧ר אֵלַ֣⁠י לֵ⁠אמֹ֗ר הִשָּׁ֧מֶר לְ⁠ךָ֛ מִ⁠דַּבֵּ֥ר עִֽם־יַעֲקֹ֖ב מִ⁠טּ֥וֹב עַד־רָֽע׃","yeş̌-lĕ⁠ʼé֣l yádi֔⁠y la⁠ʻàş֥̂wòţ ʻimá̇⁠ke֖m rá֑ʻ wֽé⁠ʼlòhé֨y ʼàbiy⁠ke֜m ʼe֣meş̌ ׀ ʼáma֧r ʼéla֣⁠y lé⁠ʼmò֗r hişá֧̇̌mer lĕ⁠ká֛ mi⁠dȧbé֥̇r ʻiֽm-yaʻàqò֖b mi⁠ṫ֥wòb ʻad-ráֽʻ׃"],[31,30,"וְ⁠עַתָּה֙ הָלֹ֣ךְ הָלַ֔כְתָּ כִּֽי־נִכְסֹ֥ף נִכְסַ֖פְתָּה לְ⁠בֵ֣ית אָבִ֑י⁠ךָ לָ֥⁠מָּה גָנַ֖בְתָּ אֶת־אֱלֹהָֽ⁠י׃","wĕ⁠ʻaţá̇h֙ hálò֣kĕ hála֔kĕţá̇ kiֽ̇y-nikĕsò֥p nikĕsa֖pĕţá̇h lĕ⁠bé֣yţ ʼábi֑y⁠ká lá֥⁠má̇h gána֖bĕţá̇ ʼeţ-ʼèlòháֽ⁠y׃"],[31,31,"וַ⁠יַּ֥עַן יַעֲקֹ֖ב וַ⁠יֹּ֣אמֶר לְ⁠לָבָ֑ן כִּ֣י יָרֵ֔אתִי כִּ֣י אָמַ֔רְתִּי פֶּן־תִּגְזֹ֥ל אֶת־בְּנוֹתֶ֖י⁠ךָ מֵ⁠עִמִּֽ⁠י׃","wa⁠yȧ֥ʻan yaʻàqò֖b wa⁠yò֣̇ʼmer lĕ⁠lábá֑n ki֣̇y yáré֔ʼţiy ki֣̇y ʼáma֔rĕţi̇y pėn-ţi̇gĕzò֥l ʼeţ-bĕ̇nwòţe֖y⁠ká mé⁠ʻimiֽ̇⁠y׃"],[31,32,"עִ֠ם אֲשֶׁ֨ר תִּמְצָ֣א אֶת־אֱלֹהֶי⁠ךָ֮ לֹ֣א יִֽחְיֶה֒ נֶ֣גֶד אַחֵ֧י⁠נוּ הַֽכֶּר־לְ⁠ךָ֛ מָ֥ה עִמָּדִ֖⁠י וְ⁠קַֽח־לָ֑⁠ךְ וְ⁠לֹֽא־יָדַ֣ע יַעֲקֹ֔ב כִּ֥י רָחֵ֖ל גְּנָבָֽתַ⁠ם׃","ʻi֠m ʼàşě֨r ţi̇mĕẕá֣ʼ ʼeţ-ʼèlòhey⁠ká֮ lò֣ʼ yiֽẖĕyeh֒ ne֣ged ʼaẖé֧y⁠nẇ haֽkėr-lĕ⁠ká֛ má֥h ʻimá̇di֖⁠y wĕ⁠qaֽẖ-lá֑⁠kĕ wĕ⁠lòֽʼ-yáda֣ʻ yaʻàqò֔b ki֥̇y ráẖé֖l gĕ̇nábáֽţa⁠m׃"],[31,33,"וַ⁠יָּבֹ֨א לָבָ֜ן בְּ⁠אֹ֥הֶל יַעֲקֹ֣ב ׀ וּ⁠בְ⁠אֹ֣הֶל לֵאָ֗ה וּ⁠בְ⁠אֹ֛הֶל שְׁתֵּ֥י הָ⁠אֲמָהֹ֖ת וְ⁠לֹ֣א מָצָ֑א וַ⁠יֵּצֵא֙ מֵ⁠אֹ֣הֶל לֵאָ֔ה וַ⁠יָּבֹ֖א בְּ⁠אֹ֥הֶל רָחֵֽל׃","wa⁠yá̇bò֨ʼ lábá֜n bĕ̇⁠ʼò֥hel yaʻàqò֣b ׀ ẇ⁠bĕ⁠ʼò֣hel léʼá֗h ẇ⁠bĕ⁠ʼò֛hel şĕ̌ţé֥̇y há⁠ʼàmáhò֖ţ wĕ⁠lò֣ʼ máẕá֑ʼ wa⁠yé̇ẕéʼ֙ mé⁠ʼò֣hel léʼá֔h wa⁠yá̇bò֖ʼ bĕ̇⁠ʼò֥hel ráẖéֽl׃"],[31,34,"וְ⁠רָחֵ֞ל לָקְחָ֣ה אֶת־הַ⁠תְּרָפִ֗ים וַ⁠תְּשִׂמֵ֛⁠ם בְּ⁠כַ֥ר הַ⁠גָּמָ֖ל וַ⁠תֵּ֣שֶׁב עֲלֵי⁠הֶ֑ם וַ⁠יְמַשֵּׁ֥שׁ לָבָ֛ן אֶת־כָּל־הָ⁠אֹ֖הֶל וְ⁠לֹ֥א מָצָֽא׃","wĕ⁠ráẖé֞l láqĕẖá֣h ʼeţ-ha⁠ţĕ̇rápi֗ym wa⁠ţĕ̇şîmé֛⁠m bĕ̇⁠ka֥r ha⁠gá̇má֖l wa⁠ţé֣̇şěb ʻàléy⁠he֑m wa⁠yĕmaşé֥̇̌ş̌ lábá֛n ʼeţ-ká̇l-há⁠ʼò֖hel wĕ⁠lò֥ʼ máẕáֽʼ׃"],[31,35,"וַ⁠תֹּ֣אמֶר אֶל־אָבִ֗י⁠הָ אַל־יִ֨חַר֙ בְּ⁠עֵינֵ֣י אֲדֹנִ֔⁠י כִּ֣י ל֤וֹא אוּכַל֙ לָ⁠ק֣וּם מִ⁠פָּנֶ֔י⁠ךָ כִּי־דֶ֥רֶךְ נָשִׁ֖ים לִ֑⁠י וַ⁠יְחַפֵּ֕שׂ וְ⁠לֹ֥א מָצָ֖א אֶת־הַ⁠תְּרָפִֽים׃","wa⁠ţò֣̇ʼmer ʼel-ʼábi֗y⁠há ʼal-yi֨ẖar֙ bĕ̇⁠ʻéyné֣y ʼàdòni֔⁠y ki֣̇y l֤wòʼ ʼẇkal֙ lá⁠q֣ẇm mi⁠pá̇ne֔y⁠ká ki̇y-de֥rekĕ náşǐ֖ym li֑⁠y wa⁠yĕẖapé̇֕ş̂ wĕ⁠lò֥ʼ máẕá֖ʼ ʼeţ-ha⁠ţĕ̇rápiֽym׃"],[31,36,"וַ⁠יִּ֥חַר לְ⁠יַעֲקֹ֖ב וַ⁠יָּ֣רֶב בְּ⁠לָבָ֑ן וַ⁠יַּ֤עַן יַעֲקֹב֙ וַ⁠יֹּ֣אמֶר לְ⁠לָבָ֔ן מַה־פִּשְׁעִ⁠י֙ מַ֣ה חַטָּאתִ֔⁠י כִּ֥י דָלַ֖קְתָּ אַחֲרָֽ⁠י׃","wa⁠yi֥̇ẖar lĕ⁠yaʻàqò֖b wa⁠yá֣̇reb bĕ̇⁠lábá֑n wa⁠yȧ֤ʻan yaʻàqòb֙ wa⁠yò֣̇ʼmer lĕ⁠lábá֔n mah-pi̇şĕ̌ʻi⁠y֙ ma֣h ẖatá̇ʼţi֔⁠y ki֥̇y dála֖qĕţá̇ ʼaẖàráֽ⁠y׃"],[31,37,"כִּֽי־מִשַּׁ֣שְׁתָּ אֶת־כָּל־כֵּלַ֗⁠י מַה־מָּצָ֨אתָ֙ מִ⁠כֹּ֣ל כְּלֵי־בֵיתֶ֔⁠ךָ שִׂ֣ים כֹּ֔ה נֶ֥גֶד אַחַ֖⁠י וְ⁠אַחֶ֑י⁠ךָ וְ⁠יוֹכִ֖יחוּ בֵּ֥ין שְׁנֵֽי⁠נוּ׃","kiֽ̇y-mişȧ֣̌şĕ̌ţá̇ ʼeţ-ká̇l-ké̇la֗⁠y mah-má̇ẕá֨ʼţá֙ mi⁠kò֣̇l kĕ̇léy-béyţe֔⁠ká şî֣ym kò̇֔h ne֥ged ʼaẖa֖⁠y wĕ⁠ʼaẖe֑y⁠ká wĕ⁠ywòki֖yẖẇ bé֥̇yn şĕ̌néֽy⁠nẇ׃"],[31,38,"זֶה֩ עֶשְׂרִ֨ים שָׁנָ֤ה אָנֹכִי֙ עִמָּ֔⁠ךְ רְחֵלֶ֥י⁠ךָ וְ⁠עִזֶּ֖י⁠ךָ לֹ֣א שִׁכֵּ֑לוּ וְ⁠אֵילֵ֥י צֹאנְ⁠ךָ֖ לֹ֥א אָכָֽלְתִּי׃","zeh֩ ʻeşĕ̂ri֨ym şá̌ná֤h ʼánòkiy֙ ʻimá̇֔⁠kĕ rĕẖéle֥y⁠ká wĕ⁠ʻizė֖y⁠ká lò֣ʼ şǐké֑̇lẇ wĕ⁠ʼéylé֥y ẕòʼnĕ⁠ká֖ lò֥ʼ ʼákáֽlĕţi̇y׃"],[31,39,"טְרֵפָה֙ לֹא־הֵבֵ֣אתִי אֵלֶ֔י⁠ךָ אָנֹכִ֣י אֲחַטֶּ֔⁠נָּה מִ⁠יָּדִ֖⁠י תְּבַקְשֶׁ֑⁠נָּה גְּנֻֽבְתִ֣י י֔וֹם וּ⁠גְנֻֽבְתִ֖י לָֽיְלָה׃","tĕrépáh֙ lòʼ-hébé֣ʼţiy ʼéle֔y⁠ká ʼánòki֣y ʼàẖatė֔⁠ná̇h mi⁠yá̇di֖⁠y ţĕ̇baqĕşě֑⁠ná̇h gĕ̇nuֽbĕţi֣y y֔wòm ẇ⁠gĕnuֽbĕţi֖y láֽyĕláh׃"],[31,40,"הָיִ֧יתִי בַ⁠יּ֛וֹם אֲכָלַ֥⁠נִי חֹ֖רֶב וְ⁠קֶ֣רַח בַּ⁠לָּ֑יְלָה וַ⁠תִּדַּ֥ד שְׁנָתִ֖⁠י מֵֽ⁠עֵינָֽ⁠י׃","háyi֧yţiy ba⁠ẏ֛wòm ʼàkála֥⁠niy ẖò֖reb wĕ⁠qe֣raẖ bȧ⁠lá֑̇yĕláh wa⁠ţi̇dȧ֥d şĕ̌náţi֖⁠y méֽ⁠ʻéynáֽ⁠y׃"],[31,41,"זֶה־לִּ֞⁠י עֶשְׂרִ֣ים שָׁנָה֮ בְּ⁠בֵיתֶ⁠ךָ֒ עֲבַדְתִּ֜י⁠ךָ אַרְבַּֽע־עֶשְׂרֵ֤ה שָׁנָה֙ בִּ⁠שְׁתֵּ֣י בְנֹתֶ֔י⁠ךָ וְ⁠שֵׁ֥שׁ שָׁנִ֖ים בְּ⁠צֹאנֶ֑⁠ךָ וַ⁠תַּחֲלֵ֥ף אֶת־מַשְׂכֻּרְתִּ֖⁠י עֲשֶׂ֥רֶת מֹנִֽים׃","zeh-li̇֞⁠y ʻeşĕ̂ri֣ym şá̌náh֮ bĕ̇⁠béyţe⁠ká֒ ʻàbadĕţi̇֜y⁠ká ʼarĕbȧֽʻ-ʻeşĕ̂ré֤h şá̌náh֙ bi̇⁠şĕ̌ţé֣̇y bĕnòţe֔y⁠ká wĕ⁠şé֥̌ş̌ şá̌ni֖ym bĕ̇⁠ẕòʼne֑⁠ká wa⁠ţȧẖàlé֥p ʼeţ-maşĕ̂ku̇rĕţi֖̇⁠y ʻàşê֥reţ mòniֽym׃"],[31,42,"לוּלֵ֡י אֱלֹהֵ֣י אָבִ⁠י֩ אֱלֹהֵ֨י אַבְרָהָ֜ם וּ⁠פַ֤חַד יִצְחָק֙ הָ֣יָה לִ֔⁠י כִּ֥י עַתָּ֖ה רֵיקָ֣ם שִׁלַּחְתָּ֑⁠נִי אֶת־עָנְיִ֞⁠י וְ⁠אֶת־יְגִ֧יעַ כַּפַּ֛⁠י רָאָ֥ה אֱלֹהִ֖ים וַ⁠יּ֥וֹכַח אָֽמֶשׁ׃","lẇlé֡y ʼèlòhé֣y ʼábi⁠y֩ ʼèlòhé֨y ʼabĕráhá֜m ẇ⁠pa֤ẖad yiẕĕẖáq֙ há֣yáh li֔⁠y ki֥̇y ʻaţá֖̇h réyqá֣m şǐlȧẖĕţá֑̇⁠niy ʼeţ-ʻánĕyi֞⁠y wĕ⁠ʼeţ-yĕgi֧yʻa kȧpȧ֛⁠y ráʼá֥h ʼèlòhi֖ym wa⁠ẏ֥wòkaẖ ʼáֽmeş̌׃"],[31,43,"וַ⁠יַּ֨עַן לָבָ֜ן וַ⁠יֹּ֣אמֶר אֶֽל־יַעֲקֹ֗ב הַ⁠בָּנ֨וֹת בְּנֹתַ֜⁠י וְ⁠הַ⁠בָּנִ֤ים בָּנַ⁠י֙ וְ⁠הַ⁠צֹּ֣אן צֹאנִ֔⁠י וְ⁠כֹ֛ל אֲשֶׁר־אַתָּ֥ה רֹאֶ֖ה לִ⁠י־ה֑וּא וְ⁠לִ⁠בְנֹתַ֞⁠י מָֽה־אֶֽעֱשֶׂ֤ה לָ⁠אֵ֨לֶּה֙ הַ⁠יּ֔וֹם א֥וֹ לִ⁠בְנֵי⁠הֶ֖ן אֲשֶׁ֥ר יָלָֽדוּ׃","wa⁠yȧ֨ʻan lábá֜n wa⁠yò֣̇ʼmer ʼeֽl-yaʻàqò֗b ha⁠bá̇n֨wòţ bĕ̇nòţa֜⁠y wĕ⁠ha⁠bá̇ni֤ym bá̇na⁠y֙ wĕ⁠ha⁠ẕò֣̇ʼn ẕòʼni֔⁠y wĕ⁠kò֛l ʼàşěr-ʼaţá֥̇h ròʼe֖h li⁠y-h֑ẇʼ wĕ⁠li⁠bĕnòţa֞⁠y máֽh-ʼֽeʻèşê֤h lá⁠ʼé֨lėh֙ ha⁠ẏ֔wòm ʼ֥wò li⁠bĕnéy⁠he֖n ʼàşě֥r yáláֽdẇ׃"],[31,44,"וְ⁠עַתָּ֗ה לְכָ֛⁠ה נִכְרְתָ֥ה בְרִ֖ית אֲנִ֣י וָ⁠אָ֑תָּה וְ⁠הָיָ֥ה לְ⁠עֵ֖ד בֵּינִ֥⁠י וּ⁠בֵינֶֽ⁠ךָ׃","wĕ⁠ʻaţá̇֗h lĕká֛⁠h nikĕrĕţá֥h bĕri֖yţ ʼàni֣y wá⁠ʼá֑ţá̇h wĕ⁠háyá֥h lĕ⁠ʻé֖d bé̇yni֥⁠y ẇ⁠béyneֽ⁠ká׃"],[31,45,"וַ⁠יִּקַּ֥ח יַעֲקֹ֖ב אָ֑בֶן וַ⁠יְרִימֶ֖⁠הָ מַצֵּבָֽה׃","wa⁠yi̇qȧ֥ẖ yaʻàqò֖b ʼá֑ben wa⁠yĕriyme֖⁠há maẕé̇báֽh׃"],[31,46,"וַ⁠יֹּ֨אמֶר יַעֲקֹ֤ב לְ⁠אֶחָי⁠ו֙ לִקְט֣וּ אֲבָנִ֔ים וַ⁠יִּקְח֥וּ אֲבָנִ֖ים וַ⁠יַּֽעֲשׂוּ־גָ֑ל וַ⁠יֹּ֥אכְלוּ שָׁ֖ם עַל־הַ⁠גָּֽל׃","wa⁠yò̇֨ʼmer yaʻàqò֤b lĕ⁠ʼeẖáy⁠w֙ liqĕt֣ẇ ʼàbáni֔ym wa⁠yi̇qĕẖ֥ẇ ʼàbáni֖ym wa⁠yȧֽʻàş̂ẇ-gá֑l wa⁠yò֥̇ʼkĕlẇ şá֖̌m ʻal-ha⁠gáֽ̇l׃"],[31,47,"וַ⁠יִּקְרָא־ל֣⁠וֹ לָבָ֔ן יְגַ֖ר שָׂהֲדוּתָ֑א וְ⁠יַֽעֲקֹ֔ב קָ֥רָא ל֖⁠וֹ גַּלְעֵֽד׃","wa⁠yi̇qĕráʼ-l֣⁠wò lábá֔n yĕga֖r şá̂hàdẇţá֑ʼ wĕ⁠yaֽʻàqò֔b qá֥ráʼ l֖⁠wò gȧlĕʻéֽd׃"],[31,48,"וַ⁠יֹּ֣אמֶר לָבָ֔ן הַ⁠גַּ֨ל הַ⁠זֶּ֥ה עֵ֛ד בֵּינִ֥⁠י וּ⁠בֵינְ⁠ךָ֖ הַ⁠יּ֑וֹם עַל־כֵּ֥ן קָרָֽא־שְׁמ֖⁠וֹ גַּלְעֵֽד׃","wa⁠yò֣̇ʼmer lábá֔n ha⁠gȧ֨l ha⁠zė֥h ʻé֛d bé̇yni֥⁠y ẇ⁠béynĕ⁠ká֖ ha⁠ẏ֑wòm ʻal-ké֥̇n qáráֽʼ-şĕ̌m֖⁠wò gȧlĕʻéֽd׃"],[31,49,"וְ⁠הַ⁠מִּצְפָּה֙ אֲשֶׁ֣ר אָמַ֔ר יִ֥צֶף יְהוָ֖ה בֵּינִ֣⁠י וּ⁠בֵינֶ֑⁠ךָ כִּ֥י נִסָּתֵ֖ר אִ֥ישׁ מֵ⁠רֵעֵֽ⁠הוּ׃","wĕ⁠ha⁠mi̇ẕĕpá̇h֙ ʼàşě֣r ʼáma֔r yi֥ẕep yĕhwá֖h bé̇yni֣⁠y ẇ⁠béyne֑⁠ká ki֥̇y nisá̇ţé֖r ʼi֥yş̌ mé⁠réʻéֽ⁠hẇ׃"],[31,50,"אִם־תְּעַנֶּ֣ה אֶת־בְּנֹתַ֗⁠י וְ⁠אִם־תִּקַּ֤ח נָשִׁים֙ עַל־בְּנֹתַ֔⁠י אֵ֥ין אִ֖ישׁ עִמָּ֑⁠נוּ רְאֵ֕ה אֱלֹהִ֥ים עֵ֖ד בֵּינִ֥⁠י וּ⁠בֵינֶֽ⁠ךָ׃","ʼim-ţĕ̇ʻanė֣h ʼeţ-bĕ̇nòţa֗⁠y wĕ⁠ʼim-ţi̇qȧ֤ẖ náşǐym֙ ʻal-bĕ̇nòţa֔⁠y ʼé֥yn ʼi֖yş̌ ʻimá֑̇⁠nẇ rĕʼé֕h ʼèlòhi֥ym ʻé֖d bé̇yni֥⁠y ẇ⁠béyneֽ⁠ká׃"],[31,51,"וַ⁠יֹּ֥אמֶר לָבָ֖ן לְ⁠יַעֲקֹ֑ב הִנֵּ֣ה ׀ הַ⁠גַּ֣ל הַ⁠זֶּ֗ה וְ⁠הִנֵּה֙ הַ⁠מַצֵּבָ֔ה אֲשֶׁ֥ר יָרִ֖יתִי בֵּינִ֥⁠י וּ⁠בֵינֶֽ⁠ךָ׃","wa⁠yò֥̇ʼmer lábá֖n lĕ⁠yaʻàqò֑b hiné֣̇h ׀ ha⁠gȧ֣l ha⁠zė֗h wĕ⁠hiné̇h֙ ha⁠maẕé̇bá֔h ʼàşě֥r yári֖yţiy bé̇yni֥⁠y ẇ⁠béyneֽ⁠ká׃"],[31,52,"עֵ֚ד הַ⁠גַּ֣ל הַ⁠זֶּ֔ה וְ⁠עֵדָ֖ה הַ⁠מַּצֵּבָ֑ה אִם־אָ֗נִי לֹֽא־אֶֽעֱבֹ֤ר אֵלֶ֨י⁠ךָ֙ אֶת־הַ⁠גַּ֣ל הַ⁠זֶּ֔ה וְ⁠אִם־אַ֠תָּה לֹא־תַעֲבֹ֨ר אֵלַ֜⁠י אֶת־הַ⁠גַּ֥ל הַ⁠זֶּ֛ה וְ⁠אֶת־הַ⁠מַּצֵּבָ֥ה הַ⁠זֹּ֖את לְ⁠רָעָֽה׃","ʻé֚d ha⁠gȧ֣l ha⁠zė֔h wĕ⁠ʻédá֖h ha⁠mȧẕé̇bá֑h ʼim-ʼá֗niy lòֽʼ-ʼֽeʻèbò֤r ʼéle֨y⁠ká֙ ʼeţ-ha⁠gȧ֣l ha⁠zė֔h wĕ⁠ʼim-ʼa֠ţá̇h lòʼ-ţaʻàbò֨r ʼéla֜⁠y ʼeţ-ha⁠gȧ֥l ha⁠zė֛h wĕ⁠ʼeţ-ha⁠mȧẕé̇bá֥h ha⁠zò֖̇ʼţ lĕ⁠ráʻáֽh׃"],[31,53,"אֱלֹהֵ֨י אַבְרָהָ֜ם וֵֽ⁠אלֹהֵ֤י נָחוֹר֙ יִשְׁפְּט֣וּ בֵינֵ֔י⁠נוּ אֱלֹהֵ֖י אֲבִי⁠הֶ֑ם וַ⁠יִּשָּׁבַ֣ע יַעֲקֹ֔ב בְּ⁠פַ֖חַד אָבִ֥י⁠ו יִצְחָֽק׃","ʼèlòhé֨y ʼabĕráhá֜m wéֽ⁠ʼlòhé֤y náẖwòr֙ yişĕ̌pĕ̇t֣ẇ béyné֔y⁠nẇ ʼèlòhé֖y ʼàbiy⁠he֑m wa⁠yi̇şá̇̌ba֣ʻ yaʻàqò֔b bĕ̇⁠pa֖ẖad ʼábi֥y⁠w yiẕĕẖáֽq׃"],[31,54,"וַ⁠יִּזְבַּ֨ח יַעֲקֹ֥ב זֶ֨בַח֙ בָּ⁠הָ֔ר וַ⁠יִּקְרָ֥א לְ⁠אֶחָ֖י⁠ו לֶ⁠אֱכָל־לָ֑חֶם וַ⁠יֹּ֣אכְלוּ לֶ֔חֶם וַ⁠יָּלִ֖ינוּ בָּ⁠הָֽר׃","wa⁠yi̇zĕbȧ֨ẖ yaʻàqò֥b ze֨baẖ֙ bá̇⁠há֔r wa⁠yi̇qĕrá֥ʼ lĕ⁠ʼeẖá֖y⁠w le⁠ʼèkál-lá֑ẖem wa⁠yò֣̇ʼkĕlẇ le֔ẖem wa⁠yá̇li֖ynẇ bá̇⁠háֽr׃"],[31,55,"וַ⁠יַּשְׁכֵּ֨ם לָבָ֜ן בַּ⁠בֹּ֗קֶר וַ⁠יְנַשֵּׁ֧ק לְ⁠בָנָ֛י⁠ו וְ⁠לִ⁠בְנוֹתָ֖י⁠ו וַ⁠יְבָ֣רֶךְ אֶתְ⁠הֶ֑ם וַ⁠יֵּ֛לֶךְ וַ⁠יָּ֥שָׁב לָבָ֖ן לִ⁠מְקֹמֽ⁠וֹ׃","wa⁠yȧşĕ̌ké̇֨m lábá֜n bȧ⁠bò̇֗qer wa⁠yĕnaşé֧̇̌q lĕ⁠báná֛y⁠w wĕ⁠li⁠bĕnwòţá֖y⁠w wa⁠yĕbá֣rekĕ ʼeţĕ⁠he֑m wa⁠yé֛̇lekĕ wa⁠yá֥̇şá̌b lábá֖n li⁠mĕqòmֽ⁠wò׃"],[32,1,"וְ⁠יַעֲקֹ֖ב הָלַ֣ךְ לְ⁠דַרְכּ֑⁠וֹ וַ⁠יִּפְגְּעוּ־ב֖⁠וֹ מַלְאֲכֵ֥י אֱלֹהִֽים׃","wĕ⁠yaʻàqò֖b hála֣kĕ lĕ⁠darĕk֑̇⁠wò wa⁠yi̇pĕgĕ̇ʻẇ-b֖⁠wò malĕʼàké֥y ʼèlòhiֽym׃"],[32,2,"וַ⁠יֹּ֤אמֶר יַעֲקֹב֙ כַּ⁠אֲשֶׁ֣ר רָאָ֔⁠ם מַחֲנֵ֥ה אֱלֹהִ֖ים זֶ֑ה וַ⁠יִּקְרָ֛א שֵֽׁם־הַ⁠מָּק֥וֹם הַ⁠ה֖וּא מַֽחֲנָֽיִם׃פ","wa⁠yò֤̇ʼmer yaʻàqòb֙ kȧ⁠ʼàşě֣r ráʼá֔⁠m maẖàné֥h ʼèlòhi֖ym ze֑h wa⁠yi̇qĕrá֛ʼ şéֽ̌m-ha⁠má̇q֥wòm ha⁠h֖ẇʼ mֽaẖànáֽyim׃p"],[32,3,"וַ⁠יִּשְׁלַ֨ח יַעֲקֹ֤ב מַלְאָכִים֙ לְ⁠פָנָ֔י⁠ו אֶל־עֵשָׂ֖ו אָחִ֑י⁠ו אַ֥רְצָ⁠ה שֵׂעִ֖יר שְׂדֵ֥ה אֱדֽוֹם׃","wa⁠yi̇şĕ̌la֨ẖ yaʻàqò֤b malĕʼákiym֙ lĕ⁠páná֔y⁠w ʼel-ʻéşá֖̂w ʼáẖi֑y⁠w ʼa֥rĕẕá⁠h şé̂ʻi֖yr şĕ̂dé֥h ʼèdֽwòm׃"],[32,4,"וַ⁠יְצַ֤ו אֹתָ⁠ם֙ לֵ⁠אמֹ֔ר כֹּ֣ה תֹאמְר֔וּ⁠ן לַֽ⁠אדֹנִ֖⁠י לְ⁠עֵשָׂ֑ו כֹּ֤ה אָמַר֙ עַבְדְּ⁠ךָ֣ יַעֲקֹ֔ב עִם־לָבָ֣ן גַּ֔רְתִּי וָ⁠אֵחַ֖ר עַד־עָֽתָּה׃","wa⁠yĕẕa֤w ʼòţá⁠m֙ lé⁠ʼmò֔r kò֣̇h ţòʼmĕr֔ẇ⁠n laֽ⁠ʼdòni֖⁠y lĕ⁠ʻéşá֑̂w kò֤̇h ʼámar֙ ʻabĕdĕ̇⁠ká֣ yaʻàqò֔b ʻim-lábá֣n gȧ֔rĕţi̇y wá⁠ʼéẖa֖r ʻad-ʻáֽţá̇h׃"],[32,5,"וַֽ⁠יְהִי־לִ⁠י֙ שׁ֣וֹר וַ⁠חֲמ֔וֹר צֹ֖אן וְ⁠עֶ֣בֶד וְ⁠שִׁפְחָ֑ה וָֽ⁠אֶשְׁלְחָ⁠ה֙ לְ⁠הַגִּ֣יד לַֽ⁠אדֹנִ֔⁠י לִ⁠מְצֹא־חֵ֖ן בְּ⁠עֵינֶֽי⁠ךָ׃","waֽ⁠yĕhiy-li⁠y֙ ş֣̌wòr wa⁠ẖàm֔wòr ẕò֖ʼn wĕ⁠ʻe֣bed wĕ⁠şǐpĕẖá֑h wáֽ⁠ʼeşĕ̌lĕẖá⁠h֙ lĕ⁠hagi֣̇yd lֽa⁠ʼdòni֔⁠y li⁠mĕẕòʼ-ẖé֖n bĕ̇⁠ʻéyneֽy⁠ká׃"],[32,6,"וַ⁠יָּשֻׁ֨בוּ֙ הַ⁠מַּלְאָכִ֔ים אֶֽל־יַעֲקֹ֖ב לֵ⁠אמֹ֑ר בָּ֤אנוּ אֶל־אָחִ֨י⁠ךָ֙ אֶל־עֵשָׂ֔ו וְ⁠גַם֙ הֹלֵ֣ךְ לִ⁠קְרָֽאתְ⁠ךָ֔ וְ⁠אַרְבַּע־מֵא֥וֹת אִ֖ישׁ עִמּֽ⁠וֹ׃","wa⁠yá̇şǔ֨bẇ֙ ha⁠mȧlĕʼáki֔ym ʼeֽl-yaʻàqò֖b lé⁠ʼmò֑r bá֤̇ʼnẇ ʼel-ʼáẖi֨y⁠ká֙ ʼel-ʻéşá̂֔w wĕ⁠gam֙ hòlé֣kĕ li⁠qĕráֽʼţĕ⁠ká֔ wĕ⁠ʼarĕbȧʻ-méʼ֥wòţ ʼi֖yş̌ ʻiṁֽ⁠wò׃"],[32,7,"וַ⁠יִּירָ֧א יַעֲקֹ֛ב מְאֹ֖ד וַ⁠יֵּ֣צֶר ל֑⁠וֹ וַ⁠יַּ֜חַץ אֶת־הָ⁠עָ֣ם אֲשֶׁר־אִתּ֗⁠וֹ וְ⁠אֶת־הַ⁠צֹּ֧אן וְ⁠אֶת־הַ⁠בָּקָ֛ר וְ⁠הַ⁠גְּמַלִּ֖ים לִ⁠שְׁנֵ֥י מַחֲנֽוֹת׃","wa⁠yi̇yrá֧ʼ yaʻàqò֛b mĕʼò֖d wa⁠yé֣̇ẕer l֑⁠wò wa⁠yȧ֜ẖaẕ ʼeţ-há⁠ʻá֣m ʼàşěr-ʼiţ̇֗⁠wò wĕ⁠ʼeţ-ha⁠ẕò֧̇ʼn wĕ⁠ʼeţ-ha⁠bá̇qá֛r wĕ⁠ha⁠gĕ̇mali֖̇ym li⁠şĕ̌né֥y maẖànֽwòţ׃"],[32,8,"וַ⁠יֹּ֕אמֶר אִם־יָב֥וֹא עֵשָׂ֛ו אֶל־הַ⁠מַּחֲנֶ֥ה הָ⁠אַחַ֖ת וְ⁠הִכָּ֑⁠הוּ וְ⁠הָיָ֛ה הַ⁠מַּחֲנֶ֥ה הַ⁠נִּשְׁאָ֖ר לִ⁠פְלֵיטָֽה׃","wa⁠yò̇֕ʼmer ʼim-yáb֥wòʼ ʻéşá֛̂w ʼel-ha⁠mȧẖàne֥h há⁠ʼaẖa֖ţ wĕ⁠hiká֑̇⁠hẇ wĕ⁠háyá֛h ha⁠mȧẖàne֥h ha⁠ni̇şĕ̌ʼá֖r li⁠pĕléytáֽh׃"],[32,9,"וַ⁠יֹּאמֶר֮ יַעֲקֹב֒ אֱלֹהֵי֙ אָבִ֣⁠י אַבְרָהָ֔ם וֵ⁠אלֹהֵ֖י אָבִ֣⁠י יִצְחָ֑ק יְהוָ֞ה הָ⁠אֹמֵ֣ר אֵלַ֗⁠י שׁ֧וּב לְ⁠אַרְצְ⁠ךָ֛ וּ⁠לְ⁠מוֹלַדְתְּ⁠ךָ֖ וְ⁠אֵיטִ֥יבָה עִמָּֽ⁠ךְ׃","wa⁠yò̇ʼmer֮ yaʻàqòb֒ ʼèlòhéy֙ ʼábi֣⁠y ʼabĕráhá֔m wé⁠ʼlòhé֖y ʼábi֣⁠y yiẕĕẖá֑q yĕhwá֞h há⁠ʼòmé֣r ʼéla֗⁠y ş֧̌ẇb lĕ⁠ʼarĕẕĕ⁠ká֛ ẇ⁠lĕ⁠mwòladĕţĕ̇⁠ká֖ wĕ⁠ʼéyti֥ybáh ʻimáֽ̇⁠kĕ׃"],[32,10,"קָטֹ֜נְתִּי מִ⁠כֹּ֤ל הַ⁠חֲסָדִים֙ וּ⁠מִ⁠כָּל־הָ֣⁠אֱמֶ֔ת אֲשֶׁ֥ר עָשִׂ֖יתָ אֶת־עַבְדֶּ֑⁠ךָ כִּ֣י בְ⁠מַקְלִ֗⁠י עָבַ֨רְתִּי֙ אֶת־הַ⁠יַּרְדֵּ֣ן הַ⁠זֶּ֔ה וְ⁠עַתָּ֥ה הָיִ֖יתִי לִ⁠שְׁנֵ֥י מַחֲנֽוֹת׃","qátò֜nĕţi̇y mi⁠kò֤̇l ha⁠ẖàsádiym֙ ẇ⁠mi⁠ká̇l-há֣⁠ʼème֔ţ ʼàşě֥r ʻáşî֖yţá ʼeţ-ʻabĕdė֑⁠ká ki֣̇y bĕ⁠maqĕli֗⁠y ʻába֨rĕţi̇y֙ ʼeţ-ha⁠yȧrĕdé֣̇n ha⁠zė֔h wĕ⁠ʻaţá֥̇h háyi֖yţiy li⁠şĕ̌né֥y maẖànֽwòţ׃"],[32,11,"הַצִּילֵ֥⁠נִי נָ֛א מִ⁠יַּ֥ד אָחִ֖⁠י מִ⁠יַּ֣ד עֵשָׂ֑ו כִּֽי־יָרֵ֤א אָנֹכִי֙ אֹת֔⁠וֹ פֶּן־יָב֣וֹא וְ⁠הִכַּ֔⁠נִי אֵ֖ם עַל־בָּנִֽים׃","haẕi̇ylé֥⁠niy ná֛ʼ mi⁠yȧ֥d ʼáẖi֖⁠y mi⁠yȧ֣d ʻéşá֑̂w kiֽ̇y-yáré֤ʼ ʼánòkiy֙ ʼòţ֔⁠wò pėn-yáb֣wòʼ wĕ⁠hikȧ֔⁠niy ʼé֖m ʻal-bá̇niֽym׃"],[32,12,"וְ⁠אַתָּ֣ה אָמַ֔רְתָּ הֵיטֵ֥ב אֵיטִ֖יב עִמָּ֑⁠ךְ וְ⁠שַׂמְתִּ֤י אֶֽת־זַרְעֲ⁠ךָ֙ כְּ⁠ח֣וֹל הַ⁠יָּ֔ם אֲשֶׁ֥ר לֹא־יִסָּפֵ֖ר מֵ⁠רֹֽב׃","wĕ⁠ʼaţá֣̇h ʼáma֔rĕţá̇ héyté֥b ʼéyti֖yb ʻimá֑̇⁠kĕ wĕ⁠şâmĕţi֤̇y ʼeֽţ-zarĕʻà⁠ká֙ kĕ̇⁠ẖ֣wòl ha⁠yá̇֔m ʼàşě֥r lòʼ-yisá̇pé֖r mé⁠ròֽb׃"],[32,13,"וַ⁠יָּ֥לֶן שָׁ֖ם בַּ⁠לַּ֣יְלָה הַ⁠ה֑וּא וַ⁠יִּקַּ֞ח מִן־הַ⁠בָּ֧א בְ⁠יָד֛⁠וֹ מִנְחָ֖ה לְ⁠עֵשָׂ֥ו אָחִֽי⁠ו׃","wa⁠yá֥̇len şá֖̌m bȧ⁠lȧ֣yĕláh ha⁠h֑ẇʼ wa⁠yi̇qȧ֞ẖ min-ha⁠bá֧̇ʼ bĕ⁠yád֛⁠wò minĕẖá֖h lĕ⁠ʻéşá֥̂w ʼáẖiֽy⁠w׃"],[32,14,"עִזִּ֣ים מָאתַ֔יִם וּ⁠תְיָשִׁ֖ים עֶשְׂרִ֑ים רְחֵלִ֥ים מָאתַ֖יִם וְ⁠אֵילִ֥ים עֶשְׂרִֽים׃","ʻizi֣̇ym máʼţa֔yim ẇ⁠ţĕyáşǐ֖ym ʻeşĕ̂ri֑ym rĕẖéli֥ym máʼţa֖yim wĕ⁠ʼéyli֥ym ʻeşĕ̂riֽym׃"],[32,15,"גְּמַלִּ֧ים מֵינִיק֛וֹת וּ⁠בְנֵי⁠הֶ֖ם שְׁלֹשִׁ֑ים פָּר֤וֹת אַרְבָּעִים֙ וּ⁠פָרִ֣ים עֲשָׂרָ֔ה אֲתֹנֹ֣ת עֶשְׂרִ֔ים וַ⁠עְיָרִ֖ם עֲשָׂרָֽה׃","gĕ̇mali֧̇ym méyniyq֛wòţ ẇ⁠bĕnéy⁠he֖m şĕ̌lòşǐ֑ym pá̇r֤wòţ ʼarĕbá̇ʻiym֙ ẇ⁠pári֣ym ʻàşá̂rá֔h ʼàţònò֣ţ ʻeşĕ̂ri֔ym wa⁠ʻĕyári֖m ʻàşá̂ráֽh׃"],[32,16,"וַ⁠יִּתֵּן֙ בְּ⁠יַד־עֲבָדָ֔י⁠ו עֵ֥דֶר עֵ֖דֶר לְ⁠בַדּ֑⁠וֹ וַ֤⁠יֹּאמֶר אֶל־עֲבָדָי⁠ו֙ עִבְר֣וּ לְ⁠פָנַ֔⁠י וְ⁠רֶ֣וַח תָּשִׂ֔ימוּ בֵּ֥ין עֵ֖דֶר וּ⁠בֵ֥ין עֵֽדֶר׃","wa⁠yi̇ţé̇n֙ bĕ̇⁠yad-ʻàbádá֔y⁠w ʻé֥der ʻé֖der lĕ⁠baḋ֑⁠wò wa֤⁠yò̇ʼmer ʼel-ʻàbádáy⁠w֙ ʻibĕr֣ẇ lĕ⁠pána֔⁠y wĕ⁠re֣waẖ ţá̇şî֔ymẇ bé֥̇yn ʻé֖der ẇ⁠bé֥yn ʻéֽder׃"],[32,17,"וַ⁠יְצַ֥ו אֶת־הָ⁠רִאשׁ֖וֹן לֵ⁠אמֹ֑ר כִּ֣י יִֽפְגָּשְׁ⁠ךָ֞ עֵשָׂ֣ו אָחִ֗⁠י וִ⁠שְׁאֵֽלְ⁠ךָ֙ לֵ⁠אמֹ֔ר לְ⁠מִי־אַ֨תָּה֙ וְ⁠אָ֣נָה תֵלֵ֔ךְ וּ⁠לְ⁠מִ֖י אֵ֥לֶּה לְ⁠פָנֶֽי⁠ךָ׃","wa⁠yĕẕa֥w ʼeţ-há⁠riʼş֖̌wòn lé⁠ʼmò֑r ki֣̇y yiֽpĕgá̇şĕ̌⁠ká֞ ʻéşá֣̂w ʼáẖi֗⁠y wi⁠şĕ̌ʼéֽlĕ⁠ká֙ lé⁠ʼmò֔r lĕ⁠miy-ʼa֨ţá̇h֙ wĕ⁠ʼá֣náh ţélé֔kĕ ẇ⁠lĕ⁠mi֖y ʼé֥lėh lĕ⁠páneֽy⁠ká׃"],[32,18,"וְ⁠אָֽמַרְתָּ֙ לְ⁠עַבְדְּ⁠ךָ֣ לְ⁠יַעֲקֹ֔ב מִנְחָ֥ה הִוא֙ שְׁלוּחָ֔ה לַֽ⁠אדֹנִ֖⁠י לְ⁠עֵשָׂ֑ו וְ⁠הִנֵּ֥ה גַם־ה֖וּא אַחֲרֵֽי⁠נוּ׃","wĕ⁠ʼáֽmarĕţá̇֙ lĕ⁠ʻabĕdĕ̇⁠ká֣ lĕ⁠yaʻàqò֔b minĕẖá֥h hiwʼ֙ şĕ̌lẇẖá֔h lֽa⁠ʼdòni֖⁠y lĕ⁠ʻéşá֑̂w wĕ⁠hiné֥̇h gam-h֖ẇʼ ʼaẖàréֽy⁠nẇ׃"],[32,19,"וַ⁠יְצַ֞ו גַּ֣ם אֶת־הַ⁠שֵּׁנִ֗י גַּ֚ם אֶת־הַ⁠שְּׁלִישִׁ֔י גַּ֚ם אֶת־כָּל־הַ⁠הֹ֣לְכִ֔ים אַחֲרֵ֥י הָ⁠עֲדָרִ֖ים לֵ⁠אמֹ֑ר כַּ⁠דָּבָ֤ר הַ⁠זֶּה֙ תְּדַבְּר֣וּ⁠ן אֶל־עֵשָׂ֔ו בְּ⁠מֹצַאֲ⁠כֶ֖ם אֹתֽ⁠וֹ׃","wa⁠yĕẕa֞w gȧ֣m ʼeţ-ha⁠şé̇̌ni֗y gȧ֚m ʼeţ-ha⁠şĕ̇̌liyşǐ֔y gȧ֚m ʼeţ-ká̇l-ha⁠hò֣lĕki֔ym ʼaẖàré֥y há⁠ʻàdári֖ym lé⁠ʼmò֑r kȧ⁠dá̇bá֤r ha⁠zėh֙ ţĕ̇dabĕ̇r֣ẇ⁠n ʼel-ʻéşá̂֔w bĕ̇⁠mòẕaʼà⁠ke֖m ʼòţֽ⁠wò׃"],[32,20,"וַ⁠אֲמַרְתֶּ֕ם גַּ֗ם הִנֵּ֛ה עַבְדְּ⁠ךָ֥ יַעֲקֹ֖ב אַחֲרֵ֑י⁠נוּ כִּֽי־אָמַ֞ר אֲכַפְּרָ֣ה פָנָ֗י⁠ו בַּ⁠מִּנְחָה֙ הַ⁠הֹלֶ֣כֶת לְ⁠פָנָ֔⁠י וְ⁠אַחֲרֵי־כֵן֙ אֶרְאֶ֣ה פָנָ֔י⁠ו אוּלַ֖י יִשָּׂ֥א פָנָֽ⁠י׃","wa⁠ʼàmarĕţė֕m gȧ֗m hiné֛̇h ʻabĕdĕ̇⁠ká֥ yaʻàqò֖b ʼaẖàré֑y⁠nẇ kiֽ̇y-ʼáma֞r ʼàkapĕ̇rá֣h páná֗y⁠w bȧ⁠mi̇nĕẖáh֙ ha⁠hòle֣keţ lĕ⁠páná֔⁠y wĕ⁠ʼaẖàréy-kén֙ ʼerĕʼe֣h páná֔y⁠w ʼẇla֖y yişá֥̇̂ʼ pánáֽ⁠y׃"],[32,21,"וַ⁠תַּעֲבֹ֥ר הַ⁠מִּנְחָ֖ה עַל־פָּנָ֑י⁠ו וְ⁠ה֛וּא לָ֥ן בַּ⁠לַּֽיְלָה־הַ⁠ה֖וּא בַּֽ⁠מַּחֲנֶֽה׃","wa⁠ţȧʻàbò֥r ha⁠mi̇nĕẖá֖h ʻal-pá̇ná֑y⁠w wĕ⁠h֛ẇʼ lá֥n bȧ⁠lȧֽyĕláh-ha⁠h֖ẇʼ bȧֽ⁠mȧẖàneֽh׃"],[32,22,"וַ⁠יָּ֣קָם ׀ בַּ⁠לַּ֣יְלָה ה֗וּא וַ⁠יִּקַּ֞ח אֶת־שְׁתֵּ֤י נָשָׁי⁠ו֙ וְ⁠אֶת־שְׁתֵּ֣י שִׁפְחֹתָ֔י⁠ו וְ⁠אֶת־אַחַ֥ד עָשָׂ֖ר יְלָדָ֑י⁠ו וַֽ⁠יַּעֲבֹ֔ר אֵ֖ת מַעֲבַ֥ר יַבֹּֽק׃","wa⁠yá֣̇qám ׀ bȧ⁠lȧ֣yĕláh h֗ẇʼ wa⁠yi̇qȧ֞ẖ ʼeţ-şĕ̌ţé֤̇y náşá̌y⁠w֙ wĕ⁠ʼeţ-şĕ̌ţé֣̇y şǐpĕẖòţá֔y⁠w wĕ⁠ʼeţ-ʼaẖa֥d ʻáşá֖̂r yĕládá֑y⁠w waֽ⁠yȧʻàbò֔r ʼé֖ţ maʻàba֥r yabòֽ̇q׃"],[32,23,"וַ⁠יִּקָּחֵ֔⁠ם וַ⁠יַּֽעֲבִרֵ֖⁠ם אֶת־הַ⁠נָּ֑חַל וַֽ⁠יַּעֲבֵ֖ר אֶת־אֲשֶׁר־ל⁠וֹ׃","wa⁠yi̇qá̇ẖé֔⁠m wa⁠yȧֽʻàbiré֖⁠m ʼeţ-ha⁠ná֑̇ẖal waֽ⁠yȧʻàbé֖r ʼeţ-ʼàşěr-l⁠wò׃"],[32,24,"וַ⁠יִּוָּתֵ֥ר יַעֲקֹ֖ב לְ⁠בַדּ֑⁠וֹ וַ⁠יֵּאָבֵ֥ק אִישׁ֙ עִמּ֔⁠וֹ עַ֖ד עֲל֥וֹת הַ⁠שָּֽׁחַר׃","wa⁠yi̇wá̇ţé֥r yaʻàqò֖b lĕ⁠baḋ֑⁠wò wa⁠yé̇ʼábé֥q ʼiyş̌֙ ʻiṁ֔⁠wò ʻa֖d ʻàl֥wòţ ha⁠şáֽ̇̌ẖar׃"],[32,25,"וַ⁠יַּ֗רְא כִּ֣י לֹ֤א יָכֹל֙ ל֔⁠וֹ וַ⁠יִּגַּ֖ע בְּ⁠כַף־יְרֵכ֑⁠וֹ וַ⁠תֵּ֨קַע֙ כַּף־יֶ֣רֶךְ יַעֲקֹ֔ב בְּ⁠הֵֽאָבְק֖⁠וֹ עִמּֽ⁠וֹ׃","wa⁠yȧ֗rĕʼ ki֣̇y lò֤ʼ yákòl֙ l֔⁠wò wa⁠yi̇gȧ֖ʻ bĕ̇⁠kap-yĕrék֑⁠wò wa⁠ţé̇֨qaʻ֙ kȧp-ye֣rekĕ yaʻàqò֔b bĕ̇⁠héֽʼábĕq֖⁠wò ʻiṁֽ⁠wò׃"],[32,26,"וַ⁠יֹּ֣אמֶר שַׁלְּחֵ֔⁠נִי כִּ֥י עָלָ֖ה הַ⁠שָּׁ֑חַר וַ⁠יֹּ֨אמֶר֙ לֹ֣א אֲשַֽׁלֵּחֲ⁠ךָ֔ כִּ֖י אִם־בֵּרַכְתָּֽ⁠נִי׃","wa⁠yò֣̇ʼmer şǎlĕ̇ẖé֔⁠niy ki֥̇y ʻálá֖h ha⁠şá֑̇̌ẖar wa⁠yò̇֨ʼmer֙ lò֣ʼ ʼàşǎֽlé̇ẖà⁠ká֔ ki֖̇y ʼim-bé̇rakĕţáֽ̇⁠niy׃"],[32,27,"וַ⁠יֹּ֥אמֶר אֵלָ֖י⁠ו מַה־שְּׁמֶ֑⁠ךָ וַ⁠יֹּ֖אמֶר יַעֲקֹֽב׃","wa⁠yò֥̇ʼmer ʼélá֖y⁠w mah-şĕ̇̌me֑⁠ká wa⁠yò֖̇ʼmer yaʻàqòֽb׃"],[32,28,"וַ⁠יֹּ֗אמֶר לֹ֤א יַעֲקֹב֙ יֵאָמֵ֥ר עוֹד֙ שִׁמְ⁠ךָ֔ כִּ֖י אִם־יִשְׂרָאֵ֑ל כִּֽי־שָׂרִ֧יתָ עִם־אֱלֹהִ֛ים וְ⁠עִם־אֲנָשִׁ֖ים וַ⁠תּוּכָֽל׃","wa⁠yò̇֗ʼmer lò֤ʼ yaʻàqòb֙ yéʼámé֥r ʻwòd֙ şǐmĕ⁠ká֔ ki֖̇y ʼim-yişĕ̂ráʼé֑l kiֽ̇y-şá̂ri֧yţá ʻim-ʼèlòhi֛ym wĕ⁠ʻim-ʼànáşǐ֖ym wa⁠ţ̇ẇkáֽl׃"],[32,29,"וַ⁠יִּשְׁאַ֣ל יַעֲקֹ֗ב וַ⁠יֹּ֨אמֶר֙ הַגִּֽידָ⁠ה־נָּ֣א שְׁמֶ֔⁠ךָ וַ⁠יֹּ֕אמֶר לָ֥⁠מָּה זֶּ֖ה תִּשְׁאַ֣ל לִ⁠שְׁמִ֑⁠י וַ⁠יְבָ֥רֶךְ אֹת֖⁠וֹ שָֽׁם׃","wa⁠yi̇şĕ̌ʼa֣l yaʻàqò֗b wa⁠yò̇֨ʼmer֙ hagiֽ̇ydá⁠h-ná֣̇ʼ şĕ̌me֔⁠ká wa⁠yò̇֕ʼmer lá֥⁠má̇h zė֖h ţi̇şĕ̌ʼa֣l li⁠şĕ̌mi֑⁠y wa⁠yĕbá֥rekĕ ʼòţ֖⁠wò şáֽ̌m׃"],[32,30,"וַ⁠יִּקְרָ֧א יַעֲקֹ֛ב שֵׁ֥ם הַ⁠מָּק֖וֹם פְּנִיאֵ֑ל כִּֽי־רָאִ֤יתִי אֱלֹהִים֙ פָּנִ֣ים אֶל־פָּנִ֔ים וַ⁠תִּנָּצֵ֖ל נַפְשִֽׁ⁠י׃","wa⁠yi̇qĕrá֧ʼ yaʻàqò֛b şé֥̌m ha⁠má̇q֖wòm pĕ̇niyʼé֑l kiֽ̇y-ráʼi֤yţiy ʼèlòhiym֙ pá̇ni֣ym ʼel-pá̇ni֔ym wa⁠ţi̇ná̇ẕé֖l napĕşǐֽ⁠y׃"],[32,31,"וַ⁠יִּֽזְרַֽח־ל֣⁠וֹ הַ⁠שֶּׁ֔מֶשׁ כַּ⁠אֲשֶׁ֥ר עָבַ֖ר אֶת־פְּנוּאֵ֑ל וְ⁠ה֥וּא צֹלֵ֖עַ עַל־יְרֵכֽ⁠וֹ׃","wa⁠yiֽ̇zĕraֽẖ-l֣⁠wò ha⁠şė̌֔meş̌ kȧ⁠ʼàşě֥r ʻába֖r ʼeţ-pĕ̇nẇʼé֑l wĕ⁠h֥ẇʼ ẕòlé֖ʻa ʻal-yĕrékֽ⁠wò׃"],[32,32,"עַל־כֵּ֡ן לֹֽא־יֹאכְל֨וּ בְנֵֽי־יִשְׂרָאֵ֜ל אֶת־גִּ֣יד הַ⁠נָּשֶׁ֗ה אֲשֶׁר֙ עַל־כַּ֣ף הַ⁠יָּרֵ֔ךְ עַ֖ד הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה כִּ֤י נָגַע֙ בְּ⁠כַף־יֶ֣רֶךְ יַעֲקֹ֔ב בְּ⁠גִ֖יד הַ⁠נָּשֶֽׁה׃","ʻal-ké̇֡n lòֽʼ-yòʼkĕl֨ẇ bĕnéֽy-yişĕ̂ráʼé֜l ʼeţ-gi֣̇yd ha⁠ná̇şě֗h ʼàşěr֙ ʻal-kȧ֣p ha⁠yá̇ré֔kĕ ʻa֖d ha⁠ẏ֣wòm ha⁠zė֑h ki֤̇y nágaʻ֙ bĕ̇⁠kap-ye֣rekĕ yaʻàqò֔b bĕ̇⁠gi֖yd ha⁠ná̇şěֽh׃"],[33,1,"וַ⁠יִּשָּׂ֨א יַעֲקֹ֜ב עֵינָ֗י⁠ו וַ⁠יַּרְא֙ וְ⁠הִנֵּ֣ה עֵשָׂ֣ו בָּ֔א וְ⁠עִמּ֕⁠וֹ אַרְבַּ֥ע מֵא֖וֹת אִ֑ישׁ וַ⁠יַּ֣חַץ אֶת־הַ⁠יְלָדִ֗ים עַל־לֵאָה֙ וְ⁠עַל־רָחֵ֔ל וְ⁠עַ֖ל שְׁתֵּ֥י הַ⁠שְּׁפָחֽוֹת׃","wa⁠yi̇şá̇̂֨ʼ yaʻàqò֜b ʻéyná֗y⁠w wa⁠yȧrĕʼ֙ wĕ⁠hiné֣̇h ʻéşá֣̂w bá̇֔ʼ wĕ⁠ʻiṁ֕⁠wò ʼarĕbȧ֥ʻ méʼ֖wòţ ʼi֑yş̌ wa⁠yȧ֣ẖaẕ ʼeţ-ha⁠yĕládi֗ym ʻal-léʼáh֙ wĕ⁠ʻal-ráẖé֔l wĕ⁠ʻa֖l şĕ̌ţé֥̇y ha⁠şĕ̇̌páẖֽwòţ׃"],[33,2,"וַ⁠יָּ֧שֶׂם אֶת־הַ⁠שְּׁפָח֛וֹת וְ⁠אֶת־יַלְדֵי⁠הֶ֖ן רִֽאשֹׁנָ֑ה וְ⁠אֶת־לֵאָ֤ה וִֽ⁠ילָדֶ֨י⁠הָ֙ אַחֲרֹנִ֔ים וְ⁠אֶת־רָחֵ֥ל וְ⁠אֶת־יוֹסֵ֖ף אַחֲרֹנִֽים׃","wa⁠yá֧̇şêm ʼeţ-ha⁠şĕ̇̌páẖ֛wòţ wĕ⁠ʼeţ-yalĕdéy⁠he֖n riֽʼşò̌ná֑h wĕ⁠ʼeţ-léʼá֤h wiֽ⁠yláde֨y⁠há֙ ʼaẖàròni֔ym wĕ⁠ʼeţ-ráẖé֥l wĕ⁠ʼeţ-ywòsé֖p ʼaẖàròniֽym׃"],[33,3,"וְ⁠ה֖וּא עָבַ֣ר לִ⁠פְנֵי⁠הֶ֑ם וַ⁠יִּשְׁתַּ֤חוּ אַ֨רְצָ⁠ה֙ שֶׁ֣בַע פְּעָמִ֔ים עַד־גִּשְׁתּ֖⁠וֹ עַד־אָחִֽי⁠ו׃","wĕ⁠h֖ẇʼ ʻába֣r li⁠pĕnéy⁠he֑m wa⁠yi̇şĕ̌ţȧ֤ẖẇ ʼa֨rĕẕá⁠h֙ şě֣baʻ pĕ̇ʻámi֔ym ʻad-gi̇şĕ̌ţ֖̇⁠wò ʻad-ʼáẖiֽy⁠w׃"],[33,4,"וַ⁠יָּ֨רָץ עֵשָׂ֤ו לִ⁠קְרָאת⁠וֹ֙ וַֽ⁠יְחַבְּקֵ֔⁠הוּ וַ⁠יִּפֹּ֥ל עַל־צַוָּארָ֖⁠ו וַׄ⁠יִּׄשָּׁׄקֵ֑ׄ⁠הׄוּׄ וַ⁠יִּבְכּֽוּ׃","wa⁠yá̇֨ráẕ ʻéşá֤̂w li⁠qĕráʼţ⁠wò֙ wֽa⁠yĕẖabĕ̇qé֔⁠hẇ wa⁠yi̇pò֥̇l ʻal-ẕawá̇ʼrá֖⁠w waׄ⁠yi̇ׄşá̇̌ׄqé֑ׄ⁠hׄẇׄ wa⁠yi̇bĕkֽ̇ẇ׃"],[33,5,"וַ⁠יִּשָּׂ֣א אֶת־עֵינָ֗י⁠ו וַ⁠יַּ֤רְא אֶת־הַ⁠נָּשִׁים֙ וְ⁠אֶת־הַ⁠יְלָדִ֔ים וַ⁠יֹּ֖אמֶר מִי־אֵ֣לֶּה לָּ֑⁠ךְ וַ⁠יֹּאמַ֕ר הַ⁠יְלָדִ֕ים אֲשֶׁר־חָנַ֥ן אֱלֹהִ֖ים אֶת־עַבְדֶּֽ⁠ךָ׃","wa⁠yi̇şá֣̇̂ʼ ʼeţ-ʻéyná֗y⁠w wa⁠yȧ֤rĕʼ ʼeţ-ha⁠ná̇şǐym֙ wĕ⁠ʼeţ-ha⁠yĕládi֔ym wa⁠yò֖̇ʼmer miy-ʼé֣lėh lá֑̇⁠kĕ wa⁠yò̇ʼma֕r ha⁠yĕládi֕ym ʼàşěr-ẖána֥n ʼèlòhi֖ym ʼeţ-ʻabĕdėֽ⁠ká׃"],[33,6,"וַ⁠תִּגַּ֧שְׁןָ הַ⁠שְּׁפָח֛וֹת הֵ֥נָּה וְ⁠יַלְדֵי⁠הֶ֖ן וַ⁠תִּֽשְׁתַּחֲוֶֽיןָ׃","wa⁠ţi̇gȧ֧şĕ̌ná ha⁠şĕ̇̌páẖ֛wòţ hé֥ná̇h wĕ⁠yalĕdéy⁠he֖n wa⁠ţiֽ̇şĕ̌ţȧẖàweֽyná׃"],[33,7,"וַ⁠תִּגַּ֧שׁ גַּם־לֵאָ֛ה וִ⁠ילָדֶ֖י⁠הָ וַ⁠יִּֽשְׁתַּחֲו֑וּ וְ⁠אַחַ֗ר נִגַּ֥שׁ יוֹסֵ֛ף וְ⁠רָחֵ֖ל וַ⁠יִּֽשְׁתַּחֲוֽוּ׃","wa⁠ţi̇gȧ֧ş̌ gȧm-léʼá֛h wi⁠yláde֖y⁠há wa⁠yiֽ̇şĕ̌ţȧẖàw֑ẇ wĕ⁠ʼaẖa֗r nigȧ֥ş̌ ywòsé֛p wĕ⁠ráẖé֖l wa⁠yiֽ̇şĕ̌ţȧẖàwֽẇ׃"],[33,8,"וַ⁠יֹּ֕אמֶר מִ֥י לְ⁠ךָ֛ כָּל־הַ⁠מַּחֲנֶ֥ה הַ⁠זֶּ֖ה אֲשֶׁ֣ר פָּגָ֑שְׁתִּי וַ⁠יֹּ֕אמֶר לִ⁠מְצֹא־חֵ֖ן בְּ⁠עֵינֵ֥י אֲדֹנִֽ⁠י׃","wa⁠yò̇֕ʼmer mi֥y lĕ⁠ká֛ ká̇l-ha⁠mȧẖàne֥h ha⁠zė֖h ʼàşě֣r pá̇gá֑şĕ̌ţi̇y wa⁠yò̇֕ʼmer li⁠mĕẕòʼ-ẖé֖n bĕ̇⁠ʻéyné֥y ʼàdòniֽ⁠y׃"],[33,9,"וַ⁠יֹּ֥אמֶר עֵשָׂ֖ו יֶשׁ־לִ֣⁠י רָ֑ב אָחִ֕⁠י יְהִ֥י לְ⁠ךָ֖ אֲשֶׁר־לָֽ⁠ךְ׃","wa⁠yò֥̇ʼmer ʻéşá֖̂w yeş̌-li֣⁠y rá֑b ʼáẖi֕⁠y yĕhi֥y lĕ⁠ká֖ ʼàşěr-láֽ⁠kĕ׃"],[33,10,"וַ⁠יֹּ֣אמֶר יַעֲקֹ֗ב אַל־נָא֙ אִם־נָ֨א מָצָ֤אתִי חֵן֙ בְּ⁠עֵינֶ֔י⁠ךָ וְ⁠לָקַחְתָּ֥ מִנְחָתִ֖⁠י מִ⁠יָּדִ֑⁠י כִּ֣י עַל־כֵּ֞ן רָאִ֣יתִי פָנֶ֗י⁠ךָ כִּ⁠רְאֹ֛ת פְּנֵ֥י אֱלֹהִ֖ים וַ⁠תִּרְצֵֽ⁠נִי׃","wa⁠yò֣̇ʼmer yaʻàqò֗b ʼal-náʼ֙ ʼim-ná֨ʼ máẕá֤ʼţiy ẖén֙ bĕ̇⁠ʻéyne֔y⁠ká wĕ⁠láqaẖĕţá֥̇ minĕẖáţi֖⁠y mi⁠yá̇di֑⁠y ki֣̇y ʻal-ké̇֞n ráʼi֣yţiy páne֗y⁠ká ki̇⁠rĕʼò֛ţ pĕ̇né֥y ʼèlòhi֖ym wa⁠ţi̇rĕẕéֽ⁠niy׃"],[33,11,"קַח־נָ֤א אֶת־בִּרְכָתִ⁠י֙ אֲשֶׁ֣ר הֻבָ֣את לָ֔⁠ךְ כִּֽי־חַנַּ֥⁠נִי אֱלֹהִ֖ים וְ⁠כִ֣י יֶשׁ־לִ⁠י־כֹ֑ל וַ⁠יִּפְצַר־בּ֖⁠וֹ וַ⁠יִּקָּֽח׃","qaẖ-ná֤ʼ ʼeţ-bi̇rĕkáţi⁠y֙ ʼàşě֣r hubá֣ʼţ lá֔⁠kĕ kiֽ̇y-ẖanȧ֥⁠niy ʼèlòhi֖ym wĕ⁠ki֣y yeş̌-li⁠y-kò֑l wa⁠yi̇pĕẕar-ḃ֖⁠wò wa⁠yi̇qáֽ̇ẖ׃"],[33,12,"וַ⁠יֹּ֖אמֶר נִסְעָ֣ה וְ⁠נֵלֵ֑כָה וְ⁠אֵלְכָ֖ה לְ⁠נֶגְדֶּֽ⁠ךָ׃","wa⁠yò֖̇ʼmer nisĕʻá֣h wĕ⁠nélé֑káh wĕ⁠ʼélĕká֖h lĕ⁠negĕdėֽ⁠ká׃"],[33,13,"וַ⁠יֹּ֣אמֶר אֵלָ֗י⁠ו אֲדֹנִ֤⁠י יֹדֵ֨עַ֙ כִּֽי־הַ⁠יְלָדִ֣ים רַכִּ֔ים וְ⁠הַ⁠צֹּ֥אן וְ⁠הַ⁠בָּקָ֖ר עָל֣וֹת עָלָ֑⁠י וּ⁠דְפָקוּ⁠ם֙ י֣וֹם אֶחָ֔ד וָ⁠מֵ֖תוּ כָּל־הַ⁠צֹּֽאן׃","wa⁠yò֣̇ʼmer ʼélá֗y⁠w ʼàdòni֤⁠y yòdé֨ʻa֙ kiֽ̇y-ha⁠yĕládi֣ym raki̇֔ym wĕ⁠ha⁠ẕò֥̇ʼn wĕ⁠ha⁠bá̇qá֖r ʻál֣wòţ ʻálá֑⁠y ẇ⁠dĕpáqẇ⁠m֙ y֣wòm ʼeẖá֔d wá⁠mé֖ţẇ ká̇l-ha⁠ẕòֽ̇ʼn׃"],[33,14,"יַעֲבָר־נָ֥א אֲדֹנִ֖⁠י לִ⁠פְנֵ֣י עַבְדּ֑⁠וֹ וַ⁠אֲנִ֞י אֶֽתְנָהֲלָ֣ה לְ⁠אִטִּ֗⁠י לְ⁠רֶ֨גֶל הַ⁠מְּלָאכָ֤ה אֲשֶׁר־לְ⁠פָנַ⁠י֙ וּ⁠לְ⁠רֶ֣גֶל הַ⁠יְלָדִ֔ים עַ֛ד אֲשֶׁר־אָבֹ֥א אֶל־אֲדֹנִ֖⁠י שֵׂעִֽירָ⁠ה׃","yaʻàbár-ná֥ʼ ʼàdòni֖⁠y li⁠pĕné֣y ʻabĕḋ֑⁠wò wa⁠ʼàni֞y ʼeֽţĕnáhàlá֣h lĕ⁠ʼiti̇֗⁠y lĕ⁠re֨gel ha⁠mĕ̇láʼká֤h ʼàşěr-lĕ⁠pána⁠y֙ ẇ⁠lĕ⁠re֣gel ha⁠yĕládi֔ym ʻa֛d ʼàşěr-ʼábò֥ʼ ʼel-ʼàdòni֖⁠y şé̂ʻiֽyrá⁠h׃"],[33,15,"וַ⁠יֹּ֣אמֶר עֵשָׂ֔ו אַצִּֽיגָה־נָּ֣א עִמְּ⁠ךָ֔ מִן־הָ⁠עָ֖ם אֲשֶׁ֣ר אִתִּ֑⁠י וַ⁠יֹּ֨אמֶר֙ לָ֣⁠מָּה זֶּ֔ה אֶמְצָא־חֵ֖ן בְּ⁠עֵינֵ֥י אֲדֹנִֽ⁠י׃","wa⁠yò֣̇ʼmer ʻéşá̂֔w ʼaẕiֽ̇ygáh-ná֣̇ʼ ʻimĕ̇⁠ká֔ min-há⁠ʻá֖m ʼàşě֣r ʼiţi֑̇⁠y wa⁠yò̇֨ʼmer֙ lá֣⁠má̇h zė֔h ʼemĕẕáʼ-ẖé֖n bĕ̇⁠ʻéyné֥y ʼàdòniֽ⁠y׃"],[33,16,"וַ⁠יָּשָׁב֩ בַּ⁠יּ֨וֹם הַ⁠ה֥וּא עֵשָׂ֛ו לְ⁠דַרְכּ֖⁠וֹ שֵׂעִֽירָ⁠ה׃","wa⁠yá̇şá̌b֩ bȧ⁠ẏ֨wòm ha⁠h֥ẇʼ ʻéşá֛̂w lĕ⁠darĕk֖̇⁠wò şé̂ʻiֽyrá⁠h׃"],[33,17,"וְ⁠יַעֲקֹב֙ נָסַ֣ע סֻכֹּ֔תָ⁠ה וַ⁠יִּ֥בֶן ל֖⁠וֹ בָּ֑יִת וּ⁠לְ⁠מִקְנֵ֨⁠הוּ֙ עָשָׂ֣ה סֻכֹּ֔ת עַל־כֵּ֛ן קָרָ֥א שֵׁם־הַ⁠מָּק֖וֹם סֻכּֽוֹת׃ס","wĕ⁠yaʻàqòb֙ nása֣ʻ sukò̇֔ţá⁠h wa⁠yi֥̇ben l֖⁠wò bá֑̇yiţ ẇ⁠lĕ⁠miqĕné֨⁠hẇ֙ ʻáşá֣̂h sukò̇֔ţ ʻal-ké֛̇n qárá֥ʼ şé̌m-ha⁠má̇q֖wòm sukֽ̇wòţ׃s"],[33,18,"וַ⁠יָּבֹא֩ יַעֲקֹ֨ב שָׁלֵ֜ם עִ֣יר שְׁכֶ֗ם אֲשֶׁר֙ בְּ⁠אֶ֣רֶץ כְּנַ֔עַן בְּ⁠בֹא֖⁠וֹ מִ⁠פַּדַּ֣ן אֲרָ֑ם וַ⁠יִּ֖חַן אֶת־פְּנֵ֥י הָ⁠עִֽיר׃","wa⁠yá̇bòʼ֩ yaʻàqò֨b şá̌lé֜m ʻi֣yr şĕ̌ke֗m ʼàşěr֙ bĕ̇⁠ʼe֣reẕ kĕ̇na֔ʻan bĕ̇⁠bòʼ֖⁠wò mi⁠pȧdȧ֣n ʼàrá֑m wa⁠yi֖̇ẖan ʼeţ-pĕ̇né֥y há⁠ʻiֽyr׃"],[33,19,"וַ⁠יִּ֜קֶן אֶת־חֶלְקַ֣ת הַ⁠שָּׂדֶ֗ה אֲשֶׁ֤ר נָֽטָה־שָׁם֙ אָהֳל֔⁠וֹ מִ⁠יַּ֥ד בְּנֵֽי־חֲמ֖וֹר אֲבִ֣י שְׁכֶ֑ם בְּ⁠מֵאָ֖ה קְשִׂיטָֽה׃","wa⁠yi̇֜qen ʼeţ-ẖelĕqa֣ţ ha⁠şá̇̂de֗h ʼàşě֤r náֽtáh-şá̌m֙ ʼáhol֔⁠wò mi⁠yȧ֥d bĕ̇néֽy-ẖàm֖wòr ʼàbi֣y şĕ̌ke֑m bĕ̇⁠méʼá֖h qĕşîytáֽh׃"],[33,20,"וַ⁠יַּצֶּב־שָׁ֖ם מִזְבֵּ֑חַ וַ⁠יִּ֨קְרָא־ל֔⁠וֹ אֵ֖ל אֱלֹהֵ֥י יִשְׂרָאֵֽל׃ס","wa⁠yȧẕėb-şá֖̌m mizĕbé֑̇ẖa wa⁠yi̇֨qĕráʼ-l֔⁠wò ʼé֖l ʼèlòhé֥y yişĕ̂ráʼéֽl׃s"],[34,1,"וַ⁠תֵּצֵ֤א דִינָה֙ בַּת־לֵאָ֔ה אֲשֶׁ֥ר יָלְדָ֖ה לְ⁠יַעֲקֹ֑ב לִ⁠רְא֖וֹת בִּ⁠בְנ֥וֹת הָ⁠אָֽרֶץ׃","wa⁠ţé̇ẕé֤ʼ diynáh֙ bȧţ-léʼá֔h ʼàşě֥r yálĕdá֖h lĕ⁠yaʻàqò֑b li⁠rĕʼ֖wòţ bi̇⁠bĕn֥wòţ há⁠ʼáֽreẕ׃"],[34,2,"וַ⁠יַּ֨רְא אֹתָ֜⁠הּ שְׁכֶ֧ם בֶּן־חֲמ֛וֹר הַֽ⁠חִוִּ֖י נְשִׂ֣יא הָ⁠אָ֑רֶץ וַ⁠יִּקַּ֥ח אֹתָ֛⁠הּ וַ⁠יִּשְׁכַּ֥ב אֹתָ֖⁠הּ וַ⁠יְעַנֶּֽ⁠הָ׃","wa⁠yȧ֨rĕʼ ʼòţá֜⁠ḣ şĕ̌ke֧m bėn-ẖàm֛wòr hֽa⁠ẖiwi֖̇y nĕşî֣yʼ há⁠ʼá֑reẕ wa⁠yi̇qȧ֥ẖ ʼòţá֛⁠ḣ wa⁠yi̇şĕ̌kȧ֥b ʼòţá֖⁠ḣ wa⁠yĕʻanėֽ⁠há׃"],[34,3,"וַ⁠תִּדְבַּ֣ק נַפְשׁ֔⁠וֹ בְּ⁠דִינָ֖ה בַּֽת־יַעֲקֹ֑ב וַ⁠יֶּֽאֱהַב֙ אֶת־הַֽ⁠נַּעֲרָ֔ וַ⁠יְדַבֵּ֖ר עַל־לֵ֥ב הַֽ⁠נַּעֲרָֽ׃","wa⁠ţi̇dĕbȧ֣q napĕş̌֔⁠wò bĕ̇⁠diyná֖h bȧֽţ-yaʻàqò֑b wa⁠yėֽʼèhab֙ ʼeţ-haֽ⁠nȧʻàrá֔ wa⁠yĕdabé֖̇r ʻal-lé֥b haֽ⁠nȧʻàráֽ׃"],[34,4,"וַ⁠יֹּ֣אמֶר שְׁכֶ֔ם אֶל־חֲמ֥וֹר אָבִ֖י⁠ו לֵ⁠אמֹ֑ר קַֽח־לִ֛⁠י אֶת־הַ⁠יַּלְדָּ֥ה הַ⁠זֹּ֖את לְ⁠אִשָּֽׁה׃","wa⁠yò֣̇ʼmer şĕ̌ke֔m ʼel-ẖàm֥wòr ʼábi֖y⁠w lé⁠ʼmò֑r qaֽẖ-li֛⁠y ʼeţ-ha⁠yȧlĕdá֥̇h ha⁠zò֖̇ʼţ lĕ⁠ʼişáֽ̇̌h׃"],[34,5,"וְ⁠יַעֲקֹ֣ב שָׁמַ֗ע כִּ֤י טִמֵּא֙ אֶת־דִּינָ֣ה בִתּ֔⁠וֹ וּ⁠בָנָ֛י⁠ו הָי֥וּ אֶת־מִקְנֵ֖⁠הוּ בַּ⁠שָּׂדֶ֑ה וְ⁠הֶחֱרִ֥שׁ יַעֲקֹ֖ב עַד־בֹּאָֽ⁠ם׃","wĕ⁠yaʻàqò֣b şá̌ma֗ʻ ki֤̇y timé̇ʼ֙ ʼeţ-di̇yná֣h biţ̇֔⁠wò ẇ⁠báná֛y⁠w háy֥ẇ ʼeţ-miqĕné֖⁠hẇ bȧ⁠şá̇̂de֑h wĕ⁠heẖèri֥ş̌ yaʻàqò֖b ʻad-bò̇ʼáֽ⁠m׃"],[34,6,"וַ⁠יֵּצֵ֛א חֲמ֥וֹר אֲבִֽי־שְׁכֶ֖ם אֶֽל־יַעֲקֹ֑ב לְ⁠דַבֵּ֖ר אִתּֽ⁠וֹ׃","wa⁠yé̇ẕé֛ʼ ẖàm֥wòr ʼàbiֽy-şĕ̌ke֖m ʼeֽl-yaʻàqò֑b lĕ⁠dabé֖̇r ʼiţֽ̇⁠wò׃"],[34,7,"וּ⁠בְנֵ֨י יַעֲקֹ֜ב בָּ֤אוּ מִן־הַ⁠שָּׂדֶה֙ כְּ⁠שָׁמְעָ֔⁠ם וַ⁠יִּֽתְעַצְּבוּ֙ הָֽ⁠אֲנָשִׁ֔ים וַ⁠יִּ֥חַר לָ⁠הֶ֖ם מְאֹ֑ד כִּֽי־נְבָלָ֞ה עָשָׂ֣ה בְ⁠יִשְׂרָאֵ֗ל לִ⁠שְׁכַּב֙ אֶת־בַּֽת־יַעֲקֹ֔ב וְ⁠כֵ֖ן לֹ֥א יֵעָשֶֽׂה׃","ẇ⁠bĕné֨y yaʻàqò֜b bá֤̇ʼẇ min-ha⁠şá̇̂deh֙ kĕ̇⁠şá̌mĕʻá֔⁠m wa⁠yiֽ̇ţĕʻaẕĕ̇bẇ֙ háֽ⁠ʼànáşǐ֔ym wa⁠yi֥̇ẖar lá⁠he֖m mĕʼò֑d kiֽ̇y-nĕbálá֞h ʻáşá֣̂h bĕ⁠yişĕ̂ráʼé֗l li⁠şĕ̌kȧb֙ ʼeţ-bȧֽţ-yaʻàqò֔b wĕ⁠ké֖n lò֥ʼ yéʻáşêֽh׃"],[34,8,"וַ⁠יְדַבֵּ֥ר חֲמ֖וֹר אִתָּ֣⁠ם לֵ⁠אמֹ֑ר שְׁכֶ֣ם בְּנִ֗⁠י חָֽשְׁקָ֤ה נַפְשׁ⁠וֹ֙ בְּ⁠בִתְּ⁠כֶ֔ם תְּנ֨וּ נָ֥א אֹתָ֛⁠הּ ל֖⁠וֹ לְ⁠אִשָּֽׁה׃","wa⁠yĕdabé֥̇r ẖàm֖wòr ʼiţá֣̇⁠m lé⁠ʼmò֑r şĕ̌ke֣m bĕ̇ni֗⁠y ẖáֽşĕ̌qá֤h napĕş̌⁠wò֙ bĕ̇⁠biţĕ̇⁠ke֔m ţĕ̇n֨ẇ ná֥ʼ ʼòţá֛⁠ḣ l֖⁠wò lĕ⁠ʼişáֽ̇̌h׃"],[34,9,"וְ⁠הִֽתְחַתְּנ֖וּ אֹתָ֑⁠נוּ בְּנֹֽתֵי⁠כֶם֙ תִּתְּנוּ־לָ֔⁠נוּ וְ⁠אֶת־בְּנֹתֵ֖י⁠נוּ תִּקְח֥וּ לָ⁠כֶֽם׃","wĕ⁠hiֽţĕẖaţĕ̇n֖ẇ ʼòţá֑⁠nẇ bĕ̇nòֽţéy⁠kem֙ ţi̇ţĕ̇nẇ-lá֔⁠nẇ wĕ⁠ʼeţ-bĕ̇nòţé֖y⁠nẇ ţi̇qĕẖ֥ẇ lá⁠keֽm׃"],[34,10,"וְ⁠אִתָּ֖⁠נוּ תֵּשֵׁ֑בוּ וְ⁠הָ⁠אָ֨רֶץ֙ תִּהְיֶ֣ה לִ⁠פְנֵי⁠כֶ֔ם שְׁבוּ֙ וּ⁠סְחָר֔וּ⁠הָ וְ⁠הֵֽאָחֲז֖וּ בָּֽ⁠הּ׃","wĕ⁠ʼiţá֖̇⁠nẇ ţé̇şé֑̌bẇ wĕ⁠há⁠ʼá֨reẕ֙ ţi̇hĕye֣h li⁠pĕnéy⁠ke֔m şĕ̌bẇ֙ ẇ⁠sĕẖár֔ẇ⁠há wĕ⁠héֽʼáẖàz֖ẇ báֽ̇⁠ḣ׃"],[34,11,"וַ⁠יֹּ֤אמֶר שְׁכֶם֙ אֶל־אָבִ֣י⁠ה וְ⁠אֶל־אַחֶ֔י⁠הָ אֶמְצָא־חֵ֖ן בְּ⁠עֵינֵי⁠כֶ֑ם וַ⁠אֲשֶׁ֥ר תֹּאמְר֛וּ אֵלַ֖⁠י אֶתֵּֽן׃","wa⁠yò֤̇ʼmer şĕ̌kem֙ ʼel-ʼábi֣y⁠h wĕ⁠ʼel-ʼaẖe֔y⁠há ʼemĕẕáʼ-ẖé֖n bĕ̇⁠ʻéynéy⁠ke֑m wa⁠ʼàşě֥r ţò̇ʼmĕr֛ẇ ʼéla֖⁠y ʼeţéֽ̇n׃"],[34,12,"הַרְבּ֨וּ עָלַ֤⁠י מְאֹד֙ מֹ֣הַר וּ⁠מַתָּ֔ן וְ⁠אֶ֨תְּנָ֔ה כַּ⁠אֲשֶׁ֥ר תֹּאמְר֖וּ אֵלָ֑⁠י וּ⁠תְנוּ־לִ֥⁠י אֶת־הַֽ⁠נַּעֲרָ֖ לְ⁠אִשָּֽׁה׃","harĕḃ֨ẇ ʻála֤⁠y mĕʼòd֙ mò֣har ẇ⁠maţá̇֔n wĕ⁠ʼe֨ţĕ̇ná֔h kȧ⁠ʼàşě֥r ţò̇ʼmĕr֖ẇ ʼélá֑⁠y ẇ⁠ţĕnẇ-li֥⁠y ʼeţ-haֽ⁠nȧʻàrá֖ lĕ⁠ʼişáֽ̇̌h׃"],[34,13,"וַ⁠יַּעֲנ֨וּ בְנֵֽי־יַעֲקֹ֜ב אֶת־שְׁכֶ֨ם וְ⁠אֶת־חֲמ֥וֹר אָבִ֛י⁠ו בְּ⁠מִרְמָ֖ה וַ⁠יְדַבֵּ֑רוּ אֲשֶׁ֣ר טִמֵּ֔א אֵ֖ת דִּינָ֥ה אֲחֹתָֽ⁠ם׃","wa⁠yȧʻàn֨ẇ bĕnéֽy-yaʻàqò֜b ʼeţ-şĕ̌ke֨m wĕ⁠ʼeţ-ẖàm֥wòr ʼábi֛y⁠w bĕ̇⁠mirĕmá֖h wa⁠yĕdabé֑̇rẇ ʼàşě֣r timé̇֔ʼ ʼé֖ţ di̇yná֥h ʼàẖòţáֽ⁠m׃"],[34,14,"וַ⁠יֹּאמְר֣וּ אֲלֵי⁠הֶ֗ם לֹ֤א נוּכַל֙ לַ⁠עֲשׂוֹת֙ הַ⁠דָּבָ֣ר הַ⁠זֶּ֔ה לָ⁠תֵת֙ אֶת־אֲחֹתֵ֔⁠נוּ לְ⁠אִ֖ישׁ אֲשֶׁר־ל֣⁠וֹ עָרְלָ֑ה כִּֽי־חֶרְפָּ֥ה הִ֖וא לָֽ⁠נוּ׃","wa⁠yò̇ʼmĕr֣ẇ ʼàléy⁠he֗m lò֤ʼ nẇkal֙ la⁠ʻàş̂wòţ֙ ha⁠dá̇bá֣r ha⁠zė֔h lá⁠ţéţ֙ ʼeţ-ʼàẖòţé֔⁠nẇ lĕ⁠ʼi֖yş̌ ʼàşěr-l֣⁠wò ʻárĕlá֑h kiֽ̇y-ẖerĕpá֥̇h hi֖wʼ láֽ⁠nẇ׃"],[34,15,"אַךְ־בְּ⁠זֹ֖את נֵא֣וֹת לָ⁠כֶ֑ם אִ֚ם תִּהְי֣וּ כָמֹ֔⁠נוּ לְ⁠הִמֹּ֥ל לָ⁠כֶ֖ם כָּל־זָכָֽר׃","ʼakĕ-bĕ̇⁠zò֖ʼţ néʼ֣wòţ lá⁠ke֑m ʼi֚m ţi̇hĕy֣ẇ kámò֔⁠nẇ lĕ⁠himò֥̇l lá⁠ke֖m ká̇l-zákáֽr׃"],[34,16,"וְ⁠נָתַ֤נּוּ אֶת־בְּנֹתֵ֨י⁠נוּ֙ לָ⁠כֶ֔ם וְ⁠אֶת־בְּנֹתֵי⁠כֶ֖ם נִֽקַּֽח־לָ֑⁠נוּ וְ⁠יָשַׁ֣בְנוּ אִתְּ⁠כֶ֔ם וְ⁠הָיִ֖ינוּ לְ⁠עַ֥ם אֶחָֽד׃","wĕ⁠náţa֤ṅẇ ʼeţ-bĕ̇nòţé֨y⁠nẇ֙ lá⁠ke֔m wĕ⁠ʼeţ-bĕ̇nòţéy⁠ke֖m niֽqȧֽẖ-lá֑⁠nẇ wĕ⁠yáşǎ֣bĕnẇ ʼiţĕ̇⁠ke֔m wĕ⁠háyi֖ynẇ lĕ⁠ʻa֥m ʼeẖáֽd׃"],[34,17,"וְ⁠אִם־לֹ֧א תִשְׁמְע֛וּ אֵלֵ֖י⁠נוּ לְ⁠הִמּ֑וֹל וְ⁠לָקַ֥חְנוּ אֶת־בִּתֵּ֖⁠נוּ וְ⁠הָלָֽכְנוּ׃","wĕ⁠ʼim-lò֧ʼ ţişĕ̌mĕʻ֛ẇ ʼélé֖y⁠nẇ lĕ⁠hiṁ֑wòl wĕ⁠láqa֥ẖĕnẇ ʼeţ-bi̇ţé֖̇⁠nẇ wĕ⁠háláֽkĕnẇ׃"],[34,18,"וַ⁠יִּֽיטְב֥וּ דִבְרֵי⁠הֶ֖ם בְּ⁠עֵינֵ֣י חֲמ֑וֹר וּ⁠בְ⁠עֵינֵ֖י שְׁכֶ֥ם בֶּן־חֲמֽוֹר׃","wa⁠yiֽ̇ytĕb֥ẇ dibĕréy⁠he֖m bĕ̇⁠ʻéyné֣y ẖàm֑wòr ẇ⁠bĕ⁠ʻéyné֖y şĕ̌ke֥m bėn-ẖàmֽwòr׃"],[34,19,"וְ⁠לֹֽא־אֵחַ֤ר הַ⁠נַּ֨עַר֙ לַ⁠עֲשׂ֣וֹת הַ⁠דָּבָ֔ר כִּ֥י חָפֵ֖ץ בְּ⁠בַֽת־יַעֲקֹ֑ב וְ⁠ה֣וּא נִכְבָּ֔ד מִ⁠כֹּ֖ל בֵּ֥ית אָבִֽי⁠ו׃","wĕ⁠lòֽʼ-ʼéẖa֤r ha⁠nȧ֨ʻar֙ la⁠ʻàş֣̂wòţ ha⁠dá̇bá֔r ki֥̇y ẖápé֖ẕ bĕ̇⁠baֽţ-yaʻàqò֑b wĕ⁠h֣ẇʼ nikĕbá̇֔d mi⁠kò֖̇l bé֥̇yţ ʼábiֽy⁠w׃"],[34,20,"וַ⁠יָּבֹ֥א חֲמ֛וֹר וּ⁠שְׁכֶ֥ם בְּנ֖⁠וֹ אֶל־שַׁ֣עַר עִירָ֑⁠ם וַֽ⁠יְדַבְּר֛וּ אֶל־אַנְשֵׁ֥י עִירָ֖⁠ם לֵ⁠אמֹֽר׃","wa⁠yá̇bò֥ʼ ẖàm֛wòr ẇ⁠şĕ̌ke֥m bĕ̇n֖⁠wò ʼel-şǎ֣ʻar ʻiyrá֑⁠m waֽ⁠yĕdabĕ̇r֛ẇ ʼel-ʼanĕşé֥̌y ʻiyrá֖⁠m lé⁠ʼmòֽr׃"],[34,21,"הָ⁠אֲנָשִׁ֨ים הָ⁠אֵ֜לֶּה שְֽׁלֵמִ֧ים הֵ֣ם אִתָּ֗⁠נוּ וְ⁠יֵשְׁב֤וּ בָ⁠אָ֨רֶץ֙ וְ⁠יִסְחֲר֣וּ אֹתָ֔⁠הּ וְ⁠הָ⁠אָ֛רֶץ הִנֵּ֥ה רַֽחֲבַת־יָדַ֖יִם לִ⁠פְנֵי⁠הֶ֑ם אֶת־בְּנֹתָ⁠ם֙ נִקַּֽח־לָ֣⁠נוּ לְ⁠נָשִׁ֔ים וְ⁠אֶת־בְּנֹתֵ֖י⁠נוּ נִתֵּ֥ן לָ⁠הֶֽם׃","há⁠ʼànáşǐ֨ym há⁠ʼé֜lėh şĕֽ̌lémi֧ym hé֣m ʼiţá̇֗⁠nẇ wĕ⁠yéşĕ̌b֤ẇ bá⁠ʼá֨reẕ֙ wĕ⁠yisĕẖàr֣ẇ ʼòţá֔⁠ḣ wĕ⁠há⁠ʼá֛reẕ hiné֥̇h raֽẖàbaţ-yáda֖yim li⁠pĕnéy⁠he֑m ʼeţ-bĕ̇nòţá⁠m֙ niqȧֽẖ-lá֣⁠nẇ lĕ⁠náşǐ֔ym wĕ⁠ʼeţ-bĕ̇nòţé֖y⁠nẇ niţé֥̇n lá⁠heֽm׃"],[34,22,"אַךְ־בְּ֠⁠זֹאת יֵאֹ֨תוּ לָ֤⁠נוּ הָ⁠אֲנָשִׁים֙ לָ⁠שֶׁ֣בֶת אִתָּ֔⁠נוּ לִ⁠הְי֖וֹת לְ⁠עַ֣ם אֶחָ֑ד בְּ⁠הִמּ֥וֹל לָ֨⁠נוּ֙ כָּל־זָכָ֔ר כַּ⁠אֲשֶׁ֖ר הֵ֥ם נִמֹּלִֽים׃","ʼakĕ-bĕ̇֠⁠zòʼţ yéʼò֨ţẇ lá֤⁠nẇ há⁠ʼànáşǐym֙ lá⁠şě֣beţ ʼiţá̇֔⁠nẇ li⁠hĕy֖wòţ lĕ⁠ʻa֣m ʼeẖá֑d bĕ̇⁠hiṁ֥wòl lá֨⁠nẇ֙ ká̇l-záká֔r kȧ⁠ʼàşě֖r hé֥m nimò̇liֽym׃"],[34,23,"מִקְנֵ⁠הֶ֤ם וְ⁠קִנְיָנָ⁠ם֙ וְ⁠כָל־בְּהֶמְתָּ֔⁠ם הֲ⁠ל֥וֹא לָ֖⁠נוּ הֵ֑ם אַ֚ךְ נֵא֣וֹתָה לָ⁠הֶ֔ם וְ⁠יֵשְׁב֖וּ אִתָּֽ⁠נוּ׃","miqĕné⁠he֤m wĕ⁠qinĕyáná⁠m֙ wĕ⁠kál-bĕ̇hemĕţá̇֔⁠m hà⁠l֥wòʼ lá֖⁠nẇ hé֑m ʼa֚kĕ néʼ֣wòţáh lá⁠he֔m wĕ⁠yéşĕ̌b֖ẇ ʼiţáֽ̇⁠nẇ׃"],[34,24,"וַ⁠יִּשְׁמְע֤וּ אֶל־חֲמוֹר֙ וְ⁠אֶל־שְׁכֶ֣ם בְּנ֔⁠וֹ כָּל־יֹצְאֵ֖י שַׁ֣עַר עִיר֑⁠וֹ וַ⁠יִּמֹּ֨לוּ֙ כָּל־זָכָ֔ר כָּל־יֹצְאֵ֖י שַׁ֥עַר עִירֽ⁠וֹ׃","wa⁠yi̇şĕ̌mĕʻ֤ẇ ʼel-ẖàmwòr֙ wĕ⁠ʼel-şĕ̌ke֣m bĕ̇n֔⁠wò ká̇l-yòẕĕʼé֖y şǎ֣ʻar ʻiyr֑⁠wò wa⁠yi̇mò̇֨lẇ֙ ká̇l-záká֔r ká̇l-yòẕĕʼé֖y şǎ֥ʻar ʻiyrֽ⁠wò׃"],[34,25,"וַ⁠יְהִי֩ בַ⁠יּ֨וֹם הַ⁠שְּׁלִישִׁ֜י בִּֽ⁠הְיוֹתָ֣⁠ם כֹּֽאֲבִ֗ים וַ⁠יִּקְח֣וּ שְׁנֵֽי־בְנֵי־יַ֠עֲקֹב שִׁמְע֨וֹן וְ⁠לֵוִ֜י אֲחֵ֤י דִינָה֙ אִ֣ישׁ חַרְבּ֔⁠וֹ וַ⁠יָּבֹ֥אוּ עַל־הָ⁠עִ֖יר בֶּ֑טַח וַ⁠יַּֽהַרְג֖וּ כָּל־זָכָֽר׃","wa⁠yĕhiy֩ ba⁠ẏ֨wòm ha⁠şĕ̇̌liyşǐ֜y biֽ̇⁠hĕywòţá֣⁠m kòֽ̇ʼàbi֗ym wa⁠yi̇qĕẖ֣ẇ şĕ̌néֽy-bĕnéy-ya֠ʻàqòb şǐmĕʻ֨wòn wĕ⁠léwi֜y ʼàẖé֤y diynáh֙ ʼi֣yş̌ ẖarĕḃ֔⁠wò wa⁠yá̇bò֥ʼẇ ʻal-há⁠ʻi֖yr bė֑taẖ wa⁠yȧֽharĕg֖ẇ ká̇l-zákáֽr׃"],[34,26,"וְ⁠אֶת־חֲמוֹר֙ וְ⁠אֶת־שְׁכֶ֣ם בְּנ֔⁠וֹ הָרְג֖וּ לְ⁠פִי־חָ֑רֶב וַ⁠יִּקְח֧וּ אֶת־דִּינָ֛ה מִ⁠בֵּ֥ית שְׁכֶ֖ם וַ⁠יֵּצֵֽאוּ׃","wĕ⁠ʼeţ-ẖàmwòr֙ wĕ⁠ʼeţ-şĕ̌ke֣m bĕ̇n֔⁠wò hárĕg֖ẇ lĕ⁠piy-ẖá֑reb wa⁠yi̇qĕẖ֧ẇ ʼeţ-di̇yná֛h mi⁠bé֥̇yţ şĕ̌ke֖m wa⁠yé̇ẕéֽʼẇ׃"],[34,27,"בְּנֵ֣י יַעֲקֹ֗ב בָּ֚אוּ עַל־הַ֣⁠חֲלָלִ֔ים וַ⁠יָּבֹ֖זּוּ הָ⁠עִ֑יר אֲשֶׁ֥ר טִמְּא֖וּ אֲחוֹתָֽ⁠ם׃","bĕ̇né֣y yaʻàqò֗b bá֚̇ʼẇ ʻal-ha֣⁠ẖàláli֔ym wa⁠yá̇bò֖żẇ há⁠ʻi֑yr ʼàşě֥r timĕ̇ʼ֖ẇ ʼàẖwòţáֽ⁠m׃"],[34,28,"אֶת־צֹאנָ֥⁠ם וְ⁠אֶת־בְּקָרָ֖⁠ם וְ⁠אֶת־חֲמֹרֵי⁠הֶּ֑ם וְ⁠אֵ֧ת אֲשֶׁר־בָּ⁠עִ֛יר וְ⁠אֶת־אֲשֶׁ֥ר בַּ⁠שָּׂדֶ֖ה לָקָֽחוּ׃","ʼeţ-ẕòʼná֥⁠m wĕ⁠ʼeţ-bĕ̇qárá֖⁠m wĕ⁠ʼeţ-ẖàmòréy⁠hė֑m wĕ⁠ʼé֧ţ ʼàşěr-bá̇⁠ʻi֛yr wĕ⁠ʼeţ-ʼàşě֥r bȧ⁠şá̇̂de֖h láqáֽẖẇ׃"],[34,29,"וְ⁠אֶת־כָּל־חֵילָ֤⁠ם וְ⁠אֶת־כָּל־טַפָּ⁠ם֙ וְ⁠אֶת־נְשֵׁי⁠הֶ֔ם שָׁב֖וּ וַ⁠יָּבֹ֑זּוּ וְ⁠אֵ֖ת כָּל־אֲשֶׁ֥ר בַּ⁠בָּֽיִת׃","wĕ⁠ʼeţ-ká̇l-ẖéylá֤⁠m wĕ⁠ʼeţ-ká̇l-tapá̇⁠m֙ wĕ⁠ʼeţ-nĕşé̌y⁠he֔m şá̌b֖ẇ wa⁠yá̇bò֑żẇ wĕ⁠ʼé֖ţ ká̇l-ʼàşě֥r bȧ⁠báֽ̇yiţ׃"],[34,30,"וַ⁠יֹּ֨אמֶר יַעֲקֹ֜ב אֶל־שִׁמְע֣וֹן וְ⁠אֶל־לֵוִי֮ עֲכַרְתֶּ֣ם אֹתִ⁠י֒ לְ⁠הַבְאִישֵׁ֨⁠נִי֙ בְּ⁠יֹשֵׁ֣ב הָ⁠אָ֔רֶץ בַּֽ⁠כְּנַעֲנִ֖י וּ⁠בַ⁠פְּרִזִּ֑י וַ⁠אֲנִי֙ מְתֵ֣י מִסְפָּ֔ר וְ⁠נֶאֶסְפ֤וּ עָלַ⁠י֙ וְ⁠הִכּ֔וּ⁠נִי וְ⁠נִשְׁמַדְתִּ֖י אֲנִ֥י וּ⁠בֵיתִֽ⁠י׃","wa⁠yò̇֨ʼmer yaʻàqò֜b ʼel-şǐmĕʻ֣wòn wĕ⁠ʼel-léwiy֮ ʻàkarĕţė֣m ʼòţi⁠y֒ lĕ⁠habĕʼiyşé̌֨⁠niy֙ bĕ̇⁠yòşé֣̌b há⁠ʼá֔reẕ bȧֽ⁠kĕ̇naʻàni֖y ẇ⁠ba⁠pĕ̇rizi֑̇y wa⁠ʼàniy֙ mĕţé֣y misĕpá̇֔r wĕ⁠neʼesĕp֤ẇ ʻála⁠y֙ wĕ⁠hik̇֔ẇ⁠niy wĕ⁠nişĕ̌madĕţi֖̇y ʼàni֥y ẇ⁠béyţiֽ⁠y׃"],[34,31,"וַ⁠יֹּאמְר֑וּ הַ⁠כְ⁠זוֹנָ֕ה יַעֲשֶׂ֖ה אֶת־אֲחוֹתֵֽ⁠נוּ׃פ","wa⁠yò̇ʼmĕr֑ẇ ha⁠kĕ⁠zwòná֕h yaʻàşê֖h ʼeţ-ʼàẖwòţéֽ⁠nẇ׃p"],[35,1,"וַ⁠יֹּ֤אמֶר אֱלֹהִים֙ אֶֽל־יַעֲקֹ֔ב ק֛וּם עֲלֵ֥ה בֵֽית־אֵ֖ל וְ⁠שֶׁב־שָׁ֑ם וַ⁠עֲשֵׂה־שָׁ֣ם מִזְבֵּ֔חַ לָ⁠אֵל֙ הַ⁠נִּרְאֶ֣ה אֵלֶ֔י⁠ךָ בְּ⁠בָרְחֲ⁠ךָ֔ מִ⁠פְּנֵ֖י עֵשָׂ֥ו אָחִֽי⁠ךָ׃","wa⁠yò֤̇ʼmer ʼèlòhiym֙ ʼeֽl-yaʻàqò֔b q֛ẇm ʻàlé֥h béֽyţ-ʼé֖l wĕ⁠şěb-şá֑̌m wa⁠ʻàşé̂h-şá֣̌m mizĕbé̇֔ẖa lá⁠ʼél֙ ha⁠ni̇rĕʼe֣h ʼéle֔y⁠ká bĕ̇⁠bárĕẖà⁠ká֔ mi⁠pĕ̇né֖y ʻéşá֥̂w ʼáẖiֽy⁠ká׃"],[35,2,"וַ⁠יֹּ֤אמֶר יַעֲקֹב֙ אֶל־בֵּית֔⁠וֹ וְ⁠אֶ֖ל כָּל־אֲשֶׁ֣ר עִמּ֑⁠וֹ הָסִ֜רוּ אֶת־אֱלֹהֵ֤י הַ⁠נֵּכָר֙ אֲשֶׁ֣ר בְּ⁠תֹכְ⁠כֶ֔ם וְ⁠הִֽטַּהֲר֔וּ וְ⁠הַחֲלִ֖יפוּ שִׂמְלֹתֵי⁠כֶֽם׃","wa⁠yò֤̇ʼmer yaʻàqòb֙ ʼel-bé̇yţ֔⁠wò wĕ⁠ʼe֖l ká̇l-ʼàşě֣r ʻiṁ֑⁠wò hási֜rẇ ʼeţ-ʼèlòhé֤y ha⁠né̇kár֙ ʼàşě֣r bĕ̇⁠ţòkĕ⁠ke֔m wĕ⁠hiֽtȧhàr֔ẇ wĕ⁠haẖàli֖ypẇ şîmĕlòţéy⁠keֽm׃"],[35,3,"וְ⁠נָק֥וּמָה וְ⁠נַעֲלֶ֖ה בֵּֽית־אֵ֑ל וְ⁠אֶֽעֱשֶׂה־שָּׁ֣ם מִזְבֵּ֗חַ לָ⁠אֵ֞ל הָ⁠עֹנֶ֤ה אֹתִ⁠י֙ בְּ⁠י֣וֹם צָֽרָתִ֔⁠י וַ⁠יְהִי֙ עִמָּדִ֔⁠י בַּ⁠דֶּ֖רֶךְ אֲשֶׁ֥ר הָלָֽכְתִּי׃","wĕ⁠náq֥ẇmáh wĕ⁠naʻàle֖h béֽ̇yţ-ʼé֑l wĕ⁠ʼeֽʻèşêh-şá֣̇̌m mizĕbé̇֗ẖa lá⁠ʼé֞l há⁠ʻòne֤h ʼòţi⁠y֙ bĕ̇⁠y֣wòm ẕáֽráţi֔⁠y wa⁠yĕhiy֙ ʻimá̇di֔⁠y bȧ⁠dė֖rekĕ ʼàşě֥r háláֽkĕţi̇y׃"],[35,4,"וַ⁠יִּתְּנ֣וּ אֶֽל־יַעֲקֹ֗ב אֵ֣ת כָּל־אֱלֹהֵ֤י הַ⁠נֵּכָר֙ אֲשֶׁ֣ר בְּ⁠יָדָ֔⁠ם וְ⁠אֶת־הַ⁠נְּזָמִ֖ים אֲשֶׁ֣ר בְּ⁠אָזְנֵי⁠הֶ֑ם וַ⁠יִּטְמֹ֤ן אֹתָ⁠ם֙ יַעֲקֹ֔ב תַּ֥חַת הָ⁠אֵלָ֖ה אֲשֶׁ֥ר עִם־שְׁכֶֽם׃","wa⁠yi̇ţĕ̇n֣ẇ ʼeֽl-yaʻàqò֗b ʼé֣ţ ká̇l-ʼèlòhé֤y ha⁠né̇kár֙ ʼàşě֣r bĕ̇⁠yádá֔⁠m wĕ⁠ʼeţ-ha⁠nĕ̇zámi֖ym ʼàşě֣r bĕ̇⁠ʼázĕnéy⁠he֑m wa⁠yi̇tĕmò֤n ʼòţá⁠m֙ yaʻàqò֔b ţȧ֥ẖaţ há⁠ʼélá֖h ʼàşě֥r ʻim-şĕ̌keֽm׃"],[35,5,"וַ⁠יִּסָּ֑עוּ וַ⁠יְהִ֣י ׀ חִתַּ֣ת אֱלֹהִ֗ים עַל־הֶֽ⁠עָרִים֙ אֲשֶׁר֙ סְבִיבֹ֣תֵי⁠הֶ֔ם וְ⁠לֹ֣א רָֽדְפ֔וּ אַחֲרֵ֖י בְּנֵ֥י יַעֲקֹֽב׃","wa⁠yi̇sá֑̇ʻẇ wa⁠yĕhi֣y ׀ ẖiţȧ֣ţ ʼèlòhi֗ym ʻal-heֽ⁠ʻáriym֙ ʼàşěr֙ sĕbiybò֣ţéy⁠he֔m wĕ⁠lò֣ʼ ráֽdĕp֔ẇ ʼaẖàré֖y bĕ̇né֥y yaʻàqòֽb׃"],[35,6,"וַ⁠יָּבֹ֨א יַעֲקֹ֜ב ל֗וּזָ⁠ה אֲשֶׁר֙ בְּ⁠אֶ֣רֶץ כְּנַ֔עַן הִ֖וא בֵּֽית־אֵ֑ל ה֖וּא וְ⁠כָל־הָ⁠עָ֥ם אֲשֶׁר־עִמּֽ⁠וֹ׃","wa⁠yá̇bò֨ʼ yaʻàqò֜b l֗ẇzá⁠h ʼàşěr֙ bĕ̇⁠ʼe֣reẕ kĕ̇na֔ʻan hi֖wʼ béֽ̇yţ-ʼé֑l h֖ẇʼ wĕ⁠kál-há⁠ʻá֥m ʼàşěr-ʻiṁֽ⁠wò׃"],[35,7,"וַ⁠יִּ֤בֶן שָׁם֙ מִזְבֵּ֔חַ וַ⁠יִּקְרָא֙ לַ⁠מָּק֔וֹם אֵ֖ל בֵּֽית־אֵ֑ל כִּ֣י שָׁ֗ם נִגְל֤וּ אֵלָי⁠ו֙ הָֽ⁠אֱלֹהִ֔ים בְּ⁠בָרְח֖⁠וֹ מִ⁠פְּנֵ֥י אָחִֽי⁠ו׃","wa⁠yi֤̇ben şá̌m֙ mizĕbé̇֔ẖa wa⁠yi̇qĕráʼ֙ la⁠má̇q֔wòm ʼé֖l béֽ̇yţ-ʼé֑l ki֣̇y şá̌֗m nigĕl֤ẇ ʼéláy⁠w֙ háֽ⁠ʼèlòhi֔ym bĕ̇⁠bárĕẖ֖⁠wò mi⁠pĕ̇né֥y ʼáẖiֽy⁠w׃"],[35,8,"וַ⁠תָּ֤מָת דְּבֹרָה֙ מֵינֶ֣קֶת רִבְקָ֔ה וַ⁠תִּקָּבֵ֛ר מִ⁠תַּ֥חַת לְ⁠בֵֽית־אֵ֖ל תַּ֣חַת הָֽ⁠אַלּ֑וֹן וַ⁠יִּקְרָ֥א שְׁמ֖⁠וֹ אַלּ֥וֹן בָּכֽוּת׃פ","wa⁠ţá֤̇máţ dĕ̇bòráh֙ méyne֣qeţ ribĕqá֔h wa⁠ţi̇qá̇bé֛r mi⁠ţȧ֥ẖaţ lĕ⁠béֽyţ-ʼé֖l ţȧ֣ẖaţ háֽ⁠ʼal֑̇wòn wa⁠yi̇qĕrá֥ʼ şĕ̌m֖⁠wò ʼal֥̇wòn bá̇kֽẇţ׃p"],[35,9,"וַ⁠יֵּרָ֨א אֱלֹהִ֤ים אֶֽל־יַעֲקֹב֙ ע֔וֹד בְּ⁠בֹא֖⁠וֹ מִ⁠פַּדַּ֣ן אֲרָ֑ם וַ⁠יְבָ֖רֶךְ אֹתֽ⁠וֹ׃","wa⁠yé̇rá֨ʼ ʼèlòhi֤ym ʼeֽl-yaʻàqòb֙ ʻ֔wòd bĕ̇⁠bòʼ֖⁠wò mi⁠pȧdȧ֣n ʼàrá֑m wa⁠yĕbá֖rekĕ ʼòţֽ⁠wò׃"],[35,10,"וַ⁠יֹּֽאמֶר־ל֥⁠וֹ אֱלֹהִ֖ים שִׁמְ⁠ךָ֣ יַעֲקֹ֑ב לֹֽא־יִקָּרֵא֩ שִׁמְ⁠ךָ֨ ע֜וֹד יַעֲקֹ֗ב כִּ֤י אִם־יִשְׂרָאֵל֙ יִהְיֶ֣ה שְׁמֶ֔⁠ךָ וַ⁠יִּקְרָ֥א אֶת־שְׁמ֖⁠וֹ יִשְׂרָאֵֽל׃","wa⁠yòֽ̇ʼmer-l֥⁠wò ʼèlòhi֖ym şǐmĕ⁠ká֣ yaʻàqò֑b lòֽʼ-yiqá̇réʼ֩ şǐmĕ⁠ká֨ ʻ֜wòd yaʻàqò֗b ki֤̇y ʼim-yişĕ̂ráʼél֙ yihĕye֣h şĕ̌me֔⁠ká wa⁠yi̇qĕrá֥ʼ ʼeţ-şĕ̌m֖⁠wò yişĕ̂ráʼéֽl׃"],[35,11,"וַ⁠יֹּאמֶר֩ ל֨⁠וֹ אֱלֹהִ֜ים אֲנִ֨י אֵ֤ל שַׁדַּי֙ פְּרֵ֣ה וּ⁠רְבֵ֔ה גּ֛וֹי וּ⁠קְהַ֥ל גּוֹיִ֖ם יִהְיֶ֣ה מִמֶּ֑⁠ךָּ וּ⁠מְלָכִ֖ים מֵ⁠חֲלָצֶ֥י⁠ךָ יֵצֵֽאוּ׃","wa⁠yò̇ʼmer֩ l֨⁠wò ʼèlòhi֜ym ʼàni֨y ʼé֤l şǎdȧy֙ pĕ̇ré֣h ẇ⁠rĕbé֔h ġ֛wòy ẇ⁠qĕha֥l ġwòyi֖m yihĕye֣h mimė֑⁠ká̇ ẇ⁠mĕláki֖ym mé⁠ẖàláẕe֥y⁠ká yéẕéֽʼẇ׃"],[35,12,"וְ⁠אֶת־הָ⁠אָ֗רֶץ אֲשֶׁ֥ר נָתַ֛תִּי לְ⁠אַבְרָהָ֥ם וּ⁠לְ⁠יִצְחָ֖ק לְ⁠ךָ֣ אֶתְּנֶ֑⁠נָּה וּֽ⁠לְ⁠זַרְעֲ⁠ךָ֥ אַחֲרֶ֖י⁠ךָ אֶתֵּ֥ן אֶת־הָ⁠אָֽרֶץ׃","wĕ⁠ʼeţ-há⁠ʼá֗reẕ ʼàşě֥r náţa֛ţi̇y lĕ⁠ʼabĕráhá֥m ẇ⁠lĕ⁠yiẕĕẖá֖q lĕ⁠ká֣ ʼeţĕ̇ne֑⁠ná̇h ẇֽ⁠lĕ⁠zarĕʻà⁠ká֥ ʼaẖàre֖y⁠ká ʼeţé֥̇n ʼeţ-há⁠ʼáֽreẕ׃"],[35,13,"וַ⁠יַּ֥עַל מֵ⁠עָלָ֖י⁠ו אֱלֹהִ֑ים בַּ⁠מָּק֖וֹם אֲשֶׁר־דִּבֶּ֥ר אִתּֽ⁠וֹ׃","wa⁠yȧ֥ʻal mé⁠ʻálá֖y⁠w ʼèlòhi֑ym bȧ⁠má̇q֖wòm ʼàşěr-di̇bė֥r ʼiţֽ̇⁠wò׃"],[35,14,"וַ⁠יַּצֵּ֨ב יַעֲקֹ֜ב מַצֵּבָ֗ה בַּ⁠מָּק֛וֹם אֲשֶׁר־דִּבֶּ֥ר אִתּ֖⁠וֹ מַצֶּ֣בֶת אָ֑בֶן וַ⁠יַּסֵּ֤ךְ עָלֶ֨י⁠הָ֙ נֶ֔סֶךְ וַ⁠יִּצֹ֥ק עָלֶ֖י⁠הָ שָֽׁמֶן׃","wa⁠yȧẕé̇֨b yaʻàqò֜b maẕé̇bá֗h bȧ⁠má̇q֛wòm ʼàşěr-di̇bė֥r ʼiţ֖̇⁠wò maẕė֣beţ ʼá֑ben wa⁠yȧsé֤̇kĕ ʻále֨y⁠há֙ ne֔sekĕ wa⁠yi̇ẕò֥q ʻále֖y⁠há şáֽ̌men׃"],[35,15,"וַ⁠יִּקְרָ֨א יַעֲקֹ֜ב אֶת־שֵׁ֣ם הַ⁠מָּק֗וֹם אֲשֶׁר֩ דִּבֶּ֨ר אִתּ֥⁠וֹ שָׁ֛ם אֱלֹהִ֖ים בֵּֽית־אֵֽל׃","wa⁠yi̇qĕrá֨ʼ yaʻàqò֜b ʼeţ-şé֣̌m ha⁠má̇q֗wòm ʼàşěr֩ di̇bė֨r ʼiţ֥̇⁠wò şá֛̌m ʼèlòhi֖ym béֽ̇yţ-ʼéֽl׃"],[35,16,"וַ⁠יִּסְעוּ֙ מִ⁠בֵּ֣ית אֵ֔ל וַֽ⁠יְהִי־ע֥וֹד כִּבְרַת־הָ⁠אָ֖רֶץ לָ⁠ב֣וֹא אֶפְרָ֑תָה וַ⁠תֵּ֥לֶד רָחֵ֖ל וַ⁠תְּקַ֥שׁ בְּ⁠לִדְתָּֽ⁠הּ׃","wa⁠yi̇sĕʻẇ֙ mi⁠bé֣̇yţ ʼé֔l waֽ⁠yĕhiy-ʻ֥wòd ki̇bĕraţ-há⁠ʼá֖reẕ lá⁠b֣wòʼ ʼepĕrá֑ţáh wa⁠ţé֥̇led ráẖé֖l wa⁠ţĕ̇qa֥ş̌ bĕ̇⁠lidĕţáֽ̇⁠ḣ׃"],[35,17,"וַ⁠יְהִ֥י בְ⁠הַקְשֹׁתָ֖⁠הּ בְּ⁠לִדְתָּ֑⁠הּ וַ⁠תֹּ֨אמֶר לָ֤⁠הּ הַ⁠מְיַלֶּ֨דֶת֙ אַל־תִּ֣ירְאִ֔י כִּֽי־גַם־זֶ֥ה לָ֖⁠ךְ בֵּֽן׃","wa⁠yĕhi֥y bĕ⁠haqĕşò̌ţá֖⁠ḣ bĕ̇⁠lidĕţá֑̇⁠ḣ wa⁠ţò̇֨ʼmer lá֤⁠ḣ ha⁠mĕyalė֨deţ֙ ʼal-ţi֣̇yrĕʼi֔y kiֽ̇y-gam-ze֥h lá֖⁠kĕ béֽ̇n׃"],[35,18,"וַ⁠יְהִ֞י בְּ⁠צֵ֤את נַפְשָׁ⁠הּ֙ כִּ֣י מֵ֔תָה וַ⁠תִּקְרָ֥א שְׁמ֖⁠וֹ בֶּן־אוֹנִ֑י וְ⁠אָבִ֖י⁠ו קָֽרָא־ל֥⁠וֹ בִנְיָמִֽין׃","wa⁠yĕhi֞y bĕ̇⁠ẕé֤ʼţ napĕşá̌⁠ḣ֙ ki֣̇y mé֔ţáh wa⁠ţi̇qĕrá֥ʼ şĕ̌m֖⁠wò bėn-ʼwòni֑y wĕ⁠ʼábi֖y⁠w qáֽráʼ-l֥⁠wò binĕyámiֽyn׃"],[35,19,"וַ⁠תָּ֖מָת רָחֵ֑ל וַ⁠תִּקָּבֵר֙ בְּ⁠דֶ֣רֶךְ אֶפְרָ֔תָה הִ֖וא בֵּ֥ית לָֽחֶם׃","wa⁠ţá֖̇máţ ráẖé֑l wa⁠ţi̇qá̇bér֙ bĕ̇⁠de֣rekĕ ʼepĕrá֔ţáh hi֖wʼ bé֥̇yţ láֽẖem׃"],[35,20,"וַ⁠יַּצֵּ֧ב יַעֲקֹ֛ב מַצֵּבָ֖ה עַל־קְבֻרָתָ֑⁠הּ הִ֛וא מַצֶּ֥בֶת קְבֻֽרַת־רָחֵ֖ל עַד־הַ⁠יּֽוֹם׃","wa⁠yȧẕé֧̇b yaʻàqò֛b maẕé̇bá֖h ʻal-qĕburáţá֑⁠ḣ hi֛wʼ maẕė֥beţ qĕbuֽraţ-ráẖé֖l ʻad-ha⁠ẏֽwòm׃"],[35,21,"וַ⁠יִּסַּ֖ע יִשְׂרָאֵ֑ל וַ⁠יֵּ֣ט אָֽהֳלֹ֔⁠ה מֵ⁠הָ֖לְאָה לְ⁠מִגְדַּל־עֵֽדֶר׃","wa⁠yi̇sȧ֖ʻ yişĕ̂ráʼé֑l wa⁠yé֣̇t ʼáֽholò֔⁠h mé⁠há֖lĕʼáh lĕ⁠migĕdȧl-ʻéֽder׃"],[35,22,"וַ⁠יְהִ֗י בִּ⁠שְׁכֹּ֤ן יִשְׂרָאֵל֙ בָּ⁠אָ֣רֶץ הַ⁠הִ֔וא וַ⁠יֵּ֣לֶךְ רְאוּבֵ֔ן וַ⁠יִּשְׁכַּב֙ אֶת־בִּלְהָה֙ פִּילֶ֣גֶשׁ אָבִ֔י⁠ו וַ⁠יִּשְׁמַ֖ע יִשְׂרָאֵ֑ל פ וַ⁠יִּֽהְי֥וּ בְנֵֽי־יַעֲקֹ֖ב שְׁנֵ֥ים עָשָֽׂר׃","wa⁠yĕhi֗y bi̇⁠şĕ̌kò֤̇n yişĕ̂ráʼél֙ bá̇⁠ʼá֣reẕ ha⁠hi֔wʼ wa⁠yé֣̇lekĕ rĕʼẇbé֔n wa⁠yi̇şĕ̌kȧb֙ ʼeţ-bi̇lĕháh֙ pi̇yle֣geş̌ ʼábi֔y⁠w wa⁠yi̇şĕ̌ma֖ʻ yişĕ̂ráʼé֑l p wa⁠yiֽ̇hĕy֥ẇ bĕnéֽy-yaʻàqò֖b şĕ̌né֥ym ʻáşáֽ̂r׃"],[35,23,"בְּנֵ֣י לֵאָ֔ה בְּכ֥וֹר יַעֲקֹ֖ב רְאוּבֵ֑ן וְ⁠שִׁמְעוֹן֙ וְ⁠לֵוִ֣י וִֽ⁠יהוּדָ֔ה וְ⁠יִשָּׂשכָ֖ר וּ⁠זְבוּלֻֽן׃","bĕ̇né֣y léʼá֔h bĕ̇k֥wòr yaʻàqò֖b rĕʼẇbé֑n wĕ⁠şǐmĕʻwòn֙ wĕ⁠léwi֣y wiֽ⁠yhẇdá֔h wĕ⁠yişá̇̂şká֖r ẇ⁠zĕbẇluֽn׃"],[35,24,"בְּנֵ֣י רָחֵ֔ל יוֹסֵ֖ף וּ⁠בִנְיָמִֽן׃","bĕ̇né֣y ráẖé֔l ywòsé֖p ẇ⁠binĕyámiֽn׃"],[35,25,"וּ⁠בְנֵ֤י בִלְהָה֙ שִׁפְחַ֣ת רָחֵ֔ל דָּ֖ן וְ⁠נַפְתָּלִֽי׃","ẇ⁠bĕné֤y bilĕháh֙ şǐpĕẖa֣ţ ráẖé֔l dá֖̇n wĕ⁠napĕţá̇liֽy׃"],[35,26,"וּ⁠בְנֵ֥י זִלְפָּ֛ה שִׁפְחַ֥ת לֵאָ֖ה גָּ֣ד וְ⁠אָשֵׁ֑ר אֵ֚לֶּה בְּנֵ֣י יַעֲקֹ֔ב אֲשֶׁ֥ר יֻלַּד־ל֖⁠וֹ בְּ⁠פַדַּ֥ן אֲרָֽם׃","ẇ⁠bĕné֥y zilĕpá֛̇h şǐpĕẖa֥ţ léʼá֖h gá֣̇d wĕ⁠ʼáşé֑̌r ʼé֚lėh bĕ̇né֣y yaʻàqò֔b ʼàşě֥r yulȧd-l֖⁠wò bĕ̇⁠padȧ֥n ʼàráֽm׃"],[35,27,"וַ⁠יָּבֹ֤א יַעֲקֹב֙ אֶל־יִצְחָ֣ק אָבִ֔י⁠ו מַמְרֵ֖א קִרְיַ֣ת הָֽאַרְבַּ֑ע הִ֣וא חֶבְר֔וֹן אֲשֶׁר־גָּֽר־שָׁ֥ם אַבְרָהָ֖ם וְ⁠יִצְחָֽק׃","wa⁠yá̇bò֤ʼ yaʻàqòb֙ ʼel-yiẕĕẖá֣q ʼábi֔y⁠w mamĕré֖ʼ qirĕya֣ţ háֽʼarĕbȧ֑ʻ hi֣wʼ ẖebĕr֔wòn ʼàşěr-gáֽ̇r-şá֥̌m ʼabĕráhá֖m wĕ⁠yiẕĕẖáֽq׃"],[35,28,"וַ⁠יִּֽהְי֖וּ יְמֵ֣י יִצְחָ֑ק מְאַ֥ת שָׁנָ֖ה וּ⁠שְׁמֹנִ֥ים שָׁנָֽה׃","wa⁠yiֽ̇hĕy֖ẇ yĕmé֣y yiẕĕẖá֑q mĕʼa֥ţ şá̌ná֖h ẇ⁠şĕ̌mòni֥ym şá̌náֽh׃"],[35,29,"וַ⁠יִּגְוַ֨ע יִצְחָ֤ק וַ⁠יָּ֨מָת֙ וַ⁠יֵּאָ֣סֶף אֶל־עַמָּ֔י⁠ו זָקֵ֖ן וּ⁠שְׂבַ֣ע יָמִ֑ים וַ⁠יִּקְבְּר֣וּ אֹת֔⁠וֹ עֵשָׂ֥ו וְ⁠יַעֲקֹ֖ב בָּנָֽי⁠ו׃פ","wa⁠yi̇gĕwa֨ʻ yiẕĕẖá֤q wa⁠yá̇֨máţ֙ wa⁠yé̇ʼá֣sep ʼel-ʻamá̇֔y⁠w záqé֖n ẇ⁠şĕ̂ba֣ʻ yámi֑ym wa⁠yi̇qĕbĕ̇r֣ẇ ʼòţ֔⁠wò ʻéşá֥̂w wĕ⁠yaʻàqò֖b bá̇náֽy⁠w׃p"],[36,1,"וְ⁠אֵ֛לֶּה תֹּלְד֥וֹת עֵשָׂ֖ו ה֥וּא אֱדֽוֹם׃","wĕ⁠ʼé֛lėh ţò̇lĕd֥wòţ ʻéşá֖̂w h֥ẇʼ ʼèdֽwòm׃"],[36,2,"עֵשָׂ֛ו לָקַ֥ח אֶת־נָשָׁ֖י⁠ו מִ⁠בְּנ֣וֹת כְּנָ֑עַן אֶת־עָדָ֗ה בַּת־אֵילוֹן֙ הַֽ⁠חִתִּ֔י וְ⁠אֶת־אָהֳלִֽיבָמָה֙ בַּת־עֲנָ֔ה בַּת־צִבְע֖וֹן הַֽ⁠חִוִּֽי׃","ʻéşá֛̂w láqa֥ẖ ʼeţ-náşá֖̌y⁠w mi⁠bĕ̇n֣wòţ kĕ̇ná֑ʻan ʼeţ-ʻádá֗h bȧţ-ʼéylwòn֙ haֽ⁠ẖiţi̇֔y wĕ⁠ʼeţ-ʼáholiֽybámáh֙ bȧţ-ʻàná֔h bȧţ-ẕibĕʻ֖wòn hֽa⁠ẖiwiֽ̇y׃"],[36,3,"וְ⁠אֶת־בָּשְׂמַ֥ת בַּת־יִשְׁמָעֵ֖אל אֲח֥וֹת נְבָיֽוֹת׃","wĕ⁠ʼeţ-bá̇şĕ̂ma֥ţ bȧţ-yişĕ̌máʻé֖ʼl ʼàẖ֥wòţ nĕbáyֽwòţ׃"],[36,4,"וַ⁠תֵּ֧לֶד עָדָ֛ה לְ⁠עֵשָׂ֖ו אֶת־אֱלִיפָ֑ז וּ⁠בָ֣שְׂמַ֔ת יָלְדָ֖ה אֶת־רְעוּאֵֽל׃","wa⁠ţé֧̇led ʻádá֛h lĕ⁠ʻéşá֖̂w ʼeţ-ʼèliypá֑z ẇ⁠bá֣şĕ̂ma֔ţ yálĕdá֖h ʼeţ-rĕʻẇʼéֽl׃"],[36,5,"וְ⁠אָהֳלִֽיבָמָה֙ יָֽלְדָ֔ה אֶת־יעיש וְ⁠אֶת־יַעְלָ֖ם וְ⁠אֶת־קֹ֑רַח אֵ֚לֶּה בְּנֵ֣י עֵשָׂ֔ו אֲשֶׁ֥ר יֻלְּדוּ־ל֖⁠וֹ בְּ⁠אֶ֥רֶץ כְּנָֽעַן׃","wĕ⁠ʼáholiֽybámáh֙ yáֽlĕdá֔h ʼeţ-yʻyş wĕ⁠ʼeţ-yaʻĕlá֖m wĕ⁠ʼeţ-qò֑raẖ ʼé֚lėh bĕ̇né֣y ʻéşá̂֔w ʼàşě֥r yulĕ̇dẇ-l֖⁠wò bĕ̇⁠ʼe֥reẕ kĕ̇náֽʻan׃"],[36,6,"וַ⁠יִּקַּ֣ח עֵשָׂ֡ו אֶת־נָ֠שָׁי⁠ו וְ⁠אֶת־בָּנָ֣י⁠ו וְ⁠אֶת־בְּנֹתָי⁠ו֮ וְ⁠אֶת־כָּל־נַפְשׁ֣וֹת בֵּית⁠וֹ֒ וְ⁠אֶת־מִקְנֵ֣⁠הוּ וְ⁠אֶת־כָּל־בְּהֶמְתּ֗⁠וֹ וְ⁠אֵת֙ כָּל־קִנְיָנ֔⁠וֹ אֲשֶׁ֥ר רָכַ֖שׁ בְּ⁠אֶ֣רֶץ כְּנָ֑עַן וַ⁠יֵּ֣לֶךְ אֶל־אֶ֔רֶץ מִ⁠פְּנֵ֖י יַעֲקֹ֥ב אָחִֽי⁠ו׃","wa⁠yi̇qȧ֣ẖ ʻéşá̂֡w ʼeţ-ná֠şá̌y⁠w wĕ⁠ʼeţ-bá̇ná֣y⁠w wĕ⁠ʼeţ-bĕ̇nòţáy⁠w֮ wĕ⁠ʼeţ-ká̇l-napĕş֣̌wòţ bé̇yţ⁠wò֒ wĕ⁠ʼeţ-miqĕné֣⁠hẇ wĕ⁠ʼeţ-ká̇l-bĕ̇hemĕţ̇֗⁠wò wĕ⁠ʼéţ֙ ká̇l-qinĕyán֔⁠wò ʼàşě֥r ráka֖ş̌ bĕ̇⁠ʼe֣reẕ kĕ̇ná֑ʻan wa⁠yé֣̇lekĕ ʼel-ʼe֔reẕ mi⁠pĕ̇né֖y yaʻàqò֥b ʼáẖiֽy⁠w׃"],[36,7,"כִּֽי־הָיָ֧ה רְכוּשָׁ֛⁠ם רָ֖ב מִ⁠שֶּׁ֣בֶת יַחְדָּ֑ו וְ⁠לֹ֨א יָֽכְלָ֜ה אֶ֤רֶץ מְגֽוּרֵי⁠הֶם֙ לָ⁠שֵׂ֣את אֹתָ֔⁠ם מִ⁠פְּנֵ֖י מִקְנֵי⁠הֶֽם׃","kiֽ̇y-háyá֧h rĕkẇşá֛̌⁠m rá֖b mi⁠şė֣̌beţ yaẖĕdá֑̇w wĕ⁠lò֨ʼ yֽákĕlá֜h ʼe֤reẕ mĕgֽẇréy⁠hem֙ lá⁠şé֣̂ʼţ ʼòţá֔⁠m mi⁠pĕ̇né֖y miqĕnéy⁠heֽm׃"],[36,8,"וַ⁠יֵּ֤שֶׁב עֵשָׂו֙ בְּ⁠הַ֣ר שֵׂעִ֔יר עֵשָׂ֖ו ה֥וּא אֱדֽוֹם׃","wa⁠yé֤̇şěb ʻéşá̂w֙ bĕ̇⁠ha֣r şé̂ʻi֔yr ʻéşá֖̂w h֥ẇʼ ʼèdֽwòm׃"],[36,9,"וְ⁠אֵ֛לֶּה תֹּלְד֥וֹת עֵשָׂ֖ו אֲבִ֣י אֱד֑וֹם בְּ⁠הַ֖ר שֵׂעִֽיר׃","wĕ⁠ʼé֛lėh ţò̇lĕd֥wòţ ʻéşá֖̂w ʼàbi֣y ʼèd֑wòm bĕ̇⁠ha֖r şé̂ʻiֽyr׃"],[36,10,"אֵ֖לֶּה שְׁמ֣וֹת בְּנֵֽי־עֵשָׂ֑ו אֱלִיפַ֗ז בֶּן־עָדָה֙ אֵ֣שֶׁת עֵשָׂ֔ו רְעוּאֵ֕ל בֶּן־בָּשְׂמַ֖ת אֵ֥שֶׁת עֵשָֽׂו׃","ʼé֖lėh şĕ̌m֣wòţ bĕ̇néֽy-ʻéşá֑̂w ʼèliypa֗z bėn-ʻádáh֙ ʼé֣şěţ ʻéşá̂֔w rĕʻẇʼé֕l bėn-bá̇şĕ̂ma֖ţ ʼé֥şěţ ʻéşáֽ̂w׃"],[36,11,"וַ⁠יִּהְי֖וּ בְּנֵ֣י אֱלִיפָ֑ז תֵּימָ֣ן אוֹמָ֔ר צְפ֥וֹ וְ⁠גַעְתָּ֖ם וּ⁠קְנַֽז׃","wa⁠yi̇hĕy֖ẇ bĕ̇né֣y ʼèliypá֑z ţé̇ymá֣n ʼwòmá֔r ẕĕp֥wò wĕ⁠gaʻĕţá֖̇m ẇ⁠qĕnaֽz׃"],[36,12,"וְ⁠תִמְנַ֣ע ׀ הָיְתָ֣ה פִילֶ֗גֶשׁ לֶֽ⁠אֱלִיפַז֙ בֶּן־עֵשָׂ֔ו וַ⁠תֵּ֥לֶד לֶ⁠אֱלִיפַ֖ז אֶת־עֲמָלֵ֑ק אֵ֕לֶּה בְּנֵ֥י עָדָ֖ה אֵ֥שֶׁת עֵשָֽׂו׃","wĕ⁠ţimĕna֣ʻ ׀ háyĕţá֣h piyle֗geş̌ leֽ⁠ʼèliypaz֙ bėn-ʻéşá̂֔w wa⁠ţé֥̇led le⁠ʼèliypa֖z ʼeţ-ʻàmálé֑q ʼé֕lėh bĕ̇né֥y ʻádá֖h ʼé֥şěţ ʻéşáֽ̂w׃"],[36,13,"וְ⁠אֵ֨לֶּה֙ בְּנֵ֣י רְעוּאֵ֔ל נַ֥חַת וָ⁠זֶ֖רַח שַׁמָּ֣ה וּ⁠מִזָּ֑ה אֵ֣לֶּ֣ה הָי֔וּ בְּנֵ֥י בָשְׂמַ֖ת אֵ֥שֶׁת עֵשָֽׂו׃","wĕ⁠ʼé֨lėh֙ bĕ̇né֣y rĕʻẇʼé֔l na֥ẖaţ wá⁠ze֖raẖ şǎmá֣̇h ẇ⁠mizá֑̇h ʼé֣lė֣h háy֔ẇ bĕ̇né֥y báşĕ̂ma֖ţ ʼé֥şěţ ʻéşáֽ̂w׃"],[36,14,"וְ⁠אֵ֣לֶּה הָי֗וּ בְּנֵ֨י אָהֳלִיבָמָ֧ה בַת־עֲנָ֛ה בַּת־צִבְע֖וֹן אֵ֣שֶׁת עֵשָׂ֑ו וַ⁠תֵּ֣לֶד לְ⁠עֵשָׂ֔ו אֶת־יעיש וְ⁠אֶת־יַעְלָ֖ם וְ⁠אֶת־קֹֽרַח׃","wĕ⁠ʼé֣lėh háy֗ẇ bĕ̇né֨y ʼáholiybámá֧h baţ-ʻàná֛h bȧţ-ẕibĕʻ֖wòn ʼé֣şěţ ʻéşá֑̂w wa⁠ţé֣̇led lĕ⁠ʻéşá̂֔w ʼeţ-yʻyş wĕ⁠ʼeţ-yaʻĕlá֖m wĕ⁠ʼeţ-qòֽraẖ׃"],[36,15,"אֵ֖לֶּה אַלּוּפֵ֣י בְנֵֽי־עֵשָׂ֑ו בְּנֵ֤י אֱלִיפַז֙ בְּכ֣וֹר עֵשָׂ֔ו אַלּ֤וּף תֵּימָן֙ אַלּ֣וּף אוֹמָ֔ר אַלּ֥וּף צְפ֖וֹ אַלּ֥וּף קְנַֽז׃","ʼé֖lėh ʼal̇ẇpé֣y bĕnéֽy-ʻéşá֑̂w bĕ̇né֤y ʼèliypaz֙ bĕ̇k֣wòr ʻéşá̂֔w ʼal֤̇ẇp ţé̇ymán֙ ʼal֣̇ẇp ʼwòmá֔r ʼal֥̇ẇp ẕĕp֖wò ʼal֥̇ẇp qĕnaֽz׃"],[36,16,"אַלּֽוּף־קֹ֛רַח אַלּ֥וּף גַּעְתָּ֖ם אַלּ֣וּף עֲמָלֵ֑ק אֵ֣לֶּה אַלּוּפֵ֤י אֱלִיפַז֙ בְּ⁠אֶ֣רֶץ אֱד֔וֹם אֵ֖לֶּה בְּנֵ֥י עָדָֽה׃","ʼalֽ̇ẇp-qò֛raẖ ʼal֥̇ẇp gȧʻĕţá֖̇m ʼal֣̇ẇp ʻàmálé֑q ʼé֣lėh ʼal̇ẇpé֤y ʼèliypaz֙ bĕ̇⁠ʼe֣reẕ ʼèd֔wòm ʼé֖lėh bĕ̇né֥y ʻádáֽh׃"],[36,17,"וְ⁠אֵ֗לֶּה בְּנֵ֤י רְעוּאֵל֙ בֶּן־עֵשָׂ֔ו אַלּ֥וּף נַ֨חַת֙ אַלּ֣וּף זֶ֔רַח אַלּ֥וּף שַׁמָּ֖ה אַלּ֣וּף מִזָּ֑ה אֵ֣לֶּה אַלּוּפֵ֤י רְעוּאֵל֙ בְּ⁠אֶ֣רֶץ אֱד֔וֹם אֵ֕לֶּה בְּנֵ֥י בָשְׂמַ֖ת אֵ֥שֶׁת עֵשָֽׂו׃","wĕ⁠ʼé֗lėh bĕ̇né֤y rĕʻẇʼél֙ bėn-ʻéşá̂֔w ʼal֥̇ẇp na֨ẖaţ֙ ʼal֣̇ẇp ze֔raẖ ʼal֥̇ẇp şǎmá֖̇h ʼal֣̇ẇp mizá֑̇h ʼé֣lėh ʼal̇ẇpé֤y rĕʻẇʼél֙ bĕ̇⁠ʼe֣reẕ ʼèd֔wòm ʼé֕lėh bĕ̇né֥y báşĕ̂ma֖ţ ʼé֥şěţ ʻéşáֽ̂w׃"],[36,18,"וְ⁠אֵ֗לֶּה בְּנֵ֤י אָהֳלִֽיבָמָה֙ אֵ֣שֶׁת עֵשָׂ֔ו אַלּ֥וּף יְע֛וּשׁ אַלּ֥וּף יַעְלָ֖ם אַלּ֣וּף קֹ֑רַח אֵ֣לֶּה אַלּוּפֵ֞י אָֽהֳלִיבָמָ֛ה בַּת־עֲנָ֖ה אֵ֥שֶׁת עֵשָֽׂו׃","wĕ⁠ʼé֗lėh bĕ̇né֤y ʼáholiֽybámáh֙ ʼé֣şěţ ʻéşá̂֔w ʼal֥̇ẇp yĕʻ֛ẇş̌ ʼal֥̇ẇp yaʻĕlá֖m ʼal֣̇ẇp qò֑raẖ ʼé֣lėh ʼal̇ẇpé֞y ʼáֽholiybámá֛h bȧţ-ʻàná֖h ʼé֥şěţ ʻéşáֽ̂w׃"],[36,19,"אֵ֧לֶּה בְנֵי־עֵשָׂ֛ו וְ⁠אֵ֥לֶּה אַלּוּפֵי⁠הֶ֖ם ה֥וּא אֱדֽוֹם׃ס","ʼé֧lėh bĕnéy-ʻéşá֛̂w wĕ⁠ʼé֥lėh ʼal̇ẇpéy⁠he֖m h֥ẇʼ ʼèdֽwòm׃s"],[36,20,"אֵ֤לֶּה בְנֵֽי־שֵׂעִיר֙ הַ⁠חֹרִ֔י יֹשְׁבֵ֖י הָ⁠אָ֑רֶץ לוֹטָ֥ן וְ⁠שׁוֹבָ֖ל וְ⁠צִבְע֥וֹן וַ⁠עֲנָֽה׃","ʼé֤lėh bĕnéֽy-şé̂ʻiyr֙ ha⁠ẖòri֔y yòşĕ̌bé֖y há⁠ʼá֑reẕ lwòtá֥n wĕ⁠ş̌wòbá֖l wĕ⁠ẕibĕʻ֥wòn wa⁠ʻànáֽh׃"],[36,21,"וְ⁠דִשׁ֥וֹן וְ⁠אֵ֖צֶר וְ⁠דִישָׁ֑ן אֵ֣לֶּה אַלּוּפֵ֧י הַ⁠חֹרִ֛י בְּנֵ֥י שֵׂעִ֖יר בְּ⁠אֶ֥רֶץ אֱדֽוֹם׃","wĕ⁠diş֥̌wòn wĕ⁠ʼé֖ẕer wĕ⁠diyşá֑̌n ʼé֣lėh ʼal̇ẇpé֧y ha⁠ẖòri֛y bĕ̇né֥y şé̂ʻi֖yr bĕ̇⁠ʼe֥reẕ ʼèdֽwòm׃"],[36,22,"וַ⁠יִּהְי֥וּ בְנֵי־לוֹטָ֖ן חֹרִ֣י וְ⁠הֵימָ֑ם וַ⁠אֲח֥וֹת לוֹטָ֖ן תִּמְנָֽע׃","wa⁠yi̇hĕy֥ẇ bĕnéy-lwòtá֖n ẖòri֣y wĕ⁠héymá֑m wa⁠ʼàẖ֥wòţ lwòtá֖n ţi̇mĕnáֽʻ׃"],[36,23,"וְ⁠אֵ֨לֶּה֙ בְּנֵ֣י שׁוֹבָ֔ל עַלְוָ֥ן וּ⁠מָנַ֖חַת וְ⁠עֵיבָ֑ל שְׁפ֖וֹ וְ⁠אוֹנָֽם׃","wĕ⁠ʼé֨lėh֙ bĕ̇né֣y ş̌wòbá֔l ʻalĕwá֥n ẇ⁠mána֖ẖaţ wĕ⁠ʻéybá֑l şĕ̌p֖wò wĕ⁠ʼwònáֽm׃"],[36,24,"וְ⁠אֵ֥לֶּה בְנֵֽי־צִבְע֖וֹן וְ⁠אַיָּ֣ה וַ⁠עֲנָ֑ה ה֣וּא עֲנָ֗ה אֲשֶׁ֨ר מָצָ֤א אֶת־הַ⁠יֵּמִם֙ בַּ⁠מִּדְבָּ֔ר בִּ⁠רְעֹת֥⁠וֹ אֶת־הַ⁠חֲמֹרִ֖ים לְ⁠צִבְע֥וֹן אָבִֽי⁠ו׃","wĕ⁠ʼé֥lėh bĕnéֽy-ẕibĕʻ֖wòn wĕ⁠ʼayá֣̇h wa⁠ʻàná֑h h֣ẇʼ ʻàná֗h ʼàşě֨r máẕá֤ʼ ʼeţ-ha⁠yé̇mim֙ bȧ⁠mi̇dĕbá̇֔r bi̇⁠rĕʻòţ֥⁠wò ʼeţ-ha⁠ẖàmòri֖ym lĕ⁠ẕibĕʻ֥wòn ʼábiֽy⁠w׃"],[36,25,"וְ⁠אֵ֥לֶּה בְנֵֽי־עֲנָ֖ה דִּשֹׁ֑ן וְ⁠אָהֳלִיבָמָ֖ה בַּת־עֲנָֽה׃","wĕ⁠ʼé֥lėh bĕnéֽy-ʻàná֖h di̇şò֑̌n wĕ⁠ʼáholiybámá֖h bȧţ-ʻànáֽh׃"],[36,26,"וְ⁠אֵ֖לֶּה בְּנֵ֣י דִישָׁ֑ן חֶמְדָּ֥ן וְ⁠אֶשְׁבָּ֖ן וְ⁠יִתְרָ֥ן וּ⁠כְרָֽן׃","wĕ⁠ʼé֖lėh bĕ̇né֣y diyşá֑̌n ẖemĕdá֥̇n wĕ⁠ʼeşĕ̌bá֖̇n wĕ⁠yiţĕrá֥n ẇ⁠kĕráֽn׃"],[36,27,"אֵ֖לֶּה בְּנֵי־אֵ֑צֶר בִּלְהָ֥ן וְ⁠זַעֲוָ֖ן וַ⁠עֲקָֽן׃","ʼé֖lėh bĕ̇néy-ʼé֑ẕer bi̇lĕhá֥n wĕ⁠zaʻàwá֖n wa⁠ʻàqáֽn׃"],[36,28,"אֵ֥לֶּה בְנֵֽי־דִישָׁ֖ן ע֥וּץ וַ⁠אֲרָֽן׃","ʼé֥lėh bĕnéֽy-diyşá֖̌n ʻ֥ẇẕ wa⁠ʼàráֽn׃"],[36,29,"אֵ֖לֶּה אַלּוּפֵ֣י הַ⁠חֹרִ֑י אַלּ֤וּף לוֹטָן֙ אַלּ֣וּף שׁוֹבָ֔ל אַלּ֥וּף צִבְע֖וֹן אַלּ֥וּף עֲנָֽה׃","ʼé֖lėh ʼal̇ẇpé֣y ha⁠ẖòri֑y ʼal֤̇ẇp lwòtán֙ ʼal֣̇ẇp ş̌wòbá֔l ʼal֥̇ẇp ẕibĕʻ֖wòn ʼal֥̇ẇp ʻànáֽh׃"],[36,30,"אַלּ֥וּף דִּשֹׁ֛ן אַלּ֥וּף אֵ֖צֶר אַלּ֣וּף דִּישָׁ֑ן אֵ֣לֶּה אַלּוּפֵ֧י הַ⁠חֹרִ֛י לְ⁠אַלֻּפֵי⁠הֶ֖ם בְּ⁠אֶ֥רֶץ שֵׂעִֽיר׃פ","ʼal֥̇ẇp di̇şò֛̌n ʼal֥̇ẇp ʼé֖ẕer ʼal֣̇ẇp di̇yşá֑̌n ʼé֣lėh ʼal̇ẇpé֧y ha⁠ẖòri֛y lĕ⁠ʼalu̇péy⁠he֖m bĕ̇⁠ʼe֥reẕ şé̂ʻiֽyr׃p"],[36,31,"וְ⁠אֵ֨לֶּה֙ הַ⁠מְּלָכִ֔ים אֲשֶׁ֥ר מָלְכ֖וּ בְּ⁠אֶ֣רֶץ אֱד֑וֹם לִ⁠פְנֵ֥י מְלָךְ־מֶ֖לֶךְ לִ⁠בְנֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠ʼé֨lėh֙ ha⁠mĕ̇láki֔ym ʼàşě֥r málĕk֖ẇ bĕ̇⁠ʼe֣reẕ ʼèd֑wòm li⁠pĕné֥y mĕlákĕ-me֖lekĕ li⁠bĕné֥y yişĕ̂ráʼéֽl׃"],[36,32,"וַ⁠יִּמְלֹ֣ךְ בֶּ⁠אֱד֔וֹם בֶּ֖לַע בֶּן־בְּע֑וֹר וְ⁠שֵׁ֥ם עִיר֖⁠וֹ דִּנְהָֽבָה׃","wa⁠yi̇mĕlò֣kĕ bė⁠ʼèd֔wòm bė֖laʻ bėn-bĕ̇ʻ֑wòr wĕ⁠şé֥̌m ʻiyr֖⁠wò di̇nĕháֽbáh׃"],[36,33,"וַ⁠יָּ֖מָת בָּ֑לַע וַ⁠יִּמְלֹ֣ךְ תַּחְתָּ֔י⁠ו יוֹבָ֥ב בֶּן־זֶ֖רַח מִ⁠בָּצְרָֽה׃","wa⁠yá֖̇máţ bá֑̇laʻ wa⁠yi̇mĕlò֣kĕ ţȧẖĕţá̇֔y⁠w ywòbá֥b bėn-ze֖raẖ mi⁠bá̇ẕĕráֽh׃"],[36,34,"וַ⁠יָּ֖מָת יוֹבָ֑ב וַ⁠יִּמְלֹ֣ךְ תַּחְתָּ֔י⁠ו חֻשָׁ֖ם מֵ⁠אֶ֥רֶץ הַ⁠תֵּימָנִֽי׃","wa⁠yá֖̇máţ ywòbá֑b wa⁠yi̇mĕlò֣kĕ ţȧẖĕţá̇֔y⁠w ẖuşá֖̌m mé⁠ʼe֥reẕ ha⁠ţé̇ymániֽy׃"],[36,35,"וַ⁠יָּ֖מָת חֻשָׁ֑ם וַ⁠יִּמְלֹ֨ךְ תַּחְתָּ֜י⁠ו הֲדַ֣ד בֶּן־בְּדַ֗ד הַ⁠מַּכֶּ֤ה אֶת־מִדְיָן֙ בִּ⁠שְׂדֵ֣ה מוֹאָ֔ב וְ⁠שֵׁ֥ם עִיר֖⁠וֹ עֲוִֽית׃","wa⁠yá֖̇máţ ẖuşá֑̌m wa⁠yi̇mĕlò֨kĕ ţȧẖĕţá̇֜y⁠w hàda֣d bėn-bĕ̇da֗d ha⁠mȧkė֤h ʼeţ-midĕyán֙ bi̇⁠şĕ̂dé֣h mwòʼá֔b wĕ⁠şé֥̌m ʻiyr֖⁠wò ʻàwiֽyţ׃"],[36,36,"וַ⁠יָּ֖מָת הֲדָ֑ד וַ⁠יִּמְלֹ֣ךְ תַּחְתָּ֔י⁠ו שַׂמְלָ֖ה מִ⁠מַּשְׂרֵקָֽה׃","wa⁠yá֖̇máţ hàdá֑d wa⁠yi̇mĕlò֣kĕ ţȧẖĕţá̇֔y⁠w şâmĕlá֖h mi⁠mȧşĕ̂réqáֽh׃"],[36,37,"וַ⁠יָּ֖מָת שַׂמְלָ֑ה וַ⁠יִּמְלֹ֣ךְ תַּחְתָּ֔י⁠ו שָׁא֖וּל מֵ⁠רְחֹב֥וֹת הַ⁠נָּהָֽר׃","wa⁠yá֖̇máţ şâmĕlá֑h wa⁠yi̇mĕlò֣kĕ ţȧẖĕţá̇֔y⁠w şá̌ʼ֖ẇl mé⁠rĕẖòb֥wòţ ha⁠ná̇háֽr׃"],[36,38,"וַ⁠יָּ֖מָת שָׁא֑וּל וַ⁠יִּמְלֹ֣ךְ תַּחְתָּ֔י⁠ו בַּ֥עַל חָנָ֖ן בֶּן־עַכְבּֽוֹר׃","wa⁠yá֖̇máţ şá̌ʼ֑ẇl wa⁠yi̇mĕlò֣kĕ ţȧẖĕţá̇֔y⁠w bȧ֥ʻal ẖáná֖n bėn-ʻakĕḃֽwòr׃"],[36,39,"וַ⁠יָּמָת֮ בַּ֣עַל חָנָ֣ן בֶּן־עַכְבּוֹר֒ וַ⁠יִּמְלֹ֤ךְ תַּחְתָּי⁠ו֙ הֲדַ֔ר וְ⁠שֵׁ֥ם עִיר֖⁠וֹ פָּ֑עוּ וְ⁠שֵׁ֨ם אִשְׁתּ֤⁠וֹ מְהֵֽיטַבְאֵל֙ בַּת־מַטְרֵ֔ד בַּ֖ת מֵ֥י זָהָֽב׃","wa⁠yá̇máţ֮ bȧ֣ʻal ẖáná֣n bėn-ʻakĕḃwòr֒ wa⁠yi̇mĕlò֤kĕ ţȧẖĕţá̇y⁠w֙ hàda֔r wĕ⁠şé֥̌m ʻiyr֖⁠wò pá֑̇ʻẇ wĕ⁠şé̌֨m ʼişĕ̌ţ֤̇⁠wò mĕhéֽytabĕʼél֙ bȧţ-matĕré֔d bȧ֖ţ mé֥y záháֽb׃"],[36,40,"וְ֠⁠אֵלֶּה שְׁמ֞וֹת אַלּוּפֵ֤י עֵשָׂו֙ לְ⁠מִשְׁפְּחֹתָ֔⁠ם לִ⁠מְקֹמֹתָ֖⁠ם בִּ⁠שְׁמֹתָ֑⁠ם אַלּ֥וּף תִּמְנָ֛ע אַלּ֥וּף עַֽלְוָ֖ה אַלּ֥וּף יְתֵֽת׃","wĕ֠⁠ʼélėh şĕ̌m֞wòţ ʼal̇ẇpé֤y ʻéşá̂w֙ lĕ⁠mişĕ̌pĕ̇ẖòţá֔⁠m li⁠mĕqòmòţá֖⁠m bi̇⁠şĕ̌mòţá֑⁠m ʼal֥̇ẇp ţi̇mĕná֛ʻ ʼal֥̇ẇp ʻaֽlĕwá֖h ʼal֥̇ẇp yĕţéֽţ׃"],[36,41,"אַלּ֧וּף אָהֳלִיבָמָ֛ה אַלּ֥וּף אֵלָ֖ה אַלּ֥וּף פִּינֹֽן׃","ʼal֧̇ẇp ʼáholiybámá֛h ʼal֥̇ẇp ʼélá֖h ʼal֥̇ẇp pi̇ynòֽn׃"],[36,42,"אַלּ֥וּף קְנַ֛ז אַלּ֥וּף תֵּימָ֖ן אַלּ֥וּף מִבְצָֽר׃","ʼal֥̇ẇp qĕna֛z ʼal֥̇ẇp ţé̇ymá֖n ʼal֥̇ẇp mibĕẕáֽr׃"],[36,43,"אַלּ֥וּף מַגְדִּיאֵ֖ל אַלּ֣וּף עִירָ֑ם אֵ֣לֶּה ׀ אַלּוּפֵ֣י אֱד֗וֹם לְ⁠מֹֽשְׁבֹתָ⁠ם֙ בְּ⁠אֶ֣רֶץ אֲחֻזָּתָ֔⁠ם ה֥וּא עֵשָׂ֖ו אֲבִ֥י אֱדֽוֹם׃פ","ʼal֥̇ẇp magĕdi̇yʼé֖l ʼal֣̇ẇp ʻiyrá֑m ʼé֣lėh ׀ ʼal̇ẇpé֣y ʼèd֗wòm lĕ⁠mòֽşĕ̌bòţá⁠m֙ bĕ̇⁠ʼe֣reẕ ʼàẖuzá̇ţá֔⁠m h֥ẇʼ ʻéşá֖̂w ʼàbi֥y ʼèdֽwòm׃p"],[37,1,"וַ⁠יֵּ֣שֶׁב יַעֲקֹ֔ב בְּ⁠אֶ֖רֶץ מְגוּרֵ֣י אָבִ֑י⁠ו בְּ⁠אֶ֖רֶץ כְּנָֽעַן׃","wa⁠yé֣̇şěb yaʻàqò֔b bĕ̇⁠ʼe֖reẕ mĕgẇré֣y ʼábi֑y⁠w bĕ̇⁠ʼe֖reẕ kĕ̇náֽʻan׃"],[37,2,"אֵ֣לֶּה ׀ תֹּלְד֣וֹת יַעֲקֹ֗ב יוֹסֵ֞ף בֶּן־שְׁבַֽע־עֶשְׂרֵ֤ה שָׁנָה֙ הָיָ֨ה רֹעֶ֤ה אֶת־אֶחָי⁠ו֙ בַּ⁠צֹּ֔אן וְ⁠ה֣וּא נַ֗עַר אֶת־בְּנֵ֥י בִלְהָ֛ה וְ⁠אֶת־בְּנֵ֥י זִלְפָּ֖ה נְשֵׁ֣י אָבִ֑י⁠ו וַ⁠יָּבֵ֥א יוֹסֵ֛ף אֶת־דִּבָּתָ֥⁠ם רָעָ֖ה אֶל־אֲבִי⁠הֶֽם׃","ʼé֣lėh ׀ ţò̇lĕd֣wòţ yaʻàqò֗b ywòsé֞p bėn-şĕ̌baֽʻ-ʻeşĕ̂ré֤h şá̌náh֙ háyá֨h ròʻe֤h ʼeţ-ʼeẖáy⁠w֙ bȧ⁠ẕò̇֔ʼn wĕ⁠h֣ẇʼ na֗ʻar ʼeţ-bĕ̇né֥y bilĕhá֛h wĕ⁠ʼeţ-bĕ̇né֥y zilĕpá֖̇h nĕşé֣̌y ʼábi֑y⁠w wa⁠yá̇bé֥ʼ ywòsé֛p ʼeţ-di̇bá̇ţá֥⁠m ráʻá֖h ʼel-ʼàbiy⁠heֽm׃"],[37,3,"וְ⁠יִשְׂרָאֵ֗ל אָהַ֤ב אֶת־יוֹסֵף֙ מִ⁠כָּל־בָּנָ֔י⁠ו כִּֽי־בֶן־זְקֻנִ֥ים ה֖וּא ל֑⁠וֹ וְ⁠עָ֥שָׂה ל֖⁠וֹ כְּתֹ֥נֶת פַּסִּֽים׃","wĕ⁠yişĕ̂ráʼé֗l ʼáha֤b ʼeţ-ywòsép֙ mi⁠ká̇l-bá̇ná֔y⁠w kiֽ̇y-ben-zĕquni֥ym h֖ẇʼ l֑⁠wò wĕ⁠ʻá֥şá̂h l֖⁠wò kĕ̇ţò֥neţ pȧsiֽ̇ym׃"],[37,4,"וַ⁠יִּרְא֣וּ אֶחָ֗י⁠ו כִּֽי־אֹת֞⁠וֹ אָהַ֤ב אֲבִי⁠הֶם֙ מִ⁠כָּל־אֶחָ֔י⁠ו וַֽ⁠יִּשְׂנְא֖וּ אֹת֑⁠וֹ וְ⁠לֹ֥א יָכְל֖וּ דַּבְּר֥⁠וֹ לְ⁠שָׁלֹֽם׃","wa⁠yi̇rĕʼ֣ẇ ʼeẖá֗y⁠w kiֽ̇y-ʼòţ֞⁠wò ʼáha֤b ʼàbiy⁠hem֙ mi⁠ká̇l-ʼeẖá֔y⁠w waֽ⁠yi̇şĕ̂nĕʼ֖ẇ ʼòţ֑⁠wò wĕ⁠lò֥ʼ yákĕl֖ẇ dȧbĕ̇r֥⁠wò lĕ⁠şá̌lòֽm׃"],[37,5,"וַ⁠יַּחֲלֹ֤ם יוֹסֵף֙ חֲל֔וֹם וַ⁠יַּגֵּ֖ד לְ⁠אֶחָ֑י⁠ו וַ⁠יּוֹסִ֥פוּ ע֖וֹד שְׂנֹ֥א אֹתֽ⁠וֹ׃","wa⁠yȧẖàlò֤m ywòsép֙ ẖàl֔wòm wa⁠yȧgé֖̇d lĕ⁠ʼeẖá֑y⁠w wa⁠ẏwòsi֥pẇ ʻ֖wòd şĕ̂nò֥ʼ ʼòţֽ⁠wò׃"],[37,6,"וַ⁠יֹּ֖אמֶר אֲלֵי⁠הֶ֑ם שִׁמְעוּ־נָ֕א הַ⁠חֲל֥וֹם הַ⁠זֶּ֖ה אֲשֶׁ֥ר חָלָֽמְתִּי׃","wa⁠yò֖̇ʼmer ʼàléy⁠he֑m şǐmĕʻẇ-ná֕ʼ ha⁠ẖàl֥wòm ha⁠zė֖h ʼàşě֥r ẖáláֽmĕţi̇y׃"],[37,7,"וְ֠⁠הִנֵּה אֲנַ֜חְנוּ מְאַלְּמִ֤ים אֲלֻמִּים֙ בְּ⁠ת֣וֹךְ הַ⁠שָּׂדֶ֔ה וְ⁠הִנֵּ֛ה קָ֥מָה אֲלֻמָּתִ֖⁠י וְ⁠גַם־נִצָּ֑בָה וְ⁠הִנֵּ֤ה תְסֻבֶּ֨ינָה֙ אֲלֻמֹּ֣תֵי⁠כֶ֔ם וַ⁠תִּֽשְׁתַּחֲוֶ֖יןָ לַ⁠אֲלֻמָּתִֽ⁠י׃","wĕ֠⁠hiné̇h ʼàna֜ẖĕnẇ mĕʼalĕ̇mi֤ym ʼàlumi̇ym֙ bĕ̇⁠ţ֣wòkĕ ha⁠şá̇̂de֔h wĕ⁠hiné֛̇h qá֥máh ʼàlumá̇ţi֖⁠y wĕ⁠gam-niẕá֑̇báh wĕ⁠hiné֤̇h ţĕsubė֨ynáh֙ ʼàlumò֣̇ţéy⁠ke֔m wa⁠ţiֽ̇şĕ̌ţȧẖàwe֖yná la⁠ʼàlumá̇ţiֽ⁠y׃"],[37,8,"וַ⁠יֹּ֤אמְרוּ ל⁠וֹ֙ אֶחָ֔י⁠ו הֲ⁠מָלֹ֤ךְ תִּמְלֹךְ֙ עָלֵ֔י⁠נוּ אִם־מָשׁ֥וֹל תִּמְשֹׁ֖ל בָּ֑⁠נוּ וַ⁠יּוֹסִ֤פוּ עוֹד֙ שְׂנֹ֣א אֹת֔⁠וֹ עַל־חֲלֹמֹתָ֖י⁠ו וְ⁠עַל־דְּבָרָֽי⁠ו׃","wa⁠yò֤̇ʼmĕrẇ l⁠wò֙ ʼeẖá֔y⁠w hà⁠málò֤kĕ ţi̇mĕlòkĕ֙ ʻálé֔y⁠nẇ ʼim-máş֥̌wòl ţi̇mĕşò֖̌l bá֑̇⁠nẇ wa⁠ẏwòsi֤pẇ ʻwòd֙ şĕ̂nò֣ʼ ʼòţ֔⁠wò ʻal-ẖàlòmòţá֖y⁠w wĕ⁠ʻal-dĕ̇báráֽy⁠w׃"],[37,9,"וַ⁠יַּחֲלֹ֥ם עוֹד֙ חֲל֣וֹם אַחֵ֔ר וַ⁠יְסַפֵּ֥ר אֹת֖⁠וֹ לְ⁠אֶחָ֑י⁠ו וַ⁠יֹּ֗אמֶר הִנֵּ֨ה חָלַ֤מְתִּֽי חֲלוֹם֙ ע֔וֹד וְ⁠הִנֵּ֧ה הַ⁠שֶּׁ֣מֶשׁ וְ⁠הַ⁠יָּרֵ֗חַ וְ⁠אַחַ֤ד עָשָׂר֙ כּֽוֹכָבִ֔ים מִֽשְׁתַּחֲוִ֖ים לִֽ⁠י׃","wa⁠yȧẖàlò֥m ʻwòd֙ ẖàl֣wòm ʼaẖé֔r wa⁠yĕsapé֥̇r ʼòţ֖⁠wò lĕ⁠ʼeẖá֑y⁠w wa⁠yò̇֗ʼmer hiné̇֨h ẖála֤mĕţiֽ̇y ẖàlwòm֙ ʻ֔wòd wĕ⁠hiné֧̇h ha⁠şė֣̌meş̌ wĕ⁠ha⁠yá̇ré֗ẖa wĕ⁠ʼaẖa֤d ʻáşá̂r֙ kֽ̇wòkábi֔ym miֽşĕ̌ţȧẖàwi֖ym liֽ⁠y׃"],[37,10,"וַ⁠יְסַפֵּ֣ר אֶל־אָבִי⁠ו֮ וְ⁠אֶל־אֶחָי⁠ו֒ וַ⁠יִּגְעַר־בּ֣⁠וֹ אָבִ֔י⁠ו וַ⁠יֹּ֣אמֶר ל֔⁠וֹ מָ֛ה הַ⁠חֲל֥וֹם הַ⁠זֶּ֖ה אֲשֶׁ֣ר חָלָ֑מְתָּ הֲ⁠ב֣וֹא נָב֗וֹא אֲנִי֙ וְ⁠אִמְּ⁠ךָ֣ וְ⁠אַחֶ֔י⁠ךָ לְ⁠הִשְׁתַּחֲוֺ֥ת לְ⁠ךָ֖ אָֽרְצָ⁠ה׃","wa⁠yĕsapé֣̇r ʼel-ʼábiy⁠w֮ wĕ⁠ʼel-ʼeẖáy⁠w֒ wa⁠yi̇gĕʻar-ḃ֣⁠wò ʼábi֔y⁠w wa⁠yò֣̇ʼmer l֔⁠wò má֛h ha⁠ẖàl֥wòm ha⁠zė֖h ʼàşě֣r ẖálá֑mĕţá̇ hà⁠b֣wòʼ náb֗wòʼ ʼàniy֙ wĕ⁠ʼimĕ̇⁠ká֣ wĕ⁠ʼaẖe֔y⁠ká lĕ⁠hişĕ̌ţȧẖàwֺ֥ţ lĕ⁠ká֖ ʼáֽrĕẕá⁠h׃"],[37,11,"וַ⁠יְקַנְאוּ־ב֖⁠וֹ אֶחָ֑י⁠ו וְ⁠אָבִ֖י⁠ו שָׁמַ֥ר אֶת־הַ⁠דָּבָֽר׃","wa⁠yĕqanĕʼẇ-b֖⁠wò ʼeẖá֑y⁠w wĕ⁠ʼábi֖y⁠w şá̌ma֥r ʼeţ-ha⁠dá̇báֽr׃"],[37,12,"וַ⁠יֵּלְכ֖וּ אֶחָ֑י⁠ו לִ⁠רְע֛וֹת אֶׄתׄ־צֹ֥אן אֲבִי⁠הֶ֖ם בִּ⁠שְׁכֶֽם׃","wa⁠yé̇lĕk֖ẇ ʼeẖá֑y⁠w li⁠rĕʻ֛wòţ ʼeׄţׄ-ẕò֥ʼn ʼàbiy⁠he֖m bi̇⁠şĕ̌keֽm׃"],[37,13,"וַ⁠יֹּ֨אמֶר יִשְׂרָאֵ֜ל אֶל־יוֹסֵ֗ף הֲ⁠ל֤וֹא אַחֶ֨י⁠ךָ֙ רֹעִ֣ים בִּ⁠שְׁכֶ֔ם לְכָ֖⁠ה וְ⁠אֶשְׁלָחֲ⁠ךָ֣ אֲלֵי⁠הֶ֑ם וַ⁠יֹּ֥אמֶר ל֖⁠וֹ הִנֵּֽ⁠נִי׃","wa⁠yò̇֨ʼmer yişĕ̂ráʼé֜l ʼel-ywòsé֗p hà⁠l֤wòʼ ʼaẖe֨y⁠ká֙ ròʻi֣ym bi̇⁠şĕ̌ke֔m lĕká֖⁠h wĕ⁠ʼeşĕ̌láẖà⁠ká֣ ʼàléy⁠he֑m wa⁠yò֥̇ʼmer l֖⁠wò hinéֽ̇⁠niy׃"],[37,14,"וַ⁠יֹּ֣אמֶר ל֗⁠וֹ לֶךְ־נָ֨א רְאֵ֜ה אֶת־שְׁל֤וֹם אַחֶ֨י⁠ךָ֙ וְ⁠אֶת־שְׁל֣וֹם הַ⁠צֹּ֔אן וַ⁠הֲשִׁבֵ֖⁠נִי דָּבָ֑ר וַ⁠יִּשְׁלָחֵ֨⁠הוּ֙ מֵ⁠עֵ֣מֶק חֶבְר֔וֹן וַ⁠יָּבֹ֖א שְׁכֶֽמָ⁠ה׃","wa⁠yò֣̇ʼmer l֗⁠wò lekĕ-ná֨ʼ rĕʼé֜h ʼeţ-şĕ̌l֤wòm ʼaẖe֨y⁠ká֙ wĕ⁠ʼeţ-şĕ̌l֣wòm ha⁠ẕò̇֔ʼn wa⁠hàşǐbé֖⁠niy dá̇bá֑r wa⁠yi̇şĕ̌láẖé֨⁠hẇ֙ mé⁠ʻé֣meq ẖebĕr֔wòn wa⁠yá̇bò֖ʼ şĕ̌keֽmá⁠h׃"],[37,15,"וַ⁠יִּמְצָאֵ֣⁠הוּ אִ֔ישׁ וְ⁠הִנֵּ֥ה תֹעֶ֖ה בַּ⁠שָּׂדֶ֑ה וַ⁠יִּשְׁאָלֵ֧⁠הוּ הָ⁠אִ֛ישׁ לֵ⁠אמֹ֖ר מַה־תְּבַקֵּֽשׁ׃","wa⁠yi̇mĕẕáʼé֣⁠hẇ ʼi֔yş̌ wĕ⁠hiné֥̇h ţòʻe֖h bȧ⁠şá̇̂de֑h wa⁠yi̇şĕ̌ʼálé֧⁠hẇ há⁠ʼi֛yş̌ lé⁠ʼmò֖r mah-ţĕ̇baqéֽ̇ş̌׃"],[37,16,"וַ⁠יֹּ֕אמֶר אֶת־אַחַ֖⁠י אָנֹכִ֣י מְבַקֵּ֑שׁ הַגִּֽידָ⁠ה־נָּ֣א לִ֔⁠י אֵיפֹ֖ה הֵ֥ם רֹעִֽים׃","wa⁠yò̇֕ʼmer ʼeţ-ʼaẖa֖⁠y ʼánòki֣y mĕbaqé֑̇ş̌ hagiֽ̇ydá⁠h-ná֣̇ʼ li֔⁠y ʼéypò֖h hé֥m ròʻiֽym׃"],[37,17,"וַ⁠יֹּ֤אמֶר הָ⁠אִישׁ֙ נָסְע֣וּ מִ⁠זֶּ֔ה כִּ֤י שָׁמַ֨עְתִּי֙ אֹֽמְרִ֔ים נֵלְכָ֖ה דֹּתָ֑יְנָ⁠ה וַ⁠יֵּ֤לֶךְ יוֹסֵף֙ אַחַ֣ר אֶחָ֔י⁠ו וַ⁠יִּמְצָאֵ֖⁠ם בְּ⁠דֹתָֽן׃","wa⁠yò֤̇ʼmer há⁠ʼiyş̌֙ násĕʻ֣ẇ mi⁠zė֔h ki֤̇y şá̌ma֨ʻĕţi̇y֙ ʼòֽmĕri֔ym nélĕká֖h dò̇ţá֑yĕná⁠h wa⁠yé֤̇lekĕ ywòsép֙ ʼaẖa֣r ʼeẖá֔y⁠w wa⁠yi̇mĕẕáʼé֖⁠m bĕ̇⁠dòţáֽn׃"],[37,18,"וַ⁠יִּרְא֥וּ אֹת֖⁠וֹ מֵ⁠רָחֹ֑ק וּ⁠בְ⁠טֶ֨רֶם֙ יִקְרַ֣ב אֲלֵי⁠הֶ֔ם וַ⁠יִּֽתְנַכְּל֥וּ אֹת֖⁠וֹ לַ⁠הֲמִיתֽ⁠וֹ׃","wa⁠yi̇rĕʼ֥ẇ ʼòţ֖⁠wò mé⁠ráẖò֑q ẇ⁠bĕ⁠te֨rem֙ yiqĕra֣b ʼàléy⁠he֔m wa⁠yiֽ̇ţĕnakĕ̇l֥ẇ ʼòţ֖⁠wò la⁠hàmiyţֽ⁠wò׃"],[37,19,"וַ⁠יֹּאמְר֖וּ אִ֣ישׁ אֶל־אָחִ֑י⁠ו הִנֵּ֗ה בַּ֛עַל הַ⁠חֲלֹמ֥וֹת הַלָּזֶ֖ה בָּֽא׃","wa⁠yò̇ʼmĕr֖ẇ ʼi֣yş̌ ʼel-ʼáẖi֑y⁠w hiné̇֗h bȧ֛ʻal ha⁠ẖàlòm֥wòţ halá̇ze֖h báֽ̇ʼ׃"],[37,20,"וְ⁠עַתָּ֣ה ׀ לְכ֣וּ וְ⁠נַֽהַרְגֵ֗⁠הוּ וְ⁠נַשְׁלִכֵ֨⁠הוּ֙ בְּ⁠אַחַ֣ד הַ⁠בֹּר֔וֹת וְ⁠אָמַ֕רְנוּ חַיָּ֥ה רָעָ֖ה אֲכָלָ֑תְ⁠הוּ וְ⁠נִרְאֶ֕ה מַה־יִּהְי֖וּ חֲלֹמֹתָֽי⁠ו׃","wĕ⁠ʻaţá֣̇h ׀ lĕk֣ẇ wĕ⁠naֽharĕgé֗⁠hẇ wĕ⁠naşĕ̌liké֨⁠hẇ֙ bĕ̇⁠ʼaẖa֣d ha⁠bò̇r֔wòţ wĕ⁠ʼáma֕rĕnẇ ẖayá֥̇h ráʻá֖h ʼàkálá֑ţĕ⁠hẇ wĕ⁠nirĕʼe֕h mah-yi̇hĕy֖ẇ ẖàlòmòţáֽy⁠w׃"],[37,21,"וַ⁠יִּשְׁמַ֣ע רְאוּבֵ֔ן וַ⁠יַּצִּלֵ֖⁠הוּ מִ⁠יָּדָ֑⁠ם וַ⁠יֹּ֕אמֶר לֹ֥א נַכֶּ֖⁠נּוּ נָֽפֶשׁ׃","wa⁠yi̇şĕ̌ma֣ʻ rĕʼẇbé֔n wa⁠yȧẕi̇lé֖⁠hẇ mi⁠yá̇dá֑⁠m wa⁠yò̇֕ʼmer lò֥ʼ nakė֖⁠ṅẇ náֽpeş̌׃"],[37,22,"וַ⁠יֹּ֨אמֶר אֲלֵ⁠הֶ֣ם ׀ רְאוּבֵן֮ אַל־תִּשְׁפְּכוּ־דָם֒ הַשְׁלִ֣יכוּ אֹת֗⁠וֹ אֶל־הַ⁠בּ֤וֹר הַ⁠זֶּה֙ אֲשֶׁ֣ר בַּ⁠מִּדְבָּ֔ר וְ⁠יָ֖ד אַל־תִּשְׁלְחוּ־ב֑⁠וֹ לְמַ֗עַן הַצִּ֤יל אֹת⁠וֹ֙ מִ⁠יָּדָ֔⁠ם לַ⁠הֲשִׁיב֖⁠וֹ אֶל־אָבִֽי⁠ו׃","wa⁠yò̇֨ʼmer ʼàlé⁠he֣m ׀ rĕʼẇbén֮ ʼal-ţi̇şĕ̌pĕ̇kẇ-dám֒ haşĕ̌li֣ykẇ ʼòţ֗⁠wò ʼel-ha⁠ḃ֤wòr ha⁠zėh֙ ʼàşě֣r bȧ⁠mi̇dĕbá̇֔r wĕ⁠yá֖d ʼal-ţi̇şĕ̌lĕẖẇ-b֑⁠wò lĕma֗ʻan haẕi֤̇yl ʼòţ⁠wò֙ mi⁠yá̇dá֔⁠m la⁠hàşǐyb֖⁠wò ʼel-ʼábiֽy⁠w׃"],[37,23,"וַֽ⁠יְהִ֕י כַּֽ⁠אֲשֶׁר־בָּ֥א יוֹסֵ֖ף אֶל־אֶחָ֑י⁠ו וַ⁠יַּפְשִׁ֤יטוּ אֶת־יוֹסֵף֙ אֶת־כֻּתָּנְתּ֔⁠וֹ אֶת־כְּתֹ֥נֶת הַ⁠פַּסִּ֖ים אֲשֶׁ֥ר עָלָֽי⁠ו׃","wֽa⁠yĕhi֕y kֽ̇a⁠ʼàşěr-bá֥̇ʼ ywòsé֖p ʼel-ʼeẖá֑y⁠w wa⁠yȧpĕşǐ֤ytẇ ʼeţ-ywòsép֙ ʼeţ-ku̇ţá̇nĕţ̇֔⁠wò ʼeţ-kĕ̇ţò֥neţ ha⁠pȧsi֖̇ym ʼàşě֥r ʻáláֽy⁠w׃"],[37,24,"וַ⁠יִּ֨קָּחֻ֔⁠הוּ וַ⁠יַּשְׁלִ֥כוּ אֹת֖⁠וֹ הַ⁠בֹּ֑רָ⁠ה וְ⁠הַ⁠בּ֣וֹר רֵ֔ק אֵ֥ין בּ֖⁠וֹ מָֽיִם׃","wa⁠yi̇֨qá̇ẖu֔⁠hẇ wa⁠yȧşĕ̌li֥kẇ ʼòţ֖⁠wò ha⁠bò֑̇rá⁠h wĕ⁠ha⁠ḃ֣wòr ré֔q ʼé֥yn ḃ֖⁠wò máֽyim׃"],[37,25,"וַ⁠יֵּשְׁבוּ֮ לֶֽ⁠אֱכָל־לֶחֶם֒ וַ⁠יִּשְׂא֤וּ עֵֽינֵי⁠הֶם֙ וַ⁠יִּרְא֔וּ וְ⁠הִנֵּה֙ אֹרְחַ֣ת יִשְׁמְעֵאלִ֔ים בָּאָ֖ה מִ⁠גִּלְעָ֑ד וּ⁠גְמַלֵּי⁠הֶ֣ם נֹֽשְׂאִ֗ים נְכֹאת֙ וּ⁠צְרִ֣י וָ⁠לֹ֔ט הוֹלְכִ֖ים לְ⁠הוֹרִ֥יד מִצְרָֽיְמָ⁠ה׃","wa⁠yé̇şĕ̌bẇ֮ leֽ⁠ʼèkál-leẖem֒ wa⁠yi̇şĕ̂ʼ֤ẇ ʻéֽynéy⁠hem֙ wa⁠yi̇rĕʼ֔ẇ wĕ⁠hiné̇h֙ ʼòrĕẖa֣ţ yişĕ̌mĕʻéʼli֔ym bá̇ʼá֖h mi⁠gi̇lĕʻá֑d ẇ⁠gĕmalé̇y⁠he֣m nòֽşĕ̂ʼi֗ym nĕkòʼţ֙ ẇ⁠ẕĕri֣y wá⁠lò֔t hwòlĕki֖ym lĕ⁠hwòri֥yd miẕĕráֽyĕmá⁠h׃"],[37,26,"וַ⁠יֹּ֥אמֶר יְהוּדָ֖ה אֶל־אֶחָ֑י⁠ו מַה־בֶּ֗צַע כִּ֤י נַהֲרֹג֙ אֶת־אָחִ֔י⁠נוּ וְ⁠כִסִּ֖ינוּ אֶת־דָּמֽ⁠וֹ׃","wa⁠yò֥̇ʼmer yĕhẇdá֖h ʼel-ʼeẖá֑y⁠w mah-bė֗ẕaʻ ki֤̇y nahàròg֙ ʼeţ-ʼáẖi֔y⁠nẇ wĕ⁠kisi֖̇ynẇ ʼeţ-dá̇mֽ⁠wò׃"],[37,27,"לְכ֞וּ וְ⁠נִמְכְּרֶ֣⁠נּוּ לַ⁠יִּשְׁמְעֵאלִ֗ים וְ⁠יָדֵ֨⁠נוּ֙ אַל־תְּהִי־ב֔⁠וֹ כִּֽי־אָחִ֥י⁠נוּ בְשָׂרֵ֖⁠נוּ ה֑וּא וַֽ⁠יִּשְׁמְע֖וּ אֶחָֽי⁠ו׃","lĕk֞ẇ wĕ⁠nimĕkĕ̇re֣⁠ṅẇ la⁠yi̇şĕ̌mĕʻéʼli֗ym wĕ⁠yádé֨⁠nẇ֙ ʼal-ţĕ̇hiy-b֔⁠wò kiֽ̇y-ʼáẖi֥y⁠nẇ bĕşá̂ré֖⁠nẇ h֑ẇʼ waֽ⁠yi̇şĕ̌mĕʻ֖ẇ ʼeẖáֽy⁠w׃"],[37,28,"וַ⁠יַּֽעַבְרוּ֩ אֲנָשִׁ֨ים מִדְיָנִ֜ים סֹֽחֲרִ֗ים וַֽ⁠יִּמְשְׁכוּ֙ וַ⁠יַּֽעֲל֤וּ אֶת־יוֹסֵף֙ מִן־הַ⁠בּ֔וֹר וַ⁠יִּמְכְּר֧וּ אֶת־יוֹסֵ֛ף לַ⁠יִּשְׁמְעֵאלִ֖ים בְּ⁠עֶשְׂרִ֣ים כָּ֑סֶף וַ⁠יָּבִ֥יאוּ אֶת־יוֹסֵ֖ף מִצְרָֽיְמָ⁠ה׃","wa⁠yȧֽʻabĕrẇ֩ ʼànáşǐ֨ym midĕyáni֜ym sòֽẖàri֗ym waֽ⁠yi̇mĕşĕ̌kẇ֙ wa⁠yȧֽʻàl֤ẇ ʼeţ-ywòsép֙ min-ha⁠ḃ֔wòr wa⁠yi̇mĕkĕ̇r֧ẇ ʼeţ-ywòsé֛p la⁠yi̇şĕ̌mĕʻéʼli֖ym bĕ̇⁠ʻeşĕ̂ri֣ym ká֑̇sep wa⁠yá̇bi֥yʼẇ ʼeţ-ywòsé֖p miẕĕráֽyĕmá⁠h׃"],[37,29,"וַ⁠יָּ֤שָׁב רְאוּבֵן֙ אֶל־הַ⁠בּ֔וֹר וְ⁠הִנֵּ֥ה אֵין־יוֹסֵ֖ף בַּ⁠בּ֑וֹר וַ⁠יִּקְרַ֖ע אֶת־בְּגָדָֽי⁠ו׃","wa⁠yá֤̇şá̌b rĕʼẇbén֙ ʼel-ha⁠ḃ֔wòr wĕ⁠hiné֥̇h ʼéyn-ywòsé֖p bȧ⁠ḃ֑wòr wa⁠yi̇qĕra֖ʻ ʼeţ-bĕ̇gádáֽy⁠w׃"],[37,30,"וַ⁠יָּ֥שָׁב אֶל־אֶחָ֖י⁠ו וַ⁠יֹּאמַ֑ר הַ⁠יֶּ֣לֶד אֵינֶ֔⁠נּוּ וַ⁠אֲנִ֖י אָ֥נָה אֲנִי־בָֽא׃","wa⁠yá֥̇şá̌b ʼel-ʼeẖá֖y⁠w wa⁠yò̇ʼma֑r ha⁠yė֣led ʼéyne֔⁠ṅẇ wa⁠ʼàni֖y ʼá֥náh ʼàniy-báֽʼ׃"],[37,31,"וַ⁠יִּקְח֖וּ אֶת־כְּתֹ֣נֶת יוֹסֵ֑ף וַֽ⁠יִּשְׁחֲטוּ֙ שְׂעִ֣יר עִזִּ֔ים וַ⁠יִּטְבְּל֥וּ אֶת־הַ⁠כֻּתֹּ֖נֶת בַּ⁠דָּֽם׃","wa⁠yi̇qĕẖ֖ẇ ʼeţ-kĕ̇ţò֣neţ ywòsé֑p waֽ⁠yi̇şĕ̌ẖàtẇ֙ şĕ̂ʻi֣yr ʻizi̇֔ym wa⁠yi̇tĕbĕ̇l֥ẇ ʼeţ-ha⁠ku̇ţò֖̇neţ bȧ⁠dáֽ̇m׃"],[37,32,"וַֽ⁠יְשַׁלְּח֞וּ אֶת־כְּתֹ֣נֶת הַ⁠פַּסִּ֗ים וַ⁠יָּבִ֨יאוּ֙ אֶל־אֲבִי⁠הֶ֔ם וַ⁠יֹּאמְר֖וּ זֹ֣את מָצָ֑אנוּ הַכֶּר־נָ֗א הַ⁠כְּתֹ֧נֶת בִּנְ⁠ךָ֛ הִ֖וא אִם־לֹֽא׃","waֽ⁠yĕşǎlĕ̇ẖ֞ẇ ʼeţ-kĕ̇ţò֣neţ ha⁠pȧsi̇֗ym wa⁠yá̇bi֨yʼẇ֙ ʼel-ʼàbiy⁠he֔m wa⁠yò̇ʼmĕr֖ẇ zò֣ʼţ máẕá֑ʼnẇ hakėr-ná֗ʼ ha⁠kĕ̇ţò֧neţ bi̇nĕ⁠ká֛ hi֖wʼ ʼim-lòֽʼ׃"],[37,33,"וַ⁠יַּכִּירָ֤⁠הּ וַ⁠יֹּ֨אמֶר֙ כְּתֹ֣נֶת בְּנִ֔⁠י חַיָּ֥ה רָעָ֖ה אֲכָלָ֑תְ⁠הוּ טָרֹ֥ף טֹרַ֖ף יוֹסֵֽף׃","wa⁠yȧki̇yrá֤⁠ḣ wa⁠yò̇֨ʼmer֙ kĕ̇ţò֣neţ bĕ̇ni֔⁠y ẖayá֥̇h ráʻá֖h ʼàkálá֑ţĕ⁠hẇ tárò֥p tòra֖p ywòséֽp׃"],[37,34,"וַ⁠יִּקְרַ֤ע יַעֲקֹב֙ שִׂמְלֹתָ֔י⁠ו וַ⁠יָּ֥שֶׂם שַׂ֖ק בְּ⁠מָתְנָ֑י⁠ו וַ⁠יִּתְאַבֵּ֥ל עַל־בְּנ֖⁠וֹ יָמִ֥ים רַבִּֽים׃","wa⁠yi̇qĕra֤ʻ yaʻàqòb֙ şîmĕlòţá֔y⁠w wa⁠yá֥̇şêm şâ֖q bĕ̇⁠máţĕná֑y⁠w wa⁠yi̇ţĕʼabé֥̇l ʻal-bĕ̇n֖⁠wò yámi֥ym rabiֽ̇ym׃"],[37,35,"וַ⁠יָּקֻמוּ֩ כָל־בָּנָ֨י⁠ו וְ⁠כָל־בְּנֹתָ֜י⁠ו לְ⁠נַחֲמ֗⁠וֹ וַ⁠יְמָאֵן֙ לְ⁠הִתְנַחֵ֔ם וַ⁠יֹּ֕אמֶר כִּֽי־אֵרֵ֧ד אֶל־בְּנִ֛⁠י אָבֵ֖ל שְׁאֹ֑לָ⁠ה וַ⁠יֵּ֥בְךְּ אֹת֖⁠וֹ אָבִֽי⁠ו׃","wa⁠yá̇qumẇ֩ kál-bá̇ná֨y⁠w wĕ⁠kál-bĕ̇nòţá֜y⁠w lĕ⁠naẖàm֗⁠wò wa⁠yĕmáʼén֙ lĕ⁠hiţĕnaẖé֔m wa⁠yò̇֕ʼmer kiֽ̇y-ʼéré֧d ʼel-bĕ̇ni֛⁠y ʼábé֖l şĕ̌ʼò֑lá⁠h wa⁠yé֥̇bĕkĕ̇ ʼòţ֖⁠wò ʼábiֽy⁠w׃"],[37,36,"וְ⁠הַ֨⁠מְּדָנִ֔ים מָכְר֥וּ אֹת֖⁠וֹ אֶל־מִצְרָ֑יִם לְ⁠פֽוֹטִיפַר֙ סְרִ֣יס פַּרְעֹ֔ה שַׂ֖ר הַ⁠טַּבָּחִֽים׃פ","wĕ⁠ha֨⁠mĕ̇dáni֔ym mákĕr֥ẇ ʼòţ֖⁠wò ʼel-miẕĕrá֑yim lĕ⁠pֽwòtiypar֙ sĕri֣ys pȧrĕʻò֔h şâ֖r ha⁠tȧbá̇ẖiֽym׃p"],[38,1,"וַֽ⁠יְהִי֙ בָּ⁠עֵ֣ת הַ⁠הִ֔וא וַ⁠יֵּ֥רֶד יְהוּדָ֖ה מֵ⁠אֵ֣ת אֶחָ֑י⁠ו וַ⁠יֵּ֛ט עַד־אִ֥ישׁ עֲדֻלָּמִ֖י וּ⁠שְׁמ֥⁠וֹ חִירָֽה׃","waֽ⁠yĕhiy֙ bá̇⁠ʻé֣ţ ha⁠hi֔wʼ wa⁠yé֥̇red yĕhẇdá֖h mé⁠ʼé֣ţ ʼeẖá֑y⁠w wa⁠yé֛̇t ʻad-ʼi֥yş̌ ʻàdulá̇mi֖y ẇ⁠şĕ̌m֥⁠wò ẖiyráֽh׃"],[38,2,"וַ⁠יַּרְא־שָׁ֧ם יְהוּדָ֛ה בַּת־אִ֥ישׁ כְּנַעֲנִ֖י וּ⁠שְׁמ֣⁠וֹ שׁ֑וּעַ וַ⁠יִּקָּחֶ֖⁠הָ וַ⁠יָּבֹ֥א אֵלֶֽי⁠הָ׃","wa⁠yȧrĕʼ-şá֧̌m yĕhẇdá֛h bȧţ-ʼi֥yş̌ kĕ̇naʻàni֖y ẇ⁠şĕ̌m֣⁠wò ş֑̌ẇʻa wa⁠yi̇qá̇ẖe֖⁠há wa⁠yá̇bò֥ʼ ʼéleֽy⁠há׃"],[38,3,"וַ⁠תַּ֖הַר וַ⁠תֵּ֣לֶד בֵּ֑ן וַ⁠יִּקְרָ֥א אֶת־שְׁמ֖⁠וֹ עֵֽר׃","wa⁠ţȧ֖har wa⁠ţé֣̇led bé֑̇n wa⁠yi̇qĕrá֥ʼ ʼeţ-şĕ̌m֖⁠wò ʻéֽr׃"],[38,4,"וַ⁠תַּ֥הַר ע֖וֹד וַ⁠תֵּ֣לֶד בֵּ֑ן וַ⁠תִּקְרָ֥א אֶת־שְׁמ֖⁠וֹ אוֹנָֽן׃","wa⁠ţȧ֥har ʻ֖wòd wa⁠ţé֣̇led bé֑̇n wa⁠ţi̇qĕrá֥ʼ ʼeţ-şĕ̌m֖⁠wò ʼwònáֽn׃"],[38,5,"וַ⁠תֹּ֤סֶף עוֹד֙ וַ⁠תֵּ֣לֶד בֵּ֔ן וַ⁠תִּקְרָ֥א אֶת־שְׁמ֖⁠וֹ שֵׁלָ֑ה וְ⁠הָיָ֥ה בִ⁠כְזִ֖יב בְּ⁠לִדְתָּ֥⁠הּ אֹתֽ⁠וֹ׃","wa⁠ţò֤̇sep ʻwòd֙ wa⁠ţé֣̇led bé̇֔n wa⁠ţi̇qĕrá֥ʼ ʼeţ-şĕ̌m֖⁠wò şé̌lá֑h wĕ⁠háyá֥h bi⁠kĕzi֖yb bĕ̇⁠lidĕţá֥̇⁠ḣ ʼòţֽ⁠wò׃"],[38,6,"וַ⁠יִּקַּ֧ח יְהוּדָ֛ה אִשָּׁ֖ה לְ⁠עֵ֣ר בְּכוֹר֑⁠וֹ וּ⁠שְׁמָ֖⁠הּ תָּמָֽר׃","wa⁠yi̇qȧ֧ẖ yĕhẇdá֛h ʼişá֖̇̌h lĕ⁠ʻé֣r bĕ̇kwòr֑⁠wò ẇ⁠şĕ̌má֖⁠ḣ ţá̇máֽr׃"],[38,7,"וַ⁠יְהִ֗י עֵ֚ר בְּכ֣וֹר יְהוּדָ֔ה רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה וַ⁠יְמִתֵ֖⁠הוּ יְהוָֽה׃","wa⁠yĕhi֗y ʻé֚r bĕ̇k֣wòr yĕhẇdá֔h ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h wa⁠yĕmiţé֖⁠hẇ yĕhwáֽh׃"],[38,8,"וַ⁠יֹּ֤אמֶר יְהוּדָה֙ לְ⁠אוֹנָ֔ן בֹּ֛א אֶל־אֵ֥שֶׁת אָחִ֖י⁠ךָ וְ⁠יַבֵּ֣ם אֹתָ֑⁠הּ וְ⁠הָקֵ֥ם זֶ֖רַע לְ⁠אָחִֽי⁠ךָ׃","wa⁠yò֤̇ʼmer yĕhẇdáh֙ lĕ⁠ʼwòná֔n bò֛̇ʼ ʼel-ʼé֥şěţ ʼáẖi֖y⁠ká wĕ⁠yabé֣̇m ʼòţá֑⁠ḣ wĕ⁠háqé֥m ze֖raʻ lĕ⁠ʼáẖiֽy⁠ká׃"],[38,9,"וַ⁠יֵּ֣דַע אוֹנָ֔ן כִּ֛י לֹּ֥א ל֖⁠וֹ יִהְיֶ֣ה הַ⁠זָּ֑רַע וְ⁠הָיָ֞ה אִם־בָּ֨א אֶל־אֵ֤שֶׁת אָחִי⁠ו֙ וְ⁠שִׁחֵ֣ת אַ֔רְצָ⁠ה לְ⁠בִלְתִּ֥י נְתָן־זֶ֖רַע לְ⁠אָחִֽי⁠ו׃","wa⁠yé֣̇daʻ ʼwòná֔n ki֛̇y lò֥̇ʼ l֖⁠wò yihĕye֣h ha⁠zá֑̇raʻ wĕ⁠háyá֞h ʼim-bá̇֨ʼ ʼel-ʼé֤şěţ ʼáẖiy⁠w֙ wĕ⁠şǐẖé֣ţ ʼa֔rĕẕá⁠h lĕ⁠bilĕţi֥̇y nĕţán-ze֖raʻ lĕ⁠ʼáẖiֽy⁠w׃"],[38,10,"וַ⁠יֵּ֛רַע בְּ⁠עֵינֵ֥י יְהוָ֖ה אֲשֶׁ֣ר עָשָׂ֑ה וַ⁠יָּ֖מֶת גַּם־אֹתֽ⁠וֹ׃","wa⁠yé֛̇raʻ bĕ̇⁠ʻéyné֥y yĕhwá֖h ʼàşě֣r ʻáşá֑̂h wa⁠yá֖̇meţ gȧm-ʼòţֽ⁠wò׃"],[38,11,"וַ⁠יֹּ֣אמֶר יְהוּדָה֩ לְ⁠תָמָ֨ר כַּלָּת֜⁠וֹ שְׁבִ֧י אַלְמָנָ֣ה בֵית־אָבִ֗י⁠ךְ עַד־יִגְדַּל֙ שֵׁלָ֣ה בְנִ֔⁠י כִּ֣י אָמַ֔ר פֶּן־יָמ֥וּת גַּם־ה֖וּא כְּ⁠אֶחָ֑י⁠ו וַ⁠תֵּ֣לֶךְ תָּמָ֔ר וַ⁠תֵּ֖שֶׁב בֵּ֥ית אָבִֽי⁠הָ׃","wa⁠yò֣̇ʼmer yĕhẇdáh֩ lĕ⁠ţámá֨r kȧlá̇ţ֜⁠wò şĕ̌bi֧y ʼalĕmáná֣h béyţ-ʼábi֗y⁠kĕ ʻad-yigĕdȧl֙ şé̌lá֣h bĕni֔⁠y ki֣̇y ʼáma֔r pėn-yám֥ẇţ gȧm-h֖ẇʼ kĕ̇⁠ʼeẖá֑y⁠w wa⁠ţé֣̇lekĕ ţá̇má֔r wa⁠ţé֖̇şěb bé֥̇yţ ʼábiֽy⁠há׃"],[38,12,"וַ⁠יִּרְבּוּ֙ הַ⁠יָּמִ֔ים וַ⁠תָּ֖מָת בַּת־שׁ֣וּעַ אֵֽשֶׁת־יְהוּדָ֑ה וַ⁠יִּנָּ֣חֶם יְהוּדָ֗ה וַ⁠יַּ֜עַל עַל־גֹּֽזֲזֵ֤י צֹאנ⁠וֹ֙ ה֗וּא וְ⁠חִירָ֛ה רֵעֵ֥⁠הוּ הָ⁠עֲדֻלָּמִ֖י תִּמְנָֽתָ⁠ה׃","wa⁠yi̇rĕḃẇ֙ ha⁠yá̇mi֔ym wa⁠ţá֖̇máţ bȧţ-ş֣̌ẇʻa ʼéֽşěţ-yĕhẇdá֑h wa⁠yi̇ná֣̇ẖem yĕhẇdá֗h wa⁠yȧ֜ʻal ʻal-gòֽ̇zàzé֤y ẕòʼn⁠wò֙ h֗ẇʼ wĕ⁠ẖiyrá֛h réʻé֥⁠hẇ há⁠ʻàdulá̇mi֖y ţi̇mĕnáֽţá⁠h׃"],[38,13,"וַ⁠יֻּגַּ֥ד לְ⁠תָמָ֖ר לֵ⁠אמֹ֑ר הִנֵּ֥ה חָמִ֛י⁠ךְ עֹלֶ֥ה תִמְנָ֖תָ⁠ה לָ⁠גֹ֥ז צֹאנֽ⁠וֹ׃","wa⁠yu̇gȧ֥d lĕ⁠ţámá֖r lé⁠ʼmò֑r hiné֥̇h ẖámi֛y⁠kĕ ʻòle֥h ţimĕná֖ţá⁠h lá⁠gò֥z ẕòʼnֽ⁠wò׃"],[38,14,"וַ⁠תָּסַר֩ בִּגְדֵ֨י אַלְמְנוּתָ֜⁠הּ מֵֽ⁠עָלֶ֗י⁠הָ וַ⁠תְּכַ֤ס בַּ⁠צָּעִיף֙ וַ⁠תִּתְעַלָּ֔ף וַ⁠תֵּ֨שֶׁב֙ בְּ⁠פֶ֣תַח עֵינַ֔יִם אֲשֶׁ֖ר עַל־דֶּ֣רֶךְ תִּמְנָ֑תָ⁠ה כִּ֤י רָאֲתָה֙ כִּֽי־גָדַ֣ל שֵׁלָ֔ה וְ⁠הִ֕וא לֹֽא־נִתְּנָ֥ה ל֖⁠וֹ לְ⁠אִשָּֽׁה׃","wa⁠ţá̇sar֩ bi̇gĕdé֨y ʼalĕmĕnẇţá֜⁠ḣ méֽ⁠ʻále֗y⁠há wa⁠ţĕ̇ka֤s bȧ⁠ẕá̇ʻiyp֙ wa⁠ţi̇ţĕʻalá̇֔p wa⁠ţé̇֨şěb֙ bĕ̇⁠pe֣ţaẖ ʻéyna֔yim ʼàşě֖r ʻal-dė֣rekĕ ţi̇mĕná֑ţá⁠h ki֤̇y ráʼàţáh֙ kiֽ̇y-gáda֣l şé̌lá֔h wĕ⁠hi֕wʼ lòֽʼ-niţĕ̇ná֥h l֖⁠wò lĕ⁠ʼişáֽ̇̌h׃"],[38,15,"וַ⁠יִּרְאֶ֣⁠הָ יְהוּדָ֔ה וַֽ⁠יַּחְשְׁבֶ֖⁠הָ לְ⁠זוֹנָ֑ה כִּ֥י כִסְּתָ֖ה פָּנֶֽי⁠הָ׃","wa⁠yi̇rĕʼe֣⁠há yĕhẇdá֔h wֽa⁠yȧẖĕşĕ̌be֖⁠há lĕ⁠zwòná֑h ki֥̇y kisĕ̇ţá֖h pá̇neֽy⁠há׃"],[38,16,"וַ⁠יֵּ֨ט אֵלֶ֜י⁠הָ אֶל־הַ⁠דֶּ֗רֶךְ וַ⁠יֹּ֨אמֶר֙ הָֽבָ⁠ה־נָּא֙ אָב֣וֹא אֵלַ֔יִ⁠ךְ כִּ֚י לֹ֣א יָדַ֔ע כִּ֥י כַלָּת֖⁠וֹ הִ֑וא וַ⁠תֹּ֨אמֶר֙ מַה־תִּתֶּן־לִּ֔⁠י כִּ֥י תָב֖וֹא אֵלָֽ⁠י׃","wa⁠yé̇֨t ʼéle֜y⁠há ʼel-ha⁠dė֗rekĕ wa⁠yò̇֨ʼmer֙ háֽbá⁠h-ná̇ʼ֙ ʼáb֣wòʼ ʼéla֔yi⁠kĕ ki֚̇y lò֣ʼ yáda֔ʻ ki֥̇y kalá̇ţ֖⁠wò hi֑wʼ wa⁠ţò̇֨ʼmer֙ mah-ţi̇ţėn-li̇֔⁠y ki֥̇y ţáb֖wòʼ ʼéláֽ⁠y׃"],[38,17,"וַ⁠יֹּ֕אמֶר אָנֹכִ֛י אֲשַׁלַּ֥ח גְּדִֽי־עִזִּ֖ים מִן־הַ⁠צֹּ֑אן וַ⁠תֹּ֕אמֶר אִם־תִּתֵּ֥ן עֵרָב֖וֹן עַ֥ד שָׁלְחֶֽ⁠ךָ׃","wa⁠yò̇֕ʼmer ʼánòki֛y ʼàşǎlȧ֥ẖ gĕ̇diֽy-ʻizi֖̇ym min-ha⁠ẕò֑̇ʼn wa⁠ţò̇֕ʼmer ʼim-ţi̇ţé֥̇n ʻéráb֖wòn ʻa֥d şá̌lĕẖeֽ⁠ká׃"],[38,18,"וַ⁠יֹּ֗אמֶר מָ֣ה הָֽ⁠עֵרָבוֹן֮ אֲשֶׁ֣ר אֶתֶּן־לָּ⁠ךְ֒ וַ⁠תֹּ֗אמֶר חֹתָֽמְ⁠ךָ֙ וּ⁠פְתִילֶ֔⁠ךָ וּ⁠מַטְּ⁠ךָ֖ אֲשֶׁ֣ר בְּ⁠יָדֶ֑⁠ךָ וַ⁠יִּתֶּן־לָּ֛⁠הּ וַ⁠יָּבֹ֥א אֵלֶ֖י⁠הָ וַ⁠תַּ֥הַר לֽ⁠וֹ׃","wa⁠yò̇֗ʼmer má֣h hֽá⁠ʻérábwòn֮ ʼàşě֣r ʼeţėn-lá̇⁠kĕ֒ wa⁠ţò̇֗ʼmer ẖòţáֽmĕ⁠ká֙ ẇ⁠pĕţiyle֔⁠ká ẇ⁠matĕ̇⁠ká֖ ʼàşě֣r bĕ̇⁠yáde֑⁠ká wa⁠yi̇ţėn-lá֛̇⁠ḣ wa⁠yá̇bò֥ʼ ʼéle֖y⁠há wa⁠ţȧ֥har lֽ⁠wò׃"],[38,19,"וַ⁠תָּ֣קָם וַ⁠תֵּ֔לֶךְ וַ⁠תָּ֥סַר צְעִיפָ֖⁠הּ מֵ⁠עָלֶ֑י⁠הָ וַ⁠תִּלְבַּ֖שׁ בִּגְדֵ֥י אַלְמְנוּתָֽ⁠הּ׃","wa⁠ţá֣̇qám wa⁠ţé̇֔lekĕ wa⁠ţá֥̇sar ẕĕʻiypá֖⁠ḣ mé⁠ʻále֑y⁠há wa⁠ţi̇lĕbȧ֖ş̌ bi̇gĕdé֥y ʼalĕmĕnẇţáֽ⁠ḣ׃"],[38,20,"וַ⁠יִּשְׁלַ֨ח יְהוּדָ֜ה אֶת־גְּדִ֣י הָֽ⁠עִזִּ֗ים בְּ⁠יַד֙ רֵעֵ֣⁠הוּ הָֽ⁠עֲדֻלָּמִ֔י לָ⁠קַ֥חַת הָ⁠עֵרָב֖וֹן מִ⁠יַּ֣ד הָ⁠אִשָּׁ֑ה וְ⁠לֹ֖א מְצָאָֽ⁠הּ׃","wa⁠yi̇şĕ̌la֨ẖ yĕhẇdá֜h ʼeţ-gĕ̇di֣y háֽ⁠ʻizi̇֗ym bĕ̇⁠yad֙ réʻé֣⁠hẇ háֽ⁠ʻàdulá̇mi֔y lá⁠qa֥ẖaţ há⁠ʻéráb֖wòn mi⁠yȧ֣d há⁠ʼişá֑̇̌h wĕ⁠lò֖ʼ mĕẕáʼáֽ⁠ḣ׃"],[38,21,"וַ⁠יִּשְׁאַ֞ל אֶת־אַנְשֵׁ֤י מְקֹמָ⁠הּ֙ לֵ⁠אמֹ֔ר אַיֵּ֧ה הַ⁠קְּדֵשָׁ֛ה הִ֥וא בָ⁠עֵינַ֖יִם עַל־הַ⁠דָּ֑רֶךְ וַ⁠יֹּ֣אמְר֔וּ לֹא־הָיְתָ֥ה בָ⁠זֶ֖ה קְדֵשָֽׁה׃","wa⁠yi̇şĕ̌ʼa֞l ʼeţ-ʼanĕşé֤̌y mĕqòmá⁠ḣ֙ lé⁠ʼmò֔r ʼayé֧̇h ha⁠qĕ̇déşá֛̌h hi֥wʼ bá⁠ʻéyna֖yim ʻal-ha⁠dá֑̇rekĕ wa⁠yò֣̇ʼmĕr֔ẇ lòʼ-háyĕţá֥h bá⁠ze֖h qĕdéşáֽ̌h׃"],[38,22,"וַ⁠יָּ֨שָׁב֙ אֶל־יְהוּדָ֔ה וַ⁠יֹּ֖אמֶר לֹ֣א מְצָאתִ֑י⁠הָ וְ⁠גַ֨ם אַנְשֵׁ֤י הַ⁠מָּקוֹם֙ אָֽמְר֔וּ לֹא־הָיְתָ֥ה בָ⁠זֶ֖ה קְדֵשָֽׁה׃","wa⁠yá̇֨şá̌b֙ ʼel-yĕhẇdá֔h wa⁠yò֖̇ʼmer lò֣ʼ mĕẕáʼţi֑y⁠há wĕ⁠ga֨m ʼanĕşé֤̌y ha⁠má̇qwòm֙ ʼáֽmĕr֔ẇ lòʼ-háyĕţá֥h bá⁠ze֖h qĕdéşáֽ̌h׃"],[38,23,"וַ⁠יֹּ֤אמֶר יְהוּדָה֙ תִּֽקַּֽח־לָ֔⁠הּ פֶּ֖ן נִהְיֶ֣ה לָ⁠ב֑וּז הִנֵּ֤ה שָׁלַ֨חְתִּי֙ הַ⁠גְּדִ֣י הַ⁠זֶּ֔ה וְ⁠אַתָּ֖ה לֹ֥א מְצָאתָֽ⁠הּ׃","wa⁠yò֤̇ʼmer yĕhẇdáh֙ ţiֽ̇qȧֽẖ-lá֔⁠ḣ pė֖n nihĕye֣h lá⁠b֑ẇz hiné֤̇h şá̌la֨ẖĕţi̇y֙ ha⁠gĕ̇di֣y ha⁠zė֔h wĕ⁠ʼaţá֖̇h lò֥ʼ mĕẕáʼţáֽ⁠ḣ׃"],[38,24,"וַ⁠יְהִ֣י ׀ כְּ⁠מִ⁠שְׁלֹ֣שׁ חֳדָשִׁ֗ים וַ⁠יֻּגַּ֨ד לִֽ⁠יהוּדָ֤ה לֵֽ⁠אמֹר֙ זָֽנְתָה֙ תָּמָ֣ר כַּלָּתֶ֔⁠ךָ וְ⁠גַ֛ם הִנֵּ֥ה הָרָ֖ה לִ⁠זְנוּנִ֑ים וַ⁠יֹּ֣אמֶר יְהוּדָ֔ה הוֹצִיא֖וּ⁠הָ וְ⁠תִשָּׂרֵֽף׃","wa⁠yĕhi֣y ׀ kĕ̇⁠mi⁠şĕ̌lò֣ş̌ ẖodáşǐ֗ym wa⁠yu̇gȧ֨d liֽ⁠yhẇdá֤h lֽé⁠ʼmòr֙ záֽnĕţáh֙ ţá̇má֣r kȧlá̇ţe֔⁠ká wĕ⁠ga֛m hiné֥̇h hárá֖h li⁠zĕnẇni֑ym wa⁠yò֣̇ʼmer yĕhẇdá֔h hwòẕiyʼ֖ẇ⁠há wĕ⁠ţişá̇̂réֽp׃"],[38,25,"הִ֣וא מוּצֵ֗את וְ⁠הִ֨יא שָׁלְחָ֤ה אֶל־חָמִ֨י⁠הָ֙ לֵ⁠אמֹ֔ר לְ⁠אִישׁ֙ אֲשֶׁר־אֵ֣לֶּה לּ֔⁠וֹ אָנֹכִ֖י הָרָ֑ה וַ⁠תֹּ֨אמֶר֙ הַכֶּר־נָ֔א לְ⁠מִ֞י הַ⁠חֹתֶ֧מֶת וְ⁠הַ⁠פְּתִילִ֛ים וְ⁠הַ⁠מַּטֶּ֖ה הָ⁠אֵֽלֶּה׃","hi֣wʼ mẇẕé֗ʼţ wĕ⁠hi֨yʼ şá̌lĕẖá֤h ʼel-ẖámi֨y⁠há֙ lé⁠ʼmò֔r lĕ⁠ʼiyş̌֙ ʼàşěr-ʼé֣lėh l̇֔⁠wò ʼánòki֖y hárá֑h wa⁠ţò̇֨ʼmer֙ hakėr-ná֔ʼ lĕ⁠mi֞y ha⁠ẖòţe֧meţ wĕ⁠ha⁠pĕ̇ţiyli֛ym wĕ⁠ha⁠mȧtė֖h há⁠ʼéֽlėh׃"],[38,26,"וַ⁠יַּכֵּ֣ר יְהוּדָ֗ה וַ⁠יֹּ֨אמֶר֙ צָֽדְקָ֣ה מִמֶּ֔⁠נִּי כִּֽי־עַל־כֵּ֥ן לֹא־נְתַתִּ֖י⁠הָ לְ⁠שֵׁלָ֣ה בְנִ֑⁠י וְ⁠לֹֽא־יָסַ֥ף ע֖וֹד לְ⁠דַעְתָּֽ⁠ה׃","wa⁠yȧké֣̇r yĕhẇdá֗h wa⁠yò̇֨ʼmer֙ ẕáֽdĕqá֣h mimė֔⁠ni̇y kiֽ̇y-ʻal-ké֥̇n lòʼ-nĕţaţi֖̇y⁠há lĕ⁠şé̌lá֣h bĕni֑⁠y wĕ⁠lòֽʼ-yása֥p ʻ֖wòd lĕ⁠daʻĕţáֽ̇⁠h׃"],[38,27,"וַ⁠יְהִ֖י בְּ⁠עֵ֣ת לִדְתָּ֑⁠הּ וְ⁠הִנֵּ֥ה תְאוֹמִ֖ים בְּ⁠בִטְנָֽ⁠הּ׃","wa⁠yĕhi֖y bĕ̇⁠ʻé֣ţ lidĕţá֑̇⁠ḣ wĕ⁠hiné֥̇h ţĕʼwòmi֖ym bĕ̇⁠bitĕnáֽ⁠ḣ׃"],[38,28,"וַ⁠יְהִ֥י בְ⁠לִדְתָּ֖⁠הּ וַ⁠יִּתֶּן־יָ֑ד וַ⁠תִּקַּ֣ח הַ⁠מְיַלֶּ֗דֶת וַ⁠תִּקְשֹׁ֨ר עַל־יָד֤⁠וֹ שָׁנִי֙ לֵ⁠אמֹ֔ר זֶ֖ה יָצָ֥א רִאשֹׁנָֽה׃","wa⁠yĕhi֥y bĕ⁠lidĕţá֖̇⁠ḣ wa⁠yi̇ţėn-yá֑d wa⁠ţi̇qȧ֣ẖ ha⁠mĕyalė֗deţ wa⁠ţi̇qĕşò̌֨r ʻal-yád֤⁠wò şá̌niy֙ lé⁠ʼmò֔r ze֖h yáẕá֥ʼ riʼşò̌náֽh׃"],[38,29,"וַ⁠יְהִ֣י ׀ כְּ⁠מֵשִׁ֣יב יָד֗⁠וֹ וְ⁠הִנֵּה֙ יָצָ֣א אָחִ֔י⁠ו וַ⁠תֹּ֕אמֶר מַה־פָּרַ֖צְתָּ עָלֶ֣י⁠ךָ פָּ֑רֶץ וַ⁠יִּקְרָ֥א שְׁמ֖⁠וֹ פָּֽרֶץ׃","wa⁠yĕhi֣y ׀ kĕ̇⁠méşǐ֣yb yád֗⁠wò wĕ⁠hiné̇h֙ yáẕá֣ʼ ʼáẖi֔y⁠w wa⁠ţò̇֕ʼmer mah-pá̇ra֖ẕĕţá̇ ʻále֣y⁠ká pá֑̇reẕ wa⁠yi̇qĕrá֥ʼ şĕ̌m֖⁠wò páֽ̇reẕ׃"],[38,30,"וְ⁠אַחַר֙ יָצָ֣א אָחִ֔י⁠ו אֲשֶׁ֥ר עַל־יָד֖⁠וֹ הַ⁠שָּׁנִ֑י וַ⁠יִּקְרָ֥א שְׁמ֖⁠וֹ זָֽרַח׃ס","wĕ⁠ʼaẖar֙ yáẕá֣ʼ ʼáẖi֔y⁠w ʼàşě֥r ʻal-yád֖⁠wò ha⁠şá̇̌ni֑y wa⁠yi̇qĕrá֥ʼ şĕ̌m֖⁠wò záֽraẖ׃s"],[39,1,"וְ⁠יוֹסֵ֖ף הוּרַ֣ד מִצְרָ֑יְמָ⁠ה וַ⁠יִּקְנֵ֡⁠הוּ פּוֹטִיפַר֩ סְרִ֨יס פַּרְעֹ֜ה שַׂ֤ר הַ⁠טַּבָּחִים֙ אִ֣ישׁ מִצְרִ֔י מִ⁠יַּד֙ הַ⁠יִּשְׁמְעֵאלִ֔ים אֲשֶׁ֥ר הוֹרִדֻ֖⁠הוּ שָֽׁמָּ⁠ה׃","wĕ⁠ywòsé֖p hẇra֣d miẕĕrá֑yĕmá⁠h wa⁠yi̇qĕné֡⁠hẇ ṗwòtiypar֩ sĕri֨ys pȧrĕʻò֜h şâ֤r ha⁠tȧbá̇ẖiym֙ ʼi֣yş̌ miẕĕri֔y mi⁠yȧd֙ ha⁠yi̇şĕ̌mĕʻéʼli֔ym ʼàşě֥r hwòridu֖⁠hẇ şáֽ̌má̇⁠h׃"],[39,2,"וַ⁠יְהִ֤י יְהוָה֙ אֶת־יוֹסֵ֔ף וַ⁠יְהִ֖י אִ֣ישׁ מַצְלִ֑יחַ וַ⁠יְהִ֕י בְּ⁠בֵ֥ית אֲדֹנָ֖י⁠ו הַ⁠מִּצְרִֽי׃","wa⁠yĕhi֤y yĕhwáh֙ ʼeţ-ywòsé֔p wa⁠yĕhi֖y ʼi֣yş̌ maẕĕli֑yẖa wa⁠yĕhi֕y bĕ̇⁠bé֥yţ ʼàdòná֖y⁠w ha⁠mi̇ẕĕriֽy׃"],[39,3,"וַ⁠יַּ֣רְא אֲדֹנָ֔י⁠ו כִּ֥י יְהוָ֖ה אִתּ֑⁠וֹ וְ⁠כֹל֙ אֲשֶׁר־ה֣וּא עֹשֶׂ֔ה יְהוָ֖ה מַצְלִ֥יחַ בְּ⁠יָדֽ⁠וֹ׃","wa⁠yȧ֣rĕʼ ʼàdòná֔y⁠w ki֥̇y yĕhwá֖h ʼiţ֑̇⁠wò wĕ⁠kòl֙ ʼàşěr-h֣ẇʼ ʻòşê֔h yĕhwá֖h maẕĕli֥yẖa bĕ̇⁠yádֽ⁠wò׃"],[39,4,"וַ⁠יִּמְצָ֨א יוֹסֵ֥ף חֵ֛ן בְּ⁠עֵינָ֖י⁠ו וַ⁠יְשָׁ֣רֶת אֹת֑⁠וֹ וַ⁠יַּפְקִדֵ֨⁠הוּ֙ עַל־בֵּית֔⁠וֹ וְ⁠כָל־יֶשׁ־ל֖⁠וֹ נָתַ֥ן בְּ⁠יָדֽ⁠וֹ׃","wa⁠yi̇mĕẕá֨ʼ ywòsé֥p ẖé֛n bĕ̇⁠ʻéyná֖y⁠w wa⁠yĕşá֣̌reţ ʼòţ֑⁠wò wa⁠yȧpĕqidé֨⁠hẇ֙ ʻal-bé̇yţ֔⁠wò wĕ⁠kál-yeş̌-l֖⁠wò náţa֥n bĕ̇⁠yádֽ⁠wò׃"],[39,5,"וַ⁠יְהִ֡י מֵ⁠אָז֩ הִפְקִ֨יד אֹת֜⁠וֹ בְּ⁠בֵית֗⁠וֹ וְ⁠עַל֙ כָּל־אֲשֶׁ֣ר יֶשׁ־ל֔⁠וֹ וַ⁠יְבָ֧רֶךְ יְהוָ֛ה אֶת־בֵּ֥ית הַ⁠מִּצְרִ֖י בִּ⁠גְלַ֣ל יוֹסֵ֑ף וַ⁠יְהִ֞י בִּרְכַּ֤ת יְהוָה֙ בְּ⁠כָל־אֲשֶׁ֣ר יֶשׁ־ל֔⁠וֹ בַּ⁠בַּ֖יִת וּ⁠בַ⁠שָּׂדֶֽה׃","wa⁠yĕhi֡y mé⁠ʼáz֩ hipĕqi֨yd ʼòţ֜⁠wò bĕ̇⁠béyţ֗⁠wò wĕ⁠ʻal֙ ká̇l-ʼàşě֣r yeş̌-l֔⁠wò wa⁠yĕbá֧rekĕ yĕhwá֛h ʼeţ-bé֥̇yţ ha⁠mi̇ẕĕri֖y bi̇⁠gĕla֣l ywòsé֑p wa⁠yĕhi֞y bi̇rĕkȧ֤ţ yĕhwáh֙ bĕ̇⁠kál-ʼàşě֣r yeş̌-l֔⁠wò bȧ⁠bȧ֖yiţ ẇ⁠ba⁠şá̇̂deֽh׃"],[39,6,"וַ⁠יַּעֲזֹ֣ב כָּל־אֲשֶׁר־ל⁠וֹ֮ בְּ⁠יַד־יוֹסֵף֒ וְ⁠לֹא־יָדַ֤ע אִתּ⁠וֹ֙ מְא֔וּמָה כִּ֥י אִם־הַ⁠לֶּ֖חֶם אֲשֶׁר־ה֣וּא אוֹכֵ֑ל וַ⁠יְהִ֣י יוֹסֵ֔ף יְפֵה־תֹ֖אַר וִ⁠יפֵ֥ה מַרְאֶֽה׃","wa⁠yȧʻàzò֣b ká̇l-ʼàşěr-l⁠wò֮ bĕ̇⁠yad-ywòsép֒ wĕ⁠lòʼ-yáda֤ʻ ʼiţ̇⁠wò֙ mĕʼ֔ẇmáh ki֥̇y ʼim-ha⁠lė֖ẖem ʼàşěr-h֣ẇʼ ʼwòké֑l wa⁠yĕhi֣y ywòsé֔p yĕpéh-ţò֖ʼar wi⁠ypé֥h marĕʼeֽh׃"],[39,7,"וַ⁠יְהִ֗י אַחַר֙ הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה וַ⁠תִּשָּׂ֧א אֵֽשֶׁת־אֲדֹנָ֛י⁠ו אֶת־עֵינֶ֖י⁠הָ אֶל־יוֹסֵ֑ף וַ⁠תֹּ֖אמֶר שִׁכְבָ֥⁠ה עִמִּֽ⁠י׃","wa⁠yĕhi֗y ʼaẖar֙ ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh wa⁠ţi̇şá֧̇̂ʼ ʼéֽşěţ-ʼàdòná֛y⁠w ʼeţ-ʻéyne֖y⁠há ʼel-ywòsé֑p wa⁠ţò֖̇ʼmer şǐkĕbá֥⁠h ʻimiֽ̇⁠y׃"],[39,8,"וַ⁠יְמָאֵ֓ן ׀ וַ⁠יֹּ֨אמֶר֙ אֶל־אֵ֣שֶׁת אֲדֹנָ֔י⁠ו הֵ֣ן אֲדֹנִ֔⁠י לֹא־יָדַ֥ע אִתִּ֖⁠י מַה־בַּ⁠בָּ֑יִת וְ⁠כֹ֥ל אֲשֶׁר־יֶשׁ־ל֖⁠וֹ נָתַ֥ן בְּ⁠יָדִֽ⁠י׃","wa⁠yĕmáʼé֓n ׀ wa⁠yò̇֨ʼmer֙ ʼel-ʼé֣şěţ ʼàdòná֔y⁠w hé֣n ʼàdòni֔⁠y lòʼ-yáda֥ʻ ʼiţi֖̇⁠y mah-bȧ⁠bá֑̇yiţ wĕ⁠kò֥l ʼàşěr-yeş̌-l֖⁠wò náţa֥n bĕ̇⁠yádiֽ⁠y׃"],[39,9,"אֵינֶ֨⁠נּוּ גָד֜וֹל בַּ⁠בַּ֣יִת הַ⁠זֶּה֮ מִמֶּ⁠נִּי֒ וְ⁠לֹֽא־חָשַׂ֤ךְ מִמֶּ֨⁠נִּי֙ מְא֔וּמָה כִּ֥י אִם־אוֹתָ֖⁠ךְ בַּ⁠אֲשֶׁ֣ר אַתְּ־אִשְׁתּ֑⁠וֹ וְ⁠אֵ֨יךְ אֶֽעֱשֶׂ֜ה הָ⁠רָעָ֤ה הַ⁠גְּדֹלָה֙ הַ⁠זֹּ֔את וְ⁠חָטָ֖אתִי לֵֽ⁠אלֹהִֽים׃","ʼéyne֨⁠ṅẇ gád֜wòl bȧ⁠bȧ֣yiţ ha⁠zėh֮ mimė⁠ni̇y֒ wĕ⁠lòֽʼ-ẖáşâ֤kĕ mimė֨⁠ni̇y֙ mĕʼ֔ẇmáh ki֥̇y ʼim-ʼwòţá֖⁠kĕ bȧ⁠ʼàşě֣r ʼaţĕ̇-ʼişĕ̌ţ֑̇⁠wò wĕ⁠ʼé֨ykĕ ʼeֽʻèşê֜h há⁠ráʻá֤h ha⁠gĕ̇dòláh֙ ha⁠zò̇֔ʼţ wĕ⁠ẖátá֖ʼţiy léֽ⁠ʼlòhiֽym׃"],[39,10,"וַ⁠יְהִ֕י כְּ⁠דַבְּרָ֥⁠הּ אֶל־יוֹסֵ֖ף י֣וֹם ׀ י֑וֹם וְ⁠לֹא־שָׁמַ֥ע אֵלֶ֛י⁠הָ לִ⁠שְׁכַּ֥ב אֶצְלָ֖⁠הּ לִ⁠הְי֥וֹת עִמָּֽ⁠הּ׃","wa⁠yĕhi֕y kĕ̇⁠dabĕ̇rá֥⁠ḣ ʼel-ywòsé֖p y֣wòm ׀ y֑wòm wĕ⁠lòʼ-şá̌ma֥ʻ ʼéle֛y⁠há li⁠şĕ̌kȧ֥b ʼeẕĕlá֖⁠ḣ li⁠hĕy֥wòţ ʻimáֽ̇⁠ḣ׃"],[39,11,"וַ⁠יְהִי֙ כְּ⁠הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה וַ⁠יָּבֹ֥א הַ⁠בַּ֖יְתָ⁠ה לַ⁠עֲשׂ֣וֹת מְלַאכְתּ֑⁠וֹ וְ⁠אֵ֨ין אִ֜ישׁ מֵ⁠אַנְשֵׁ֥י הַ⁠בַּ֛יִת שָׁ֖ם בַּ⁠בָּֽיִת׃","wa⁠yĕhiy֙ kĕ̇⁠ha⁠ẏ֣wòm ha⁠zė֔h wa⁠yá̇bò֥ʼ ha⁠bȧ֖yĕţá⁠h la⁠ʻàş֣̂wòţ mĕlaʼkĕţ֑̇⁠wò wĕ⁠ʼé֨yn ʼi֜yş̌ mé⁠ʼanĕşé֥̌y ha⁠bȧ֛yiţ şá֖̌m bȧ⁠báֽ̇yiţ׃"],[39,12,"וַ⁠תִּתְפְּשֵׂ֧⁠הוּ בְּ⁠בִגְד֛⁠וֹ לֵ⁠אמֹ֖ר שִׁכְבָ֣⁠ה עִמִּ֑⁠י וַ⁠יַּעֲזֹ֤ב בִּגְד⁠וֹ֙ בְּ⁠יָדָ֔⁠הּ וַ⁠יָּ֖נָס וַ⁠יֵּצֵ֥א הַ⁠חֽוּצָ⁠ה׃","wa⁠ţi̇ţĕpĕ̇şé֧̂⁠hẇ bĕ̇⁠bigĕd֛⁠wò lé⁠ʼmò֖r şǐkĕbá֣⁠h ʻimi֑̇⁠y wa⁠yȧʻàzò֤b bi̇gĕd⁠wò֙ bĕ̇⁠yádá֔⁠ḣ wa⁠yá֖̇nás wa⁠yé̇ẕé֥ʼ ha⁠ẖֽẇẕá⁠h׃"],[39,13,"וַ⁠יְהִי֙ כִּ⁠רְאוֹתָ֔⁠הּ כִּֽי־עָזַ֥ב בִּגְד֖⁠וֹ בְּ⁠יָדָ֑⁠הּ וַ⁠יָּ֖נָס הַ⁠חֽוּצָ⁠ה׃","wa⁠yĕhiy֙ ki̇⁠rĕʼwòţá֔⁠ḣ kiֽ̇y-ʻáza֥b bi̇gĕd֖⁠wò bĕ̇⁠yádá֑⁠ḣ wa⁠yá֖̇nás ha⁠ẖֽẇẕá⁠h׃"],[39,14,"וַ⁠תִּקְרָ֞א לְ⁠אַנְשֵׁ֣י בֵיתָ֗⁠הּ וַ⁠תֹּ֤אמֶר לָ⁠הֶם֙ לֵ⁠אמֹ֔ר רְא֗וּ הֵ֥בִיא לָ֛⁠נוּ אִ֥ישׁ עִבְרִ֖י לְ⁠צַ֣חֶק בָּ֑⁠נוּ בָּ֤א אֵלַ⁠י֙ לִ⁠שְׁכַּ֣ב עִמִּ֔⁠י וָ⁠אֶקְרָ֖א בְּ⁠ק֥וֹל גָּדֽוֹל׃","wa⁠ţi̇qĕrá֞ʼ lĕ⁠ʼanĕşé֣̌y béyţá֗⁠ḣ wa⁠ţò֤̇ʼmer lá⁠hem֙ lé⁠ʼmò֔r rĕʼ֗ẇ hé֥biyʼ lá֛⁠nẇ ʼi֥yş̌ ʻibĕri֖y lĕ⁠ẕa֣ẖeq bá֑̇⁠nẇ bá֤̇ʼ ʼéla⁠y֙ li⁠şĕ̌kȧ֣b ʻimi̇֔⁠y wá⁠ʼeqĕrá֖ʼ bĕ̇⁠q֥wòl gá̇dֽwòl׃"],[39,15,"וַ⁠יְהִ֣י כְ⁠שָׁמְע֔⁠וֹ כִּֽי־הֲרִימֹ֥תִי קוֹלִ֖⁠י וָ⁠אֶקְרָ֑א וַ⁠יַּעֲזֹ֤ב בִּגְד⁠וֹ֙ אֶצְלִ֔⁠י וַ⁠יָּ֖נָס וַ⁠יֵּצֵ֥א הַ⁠חֽוּצָ⁠ה׃","wa⁠yĕhi֣y kĕ⁠şá̌mĕʻ֔⁠wò kiֽ̇y-hàriymò֥ţiy qwòli֖⁠y wá⁠ʼeqĕrá֑ʼ wa⁠yȧʻàzò֤b bi̇gĕd⁠wò֙ ʼeẕĕli֔⁠y wa⁠yá֖̇nás wa⁠yé̇ẕé֥ʼ ha⁠ẖֽẇẕá⁠h׃"],[39,16,"וַ⁠תַּנַּ֥ח בִּגְד֖⁠וֹ אֶצְלָ֑⁠הּ עַד־בּ֥וֹא אֲדֹנָ֖י⁠ו אֶל־בֵּיתֽ⁠וֹ׃","wa⁠ţȧnȧ֥ẖ bi̇gĕd֖⁠wò ʼeẕĕlá֑⁠ḣ ʻad-ḃ֥wòʼ ʼàdòná֖y⁠w ʼel-bé̇yţֽ⁠wò׃"],[39,17,"וַ⁠תְּדַבֵּ֣ר אֵלָ֔י⁠ו כַּ⁠דְּבָרִ֥ים הָ⁠אֵ֖לֶּה לֵ⁠אמֹ֑ר בָּֽא־אֵלַ֞⁠י הָ⁠עֶ֧בֶד הָֽ⁠עִבְרִ֛י אֲשֶׁר־הֵבֵ֥אתָ לָּ֖⁠נוּ לְ⁠צַ֥חֶק בִּֽ⁠י׃","wa⁠ţĕ̇dabé֣̇r ʼélá֔y⁠w kȧ⁠dĕ̇bári֥ym há⁠ʼé֖lėh lé⁠ʼmò֑r báֽ̇ʼ-ʼéla֞⁠y há⁠ʻe֧bed háֽ⁠ʻibĕri֛y ʼàşěr-hébé֥ʼţá lá֖̇⁠nẇ lĕ⁠ẕa֥ẖeq biֽ̇⁠y׃"],[39,18,"וַ⁠יְהִ֕י כַּ⁠הֲרִימִ֥⁠י קוֹלִ֖⁠י וָ⁠אֶקְרָ֑א וַ⁠יַּעֲזֹ֥ב בִּגְד֛⁠וֹ אֶצְלִ֖⁠י וַ⁠יָּ֥נָס הַ⁠חֽוּצָ⁠ה׃","wa⁠yĕhi֕y kȧ⁠hàriymi֥⁠y qwòli֖⁠y wá⁠ʼeqĕrá֑ʼ wa⁠yȧʻàzò֥b bi̇gĕd֛⁠wò ʼeẕĕli֖⁠y wa⁠yá֥̇nás ha⁠ẖֽẇẕá⁠h׃"],[39,19,"וַ⁠יְהִי֩ כִ⁠שְׁמֹ֨עַ אֲדֹנָ֜י⁠ו אֶת־דִּבְרֵ֣י אִשְׁתּ֗⁠וֹ אֲשֶׁ֨ר דִּבְּרָ֤ה אֵלָי⁠ו֙ לֵ⁠אמֹ֔ר כַּ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה עָ֥שָׂהּ לִ֖⁠י עַבְדֶּ֑⁠ךָ וַ⁠יִּ֖חַר אַפּֽ⁠וֹ׃","wa⁠yĕhiy֩ ki⁠şĕ̌mò֨ʻa ʼàdòná֜y⁠w ʼeţ-di̇bĕré֣y ʼişĕ̌ţ̇֗⁠wò ʼàşě֨r di̇bĕ̇rá֤h ʼéláy⁠w֙ lé⁠ʼmò֔r kȧ⁠dĕ̇bári֣ym há⁠ʼé֔lėh ʻá֥şá̂ḣ li֖⁠y ʻabĕdė֑⁠ká wa⁠yi֖̇ẖar ʼaṗֽ⁠wò׃"],[39,20,"וַ⁠יִּקַּח֩ אֲדֹנֵ֨י יוֹסֵ֜ף אֹת֗⁠וֹ וַֽ⁠יִּתְּנֵ֨⁠הוּ֙ אֶל־בֵּ֣ית הַ⁠סֹּ֔הַר מְק֕וֹם אֲשֶׁר־אסורי הַ⁠מֶּ֖לֶךְ אֲסוּרִ֑ים וַֽ⁠יְהִי־שָׁ֖ם בְּ⁠בֵ֥ית הַ⁠סֹּֽהַר׃","wa⁠yi̇qȧẖ֩ ʼàdòné֨y ywòsé֜p ʼòţ֗⁠wò waֽ⁠yi̇ţĕ̇né֨⁠hẇ֙ ʼel-bé֣̇yţ ha⁠sò̇֔har mĕq֕wòm ʼàşěr-ʼswry ha⁠mė֖lekĕ ʼàsẇri֑ym wֽa⁠yĕhiy-şá֖̌m bĕ̇⁠bé֥yţ ha⁠sòֽ̇har׃"],[39,21,"וַ⁠יְהִ֤י יְהוָה֙ אֶת־יוֹסֵ֔ף וַ⁠יֵּ֥ט אֵלָ֖י⁠ו חָ֑סֶד וַ⁠יִּתֵּ֣ן חִנּ֔⁠וֹ בְּ⁠עֵינֵ֖י שַׂ֥ר בֵּית־הַ⁠סֹּֽהַר׃","wa⁠yĕhi֤y yĕhwáh֙ ʼeţ-ywòsé֔p wa⁠yé֥̇t ʼélá֖y⁠w ẖá֑sed wa⁠yi̇ţé֣̇n ẖiṅ֔⁠wò bĕ̇⁠ʻéyné֖y şâ֥r bé̇yţ-ha⁠sòֽ̇har׃"],[39,22,"וַ⁠יִּתֵּ֞ן שַׂ֤ר בֵּית־הַ⁠סֹּ֨הַר֙ בְּ⁠יַד־יוֹסֵ֔ף אֵ֚ת כָּל־הָ֣⁠אֲסִירִ֔ם אֲשֶׁ֖ר בְּ⁠בֵ֣ית הַ⁠סֹּ֑הַר וְ⁠אֵ֨ת כָּל־אֲשֶׁ֤ר עֹשִׂים֙ שָׁ֔ם ה֖וּא הָיָ֥ה עֹשֶֽׂה׃","wa⁠yi̇ţé̇֞n şâ֤r bé̇yţ-ha⁠sò̇֨har֙ bĕ̇⁠yad-ywòsé֔p ʼé֚ţ ká̇l-há֣⁠ʼàsiyri֔m ʼàşě֖r bĕ̇⁠bé֣yţ ha⁠sò֑̇har wĕ⁠ʼé֨ţ ká̇l-ʼàşě֤r ʻòşîym֙ şá̌֔m h֖ẇʼ háyá֥h ʻòşêֽh׃"],[39,23,"אֵ֣ין ׀ שַׂ֣ר בֵּית־הַ⁠סֹּ֗הַר רֹאֶ֤ה אֶֽת־כָּל־מְא֨וּמָה֙ בְּ⁠יָד֔⁠וֹ בַּ⁠אֲשֶׁ֥ר יְהוָ֖ה אִתּ֑⁠וֹ וַֽ⁠אֲשֶׁר־ה֥וּא עֹשֶׂ֖ה יְהוָ֥ה מַצְלִֽיחַ׃ס","ʼé֣yn ׀ şâ֣r bé̇yţ-ha⁠sò̇֗har ròʼe֤h ʼeֽţ-ká̇l-mĕʼ֨ẇmáh֙ bĕ̇⁠yád֔⁠wò bȧ⁠ʼàşě֥r yĕhwá֖h ʼiţ֑̇⁠wò waֽ⁠ʼàşěr-h֥ẇʼ ʻòşê֖h yĕhwá֥h maẕĕliֽyẖa׃s"],[40,1,"וַ⁠יְהִ֗י אַחַר֙ הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה חָֽטְא֛וּ מַשְׁקֵ֥ה מֶֽלֶךְ־מִצְרַ֖יִם וְ⁠הָ⁠אֹפֶ֑ה לַ⁠אֲדֹנֵי⁠הֶ֖ם לְ⁠מֶ֥לֶךְ מִצְרָֽיִם׃","wa⁠yĕhi֗y ʼaẖar֙ ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh ẖáֽtĕʼ֛ẇ maşĕ̌qé֥h meֽlekĕ-miẕĕra֖yim wĕ⁠há⁠ʼòpe֑h la⁠ʼàdònéy⁠he֖m lĕ⁠me֥lekĕ miẕĕráֽyim׃"],[40,2,"וַ⁠יִּקְצֹ֣ף פַּרְעֹ֔ה עַ֖ל שְׁנֵ֣י סָרִיסָ֑י⁠ו עַ֚ל שַׂ֣ר הַ⁠מַּשְׁקִ֔ים וְ⁠עַ֖ל שַׂ֥ר הָ⁠אוֹפִֽים׃","wa⁠yi̇qĕẕò֣p pȧrĕʻò֔h ʻa֖l şĕ̌né֣y sáriysá֑y⁠w ʻa֚l şâ֣r ha⁠mȧşĕ̌qi֔ym wĕ⁠ʻa֖l şâ֥r há⁠ʼwòpiֽym׃"],[40,3,"וַ⁠יִּתֵּ֨ן אֹתָ֜⁠ם בְּ⁠מִשְׁמַ֗ר בֵּ֛ית שַׂ֥ר הַ⁠טַבָּחִ֖ים אֶל־בֵּ֣ית הַ⁠סֹּ֑הַר מְק֕וֹם אֲשֶׁ֥ר יוֹסֵ֖ף אָס֥וּר שָֽׁם׃","wa⁠yi̇ţé̇֨n ʼòţá֜⁠m bĕ̇⁠mişĕ̌ma֗r bé֛̇yţ şâ֥r ha⁠tabá̇ẖi֖ym ʼel-bé֣̇yţ ha⁠sò֑̇har mĕq֕wòm ʼàşě֥r ywòsé֖p ʼás֥ẇr şáֽ̌m׃"],[40,4,"וַ֠⁠יִּפְקֹד שַׂ֣ר הַ⁠טַּבָּחִ֧ים אֶת־יוֹסֵ֛ף אִתָּ֖⁠ם וַ⁠יְשָׁ֣רֶת אֹתָ֑⁠ם וַ⁠יִּהְי֥וּ יָמִ֖ים בְּ⁠מִשְׁמָֽר׃","wa֠⁠yi̇pĕqòd şâ֣r ha⁠tȧbá̇ẖi֧ym ʼeţ-ywòsé֛p ʼiţá֖̇⁠m wa⁠yĕşá֣̌reţ ʼòţá֑⁠m wa⁠yi̇hĕy֥ẇ yámi֖ym bĕ̇⁠mişĕ̌máֽr׃"],[40,5,"וַ⁠יַּֽחַלְמוּ֩ חֲל֨וֹם שְׁנֵי⁠הֶ֜ם אִ֤ישׁ חֲלֹמ⁠וֹ֙ בְּ⁠לַ֣יְלָה אֶחָ֔ד אִ֖ישׁ כְּ⁠פִתְר֣וֹן חֲלֹמ֑⁠וֹ הַ⁠מַּשְׁקֶ֣ה וְ⁠הָ⁠אֹפֶ֗ה אֲשֶׁר֙ לְ⁠מֶ֣לֶךְ מִצְרַ֔יִם אֲשֶׁ֥ר אֲסוּרִ֖ים בְּ⁠בֵ֥ית הַ⁠סֹּֽהַר׃","wa⁠yȧֽẖalĕmẇ֩ ẖàl֨wòm şĕ̌néy⁠he֜m ʼi֤yş̌ ẖàlòm⁠wò֙ bĕ̇⁠la֣yĕláh ʼeẖá֔d ʼi֖yş̌ kĕ̇⁠piţĕr֣wòn ẖàlòm֑⁠wò ha⁠mȧşĕ̌qe֣h wĕ⁠há⁠ʼòpe֗h ʼàşěr֙ lĕ⁠me֣lekĕ miẕĕra֔yim ʼàşě֥r ʼàsẇri֖ym bĕ̇⁠bé֥yţ ha⁠sòֽ̇har׃"],[40,6,"וַ⁠יָּבֹ֧א אֲלֵי⁠הֶ֛ם יוֹסֵ֖ף בַּ⁠בֹּ֑קֶר וַ⁠יַּ֣רְא אֹתָ֔⁠ם וְ⁠הִנָּ֖⁠ם זֹעֲפִֽים׃","wa⁠yá̇bò֧ʼ ʼàléy⁠he֛m ywòsé֖p bȧ⁠bò֑̇qer wa⁠yȧ֣rĕʼ ʼòţá֔⁠m wĕ⁠hiná֖̇⁠m zòʻàpiֽym׃"],[40,7,"וַ⁠יִּשְׁאַ֞ל אֶת־סְרִיסֵ֣י פַרְעֹ֗ה אֲשֶׁ֨ר אִתּ֧⁠וֹ בְ⁠מִשְׁמַ֛ר בֵּ֥ית אֲדֹנָ֖י⁠ו לֵ⁠אמֹ֑ר מַדּ֛וּעַ פְּנֵי⁠כֶ֥ם רָעִ֖ים הַ⁠יּֽוֹם׃","wa⁠yi̇şĕ̌ʼa֞l ʼeţ-sĕriysé֣y parĕʻò֗h ʼàşě֨r ʼiţ֧̇⁠wò bĕ⁠mişĕ̌ma֛r bé֥̇yţ ʼàdòná֖y⁠w lé⁠ʼmò֑r maḋ֛ẇʻa pĕ̇néy⁠ke֥m ráʻi֖ym ha⁠ẏֽwòm׃"],[40,8,"וַ⁠יֹּאמְר֣וּ אֵלָ֔י⁠ו חֲל֣וֹם חָלַ֔מְנוּ וּ⁠פֹתֵ֖ר אֵ֣ין אֹת֑⁠וֹ וַ⁠יֹּ֨אמֶר אֲלֵ⁠הֶ֜ם יוֹסֵ֗ף הֲ⁠ל֤וֹא לֵֽ⁠אלֹהִים֙ פִּתְרֹנִ֔ים סַפְּרוּ־נָ֖א לִֽ⁠י׃","wa⁠yò̇ʼmĕr֣ẇ ʼélá֔y⁠w ẖàl֣wòm ẖála֔mĕnẇ ẇ⁠pòţé֖r ʼé֣yn ʼòţ֑⁠wò wa⁠yò̇֨ʼmer ʼàlé⁠he֜m ywòsé֗p hà⁠l֤wòʼ lֽé⁠ʼlòhiym֙ pi̇ţĕròni֔ym sapĕ̇rẇ-ná֖ʼ liֽ⁠y׃"],[40,9,"וַ⁠יְסַפֵּ֧ר שַֽׂר־הַ⁠מַּשְׁקִ֛ים אֶת־חֲלֹמ֖⁠וֹ לְ⁠יוֹסֵ֑ף וַ⁠יֹּ֣אמֶר ל֔⁠וֹ בַּ⁠חֲלוֹמִ֕⁠י וְ⁠הִנֵּה־גֶ֖פֶן לְ⁠פָנָֽ⁠י׃","wa⁠yĕsapé֧̇r şâֽr-ha⁠mȧşĕ̌qi֛ym ʼeţ-ẖàlòm֖⁠wò lĕ⁠ywòsé֑p wa⁠yò֣̇ʼmer l֔⁠wò bȧ⁠ẖàlwòmi֕⁠y wĕ⁠hiné̇h-ge֖pen lĕ⁠pánáֽ⁠y׃"],[40,10,"וּ⁠בַ⁠גֶּ֖פֶן שְׁלֹשָׁ֣ה שָׂרִיגִ֑ם וְ⁠הִ֤יא כְ⁠פֹרַ֨חַת֙ עָלְתָ֣ה נִצָּ֔⁠הּ הִבְשִׁ֥ילוּ אַשְׁכְּלֹתֶ֖י⁠הָ עֲנָבִֽים׃","ẇ⁠ba⁠gė֖pen şĕ̌lòşá֣̌h şá̂riygi֑m wĕ⁠hi֤yʼ kĕ⁠pòra֨ẖaţ֙ ʻálĕţá֣h niẕá̇֔⁠ḣ hibĕşǐ֥ylẇ ʼaşĕ̌kĕ̇lòţe֖y⁠há ʻànábiֽym׃"],[40,11,"וְ⁠כ֥וֹס פַּרְעֹ֖ה בְּ⁠יָדִ֑⁠י וָ⁠אֶקַּ֣ח אֶת־הָֽ⁠עֲנָבִ֗ים וָֽ⁠אֶשְׂחַ֤ט אֹתָ⁠ם֙ אֶל־כּ֣וֹס פַּרְעֹ֔ה וָ⁠אֶתֵּ֥ן אֶת־הַ⁠כּ֖וֹס עַל־כַּ֥ף פַּרְעֹֽה׃","wĕ⁠k֥wòs pȧrĕʻò֖h bĕ̇⁠yádi֑⁠y wá⁠ʼeqȧ֣ẖ ʼeţ-háֽ⁠ʻànábi֗ym wáֽ⁠ʼeşĕ̂ẖa֤t ʼòţá⁠m֙ ʼel-k֣̇wòs pȧrĕʻò֔h wá⁠ʼeţé֥̇n ʼeţ-ha⁠k֖̇wòs ʻal-kȧ֥p pȧrĕʻòֽh׃"],[40,12,"וַ⁠יֹּ֤אמֶר ל⁠וֹ֙ יוֹסֵ֔ף זֶ֖ה פִּתְרֹנ֑⁠וֹ שְׁלֹ֨שֶׁת֙ הַ⁠שָּׂ֣רִגִ֔ים שְׁלֹ֥שֶׁת יָמִ֖ים הֵֽם׃","wa⁠yò֤̇ʼmer l⁠wò֙ ywòsé֔p ze֖h pi̇ţĕròn֑⁠wò şĕ̌lò֨şěţ֙ ha⁠şá֣̇̂rigi֔ym şĕ̌lò֥şěţ yámi֖ym héֽm׃"],[40,13,"בְּ⁠ע֣וֹד ׀ שְׁלֹ֣שֶׁת יָמִ֗ים יִשָּׂ֤א פַרְעֹה֙ אֶת־רֹאשֶׁ֔⁠ךָ וַ⁠הֲשִֽׁיבְ⁠ךָ֖ עַל־כַּנֶּ֑⁠ךָ וְ⁠נָתַתָּ֤ כוֹס־פַּרְעֹה֙ בְּ⁠יָד֔⁠וֹ כַּ⁠מִּשְׁפָּט֙ הָֽ⁠רִאשׁ֔וֹן אֲשֶׁ֥ר הָיִ֖יתָ מַשְׁקֵֽ⁠הוּ׃","bĕ̇⁠ʻ֣wòd ׀ şĕ̌lò֣şěţ yámi֗ym yişá֤̇̂ʼ parĕʻòh֙ ʼeţ-ròʼşě֔⁠ká wa⁠hàşǐֽybĕ⁠ká֖ ʻal-kȧnė֑⁠ká wĕ⁠náţaţá֤̇ kwòs-pȧrĕʻòh֙ bĕ̇⁠yád֔⁠wò kȧ⁠mi̇şĕ̌pá̇t֙ háֽ⁠riʼş̌֔wòn ʼàşě֥r háyi֖yţá maşĕ̌qéֽ⁠hẇ׃"],[40,14,"כִּ֧י אִם־זְכַרְתַּ֣⁠נִי אִתְּ⁠ךָ֗ כַּ⁠אֲשֶׁר֙ יִ֣יטַב לָ֔⁠ךְ וְ⁠עָשִֽׂיתָ־נָּ֥א עִמָּדִ֖⁠י חָ֑סֶד וְ⁠הִזְכַּרְתַּ֨⁠נִי֙ אֶל־פַּרְעֹ֔ה וְ⁠הוֹצֵאתַ֖⁠נִי מִן־הַ⁠בַּ֥יִת הַ⁠זֶּֽה׃","ki֧̇y ʼim-zĕkarĕţȧ֣⁠niy ʼiţĕ̇⁠ká֗ kȧ⁠ʼàşěr֙ yi֣ytab lá֔⁠kĕ wĕ⁠ʻáşîֽyţá-ná֥̇ʼ ʻimá̇di֖⁠y ẖá֑sed wĕ⁠hizĕkȧrĕţȧ֨⁠niy֙ ʼel-pȧrĕʻò֔h wĕ⁠hwòẕéʼţa֖⁠niy min-ha⁠bȧ֥yiţ ha⁠zėֽh׃"],[40,15,"כִּֽי־גֻנֹּ֣ב גֻּנַּ֔בְתִּי מֵ⁠אֶ֖רֶץ הָ⁠עִבְרִ֑ים וְ⁠גַם־פֹּה֙ לֹא־עָשִׂ֣יתִֽי מְא֔וּמָה כִּֽי־שָׂמ֥וּ אֹתִ֖⁠י בַּ⁠בּֽוֹר׃","kiֽ̇y-gunò֣̇b gu̇nȧ֔bĕţi̇y mé⁠ʼe֖reẕ há⁠ʻibĕri֑ym wĕ⁠gam-pò̇h֙ lòʼ-ʻáşî֣yţiֽy mĕʼ֔ẇmáh kiֽ̇y-şá̂m֥ẇ ʼòţi֖⁠y bȧ⁠ḃֽwòr׃"],[40,16,"וַ⁠יַּ֥רְא שַׂר־הָ⁠אֹפִ֖ים כִּ֣י ט֣וֹב פָּתָ֑ר וַ⁠יֹּ֨אמֶר֙ אֶל־יוֹסֵ֔ף אַף־אֲנִי֙ בַּ⁠חֲלוֹמִ֔⁠י וְ⁠הִנֵּ֗ה שְׁלֹשָׁ֛ה סַלֵּ֥י חֹרִ֖י עַל־רֹאשִֽׁ⁠י׃","wa⁠yȧ֥rĕʼ şâr-há⁠ʼòpi֖ym ki֣̇y t֣wòb pá̇ţá֑r wa⁠yò̇֨ʼmer֙ ʼel-ywòsé֔p ʼap-ʼàniy֙ bȧ⁠ẖàlwòmi֔⁠y wĕ⁠hiné̇֗h şĕ̌lòşá֛̌h salé֥̇y ẖòri֖y ʻal-ròʼşǐֽ⁠y׃"],[40,17,"וּ⁠בַ⁠סַּ֣ל הָֽ⁠עֶלְי֔וֹן מִ⁠כֹּ֛ל מַאֲכַ֥ל פַּרְעֹ֖ה מַעֲשֵׂ֣ה אֹפֶ֑ה וְ⁠הָ⁠ע֗וֹף אֹכֵ֥ל אֹתָ֛⁠ם מִן־הַ⁠סַּ֖ל מֵ⁠עַ֥ל רֹאשִֽׁ⁠י׃","ẇ⁠ba⁠sȧ֣l háֽ⁠ʻelĕy֔wòn mi⁠kò֛̇l maʼàka֥l pȧrĕʻò֖h maʻàşé֣̂h ʼòpe֑h wĕ⁠há⁠ʻ֗wòp ʼòké֥l ʼòţá֛⁠m min-ha⁠sȧ֖l mé⁠ʻa֥l ròʼşǐֽ⁠y׃"],[40,18,"וַ⁠יַּ֤עַן יוֹסֵף֙ וַ⁠יֹּ֔אמֶר זֶ֖ה פִּתְרֹנ֑⁠וֹ שְׁלֹ֨שֶׁת֙ הַ⁠סַּלִּ֔ים שְׁלֹ֥שֶׁת יָמִ֖ים הֵֽם׃","wa⁠yȧ֤ʻan ywòsép֙ wa⁠yò̇֔ʼmer ze֖h pi̇ţĕròn֑⁠wò şĕ̌lò֨şěţ֙ ha⁠sȧli̇֔ym şĕ̌lò֥şěţ yámi֖ym héֽm׃"],[40,19,"בְּ⁠ע֣וֹד ׀ שְׁלֹ֣שֶׁת יָמִ֗ים יִשָּׂ֨א פַרְעֹ֤ה אֶת־רֹֽאשְׁ⁠ךָ֙ מֵֽ⁠עָלֶ֔י⁠ךָ וְ⁠תָלָ֥ה אוֹתְ⁠ךָ֖ עַל־עֵ֑ץ וְ⁠אָכַ֥ל הָ⁠ע֛וֹף אֶת־בְּשָׂרְ⁠ךָ֖ מֵ⁠עָלֶֽי⁠ךָ׃","bĕ̇⁠ʻ֣wòd ׀ şĕ̌lò֣şěţ yámi֗ym yişá̇̂֨ʼ parĕʻò֤h ʼeţ-ròֽʼşĕ̌⁠ká֙ méֽ⁠ʻále֔y⁠ká wĕ⁠ţálá֥h ʼwòţĕ⁠ká֖ ʻal-ʻé֑ẕ wĕ⁠ʼáka֥l há⁠ʻ֛wòp ʼeţ-bĕ̇şá̂rĕ⁠ká֖ mé⁠ʻáleֽy⁠ká׃"],[40,20,"וַ⁠יְהִ֣י ׀ בַּ⁠יּ֣וֹם הַ⁠שְּׁלִישִׁ֗י י֚וֹם הֻלֶּ֣דֶת אֶת־פַּרְעֹ֔ה וַ⁠יַּ֥עַשׂ מִשְׁתֶּ֖ה לְ⁠כָל־עֲבָדָ֑י⁠ו וַ⁠יִּשָּׂ֞א אֶת־רֹ֣אשׁ ׀ שַׂ֣ר הַ⁠מַּשְׁקִ֗ים וְ⁠אֶת־רֹ֛אשׁ שַׂ֥ר הָ⁠אֹפִ֖ים בְּ⁠ת֥וֹךְ עֲבָדָֽי⁠ו׃","wa⁠yĕhi֣y ׀ bȧ⁠ẏ֣wòm ha⁠şĕ̇̌liyşǐ֗y y֚wòm hulė֣deţ ʼeţ-pȧrĕʻò֔h wa⁠yȧ֥ʻaş̂ mişĕ̌ţė֖h lĕ⁠kál-ʻàbádá֑y⁠w wa⁠yi̇şá̇̂֞ʼ ʼeţ-rò֣ʼş̌ ׀ şâ֣r ha⁠mȧşĕ̌qi֗ym wĕ⁠ʼeţ-rò֛ʼş̌ şâ֥r há⁠ʼòpi֖ym bĕ̇⁠ţ֥wòkĕ ʻàbádáֽy⁠w׃"],[40,21,"וַ⁠יָּ֛שֶׁב אֶת־שַׂ֥ר הַ⁠מַּשְׁקִ֖ים עַל־מַשְׁקֵ֑⁠הוּ וַ⁠יִּתֵּ֥ן הַ⁠כּ֖וֹס עַל־כַּ֥ף פַּרְעֹֽה׃","wa⁠yá֛̇şěb ʼeţ-şâ֥r ha⁠mȧşĕ̌qi֖ym ʻal-maşĕ̌qé֑⁠hẇ wa⁠yi̇ţé֥̇n ha⁠k֖̇wòs ʻal-kȧ֥p pȧrĕʻòֽh׃"],[40,22,"וְ⁠אֵ֛ת שַׂ֥ר הָ⁠אֹפִ֖ים תָּלָ֑ה כַּ⁠אֲשֶׁ֥ר פָּתַ֛ר לָ⁠הֶ֖ם יוֹסֵֽף׃","wĕ⁠ʼé֛ţ şâ֥r há⁠ʼòpi֖ym ţá̇lá֑h kȧ⁠ʼàşě֥r pá̇ţa֛r lá⁠he֖m ywòséֽp׃"],[40,23,"וְ⁠לֹֽא־זָכַ֧ר שַֽׂר־הַ⁠מַּשְׁקִ֛ים אֶת־יוֹסֵ֖ף וַ⁠יִּשְׁכָּחֵֽ⁠הוּ׃פ","wĕ⁠lòֽʼ-záka֧r şâֽr-ha⁠mȧşĕ̌qi֛ym ʼeţ-ywòsé֖p wa⁠yi̇şĕ̌ká̇ẖéֽ⁠hẇ׃p"],[41,1,"וַ⁠יְהִ֕י מִ⁠קֵּ֖ץ שְׁנָתַ֣יִם יָמִ֑ים וּ⁠פַרְעֹ֣ה חֹלֵ֔ם וְ⁠הִנֵּ֖ה עֹמֵ֥ד עַל־הַ⁠יְאֹֽר׃","wa⁠yĕhi֕y mi⁠qé֖̇ẕ şĕ̌náţa֣yim yámi֑ym ẇ⁠parĕʻò֣h ẖòlé֔m wĕ⁠hiné֖̇h ʻòmé֥d ʻal-ha⁠yĕʼòֽr׃"],[41,2,"וְ⁠הִנֵּ֣ה מִן־הַ⁠יְאֹ֗ר עֹלֹת֙ שֶׁ֣בַע פָּר֔וֹת יְפ֥וֹת מַרְאֶ֖ה וּ⁠בְרִיאֹ֣ת בָּשָׂ֑ר וַ⁠תִּרְעֶ֖ינָה בָּ⁠אָֽחוּ׃","wĕ⁠hiné֣̇h min-ha⁠yĕʼò֗r ʻòlòţ֙ şě֣baʻ pá̇r֔wòţ yĕp֥wòţ marĕʼe֖h ẇ⁠bĕriyʼò֣ţ bá̇şá֑̂r wa⁠ţi̇rĕʻe֖ynáh bá̇⁠ʼáֽẖẇ׃"],[41,3,"וְ⁠הִנֵּ֞ה שֶׁ֧בַע פָּר֣וֹת אֲחֵר֗וֹת עֹל֤וֹת אַחֲרֵי⁠הֶן֙ מִן־הַ⁠יְאֹ֔ר רָע֥וֹת מַרְאֶ֖ה וְ⁠דַקּ֣וֹת בָּשָׂ֑ר וַֽ⁠תַּעֲמֹ֛דְנָה אֵ֥צֶל הַ⁠פָּר֖וֹת עַל־שְׂפַ֥ת הַ⁠יְאֹֽר׃","wĕ⁠hiné̇֞h şě֧baʻ pá̇r֣wòţ ʼàẖér֗wòţ ʻòl֤wòţ ʼaẖàréy⁠hen֙ min-ha⁠yĕʼò֔r ráʻ֥wòţ marĕʼe֖h wĕ⁠daq֣̇wòţ bá̇şá֑̂r waֽ⁠ţȧʻàmò֛dĕnáh ʼé֥ẕel ha⁠pá̇r֖wòţ ʻal-şĕ̂pa֥ţ ha⁠yĕʼòֽr׃"],[41,4,"וַ⁠תֹּאכַ֣לְנָה הַ⁠פָּר֗וֹת רָע֤וֹת הַ⁠מַּרְאֶה֙ וְ⁠דַקֹּ֣ת הַ⁠בָּשָׂ֔ר אֵ֚ת שֶׁ֣בַע הַ⁠פָּר֔וֹת יְפֹ֥ת הַ⁠מַּרְאֶ֖ה וְ⁠הַ⁠בְּרִיאֹ֑ת וַ⁠יִּיקַ֖ץ פַּרְעֹֽה׃","wa⁠ţò̇ʼka֣lĕnáh ha⁠pá̇r֗wòţ ráʻ֤wòţ ha⁠mȧrĕʼeh֙ wĕ⁠daqò֣̇ţ ha⁠bá̇şá̂֔r ʼé֚ţ şě֣baʻ ha⁠pá̇r֔wòţ yĕpò֥ţ ha⁠mȧrĕʼe֖h wĕ⁠ha⁠bĕ̇riyʼò֑ţ wa⁠yi̇yqa֖ẕ pȧrĕʻòֽh׃"],[41,5,"וַ⁠יִּישָׁ֕ן וַֽ⁠יַּחֲלֹ֖ם שֵׁנִ֑ית וְ⁠הִנֵּ֣ה ׀ שֶׁ֣בַע שִׁבֳּלִ֗ים עֹל֛וֹת בְּ⁠קָנֶ֥ה אֶחָ֖ד בְּרִיא֥וֹת וְ⁠טֹבֽוֹת׃","wa⁠yi̇yşá̌֕n waֽ⁠yȧẖàlò֖m şé̌ni֑yţ wĕ⁠hiné֣̇h ׀ şě֣baʻ şǐbȯli֗ym ʻòl֛wòţ bĕ̇⁠qáne֥h ʼeẖá֖d bĕ̇riyʼ֥wòţ wĕ⁠tòbֽwòţ׃"],[41,6,"וְ⁠הִנֵּה֙ שֶׁ֣בַע שִׁבֳּלִ֔ים דַּקּ֖וֹת וּ⁠שְׁדוּפֹ֣ת קָדִ֑ים צֹמְח֖וֹת אַחֲרֵי⁠הֶֽן׃","wĕ⁠hiné̇h֙ şě֣baʻ şǐbȯli֔ym dȧq֖̇wòţ ẇ⁠şĕ̌dẇpò֣ţ qádi֑ym ẕòmĕẖ֖wòţ ʼaẖàréy⁠heֽn׃"],[41,7,"וַ⁠תִּבְלַ֨עְנָה֙ הַ⁠שִּׁבֳּלִ֣ים הַ⁠דַּקּ֔וֹת אֵ֚ת שֶׁ֣בַע הַֽ⁠שִּׁבֳּלִ֔ים הַ⁠בְּרִיא֖וֹת וְ⁠הַ⁠מְּלֵא֑וֹת וַ⁠יִּיקַ֥ץ פַּרְעֹ֖ה וְ⁠הִנֵּ֥ה חֲלֽוֹם׃","wa⁠ţi̇bĕla֨ʻĕnáh֙ ha⁠şi̇̌bȯli֣ym ha⁠dȧq̇֔wòţ ʼé֚ţ şě֣baʻ haֽ⁠şi̇̌bȯli֔ym ha⁠bĕ̇riyʼ֖wòţ wĕ⁠ha⁠mĕ̇léʼ֑wòţ wa⁠yi̇yqa֥ẕ pȧrĕʻò֖h wĕ⁠hiné֥̇h ẖàlֽwòm׃"],[41,8,"וַ⁠יְהִ֤י בַ⁠בֹּ֨קֶר֙ וַ⁠תִּפָּ֣עֶם רוּח֔⁠וֹ וַ⁠יִּשְׁלַ֗ח וַ⁠יִּקְרָ֛א אֶת־כָּל־חַרְטֻמֵּ֥י מִצְרַ֖יִם וְ⁠אֶת־כָּל־חֲכָמֶ֑י⁠הָ וַ⁠יְסַפֵּ֨ר פַּרְעֹ֤ה לָ⁠הֶם֙ אֶת־חֲלֹמ֔⁠וֹ וְ⁠אֵין־פּוֹתֵ֥ר אוֹתָ֖⁠ם לְ⁠פַרְעֹֽה׃","wa⁠yĕhi֤y ba⁠bò̇֨qer֙ wa⁠ţi̇pá֣̇ʻem rẇẖ֔⁠wò wa⁠yi̇şĕ̌la֗ẖ wa⁠yi̇qĕrá֛ʼ ʼeţ-ká̇l-ẖarĕtumé֥̇y miẕĕra֖yim wĕ⁠ʼeţ-ká̇l-ẖàkáme֑y⁠há wa⁠yĕsapé̇֨r pȧrĕʻò֤h lá⁠hem֙ ʼeţ-ẖàlòm֔⁠wò wĕ⁠ʼéyn-ṗwòţé֥r ʼwòţá֖⁠m lĕ⁠parĕʻòֽh׃"],[41,9,"וַ⁠יְדַבֵּר֙ שַׂ֣ר הַ⁠מַּשְׁקִ֔ים אֶת־פַּרְעֹ֖ה לֵ⁠אמֹ֑ר אֶת־חֲטָאַ֕⁠י אֲנִ֖י מַזְכִּ֥יר הַ⁠יּֽוֹם׃","wa⁠yĕdabé̇r֙ şâ֣r ha⁠mȧşĕ̌qi֔ym ʼeţ-pȧrĕʻò֖h lé⁠ʼmò֑r ʼeţ-ẖàtáʼa֕⁠y ʼàni֖y mazĕki֥̇yr ha⁠ẏֽwòm׃"],[41,10,"פַּרְעֹ֖ה קָצַ֣ף עַל־עֲבָדָ֑י⁠ו וַ⁠יִּתֵּ֨ן אֹתִ֜⁠י בְּ⁠מִשְׁמַ֗ר בֵּ֚ית שַׂ֣ר הַ⁠טַּבָּחִ֔ים אֹתִ֕⁠י וְ⁠אֵ֖ת שַׂ֥ר הָ⁠אֹפִֽים׃","pȧrĕʻò֖h qáẕa֣p ʻal-ʻàbádá֑y⁠w wa⁠yi̇ţé̇֨n ʼòţi֜⁠y bĕ̇⁠mişĕ̌ma֗r bé֚̇yţ şâ֣r ha⁠tȧbá̇ẖi֔ym ʼòţi֕⁠y wĕ⁠ʼé֖ţ şâ֥r há⁠ʼòpiֽym׃"],[41,11,"וַ⁠נַּֽחַלְמָ֥⁠ה חֲל֛וֹם בְּ⁠לַ֥יְלָה אֶחָ֖ד אֲנִ֣י וָ⁠ה֑וּא אִ֛ישׁ כְּ⁠פִתְר֥וֹן חֲלֹמ֖⁠וֹ חָלָֽמְנוּ׃","wa⁠nȧֽẖalĕmá֥⁠h ẖàl֛wòm bĕ̇⁠la֥yĕláh ʼeẖá֖d ʼàni֣y wá⁠h֑ẇʼ ʼi֛yş̌ kĕ̇⁠piţĕr֥wòn ẖàlòm֖⁠wò ẖáláֽmĕnẇ׃"],[41,12,"וְ⁠שָׁ֨ם אִתָּ֜⁠נוּ נַ֣עַר עִבְרִ֗י עֶ֚בֶד לְ⁠שַׂ֣ר הַ⁠טַּבָּחִ֔ים וַ⁠נְּ֨סַפֶּר־ל֔⁠וֹ וַ⁠יִּפְתָּר־לָ֖⁠נוּ אֶת־חֲלֹמֹתֵ֑י⁠נוּ אִ֥ישׁ כַּ⁠חֲלֹמ֖⁠וֹ פָּתָֽר׃","wĕ⁠şá̌֨m ʼiţá̇֜⁠nẇ na֣ʻar ʻibĕri֗y ʻe֚bed lĕ⁠şâ֣r ha⁠tȧbá̇ẖi֔ym wa⁠nĕ̇֨sapėr-l֔⁠wò wa⁠yi̇pĕţá̇r-lá֖⁠nẇ ʼeţ-ẖàlòmòţé֑y⁠nẇ ʼi֥yş̌ kȧ⁠ẖàlòm֖⁠wò pá̇ţáֽr׃"],[41,13,"וַ⁠יְהִ֛י כַּ⁠אֲשֶׁ֥ר פָּֽתַר־לָ֖⁠נוּ כֵּ֣ן הָיָ֑ה אֹתִ֛⁠י הֵשִׁ֥יב עַל־כַּנִּ֖⁠י וְ⁠אֹת֥⁠וֹ תָלָֽה׃","wa⁠yĕhi֛y kȧ⁠ʼàşě֥r páֽ̇ţar-lá֖⁠nẇ ké֣̇n háyá֑h ʼòţi֛⁠y héşǐ֥yb ʻal-kȧni֖̇⁠y wĕ⁠ʼòţ֥⁠wò ţáláֽh׃"],[41,14,"וַ⁠יִּשְׁלַ֤ח פַּרְעֹה֙ וַ⁠יִּקְרָ֣א אֶת־יוֹסֵ֔ף וַ⁠יְרִיצֻ֖⁠הוּ מִן־הַ⁠בּ֑וֹר וַ⁠יְגַלַּח֙ וַ⁠יְחַלֵּ֣ף שִׂמְלֹתָ֔י⁠ו וַ⁠יָּבֹ֖א אֶל־פַּרְעֹֽה׃","wa⁠yi̇şĕ̌la֤ẖ pȧrĕʻòh֙ wa⁠yi̇qĕrá֣ʼ ʼeţ-ywòsé֔p wa⁠yĕriyẕu֖⁠hẇ min-ha⁠ḃ֑wòr wa⁠yĕgalȧẖ֙ wa⁠yĕẖalé֣̇p şîmĕlòţá֔y⁠w wa⁠yá̇bò֖ʼ ʼel-pȧrĕʻòֽh׃"],[41,15,"וַ⁠יֹּ֤אמֶר פַּרְעֹה֙ אֶל־יוֹסֵ֔ף חֲל֣וֹם חָלַ֔מְתִּי וּ⁠פֹתֵ֖ר אֵ֣ין אֹת֑⁠וֹ וַ⁠אֲנִ֗י שָׁמַ֤עְתִּי עָלֶ֨י⁠ךָ֙ לֵ⁠אמֹ֔ר תִּשְׁמַ֥ע חֲל֖וֹם לִ⁠פְתֹּ֥ר אֹתֽ⁠וֹ׃","wa⁠yò֤̇ʼmer pȧrĕʻòh֙ ʼel-ywòsé֔p ẖàl֣wòm ẖála֔mĕţi̇y ẇ⁠pòţé֖r ʼé֣yn ʼòţ֑⁠wò wa⁠ʼàni֗y şá̌ma֤ʻĕţi̇y ʻále֨y⁠ká֙ lé⁠ʼmò֔r ţi̇şĕ̌ma֥ʻ ẖàl֖wòm li⁠pĕţò֥̇r ʼòţֽ⁠wò׃"],[41,16,"וַ⁠יַּ֨עַן יוֹסֵ֧ף אֶת־פַּרְעֹ֛ה לֵ⁠אמֹ֖ר בִּלְעָדָ֑⁠י אֱלֹהִ֕ים יַעֲנֶ֖ה אֶת־שְׁל֥וֹם פַּרְעֹֽה׃","wa⁠yȧ֨ʻan ywòsé֧p ʼeţ-pȧrĕʻò֛h lé⁠ʼmò֖r bi̇lĕʻádá֑⁠y ʼèlòhi֕ym yaʻàne֖h ʼeţ-şĕ̌l֥wòm pȧrĕʻòֽh׃"],[41,17,"וַ⁠יְדַבֵּ֥ר פַּרְעֹ֖ה אֶל־יוֹסֵ֑ף בַּ⁠חֲלֹמִ֕⁠י הִנְ⁠נִ֥י עֹמֵ֖ד עַל־שְׂפַ֥ת הַ⁠יְאֹֽר׃","wa⁠yĕdabé֥̇r pȧrĕʻò֖h ʼel-ywòsé֑p bȧ⁠ẖàlòmi֕⁠y hinĕ⁠ni֥y ʻòmé֖d ʻal-şĕ̂pa֥ţ ha⁠yĕʼòֽr׃"],[41,18,"וְ⁠הִנֵּ֣ה מִן־הַ⁠יְאֹ֗ר עֹלֹת֙ שֶׁ֣בַע פָּר֔וֹת בְּרִיא֥וֹת בָּשָׂ֖ר וִ⁠יפֹ֣ת תֹּ֑אַר וַ⁠תִּרְעֶ֖ינָה בָּ⁠אָֽחוּ׃","wĕ⁠hiné֣̇h min-ha⁠yĕʼò֗r ʻòlòţ֙ şě֣baʻ pá̇r֔wòţ bĕ̇riyʼ֥wòţ bá̇şá֖̂r wi⁠ypò֣ţ ţò֑̇ʼar wa⁠ţi̇rĕʻe֖ynáh bá̇⁠ʼáֽẖẇ׃"],[41,19,"וְ⁠הִנֵּ֞ה שֶֽׁבַע־פָּר֤וֹת אֲחֵרוֹת֙ עֹל֣וֹת אַחֲרֵי⁠הֶ֔ן דַּלּ֨וֹת וְ⁠רָע֥וֹת תֹּ֛אַר מְאֹ֖ד וְ⁠רַקּ֣וֹת בָּשָׂ֑ר לֹֽא־רָאִ֧יתִי כָ⁠הֵ֛נָּה בְּ⁠כָל־אֶ֥רֶץ מִצְרַ֖יִם לָ⁠רֹֽעַ׃","wĕ⁠hiné̇֞h şěֽbaʻ-pá̇r֤wòţ ʼàẖérwòţ֙ ʻòl֣wòţ ʼaẖàréy⁠he֔n dȧl̇֨wòţ wĕ⁠ráʻ֥wòţ ţò֛̇ʼar mĕʼò֖d wĕ⁠raq֣̇wòţ bá̇şá֑̂r lòֽʼ-ráʼi֧yţiy ká⁠hé֛ná̇h bĕ̇⁠kál-ʼe֥reẕ miẕĕra֖yim lá⁠ròֽʻa׃"],[41,20,"וַ⁠תֹּאכַ֨לְנָה֙ הַ⁠פָּר֔וֹת הָ⁠רַקּ֖וֹת וְ⁠הָ⁠רָע֑וֹת אֵ֣ת שֶׁ֧בַע הַ⁠פָּר֛וֹת הָ⁠רִאשֹׁנ֖וֹת הַ⁠בְּרִיאֹֽת׃","wa⁠ţò̇ʼka֨lĕnáh֙ ha⁠pá̇r֔wòţ há⁠raq֖̇wòţ wĕ⁠há⁠ráʻ֑wòţ ʼé֣ţ şě֧baʻ ha⁠pá̇r֛wòţ há⁠riʼşò̌n֖wòţ ha⁠bĕ̇riyʼòֽţ׃"],[41,21,"וַ⁠תָּבֹ֣אנָה אֶל־קִרְבֶּ֗⁠נָה וְ⁠לֹ֤א נוֹדַע֙ כִּי־בָ֣אוּ אֶל־קִרְבֶּ֔⁠נָה וּ⁠מַרְאֵי⁠הֶ֣ן רַ֔ע כַּ⁠אֲשֶׁ֖ר בַּ⁠תְּחִלָּ֑ה וָ⁠אִיקָֽץ׃","wa⁠ţá̇bò֣ʼnáh ʼel-qirĕbė֗⁠náh wĕ⁠lò֤ʼ nwòdaʻ֙ ki̇y-bá֣ʼẇ ʼel-qirĕbė֔⁠náh ẇ⁠marĕʼéy⁠he֣n ra֔ʻ kȧ⁠ʼàşě֖r bȧ⁠ţĕ̇ẖilá֑̇h wá⁠ʼiyqáֽẕ׃"],[41,22,"וָ⁠אֵ֖רֶא בַּ⁠חֲלֹמִ֑⁠י וְ⁠הִנֵּ֣ה ׀ שֶׁ֣בַע שִׁבֳּלִ֗ים עֹלֹ֛ת בְּ⁠קָנֶ֥ה אֶחָ֖ד מְלֵאֹ֥ת וְ⁠טֹבֽוֹת׃","wá⁠ʼé֖reʼ bȧ⁠ẖàlòmi֑⁠y wĕ⁠hiné֣̇h ׀ şě֣baʻ şǐbȯli֗ym ʻòlò֛ţ bĕ̇⁠qáne֥h ʼeẖá֖d mĕléʼò֥ţ wĕ⁠tòbֽwòţ׃"],[41,23,"וְ⁠הִנֵּה֙ שֶׁ֣בַע שִׁבֳּלִ֔ים צְנֻמ֥וֹת דַּקּ֖וֹת שְׁדֻפ֣וֹת קָדִ֑ים צֹמְח֖וֹת אַחֲרֵי⁠הֶֽם׃","wĕ⁠hiné̇h֙ şě֣baʻ şǐbȯli֔ym ẕĕnum֥wòţ dȧq֖̇wòţ şĕ̌dup֣wòţ qádi֑ym ẕòmĕẖ֖wòţ ʼaẖàréy⁠heֽm׃"],[41,24,"וַ⁠תִּבְלַ֨עְןָ֙ הָ⁠שִׁבֳּלִ֣ים הַ⁠דַּקֹּ֔ת אֵ֛ת שֶׁ֥בַע הַֽ⁠שִׁבֳּלִ֖ים הַ⁠טֹּב֑וֹת וָֽ⁠אֹמַר֙ אֶל־הַֽ⁠חַרְטֻמִּ֔ים וְ⁠אֵ֥ין מַגִּ֖יד לִֽ⁠י׃","wa⁠ţi̇bĕla֨ʻĕná֙ há⁠şǐbȯli֣ym ha⁠dȧqò̇֔ţ ʼé֛ţ şě֥baʻ haֽ⁠şǐbȯli֖ym ha⁠tò̇b֑wòţ wáֽ⁠ʼòmar֙ ʼel-haֽ⁠ẖarĕtumi̇֔ym wĕ⁠ʼé֥yn magi֖̇yd liֽ⁠y׃"],[41,25,"וַ⁠יֹּ֤אמֶר יוֹסֵף֙ אֶל־פַּרְעֹ֔ה חֲל֥וֹם פַּרְעֹ֖ה אֶחָ֣ד ה֑וּא אֵ֣ת אֲשֶׁ֧ר הָ⁠אֱלֹהִ֛ים עֹשֶׂ֖ה הִגִּ֥יד לְ⁠פַרְעֹֽה׃","wa⁠yò֤̇ʼmer ywòsép֙ ʼel-pȧrĕʻò֔h ẖàl֥wòm pȧrĕʻò֖h ʼeẖá֣d h֑ẇʼ ʼé֣ţ ʼàşě֧r há⁠ʼèlòhi֛ym ʻòşê֖h higi֥̇yd lĕ⁠parĕʻòֽh׃"],[41,26,"שֶׁ֧בַע פָּרֹ֣ת הַ⁠טֹּבֹ֗ת שֶׁ֤בַע שָׁנִים֙ הֵ֔נָּה וְ⁠שֶׁ֤בַע הַֽ⁠שִּׁבֳּלִים֙ הַ⁠טֹּבֹ֔ת שֶׁ֥בַע שָׁנִ֖ים הֵ֑נָּה חֲל֖וֹם אֶחָ֥ד הֽוּא׃","şě֧baʻ pá̇rò֣ţ ha⁠tò̇bò֗ţ şě֤baʻ şá̌niym֙ hé֔ná̇h wĕ⁠şě֤baʻ haֽ⁠şi̇̌bȯliym֙ ha⁠tò̇bò֔ţ şě֥baʻ şá̌ni֖ym hé֑ná̇h ẖàl֖wòm ʼeẖá֥d hֽẇʼ׃"],[41,27,"וְ⁠שֶׁ֣בַע הַ֠⁠פָּרוֹת הָֽ⁠רַקּ֨וֹת וְ⁠הָ⁠רָעֹ֜ת הָ⁠עֹלֹ֣ת אַחֲרֵי⁠הֶ֗ן שֶׁ֤בַע שָׁנִים֙ הֵ֔נָּה וְ⁠שֶׁ֤בַע הַֽ⁠שִׁבֳּלִים֙ הָ⁠רֵק֔וֹת שְׁדֻפ֖וֹת הַ⁠קָּדִ֑ים יִהְי֕וּ שֶׁ֖בַע שְׁנֵ֥י רָעָֽב׃","wĕ⁠şě֣baʻ ha֠⁠pá̇rwòţ háֽ⁠raq̇֨wòţ wĕ⁠há⁠ráʻò֜ţ há⁠ʻòlò֣ţ ʼaẖàréy⁠he֗n şě֤baʻ şá̌niym֙ hé֔ná̇h wĕ⁠şě֤baʻ haֽ⁠şǐbȯliym֙ há⁠réq֔wòţ şĕ̌dup֖wòţ ha⁠qá̇di֑ym yihĕy֕ẇ şě֖baʻ şĕ̌né֥y ráʻáֽb׃"],[41,28,"ה֣וּא הַ⁠דָּבָ֔ר אֲשֶׁ֥ר דִּבַּ֖רְתִּי אֶל־פַּרְעֹ֑ה אֲשֶׁ֧ר הָ⁠אֱלֹהִ֛ים עֹשֶׂ֖ה הֶרְאָ֥ה אֶת־פַּרְעֹֽה׃","h֣ẇʼ ha⁠dá̇bá֔r ʼàşě֥r di̇bȧ֖rĕţi̇y ʼel-pȧrĕʻò֑h ʼàşě֧r há⁠ʼèlòhi֛ym ʻòşê֖h herĕʼá֥h ʼeţ-pȧrĕʻòֽh׃"],[41,29,"הִנֵּ֛ה שֶׁ֥בַע שָׁנִ֖ים בָּא֑וֹת שָׂבָ֥ע גָּד֖וֹל בְּ⁠כָל־אֶ֥רֶץ מִצְרָֽיִם׃","hiné֛̇h şě֥baʻ şá̌ni֖ym bá̇ʼ֑wòţ şá̂bá֥ʻ gá̇d֖wòl bĕ̇⁠kál-ʼe֥reẕ miẕĕráֽyim׃"],[41,30,"וְ֠⁠קָמוּ שֶׁ֜בַע שְׁנֵ֤י רָעָב֙ אַחֲרֵי⁠הֶ֔ן וְ⁠נִשְׁכַּ֥ח כָּל־הַ⁠שָּׂבָ֖ע בְּ⁠אֶ֣רֶץ מִצְרָ֑יִם וְ⁠כִלָּ֥ה הָ⁠רָעָ֖ב אֶת־הָ⁠אָֽרֶץ׃","wĕ֠⁠qámẇ şě֜baʻ şĕ̌né֤y ráʻáb֙ ʼaẖàréy⁠he֔n wĕ⁠nişĕ̌kȧ֥ẖ ká̇l-ha⁠şá̇̂bá֖ʻ bĕ̇⁠ʼe֣reẕ miẕĕrá֑yim wĕ⁠kilá֥̇h há⁠ráʻá֖b ʼeţ-há⁠ʼáֽreẕ׃"],[41,31,"וְ⁠לֹֽא־יִוָּדַ֤ע הַ⁠שָּׂבָע֙ בָּ⁠אָ֔רֶץ מִ⁠פְּנֵ֛י הָ⁠רָעָ֥ב הַ⁠ה֖וּא אַחֲרֵי־כֵ֑ן כִּֽי־כָבֵ֥ד ה֖וּא מְאֹֽד׃","wĕ⁠lòֽʼ-yiwá̇da֤ʻ ha⁠şá̇̂báʻ֙ bá̇⁠ʼá֔reẕ mi⁠pĕ̇né֛y há⁠ráʻá֥b ha⁠h֖ẇʼ ʼaẖàréy-ké֑n kiֽ̇y-kábé֥d h֖ẇʼ mĕʼòֽd׃"],[41,32,"וְ⁠עַ֨ל הִשָּׁנ֧וֹת הַ⁠חֲל֛וֹם אֶל־פַּרְעֹ֖ה פַּעֲמָ֑יִם כִּֽי־נָכ֤וֹן הַ⁠דָּבָר֙ מֵ⁠עִ֣ם הָ⁠אֱלֹהִ֔ים וּ⁠מְמַהֵ֥ר הָ⁠אֱלֹהִ֖ים לַ⁠עֲשֹׂתֽ⁠וֹ׃","wĕ⁠ʻa֨l hişá̇̌n֧wòţ ha⁠ẖàl֛wòm ʼel-pȧrĕʻò֖h pȧʻàmá֑yim kiֽ̇y-nák֤wòn ha⁠dá̇bár֙ mé⁠ʻi֣m há⁠ʼèlòhi֔ym ẇ⁠mĕmahé֥r há⁠ʼèlòhi֖ym la⁠ʻàşò̂ţֽ⁠wò׃"],[41,33,"וְ⁠עַתָּה֙ יֵרֶ֣א פַרְעֹ֔ה אִ֖ישׁ נָב֣וֹן וְ⁠חָכָ֑ם וִ⁠ישִׁיתֵ֖⁠הוּ עַל־אֶ֥רֶץ מִצְרָֽיִם׃","wĕ⁠ʻaţá̇h֙ yére֣ʼ parĕʻò֔h ʼi֖yş̌ náb֣wòn wĕ⁠ẖáká֑m wi⁠yşǐyţé֖⁠hẇ ʻal-ʼe֥reẕ miẕĕráֽyim׃"],[41,34,"יַעֲשֶׂ֣ה פַרְעֹ֔ה וְ⁠יַפְקֵ֥ד פְּקִדִ֖ים עַל־הָ⁠אָ֑רֶץ וְ⁠חִמֵּשׁ֙ אֶת־אֶ֣רֶץ מִצְרַ֔יִם בְּ⁠שֶׁ֖בַע שְׁנֵ֥י הַ⁠שָּׂבָֽע׃","yaʻàşê֣h parĕʻò֔h wĕ⁠yapĕqé֥d pĕ̇qidi֖ym ʻal-há⁠ʼá֑reẕ wĕ⁠ẖimé̇ş̌֙ ʼeţ-ʼe֣reẕ miẕĕra֔yim bĕ̇⁠şě֖baʻ şĕ̌né֥y ha⁠şá̇̂báֽʻ׃"],[41,35,"וְ⁠יִקְבְּצ֗וּ אֶת־כָּל־אֹ֨כֶל֙ הַ⁠שָּׁנִ֣ים הַ⁠טֹּבֹ֔ת הַ⁠בָּאֹ֖ת הָ⁠אֵ֑לֶּה וְ⁠יִצְבְּרוּ־בָ֞ר תַּ֧חַת יַד־פַּרְעֹ֛ה אֹ֥כֶל בֶּ⁠עָרִ֖ים וְ⁠שָׁמָֽרוּ׃","wĕ⁠yiqĕbĕ̇ẕ֗ẇ ʼeţ-ká̇l-ʼò֨kel֙ ha⁠şá̇̌ni֣ym ha⁠tò̇bò֔ţ ha⁠bá̇ʼò֖ţ há⁠ʼé֑lėh wĕ⁠yiẕĕbĕ̇rẇ-bá֞r ţȧ֧ẖaţ yad-pȧrĕʻò֛h ʼò֥kel bė⁠ʻári֖ym wĕ⁠şá̌máֽrẇ׃"],[41,36,"וְ⁠הָיָ֨ה הָ⁠אֹ֤כֶל לְ⁠פִקָּדוֹן֙ לָ⁠אָ֔רֶץ לְ⁠שֶׁ֨בַע֙ שְׁנֵ֣י הָ⁠רָעָ֔ב אֲשֶׁ֥ר תִּהְיֶ֖יןָ בְּ⁠אֶ֣רֶץ מִצְרָ֑יִם וְ⁠לֹֽא־תִכָּרֵ֥ת הָ⁠אָ֖רֶץ בָּ⁠רָעָֽב׃","wĕ⁠háyá֨h há⁠ʼò֤kel lĕ⁠piqá̇dwòn֙ lá⁠ʼá֔reẕ lĕ⁠şě֨baʻ֙ şĕ̌né֣y há⁠ráʻá֔b ʼàşě֥r ţi̇hĕye֖yná bĕ̇⁠ʼe֣reẕ miẕĕrá֑yim wĕ⁠lòֽʼ-ţiká̇ré֥ţ há⁠ʼá֖reẕ bá̇⁠ráʻáֽb׃"],[41,37,"וַ⁠יִּיטַ֥ב הַ⁠דָּבָ֖ר בְּ⁠עֵינֵ֣י פַרְעֹ֑ה וּ⁠בְ⁠עֵינֵ֖י כָּל־עֲבָדָֽי⁠ו׃","wa⁠yi̇yta֥b ha⁠dá̇bá֖r bĕ̇⁠ʻéyné֣y parĕʻò֑h ẇ⁠bĕ⁠ʻéyné֖y ká̇l-ʻàbádáֽy⁠w׃"],[41,38,"וַ⁠יֹּ֥אמֶר פַּרְעֹ֖ה אֶל־עֲבָדָ֑י⁠ו הֲ⁠נִמְצָ֣א כָ⁠זֶ֔ה אִ֕ישׁ אֲשֶׁ֛ר ר֥וּחַ אֱלֹהִ֖ים בּֽ⁠וֹ׃","wa⁠yò֥̇ʼmer pȧrĕʻò֖h ʼel-ʻàbádá֑y⁠w hà⁠nimĕẕá֣ʼ ká⁠ze֔h ʼi֕yş̌ ʼàşě֛r r֥ẇẖa ʼèlòhi֖ym ḃֽ⁠wò׃"],[41,39,"וַ⁠יֹּ֤אמֶר פַּרְעֹה֙ אֶל־יוֹסֵ֔ף אַחֲרֵ֨י הוֹדִ֧יעַ אֱלֹהִ֛ים אוֹתְ⁠ךָ֖ אֶת־כָּל־זֹ֑את אֵין־נָב֥וֹן וְ⁠חָכָ֖ם כָּמֽוֹ⁠ךָ׃","wa⁠yò֤̇ʼmer pȧrĕʻòh֙ ʼel-ywòsé֔p ʼaẖàré֨y hwòdi֧yʻa ʼèlòhi֛ym ʼwòţĕ⁠ká֖ ʼeţ-ká̇l-zò֑ʼţ ʼéyn-náb֥wòn wĕ⁠ẖáká֖m ká̇mֽwò⁠ká׃"],[41,40,"אַתָּה֙ תִּהְיֶ֣ה עַל־בֵּיתִ֔⁠י וְ⁠עַל־פִּ֖י⁠ךָ יִשַּׁ֣ק כָּל־עַמִּ֑⁠י רַ֥ק הַ⁠כִּסֵּ֖א אֶגְדַּ֥ל מִמֶּֽ⁠ךָּ׃","ʼaţá̇h֙ ţi̇hĕye֣h ʻal-bé̇yţi֔⁠y wĕ⁠ʻal-pi֖̇y⁠ká yişȧ֣̌q ká̇l-ʻami֑̇⁠y ra֥q ha⁠ki̇sé֖̇ʼ ʼegĕdȧ֥l mimėֽ⁠ká̇׃"],[41,41,"וַ⁠יֹּ֥אמֶר פַּרְעֹ֖ה אֶל־יוֹסֵ֑ף רְאֵה֙ נָתַ֣תִּי אֹֽתְ⁠ךָ֔ עַ֖ל כָּל־אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yò֥̇ʼmer pȧrĕʻò֖h ʼel-ywòsé֑p rĕʼéh֙ náţa֣ţi̇y ʼòֽţĕ⁠ká֔ ʻa֖l ká̇l-ʼe֥reẕ miẕĕráֽyim׃"],[41,42,"וַ⁠יָּ֨סַר פַּרְעֹ֤ה אֶת־טַבַּעְתּ⁠וֹ֙ מֵ⁠עַ֣ל יָד֔⁠וֹ וַ⁠יִּתֵּ֥ן אֹתָ֖⁠הּ עַל־יַ֣ד יוֹסֵ֑ף וַ⁠יַּלְבֵּ֤שׁ אֹת⁠וֹ֙ בִּגְדֵי־שֵׁ֔שׁ וַ⁠יָּ֛שֶׂם רְבִ֥ד הַ⁠זָּהָ֖ב עַל־צַוָּארֽ⁠וֹ׃","wa⁠yá̇֨sar pȧrĕʻò֤h ʼeţ-tabȧʻĕţ̇⁠wò֙ mé⁠ʻa֣l yád֔⁠wò wa⁠yi̇ţé֥̇n ʼòţá֖⁠ḣ ʻal-ya֣d ywòsé֑p wa⁠yȧlĕbé֤̇ş̌ ʼòţ⁠wò֙ bi̇gĕdéy-şé̌֔ş̌ wa⁠yá֛̇şêm rĕbi֥d ha⁠zá̇há֖b ʻal-ẕawá̇ʼrֽ⁠wò׃"],[41,43,"וַ⁠יַּרְכֵּ֣ב אֹת֗⁠וֹ בְּ⁠מִרְכֶּ֤בֶת הַ⁠מִּשְׁנֶה֙ אֲשֶׁר־ל֔⁠וֹ וַ⁠יִּקְרְא֥וּ לְ⁠פָנָ֖י⁠ו אַבְרֵ֑ךְ וְ⁠נָת֣וֹן אֹת֔⁠וֹ עַ֖ל כָּל־אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yȧrĕké֣̇b ʼòţ֗⁠wò bĕ̇⁠mirĕkė֤beţ ha⁠mi̇şĕ̌neh֙ ʼàşěr-l֔⁠wò wa⁠yi̇qĕrĕʼ֥ẇ lĕ⁠páná֖y⁠w ʼabĕré֑kĕ wĕ⁠náţ֣wòn ʼòţ֔⁠wò ʻa֖l ká̇l-ʼe֥reẕ miẕĕráֽyim׃"],[41,44,"וַ⁠יֹּ֧אמֶר פַּרְעֹ֛ה אֶל־יוֹסֵ֖ף אֲנִ֣י פַרְעֹ֑ה וּ⁠בִלְעָדֶ֗י⁠ךָ לֹֽא־יָרִ֨ים אִ֧ישׁ אֶת־יָד֛⁠וֹ וְ⁠אֶת־רַגְל֖⁠וֹ בְּ⁠כָל־אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yò֧̇ʼmer pȧrĕʻò֛h ʼel-ywòsé֖p ʼàni֣y parĕʻò֑h ẇ⁠bilĕʻáde֗y⁠ká lòֽʼ-yári֨ym ʼi֧yş̌ ʼeţ-yád֛⁠wò wĕ⁠ʼeţ-ragĕl֖⁠wò bĕ̇⁠kál-ʼe֥reẕ miẕĕráֽyim׃"],[41,45,"וַ⁠יִּקְרָ֨א פַרְעֹ֣ה שֵׁם־יוֹסֵף֮ צָֽפְנַ֣ת פַּעְנֵחַ֒ וַ⁠יִּתֶּן־ל֣⁠וֹ אֶת־אָֽסְנַ֗ת בַּת־פּ֥וֹטִי פֶ֛רַע כֹּהֵ֥ן אֹ֖ן לְ⁠אִשָּׁ֑ה וַ⁠יֵּצֵ֥א יוֹסֵ֖ף עַל־אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yi̇qĕrá֨ʼ parĕʻò֣h şé̌m-ywòsép֮ ẕáֽpĕna֣ţ pȧʻĕnéẖa֒ wa⁠yi̇ţėn-l֣⁠wò ʼeţ-ʼáֽsĕna֗ţ bȧţ-ṗ֥wòtiy pe֛raʻ kò̇hé֥n ʼò֖n lĕ⁠ʼişá֑̇̌h wa⁠yé̇ẕé֥ʼ ywòsé֖p ʻal-ʼe֥reẕ miẕĕráֽyim׃"],[41,46,"וְ⁠יוֹסֵף֙ בֶּן־שְׁלֹשִׁ֣ים שָׁנָ֔ה בְּ⁠עָמְד֕⁠וֹ לִ⁠פְנֵ֖י פַּרְעֹ֣ה מֶֽלֶךְ־מִצְרָ֑יִם וַ⁠יֵּצֵ֤א יוֹסֵף֙ מִ⁠לִּ⁠פְנֵ֣י פַרְעֹ֔ה וַֽ⁠יַּעְבֹ֖ר בְּ⁠כָל־אֶ֥רֶץ מִצְרָֽיִם׃","wĕ⁠ywòsép֙ bėn-şĕ̌lòşǐ֣ym şá̌ná֔h bĕ̇⁠ʻámĕd֕⁠wò li⁠pĕné֖y pȧrĕʻò֣h meֽlekĕ-miẕĕrá֑yim wa⁠yé̇ẕé֤ʼ ywòsép֙ mi⁠li̇⁠pĕné֣y parĕʻò֔h waֽ⁠yȧʻĕbò֖r bĕ̇⁠kál-ʼe֥reẕ miẕĕráֽyim׃"],[41,47,"וַ⁠תַּ֣עַשׂ הָ⁠אָ֔רֶץ בְּ⁠שֶׁ֖בַע שְׁנֵ֣י הַ⁠שָּׂבָ֑ע לִ⁠קְמָצִֽים׃","wa⁠ţȧ֣ʻaş̂ há⁠ʼá֔reẕ bĕ̇⁠şě֖baʻ şĕ̌né֣y ha⁠şá̇̂bá֑ʻ li⁠qĕmáẕiֽym׃"],[41,48,"וַ⁠יִּקְבֹּ֞ץ אֶת־כָּל־אֹ֣כֶל ׀ שֶׁ֣בַע שָׁנִ֗ים אֲשֶׁ֤ר הָיוּ֙ בְּ⁠אֶ֣רֶץ מִצְרַ֔יִם וַ⁠יִּתֶּן־אֹ֖כֶל בֶּ⁠עָרִ֑ים אֹ֧כֶל שְׂדֵה־הָ⁠עִ֛יר אֲשֶׁ֥ר סְבִיבֹתֶ֖י⁠הָ נָתַ֥ן בְּ⁠תוֹכָֽ⁠הּ׃","wa⁠yi̇qĕbò̇֞ẕ ʼeţ-ká̇l-ʼò֣kel ׀ şě֣baʻ şá̌ni֗ym ʼàşě֤r háyẇ֙ bĕ̇⁠ʼe֣reẕ miẕĕra֔yim wa⁠yi̇ţėn-ʼò֖kel bė⁠ʻári֑ym ʼò֧kel şĕ̂déh-há⁠ʻi֛yr ʼàşě֥r sĕbiybòţe֖y⁠há náţa֥n bĕ̇⁠ţwòkáֽ⁠ḣ׃"],[41,49,"וַ⁠יִּצְבֹּ֨ר יוֹסֵ֥ף בָּ֛ר כְּ⁠ח֥וֹל הַ⁠יָּ֖ם הַרְבֵּ֣ה מְאֹ֑ד עַ֛ד כִּי־חָדַ֥ל לִ⁠סְפֹּ֖ר כִּי־אֵ֥ין מִסְפָּֽר׃","wa⁠yi̇ẕĕbò̇֨r ywòsé֥p bá֛̇r kĕ̇⁠ẖ֥wòl ha⁠yá֖̇m harĕbé֣̇h mĕʼò֑d ʻa֛d ki̇y-ẖáda֥l li⁠sĕpò֖̇r ki̇y-ʼé֥yn misĕpáֽ̇r׃"],[41,50,"וּ⁠לְ⁠יוֹסֵ֤ף יֻלַּד֙ שְׁנֵ֣י בָנִ֔ים בְּ⁠טֶ֥רֶם תָּב֖וֹא שְׁנַ֣ת הָ⁠רָעָ֑ב אֲשֶׁ֤ר יָֽלְדָה־לּ⁠וֹ֙ אָֽסְנַ֔ת בַּת־פּ֥וֹטִי פֶ֖רַע כֹּהֵ֥ן אֽוֹן׃","ẇ⁠lĕ⁠ywòsé֤p yulȧd֙ şĕ̌né֣y báni֔ym bĕ̇⁠te֥rem ţá̇b֖wòʼ şĕ̌na֣ţ há⁠ráʻá֑b ʼàşě֤r yáֽlĕdáh-l̇⁠wò֙ ʼáֽsĕna֔ţ bȧţ-ṗ֥wòtiy pe֖raʻ kò̇hé֥n ʼֽwòn׃"],[41,51,"וַ⁠יִּקְרָ֥א יוֹסֵ֛ף אֶת־שֵׁ֥ם הַ⁠בְּכ֖וֹר מְנַשֶּׁ֑ה כִּֽי־נַשַּׁ֤⁠נִי אֱלֹהִים֙ אֶת־כָּל־עֲמָלִ֔⁠י וְ⁠אֵ֖ת כָּל־בֵּ֥ית אָבִֽ⁠י׃","wa⁠yi̇qĕrá֥ʼ ywòsé֛p ʼeţ-şé֥̌m ha⁠bĕ̇k֖wòr mĕnaşė֑̌h kiֽ̇y-naşȧ֤̌⁠niy ʼèlòhiym֙ ʼeţ-ká̇l-ʻàmáli֔⁠y wĕ⁠ʼé֖ţ ká̇l-bé֥̇yţ ʼábiֽ⁠y׃"],[41,52,"וְ⁠אֵ֛ת שֵׁ֥ם הַ⁠שֵּׁנִ֖י קָרָ֣א אֶפְרָ֑יִם כִּֽי־הִפְרַ֥⁠נִי אֱלֹהִ֖ים בְּ⁠אֶ֥רֶץ עָנְיִֽ⁠י׃","wĕ⁠ʼé֛ţ şé֥̌m ha⁠şé̇̌ni֖y qárá֣ʼ ʼepĕrá֑yim kiֽ̇y-hipĕra֥⁠niy ʼèlòhi֖ym bĕ̇⁠ʼe֥reẕ ʻánĕyiֽ⁠y׃"],[41,53,"וַ⁠תִּכְלֶ֕ינָה שֶׁ֖בַע שְׁנֵ֣י הַ⁠שָּׂבָ֑ע אֲשֶׁ֥ר הָיָ֖ה בְּ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠ţi̇kĕle֕ynáh şě֖baʻ şĕ̌né֣y ha⁠şá̇̂bá֑ʻ ʼàşě֥r háyá֖h bĕ̇⁠ʼe֥reẕ miẕĕráֽyim׃"],[41,54,"וַ⁠תְּחִלֶּ֜ינָה שֶׁ֣בַע שְׁנֵ֤י הָ⁠רָעָב֙ לָ⁠ב֔וֹא כַּ⁠אֲשֶׁ֖ר אָמַ֣ר יוֹסֵ֑ף וַ⁠יְהִ֤י רָעָב֙ בְּ⁠כָל־הָ֣⁠אֲרָצ֔וֹת וּ⁠בְ⁠כָל־אֶ֥רֶץ מִצְרַ֖יִם הָ֥יָה לָֽחֶם׃","wa⁠ţĕ̇ẖilė֜ynáh şě֣baʻ şĕ̌né֤y há⁠ráʻáb֙ lá⁠b֔wòʼ kȧ⁠ʼàşě֖r ʼáma֣r ywòsé֑p wa⁠yĕhi֤y ráʻáb֙ bĕ̇⁠kál-há֣⁠ʼàráẕ֔wòţ ẇ⁠bĕ⁠kál-ʼe֥reẕ miẕĕra֖yim há֥yáh láֽẖem׃"],[41,55,"וַ⁠תִּרְעַב֙ כָּל־אֶ֣רֶץ מִצְרַ֔יִם וַ⁠יִּצְעַ֥ק הָ⁠עָ֛ם אֶל־פַּרְעֹ֖ה לַ⁠לָּ֑חֶם וַ⁠יֹּ֨אמֶר פַּרְעֹ֤ה לְ⁠כָל־מִצְרַ֨יִם֙ לְכ֣וּ אֶל־יוֹסֵ֔ף אֲשֶׁר־יֹאמַ֥ר לָ⁠כֶ֖ם תַּעֲשֽׂוּ׃","wa⁠ţi̇rĕʻab֙ ká̇l-ʼe֣reẕ miẕĕra֔yim wa⁠yi̇ẕĕʻa֥q há⁠ʻá֛m ʼel-pȧrĕʻò֖h la⁠lá֑̇ẖem wa⁠yò̇֨ʼmer pȧrĕʻò֤h lĕ⁠kál-miẕĕra֨yim֙ lĕk֣ẇ ʼel-ywòsé֔p ʼàşěr-yòʼma֥r lá⁠ke֖m ţȧʻàşֽ̂ẇ׃"],[41,56,"וְ⁠הָ⁠רָעָ֣ב הָיָ֔ה עַ֖ל כָּל־פְּנֵ֣י הָ⁠אָ֑רֶץ וַ⁠יִּפְתַּ֨ח יוֹסֵ֜ף אֶֽת־כָּל־אֲשֶׁ֤ר בָּ⁠הֶם֙ וַ⁠יִּשְׁבֹּ֣ר לְ⁠מִצְרַ֔יִם וַ⁠יֶּחֱזַ֥ק הָֽ⁠רָעָ֖ב בְּ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wĕ⁠há⁠ráʻá֣b háyá֔h ʻa֖l ká̇l-pĕ̇né֣y há⁠ʼá֑reẕ wa⁠yi̇pĕţȧ֨ẖ ywòsé֜p ʼeֽţ-ká̇l-ʼàşě֤r bá̇⁠hem֙ wa⁠yi̇şĕ̌bò֣̇r lĕ⁠miẕĕra֔yim wa⁠yėẖèza֥q háֽ⁠ráʻá֖b bĕ̇⁠ʼe֥reẕ miẕĕráֽyim׃"],[41,57,"וְ⁠כָל־הָ⁠אָ֨רֶץ֙ בָּ֣אוּ מִצְרַ֔יְמָ⁠ה לִ⁠שְׁבֹּ֖ר אֶל־יוֹסֵ֑ף כִּֽי־חָזַ֥ק הָ⁠רָעָ֖ב בְּ⁠כָל־הָ⁠אָֽרֶץ׃","wĕ⁠kál-há⁠ʼá֨reẕ֙ bá֣̇ʼẇ miẕĕra֔yĕmá⁠h li⁠şĕ̌bò֖̇r ʼel-ywòsé֑p kiֽ̇y-ẖáza֥q há⁠ráʻá֖b bĕ̇⁠kál-há⁠ʼáֽreẕ׃"],[42,1,"וַ⁠יַּ֣רְא יַעֲקֹ֔ב כִּ֥י יֶשׁ־שֶׁ֖בֶר בְּ⁠מִצְרָ֑יִם וַ⁠יֹּ֤אמֶר יַעֲקֹב֙ לְ⁠בָנָ֔י⁠ו לָ֖⁠מָּה תִּתְרָאֽוּ׃","wa⁠yȧ֣rĕʼ yaʻàqò֔b ki֥̇y yeş̌-şě֖ber bĕ̇⁠miẕĕrá֑yim wa⁠yò֤̇ʼmer yaʻàqòb֙ lĕ⁠báná֔y⁠w lá֖⁠má̇h ţi̇ţĕráʼֽẇ׃"],[42,2,"וַ⁠יֹּ֕אמֶר הִנֵּ֣ה שָׁמַ֔עְתִּי כִּ֥י יֶשׁ־שֶׁ֖בֶר בְּ⁠מִצְרָ֑יִם רְדוּ־שָׁ֨מָּ⁠ה֙ וְ⁠שִׁבְרוּ־לָ֣⁠נוּ מִ⁠שָּׁ֔ם וְ⁠נִחְיֶ֖ה וְ⁠לֹ֥א נָמֽוּת׃","wa⁠yò̇֕ʼmer hiné֣̇h şá̌ma֔ʻĕţi̇y ki֥̇y yeş̌-şě֖ber bĕ̇⁠miẕĕrá֑yim rĕdẇ-şá̌֨má̇⁠h֙ wĕ⁠şǐbĕrẇ-lá֣⁠nẇ mi⁠şá̇̌֔m wĕ⁠niẖĕye֖h wĕ⁠lò֥ʼ námֽẇţ׃"],[42,3,"וַ⁠יֵּרְד֥וּ אֲחֵֽי־יוֹסֵ֖ף עֲשָׂרָ֑ה לִ⁠שְׁבֹּ֥ר בָּ֖ר מִ⁠מִּצְרָֽיִם׃","wa⁠yé̇rĕd֥ẇ ʼàẖéֽy-ywòsé֖p ʻàşá̂rá֑h li⁠şĕ̌bò֥̇r bá֖̇r mi⁠mi̇ẕĕráֽyim׃"],[42,4,"וְ⁠אֶת־בִּנְיָמִין֙ אֲחִ֣י יוֹסֵ֔ף לֹא־שָׁלַ֥ח יַעֲקֹ֖ב אֶת־אֶחָ֑י⁠ו כִּ֣י אָמַ֔ר פֶּן־יִקְרָאֶ֖⁠נּוּ אָסֽוֹן׃","wĕ⁠ʼeţ-bi̇nĕyámiyn֙ ʼàẖi֣y ywòsé֔p lòʼ-şá̌la֥ẖ yaʻàqò֖b ʼeţ-ʼeẖá֑y⁠w ki֣̇y ʼáma֔r pėn-yiqĕráʼe֖⁠ṅẇ ʼásֽwòn׃"],[42,5,"וַ⁠יָּבֹ֨אוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל לִ⁠שְׁבֹּ֖ר בְּ⁠ת֣וֹךְ הַ⁠בָּאִ֑ים כִּֽי־הָיָ֥ה הָ⁠רָעָ֖ב בְּ⁠אֶ֥רֶץ כְּנָֽעַן׃","wa⁠yá̇bò֨ʼẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l li⁠şĕ̌bò֖̇r bĕ̇⁠ţ֣wòkĕ ha⁠bá̇ʼi֑ym kiֽ̇y-háyá֥h há⁠ráʻá֖b bĕ̇⁠ʼe֥reẕ kĕ̇náֽʻan׃"],[42,6,"וְ⁠יוֹסֵ֗ף ה֚וּא הַ⁠שַּׁלִּ֣יט עַל־הָ⁠אָ֔רֶץ ה֥וּא הַ⁠מַּשְׁבִּ֖יר לְ⁠כָל־עַ֣ם הָ⁠אָ֑רֶץ וַ⁠יָּבֹ֨אוּ֙ אֲחֵ֣י יוֹסֵ֔ף וַ⁠יִּשְׁתַּֽחֲווּ־ל֥⁠וֹ אַפַּ֖יִם אָֽרְצָ⁠ה׃","wĕ⁠ywòsé֗p h֚ẇʼ ha⁠şȧ̌li֣̇yt ʻal-há⁠ʼá֔reẕ h֥ẇʼ ha⁠mȧşĕ̌bi֖̇yr lĕ⁠kál-ʻa֣m há⁠ʼá֑reẕ wa⁠yá̇bò֨ʼẇ֙ ʼàẖé֣y ywòsé֔p wa⁠yi̇şĕ̌ţȧֽẖàwẇ-l֥⁠wò ʼapȧ֖yim ʼáֽrĕẕá⁠h׃"],[42,7,"וַ⁠יַּ֥רְא יוֹסֵ֛ף אֶת־אֶחָ֖י⁠ו וַ⁠יַּכִּרֵ֑⁠ם וַ⁠יִּתְנַכֵּ֨ר אֲלֵי⁠הֶ֜ם וַ⁠יְדַבֵּ֧ר אִתָּ֣⁠ם קָשׁ֗וֹת וַ⁠יֹּ֤אמֶר אֲלֵ⁠הֶם֙ מֵ⁠אַ֣יִן בָּאתֶ֔ם וַ⁠יֹּ֣אמְר֔וּ מֵ⁠אֶ֥רֶץ כְּנַ֖עַן לִ⁠שְׁבָּר־אֹֽכֶל׃","wa⁠yȧ֥rĕʼ ywòsé֛p ʼeţ-ʼeẖá֖y⁠w wa⁠yȧki̇ré֑⁠m wa⁠yi̇ţĕnaké̇֨r ʼàléy⁠he֜m wa⁠yĕdabé֧̇r ʼiţá֣̇⁠m qáş̌֗wòţ wa⁠yò֤̇ʼmer ʼàlé⁠hem֙ mé⁠ʼa֣yin bá̇ʼţe֔m wa⁠yò֣̇ʼmĕr֔ẇ mé⁠ʼe֥reẕ kĕ̇na֖ʻan li⁠şĕ̌bá̇r-ʼòֽkel׃"],[42,8,"וַ⁠יַּכֵּ֥ר יוֹסֵ֖ף אֶת־אֶחָ֑י⁠ו וְ⁠הֵ֖ם לֹ֥א הִכִּרֻֽ⁠הוּ׃","wa⁠yȧké֥̇r ywòsé֖p ʼeţ-ʼeẖá֑y⁠w wĕ⁠hé֖m lò֥ʼ hiki̇ruֽ⁠hẇ׃"],[42,9,"וַ⁠יִּזְכֹּ֣ר יוֹסֵ֔ף אֵ֚ת הַ⁠חֲלֹמ֔וֹת אֲשֶׁ֥ר חָלַ֖ם לָ⁠הֶ֑ם וַ⁠יֹּ֤אמֶר אֲלֵ⁠הֶם֙ מְרַגְּלִ֣ים אַתֶּ֔ם לִ⁠רְא֛וֹת אֶת־עֶרְוַ֥ת הָ⁠אָ֖רֶץ בָּאתֶֽם׃","wa⁠yi̇zĕkò֣̇r ywòsé֔p ʼé֚ţ ha⁠ẖàlòm֔wòţ ʼàşě֥r ẖála֖m lá⁠he֑m wa⁠yò֤̇ʼmer ʼàlé⁠hem֙ mĕragĕ̇li֣ym ʼaţė֔m li⁠rĕʼ֛wòţ ʼeţ-ʻerĕwa֥ţ há⁠ʼá֖reẕ bá̇ʼţeֽm׃"],[42,10,"וַ⁠יֹּאמְר֥וּ אֵלָ֖י⁠ו לֹ֣א אֲדֹנִ֑⁠י וַ⁠עֲבָדֶ֥י⁠ךָ בָּ֖אוּ לִ⁠שְׁבָּר־אֹֽכֶל׃","wa⁠yò̇ʼmĕr֥ẇ ʼélá֖y⁠w lò֣ʼ ʼàdòni֑⁠y wa⁠ʻàbáde֥y⁠ká bá֖̇ʼẇ li⁠şĕ̌bá̇r-ʼòֽkel׃"],[42,11,"כֻּלָּ֕⁠נוּ בְּנֵ֥י אִישׁ־אֶחָ֖ד נָ֑חְנוּ כֵּנִ֣ים אֲנַ֔חְנוּ לֹא־הָי֥וּ עֲבָדֶ֖י⁠ךָ מְרַגְּלִֽים׃","ku̇lá̇֕⁠nẇ bĕ̇né֥y ʼiyş̌-ʼeẖá֖d ná֑ẖĕnẇ ké̇ni֣ym ʼàna֔ẖĕnẇ lòʼ-háy֥ẇ ʻàbáde֖y⁠ká mĕragĕ̇liֽym׃"],[42,12,"וַ⁠יֹּ֖אמֶר אֲלֵ⁠הֶ֑ם לֹ֕א כִּֽי־עֶרְוַ֥ת הָ⁠אָ֖רֶץ בָּאתֶ֥ם לִ⁠רְאֽוֹת׃","wa⁠yò֖̇ʼmer ʼàlé⁠he֑m lò֕ʼ kiֽ̇y-ʻerĕwa֥ţ há⁠ʼá֖reẕ bá̇ʼţe֥m li⁠rĕʼֽwòţ׃"],[42,13,"וַ⁠יֹּאמְר֗וּ שְׁנֵ֣ים עָשָׂר֩ עֲבָדֶ֨י⁠ךָ אַחִ֧ים ׀ אֲנַ֛חְנוּ בְּנֵ֥י אִישׁ־אֶחָ֖ד בְּ⁠אֶ֣רֶץ כְּנָ֑עַן וְ⁠הִנֵּ֨ה הַ⁠קָּטֹ֤ן אֶת־אָבִ֨י⁠נוּ֙ הַ⁠יּ֔וֹם וְ⁠הָ⁠אֶחָ֖ד אֵינֶֽ⁠נּוּ׃","wa⁠yò̇ʼmĕr֗ẇ şĕ̌né֣ym ʻáşá̂r֩ ʻàbáde֨y⁠ká ʼaẖi֧ym ׀ ʼàna֛ẖĕnẇ bĕ̇né֥y ʼiyş̌-ʼeẖá֖d bĕ̇⁠ʼe֣reẕ kĕ̇ná֑ʻan wĕ⁠hiné̇֨h ha⁠qá̇tò֤n ʼeţ-ʼábi֨y⁠nẇ֙ ha⁠ẏ֔wòm wĕ⁠há⁠ʼeẖá֖d ʼéyneֽ⁠ṅẇ׃"],[42,14,"וַ⁠יֹּ֥אמֶר אֲלֵ⁠הֶ֖ם יוֹסֵ֑ף ה֗וּא אֲשֶׁ֨ר דִּבַּ֧רְתִּי אֲלֵ⁠כֶ֛ם לֵ⁠אמֹ֖ר מְרַגְּלִ֥ים אַתֶּֽם׃","wa⁠yò֥̇ʼmer ʼàlé⁠he֖m ywòsé֑p h֗ẇʼ ʼàşě֨r di̇bȧ֧rĕţi̇y ʼàlé⁠ke֛m lé⁠ʼmò֖r mĕragĕ̇li֥ym ʼaţėֽm׃"],[42,15,"בְּ⁠זֹ֖את תִּבָּחֵ֑נוּ חֵ֤י פַרְעֹה֙ אִם־תֵּצְא֣וּ מִ⁠זֶּ֔ה כִּ֧י אִם־בְּ⁠ב֛וֹא אֲחִי⁠כֶ֥ם הַ⁠קָּטֹ֖ן הֵֽנָּה׃","bĕ̇⁠zò֖ʼţ ţi̇bá̇ẖé֑nẇ ẖé֤y parĕʻòh֙ ʼim-ţé̇ẕĕʼ֣ẇ mi⁠zė֔h ki֧̇y ʼim-bĕ̇⁠b֛wòʼ ʼàẖiy⁠ke֥m ha⁠qá̇tò֖n héֽná̇h׃"],[42,16,"שִׁלְח֨וּ מִ⁠כֶּ֣ם אֶחָד֮ וְ⁠יִקַּ֣ח אֶת־אֲחִי⁠כֶם֒ וְ⁠אַתֶּם֙ הֵאָ֣סְר֔וּ וְ⁠יִבָּֽחֲנוּ֙ דִּבְרֵי⁠כֶ֔ם הַֽ⁠אֱמֶ֖ת אִתְּ⁠כֶ֑ם וְ⁠אִם־לֹ֕א חֵ֣י פַרְעֹ֔ה כִּ֥י מְרַגְּלִ֖ים אַתֶּֽם׃","şǐlĕẖ֨ẇ mi⁠kė֣m ʼeẖád֮ wĕ⁠yiqȧ֣ẖ ʼeţ-ʼàẖiy⁠kem֒ wĕ⁠ʼaţėm֙ héʼá֣sĕr֔ẇ wĕ⁠yibáֽ̇ẖànẇ֙ di̇bĕréy⁠ke֔m haֽ⁠ʼème֖ţ ʼiţĕ̇⁠ke֑m wĕ⁠ʼim-lò֕ʼ ẖé֣y parĕʻò֔h ki֥̇y mĕragĕ̇li֖ym ʼaţėֽm׃"],[42,17,"וַ⁠יֶּאֱסֹ֥ף אֹתָ֛⁠ם אֶל־מִשְׁמָ֖ר שְׁלֹ֥שֶׁת יָמִֽים׃","wa⁠yėʼèsò֥p ʼòţá֛⁠m ʼel-mişĕ̌má֖r şĕ̌lò֥şěţ yámiֽym׃"],[42,18,"וַ⁠יֹּ֨אמֶר אֲלֵ⁠הֶ֤ם יוֹסֵף֙ בַּ⁠יּ֣וֹם הַ⁠שְּׁלִישִׁ֔י זֹ֥את עֲשׂ֖וּ וִֽ⁠חְי֑וּ אֶת־הָ⁠אֱלֹהִ֖ים אֲנִ֥י יָרֵֽא׃","wa⁠yò̇֨ʼmer ʼàlé⁠he֤m ywòsép֙ bȧ⁠ẏ֣wòm ha⁠şĕ̇̌liyşǐ֔y zò֥ʼţ ʻàş֖̂ẇ wiֽ⁠ẖĕy֑ẇ ʼeţ-há⁠ʼèlòhi֖ym ʼàni֥y yáréֽʼ׃"],[42,19,"אִם־כֵּנִ֣ים אַתֶּ֔ם אֲחִי⁠כֶ֣ם אֶחָ֔ד יֵאָסֵ֖ר בְּ⁠בֵ֣ית מִשְׁמַרְ⁠כֶ֑ם וְ⁠אַתֶּם֙ לְכ֣וּ הָבִ֔יאוּ שֶׁ֖בֶר רַעֲב֥וֹן בָּתֵּי⁠כֶֽם׃","ʼim-ké̇ni֣ym ʼaţė֔m ʼàẖiy⁠ke֣m ʼeẖá֔d yéʼásé֖r bĕ̇⁠bé֣yţ mişĕ̌marĕ⁠ke֑m wĕ⁠ʼaţėm֙ lĕk֣ẇ hábi֔yʼẇ şě֖ber raʻàb֥wòn bá̇ţé̇y⁠keֽm׃"],[42,20,"וְ⁠אֶת־אֲחִי⁠כֶ֤ם הַ⁠קָּטֹן֙ תָּבִ֣יאוּ אֵלַ֔⁠י וְ⁠יֵאָמְנ֥וּ דִבְרֵי⁠כֶ֖ם וְ⁠לֹ֣א תָמ֑וּתוּ וַ⁠יַּעֲשׂוּ־כֵֽן׃","wĕ⁠ʼeţ-ʼàẖiy⁠ke֤m ha⁠qá̇tòn֙ ţá̇bi֣yʼẇ ʼéla֔⁠y wĕ⁠yéʼámĕn֥ẇ dibĕréy⁠ke֖m wĕ⁠lò֣ʼ ţám֑ẇţẇ wa⁠yȧʻàş̂ẇ-kéֽn׃"],[42,21,"וַ⁠יֹּאמְר֞וּ אִ֣ישׁ אֶל־אָחִ֗י⁠ו אֲבָל֮ אֲשֵׁמִ֣ים ׀ אֲנַחְנוּ֮ עַל־אָחִי⁠נוּ֒ אֲשֶׁ֨ר רָאִ֜ינוּ צָרַ֥ת נַפְשׁ֛⁠וֹ בְּ⁠הִתְחַֽנְנ֥⁠וֹ אֵלֵ֖י⁠נוּ וְ⁠לֹ֣א שָׁמָ֑עְנוּ עַל־כֵּן֙ בָּ֣אָה אֵלֵ֔י⁠נוּ הַ⁠צָּרָ֖ה הַ⁠זֹּֽאת׃","wa⁠yò̇ʼmĕr֞ẇ ʼi֣yş̌ ʼel-ʼáẖi֗y⁠w ʼàbál֮ ʼàşé̌mi֣ym ׀ ʼànaẖĕnẇ֮ ʻal-ʼáẖiy⁠nẇ֒ ʼàşě֨r ráʼi֜ynẇ ẕára֥ţ napĕş֛̌⁠wò bĕ̇⁠hiţĕẖaֽnĕn֥⁠wò ʼélé֖y⁠nẇ wĕ⁠lò֣ʼ şá̌má֑ʻĕnẇ ʻal-ké̇n֙ bá֣̇ʼáh ʼélé֔y⁠nẇ ha⁠ẕá̇rá֖h ha⁠zòֽ̇ʼţ׃"],[42,22,"וַ⁠יַּעַן֩ רְאוּבֵ֨ן אֹתָ֜⁠ם לֵ⁠אמֹ֗ר הֲ⁠לוֹא֩ אָמַ֨רְתִּי אֲלֵי⁠כֶ֧ם ׀ לֵ⁠אמֹ֛ר אַל־תֶּחֶטְא֥וּ בַ⁠יֶּ֖לֶד וְ⁠לֹ֣א שְׁמַעְתֶּ֑ם וְ⁠גַם־דָּמ֖⁠וֹ הִנֵּ֥ה נִדְרָֽשׁ׃","wa⁠yȧʻan֩ rĕʼẇbé֨n ʼòţá֜⁠m lé⁠ʼmò֗r hà⁠lwòʼ֩ ʼáma֨rĕţi̇y ʼàléy⁠ke֧m ׀ lé⁠ʼmò֛r ʼal-ţėẖetĕʼ֥ẇ ba⁠yė֖led wĕ⁠lò֣ʼ şĕ̌maʻĕţė֑m wĕ⁠gam-dá̇m֖⁠wò hiné֥̇h nidĕráֽş̌׃"],[42,23,"וְ⁠הֵם֙ לֹ֣א יָֽדְע֔וּ כִּ֥י שֹׁמֵ֖עַ יוֹסֵ֑ף כִּ֥י הַ⁠מֵּלִ֖יץ בֵּינֹתָֽ⁠ם׃","wĕ⁠hém֙ lò֣ʼ yֽádĕʻ֔ẇ ki֥̇y şò̌mé֖ʻa ywòsé֑p ki֥̇y ha⁠mé̇li֖yẕ bé̇ynòţáֽ⁠m׃"],[42,24,"וַ⁠יִּסֹּ֥ב מֵֽ⁠עֲלֵי⁠הֶ֖ם וַ⁠יֵּ֑בְךְּ וַ⁠יָּ֤שָׁב אֲלֵ⁠הֶם֙ וַ⁠יְדַבֵּ֣ר אֲלֵ⁠הֶ֔ם וַ⁠יִּקַּ֤ח מֵֽ⁠אִתָּ⁠ם֙ אֶת־שִׁמְע֔וֹן וַ⁠יֶּאֱסֹ֥ר אֹת֖⁠וֹ לְ⁠עֵינֵי⁠הֶֽם׃","wa⁠yi̇sò֥̇b méֽ⁠ʻàléy⁠he֖m wa⁠yé֑̇bĕkĕ̇ wa⁠yá֤̇şá̌b ʼàlé⁠hem֙ wa⁠yĕdabé֣̇r ʼàlé⁠he֔m wa⁠yi̇qȧ֤ẖ méֽ⁠ʼiţá̇⁠m֙ ʼeţ-şǐmĕʻ֔wòn wa⁠yėʼèsò֥r ʼòţ֖⁠wò lĕ⁠ʻéynéy⁠heֽm׃"],[42,25,"וַ⁠יְצַ֣ו יוֹסֵ֗ף וַ⁠יְמַלְא֣וּ אֶת־כְּלֵי⁠הֶם֮ בָּר֒ וּ⁠לְ⁠הָשִׁ֤יב כַּסְפֵּי⁠הֶם֙ אִ֣ישׁ אֶל־שַׂקּ֔⁠וֹ וְ⁠לָ⁠תֵ֥ת לָ⁠הֶ֛ם צֵדָ֖ה לַ⁠דָּ֑רֶךְ וַ⁠יַּ֥עַשׂ לָ⁠הֶ֖ם כֵּֽן׃","wa⁠yĕẕa֣w ywòsé֗p wa⁠yĕmalĕʼ֣ẇ ʼeţ-kĕ̇léy⁠hem֮ bá̇r֒ ẇ⁠lĕ⁠háşǐ֤yb kȧsĕpé̇y⁠hem֙ ʼi֣yş̌ ʼel-şâq̇֔⁠wò wĕ⁠lá⁠ţé֥ţ lá⁠he֛m ẕédá֖h la⁠dá֑̇rekĕ wa⁠yȧ֥ʻaş̂ lá⁠he֖m kéֽ̇n׃"],[42,26,"וַ⁠יִּשְׂא֥וּ אֶת־שִׁבְרָ֖⁠ם עַל־חֲמֹרֵי⁠הֶ֑ם וַ⁠יֵּלְכ֖וּ מִ⁠שָּֽׁם׃","wa⁠yi̇şĕ̂ʼ֥ẇ ʼeţ-şǐbĕrá֖⁠m ʻal-ẖàmòréy⁠he֑m wa⁠yé̇lĕk֖ẇ mi⁠şáֽ̇̌m׃"],[42,27,"וַ⁠יִּפְתַּ֨ח הָ⁠אֶחָ֜ד אֶת־שַׂקּ֗⁠וֹ לָ⁠תֵ֥ת מִסְפּ֛וֹא לַ⁠חֲמֹר֖⁠וֹ בַּ⁠מָּל֑וֹן וַ⁠יַּרְא֙ אֶת־כַּסְפּ֔⁠וֹ וְ⁠הִנֵּה־ה֖וּא בְּ⁠פִ֥י אַמְתַּחְתּֽ⁠וֹ׃","wa⁠yi̇pĕţȧ֨ẖ há⁠ʼeẖá֜d ʼeţ-şâq̇֗⁠wò lá⁠ţé֥ţ misĕṗ֛wòʼ la⁠ẖàmòr֖⁠wò bȧ⁠má̇l֑wòn wa⁠yȧrĕʼ֙ ʼeţ-kȧsĕṗ֔⁠wò wĕ⁠hiné̇h-h֖ẇʼ bĕ̇⁠pi֥y ʼamĕţȧẖĕţֽ̇⁠wò׃"],[42,28,"וַ⁠יֹּ֤אמֶר אֶל־אֶחָי⁠ו֙ הוּשַׁ֣ב כַּסְפִּ֔⁠י וְ⁠גַ֖ם הִנֵּ֣ה בְ⁠אַמְתַּחְתִּ֑⁠י וַ⁠יֵּצֵ֣א לִבָּ֗⁠ם וַ⁠יֶּֽחֶרְד֞וּ אִ֤ישׁ אֶל־אָחִי⁠ו֙ לֵ⁠אמֹ֔ר מַה־זֹּ֛את עָשָׂ֥ה אֱלֹהִ֖ים לָֽ⁠נוּ׃","wa⁠yò֤̇ʼmer ʼel-ʼeẖáy⁠w֙ hẇşǎ֣b kȧsĕpi̇֔⁠y wĕ⁠ga֖m hiné֣̇h bĕ⁠ʼamĕţȧẖĕţi֑̇⁠y wa⁠yé̇ẕé֣ʼ libá̇֗⁠m wa⁠yėֽẖerĕd֞ẇ ʼi֤yş̌ ʼel-ʼáẖiy⁠w֙ lé⁠ʼmò֔r mah-zò֛̇ʼţ ʻáşá֥̂h ʼèlòhi֖ym láֽ⁠nẇ׃"],[42,29,"וַ⁠יָּבֹ֛אוּ אֶל־יַעֲקֹ֥ב אֲבִי⁠הֶ֖ם אַ֣רְצָ⁠ה כְּנָ֑עַן וַ⁠יַּגִּ֣ידוּ ל֔⁠וֹ אֵ֛ת כָּל־הַ⁠קֹּרֹ֥ת אֹתָ֖⁠ם לֵ⁠אמֹֽר׃","wa⁠yá̇bò֛ʼẇ ʼel-yaʻàqò֥b ʼàbiy⁠he֖m ʼa֣rĕẕá⁠h kĕ̇ná֑ʻan wa⁠yȧgi֣̇ydẇ l֔⁠wò ʼé֛ţ ká̇l-ha⁠qò̇rò֥ţ ʼòţá֖⁠m lé⁠ʼmòֽr׃"],[42,30,"דִּ֠בֶּר הָ⁠אִ֨ישׁ אֲדֹנֵ֥י הָ⁠אָ֛רֶץ אִתָּ֖⁠נוּ קָשׁ֑וֹת וַ⁠יִּתֵּ֣ן אֹתָ֔⁠נוּ כִּֽ⁠מְרַגְּלִ֖ים אֶת־הָ⁠אָֽרֶץ׃","di̇֠bėr há⁠ʼi֨yş̌ ʼàdòné֥y há⁠ʼá֛reẕ ʼiţá֖̇⁠nẇ qáş֑̌wòţ wa⁠yi̇ţé֣̇n ʼòţá֔⁠nẇ kiֽ̇⁠mĕragĕ̇li֖ym ʼeţ-há⁠ʼáֽreẕ׃"],[42,31,"וַ⁠נֹּ֥אמֶר אֵלָ֖י⁠ו כֵּנִ֣ים אֲנָ֑חְנוּ לֹ֥א הָיִ֖ינוּ מְרַגְּלִֽים׃","wa⁠nò֥̇ʼmer ʼélá֖y⁠w ké̇ni֣ym ʼàná֑ẖĕnẇ lò֥ʼ háyi֖ynẇ mĕragĕ̇liֽym׃"],[42,32,"שְׁנֵים־עָשָׂ֥ר אֲנַ֛חְנוּ אַחִ֖ים בְּנֵ֣י אָבִ֑י⁠נוּ הָ⁠אֶחָ֣ד אֵינֶ֔⁠נּוּ וְ⁠הַ⁠קָּטֹ֥ן הַ⁠יּ֛וֹם אֶת־אָבִ֖י⁠נוּ בְּ⁠אֶ֥רֶץ כְּנָֽעַן׃","şĕ̌néym-ʻáşá֥̂r ʼàna֛ẖĕnẇ ʼaẖi֖ym bĕ̇né֣y ʼábi֑y⁠nẇ há⁠ʼeẖá֣d ʼéyne֔⁠ṅẇ wĕ⁠ha⁠qá̇tò֥n ha⁠ẏ֛wòm ʼeţ-ʼábi֖y⁠nẇ bĕ̇⁠ʼe֥reẕ kĕ̇náֽʻan׃"],[42,33,"וַ⁠יֹּ֣אמֶר אֵלֵ֗י⁠נוּ הָ⁠אִישׁ֙ אֲדֹנֵ֣י הָ⁠אָ֔רֶץ בְּ⁠זֹ֣את אֵדַ֔ע כִּ֥י כֵנִ֖ים אַתֶּ֑ם אֲחִי⁠כֶ֤ם הָֽ⁠אֶחָד֙ הַנִּ֣יחוּ אִתִּ֔⁠י וְ⁠אֶת־רַעֲב֥וֹן בָּתֵּי⁠כֶ֖ם קְח֥וּ וָ⁠לֵֽכוּ׃","wa⁠yò֣̇ʼmer ʼélé֗y⁠nẇ há⁠ʼiyş̌֙ ʼàdòné֣y há⁠ʼá֔reẕ bĕ̇⁠zò֣ʼţ ʼéda֔ʻ ki֥̇y kéni֖ym ʼaţė֑m ʼàẖiy⁠ke֤m háֽ⁠ʼeẖád֙ hani֣̇yẖẇ ʼiţi̇֔⁠y wĕ⁠ʼeţ-raʻàb֥wòn bá̇ţé̇y⁠ke֖m qĕẖ֥ẇ wá⁠léֽkẇ׃"],[42,34,"וְ֠⁠הָבִיאוּ אֶת־אֲחִי⁠כֶ֣ם הַ⁠קָּטֹן֮ אֵלַ⁠י֒ וְ⁠אֵֽדְעָ֗ה כִּ֣י לֹ֤א מְרַגְּלִים֙ אַתֶּ֔ם כִּ֥י כֵנִ֖ים אַתֶּ֑ם אֶת־אֲחִי⁠כֶם֙ אֶתֵּ֣ן לָ⁠כֶ֔ם וְ⁠אֶת־הָ⁠אָ֖רֶץ תִּסְחָֽרוּ׃","wĕ֠⁠hábiyʼẇ ʼeţ-ʼàẖiy⁠ke֣m ha⁠qá̇tòn֮ ʼéla⁠y֒ wĕ⁠ʼéֽdĕʻá֗h ki֣̇y lò֤ʼ mĕragĕ̇liym֙ ʼaţė֔m ki֥̇y kéni֖ym ʼaţė֑m ʼeţ-ʼàẖiy⁠kem֙ ʼeţé֣̇n lá⁠ke֔m wĕ⁠ʼeţ-há⁠ʼá֖reẕ ţi̇sĕẖáֽrẇ׃"],[42,35,"וַ⁠יְהִ֗י הֵ֚ם מְרִיקִ֣ים שַׂקֵּי⁠הֶ֔ם וְ⁠הִנֵּה־אִ֥ישׁ צְרוֹר־כַּסְפּ֖⁠וֹ בְּ⁠שַׂקּ֑⁠וֹ וַ⁠יִּרְא֞וּ אֶת־צְרֹר֧וֹת כַּסְפֵּי⁠הֶ֛ם הֵ֥מָּה וַ⁠אֲבִי⁠הֶ֖ם וַ⁠יִּירָֽאוּ׃","wa⁠yĕhi֗y hé֚m mĕriyqi֣ym şâqé̇y⁠he֔m wĕ⁠hiné̇h-ʼi֥yş̌ ẕĕrwòr-kȧsĕṗ֖⁠wò bĕ̇⁠şâq֑̇⁠wò wa⁠yi̇rĕʼ֞ẇ ʼeţ-ẕĕròr֧wòţ kȧsĕpé̇y⁠he֛m hé֥má̇h wa⁠ʼàbiy⁠he֖m wa⁠yi̇yráֽʼẇ׃"],[42,36,"וַ⁠יֹּ֤אמֶר אֲלֵ⁠הֶם֙ יַעֲקֹ֣ב אֲבִי⁠הֶ֔ם אֹתִ֖⁠י שִׁכַּלְתֶּ֑ם יוֹסֵ֤ף אֵינֶ֨⁠נּוּ֙ וְ⁠שִׁמְע֣וֹן אֵינֶ֔⁠נּוּ וְ⁠אֶת־בִּנְיָמִ֣ן תִּקָּ֔חוּ עָלַ֖⁠י הָי֥וּ כֻלָּֽ⁠נָה׃","wa⁠yò֤̇ʼmer ʼàlé⁠hem֙ yaʻàqò֣b ʼàbiy⁠he֔m ʼòţi֖⁠y şǐkȧlĕţė֑m ywòsé֤p ʼéyne֨⁠ṅẇ֙ wĕ⁠şǐmĕʻ֣wòn ʼéyne֔⁠ṅẇ wĕ⁠ʼeţ-bi̇nĕyámi֣n ţi̇qá̇֔ẖẇ ʻála֖⁠y háy֥ẇ kuláֽ̇⁠náh׃"],[42,37,"וַ⁠יֹּ֤אמֶר רְאוּבֵן֙ אֶל־אָבִ֣י⁠ו לֵ⁠אמֹ֔ר אֶת־שְׁנֵ֤י בָנַ⁠י֙ תָּמִ֔ית אִם־לֹ֥א אֲבִיאֶ֖⁠נּוּ אֵלֶ֑י⁠ךָ תְּנָ֤⁠ה אֹת⁠וֹ֙ עַל־יָדִ֔⁠י וַ⁠אֲנִ֖י אֲשִׁיבֶ֥⁠נּוּ אֵלֶֽי⁠ךָ׃","wa⁠yò֤̇ʼmer rĕʼẇbén֙ ʼel-ʼábi֣y⁠w lé⁠ʼmò֔r ʼeţ-şĕ̌né֤y bána⁠y֙ ţá̇mi֔yţ ʼim-lò֥ʼ ʼàbiyʼe֖⁠ṅẇ ʼéle֑y⁠ká ţĕ̇ná֤⁠h ʼòţ⁠wò֙ ʻal-yádi֔⁠y wa⁠ʼàni֖y ʼàşǐybe֥⁠ṅẇ ʼéleֽy⁠ká׃"],[42,38,"וַ⁠יֹּ֕אמֶר לֹֽא־יֵרֵ֥ד בְּנִ֖⁠י עִמָּ⁠כֶ֑ם כִּֽי־אָחִ֨י⁠ו מֵ֜ת וְ⁠ה֧וּא לְ⁠בַדּ֣⁠וֹ נִשְׁאָ֗ר וּ⁠קְרָאָ֤⁠הוּ אָסוֹן֙ בַּ⁠דֶּ֨רֶךְ֙ אֲשֶׁ֣ר תֵּֽלְכוּ־בָ֔⁠הּ וְ⁠הוֹרַדְתֶּ֧ם אֶת־שֵׂיבָתִ֛⁠י בְּ⁠יָג֖וֹן שְׁאֽוֹלָ⁠ה׃","wa⁠yò̇֕ʼmer lòֽʼ-yéré֥d bĕ̇ni֖⁠y ʻimá̇⁠ke֑m kiֽ̇y-ʼáẖi֨y⁠w mé֜ţ wĕ⁠h֧ẇʼ lĕ⁠baḋ֣⁠wò nişĕ̌ʼá֗r ẇ⁠qĕráʼá֤⁠hẇ ʼáswòn֙ bȧ⁠dė֨rekĕ֙ ʼàşě֣r ţéֽ̇lĕkẇ-bá֔⁠ḣ wĕ⁠hwòradĕţė֧m ʼeţ-şé̂ybáţi֛⁠y bĕ̇⁠yág֖wòn şĕ̌ʼֽwòlá⁠h׃"],[43,1,"וְ⁠הָ⁠רָעָ֖ב כָּבֵ֥ד בָּ⁠אָֽרֶץ׃","wĕ⁠há⁠ráʻá֖b ká̇bé֥d bá̇⁠ʼáֽreẕ׃"],[43,2,"וַ⁠יְהִ֗י כַּ⁠אֲשֶׁ֤ר כִּלּוּ֙ לֶ⁠אֱכֹ֣ל אֶת־הַ⁠שֶּׁ֔בֶר אֲשֶׁ֥ר הֵבִ֖יאוּ מִ⁠מִּצְרָ֑יִם וַ⁠יֹּ֤אמֶר אֲלֵי⁠הֶם֙ אֲבִי⁠הֶ֔ם שֻׁ֖בוּ שִׁבְרוּ־לָ֥⁠נוּ מְעַט־אֹֽכֶל׃","wa⁠yĕhi֗y kȧ⁠ʼàşě֤r ki̇l̇ẇ֙ le⁠ʼèkò֣l ʼeţ-ha⁠şė̌֔ber ʼàşě֥r hébi֖yʼẇ mi⁠mi̇ẕĕrá֑yim wa⁠yò֤̇ʼmer ʼàléy⁠hem֙ ʼàbiy⁠he֔m şǔ֖bẇ şǐbĕrẇ-lá֥⁠nẇ mĕʻat-ʼòֽkel׃"],[43,3,"וַ⁠יֹּ֧אמֶר אֵלָ֛י⁠ו יְהוּדָ֖ה לֵ⁠אמֹ֑ר הָעֵ֣ד הֵעִד֩ בָּ֨⁠נוּ הָ⁠אִ֤ישׁ לֵ⁠אמֹר֙ לֹֽא־תִרְא֣וּ פָנַ֔⁠י בִּלְתִּ֖י אֲחִי⁠כֶ֥ם אִתְּ⁠כֶֽם׃","wa⁠yò֧̇ʼmer ʼélá֛y⁠w yĕhẇdá֖h lé⁠ʼmò֑r háʻé֣d héʻid֩ bá̇֨⁠nẇ há⁠ʼi֤yş̌ lé⁠ʼmòr֙ lòֽʼ-ţirĕʼ֣ẇ pána֔⁠y bi̇lĕţi֖̇y ʼàẖiy⁠ke֥m ʼiţĕ̇⁠keֽm׃"],[43,4,"אִם־יֶשְׁ⁠ךָ֛ מְשַׁלֵּ֥חַ אֶת־אָחִ֖י⁠נוּ אִתָּ֑⁠נוּ נֵרְדָ֕ה וְ⁠נִשְׁבְּרָ֥ה לְ⁠ךָ֖ אֹֽכֶל׃","ʼim-yeşĕ̌⁠ká֛ mĕşǎlé֥̇ẖa ʼeţ-ʼáẖi֖y⁠nẇ ʼiţá֑̇⁠nẇ nérĕdá֕h wĕ⁠nişĕ̌bĕ̇rá֥h lĕ⁠ká֖ ʼòֽkel׃"],[43,5,"וְ⁠אִם־אֵינְ⁠ךָ֥ מְשַׁלֵּ֖חַ לֹ֣א נֵרֵ֑ד כִּֽי־הָ⁠אִ֞ישׁ אָמַ֤ר אֵלֵ֨י⁠נוּ֙ לֹֽא־תִרְא֣וּ פָנַ֔⁠י בִּלְתִּ֖י אֲחִי⁠כֶ֥ם אִתְּ⁠כֶֽם׃","wĕ⁠ʼim-ʼéynĕ⁠ká֥ mĕşǎlé֖̇ẖa lò֣ʼ néré֑d kiֽ̇y-há⁠ʼi֞yş̌ ʼáma֤r ʼélé֨y⁠nẇ֙ lòֽʼ-ţirĕʼ֣ẇ pána֔⁠y bi̇lĕţi֖̇y ʼàẖiy⁠ke֥m ʼiţĕ̇⁠keֽm׃"],[43,6,"וַ⁠יֹּ֨אמֶר֙ יִשְׂרָאֵ֔ל לָ⁠מָ֥ה הֲרֵעֹתֶ֖ם לִ֑⁠י לְ⁠הַגִּ֣יד לָ⁠אִ֔ישׁ הַ⁠ע֥וֹד לָ⁠כֶ֖ם אָֽח׃","wa⁠yò̇֨ʼmer֙ yişĕ̂ráʼé֔l lá⁠má֥h hàréʻòţe֖m li֑⁠y lĕ⁠hagi֣̇yd lá⁠ʼi֔yş̌ ha⁠ʻ֥wòd lá⁠ke֖m ʼáֽẖ׃"],[43,7,"וַ⁠יֹּאמְר֡וּ שָׁא֣וֹל שָֽׁאַל־הָ֠⁠אִישׁ לָ֣⁠נוּ וּ⁠לְ⁠מֽוֹלַדְתֵּ֜⁠נוּ לֵ⁠אמֹ֗ר הַ⁠ע֨וֹד אֲבִי⁠כֶ֥ם חַי֙ הֲ⁠יֵ֣שׁ לָ⁠כֶ֣ם אָ֔ח וַ⁠נַ֨גֶּד־ל֔⁠וֹ עַל־פִּ֖י הַ⁠דְּבָרִ֣ים הָ⁠אֵ֑לֶּה הֲ⁠יָד֣וֹעַ נֵדַ֔ע כִּ֣י יֹאמַ֔ר הוֹרִ֖ידוּ אֶת־אֲחִי⁠כֶֽם׃","wa⁠yò̇ʼmĕr֡ẇ şá̌ʼ֣wòl şáֽ̌ʼal-há֠⁠ʼiyş̌ lá֣⁠nẇ ẇ⁠lĕ⁠mֽwòladĕţé̇֜⁠nẇ lé⁠ʼmò֗r ha⁠ʻ֨wòd ʼàbiy⁠ke֥m ẖay֙ hà⁠yé֣ş̌ lá⁠ke֣m ʼá֔ẖ wa⁠na֨gėd-l֔⁠wò ʻal-pi֖̇y ha⁠dĕ̇bári֣ym há⁠ʼé֑lėh hà⁠yád֣wòʻa néda֔ʻ ki֣̇y yòʼma֔r hwòri֖ydẇ ʼeţ-ʼàẖiy⁠keֽm׃"],[43,8,"וַ⁠יֹּ֨אמֶר יְהוּדָ֜ה אֶל־יִשְׂרָאֵ֣ל אָבִ֗י⁠ו שִׁלְחָ֥⁠ה הַ⁠נַּ֛עַר אִתִּ֖⁠י וְ⁠נָק֣וּמָה וְ⁠נֵלֵ֑כָה וְ⁠נִֽחְיֶה֙ וְ⁠לֹ֣א נָמ֔וּת גַּם־אֲנַ֥חְנוּ גַם־אַתָּ֖ה גַּם־טַפֵּֽ⁠נוּ׃","wa⁠yò̇֨ʼmer yĕhẇdá֜h ʼel-yişĕ̂ráʼé֣l ʼábi֗y⁠w şǐlĕẖá֥⁠h ha⁠nȧ֛ʻar ʼiţi֖̇⁠y wĕ⁠náq֣ẇmáh wĕ⁠nélé֑káh wĕ⁠niֽẖĕyeh֙ wĕ⁠lò֣ʼ nám֔ẇţ gȧm-ʼàna֥ẖĕnẇ gam-ʼaţá֖̇h gȧm-tapéֽ̇⁠nẇ׃"],[43,9,"אָֽנֹכִי֙ אֶֽעֶרְבֶ֔⁠נּוּ מִ⁠יָּדִ֖⁠י תְּבַקְשֶׁ֑⁠נּוּ אִם־לֹ֨א הֲבִיאֹתִ֤י⁠ו אֵלֶ֨י⁠ךָ֙ וְ⁠הִצַּגְתִּ֣י⁠ו לְ⁠פָנֶ֔י⁠ךָ וְ⁠חָטָ֥אתִֽי לְ⁠ךָ֖ כָּל־הַ⁠יָּמִֽים׃","ʼáֽnòkiy֙ ʼֽeʻerĕbe֔⁠ṅẇ mi⁠yá̇di֖⁠y ţĕ̇baqĕşě֑⁠ṅẇ ʼim-lò֨ʼ hàbiyʼòţi֤y⁠w ʼéle֨y⁠ká֙ wĕ⁠hiẕȧgĕţi֣̇y⁠w lĕ⁠páne֔y⁠ká wĕ⁠ẖátá֥ʼţiֽy lĕ⁠ká֖ ká̇l-ha⁠yá̇miֽym׃"],[43,10,"כִּ֖י לוּלֵ֣א הִתְמַהְמָ֑הְנוּ כִּֽי־עַתָּ֥ה שַׁ֖בְנוּ זֶ֥ה פַעֲמָֽיִם׃","ki֖̇y lẇlé֣ʼ hiţĕmahĕmá֑hĕnẇ kiֽ̇y-ʻaţá֥̇h şǎ֖bĕnẇ ze֥h paʻàmáֽyim׃"],[43,11,"וַ⁠יֹּ֨אמֶר אֲלֵ⁠הֶ֜ם יִשְׂרָאֵ֣ל אֲבִי⁠הֶ֗ם אִם־כֵּ֣ן ׀ אֵפוֹא֮ זֹ֣את עֲשׂוּ֒ קְח֞וּ מִ⁠זִּמְרַ֤ת הָ⁠אָ֨רֶץ֙ בִּ⁠כְלֵי⁠כֶ֔ם וְ⁠הוֹרִ֥ידוּ לָ⁠אִ֖ישׁ מִנְחָ֑ה מְעַ֤ט צֳרִי֙ וּ⁠מְעַ֣ט דְּבַ֔שׁ נְכֹ֣את וָ⁠לֹ֔ט בָּטְנִ֖ים וּ⁠שְׁקֵדִֽים׃","wa⁠yò̇֨ʼmer ʼàlé⁠he֜m yişĕ̂ráʼé֣l ʼàbiy⁠he֗m ʼim-ké֣̇n ׀ ʼépwòʼ֮ zò֣ʼţ ʻàş̂ẇ֒ qĕẖ֞ẇ mi⁠zi̇mĕra֤ţ há⁠ʼá֨reẕ֙ bi̇⁠kĕléy⁠ke֔m wĕ⁠hwòri֥ydẇ lá⁠ʼi֖yş̌ minĕẖá֑h mĕʻa֤t ẕoriy֙ ẇ⁠mĕʻa֣t dĕ̇ba֔ş̌ nĕkò֣ʼţ wá⁠lò֔t bá̇tĕni֖ym ẇ⁠şĕ̌qédiֽym׃"],[43,12,"וְ⁠כֶ֥סֶף מִשְׁנֶ֖ה קְח֣וּ בְ⁠יֶדְ⁠כֶ֑ם וְ⁠אֶת־הַ⁠כֶּ֜סֶף הַ⁠מּוּשָׁ֨ב בְּ⁠פִ֤י אַמְתְּחֹֽתֵי⁠כֶם֙ תָּשִׁ֣יבוּ בְ⁠יֶדְ⁠כֶ֔ם אוּלַ֥י מִשְׁגֶּ֖ה הֽוּא׃","wĕ⁠ke֥sep mişĕ̌ne֖h qĕẖ֣ẇ bĕ⁠yedĕ⁠ke֑m wĕ⁠ʼeţ-ha⁠kė֜sep ha⁠ṁẇşá̌֨b bĕ̇⁠pi֤y ʼamĕţĕ̇ẖòֽţéy⁠kem֙ ţá̇şǐ֣ybẇ bĕ⁠yedĕ⁠ke֔m ʼẇla֥y mişĕ̌gė֖h hֽẇʼ׃"],[43,13,"וְ⁠אֶת־אֲחִי⁠כֶ֖ם קָ֑חוּ וְ⁠ק֖וּמוּ שׁ֥וּבוּ אֶל־הָ⁠אִֽישׁ׃","wĕ⁠ʼeţ-ʼàẖiy⁠ke֖m qá֑ẖẇ wĕ⁠q֖ẇmẇ ş֥̌ẇbẇ ʼel-há⁠ʼiֽyş̌׃"],[43,14,"וְ⁠אֵ֣ל שַׁדַּ֗י יִתֵּ֨ן לָ⁠כֶ֤ם רַחֲמִים֙ לִ⁠פְנֵ֣י הָ⁠אִ֔ישׁ וְ⁠שִׁלַּ֥ח לָ⁠כֶ֛ם אֶת־אֲחִי⁠כֶ֥ם אַחֵ֖ר וְ⁠אֶת־בִּנְיָמִ֑ין וַ⁠אֲנִ֕י כַּ⁠אֲשֶׁ֥ר שָׁכֹ֖לְתִּי שָׁכָֽלְתִּי׃","wĕ⁠ʼé֣l şǎdȧ֗y yiţé̇֨n lá⁠ke֤m raẖàmiym֙ li⁠pĕné֣y há⁠ʼi֔yş̌ wĕ⁠şǐlȧ֥ẖ lá⁠ke֛m ʼeţ-ʼàẖiy⁠ke֥m ʼaẖé֖r wĕ⁠ʼeţ-bi̇nĕyámi֑yn wa⁠ʼàni֕y kȧ⁠ʼàşě֥r şá̌kò֖lĕţi̇y şá̌káֽlĕţi̇y׃"],[43,15,"וַ⁠יִּקְח֤וּ הָֽ⁠אֲנָשִׁים֙ אֶת־הַ⁠מִּנְחָ֣ה הַ⁠זֹּ֔את וּ⁠מִשְׁנֶה־כֶּ֛סֶף לָקְח֥וּ בְ⁠יָדָ֖⁠ם וְ⁠אֶת־בִּנְיָמִ֑ן וַ⁠יָּקֻ֨מוּ֙ וַ⁠יֵּרְד֣וּ מִצְרַ֔יִם וַ⁠יַּֽעַמְד֖וּ לִ⁠פְנֵ֥י יוֹסֵֽף׃","wa⁠yi̇qĕẖ֤ẇ háֽ⁠ʼànáşǐym֙ ʼeţ-ha⁠mi̇nĕẖá֣h ha⁠zò̇֔ʼţ ẇ⁠mişĕ̌neh-kė֛sep láqĕẖ֥ẇ bĕ⁠yádá֖⁠m wĕ⁠ʼeţ-bi̇nĕyámi֑n wa⁠yá̇qu֨mẇ֙ wa⁠yé̇rĕd֣ẇ miẕĕra֔yim wa⁠yȧֽʻamĕd֖ẇ li⁠pĕné֥y ywòséֽp׃"],[43,16,"וַ⁠יַּ֨רְא יוֹסֵ֣ף אִתָּ⁠ם֮ אֶת־בִּנְיָמִין֒ וַ⁠יֹּ֨אמֶר֙ לַֽ⁠אֲשֶׁ֣ר עַל־בֵּית֔⁠וֹ הָבֵ֥א אֶת־הָ⁠אֲנָשִׁ֖ים הַ⁠בָּ֑יְתָ⁠ה וּ⁠טְבֹ֤חַ טֶ֨בַח֙ וְ⁠הָכֵ֔ן כִּ֥י אִתִּ֛⁠י יֹאכְל֥וּ הָ⁠אֲנָשִׁ֖ים בַּֽ⁠צָּהֳרָֽיִם׃","wa⁠yȧ֨rĕʼ ywòsé֣p ʼiţá̇⁠m֮ ʼeţ-bi̇nĕyámiyn֒ wa⁠yò̇֨ʼmer֙ laֽ⁠ʼàşě֣r ʻal-bé̇yţ֔⁠wò hábé֥ʼ ʼeţ-há⁠ʼànáşǐ֖ym ha⁠bá֑̇yĕţá⁠h ẇ⁠tĕbò֤ẖa te֨baẖ֙ wĕ⁠háké֔n ki֥̇y ʼiţi֛̇⁠y yòʼkĕl֥ẇ há⁠ʼànáşǐ֖ym bȧֽ⁠ẕá̇horáֽyim׃"],[43,17,"וַ⁠יַּ֣עַשׂ הָ⁠אִ֔ישׁ כַּֽ⁠אֲשֶׁ֖ר אָמַ֣ר יוֹסֵ֑ף וַ⁠יָּבֵ֥א הָ⁠אִ֛ישׁ אֶת־הָ⁠אֲנָשִׁ֖ים בֵּ֥יתָ⁠ה יוֹסֵֽף׃","wa⁠yȧ֣ʻaş̂ há⁠ʼi֔yş̌ kȧֽ⁠ʼàşě֖r ʼáma֣r ywòsé֑p wa⁠yá̇bé֥ʼ há⁠ʼi֛yş̌ ʼeţ-há⁠ʼànáşǐ֖ym bé֥̇yţá⁠h ywòséֽp׃"],[43,18,"וַ⁠יִּֽירְא֣וּ הָֽ⁠אֲנָשִׁ֗ים כִּ֣י הֽוּבְאוּ֮ בֵּ֣ית יוֹסֵף֒ וַ⁠יֹּאמְר֗וּ עַל־דְּבַ֤ר הַ⁠כֶּ֨סֶף֙ הַ⁠שָּׁ֤ב בְּ⁠אַמְתְּחֹתֵ֨י⁠נוּ֙ בַּ⁠תְּחִלָּ֔ה אֲנַ֖חְנוּ מֽוּבָאִ֑ים לְ⁠הִתְגֹּלֵ֤ל עָלֵ֨י⁠נוּ֙ וּ⁠לְ⁠הִתְנַפֵּ֣ל עָלֵ֔י⁠נוּ וְ⁠לָ⁠קַ֧חַת אֹתָ֛⁠נוּ לַ⁠עֲבָדִ֖ים וְ⁠אֶת־חֲמֹרֵֽי⁠נוּ׃","wa⁠yiֽ̇yrĕʼ֣ẇ háֽ⁠ʼànáşǐ֗ym ki֣̇y hֽẇbĕʼẇ֮ bé֣̇yţ ywòsép֒ wa⁠yò̇ʼmĕr֗ẇ ʻal-dĕ̇ba֤r ha⁠kė֨sep֙ ha⁠şá֤̇̌b bĕ̇⁠ʼamĕţĕ̇ẖòţé֨y⁠nẇ֙ bȧ⁠ţĕ̇ẖilá̇֔h ʼàna֖ẖĕnẇ mֽẇbáʼi֑ym lĕ⁠hiţĕgò̇lé֤l ʻálé֨y⁠nẇ֙ ẇ⁠lĕ⁠hiţĕnapé֣̇l ʻálé֔y⁠nẇ wĕ⁠lá⁠qa֧ẖaţ ʼòţá֛⁠nẇ la⁠ʻàbádi֖ym wĕ⁠ʼeţ-ẖàmòréֽy⁠nẇ׃"],[43,19,"וַֽ⁠יִּגְּשׁוּ֙ אֶל־הָ⁠אִ֔ישׁ אֲשֶׁ֖ר עַל־בֵּ֣ית יוֹסֵ֑ף וַ⁠יְדַבְּר֥וּ אֵלָ֖י⁠ו פֶּ֥תַח הַ⁠בָּֽיִת׃","waֽ⁠yi̇gĕ̇ş̌ẇ֙ ʼel-há⁠ʼi֔yş̌ ʼàşě֖r ʻal-bé֣̇yţ ywòsé֑p wa⁠yĕdabĕ̇r֥ẇ ʼélá֖y⁠w pė֥ţaẖ ha⁠báֽ̇yiţ׃"],[43,20,"וַ⁠יֹּאמְר֖וּ בִּ֣י אֲדֹנִ֑⁠י יָרֹ֥ד יָרַ֛דְנוּ בַּ⁠תְּחִלָּ֖ה לִ⁠שְׁבָּר־אֹֽכֶל׃","wa⁠yò̇ʼmĕr֖ẇ bi֣̇y ʼàdòni֑⁠y yárò֥d yára֛dĕnẇ bȧ⁠ţĕ̇ẖilá֖̇h li⁠şĕ̌bá̇r-ʼòֽkel׃"],[43,21,"וַֽ⁠יְהִ֞י כִּי־בָ֣אנוּ אֶל־הַ⁠מָּל֗וֹן וַֽ⁠נִּפְתְּחָ⁠ה֙ אֶת־אַמְתְּחֹתֵ֔י⁠נוּ וְ⁠הִנֵּ֤ה כֶֽסֶף־אִישׁ֙ בְּ⁠פִ֣י אַמְתַּחְתּ֔⁠וֹ כַּסְפֵּ֖⁠נוּ בְּ⁠מִשְׁקָל֑⁠וֹ וַ⁠נָּ֥שֶׁב אֹת֖⁠וֹ בְּ⁠יָדֵֽ⁠נוּ׃","waֽ⁠yĕhi֞y ki̇y-bá֣ʼnẇ ʼel-ha⁠má̇l֗wòn waֽ⁠ni̇pĕţĕ̇ẖá⁠h֙ ʼeţ-ʼamĕţĕ̇ẖòţé֔y⁠nẇ wĕ⁠hiné֤̇h keֽsep-ʼiyş̌֙ bĕ̇⁠pi֣y ʼamĕţȧẖĕţ̇֔⁠wò kȧsĕpé֖̇⁠nẇ bĕ̇⁠mişĕ̌qál֑⁠wò wa⁠ná֥̇şěb ʼòţ֖⁠wò bĕ̇⁠yádéֽ⁠nẇ׃"],[43,22,"וְ⁠כֶ֧סֶף אַחֵ֛ר הוֹרַ֥דְנוּ בְ⁠יָדֵ֖⁠נוּ לִ⁠שְׁבָּר־אֹ֑כֶל לֹ֣א יָדַ֔עְנוּ מִי־שָׂ֥ם כַּסְפֵּ֖⁠נוּ בְּ⁠אַמְתְּחֹתֵֽי⁠נוּ׃","wĕ⁠ke֧sep ʼaẖé֛r hwòra֥dĕnẇ bĕ⁠yádé֖⁠nẇ li⁠şĕ̌bá̇r-ʼò֑kel lò֣ʼ yáda֔ʻĕnẇ miy-şá֥̂m kȧsĕpé֖̇⁠nẇ bĕ̇⁠ʼamĕţĕ̇ẖòţéֽy⁠nẇ׃"],[43,23,"וַ⁠יֹּאמֶר֩ שָׁל֨וֹם לָ⁠כֶ֜ם אַל־תִּירָ֗אוּ אֱלֹ֨הֵי⁠כֶ֜ם וֵֽ⁠אלֹהֵ֤י אֲבִי⁠כֶם֙ נָתַ֨ן לָ⁠כֶ֤ם מַטְמוֹן֙ בְּ⁠אַמְתְּחֹ֣תֵי⁠כֶ֔ם כַּסְפְּ⁠כֶ֖ם בָּ֣א אֵלָ֑⁠י וַ⁠יּוֹצֵ֥א אֲלֵ⁠הֶ֖ם אֶת־שִׁמְעֽוֹן׃","wa⁠yò̇ʼmer֩ şá̌l֨wòm lá⁠ke֜m ʼal-ţi̇yrá֗ʼẇ ʼèlò֨héy⁠ke֜m wֽé⁠ʼlòhé֤y ʼàbiy⁠kem֙ náţa֨n lá⁠ke֤m matĕmwòn֙ bĕ̇⁠ʼamĕţĕ̇ẖò֣ţéy⁠ke֔m kȧsĕpĕ̇⁠ke֖m bá֣̇ʼ ʼélá֑⁠y wa⁠ẏwòẕé֥ʼ ʼàlé⁠he֖m ʼeţ-şǐmĕʻֽwòn׃"],[43,24,"וַ⁠יָּבֵ֥א הָ⁠אִ֛ישׁ אֶת־הָ⁠אֲנָשִׁ֖ים בֵּ֣יתָ⁠ה יוֹסֵ֑ף וַ⁠יִּתֶּן־מַ֨יִם֙ וַ⁠יִּרְחֲצ֣וּ רַגְלֵי⁠הֶ֔ם וַ⁠יִּתֵּ֥ן מִסְפּ֖וֹא לַ⁠חֲמֹֽרֵי⁠הֶֽם׃","wa⁠yá̇bé֥ʼ há⁠ʼi֛yş̌ ʼeţ-há⁠ʼànáşǐ֖ym bé֣̇yţá⁠h ywòsé֑p wa⁠yi̇ţėn-ma֨yim֙ wa⁠yi̇rĕẖàẕ֣ẇ ragĕléy⁠he֔m wa⁠yi̇ţé֥̇n misĕṗ֖wòʼ la⁠ẖàmòֽréy⁠heֽm׃"],[43,25,"וַ⁠יָּכִ֨ינוּ֙ אֶת־הַ⁠מִּנְחָ֔ה עַד־בּ֥וֹא יוֹסֵ֖ף בַּֽ⁠צָּהֳרָ֑יִם כִּ֣י שָֽׁמְע֔וּ כִּי־שָׁ֖ם יֹ֥אכְלוּ לָֽחֶם׃","wa⁠yá̇ki֨ynẇ֙ ʼeţ-ha⁠mi̇nĕẖá֔h ʻad-ḃ֥wòʼ ywòsé֖p bȧֽ⁠ẕá̇horá֑yim ki֣̇y şáֽ̌mĕʻ֔ẇ ki̇y-şá֖̌m yò֥ʼkĕlẇ láֽẖem׃"],[43,26,"וַ⁠יָּבֹ֤א יוֹסֵף֙ הַ⁠בַּ֔יְתָ⁠ה וַ⁠יָּבִ֥יאּוּ ל֛⁠וֹ אֶת־הַ⁠מִּנְחָ֥ה אֲשֶׁר־בְּ⁠יָדָ֖⁠ם הַ⁠בָּ֑יְתָ⁠ה וַ⁠יִּשְׁתַּחֲווּ־ל֖⁠וֹ אָֽרְצָ⁠ה׃","wa⁠yá̇bò֤ʼ ywòsép֙ ha⁠bȧ֔yĕţá⁠h wa⁠yá̇bi֥yʼ̇ẇ l֛⁠wò ʼeţ-ha⁠mi̇nĕẖá֥h ʼàşěr-bĕ̇⁠yádá֖⁠m ha⁠bá֑̇yĕţá⁠h wa⁠yi̇şĕ̌ţȧẖàwẇ-l֖⁠wò ʼáֽrĕẕá⁠h׃"],[43,27,"וַ⁠יִּשְׁאַ֤ל לָ⁠הֶם֙ לְ⁠שָׁל֔וֹם וַ⁠יֹּ֗אמֶר הֲ⁠שָׁל֛וֹם אֲבִי⁠כֶ֥ם הַ⁠זָּקֵ֖ן אֲשֶׁ֣ר אֲמַרְתֶּ֑ם הַ⁠עוֹדֶ֖⁠נּוּ חָֽי׃","wa⁠yi̇şĕ̌ʼa֤l lá⁠hem֙ lĕ⁠şá̌l֔wòm wa⁠yò̇֗ʼmer hà⁠şá̌l֛wòm ʼàbiy⁠ke֥m ha⁠zá̇qé֖n ʼàşě֣r ʼàmarĕţė֑m ha⁠ʻwòde֖⁠ṅẇ ẖáֽy׃"],[43,28,"וַ⁠יֹּאמְר֗וּ שָׁל֛וֹם לְ⁠עַבְדְּ⁠ךָ֥ לְ⁠אָבִ֖י⁠נוּ עוֹדֶ֣⁠נּוּ חָ֑י וַֽ⁠יִּקְּד֖וּ ו⁠ישתחו׃","wa⁠yò̇ʼmĕr֗ẇ şá̌l֛wòm lĕ⁠ʻabĕdĕ̇⁠ká֥ lĕ⁠ʼábi֖y⁠nẇ ʻwòde֣⁠ṅẇ ẖá֑y waֽ⁠yi̇qĕ̇d֖ẇ w⁠yşţẖw׃"],[43,29,"וַ⁠יִּשָּׂ֣א עֵינָ֗י⁠ו וַ⁠יַּ֞רְא אֶת־בִּנְיָמִ֣ין אָחִי⁠ו֮ בֶּן־אִמּ⁠וֹ֒ וַ⁠יֹּ֗אמֶר הֲ⁠זֶה֙ אֲחִי⁠כֶ֣ם הַ⁠קָּטֹ֔ן אֲשֶׁ֥ר אֲמַרְתֶּ֖ם אֵלָ֑⁠י וַ⁠יֹּאמַ֕ר אֱלֹהִ֥ים יָחְנְ⁠ךָ֖ בְּנִֽ⁠י׃","wa⁠yi̇şá֣̇̂ʼ ʻéyná֗y⁠w wa⁠yȧ֞rĕʼ ʼeţ-bi̇nĕyámi֣yn ʼáẖiy⁠w֮ bėn-ʼiṁ⁠wò֒ wa⁠yò̇֗ʼmer hà⁠zeh֙ ʼàẖiy⁠ke֣m ha⁠qá̇tò֔n ʼàşě֥r ʼàmarĕţė֖m ʼélá֑⁠y wa⁠yò̇ʼma֕r ʼèlòhi֥ym yáẖĕnĕ⁠ká֖ bĕ̇niֽ⁠y׃"],[43,30,"וַ⁠יְמַהֵ֣ר יוֹסֵ֗ף כִּֽי־נִכְמְר֤וּ רַחֲמָי⁠ו֙ אֶל־אָחִ֔י⁠ו וַ⁠יְבַקֵּ֖שׁ לִ⁠בְכּ֑וֹת וַ⁠יָּבֹ֥א הַ⁠חַ֖דְרָ⁠ה וַ⁠יֵּ֥בְךְּ שָֽׁמָּ⁠ה׃","wa⁠yĕmahé֣r ywòsé֗p kiֽ̇y-nikĕmĕr֤ẇ raẖàmáy⁠w֙ ʼel-ʼáẖi֔y⁠w wa⁠yĕbaqé֖̇ş̌ li⁠bĕk֑̇wòţ wa⁠yá̇bò֥ʼ ha⁠ẖa֖dĕrá⁠h wa⁠yé֥̇bĕkĕ̇ şáֽ̌má̇⁠h׃"],[43,31,"וַ⁠יִּרְחַ֥ץ פָּנָ֖י⁠ו וַ⁠יֵּצֵ֑א וַ⁠יִּ֨תְאַפַּ֔ק וַ⁠יֹּ֖אמֶר שִׂ֥ימוּ לָֽחֶם׃","wa⁠yi̇rĕẖa֥ẕ pá̇ná֖y⁠w wa⁠yé̇ẕé֑ʼ wa⁠yi̇֨ţĕʼapȧ֔q wa⁠yò֖̇ʼmer şî֥ymẇ láֽẖem׃"],[43,32,"וַ⁠יָּשִׂ֥ימוּ ל֛⁠וֹ לְ⁠בַדּ֖⁠וֹ וְ⁠לָ⁠הֶ֣ם לְ⁠בַדָּ֑⁠ם וְ⁠לַ⁠מִּצְרִ֞ים הָ⁠אֹכְלִ֤ים אִתּ⁠וֹ֙ לְ⁠בַדָּ֔⁠ם כִּי֩ לֹ֨א יוּכְל֜וּ⁠ן הַ⁠מִּצְרִ֗ים לֶ⁠אֱכֹ֤ל אֶת־הָֽ⁠עִבְרִים֙ לֶ֔חֶם כִּי־תוֹעֵבָ֥ה הִ֖וא לְ⁠מִצְרָֽיִם׃","wa⁠yá̇şî֥ymẇ l֛⁠wò lĕ⁠baḋ֖⁠wò wĕ⁠lá⁠he֣m lĕ⁠badá֑̇⁠m wĕ⁠la⁠mi̇ẕĕri֞ym há⁠ʼòkĕli֤ym ʼiţ̇⁠wò֙ lĕ⁠badá̇֔⁠m ki̇y֩ lò֨ʼ yẇkĕl֜ẇ⁠n ha⁠mi̇ẕĕri֗ym le⁠ʼèkò֤l ʼeţ-háֽ⁠ʻibĕriym֙ le֔ẖem ki̇y-ţwòʻébá֥h hi֖wʼ lĕ⁠miẕĕráֽyim׃"],[43,33,"וַ⁠יֵּשְׁב֣וּ לְ⁠פָנָ֔י⁠ו הַ⁠בְּכֹר֙ כִּ⁠בְכֹ֣רָת֔⁠וֹ וְ⁠הַ⁠צָּעִ֖יר כִּ⁠צְעִרָת֑⁠וֹ וַ⁠יִּתְמְה֥וּ הָ⁠אֲנָשִׁ֖ים אִ֥ישׁ אֶל־רֵעֵֽ⁠הוּ׃","wa⁠yé̇şĕ̌b֣ẇ lĕ⁠páná֔y⁠w ha⁠bĕ̇kòr֙ ki̇⁠bĕkò֣ráţ֔⁠wò wĕ⁠ha⁠ẕá̇ʻi֖yr ki̇⁠ẕĕʻiráţ֑⁠wò wa⁠yi̇ţĕmĕh֥ẇ há⁠ʼànáşǐ֖ym ʼi֥yş̌ ʼel-réʻéֽ⁠hẇ׃"],[43,34,"וַ⁠יִּשָּׂ֨א מַשְׂאֹ֜ת מֵ⁠אֵ֣ת פָּנָי⁠ו֮ אֲלֵ⁠הֶם֒ וַ⁠תֵּ֜רֶב מַשְׂאַ֧ת בִּנְיָמִ֛ן מִ⁠מַּשְׂאֹ֥ת כֻּלָּ֖⁠ם חָמֵ֣שׁ יָד֑וֹת וַ⁠יִּשְׁתּ֥וּ וַֽ⁠יִּשְׁכְּר֖וּ עִמּֽ⁠וֹ׃","wa⁠yi̇şá̇̂֨ʼ maşĕ̂ʼò֜ţ mé⁠ʼé֣ţ pá̇náy⁠w֮ ʼàlé⁠hem֒ wa⁠ţé̇֜reb maşĕ̂ʼa֧ţ bi̇nĕyámi֛n mi⁠mȧşĕ̂ʼò֥ţ ku̇lá֖̇⁠m ẖámé֣ş̌ yád֑wòţ wa⁠yi̇şĕ̌ţ֥̇ẇ waֽ⁠yi̇şĕ̌kĕ̇r֖ẇ ʻiṁֽ⁠wò׃"],[44,1,"וַ⁠יְצַ֞ו אֶת־אֲשֶׁ֣ר עַל־בֵּית⁠וֹ֮ לֵ⁠אמֹר֒ מַלֵּ֞א אֶת־אַמְתְּחֹ֤ת הָֽ⁠אֲנָשִׁים֙ אֹ֔כֶל כַּ⁠אֲשֶׁ֥ר יוּכְל֖וּ⁠ן שְׂאֵ֑ת וְ⁠שִׂ֥ים כֶּֽסֶף־אִ֖ישׁ בְּ⁠פִ֥י אַמְתַּחְתּֽ⁠וֹ׃","wa⁠yĕẕa֞w ʼeţ-ʼàşě֣r ʻal-bé̇yţ⁠wò֮ lé⁠ʼmòr֒ malé̇֞ʼ ʼeţ-ʼamĕţĕ̇ẖò֤ţ háֽ⁠ʼànáşǐym֙ ʼò֔kel kȧ⁠ʼàşě֥r yẇkĕl֖ẇ⁠n şĕ̂ʼé֑ţ wĕ⁠şî֥ym kėֽsep-ʼi֖yş̌ bĕ̇⁠pi֥y ʼamĕţȧẖĕţֽ̇⁠wò׃"],[44,2,"וְ⁠אֶת־גְּבִיעִ֞⁠י גְּבִ֣יעַ הַ⁠כֶּ֗סֶף תָּשִׂים֙ בְּ⁠פִי֙ אַמְתַּ֣חַת הַ⁠קָּטֹ֔ן וְ⁠אֵ֖ת כֶּ֣סֶף שִׁבְר֑⁠וֹ וַ⁠יַּ֕עַשׂ כִּ⁠דְבַ֥ר יוֹסֵ֖ף אֲשֶׁ֥ר דִּבֵּֽר׃","wĕ⁠ʼeţ-gĕ̇biyʻi֞⁠y gĕ̇bi֣yʻa ha⁠kė֗sep ţá̇şîym֙ bĕ̇⁠piy֙ ʼamĕţȧ֣ẖaţ ha⁠qá̇tò֔n wĕ⁠ʼé֖ţ kė֣sep şǐbĕr֑⁠wò wa⁠yȧ֕ʻaş̂ ki̇⁠dĕba֥r ywòsé֖p ʼàşě֥r di̇béֽ̇r׃"],[44,3,"הַ⁠בֹּ֖קֶר א֑וֹר וְ⁠הָ⁠אֲנָשִׁ֣ים שֻׁלְּח֔וּ הֵ֖מָּה וַ⁠חֲמֹרֵי⁠הֶֽם׃","ha⁠bò֖̇qer ʼ֑wòr wĕ⁠há⁠ʼànáşǐ֣ym şǔlĕ̇ẖ֔ẇ hé֖má̇h wa⁠ẖàmòréy⁠heֽm׃"],[44,4,"הֵ֠ם יָֽצְא֣וּ אֶת־הָ⁠עִיר֮ לֹ֣א הִרְחִיקוּ֒ וְ⁠יוֹסֵ֤ף אָמַר֙ לַֽ⁠אֲשֶׁ֣ר עַל־בֵּית֔⁠וֹ ק֥וּם רְדֹ֖ף אַחֲרֵ֣י הָֽ⁠אֲנָשִׁ֑ים וְ⁠הִשַּׂגְתָּ⁠ם֙ וְ⁠אָמַרְתָּ֣ אֲלֵ⁠הֶ֔ם לָ֛⁠מָּה שִׁלַּמְתֶּ֥ם רָעָ֖ה תַּ֥חַת טוֹבָֽה׃","hé֠m yáֽẕĕʼ֣ẇ ʼeţ-há⁠ʻiyr֮ lò֣ʼ hirĕẖiyqẇ֒ wĕ⁠ywòsé֤p ʼámar֙ laֽ⁠ʼàşě֣r ʻal-bé̇yţ֔⁠wò q֥ẇm rĕdò֖p ʼaẖàré֣y háֽ⁠ʼànáşǐ֑ym wĕ⁠hişȧ̂gĕţá̇⁠m֙ wĕ⁠ʼámarĕţá֣̇ ʼàlé⁠he֔m lá֛⁠má̇h şǐlȧmĕţė֥m ráʻá֖h ţȧ֥ẖaţ twòbáֽh׃"],[44,5,"הֲ⁠ל֣וֹא זֶ֗ה אֲשֶׁ֨ר יִשְׁתֶּ֤ה אֲדֹנִ⁠י֙ בּ֔⁠וֹ וְ⁠ה֕וּא נַחֵ֥שׁ יְנַחֵ֖שׁ בּ֑⁠וֹ הֲרֵעֹתֶ֖ם אֲשֶׁ֥ר עֲשִׂיתֶֽם׃","hà⁠l֣wòʼ ze֗h ʼàşě֨r yişĕ̌ţė֤h ʼàdòni⁠y֙ ḃ֔⁠wò wĕ⁠h֕ẇʼ naẖé֥ş̌ yĕnaẖé֖ş̌ ḃ֑⁠wò hàréʻòţe֖m ʼàşě֥r ʻàşîyţeֽm׃"],[44,6,"וַֽ⁠יַּשִּׂגֵ֑⁠ם וַ⁠יְדַבֵּ֣ר אֲלֵ⁠הֶ֔ם אֶת־הַ⁠דְּבָרִ֖ים הָ⁠אֵֽלֶּה׃","waֽ⁠yȧşi̇̂gé֑⁠m wa⁠yĕdabé֣̇r ʼàlé⁠he֔m ʼeţ-ha⁠dĕ̇bári֖ym há⁠ʼéֽlėh׃"],[44,7,"וַ⁠יֹּאמְר֣וּ אֵלָ֔י⁠ו לָ֚⁠מָּה יְדַבֵּ֣ר אֲדֹנִ֔⁠י כַּ⁠דְּבָרִ֖ים הָ⁠אֵ֑לֶּה חָלִ֨ילָ⁠ה֙ לַ⁠עֲבָדֶ֔י⁠ךָ מֵ⁠עֲשׂ֖וֹת כַּ⁠דָּבָ֥ר הַ⁠זֶּֽה׃","wa⁠yò̇ʼmĕr֣ẇ ʼélá֔y⁠w lá֚⁠má̇h yĕdabé֣̇r ʼàdòni֔⁠y kȧ⁠dĕ̇bári֖ym há⁠ʼé֑lėh ẖáli֨ylá⁠h֙ la⁠ʻàbáde֔y⁠ká mé⁠ʻàş֖̂wòţ kȧ⁠dá̇bá֥r ha⁠zėֽh׃"],[44,8,"הֵ֣ן כֶּ֗סֶף אֲשֶׁ֤ר מָצָ֨אנוּ֙ בְּ⁠פִ֣י אַמְתְּחֹתֵ֔י⁠נוּ הֱשִׁיבֹ֥נוּ אֵלֶ֖י⁠ךָ מֵ⁠אֶ֣רֶץ כְּנָ֑עַן וְ⁠אֵ֗יךְ נִגְנֹב֙ מִ⁠בֵּ֣ית אֲדֹנֶ֔י⁠ךָ כֶּ֖סֶף א֥וֹ זָהָֽב׃","hé֣n kė֗sep ʼàşě֤r máẕá֨ʼnẇ֙ bĕ̇⁠pi֣y ʼamĕţĕ̇ẖòţé֔y⁠nẇ hèşǐybò֥nẇ ʼéle֖y⁠ká mé⁠ʼe֣reẕ kĕ̇ná֑ʻan wĕ⁠ʼé֗ykĕ nigĕnòb֙ mi⁠bé֣̇yţ ʼàdòne֔y⁠ká kė֖sep ʼ֥wò záháֽb׃"],[44,9,"אֲשֶׁ֨ר יִמָּצֵ֥א אִתּ֛⁠וֹ מֵ⁠עֲבָדֶ֖י⁠ךָ וָ⁠מֵ֑ת וְ⁠גַם־אֲנַ֕חְנוּ נִֽהְיֶ֥ה לַֽ⁠אדֹנִ֖⁠י לַ⁠עֲבָדִֽים׃","ʼàşě֨r yimá̇ẕé֥ʼ ʼiţ֛̇⁠wò mé⁠ʻàbáde֖y⁠ká wá⁠mé֑ţ wĕ⁠gam-ʼàna֕ẖĕnẇ niֽhĕye֥h laֽ⁠ʼdòni֖⁠y la⁠ʻàbádiֽym׃"],[44,10,"וַ⁠יֹּ֕אמֶר גַּם־עַתָּ֥ה כְ⁠דִבְרֵי⁠כֶ֖ם כֶּן־ה֑וּא אֲשֶׁ֨ר יִמָּצֵ֤א אִתּ⁠וֹ֙ יִהְיֶה־לִּ֣⁠י עָ֔בֶד וְ⁠אַתֶּ֖ם תִּהְי֥וּ נְקִיִּֽם׃","wa⁠yò̇֕ʼmer gȧm-ʻaţá֥̇h kĕ⁠dibĕréy⁠ke֖m kėn-h֑ẇʼ ʼàşě֨r yimá̇ẕé֤ʼ ʼiţ̇⁠wò֙ yihĕyeh-li֣̇⁠y ʻá֔bed wĕ⁠ʼaţė֖m ţi̇hĕy֥ẇ nĕqiyiֽ̇m׃"],[44,11,"וַֽ⁠יְמַהֲר֗וּ וַ⁠יּוֹרִ֛דוּ אִ֥ישׁ אֶת־אַמְתַּחְתּ֖⁠וֹ אָ֑רְצָ⁠ה וַֽ⁠יִּפְתְּח֖וּ אִ֥ישׁ אַמְתַּחְתּֽ⁠וֹ׃","wֽa⁠yĕmahàr֗ẇ wa⁠ẏwòri֛dẇ ʼi֥yş̌ ʼeţ-ʼamĕţȧẖĕţ֖̇⁠wò ʼá֑rĕẕá⁠h waֽ⁠yi̇pĕţĕ̇ẖ֖ẇ ʼi֥yş̌ ʼamĕţȧẖĕţֽ̇⁠wò׃"],[44,12,"וַ⁠יְחַפֵּ֕שׂ בַּ⁠גָּד֣וֹל הֵחֵ֔ל וּ⁠בַ⁠קָּטֹ֖ן כִּלָּ֑ה וַ⁠יִּמָּצֵא֙ הַ⁠גָּבִ֔יעַ בְּ⁠אַמְתַּ֖חַת בִּנְיָמִֽן׃","wa⁠yĕẖapé̇֕ş̂ bȧ⁠gá̇d֣wòl héẖé֔l ẇ⁠ba⁠qá̇tò֖n ki̇lá֑̇h wa⁠yi̇má̇ẕéʼ֙ ha⁠gá̇bi֔yʻa bĕ̇⁠ʼamĕţȧ֖ẖaţ bi̇nĕyámiֽn׃"],[44,13,"וַֽ⁠יִּקְרְע֖וּ שִׂמְלֹתָ֑⁠ם וַֽ⁠יַּעֲמֹס֙ אִ֣ישׁ עַל־חֲמֹר֔⁠וֹ וַ⁠יָּשֻׁ֖בוּ הָ⁠עִֽירָ⁠ה׃","wֽa⁠yi̇qĕrĕʻ֖ẇ şîmĕlòţá֑⁠m waֽ⁠yȧʻàmòs֙ ʼi֣yş̌ ʻal-ẖàmòr֔⁠wò wa⁠yá̇şǔ֖bẇ há⁠ʻiֽyrá⁠h׃"],[44,14,"וַ⁠יָּבֹ֨א יְהוּדָ֤ה וְ⁠אֶחָי⁠ו֙ בֵּ֣יתָ⁠ה יוֹסֵ֔ף וְ⁠ה֖וּא עוֹדֶ֣⁠נּוּ שָׁ֑ם וַ⁠יִּפְּל֥וּ לְ⁠פָנָ֖י⁠ו אָֽרְצָ⁠ה׃","wa⁠yá̇bò֨ʼ yĕhẇdá֤h wĕ⁠ʼeẖáy⁠w֙ bé֣̇yţá⁠h ywòsé֔p wĕ⁠h֖ẇʼ ʻwòde֣⁠ṅẇ şá֑̌m wa⁠yi̇pĕ̇l֥ẇ lĕ⁠páná֖y⁠w ʼáֽrĕẕá⁠h׃"],[44,15,"וַ⁠יֹּ֤אמֶר לָ⁠הֶם֙ יוֹסֵ֔ף מָֽה־הַ⁠מַּעֲשֶׂ֥ה הַ⁠זֶּ֖ה אֲשֶׁ֣ר עֲשִׂיתֶ֑ם הֲ⁠ל֣וֹא יְדַעְתֶּ֔ם כִּֽי־נַחֵ֧שׁ יְנַחֵ֛שׁ אִ֖ישׁ אֲשֶׁ֥ר כָּמֹֽ⁠נִי׃","wa⁠yò֤̇ʼmer lá⁠hem֙ ywòsé֔p máֽh-ha⁠mȧʻàşê֥h ha⁠zė֖h ʼàşě֣r ʻàşîyţe֑m hà⁠l֣wòʼ yĕdaʻĕţė֔m kiֽ̇y-naẖé֧ş̌ yĕnaẖé֛ş̌ ʼi֖yş̌ ʼàşě֥r ká̇mòֽ⁠niy׃"],[44,16,"וַ⁠יֹּ֣אמֶר יְהוּדָ֗ה מַה־נֹּאמַר֙ לַֽ⁠אדֹנִ֔⁠י מַה־נְּדַבֵּ֖ר וּ⁠מַה־נִּצְטַדָּ֑ק הָ⁠אֱלֹהִ֗ים מָצָא֙ אֶת־עֲוֺ֣ן עֲבָדֶ֔י⁠ךָ הִנֶּ⁠נּ֤וּ עֲבָדִים֙ לַֽ⁠אדֹנִ֔⁠י גַּם־אֲנַ֕חְנוּ גַּ֛ם אֲשֶׁר־נִמְצָ֥א הַ⁠גָּבִ֖יעַ בְּ⁠יָדֽ⁠וֹ׃","wa⁠yò֣̇ʼmer yĕhẇdá֗h mah-nò̇ʼmar֙ laֽ⁠ʼdòni֔⁠y mah-nĕ̇dabé֖̇r ẇ⁠mah-ni̇ẕĕtadá֑̇q há⁠ʼèlòhi֗ym máẕáʼ֙ ʼeţ-ʻàwֺ֣n ʻàbáde֔y⁠ká hinė⁠ṅ֤ẇ ʻàbádiym֙ laֽ⁠ʼdòni֔⁠y gȧm-ʼàna֕ẖĕnẇ gȧ֛m ʼàşěr-nimĕẕá֥ʼ ha⁠gá̇bi֖yʻa bĕ̇⁠yádֽ⁠wò׃"],[44,17,"וַ⁠יֹּ֕אמֶר חָלִ֣ילָ⁠ה לִּ֔⁠י מֵ⁠עֲשׂ֖וֹת זֹ֑את הָ⁠אִ֡ישׁ אֲשֶׁר֩ נִמְצָ֨א הַ⁠גָּבִ֜יעַ בְּ⁠יָד֗⁠וֹ ה֚וּא יִהְיֶה־לִּ֣⁠י עָ֔בֶד וְ⁠אַתֶּ֕ם עֲל֥וּ לְ⁠שָׁל֖וֹם אֶל־אֲבִי⁠כֶֽם׃פ","wa⁠yò̇֕ʼmer ẖáli֣ylá⁠h li̇֔⁠y mé⁠ʻàş֖̂wòţ zò֑ʼţ há⁠ʼi֡yş̌ ʼàşěr֩ nimĕẕá֨ʼ ha⁠gá̇bi֜yʻa bĕ̇⁠yád֗⁠wò h֚ẇʼ yihĕyeh-li֣̇⁠y ʻá֔bed wĕ⁠ʼaţė֕m ʻàl֥ẇ lĕ⁠şá̌l֖wòm ʼel-ʼàbiy⁠keֽm׃p"],[44,18,"וַ⁠יִּגַּ֨שׁ אֵלָ֜י⁠ו יְהוּדָ֗ה וַ⁠יֹּאמֶר֮ בִּ֣י אֲדֹנִ⁠י֒ יְדַבֶּר־נָ֨א עַבְדְּ⁠ךָ֤ דָבָר֙ בְּ⁠אָזְנֵ֣י אֲדֹנִ֔⁠י וְ⁠אַל־יִ֥חַר אַפְּ⁠ךָ֖ בְּ⁠עַבְדֶּ֑⁠ךָ כִּ֥י כָמ֖וֹ⁠ךָ כְּ⁠פַרְעֹֽה׃","wa⁠yi̇gȧ֨ş̌ ʼélá֜y⁠w yĕhẇdá֗h wa⁠yò̇ʼmer֮ bi֣̇y ʼàdòni⁠y֒ yĕdabėr-ná֨ʼ ʻabĕdĕ̇⁠ká֤ dábár֙ bĕ̇⁠ʼázĕné֣y ʼàdòni֔⁠y wĕ⁠ʼal-yi֥ẖar ʼapĕ̇⁠ká֖ bĕ̇⁠ʻabĕdė֑⁠ká ki֥̇y kám֖wò⁠ká kĕ̇⁠parĕʻòֽh׃"],[44,19,"אֲדֹנִ֣⁠י שָׁאַ֔ל אֶת־עֲבָדָ֖י⁠ו לֵ⁠אמֹ֑ר הֲ⁠יֵשׁ־לָ⁠כֶ֥ם אָ֖ב אוֹ־אָֽח׃","ʼàdòni֣⁠y şá̌ʼa֔l ʼeţ-ʻàbádá֖y⁠w lé⁠ʼmò֑r hà⁠yéş̌-lá⁠ke֥m ʼá֖b ʼwò-ʼáֽẖ׃"],[44,20,"וַ⁠נֹּ֨אמֶר֙ אֶל־אֲדֹנִ֔⁠י יֶשׁ־לָ֨⁠נוּ֙ אָ֣ב זָקֵ֔ן וְ⁠יֶ֥לֶד זְקֻנִ֖ים קָטָ֑ן וְ⁠אָחִ֨י⁠ו מֵ֜ת וַ⁠יִּוָּתֵ֨ר ה֧וּא לְ⁠בַדּ֛⁠וֹ לְ⁠אִמּ֖⁠וֹ וְ⁠אָבִ֥י⁠ו אֲהֵבֽ⁠וֹ׃","wa⁠nò̇֨ʼmer֙ ʼel-ʼàdòni֔⁠y yeş̌-lá֨⁠nẇ֙ ʼá֣b záqé֔n wĕ⁠ye֥led zĕquni֖ym qátá֑n wĕ⁠ʼáẖi֨y⁠w mé֜ţ wa⁠yi̇wá̇ţé֨r h֧ẇʼ lĕ⁠baḋ֛⁠wò lĕ⁠ʼiṁ֖⁠wò wĕ⁠ʼábi֥y⁠w ʼàhébֽ⁠wò׃"],[44,21,"וַ⁠תֹּ֨אמֶר֙ אֶל־עֲבָדֶ֔י⁠ךָ הוֹרִדֻ֖⁠הוּ אֵלָ֑⁠י וְ⁠אָשִׂ֥ימָה עֵינִ֖⁠י עָלָֽי⁠ו׃","wa⁠ţò̇֨ʼmer֙ ʼel-ʻàbáde֔y⁠ká hwòridu֖⁠hẇ ʼélá֑⁠y wĕ⁠ʼáşî֥ymáh ʻéyni֖⁠y ʻáláֽy⁠w׃"],[44,22,"וַ⁠נֹּ֨אמֶר֙ אֶל־אֲדֹנִ֔⁠י לֹא־יוּכַ֥ל הַ⁠נַּ֖עַר לַ⁠עֲזֹ֣ב אֶת־אָבִ֑י⁠ו וְ⁠עָזַ֥ב אֶת־אָבִ֖י⁠ו וָ⁠מֵֽת׃","wa⁠nò̇֨ʼmer֙ ʼel-ʼàdòni֔⁠y lòʼ-yẇka֥l ha⁠nȧ֖ʻar la⁠ʻàzò֣b ʼeţ-ʼábi֑y⁠w wĕ⁠ʻáza֥b ʼeţ-ʼábi֖y⁠w wá⁠méֽţ׃"],[44,23,"וַ⁠תֹּ֨אמֶר֙ אֶל־עֲבָדֶ֔י⁠ךָ אִם־לֹ֥א יֵרֵ֛ד אֲחִי⁠כֶ֥ם הַ⁠קָּטֹ֖ן אִתְּ⁠כֶ֑ם לֹ֥א תֹסִפ֖וּ⁠ן לִ⁠רְא֥וֹת פָּנָֽ⁠י׃","wa⁠ţò̇֨ʼmer֙ ʼel-ʻàbáde֔y⁠ká ʼim-lò֥ʼ yéré֛d ʼàẖiy⁠ke֥m ha⁠qá̇tò֖n ʼiţĕ̇⁠ke֑m lò֥ʼ ţòsip֖ẇ⁠n li⁠rĕʼ֥wòţ pá̇náֽ⁠y׃"],[44,24,"וַ⁠יְהִי֙ כִּ֣י עָלִ֔ינוּ אֶֽל־עַבְדְּ⁠ךָ֖ אָבִ֑⁠י וַ⁠נַּ֨גֶּד־ל֔⁠וֹ אֵ֖ת דִּבְרֵ֥י אֲדֹנִֽ⁠י׃","wa⁠yĕhiy֙ ki֣̇y ʻáli֔ynẇ ʼeֽl-ʻabĕdĕ̇⁠ká֖ ʼábi֑⁠y wa⁠nȧ֨gėd-l֔⁠wò ʼé֖ţ di̇bĕré֥y ʼàdòniֽ⁠y׃"],[44,25,"וַ⁠יֹּ֖אמֶר אָבִ֑י⁠נוּ שֻׁ֖בוּ שִׁבְרוּ־לָ֥⁠נוּ מְעַט־אֹֽכֶל׃","wa⁠yò֖̇ʼmer ʼábi֑y⁠nẇ şǔ֖bẇ şǐbĕrẇ-lá֥⁠nẇ mĕʻat-ʼòֽkel׃"],[44,26,"וַ⁠נֹּ֕אמֶר לֹ֥א נוּכַ֖ל לָ⁠רֶ֑דֶת אִם־יֵשׁ֩ אָחִ֨י⁠נוּ הַ⁠קָּטֹ֤ן אִתָּ֨⁠נוּ֙ וְ⁠יָרַ֔דְנוּ כִּי־לֹ֣א נוּכַ֗ל לִ⁠רְאוֹת֙ פְּנֵ֣י הָ⁠אִ֔ישׁ וְ⁠אָחִ֥י⁠נוּ הַ⁠קָּטֹ֖ן אֵינֶ֥⁠נּוּ אִתָּֽ⁠נוּ׃","wa⁠nò̇֕ʼmer lò֥ʼ nẇka֖l lá⁠re֑deţ ʼim-yéş̌֩ ʼáẖi֨y⁠nẇ ha⁠qá̇tò֤n ʼiţá̇֨⁠nẇ֙ wĕ⁠yára֔dĕnẇ ki̇y-lò֣ʼ nẇka֗l li⁠rĕʼwòţ֙ pĕ̇né֣y há⁠ʼi֔yş̌ wĕ⁠ʼáẖi֥y⁠nẇ ha⁠qá̇tò֖n ʼéyne֥⁠ṅẇ ʼiţáֽ̇⁠nẇ׃"],[44,27,"וַ⁠יֹּ֛אמֶר עַבְדְּ⁠ךָ֥ אָבִ֖⁠י אֵלֵ֑י⁠נוּ אַתֶּ֣ם יְדַעְתֶּ֔ם כִּ֥י שְׁנַ֖יִם יָֽלְדָה־לִּ֥⁠י אִשְׁתִּֽ⁠י׃","wa⁠yò֛̇ʼmer ʻabĕdĕ̇⁠ká֥ ʼábi֖⁠y ʼélé֑y⁠nẇ ʼaţė֣m yĕdaʻĕţė֔m ki֥̇y şĕ̌na֖yim yáֽlĕdáh-li֥̇⁠y ʼişĕ̌ţiֽ̇⁠y׃"],[44,28,"וַ⁠יֵּצֵ֤א הָֽ⁠אֶחָד֙ מֵֽ⁠אִתִּ֔⁠י וָ⁠אֹמַ֕ר אַ֖ךְ טָרֹ֣ף טֹרָ֑ף וְ⁠לֹ֥א רְאִיתִ֖י⁠ו עַד־הֵֽנָּה׃","wa⁠yé̇ẕé֤ʼ háֽ⁠ʼeẖád֙ méֽ⁠ʼiţi̇֔⁠y wá⁠ʼòma֕r ʼa֖kĕ tárò֣p tòrá֑p wĕ⁠lò֥ʼ rĕʼiyţi֖y⁠w ʻad-héֽná̇h׃"],[44,29,"וּ⁠לְקַחְתֶּ֧ם גַּם־אֶת־זֶ֛ה מֵ⁠עִ֥ם פָּנַ֖⁠י וְ⁠קָרָ֣⁠הוּ אָס֑וֹן וְ⁠הֽוֹרַדְתֶּ֧ם אֶת־שֵׂיבָתִ֛⁠י בְּ⁠רָעָ֖ה שְׁאֹֽלָ⁠ה׃","ẇ⁠lĕqaẖĕţė֧m gȧm-ʼeţ-ze֛h mé⁠ʻi֥m pá̇na֖⁠y wĕ⁠qárá֣⁠hẇ ʼás֑wòn wĕ⁠hֽwòradĕţė֧m ʼeţ-şé̂ybáţi֛⁠y bĕ̇⁠ráʻá֖h şĕ̌ʼòֽlá⁠h׃"],[44,30,"וְ⁠עַתָּ֗ה כְּ⁠בֹאִ⁠י֙ אֶל־עַבְדְּ⁠ךָ֣ אָבִ֔⁠י וְ⁠הַ⁠נַּ֖עַר אֵינֶ֣⁠נּוּ אִתָּ֑⁠נוּ וְ⁠נַפְשׁ֖⁠וֹ קְשׁוּרָ֥ה בְ⁠נַפְשֽׁ⁠וֹ׃","wĕ⁠ʻaţá̇֗h kĕ̇⁠bòʼi⁠y֙ ʼel-ʻabĕdĕ̇⁠ká֣ ʼábi֔⁠y wĕ⁠ha⁠nȧ֖ʻar ʼéyne֣⁠ṅẇ ʼiţá֑̇⁠nẇ wĕ⁠napĕş֖̌⁠wò qĕş̌ẇrá֥h bĕ⁠napĕşֽ̌⁠wò׃"],[44,31,"וְ⁠הָיָ֗ה כִּ⁠רְאוֹת֛⁠וֹ כִּי־אֵ֥ין הַ⁠נַּ֖עַר וָ⁠מֵ֑ת וְ⁠הוֹרִ֨ידוּ עֲבָדֶ֜י⁠ךָ אֶת־שֵׂיבַ֨ת עַבְדְּ⁠ךָ֥ אָבִ֛י⁠נוּ בְּ⁠יָג֖וֹן שְׁאֹֽלָ⁠ה׃","wĕ⁠háyá֗h ki̇⁠rĕʼwòţ֛⁠wò ki̇y-ʼé֥yn ha⁠nȧ֖ʻar wá⁠mé֑ţ wĕ⁠hwòri֨ydẇ ʻàbáde֜y⁠ká ʼeţ-şé̂yba֨ţ ʻabĕdĕ̇⁠ká֥ ʼábi֛y⁠nẇ bĕ̇⁠yág֖wòn şĕ̌ʼòֽlá⁠h׃"],[44,32,"כִּ֤י עַבְדְּ⁠ךָ֙ עָרַ֣ב אֶת־הַ⁠נַּ֔עַר מֵ⁠עִ֥ם אָבִ֖⁠י לֵ⁠אמֹ֑ר אִם־לֹ֤א אֲבִיאֶ֨⁠נּוּ֙ אֵלֶ֔י⁠ךָ וְ⁠חָטָ֥אתִי לְ⁠אָבִ֖⁠י כָּל־הַ⁠יָּמִֽים׃","ki֤̇y ʻabĕdĕ̇⁠ká֙ ʻára֣b ʼeţ-ha⁠nȧ֔ʻar mé⁠ʻi֥m ʼábi֖⁠y lé⁠ʼmò֑r ʼim-lò֤ʼ ʼàbiyʼe֨⁠ṅẇ֙ ʼéle֔y⁠ká wĕ⁠ẖátá֥ʼţiy lĕ⁠ʼábi֖⁠y ká̇l-ha⁠yá̇miֽym׃"],[44,33,"וְ⁠עַתָּ֗ה יֵֽשֶׁב־נָ֤א עַבְדְּ⁠ךָ֙ תַּ֣חַת הַ⁠נַּ֔עַר עֶ֖בֶד לַֽ⁠אדֹנִ֑⁠י וְ⁠הַ⁠נַּ֖עַר יַ֥עַל עִם־אֶחָֽי⁠ו׃","wĕ⁠ʻaţá̇֗h yéֽşěb-ná֤ʼ ʻabĕdĕ̇⁠ká֙ ţȧ֣ẖaţ ha⁠nȧ֔ʻar ʻe֖bed laֽ⁠ʼdòni֑⁠y wĕ⁠ha⁠nȧ֖ʻar ya֥ʻal ʻim-ʼeẖáֽy⁠w׃"],[44,34,"כִּי־אֵיךְ֙ אֶֽעֱלֶ֣ה אֶל־אָבִ֔⁠י וְ⁠הַ⁠נַּ֖עַר אֵינֶ֣⁠נּוּ אִתִּ֑⁠י פֶּ֚ן אֶרְאֶ֣ה בָ⁠רָ֔ע אֲשֶׁ֥ר יִמְצָ֖א אֶת־אָבִֽ⁠י׃","ki̇y-ʼéykĕ֙ ʼeֽʻèle֣h ʼel-ʼábi֔⁠y wĕ⁠ha⁠nȧ֖ʻar ʼéyne֣⁠ṅẇ ʼiţi֑̇⁠y pė֚n ʼerĕʼe֣h bá⁠rá֔ʻ ʼàşě֥r yimĕẕá֖ʼ ʼeţ-ʼábiֽ⁠y׃"],[45,1,"וְ⁠לֹֽא־יָכֹ֨ל יוֹסֵ֜ף לְ⁠הִתְאַפֵּ֗ק לְ⁠כֹ֤ל הַ⁠נִּצָּבִים֙ עָלָ֔י⁠ו וַ⁠יִּקְרָ֕א הוֹצִ֥יאוּ כָל־אִ֖ישׁ מֵ⁠עָלָ֑⁠י וְ⁠לֹא־עָ֤מַד אִישׁ֙ אִתּ֔⁠וֹ בְּ⁠הִתְוַדַּ֥ע יוֹסֵ֖ף אֶל־אֶחָֽי⁠ו׃","wĕ⁠lòֽʼ-yákò֨l ywòsé֜p lĕ⁠hiţĕʼapé̇֗q lĕ⁠kò֤l ha⁠ni̇ẕá̇biym֙ ʻálá֔y⁠w wa⁠yi̇qĕrá֕ʼ hwòẕi֥yʼẇ kál-ʼi֖yş̌ mé⁠ʻálá֑⁠y wĕ⁠lòʼ-ʻá֤mad ʼiyş̌֙ ʼiţ̇֔⁠wò bĕ̇⁠hiţĕwadȧ֥ʻ ywòsé֖p ʼel-ʼeẖáֽy⁠w׃"],[45,2,"וַ⁠יִּתֵּ֥ן אֶת־קֹל֖⁠וֹ בִּ⁠בְכִ֑י וַ⁠יִּשְׁמְע֣וּ מִצְרַ֔יִם וַ⁠יִּשְׁמַ֖ע בֵּ֥ית פַּרְעֹֽה׃","wa⁠yi̇ţé֥̇n ʼeţ-qòl֖⁠wò bi̇⁠bĕki֑y wa⁠yi̇şĕ̌mĕʻ֣ẇ miẕĕra֔yim wa⁠yi̇şĕ̌ma֖ʻ bé֥̇yţ pȧrĕʻòֽh׃"],[45,3,"וַ⁠יֹּ֨אמֶר יוֹסֵ֤ף אֶל־אֶחָי⁠ו֙ אֲנִ֣י יוֹסֵ֔ף הַ⁠ע֥וֹד אָבִ֖⁠י חָ֑י וְ⁠לֹֽא־יָכְל֤וּ אֶחָי⁠ו֙ לַ⁠עֲנ֣וֹת אֹת֔⁠וֹ כִּ֥י נִבְהֲל֖וּ מִ⁠פָּנָֽי⁠ו׃","wa⁠yò̇֨ʼmer ywòsé֤p ʼel-ʼeẖáy⁠w֙ ʼàni֣y ywòsé֔p ha⁠ʻ֥wòd ʼábi֖⁠y ẖá֑y wĕ⁠lòֽʼ-yákĕl֤ẇ ʼeẖáy⁠w֙ la⁠ʻàn֣wòţ ʼòţ֔⁠wò ki֥̇y nibĕhàl֖ẇ mi⁠pá̇náֽy⁠w׃"],[45,4,"וַ⁠יֹּ֨אמֶר יוֹסֵ֧ף אֶל־אֶחָ֛י⁠ו גְּשׁוּ־נָ֥א אֵלַ֖⁠י וַ⁠יִּגָּ֑שׁוּ וַ⁠יֹּ֗אמֶר אֲנִי֙ יוֹסֵ֣ף אֲחִי⁠כֶ֔ם אֲשֶׁר־מְכַרְתֶּ֥ם אֹתִ֖⁠י מִצְרָֽיְמָ⁠ה׃","wa⁠yò̇֨ʼmer ywòsé֧p ʼel-ʼeẖá֛y⁠w gĕ̇ş̌ẇ-ná֥ʼ ʼéla֖⁠y wa⁠yi̇gá֑̇ş̌ẇ wa⁠yò̇֗ʼmer ʼàniy֙ ywòsé֣p ʼàẖiy⁠ke֔m ʼàşěr-mĕkarĕţė֥m ʼòţi֖⁠y miẕĕráֽyĕmá⁠h׃"],[45,5,"וְ⁠עַתָּ֣ה ׀ אַל־תֵּעָ֣צְב֗וּ וְ⁠אַל־יִ֨חַר֙ בְּ⁠עֵ֣ינֵי⁠כֶ֔ם כִּֽי־מְכַרְתֶּ֥ם אֹתִ֖⁠י הֵ֑נָּה כִּ֣י לְ⁠מִֽחְיָ֔ה שְׁלָחַ֥⁠נִי אֱלֹהִ֖ים לִ⁠פְנֵי⁠כֶֽם׃","wĕ⁠ʻaţá֣̇h ׀ ʼal-ţé̇ʻá֣ẕĕb֗ẇ wĕ⁠ʼal-yi֨ẖar֙ bĕ̇⁠ʻé֣ynéy⁠ke֔m kiֽ̇y-mĕkarĕţė֥m ʼòţi֖⁠y hé֑ná̇h ki֣̇y lĕ⁠miֽẖĕyá֔h şĕ̌láẖa֥⁠niy ʼèlòhi֖ym li⁠pĕnéy⁠keֽm׃"],[45,6,"כִּי־זֶ֛ה שְׁנָתַ֥יִם הָ⁠רָעָ֖ב בְּ⁠קֶ֣רֶב הָ⁠אָ֑רֶץ וְ⁠עוֹד֙ חָמֵ֣שׁ שָׁנִ֔ים אֲשֶׁ֥ר אֵין־חָרִ֖ישׁ וְ⁠קָצִּֽיר׃","ki̇y-ze֛h şĕ̌náţa֥yim há⁠ráʻá֖b bĕ̇⁠qe֣reb há⁠ʼá֑reẕ wĕ⁠ʻwòd֙ ẖámé֣ş̌ şá̌ni֔ym ʼàşě֥r ʼéyn-ẖári֖yş̌ wĕ⁠qáẕiֽ̇yr׃"],[45,7,"וַ⁠יִּשְׁלָחֵ֤⁠נִי אֱלֹהִים֙ לִ⁠פְנֵי⁠כֶ֔ם לָ⁠שׂ֥וּם לָ⁠כֶ֛ם שְׁאֵרִ֖ית בָּ⁠אָ֑רֶץ וּ⁠לְ⁠הַחֲי֣וֹת לָ⁠כֶ֔ם לִ⁠פְלֵיטָ֖ה גְּדֹלָֽה׃","wa⁠yi̇şĕ̌láẖé֤⁠niy ʼèlòhiym֙ li⁠pĕnéy⁠ke֔m lá⁠ş֥̂ẇm lá⁠ke֛m şĕ̌ʼéri֖yţ bá̇⁠ʼá֑reẕ ẇ⁠lĕ⁠haẖày֣wòţ lá⁠ke֔m li⁠pĕléytá֖h gĕ̇dòláֽh׃"],[45,8,"וְ⁠עַתָּ֗ה לֹֽא־אַתֶּ֞ם שְׁלַחְתֶּ֤ם אֹתִ⁠י֙ הֵ֔נָּה כִּ֖י הָ⁠אֱלֹהִ֑ים וַ⁠יְשִׂימֵ֨⁠נִֽי לְ⁠אָ֜ב לְ⁠פַרְעֹ֗ה וּ⁠לְ⁠אָדוֹן֙ לְ⁠כָל־בֵּית֔⁠וֹ וּ⁠מֹשֵׁ֖ל בְּ⁠כָל־אֶ֥רֶץ מִצְרָֽיִם׃","wĕ⁠ʻaţá̇֗h lòֽʼ-ʼaţė֞m şĕ̌laẖĕţė֤m ʼòţi⁠y֙ hé֔ná̇h ki֖̇y há⁠ʼèlòhi֑ym wa⁠yĕşîymé֨⁠niֽy lĕ⁠ʼá֜b lĕ⁠parĕʻò֗h ẇ⁠lĕ⁠ʼádwòn֙ lĕ⁠kál-bé̇yţ֔⁠wò ẇ⁠mòşé֖̌l bĕ̇⁠kál-ʼe֥reẕ miẕĕráֽyim׃"],[45,9,"מַהֲרוּ֮ וַ⁠עֲל֣וּ אֶל־אָבִ⁠י֒ וַ⁠אֲמַרְתֶּ֣ם אֵלָ֗י⁠ו כֹּ֤ה אָמַר֙ בִּנְ⁠ךָ֣ יוֹסֵ֔ף שָׂמַ֧⁠נִי אֱלֹהִ֛ים לְ⁠אָד֖וֹן לְ⁠כָל־מִצְרָ֑יִם רְדָ֥⁠ה אֵלַ֖⁠י אַֽל־תַּעֲמֹֽד׃","mahàrẇ֮ wa⁠ʻàl֣ẇ ʼel-ʼábi⁠y֒ wa⁠ʼàmarĕţė֣m ʼélá֗y⁠w kò֤̇h ʼámar֙ bi̇nĕ⁠ká֣ ywòsé֔p şá̂ma֧⁠niy ʼèlòhi֛ym lĕ⁠ʼád֖wòn lĕ⁠kál-miẕĕrá֑yim rĕdá֥⁠h ʼéla֖⁠y ʼaֽl-ţȧʻàmòֽd׃"],[45,10,"וְ⁠יָשַׁבְתָּ֣ בְ⁠אֶֽרֶץ־גֹּ֗שֶׁן וְ⁠הָיִ֤יתָ קָרוֹב֙ אֵלַ֔⁠י אַתָּ֕ה וּ⁠בָנֶ֖י⁠ךָ וּ⁠בְנֵ֣י בָנֶ֑י⁠ךָ וְ⁠צֹאנְ⁠ךָ֥ וּ⁠בְקָרְ⁠ךָ֖ וְ⁠כָל־אֲשֶׁר־לָֽ⁠ךְ׃","wĕ⁠yáşǎbĕţá֣̇ bĕ⁠ʼeֽreẕ-gò̇֗şěn wĕ⁠háyi֤yţá qárwòb֙ ʼéla֔⁠y ʼaţá̇֕h ẇ⁠báne֖y⁠ká ẇ⁠bĕné֣y báne֑y⁠ká wĕ⁠ẕòʼnĕ⁠ká֥ ẇ⁠bĕqárĕ⁠ká֖ wĕ⁠kál-ʼàşěr-láֽ⁠kĕ׃"],[45,11,"וְ⁠כִלְכַּלְתִּ֤י אֹֽתְ⁠ךָ֙ שָׁ֔ם כִּי־ע֛וֹד חָמֵ֥שׁ שָׁנִ֖ים רָעָ֑ב פֶּן־תִּוָּרֵ֛שׁ אַתָּ֥ה וּ⁠בֵֽיתְ⁠ךָ֖ וְ⁠כָל־אֲשֶׁר־לָֽ⁠ךְ׃","wĕ⁠kilĕkȧlĕţi֤̇y ʼòֽţĕ⁠ká֙ şá̌֔m ki̇y-ʻ֛wòd ẖámé֥ş̌ şá̌ni֖ym ráʻá֑b pėn-ţi̇wá̇ré֛ş̌ ʼaţá֥̇h ẇ⁠béֽyţĕ⁠ká֖ wĕ⁠kál-ʼàşěr-láֽ⁠kĕ׃"],[45,12,"וְ⁠הִנֵּ֤ה עֵֽינֵי⁠כֶם֙ רֹא֔וֹת וְ⁠עֵינֵ֖י אָחִ֣⁠י בִנְיָמִ֑ין כִּי־פִ֖⁠י הַֽ⁠מְדַבֵּ֥ר אֲלֵי⁠כֶֽם׃","wĕ⁠hiné֤̇h ʻéֽynéy⁠kem֙ ròʼ֔wòţ wĕ⁠ʻéyné֖y ʼáẖi֣⁠y binĕyámi֑yn ki̇y-pi֖⁠y haֽ⁠mĕdabé֥̇r ʼàléy⁠keֽm׃"],[45,13,"וְ⁠הִגַּדְתֶּ֣ם לְ⁠אָבִ֗⁠י אֶת־כָּל־כְּבוֹדִ⁠י֙ בְּ⁠מִצְרַ֔יִם וְ⁠אֵ֖ת כָּל־אֲשֶׁ֣ר רְאִיתֶ֑ם וּ⁠מִֽהַרְתֶּ֛ם וְ⁠הוֹרַדְתֶּ֥ם אֶת־אָבִ֖⁠י הֵֽנָּה׃","wĕ⁠higȧdĕţė֣m lĕ⁠ʼábi֗⁠y ʼeţ-ká̇l-kĕ̇bwòdi⁠y֙ bĕ̇⁠miẕĕra֔yim wĕ⁠ʼé֖ţ ká̇l-ʼàşě֣r rĕʼiyţe֑m ẇ⁠miֽharĕţė֛m wĕ⁠hwòradĕţė֥m ʼeţ-ʼábi֖⁠y héֽná̇h׃"],[45,14,"וַ⁠יִּפֹּ֛ל עַל־צַוְּארֵ֥י בִנְיָמִֽן־אָחִ֖י⁠ו וַ⁠יֵּ֑בְךְּ וּ⁠בִנְיָמִ֔ן בָּכָ֖ה עַל־צַוָּארָֽי⁠ו׃","wa⁠yi̇pò֛̇l ʻal-ẕawĕ̇ʼré֥y binĕyámiֽn-ʼáẖi֖y⁠w wa⁠yé֑̇bĕkĕ̇ ẇ⁠binĕyámi֔n bá̇ká֖h ʻal-ẕawá̇ʼráֽy⁠w׃"],[45,15,"וַ⁠יְנַשֵּׁ֥ק לְ⁠כָל־אֶחָ֖י⁠ו וַ⁠יֵּ֣בְךְּ עֲלֵי⁠הֶ֑ם וְ⁠אַ֣חֲרֵי כֵ֔ן דִּבְּר֥וּ אֶחָ֖י⁠ו אִתּֽ⁠וֹ׃","wa⁠yĕnaşé֥̇̌q lĕ⁠kál-ʼeẖá֖y⁠w wa⁠yé֣̇bĕkĕ̇ ʻàléy⁠he֑m wĕ⁠ʼa֣ẖàréy ké֔n di̇bĕ̇r֥ẇ ʼeẖá֖y⁠w ʼiţֽ̇⁠wò׃"],[45,16,"וְ⁠הַ⁠קֹּ֣ל נִשְׁמַ֗ע בֵּ֤ית פַּרְעֹה֙ לֵ⁠אמֹ֔ר בָּ֖אוּ אֲחֵ֣י יוֹסֵ֑ף וַ⁠יִּיטַב֙ בְּ⁠עֵינֵ֣י פַרְעֹ֔ה וּ⁠בְ⁠עֵינֵ֖י עֲבָדָֽי⁠ו׃","wĕ⁠ha⁠qò֣̇l nişĕ̌ma֗ʻ bé֤̇yţ pȧrĕʻòh֙ lé⁠ʼmò֔r bá֖̇ʼẇ ʼàẖé֣y ywòsé֑p wa⁠yi̇ytab֙ bĕ̇⁠ʻéyné֣y parĕʻò֔h ẇ⁠bĕ⁠ʻéyné֖y ʻàbádáֽy⁠w׃"],[45,17,"וַ⁠יֹּ֤אמֶר פַּרְעֹה֙ אֶל־יוֹסֵ֔ף אֱמֹ֥ר אֶל־אַחֶ֖י⁠ךָ זֹ֣את עֲשׂ֑וּ טַֽעֲנוּ֙ אֶת־בְּעִ֣ירְ⁠כֶ֔ם וּ⁠לְכוּ־בֹ֖אוּ אַ֥רְצָ⁠ה כְּנָֽעַן׃","wa⁠yò֤̇ʼmer pȧrĕʻòh֙ ʼel-ywòsé֔p ʼèmò֥r ʼel-ʼaẖe֖y⁠ká zò֣ʼţ ʻàş֑̂ẇ taֽʻànẇ֙ ʼeţ-bĕ̇ʻi֣yrĕ⁠ke֔m ẇ⁠lĕkẇ-bò֖ʼẇ ʼa֥rĕẕá⁠h kĕ̇náֽʻan׃"],[45,18,"וּ⁠קְח֧וּ אֶת־אֲבִי⁠כֶ֛ם וְ⁠אֶת־בָּתֵּי⁠כֶ֖ם וּ⁠בֹ֣אוּ אֵלָ֑⁠י וְ⁠אֶתְּנָ֣ה לָ⁠כֶ֗ם אֶת־טוּב֙ אֶ֣רֶץ מִצְרַ֔יִם וְ⁠אִכְל֖וּ אֶת־חֵ֥לֶב הָ⁠אָֽרֶץ׃","ẇ⁠qĕẖ֧ẇ ʼeţ-ʼàbiy⁠ke֛m wĕ⁠ʼeţ-bá̇ţé̇y⁠ke֖m ẇ⁠bò֣ʼẇ ʼélá֑⁠y wĕ⁠ʼeţĕ̇ná֣h lá⁠ke֗m ʼeţ-tẇb֙ ʼe֣reẕ miẕĕra֔yim wĕ⁠ʼikĕl֖ẇ ʼeţ-ẖé֥leb há⁠ʼáֽreẕ׃"],[45,19,"וְ⁠אַתָּ֥ה צֻוֵּ֖יתָה זֹ֣את עֲשׂ֑וּ קְחוּ־לָ⁠כֶם֩ מֵ⁠אֶ֨רֶץ מִצְרַ֜יִם עֲגָל֗וֹת לְ⁠טַפְּ⁠כֶם֙ וְ⁠לִ⁠נְשֵׁי⁠כֶ֔ם וּ⁠נְשָׂאתֶ֥ם אֶת־אֲבִי⁠כֶ֖ם וּ⁠בָאתֶֽם׃","wĕ⁠ʼaţá֥̇h ẕuwé֖̇yţáh zò֣ʼţ ʻàş֑̂ẇ qĕẖẇ-lá⁠kem֩ mé⁠ʼe֨reẕ miẕĕra֜yim ʻàgál֗wòţ lĕ⁠tapĕ̇⁠kem֙ wĕ⁠li⁠nĕşé̌y⁠ke֔m ẇ⁠nĕşá̂ʼţe֥m ʼeţ-ʼàbiy⁠ke֖m ẇ⁠báʼţeֽm׃"],[45,20,"וְ⁠עֵ֣ינְ⁠כֶ֔ם אַל־תָּחֹ֖ס עַל־כְּלֵי⁠כֶ֑ם כִּי־ט֛וּב כָּל־אֶ֥רֶץ מִצְרַ֖יִם לָ⁠כֶ֥ם הֽוּא׃","wĕ⁠ʻé֣ynĕ⁠ke֔m ʼal-ţá̇ẖò֖s ʻal-kĕ̇léy⁠ke֑m ki̇y-t֛ẇb ká̇l-ʼe֥reẕ miẕĕra֖yim lá⁠ke֥m hֽẇʼ׃"],[45,21,"וַ⁠יַּֽעֲשׂוּ־כֵן֙ בְּנֵ֣י יִשְׂרָאֵ֔ל וַ⁠יִּתֵּ֨ן לָ⁠הֶ֥ם יוֹסֵ֛ף עֲגָל֖וֹת עַל־פִּ֣י פַרְעֹ֑ה וַ⁠יִּתֵּ֥ן לָ⁠הֶ֛ם צֵדָ֖ה לַ⁠דָּֽרֶךְ׃","wa⁠yȧֽʻàş̂ẇ-kén֙ bĕ̇né֣y yişĕ̂ráʼé֔l wa⁠yi̇ţé̇֨n lá⁠he֥m ywòsé֛p ʻàgál֖wòţ ʻal-pi֣̇y parĕʻò֑h wa⁠yi̇ţé֥̇n lá⁠he֛m ẕédá֖h la⁠dáֽ̇rekĕ׃"],[45,22,"לְ⁠כֻלָּ֥⁠ם נָתַ֛ן לָ⁠אִ֖ישׁ חֲלִפ֣וֹת שְׂמָלֹ֑ת וּ⁠לְ⁠בִנְיָמִ֤ן נָתַן֙ שְׁלֹ֣שׁ מֵא֣וֹת כֶּ֔סֶף וְ⁠חָמֵ֖שׁ חֲלִפֹ֥ת שְׂמָלֹֽת׃","lĕ⁠kulá֥̇⁠m náţa֛n lá⁠ʼi֖yş̌ ẖàlip֣wòţ şĕ̂málò֑ţ ẇ⁠lĕ⁠binĕyámi֤n náţan֙ şĕ̌lò֣ş̌ méʼ֣wòţ kė֔sep wĕ⁠ẖámé֖ş̌ ẖàlipò֥ţ şĕ̂málòֽţ׃"],[45,23,"וּ⁠לְ⁠אָבִ֞י⁠ו שָׁלַ֤ח כְּ⁠זֹאת֙ עֲשָׂרָ֣ה חֲמֹרִ֔ים נֹשְׂאִ֖ים מִ⁠טּ֣וּב מִצְרָ֑יִם וְ⁠עֶ֣שֶׂר אֲתֹנֹ֡ת נֹֽ֠שְׂאֹת בָּ֣ר וָ⁠לֶ֧חֶם וּ⁠מָז֛וֹן לְ⁠אָבִ֖י⁠ו לַ⁠דָּֽרֶךְ׃","ẇ⁠lĕ⁠ʼábi֞y⁠w şá̌la֤ẖ kĕ̇⁠zòʼţ֙ ʻàşá̂rá֣h ẖàmòri֔ym nòşĕ̂ʼi֖ym mi⁠ṫ֣ẇb miẕĕrá֑yim wĕ⁠ʻe֣şêr ʼàţònò֡ţ nòֽ֠şĕ̂ʼòţ bá֣̇r wá⁠le֧ẖem ẇ⁠máz֛wòn lĕ⁠ʼábi֖y⁠w la⁠dáֽ̇rekĕ׃"],[45,24,"וַ⁠יְשַׁלַּ֥ח אֶת־אֶחָ֖י⁠ו וַ⁠יֵּלֵ֑כוּ וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֔ם אַֽל־תִּרְגְּז֖וּ בַּ⁠דָּֽרֶךְ׃","wa⁠yĕşǎlȧ֥ẖ ʼeţ-ʼeẖá֖y⁠w wa⁠yé̇lé֑kẇ wa⁠yò֣̇ʼmer ʼàlé⁠he֔m ʼaֽl-ţi̇rĕgĕ̇z֖ẇ bȧ⁠dáֽ̇rekĕ׃"],[45,25,"וַֽ⁠יַּעֲל֖וּ מִ⁠מִּצְרָ֑יִם וַ⁠יָּבֹ֨אוּ֙ אֶ֣רֶץ כְּנַ֔עַן אֶֽל־יַעֲקֹ֖ב אֲבִי⁠הֶֽם׃","waֽ⁠yȧʻàl֖ẇ mi⁠mi̇ẕĕrá֑yim wa⁠yá̇bò֨ʼẇ֙ ʼe֣reẕ kĕ̇na֔ʻan ʼeֽl-yaʻàqò֖b ʼàbiy⁠heֽm׃"],[45,26,"וַ⁠יַּגִּ֨דוּ ל֜⁠וֹ לֵ⁠אמֹ֗ר ע֚וֹד יוֹסֵ֣ף חַ֔י וְ⁠כִֽי־ה֥וּא מֹשֵׁ֖ל בְּ⁠כָל־אֶ֣רֶץ מִצְרָ֑יִם וַ⁠יָּ֣פָג לִבּ֔⁠וֹ כִּ֥י לֹא־הֶאֱמִ֖ין לָ⁠הֶֽם׃","wa⁠yȧgi̇֨dẇ l֜⁠wò lé⁠ʼmò֗r ʻ֚wòd ywòsé֣p ẖa֔y wĕ⁠kiֽy-h֥ẇʼ mòşé֖̌l bĕ̇⁠kál-ʼe֣reẕ miẕĕrá֑yim wa⁠yá֣̇pág liḃ֔⁠wò ki֥̇y lòʼ-heʼèmi֖yn lá⁠heֽm׃"],[45,27,"וַ⁠יְדַבְּר֣וּ אֵלָ֗י⁠ו אֵ֣ת כָּל־דִּבְרֵ֤י יוֹסֵף֙ אֲשֶׁ֣ר דִּבֶּ֣ר אֲלֵ⁠הֶ֔ם וַ⁠יַּרְא֙ אֶת־הָ֣⁠עֲגָל֔וֹת אֲשֶׁר־שָׁלַ֥ח יוֹסֵ֖ף לָ⁠שֵׂ֣את אֹת֑⁠וֹ וַ⁠תְּחִ֕י ר֖וּחַ יַעֲקֹ֥ב אֲבִי⁠הֶֽם׃","wa⁠yĕdabĕ̇r֣ẇ ʼélá֗y⁠w ʼé֣ţ ká̇l-di̇bĕré֤y ywòsép֙ ʼàşě֣r di̇bė֣r ʼàlé⁠he֔m wa⁠yȧrĕʼ֙ ʼeţ-há֣⁠ʻàgál֔wòţ ʼàşěr-şá̌la֥ẖ ywòsé֖p lá⁠şé֣̂ʼţ ʼòţ֑⁠wò wa⁠ţĕ̇ẖi֕y r֖ẇẖa yaʻàqò֥b ʼàbiy⁠heֽm׃"],[45,28,"וַ⁠יֹּ֨אמֶר֙ יִשְׂרָאֵ֔ל רַ֛ב עוֹד־יוֹסֵ֥ף בְּנִ֖⁠י חָ֑י אֵֽלְכָ֥ה וְ⁠אֶרְאֶ֖⁠נּוּ בְּ⁠טֶ֥רֶם אָמֽוּת׃","wa⁠yò̇֨ʼmer֙ yişĕ̂ráʼé֔l ra֛b ʻwòd-ywòsé֥p bĕ̇ni֖⁠y ẖá֑y ʼéֽlĕká֥h wĕ⁠ʼerĕʼe֖⁠ṅẇ bĕ̇⁠te֥rem ʼámֽẇţ׃"],[46,1,"וַ⁠יִּסַּ֤ע יִשְׂרָאֵל֙ וְ⁠כָל־אֲשֶׁר־ל֔⁠וֹ וַ⁠יָּבֹ֖א בְּאֵ֣רָ⁠ה שָּׁ֑בַע וַ⁠יִּזְבַּ֣ח זְבָחִ֔ים לֵ⁠אלֹהֵ֖י אָבִ֥י⁠ו יִצְחָֽק׃","wa⁠yi̇sȧ֤ʻ yişĕ̂ráʼél֙ wĕ⁠kál-ʼàşěr-l֔⁠wò wa⁠yá̇bò֖ʼ bĕ̇ʼé֣rá⁠h şá֑̇̌baʻ wa⁠yi̇zĕbȧ֣ẖ zĕbáẖi֔ym lé⁠ʼlòhé֖y ʼábi֥y⁠w yiẕĕẖáֽq׃"],[46,2,"וַ⁠יֹּ֨אמֶר אֱלֹהִ֤ים ׀ לְ⁠יִשְׂרָאֵל֙ בְּ⁠מַרְאֹ֣ת הַ⁠לַּ֔יְלָה וַ⁠יֹּ֖אמֶר יַעֲקֹ֣ב ׀ יַעֲקֹ֑ב וַ⁠יֹּ֖אמֶר הִנֵּֽ⁠נִי׃","wa⁠yò̇֨ʼmer ʼèlòhi֤ym ׀ lĕ⁠yişĕ̂ráʼél֙ bĕ̇⁠marĕʼò֣ţ ha⁠lȧ֔yĕláh wa⁠yò֖̇ʼmer yaʻàqò֣b ׀ yaʻàqò֑b wa⁠yò֖̇ʼmer hinéֽ̇⁠niy׃"],[46,3,"וַ⁠יֹּ֕אמֶר אָנֹכִ֥י הָ⁠אֵ֖ל אֱלֹהֵ֣י אָבִ֑י⁠ךָ אַל־תִּירָא֙ מֵ⁠רְדָ֣ה מִצְרַ֔יְמָ⁠ה כִּֽי־לְ⁠ג֥וֹי גָּד֖וֹל אֲשִֽׂימְ⁠ךָ֥ שָֽׁם׃","wa⁠yò̇֕ʼmer ʼánòki֥y há⁠ʼé֖l ʼèlòhé֣y ʼábi֑y⁠ká ʼal-ţi̇yráʼ֙ mé⁠rĕdá֣h miẕĕra֔yĕmá⁠h kiֽ̇y-lĕ⁠g֥wòy gá̇d֖wòl ʼàşîֽymĕ⁠ká֥ şáֽ̌m׃"],[46,4,"אָנֹכִ֗י אֵרֵ֤ד עִמְּ⁠ךָ֙ מִצְרַ֔יְמָ⁠ה וְ⁠אָנֹכִ֖י אַֽעַלְ⁠ךָ֣ גַם־עָלֹ֑ה וְ⁠יוֹסֵ֕ף יָשִׁ֥ית יָד֖⁠וֹ עַל־עֵינֶֽי⁠ךָ׃","ʼánòki֗y ʼéré֤d ʻimĕ̇⁠ká֙ miẕĕra֔yĕmá⁠h wĕ⁠ʼánòki֖y ʼaֽʻalĕ⁠ká֣ gam-ʻálò֑h wĕ⁠ywòsé֕p yáşǐ֥yţ yád֖⁠wò ʻal-ʻéyneֽy⁠ká׃"],[46,5,"וַ⁠יָּ֥קָם יַעֲקֹ֖ב מִ⁠בְּאֵ֣ר שָׁ֑בַע וַ⁠יִּשְׂא֨וּ בְנֵֽי־יִשְׂרָאֵ֜ל אֶת־יַעֲקֹ֣ב אֲבִי⁠הֶ֗ם וְ⁠אֶת־טַפָּ⁠ם֙ וְ⁠אֶת־נְשֵׁי⁠הֶ֔ם בָּ⁠עֲגָל֕וֹת אֲשֶׁר־שָׁלַ֥ח פַּרְעֹ֖ה לָ⁠שֵׂ֥את אֹתֽ⁠וֹ׃","wa⁠yá֥̇qám yaʻàqò֖b mi⁠bĕ̇ʼé֣r şá֑̌baʻ wa⁠yi̇şĕ̂ʼ֨ẇ bĕnéֽy-yişĕ̂ráʼé֜l ʼeţ-yaʻàqò֣b ʼàbiy⁠he֗m wĕ⁠ʼeţ-tapá̇⁠m֙ wĕ⁠ʼeţ-nĕşé̌y⁠he֔m bá̇⁠ʻàgál֕wòţ ʼàşěr-şá̌la֥ẖ pȧrĕʻò֖h lá⁠şé֥̂ʼţ ʼòţֽ⁠wò׃"],[46,6,"וַ⁠יִּקְח֣וּ אֶת־מִקְנֵי⁠הֶ֗ם וְ⁠אֶת־רְכוּשָׁ⁠ם֙ אֲשֶׁ֤ר רָֽכְשׁוּ֙ בְּ⁠אֶ֣רֶץ כְּנַ֔עַן וַ⁠יָּבֹ֖אוּ מִצְרָ֑יְמָ⁠ה יַעֲקֹ֖ב וְ⁠כָל־זַרְע֥⁠וֹ אִתּֽ⁠וֹ׃","wa⁠yi̇qĕẖ֣ẇ ʼeţ-miqĕnéy⁠he֗m wĕ⁠ʼeţ-rĕkẇşá̌⁠m֙ ʼàşě֤r ráֽkĕş̌ẇ֙ bĕ̇⁠ʼe֣reẕ kĕ̇na֔ʻan wa⁠yá̇bò֖ʼẇ miẕĕrá֑yĕmá⁠h yaʻàqò֖b wĕ⁠kál-zarĕʻ֥⁠wò ʼiţֽ̇⁠wò׃"],[46,7,"בָּנָ֞י⁠ו וּ⁠בְנֵ֤י בָנָי⁠ו֙ אִתּ֔⁠וֹ בְּנֹתָ֛י⁠ו וּ⁠בְנ֥וֹת בָּנָ֖י⁠ו וְ⁠כָל־זַרְע֑⁠וֹ הֵבִ֥יא אִתּ֖⁠וֹ מִצְרָֽיְמָ⁠ה׃ס","bá̇ná֞y⁠w ẇ⁠bĕné֤y bánáy⁠w֙ ʼiţ̇֔⁠wò bĕ̇nòţá֛y⁠w ẇ⁠bĕn֥wòţ bá̇ná֖y⁠w wĕ⁠kál-zarĕʻ֑⁠wò hébi֥yʼ ʼiţ֖̇⁠wò miẕĕráֽyĕmá⁠h׃s"],[46,8,"וְ⁠אֵ֨לֶּה שְׁמ֧וֹת בְּנֵֽי־יִשְׂרָאֵ֛ל הַ⁠בָּאִ֥ים מִצְרַ֖יְמָ⁠ה יַעֲקֹ֣ב וּ⁠בָנָ֑י⁠ו בְּכֹ֥ר יַעֲקֹ֖ב רְאוּבֵֽן׃","wĕ⁠ʼé֨lėh şĕ̌m֧wòţ bĕ̇néֽy-yişĕ̂ráʼé֛l ha⁠bá̇ʼi֥ym miẕĕra֖yĕmá⁠h yaʻàqò֣b ẇ⁠báná֑y⁠w bĕ̇kò֥r yaʻàqò֖b rĕʼẇbéֽn׃"],[46,9,"וּ⁠בְנֵ֖י רְאוּבֵ֑ן חֲנ֥וֹךְ וּ⁠פַלּ֖וּא וְ⁠חֶצְר֥וֹן וְ⁠כַרְמִֽי׃","ẇ⁠bĕné֖y rĕʼẇbé֑n ẖàn֥wòkĕ ẇ⁠pal֖̇ẇʼ wĕ⁠ẖeẕĕr֥wòn wĕ⁠karĕmiֽy׃"],[46,10,"וּ⁠בְנֵ֣י שִׁמְע֗וֹן יְמוּאֵ֧ל וְ⁠יָמִ֛ין וְ⁠אֹ֖הַד וְ⁠יָכִ֣ין וְ⁠צֹ֑חַר וְ⁠שָׁא֖וּל בֶּן־הַֽ⁠כְּנַעֲנִֽית׃","ẇ⁠bĕné֣y şǐmĕʻ֗wòn yĕmẇʼé֧l wĕ⁠yámi֛yn wĕ⁠ʼò֖had wĕ⁠yáki֣yn wĕ⁠ẕò֑ẖar wĕ⁠şá̌ʼ֖ẇl bėn-haֽ⁠kĕ̇naʻàniֽyţ׃"],[46,11,"וּ⁠בְנֵ֖י לֵוִ֑י גֵּרְשׁ֕וֹן קְהָ֖ת וּ⁠מְרָרִֽי׃","ẇ⁠bĕné֖y léwi֑y gé̇rĕş̌֕wòn qĕhá֖ţ ẇ⁠mĕráriֽy׃"],[46,12,"וּ⁠בְנֵ֣י יְהוּדָ֗ה עֵ֧ר וְ⁠אוֹנָ֛ן וְ⁠שֵׁלָ֖ה וָ⁠פֶ֣רֶץ וָ⁠זָ֑רַח וַ⁠יָּ֨מָת עֵ֤ר וְ⁠אוֹנָן֙ בְּ⁠אֶ֣רֶץ כְּנַ֔עַן וַ⁠יִּהְי֥וּ בְנֵי־פֶ֖רֶץ חֶצְר֥וֹן וְ⁠חָמֽוּל׃","ẇ⁠bĕné֣y yĕhẇdá֗h ʻé֧r wĕ⁠ʼwòná֛n wĕ⁠şé̌lá֖h wá⁠pe֣reẕ wá⁠zá֑raẖ wa⁠yá̇֨máţ ʻé֤r wĕ⁠ʼwònán֙ bĕ̇⁠ʼe֣reẕ kĕ̇na֔ʻan wa⁠yi̇hĕy֥ẇ bĕnéy-pe֖reẕ ẖeẕĕr֥wòn wĕ⁠ẖámֽẇl׃"],[46,13,"וּ⁠בְנֵ֖י יִשָׂשכָ֑ר תּוֹלָ֥ע וּ⁠פֻוָּ֖ה וְ⁠י֥וֹב וְ⁠שִׁמְרֽוֹן׃","ẇ⁠bĕné֖y yişá̂şká֑r ţ̇wòlá֥ʻ ẇ⁠puwá֖̇h wĕ⁠y֥wòb wĕ⁠şǐmĕrֽwòn׃"],[46,14,"וּ⁠בְנֵ֖י זְבוּלֻ֑ן סֶ֥רֶד וְ⁠אֵל֖וֹן וְ⁠יַחְלְאֵֽל׃","ẇ⁠bĕné֖y zĕbẇlu֑n se֥red wĕ⁠ʼél֖wòn wĕ⁠yaẖĕlĕʼéֽl׃"],[46,15,"אֵ֣לֶּה ׀ בְּנֵ֣י לֵאָ֗ה אֲשֶׁ֨ר יָֽלְדָ֤ה לְ⁠יַעֲקֹב֙ בְּ⁠פַדַּ֣ן אֲרָ֔ם וְ⁠אֵ֖ת דִּינָ֣ה בִתּ֑⁠וֹ כָּל־נֶ֧פֶשׁ בָּנָ֛י⁠ו וּ⁠בְנוֹתָ֖י⁠ו שְׁלֹשִׁ֥ים וְ⁠שָׁלֹֽשׁ׃","ʼé֣lėh ׀ bĕ̇né֣y léʼá֗h ʼàşě֨r yáֽlĕdá֤h lĕ⁠yaʻàqòb֙ bĕ̇⁠padȧ֣n ʼàrá֔m wĕ⁠ʼé֖ţ di̇yná֣h biţ֑̇⁠wò ká̇l-ne֧peş̌ bá̇ná֛y⁠w ẇ⁠bĕnwòţá֖y⁠w şĕ̌lòşǐ֥ym wĕ⁠şá̌lòֽş̌׃"],[46,16,"וּ⁠בְנֵ֣י גָ֔ד צִפְי֥וֹן וְ⁠חַגִּ֖י שׁוּנִ֣י וְ⁠אֶצְבֹּ֑ן עֵרִ֥י וַֽ⁠אֲרוֹדִ֖י וְ⁠אַרְאֵלִֽי׃","ẇ⁠bĕné֣y gá֔d ẕipĕy֥wòn wĕ⁠ẖagi֖̇y ş̌ẇni֣y wĕ⁠ʼeẕĕbò֑̇n ʻéri֥y waֽ⁠ʼàrwòdi֖y wĕ⁠ʼarĕʼéliֽy׃"],[46,17,"וּ⁠בְנֵ֣י אָשֵׁ֗ר יִמְנָ֧ה וְ⁠יִשְׁוָ֛ה וְ⁠יִשְׁוִ֥י וּ⁠בְרִיעָ֖ה וְ⁠שֶׂ֣רַח אֲחֹתָ֑⁠ם וּ⁠בְנֵ֣י בְרִיעָ֔ה חֶ֖בֶר וּ⁠מַלְכִּיאֵֽל׃","ẇ⁠bĕné֣y ʼáşé̌֗r yimĕná֧h wĕ⁠yişĕ̌wá֛h wĕ⁠yişĕ̌wi֥y ẇ⁠bĕriyʻá֖h wĕ⁠şê֣raẖ ʼàẖòţá֑⁠m ẇ⁠bĕné֣y bĕriyʻá֔h ẖe֖ber ẇ⁠malĕki̇yʼéֽl׃"],[46,18,"אֵ֚לֶּה בְּנֵ֣י זִלְפָּ֔ה אֲשֶׁר־נָתַ֥ן לָבָ֖ן לְ⁠לֵאָ֣ה בִתּ֑⁠וֹ וַ⁠תֵּ֤לֶד אֶת־אֵ֨לֶּה֙ לְ⁠יַעֲקֹ֔ב שֵׁ֥שׁ עֶשְׂרֵ֖ה נָֽפֶשׁ׃","ʼé֚lėh bĕ̇né֣y zilĕpá̇֔h ʼàşěr-náţa֥n lábá֖n lĕ⁠léʼá֣h biţ֑̇⁠wò wa⁠ţé֤̇led ʼeţ-ʼé֨lėh֙ lĕ⁠yaʻàqò֔b şé֥̌ş̌ ʻeşĕ̂ré֖h náֽpeş̌׃"],[46,19,"בְּנֵ֤י רָחֵל֙ אֵ֣שֶׁת יַֽעֲקֹ֔ב יוֹסֵ֖ף וּ⁠בִנְיָמִֽן׃","bĕ̇né֤y ráẖél֙ ʼé֣şěţ yaֽʻàqò֔b ywòsé֖p ẇ⁠binĕyámiֽn׃"],[46,20,"וַ⁠יִּוָּלֵ֣ד לְ⁠יוֹסֵף֮ בְּ⁠אֶ֣רֶץ מִצְרַיִם֒ אֲשֶׁ֤ר יָֽלְדָה־לּ⁠וֹ֙ אָֽסְנַ֔ת בַּת־פּ֥וֹטִי פֶ֖רַע כֹּהֵ֣ן אֹ֑ן אֶת־מְנַשֶּׁ֖ה וְ⁠אֶת־אֶפְרָֽיִם׃","wa⁠yi̇wá̇lé֣d lĕ⁠ywòsép֮ bĕ̇⁠ʼe֣reẕ miẕĕrayim֒ ʼàşě֤r yáֽlĕdáh-l̇⁠wò֙ ʼáֽsĕna֔ţ bȧţ-ṗ֥wòtiy pe֖raʻ kò̇hé֣n ʼò֑n ʼeţ-mĕnaşė֖̌h wĕ⁠ʼeţ-ʼepĕráֽyim׃"],[46,21,"וּ⁠בְנֵ֣י בִנְיָמִ֗ן בֶּ֤לַע וָ⁠בֶ֨כֶר֙ וְ⁠אַשְׁבֵּ֔ל גֵּרָ֥א וְ⁠נַעֲמָ֖ן אֵחִ֣י וָ⁠רֹ֑אשׁ מֻפִּ֥ים וְ⁠חֻפִּ֖ים וָ⁠אָֽרְדְּ׃","ẇ⁠bĕné֣y binĕyámi֗n bė֤laʻ wá⁠be֨ker֙ wĕ⁠ʼaşĕ̌bé̇֔l gé̇rá֥ʼ wĕ⁠naʻàmá֖n ʼéẖi֣y wá⁠rò֑ʼş̌ mupi֥̇ym wĕ⁠ẖupi֖̇ym wá⁠ʼáֽrĕdĕ̇׃"],[46,22,"אֵ֚לֶּה בְּנֵ֣י רָחֵ֔ל אֲשֶׁ֥ר יֻלַּ֖ד לְ⁠יַעֲקֹ֑ב כָּל־נֶ֖פֶשׁ אַרְבָּעָ֥ה עָשָֽׂר׃","ʼé֚lėh bĕ̇né֣y ráẖé֔l ʼàşě֥r yulȧ֖d lĕ⁠yaʻàqò֑b ká̇l-ne֖peş̌ ʼarĕbá̇ʻá֥h ʻáşáֽ̂r׃"],[46,23,"וּ⁠בְנֵי־דָ֖ן חֻשִֽׁים׃","ẇ⁠bĕnéy-dá֖n ẖuşǐֽym׃"],[46,24,"וּ⁠בְנֵ֖י נַפְתָּלִ֑י יַחְצְאֵ֥ל וְ⁠גוּנִ֖י וְ⁠יֵ֥צֶר וְ⁠שִׁלֵּֽם׃","ẇ⁠bĕné֖y napĕţá̇li֑y yaẖĕẕĕʼé֥l wĕ⁠gẇni֖y wĕ⁠yé֥ẕer wĕ⁠şǐléֽ̇m׃"],[46,25,"אֵ֚לֶּה בְּנֵ֣י בִלְהָ֔ה אֲשֶׁר־נָתַ֥ן לָבָ֖ן לְ⁠רָחֵ֣ל בִּתּ֑⁠וֹ וַ⁠תֵּ֧לֶד אֶת־אֵ֛לֶּה לְ⁠יַעֲקֹ֖ב כָּל־נֶ֥פֶשׁ שִׁבְעָֽה׃","ʼé֚lėh bĕ̇né֣y bilĕhá֔h ʼàşěr-náţa֥n lábá֖n lĕ⁠ráẖé֣l bi̇ţ֑̇⁠wò wa⁠ţé֧̇led ʼeţ-ʼé֛lėh lĕ⁠yaʻàqò֖b ká̇l-ne֥peş̌ şǐbĕʻáֽh׃"],[46,26,"כָּל־הַ֠⁠נֶּפֶשׁ הַ⁠בָּאָ֨ה לְ⁠יַעֲקֹ֤ב מִצְרַ֨יְמָ⁠ה֙ יֹצְאֵ֣י יְרֵכ֔⁠וֹ מִ⁠לְּ⁠בַ֖ד נְשֵׁ֣י בְנֵי־יַעֲקֹ֑ב כָּל־נֶ֖פֶשׁ שִׁשִּׁ֥ים וָ⁠שֵֽׁשׁ׃","ká̇l-ha֠⁠nėpeş̌ ha⁠bá̇ʼá֨h lĕ⁠yaʻàqò֤b miẕĕra֨yĕmá⁠h֙ yòẕĕʼé֣y yĕrék֔⁠wò mi⁠lĕ̇⁠ba֖d nĕşé֣̌y bĕnéy-yaʻàqò֑b ká̇l-ne֖peş̌ şǐşi֥̇̌ym wá⁠şéֽ̌ş̌׃"],[46,27,"וּ⁠בְנֵ֥י יוֹסֵ֛ף אֲשֶׁר־יֻלַּד־ל֥⁠וֹ בְ⁠מִצְרַ֖יִם נֶ֣פֶשׁ שְׁנָ֑יִם כָּל־הַ⁠נֶּ֧פֶשׁ לְ⁠בֵֽית־יַעֲקֹ֛ב הַ⁠בָּ֥אָה מִצְרַ֖יְמָ⁠ה שִׁבְעִֽים׃פ","ẇ⁠bĕné֥y ywòsé֛p ʼàşěr-yulȧd-l֥⁠wò bĕ⁠miẕĕra֖yim ne֣peş̌ şĕ̌ná֑yim ká̇l-ha⁠nė֧peş̌ lĕ⁠béֽyţ-yaʻàqò֛b ha⁠bá֥̇ʼáh miẕĕra֖yĕmá⁠h şǐbĕʻiֽym׃p"],[46,28,"וְ⁠אֶת־יְהוּדָ֞ה שָׁלַ֤ח לְ⁠פָנָי⁠ו֙ אֶל־יוֹסֵ֔ף לְ⁠הוֹרֹ֥ת לְ⁠פָנָ֖י⁠ו גֹּ֑שְׁנָ⁠ה וַ⁠יָּבֹ֖אוּ אַ֥רְצָ⁠ה גֹּֽשֶׁן׃","wĕ⁠ʼeţ-yĕhẇdá֞h şá̌la֤ẖ lĕ⁠pánáy⁠w֙ ʼel-ywòsé֔p lĕ⁠hwòrò֥ţ lĕ⁠páná֖y⁠w gò֑̇şĕ̌ná⁠h wa⁠yá̇bò֖ʼẇ ʼa֥rĕẕá⁠h gòֽ̇şěn׃"],[46,29,"וַ⁠יֶּאְסֹ֤ר יוֹסֵף֙ מֶרְכַּבְתּ֔⁠וֹ וַ⁠יַּ֛עַל לִ⁠קְרַֽאת־יִשְׂרָאֵ֥ל אָבִ֖י⁠ו גֹּ֑שְׁנָ⁠ה וַ⁠יֵּרָ֣א אֵלָ֗י⁠ו וַ⁠יִּפֹּל֙ עַל־צַוָּארָ֔י⁠ו וַ⁠יֵּ֥בְךְּ עַל־צַוָּארָ֖י⁠ו עֽוֹד׃","wa⁠yėʼĕsò֤r ywòsép֙ merĕkȧbĕţ̇֔⁠wò wa⁠yȧ֛ʻal li⁠qĕraֽʼţ-yişĕ̂ráʼé֥l ʼábi֖y⁠w gò֑̇şĕ̌ná⁠h wa⁠yé̇rá֣ʼ ʼélá֗y⁠w wa⁠yi̇pò̇l֙ ʻal-ẕawá̇ʼrá֔y⁠w wa⁠yé֥̇bĕkĕ̇ ʻal-ẕawá̇ʼrá֖y⁠w ʻֽwòd׃"],[46,30,"וַ⁠יֹּ֧אמֶר יִשְׂרָאֵ֛ל אֶל־יוֹסֵ֖ף אָמ֣וּתָה הַ⁠פָּ֑עַם אַחֲרֵי֙ רְאוֹתִ֣⁠י אֶת־פָּנֶ֔י⁠ךָ כִּ֥י עוֹדְ⁠ךָ֖ חָֽי׃","wa⁠yò֧̇ʼmer yişĕ̂ráʼé֛l ʼel-ywòsé֖p ʼám֣ẇţáh ha⁠pá֑̇ʻam ʼaẖàréy֙ rĕʼwòţi֣⁠y ʼeţ-pá̇ne֔y⁠ká ki֥̇y ʻwòdĕ⁠ká֖ ẖáֽy׃"],[46,31,"וַ⁠יֹּ֨אמֶר יוֹסֵ֤ף אֶל־אֶחָי⁠ו֙ וְ⁠אֶל־בֵּ֣ית אָבִ֔י⁠ו אֶעֱלֶ֖ה וְ⁠אַגִּ֣ידָה לְ⁠פַרְעֹ֑ה וְ⁠אֹֽמְרָ֣ה אֵלָ֔י⁠ו אַחַ֧⁠י וּ⁠בֵית־אָבִ֛⁠י אֲשֶׁ֥ר בְּ⁠אֶֽרֶץ־כְּנַ֖עַן בָּ֥אוּ אֵלָֽ⁠י׃","wa⁠yò̇֨ʼmer ywòsé֤p ʼel-ʼeẖáy⁠w֙ wĕ⁠ʼel-bé֣̇yţ ʼábi֔y⁠w ʼeʻèle֖h wĕ⁠ʼagi֣̇ydáh lĕ⁠parĕʻò֑h wĕ⁠ʼòֽmĕrá֣h ʼélá֔y⁠w ʼaẖa֧⁠y ẇ⁠béyţ-ʼábi֛⁠y ʼàşě֥r bĕ̇⁠ʼeֽreẕ-kĕ̇na֖ʻan bá֥̇ʼẇ ʼéláֽ⁠y׃"],[46,32,"וְ⁠הָ⁠אֲנָשִׁים֙ רֹ֣עֵי צֹ֔אן כִּֽי־אַנְשֵׁ֥י מִקְנֶ֖ה הָי֑וּ וְ⁠צֹאנָ֧⁠ם וּ⁠בְקָרָ֛⁠ם וְ⁠כָל־אֲשֶׁ֥ר לָ⁠הֶ֖ם הֵבִֽיאוּ׃","wĕ⁠há⁠ʼànáşǐym֙ rò֣ʻéy ẕò֔ʼn kiֽ̇y-ʼanĕşé֥̌y miqĕne֖h háy֑ẇ wĕ⁠ẕòʼná֧⁠m ẇ⁠bĕqárá֛⁠m wĕ⁠kál-ʼàşě֥r lá⁠he֖m hébiֽyʼẇ׃"],[46,33,"וְ⁠הָיָ֕ה כִּֽי־יִקְרָ֥א לָ⁠כֶ֖ם פַּרְעֹ֑ה וְ⁠אָמַ֖ר מַה־מַּעֲשֵׂי⁠כֶֽם׃","wĕ⁠háyá֕h kiֽ̇y-yiqĕrá֥ʼ lá⁠ke֖m pȧrĕʻò֑h wĕ⁠ʼáma֖r mah-mȧʻàşé̂y⁠keֽm׃"],[46,34,"וַ⁠אֲמַרְתֶּ֗ם אַנְשֵׁ֨י מִקְנֶ֜ה הָי֤וּ עֲבָדֶ֨י⁠ךָ֙ מִ⁠נְּעוּרֵ֣י⁠נוּ וְ⁠עַד־עַ֔תָּה גַּם־אֲנַ֖חְנוּ גַּם־אֲבֹתֵ֑י⁠נוּ בַּ⁠עֲב֗וּר תֵּשְׁבוּ֙ בְּ⁠אֶ֣רֶץ גֹּ֔שֶׁן כִּֽי־תוֹעֲבַ֥ת מִצְרַ֖יִם כָּל־רֹ֥עֵה צֹֽאן׃","wa⁠ʼàmarĕţė֗m ʼanĕşé̌֨y miqĕne֜h háy֤ẇ ʻàbáde֨y⁠ká֙ mi⁠nĕ̇ʻẇré֣y⁠nẇ wĕ⁠ʻad-ʻa֔ţá̇h gȧm-ʼàna֖ẖĕnẇ gȧm-ʼàbòţé֑y⁠nẇ bȧ⁠ʻàb֗ẇr ţé̇şĕ̌bẇ֙ bĕ̇⁠ʼe֣reẕ gò̇֔şěn kiֽ̇y-ţwòʻàba֥ţ miẕĕra֖yim ká̇l-rò֥ʻéh ẕòֽʼn׃"],[47,1,"וַ⁠יָּבֹ֣א יוֹסֵף֮ וַ⁠יַּגֵּ֣ד לְ⁠פַרְעֹה֒ וַ⁠יֹּ֗אמֶר אָבִ֨⁠י וְ⁠אַחַ֜⁠י וְ⁠צֹאנָ֤⁠ם וּ⁠בְקָרָ⁠ם֙ וְ⁠כָל־אֲשֶׁ֣ר לָ⁠הֶ֔ם בָּ֖אוּ מֵ⁠אֶ֣רֶץ כְּנָ֑עַן וְ⁠הִנָּ֖⁠ם בְּ⁠אֶ֥רֶץ גֹּֽשֶׁן׃","wa⁠yá̇bò֣ʼ ywòsép֮ wa⁠yȧgé֣̇d lĕ⁠parĕʻòh֒ wa⁠yò̇֗ʼmer ʼábi֨⁠y wĕ⁠ʼaẖa֜⁠y wĕ⁠ẕòʼná֤⁠m ẇ⁠bĕqárá⁠m֙ wĕ⁠kál-ʼàşě֣r lá⁠he֔m bá֖̇ʼẇ mé⁠ʼe֣reẕ kĕ̇ná֑ʻan wĕ⁠hiná֖̇⁠m bĕ̇⁠ʼe֥reẕ gòֽ̇şěn׃"],[47,2,"וּ⁠מִ⁠קְצֵ֣ה אֶחָ֔י⁠ו לָקַ֖ח חֲמִשָּׁ֣ה אֲנָשִׁ֑ים וַ⁠יַּצִּגֵ֖⁠ם לִ⁠פְנֵ֥י פַרְעֹֽה׃","ẇ⁠mi⁠qĕẕé֣h ʼeẖá֔y⁠w láqa֖ẖ ẖàmişá֣̇̌h ʼànáşǐ֑ym wa⁠yȧẕi̇gé֖⁠m li⁠pĕné֥y parĕʻòֽh׃"],[47,3,"וַ⁠יֹּ֧אמֶר פַּרְעֹ֛ה אֶל־אֶחָ֖י⁠ו מַה־מַּעֲשֵׂי⁠כֶ֑ם וַ⁠יֹּאמְר֣וּ אֶל־פַּרְעֹ֗ה רֹעֵ֥ה צֹאן֙ עֲבָדֶ֔י⁠ךָ גַּם־אֲנַ֖חְנוּ גַּם־אֲבוֹתֵֽי⁠נוּ׃","wa⁠yò֧̇ʼmer pȧrĕʻò֛h ʼel-ʼeẖá֖y⁠w mah-mȧʻàşé̂y⁠ke֑m wa⁠yò̇ʼmĕr֣ẇ ʼel-pȧrĕʻò֗h ròʻé֥h ẕòʼn֙ ʻàbáde֔y⁠ká gȧm-ʼàna֖ẖĕnẇ gȧm-ʼàbwòţéֽy⁠nẇ׃"],[47,4,"וַ⁠יֹּאמְר֣וּ אֶל־פַּרְעֹ֗ה לָ⁠ג֣וּר בָּ⁠אָרֶץ֮ בָּאנוּ֒ כִּי־אֵ֣ין מִרְעֶ֗ה לַ⁠צֹּאן֙ אֲשֶׁ֣ר לַ⁠עֲבָדֶ֔י⁠ךָ כִּֽי־כָבֵ֥ד הָ⁠רָעָ֖ב בְּ⁠אֶ֣רֶץ כְּנָ֑עַן וְ⁠עַתָּ֛ה יֵֽשְׁבוּ־נָ֥א עֲבָדֶ֖י⁠ךָ בְּ⁠אֶ֥רֶץ גֹּֽשֶׁן׃","wa⁠yò̇ʼmĕr֣ẇ ʼel-pȧrĕʻò֗h lá⁠g֣ẇr bá̇⁠ʼáreẕ֮ bá̇ʼnẇ֒ ki̇y-ʼé֣yn mirĕʻe֗h la⁠ẕò̇ʼn֙ ʼàşě֣r la⁠ʻàbáde֔y⁠ká kiֽ̇y-kábé֥d há⁠ráʻá֖b bĕ̇⁠ʼe֣reẕ kĕ̇ná֑ʻan wĕ⁠ʻaţá֛̇h yéֽşĕ̌bẇ-ná֥ʼ ʻàbáde֖y⁠ká bĕ̇⁠ʼe֥reẕ gòֽ̇şěn׃"],[47,5,"וַ⁠יֹּ֣אמֶר פַּרְעֹ֔ה אֶל־יוֹסֵ֖ף לֵ⁠אמֹ֑ר אָבִ֥י⁠ךָ וְ⁠אַחֶ֖י⁠ךָ בָּ֥אוּ אֵלֶֽי⁠ךָ׃","wa⁠yò֣̇ʼmer pȧrĕʻò֔h ʼel-ywòsé֖p lé⁠ʼmò֑r ʼábi֥y⁠ká wĕ⁠ʼaẖe֖y⁠ká bá֥̇ʼẇ ʼéleֽy⁠ká׃"],[47,6,"אֶ֤רֶץ מִצְרַ֨יִם֙ לְ⁠פָנֶ֣י⁠ךָ הִ֔וא בְּ⁠מֵיטַ֣ב הָ⁠אָ֔רֶץ הוֹשֵׁ֥ב אֶת־אָבִ֖י⁠ךָ וְ⁠אֶת־אַחֶ֑י⁠ךָ יֵשְׁבוּ֙ בְּ⁠אֶ֣רֶץ גֹּ֔שֶׁן וְ⁠אִם־יָדַ֗עְתָּ וְ⁠יֶשׁ־בָּ⁠ם֙ אַנְשֵׁי־חַ֔יִל וְ⁠שַׂמְתָּ֛⁠ם שָׂרֵ֥י מִקְנֶ֖ה עַל־אֲשֶׁר־לִֽ⁠י׃","ʼe֤reẕ miẕĕra֨yim֙ lĕ⁠páne֣y⁠ká hi֔wʼ bĕ̇⁠méyta֣b há⁠ʼá֔reẕ hwòşé֥̌b ʼeţ-ʼábi֖y⁠ká wĕ⁠ʼeţ-ʼaẖe֑y⁠ká yéşĕ̌bẇ֙ bĕ̇⁠ʼe֣reẕ gò̇֔şěn wĕ⁠ʼim-yáda֗ʻĕţá̇ wĕ⁠yeş̌-bá̇⁠m֙ ʼanĕşé̌y-ẖa֔yil wĕ⁠şâmĕţá֛̇⁠m şá̂ré֥y miqĕne֖h ʻal-ʼàşěr-liֽ⁠y׃"],[47,7,"וַ⁠יָּבֵ֤א יוֹסֵף֙ אֶת־יַֽעֲקֹ֣ב אָבִ֔י⁠ו וַ⁠יַּֽעֲמִדֵ֖⁠הוּ לִ⁠פְנֵ֣י פַרְעֹ֑ה וַ⁠יְבָ֥רֶךְ יַעֲקֹ֖ב אֶת־פַּרְעֹֽה׃","wa⁠yá̇bé֤ʼ ywòsép֙ ʼeţ-yaֽʻàqò֣b ʼábi֔y⁠w wa⁠yȧֽʻàmidé֖⁠hẇ li⁠pĕné֣y parĕʻò֑h wa⁠yĕbá֥rekĕ yaʻàqò֖b ʼeţ-pȧrĕʻòֽh׃"],[47,8,"וַ⁠יֹּ֥אמֶר פַּרְעֹ֖ה אֶֽל־יַעֲקֹ֑ב כַּ⁠מָּ֕ה יְמֵ֖י שְׁנֵ֥י חַיֶּֽי⁠ךָ׃","wa⁠yò֥̇ʼmer pȧrĕʻò֖h ʼeֽl-yaʻàqò֑b kȧ⁠má̇֕h yĕmé֖y şĕ̌né֥y ẖayėֽy⁠ká׃"],[47,9,"וַ⁠יֹּ֤אמֶר יַעֲקֹב֙ אֶל־פַּרְעֹ֔ה יְמֵי֙ שְׁנֵ֣י מְגוּרַ֔⁠י שְׁלֹשִׁ֥ים וּ⁠מְאַ֖ת שָׁנָ֑ה מְעַ֣ט וְ⁠רָעִ֗ים הָיוּ֙ יְמֵי֙ שְׁנֵ֣י חַיַּ֔⁠י וְ⁠לֹ֣א הִשִּׂ֗יגוּ אֶת־יְמֵי֙ שְׁנֵי֙ חַיֵּ֣י אֲבֹתַ֔⁠י בִּ⁠ימֵ֖י מְגוּרֵי⁠הֶֽם׃","wa⁠yò֤̇ʼmer yaʻàqòb֙ ʼel-pȧrĕʻò֔h yĕméy֙ şĕ̌né֣y mĕgẇra֔⁠y şĕ̌lòşǐ֥ym ẇ⁠mĕʼa֖ţ şá̌ná֑h mĕʻa֣t wĕ⁠ráʻi֗ym háyẇ֙ yĕméy֙ şĕ̌né֣y ẖayȧ֔⁠y wĕ⁠lò֣ʼ hişi̇̂֗ygẇ ʼeţ-yĕméy֙ şĕ̌néy֙ ẖayé֣̇y ʼàbòţa֔⁠y bi̇⁠ymé֖y mĕgẇréy⁠heֽm׃"],[47,10,"וַ⁠יְבָ֥רֶךְ יַעֲקֹ֖ב אֶת־פַּרְעֹ֑ה וַ⁠יֵּצֵ֖א מִ⁠לִּ⁠פְנֵ֥י פַרְעֹֽה׃","wa⁠yĕbá֥rekĕ yaʻàqò֖b ʼeţ-pȧrĕʻò֑h wa⁠yé̇ẕé֖ʼ mi⁠li̇⁠pĕné֥y parĕʻòֽh׃"],[47,11,"וַ⁠יּוֹשֵׁ֣ב יוֹסֵף֮ אֶת־אָבִ֣י⁠ו וְ⁠אֶת־אֶחָי⁠ו֒ וַ⁠יִּתֵּ֨ן לָ⁠הֶ֤ם אֲחֻזָּה֙ בְּ⁠אֶ֣רֶץ מִצְרַ֔יִם בְּ⁠מֵיטַ֥ב הָ⁠אָ֖רֶץ בְּ⁠אֶ֣רֶץ רַעְמְסֵ֑ס כַּ⁠אֲשֶׁ֖ר צִוָּ֥ה פַרְעֹֽה׃","wa⁠ẏwòşé֣̌b ywòsép֮ ʼeţ-ʼábi֣y⁠w wĕ⁠ʼeţ-ʼeẖáy⁠w֒ wa⁠yi̇ţé̇֨n lá⁠he֤m ʼàẖuzá̇h֙ bĕ̇⁠ʼe֣reẕ miẕĕra֔yim bĕ̇⁠méyta֥b há⁠ʼá֖reẕ bĕ̇⁠ʼe֣reẕ raʻĕmĕsé֑s kȧ⁠ʼàşě֖r ẕiwá֥̇h parĕʻòֽh׃"],[47,12,"וַ⁠יְכַלְכֵּ֤ל יוֹסֵף֙ אֶת־אָבִ֣י⁠ו וְ⁠אֶת־אֶחָ֔י⁠ו וְ⁠אֵ֖ת כָּל־בֵּ֣ית אָבִ֑י⁠ו לֶ֖חֶם לְ⁠פִ֥י הַ⁠טָּֽף׃","wa⁠yĕkalĕké֤̇l ywòsép֙ ʼeţ-ʼábi֣y⁠w wĕ⁠ʼeţ-ʼeẖá֔y⁠w wĕ⁠ʼé֖ţ ká̇l-bé֣̇yţ ʼábi֑y⁠w le֖ẖem lĕ⁠pi֥y ha⁠táֽ̇p׃"],[47,13,"וְ⁠לֶ֤חֶם אֵין֙ בְּ⁠כָל־הָ⁠אָ֔רֶץ כִּֽי־כָבֵ֥ד הָ⁠רָעָ֖ב מְאֹ֑ד וַ⁠תֵּ֜לַהּ אֶ֤רֶץ מִצְרַ֨יִם֙ וְ⁠אֶ֣רֶץ כְּנַ֔עַן מִ⁠פְּנֵ֖י הָ⁠רָעָֽב׃","wĕ⁠le֤ẖem ʼéyn֙ bĕ̇⁠kál-há⁠ʼá֔reẕ kiֽ̇y-kábé֥d há⁠ráʻá֖b mĕʼò֑d wa⁠ţé̇֜laḣ ʼe֤reẕ miẕĕra֨yim֙ wĕ⁠ʼe֣reẕ kĕ̇na֔ʻan mi⁠pĕ̇né֖y há⁠ráʻáֽb׃"],[47,14,"וַ⁠יְלַקֵּ֣ט יוֹסֵ֗ף אֶת־כָּל־הַ⁠כֶּ֨סֶף֙ הַ⁠נִּמְצָ֤א בְ⁠אֶֽרֶץ־מִצְרַ֨יִם֙ וּ⁠בְ⁠אֶ֣רֶץ כְּנַ֔עַן בַּ⁠שֶּׁ֖בֶר אֲשֶׁר־הֵ֣ם שֹׁבְרִ֑ים וַ⁠יָּבֵ֥א יוֹסֵ֛ף אֶת־הַ⁠כֶּ֖סֶף בֵּ֥יתָ⁠ה פַרְעֹֽה׃","wa⁠yĕlaqé֣̇t ywòsé֗p ʼeţ-ká̇l-ha⁠kė֨sep֙ ha⁠ni̇mĕẕá֤ʼ bĕ⁠ʼeֽreẕ-miẕĕra֨yim֙ ẇ⁠bĕ⁠ʼe֣reẕ kĕ̇na֔ʻan bȧ⁠şė֖̌ber ʼàşěr-hé֣m şò̌bĕri֑ym wa⁠yá̇bé֥ʼ ywòsé֛p ʼeţ-ha⁠kė֖sep bé֥̇yţá⁠h parĕʻòֽh׃"],[47,15,"וַ⁠יִּתֹּ֣ם הַ⁠כֶּ֗סֶף מֵ⁠אֶ֣רֶץ מִצְרַיִם֮ וּ⁠מֵ⁠אֶ֣רֶץ כְּנַעַן֒ וַ⁠יָּבֹאוּ֩ כָל־מִצְרַ֨יִם אֶל־יוֹסֵ֤ף לֵ⁠אמֹר֙ הָֽבָ⁠ה־לָּ֣⁠נוּ לֶ֔חֶם וְ⁠לָ֥⁠מָּה נָמ֖וּת נֶגְדֶּ֑⁠ךָ כִּ֥י אָפֵ֖ס כָּֽסֶף׃","wa⁠yi̇ţò֣̇m ha⁠kė֗sep mé⁠ʼe֣reẕ miẕĕrayim֮ ẇ⁠mé⁠ʼe֣reẕ kĕ̇naʻan֒ wa⁠yá̇bòʼẇ֩ kál-miẕĕra֨yim ʼel-ywòsé֤p lé⁠ʼmòr֙ háֽbá⁠h-lá֣̇⁠nẇ le֔ẖem wĕ⁠lá֥⁠má̇h nám֖ẇţ negĕdė֑⁠ká ki֥̇y ʼápé֖s káֽ̇sep׃"],[47,16,"וַ⁠יֹּ֤אמֶר יוֹסֵף֙ הָב֣וּ מִקְנֵי⁠כֶ֔ם וְ⁠אֶתְּנָ֥ה לָ⁠כֶ֖ם בְּ⁠מִקְנֵי⁠כֶ֑ם אִם־אָפֵ֖ס כָּֽסֶף׃","wa⁠yò֤̇ʼmer ywòsép֙ háb֣ẇ miqĕnéy⁠ke֔m wĕ⁠ʼeţĕ̇ná֥h lá⁠ke֖m bĕ̇⁠miqĕnéy⁠ke֑m ʼim-ʼápé֖s káֽ̇sep׃"],[47,17,"וַ⁠יָּבִ֣יאוּ אֶת־מִקְנֵי⁠הֶם֮ אֶל־יוֹסֵף֒ וַ⁠יִּתֵּ֣ן לָ⁠הֶם֩ יוֹסֵ֨ף לֶ֜חֶם בַּ⁠סּוּסִ֗ים וּ⁠בְ⁠מִקְנֵ֥ה הַ⁠צֹּ֛אן וּ⁠בְ⁠מִקְנֵ֥ה הַ⁠בָּקָ֖ר וּ⁠בַ⁠חֲמֹרִ֑ים וַ⁠יְנַהֲלֵ֤⁠ם בַּ⁠לֶּ֨חֶם֙ בְּ⁠כָל־מִקְנֵ⁠הֶ֔ם בַּ⁠שָּׁנָ֖ה הַ⁠הִֽוא׃","wa⁠yá̇bi֣yʼẇ ʼeţ-miqĕnéy⁠hem֮ ʼel-ywòsép֒ wa⁠yi̇ţé֣̇n lá⁠hem֩ ywòsé֨p le֜ẖem bȧ⁠ṡẇsi֗ym ẇ⁠bĕ⁠miqĕné֥h ha⁠ẕò֛̇ʼn ẇ⁠bĕ⁠miqĕné֥h ha⁠bá̇qá֖r ẇ⁠ba⁠ẖàmòri֑ym wa⁠yĕnahàlé֤⁠m bȧ⁠lė֨ẖem֙ bĕ̇⁠kál-miqĕné⁠he֔m bȧ⁠şá̇̌ná֖h ha⁠hiֽwʼ׃"],[47,18,"וַ⁠תִּתֹּם֮ הַ⁠שָּׁנָ֣ה הַ⁠הִוא֒ וַ⁠יָּבֹ֨אוּ אֵלָ֜י⁠ו בַּ⁠שָּׁנָ֣ה הַ⁠שֵּׁנִ֗ית וַ⁠יֹּ֤אמְרוּ ל⁠וֹ֙ לֹֽא־נְכַחֵ֣ד מֵֽ⁠אֲדֹנִ֔⁠י כִּ֚י אִם־תַּ֣ם הַ⁠כֶּ֔סֶף וּ⁠מִקְנֵ֥ה הַ⁠בְּהֵמָ֖ה אֶל־אֲדֹנִ֑⁠י לֹ֤א נִשְׁאַר֙ לִ⁠פְנֵ֣י אֲדֹנִ֔⁠י בִּלְתִּ֥י אִם־גְּוִיָּתֵ֖⁠נוּ וְ⁠אַדְמָתֵֽ⁠נוּ׃","wa⁠ţi̇ţò̇m֮ ha⁠şá̇̌ná֣h ha⁠hiwʼ֒ wa⁠yá̇bò֨ʼẇ ʼélá֜y⁠w bȧ⁠şá̇̌ná֣h ha⁠şé̇̌ni֗yţ wa⁠yò֤̇ʼmĕrẇ l⁠wò֙ lòֽʼ-nĕkaẖé֣d méֽ⁠ʼàdòni֔⁠y ki֚̇y ʼim-ţȧ֣m ha⁠kė֔sep ẇ⁠miqĕné֥h ha⁠bĕ̇hémá֖h ʼel-ʼàdòni֑⁠y lò֤ʼ nişĕ̌ʼar֙ li⁠pĕné֣y ʼàdòni֔⁠y bi̇lĕţi֥̇y ʼim-gĕ̇wiyá̇ţé֖⁠nẇ wĕ⁠ʼadĕmáţéֽ⁠nẇ׃"],[47,19,"לָ֧⁠מָּה נָמ֣וּת לְ⁠עֵינֶ֗י⁠ךָ גַּם־אֲנַ֨חְנוּ֙ גַּ֣ם אַדְמָתֵ֔⁠נוּ קְנֵֽה־אֹתָ֥⁠נוּ וְ⁠אֶת־אַדְמָתֵ֖⁠נוּ בַּ⁠לָּ֑חֶם וְ⁠נִֽהְיֶ֞ה אֲנַ֤חְנוּ וְ⁠אַדְמָתֵ֨⁠נוּ֙ עֲבָדִ֣ים לְ⁠פַרְעֹ֔ה וְ⁠תֶן־זֶ֗רַע וְ⁠נִֽחְיֶה֙ וְ⁠לֹ֣א נָמ֔וּת וְ⁠הָ⁠אֲדָמָ֖ה לֹ֥א תֵשָֽׁם׃","lá֧⁠má̇h nám֣ẇţ lĕ⁠ʻéyne֗y⁠ká gȧm-ʼàna֨ẖĕnẇ֙ gȧ֣m ʼadĕmáţé֔⁠nẇ qĕnéֽh-ʼòţá֥⁠nẇ wĕ⁠ʼeţ-ʼadĕmáţé֖⁠nẇ bȧ⁠lá֑̇ẖem wĕ⁠niֽhĕye֞h ʼàna֤ẖĕnẇ wĕ⁠ʼadĕmáţé֨⁠nẇ֙ ʻàbádi֣ym lĕ⁠parĕʻò֔h wĕ⁠ţen-ze֗raʻ wĕ⁠niֽẖĕyeh֙ wĕ⁠lò֣ʼ nám֔ẇţ wĕ⁠há⁠ʼàdámá֖h lò֥ʼ ţéşáֽ̌m׃"],[47,20,"וַ⁠יִּ֨קֶן יוֹסֵ֜ף אֶת־כָּל־אַדְמַ֤ת מִצְרַ֨יִם֙ לְ⁠פַרְעֹ֔ה כִּֽי־מָכְר֤וּ מִצְרַ֨יִם֙ אִ֣ישׁ שָׂדֵ֔⁠הוּ כִּֽי־חָזַ֥ק עֲלֵ⁠הֶ֖ם הָ⁠רָעָ֑ב וַ⁠תְּהִ֥י הָ⁠אָ֖רֶץ לְ⁠פַרְעֹֽה׃","wa⁠yi̇֨qen ywòsé֜p ʼeţ-ká̇l-ʼadĕma֤ţ miẕĕra֨yim֙ lĕ⁠parĕʻò֔h kiֽ̇y-mákĕr֤ẇ miẕĕra֨yim֙ ʼi֣yş̌ şá̂dé֔⁠hẇ kiֽ̇y-ẖáza֥q ʻàlé⁠he֖m há⁠ráʻá֑b wa⁠ţĕ̇hi֥y há⁠ʼá֖reẕ lĕ⁠parĕʻòֽh׃"],[47,21,"וְ⁠אֶ֨ת־הָ⁠עָ֔ם הֶעֱבִ֥יר אֹת֖⁠וֹ לֶ⁠עָרִ֑ים מִ⁠קְצֵ֥ה גְבוּל־מִצְרַ֖יִם וְ⁠עַד־קָצֵֽ⁠הוּ׃","wĕ⁠ʼe֨ţ-há⁠ʻá֔m heʻèbi֥yr ʼòţ֖⁠wò le⁠ʻári֑ym mi⁠qĕẕé֥h gĕbẇl-miẕĕra֖yim wĕ⁠ʻad-qáẕéֽ⁠hẇ׃"],[47,22,"רַ֛ק אַדְמַ֥ת הַ⁠כֹּהֲנִ֖ים לֹ֣א קָנָ֑ה כִּי֩ חֹ֨ק לַ⁠כֹּהֲנִ֜ים מֵ⁠אֵ֣ת פַּרְעֹ֗ה וְ⁠אָֽכְל֤וּ אֶת־חֻקָּ⁠ם֙ אֲשֶׁ֨ר נָתַ֤ן לָ⁠הֶם֙ פַּרְעֹ֔ה עַל־כֵּ֕ן לֹ֥א מָכְר֖וּ אֶת־אַדְמָתָֽ⁠ם׃","ra֛q ʼadĕma֥ţ ha⁠kò̇hàni֖ym lò֣ʼ qáná֑h ki̇y֩ ẖò֨q la⁠kò̇hàni֜ym mé⁠ʼé֣ţ pȧrĕʻò֗h wĕ⁠ʼáֽkĕl֤ẇ ʼeţ-ẖuqá̇⁠m֙ ʼàşě֨r náţa֤n lá⁠hem֙ pȧrĕʻò֔h ʻal-ké̇֕n lò֥ʼ mákĕr֖ẇ ʼeţ-ʼadĕmáţáֽ⁠m׃"],[47,23,"וַ⁠יֹּ֤אמֶר יוֹסֵף֙ אֶל־הָ⁠עָ֔ם הֵן֩ קָנִ֨יתִי אֶתְ⁠כֶ֥ם הַ⁠יּ֛וֹם וְ⁠אֶת־אַדְמַתְ⁠כֶ֖ם לְ⁠פַרְעֹ֑ה הֵֽא־לָ⁠כֶ֣ם זֶ֔רַע וּ⁠זְרַעְתֶּ֖ם אֶת־הָ⁠אֲדָמָֽה׃","wa⁠yò֤̇ʼmer ywòsép֙ ʼel-há⁠ʻá֔m hén֩ qáni֨yţiy ʼeţĕ⁠ke֥m ha⁠ẏ֛wòm wĕ⁠ʼeţ-ʼadĕmaţĕ⁠ke֖m lĕ⁠parĕʻò֑h héֽʼ-lá⁠ke֣m ze֔raʻ ẇ⁠zĕraʻĕţė֖m ʼeţ-há⁠ʼàdámáֽh׃"],[47,24,"וְ⁠הָיָה֙ בַּ⁠תְּבוּאֹ֔ת וּ⁠נְתַתֶּ֥ם חֲמִישִׁ֖ית לְ⁠פַרְעֹ֑ה וְ⁠אַרְבַּ֣ע הַ⁠יָּדֹ֡ת יִהְיֶ֣ה לָ⁠כֶם֩ לְ⁠זֶ֨רַע הַ⁠שָּׂדֶ֧ה וּֽ⁠לְ⁠אָכְלְ⁠כֶ֛ם וְ⁠לַ⁠אֲשֶׁ֥ר בְּ⁠בָתֵּי⁠כֶ֖ם וְ⁠לֶ⁠אֱכֹ֥ל לְ⁠טַפְּ⁠כֶֽם׃","wĕ⁠háyáh֙ bȧ⁠ţĕ̇bẇʼò֔ţ ẇ⁠nĕţaţė֥m ẖàmiyşǐ֖yţ lĕ⁠parĕʻò֑h wĕ⁠ʼarĕbȧ֣ʻ ha⁠yá̇dò֡ţ yihĕye֣h lá⁠kem֩ lĕ⁠ze֨raʻ ha⁠şá̇̂de֧h ẇֽ⁠lĕ⁠ʼákĕlĕ⁠ke֛m wĕ⁠la⁠ʼàşě֥r bĕ̇⁠báţé̇y⁠ke֖m wĕ⁠le⁠ʼèkò֥l lĕ⁠tapĕ̇⁠keֽm׃"],[47,25,"וַ⁠יֹּאמְר֖וּ הֶחֱיִתָ֑⁠נוּ נִמְצָא־חֵן֙ בְּ⁠עֵינֵ֣י אֲדֹנִ֔⁠י וְ⁠הָיִ֥ינוּ עֲבָדִ֖ים לְ⁠פַרְעֹֽה׃","wa⁠yò̇ʼmĕr֖ẇ heẖèyiţá֑⁠nẇ nimĕẕáʼ-ẖén֙ bĕ̇⁠ʻéyné֣y ʼàdòni֔⁠y wĕ⁠háyi֥ynẇ ʻàbádi֖ym lĕ⁠parĕʻòֽh׃"],[47,26,"וַ⁠יָּ֣שֶׂם אֹתָ֣⁠הּ יוֹסֵ֡ף לְ⁠חֹק֩ עַד־הַ⁠יּ֨וֹם הַ⁠זֶּ֜ה עַל־אַדְמַ֥ת מִצְרַ֛יִם לְ⁠פַרְעֹ֖ה לַ⁠חֹ֑מֶשׁ רַ֞ק אַדְמַ֤ת הַ⁠כֹּֽהֲנִים֙ לְ⁠בַדָּ֔⁠ם לֹ֥א הָיְתָ֖ה לְ⁠פַרְעֹֽה׃","wa⁠yá֣̇şêm ʼòţá֣⁠ḣ ywòsé֡p lĕ⁠ẖòq֩ ʻad-ha⁠ẏ֨wòm ha⁠zė֜h ʻal-ʼadĕma֥ţ miẕĕra֛yim lĕ⁠parĕʻò֖h la⁠ẖò֑meş̌ ra֞q ʼadĕma֤ţ ha⁠kòֽ̇hàniym֙ lĕ⁠badá̇֔⁠m lò֥ʼ háyĕţá֖h lĕ⁠parĕʻòֽh׃"],[47,27,"וַ⁠יֵּ֧שֶׁב יִשְׂרָאֵ֛ל בְּ⁠אֶ֥רֶץ מִצְרַ֖יִם בְּ⁠אֶ֣רֶץ גֹּ֑שֶׁן וַ⁠יֵּאָחֲז֣וּ בָ֔⁠הּ וַ⁠יִּפְר֥וּ וַ⁠יִּרְבּ֖וּ מְאֹֽד׃","wa⁠yé֧̇şěb yişĕ̂ráʼé֛l bĕ̇⁠ʼe֥reẕ miẕĕra֖yim bĕ̇⁠ʼe֣reẕ gò֑̇şěn wa⁠yé̇ʼáẖàz֣ẇ bá֔⁠ḣ wa⁠yi̇pĕr֥ẇ wa⁠yi̇rĕḃ֖ẇ mĕʼòֽd׃"],[47,28,"וַ⁠יְחִ֤י יַעֲקֹב֙ בְּ⁠אֶ֣רֶץ מִצְרַ֔יִם שְׁבַ֥ע עֶשְׂרֵ֖ה שָׁנָ֑ה וַ⁠יְהִ֤י יְמֵֽי־יַעֲקֹב֙ שְׁנֵ֣י חַיָּ֔י⁠ו שֶׁ֣בַע שָׁנִ֔ים וְ⁠אַרְבָּעִ֥ים וּ⁠מְאַ֖ת שָׁנָֽה׃","wa⁠yĕẖi֤y yaʻàqòb֙ bĕ̇⁠ʼe֣reẕ miẕĕra֔yim şĕ̌ba֥ʻ ʻeşĕ̂ré֖h şá̌ná֑h wa⁠yĕhi֤y yĕméֽy-yaʻàqòb֙ şĕ̌né֣y ẖayá̇֔y⁠w şě֣baʻ şá̌ni֔ym wĕ⁠ʼarĕbá̇ʻi֥ym ẇ⁠mĕʼa֖ţ şá̌náֽh׃"],[47,29,"וַ⁠יִּקְרְב֣וּ יְמֵֽי־יִשְׂרָאֵ֘ל לָ⁠מוּת֒ וַ⁠יִּקְרָ֣א ׀ לִ⁠בְנ֣⁠וֹ לְ⁠יוֹסֵ֗ף וַ⁠יֹּ֤אמֶר ל⁠וֹ֙ אִם־נָ֨א מָצָ֤אתִי חֵן֙ בְּ⁠עֵינֶ֔י⁠ךָ שִֽׂים־נָ֥א יָדְ⁠ךָ֖ תַּ֣חַת יְרֵכִ֑⁠י וְ⁠עָשִׂ֤יתָ עִמָּדִ⁠י֙ חֶ֣סֶד וֶ⁠אֱמֶ֔ת אַל־נָ֥א תִקְבְּרֵ֖⁠נִי בְּ⁠מִצְרָֽיִם׃","wa⁠yi̇qĕrĕb֣ẇ yĕméֽy-yişĕ̂ráʼé֘l lá⁠mẇţ֒ wa⁠yi̇qĕrá֣ʼ ׀ li⁠bĕn֣⁠wò lĕ⁠ywòsé֗p wa⁠yò֤̇ʼmer l⁠wò֙ ʼim-ná֨ʼ máẕá֤ʼţiy ẖén֙ bĕ̇⁠ʻéyne֔y⁠ká şîֽym-ná֥ʼ yádĕ⁠ká֖ ţȧ֣ẖaţ yĕréki֑⁠y wĕ⁠ʻáşî֤yţá ʻimá̇di⁠y֙ ẖe֣sed we⁠ʼème֔ţ ʼal-ná֥ʼ ţiqĕbĕ̇ré֖⁠niy bĕ̇⁠miẕĕráֽyim׃"],[47,30,"וְ⁠שָֽׁכַבְתִּי֙ עִם־אֲבֹתַ֔⁠י וּ⁠נְשָׂאתַ֨⁠נִי֙ מִ⁠מִּצְרַ֔יִם וּ⁠קְבַרְתַּ֖⁠נִי בִּ⁠קְבֻרָתָ֑⁠ם וַ⁠יֹּאמַ֕ר אָנֹכִ֖י אֶֽעֱשֶׂ֥ה כִ⁠דְבָרֶֽ⁠ךָ׃","wĕ⁠şáֽ̌kabĕţi̇y֙ ʻim-ʼàbòţa֔⁠y ẇ⁠nĕşá̂ʼţa֨⁠niy֙ mi⁠mi̇ẕĕra֔yim ẇ⁠qĕbarĕţȧ֖⁠niy bi̇⁠qĕburáţá֑⁠m wa⁠yò̇ʼma֕r ʼánòki֖y ʼeֽʻèşê֥h ki⁠dĕbáreֽ⁠ká׃"],[47,31,"וַ⁠יֹּ֗אמֶר הִשָּֽׁבְעָ⁠ה֙ לִ֔⁠י וַ⁠יִּשָּׁבַ֖ע ל֑⁠וֹ וַ⁠יִּשְׁתַּ֥חוּ יִשְׂרָאֵ֖ל עַל־רֹ֥אשׁ הַ⁠מִּטָּֽה׃פ","wa⁠yò̇֗ʼmer hişáֽ̇̌bĕʻá⁠h֙ li֔⁠y wa⁠yi̇şá̇̌ba֖ʻ l֑⁠wò wa⁠yi̇şĕ̌ţȧ֥ẖẇ yişĕ̂ráʼé֖l ʻal-rò֥ʼş̌ ha⁠mi̇táֽ̇h׃p"],[48,1,"וַ⁠יְהִ֗י אַחֲרֵי֙ הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה וַ⁠יֹּ֣אמֶר לְ⁠יוֹסֵ֔ף הִנֵּ֥ה אָבִ֖י⁠ךָ חֹלֶ֑ה וַ⁠יִּקַּ֞ח אֶת־שְׁנֵ֤י בָנָי⁠ו֙ עִמּ֔⁠וֹ אֶת־מְנַשֶּׁ֖ה וְ⁠אֶת־אֶפְרָֽיִם׃","wa⁠yĕhi֗y ʼaẖàréy֙ ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh wa⁠yò֣̇ʼmer lĕ⁠ywòsé֔p hiné֥̇h ʼábi֖y⁠ká ẖòle֑h wa⁠yi̇qȧ֞ẖ ʼeţ-şĕ̌né֤y bánáy⁠w֙ ʻiṁ֔⁠wò ʼeţ-mĕnaşė֖̌h wĕ⁠ʼeţ-ʼepĕráֽyim׃"],[48,2,"וַ⁠יַּגֵּ֣ד לְ⁠יַעֲקֹ֔ב וַ⁠יֹּ֕אמֶר הִנֵּ֛ה בִּנְ⁠ךָ֥ יוֹסֵ֖ף בָּ֣א אֵלֶ֑י⁠ךָ וַ⁠יִּתְחַזֵּק֙ יִשְׂרָאֵ֔ל וַ⁠יֵּ֖שֶׁב עַל־הַ⁠מִּטָּֽה׃","wa⁠yȧgé֣̇d lĕ⁠yaʻàqò֔b wa⁠yò̇֕ʼmer hiné֛̇h bi̇nĕ⁠ká֥ ywòsé֖p bá֣̇ʼ ʼéle֑y⁠ká wa⁠yi̇ţĕẖazé̇q֙ yişĕ̂ráʼé֔l wa⁠yé֖̇şěb ʻal-ha⁠mi̇táֽ̇h׃"],[48,3,"וַ⁠יֹּ֤אמֶר יַעֲקֹב֙ אֶל־יוֹסֵ֔ף אֵ֥ל שַׁדַּ֛י נִרְאָֽה־אֵלַ֥⁠י בְּ⁠ל֖וּז בְּ⁠אֶ֣רֶץ כְּנָ֑עַן וַ⁠יְבָ֖רֶךְ אֹתִֽ⁠י׃","wa⁠yò֤̇ʼmer yaʻàqòb֙ ʼel-ywòsé֔p ʼé֥l şǎdȧ֛y nirĕʼáֽh-ʼéla֥⁠y bĕ̇⁠l֖ẇz bĕ̇⁠ʼe֣reẕ kĕ̇ná֑ʻan wa⁠yĕbá֖rekĕ ʼòţiֽ⁠y׃"],[48,4,"וַ⁠יֹּ֣אמֶר אֵלַ֗⁠י הִנְ⁠נִ֤י מַפְרְ⁠ךָ֙ וְ⁠הִרְבִּיתִ֔⁠ךָ וּ⁠נְתַתִּ֖י⁠ךָ לִ⁠קְהַ֣ל עַמִּ֑ים וְ⁠נָ֨תַתִּ֜י אֶת־הָ⁠אָ֧רֶץ הַ⁠זֹּ֛את לְ⁠זַרְעֲ⁠ךָ֥ אַחֲרֶ֖י⁠ךָ אֲחֻזַּ֥ת עוֹלָֽם׃","wa⁠yò֣̇ʼmer ʼéla֗⁠y hinĕ⁠ni֤y mapĕrĕ⁠ká֙ wĕ⁠hirĕbi̇yţi֔⁠ká ẇ⁠nĕţaţi֖̇y⁠ká li⁠qĕha֣l ʻami֑̇ym wĕ⁠ná֨ţaţi̇֜y ʼeţ-há⁠ʼá֧reẕ ha⁠zò֛̇ʼţ lĕ⁠zarĕʻà⁠ká֥ ʼaẖàre֖y⁠ká ʼàẖuzȧ֥ţ ʻwòláֽm׃"],[48,5,"וְ⁠עַתָּ֡ה שְׁנֵֽי־בָנֶי⁠ךָ֩ הַ⁠נּוֹלָדִ֨ים לְ⁠ךָ֜ בְּ⁠אֶ֣רֶץ מִצְרַ֗יִם עַד־בֹּאִ֥⁠י אֵלֶ֛י⁠ךָ מִצְרַ֖יְמָ⁠ה לִ⁠י־הֵ֑ם אֶפְרַ֨יִם֙ וּ⁠מְנַשֶּׁ֔ה כִּ⁠רְאוּבֵ֥ן וְ⁠שִׁמְע֖וֹן יִֽהְיוּ־לִֽ⁠י׃","wĕ⁠ʻaţá̇֡h şĕ̌néֽy-báney⁠ká֩ ha⁠ṅwòládi֨ym lĕ⁠ká֜ bĕ̇⁠ʼe֣reẕ miẕĕra֗yim ʻad-bò̇ʼi֥⁠y ʼéle֛y⁠ká miẕĕra֖yĕmá⁠h li⁠y-hé֑m ʼepĕra֨yim֙ ẇ⁠mĕnaşė̌֔h ki̇⁠rĕʼẇbé֥n wĕ⁠şǐmĕʻ֖wòn yiֽhĕyẇ-liֽ⁠y׃"],[48,6,"וּ⁠מוֹלַדְתְּ⁠ךָ֛ אֲשֶׁר־הוֹלַ֥דְתָּ אַחֲרֵי⁠הֶ֖ם לְ⁠ךָ֣ יִהְי֑וּ עַ֣ל שֵׁ֧ם אֲחֵי⁠הֶ֛ם יִקָּרְא֖וּ בְּ⁠נַחֲלָתָֽ⁠ם׃","ẇ⁠mwòladĕţĕ̇⁠ká֛ ʼàşěr-hwòla֥dĕţá̇ ʼaẖàréy⁠he֖m lĕ⁠ká֣ yihĕy֑ẇ ʻa֣l şé֧̌m ʼàẖéy⁠he֛m yiqá̇rĕʼ֖ẇ bĕ̇⁠naẖàláţáֽ⁠m׃"],[48,7,"וַ⁠אֲנִ֣י ׀ בְּ⁠בֹאִ֣⁠י מִ⁠פַּדָּ֗ן מֵ֩תָה֩ עָלַ֨⁠י רָחֵ֜ל בְּ⁠אֶ֤רֶץ כְּנַ֨עַן֙ בַּ⁠דֶּ֔רֶךְ בְּ⁠ע֥וֹד כִּבְרַת־אֶ֖רֶץ לָ⁠בֹ֣א אֶפְרָ֑תָה וָ⁠אֶקְבְּרֶ֤⁠הָ שָּׁם֙ בְּ⁠דֶ֣רֶךְ אֶפְרָ֔ת הִ֖וא בֵּ֥ית לָֽחֶם׃","wa⁠ʼàni֣y ׀ bĕ̇⁠bòʼi֣⁠y mi⁠pȧdá̇֗n mé֩ţáh֩ ʻála֨⁠y ráẖé֜l bĕ̇⁠ʼe֤reẕ kĕ̇na֨ʻan֙ bȧ⁠dė֔rekĕ bĕ̇⁠ʻ֥wòd ki̇bĕraţ-ʼe֖reẕ lá⁠bò֣ʼ ʼepĕrá֑ţáh wá⁠ʼeqĕbĕ̇re֤⁠há şá̇̌m֙ bĕ̇⁠de֣rekĕ ʼepĕrá֔ţ hi֖wʼ bé֥̇yţ láֽẖem׃"],[48,8,"וַ⁠יַּ֥רְא יִשְׂרָאֵ֖ל אֶת־בְּנֵ֣י יוֹסֵ֑ף וַ⁠יֹּ֖אמֶר מִי־אֵֽלֶּה׃","wa⁠yȧ֥rĕʼ yişĕ̂ráʼé֖l ʼeţ-bĕ̇né֣y ywòsé֑p wa⁠yò֖̇ʼmer miy-ʼéֽlėh׃"],[48,9,"וַ⁠יֹּ֤אמֶר יוֹסֵף֙ אֶל־אָבִ֔י⁠ו בָּנַ֣⁠י הֵ֔ם אֲשֶׁר־נָֽתַן־לִ֥⁠י אֱלֹהִ֖ים בָּ⁠זֶ֑ה וַ⁠יֹּאמַ֕ר קָֽחֶ⁠ם־נָ֥א אֵלַ֖⁠י וַ⁠אֲבָרֲכֵֽ⁠ם׃","wa⁠yò֤̇ʼmer ywòsép֙ ʼel-ʼábi֔y⁠w bá̇na֣⁠y hé֔m ʼàşěr-náֽţan-li֥⁠y ʼèlòhi֖ym bá̇⁠ze֑h wa⁠yò̇ʼma֕r qáֽẖe⁠m-ná֥ʼ ʼéla֖⁠y wa⁠ʼàbáràkéֽ⁠m׃"],[48,10,"וְ⁠עֵינֵ֤י יִשְׂרָאֵל֙ כָּבְד֣וּ מִ⁠זֹּ֔קֶן לֹ֥א יוּכַ֖ל לִ⁠רְא֑וֹת וַ⁠יַּגֵּ֤שׁ אֹתָ⁠ם֙ אֵלָ֔י⁠ו וַ⁠יִּשַּׁ֥ק לָ⁠הֶ֖ם וַ⁠יְחַבֵּ֥ק לָ⁠הֶֽם׃","wĕ⁠ʻéyné֤y yişĕ̂ráʼél֙ ká̇bĕd֣ẇ mi⁠zò̇֔qen lò֥ʼ yẇka֖l li⁠rĕʼ֑wòţ wa⁠yȧgé֤̇ş̌ ʼòţá⁠m֙ ʼélá֔y⁠w wa⁠yi̇şȧ֥̌q lá⁠he֖m wa⁠yĕẖabé֥̇q lá⁠heֽm׃"],[48,11,"וַ⁠יֹּ֤אמֶר יִשְׂרָאֵל֙ אֶל־יוֹסֵ֔ף רְאֹ֥ה פָנֶ֖י⁠ךָ לֹ֣א פִלָּ֑לְתִּי וְ⁠הִנֵּ֨ה הֶרְאָ֥ה אֹתִ֛⁠י אֱלֹהִ֖ים גַּ֥ם אֶת־זַרְעֶֽ⁠ךָ׃","wa⁠yò֤̇ʼmer yişĕ̂ráʼél֙ ʼel-ywòsé֔p rĕʼò֥h páne֖y⁠ká lò֣ʼ pilá֑̇lĕţi̇y wĕ⁠hiné̇֨h herĕʼá֥h ʼòţi֛⁠y ʼèlòhi֖ym gȧ֥m ʼeţ-zarĕʻeֽ⁠ká׃"],[48,12,"וַ⁠יּוֹצֵ֥א יוֹסֵ֛ף אֹתָ֖⁠ם מֵ⁠עִ֣ם בִּרְכָּ֑י⁠ו וַ⁠יִּשְׁתַּ֥חוּ לְ⁠אַפָּ֖י⁠ו אָֽרְצָ⁠ה׃","wa⁠ẏwòẕé֥ʼ ywòsé֛p ʼòţá֖⁠m mé⁠ʻi֣m bi̇rĕká֑̇y⁠w wa⁠yi̇şĕ̌ţȧ֥ẖẇ lĕ⁠ʼapá֖̇y⁠w ʼáֽrĕẕá⁠h׃"],[48,13,"וַ⁠יִּקַּ֣ח יוֹסֵף֮ אֶת־שְׁנֵי⁠הֶם֒ אֶת־אֶפְרַ֤יִם בִּֽ⁠ימִינ⁠וֹ֙ מִ⁠שְּׂמֹ֣אל יִשְׂרָאֵ֔ל וְ⁠אֶת־מְנַשֶּׁ֥ה בִ⁠שְׂמֹאל֖⁠וֹ מִ⁠ימִ֣ין יִשְׂרָאֵ֑ל וַ⁠יַּגֵּ֖שׁ אֵלָֽי⁠ו׃","wa⁠yi̇qȧ֣ẖ ywòsép֮ ʼeţ-şĕ̌néy⁠hem֒ ʼeţ-ʼepĕra֤yim biֽ̇⁠ymiyn⁠wò֙ mi⁠şĕ̇̂mò֣ʼl yişĕ̂ráʼé֔l wĕ⁠ʼeţ-mĕnaşė֥̌h bi⁠şĕ̂mòʼl֖⁠wò mi⁠ymi֣yn yişĕ̂ráʼé֑l wa⁠yȧgé֖̇ş̌ ʼéláֽy⁠w׃"],[48,14,"וַ⁠יִּשְׁלַח֩ יִשְׂרָאֵ֨ל אֶת־יְמִינ֜⁠וֹ וַ⁠יָּ֨שֶׁת עַל־רֹ֤אשׁ אֶפְרַ֨יִם֙ וְ⁠ה֣וּא הַ⁠צָּעִ֔יר וְ⁠אֶת־שְׂמֹאל֖⁠וֹ עַל־רֹ֣אשׁ מְנַשֶּׁ֑ה שִׂכֵּל֙ אֶת־יָדָ֔י⁠ו כִּ֥י מְנַשֶּׁ֖ה הַ⁠בְּכֽוֹר׃","wa⁠yi̇şĕ̌laẖ֩ yişĕ̂ráʼé֨l ʼeţ-yĕmiyn֜⁠wò wa⁠yá̇֨şěţ ʻal-rò֤ʼş̌ ʼepĕra֨yim֙ wĕ⁠h֣ẇʼ ha⁠ẕá̇ʻi֔yr wĕ⁠ʼeţ-şĕ̂mòʼl֖⁠wò ʻal-rò֣ʼş̌ mĕnaşė֑̌h şîké̇l֙ ʼeţ-yádá֔y⁠w ki֥̇y mĕnaşė֖̌h ha⁠bĕ̇kֽwòr׃"],[48,15,"וַ⁠יְבָ֥רֶךְ אֶת־יוֹסֵ֖ף וַ⁠יֹּאמַ֑ר הָֽ⁠אֱלֹהִ֡ים אֲשֶׁר֩ הִתְהַלְּכ֨וּ אֲבֹתַ֤⁠י לְ⁠פָנָי⁠ו֙ אַבְרָהָ֣ם וְ⁠יִצְחָ֔ק הָֽ⁠אֱלֹהִים֙ הָ⁠רֹעֶ֣ה אֹתִ֔⁠י מֵ⁠עוֹדִ֖⁠י עַד־הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wa⁠yĕbá֥rekĕ ʼeţ-ywòsé֖p wa⁠yò̇ʼma֑r háֽ⁠ʼèlòhi֡ym ʼàşěr֩ hiţĕhalĕ̇k֨ẇ ʼàbòţa֤⁠y lĕ⁠pánáy⁠w֙ ʼabĕráhá֣m wĕ⁠yiẕĕẖá֔q háֽ⁠ʼèlòhiym֙ há⁠ròʻe֣h ʼòţi֔⁠y mé⁠ʻwòdi֖⁠y ʻad-ha⁠ẏ֥wòm ha⁠zėֽh׃"],[48,16,"הַ⁠מַּלְאָךְ֩ הַ⁠גֹּאֵ֨ל אֹתִ֜⁠י מִ⁠כָּל־רָ֗ע יְבָרֵךְ֮ אֶת־הַ⁠נְּעָרִים֒ וְ⁠יִקָּרֵ֤א בָ⁠הֶם֙ שְׁמִ֔⁠י וְ⁠שֵׁ֥ם אֲבֹתַ֖⁠י אַבְרָהָ֣ם וְ⁠יִצְחָ֑ק וְ⁠יִדְגּ֥וּ לָ⁠רֹ֖ב בְּ⁠קֶ֥רֶב הָ⁠אָֽרֶץ׃","ha⁠mȧlĕʼákĕ֩ ha⁠gò̇ʼé֨l ʼòţi֜⁠y mi⁠ká̇l-rá֗ʻ yĕbárékĕ֮ ʼeţ-ha⁠nĕ̇ʻáriym֒ wĕ⁠yiqá̇ré֤ʼ bá⁠hem֙ şĕ̌mi֔⁠y wĕ⁠şé֥̌m ʼàbòţa֖⁠y ʼabĕráhá֣m wĕ⁠yiẕĕẖá֑q wĕ⁠yidĕġ֥ẇ lá⁠rò֖b bĕ̇⁠qe֥reb há⁠ʼáֽreẕ׃"],[48,17,"וַ⁠יַּ֣רְא יוֹסֵ֗ף כִּי־יָשִׁ֨ית אָבִ֧י⁠ו יַד־יְמִינ֛⁠וֹ עַל־רֹ֥אשׁ אֶפְרַ֖יִם וַ⁠יֵּ֣רַע בְּ⁠עֵינָ֑י⁠ו וַ⁠יִּתְמֹ֣ךְ יַד־אָבִ֗י⁠ו לְ⁠הָסִ֥יר אֹתָ֛⁠הּ מֵ⁠עַ֥ל רֹאשׁ־אֶפְרַ֖יִם עַל־רֹ֥אשׁ מְנַשֶּֽׁה׃","wa⁠yȧ֣rĕʼ ywòsé֗p ki̇y-yáşǐ֨yţ ʼábi֧y⁠w yad-yĕmiyn֛⁠wò ʻal-rò֥ʼş̌ ʼepĕra֖yim wa⁠yé֣̇raʻ bĕ̇⁠ʻéyná֑y⁠w wa⁠yi̇ţĕmò֣kĕ yad-ʼábi֗y⁠w lĕ⁠hási֥yr ʼòţá֛⁠ḣ mé⁠ʻa֥l ròʼş̌-ʼepĕra֖yim ʻal-rò֥ʼş̌ mĕnaşėֽ̌h׃"],[48,18,"וַ⁠יֹּ֧אמֶר יוֹסֵ֛ף אֶל־אָבִ֖י⁠ו לֹא־כֵ֣ן אָבִ֑⁠י כִּי־זֶ֣ה הַ⁠בְּכֹ֔ר שִׂ֥ים יְמִינְ⁠ךָ֖ עַל־רֹאשֽׁ⁠וֹ׃","wa⁠yò֧̇ʼmer ywòsé֛p ʼel-ʼábi֖y⁠w lòʼ-ké֣n ʼábi֑⁠y ki̇y-ze֣h ha⁠bĕ̇kò֔r şî֥ym yĕmiynĕ⁠ká֖ ʻal-ròʼşֽ̌⁠wò׃"],[48,19,"וַ⁠יְמָאֵ֣ן אָבִ֗י⁠ו וַ⁠יֹּ֨אמֶר֙ יָדַ֤עְתִּֽי בְנִ⁠י֙ יָדַ֔עְתִּי גַּם־ה֥וּא יִֽהְיֶה־לְּ⁠עָ֖ם וְ⁠גַם־ה֣וּא יִגְדָּ֑ל וְ⁠אוּלָ֗ם אָחִ֤י⁠ו הַ⁠קָּטֹן֙ יִגְדַּ֣ל מִמֶּ֔⁠נּוּ וְ⁠זַרְע֖⁠וֹ יִהְיֶ֥ה מְלֹֽא־הַ⁠גּוֹיִֽם׃","wa⁠yĕmáʼé֣n ʼábi֗y⁠w wa⁠yò̇֨ʼmer֙ yáda֤ʻĕţiֽ̇y bĕni⁠y֙ yáda֔ʻĕţi̇y gȧm-h֥ẇʼ yiֽhĕyeh-lĕ̇⁠ʻá֖m wĕ⁠gam-h֣ẇʼ yigĕdá֑̇l wĕ⁠ʼẇlá֗m ʼáẖi֤y⁠w ha⁠qá̇tòn֙ yigĕdȧ֣l mimė֔⁠ṅẇ wĕ⁠zarĕʻ֖⁠wò yihĕye֥h mĕlòֽʼ-ha⁠ġwòyiֽm׃"],[48,20,"וַ⁠יְבָ֨רֲכֵ֜⁠ם בַּ⁠יּ֣וֹם הַ⁠הוּא֮ לֵ⁠אמוֹר֒ בְּ⁠ךָ֗ יְבָרֵ֤ךְ יִשְׂרָאֵל֙ לֵ⁠אמֹ֔ר יְשִֽׂמְ⁠ךָ֣ אֱלֹהִ֔ים כְּ⁠אֶפְרַ֖יִם וְ⁠כִ⁠מְנַשֶּׁ֑ה וַ⁠יָּ֥שֶׂם אֶת־אֶפְרַ֖יִם לִ⁠פְנֵ֥י מְנַשֶּֽׁה׃","wa⁠yĕbá֨ràké֜⁠m bȧ⁠ẏ֣wòm ha⁠hẇʼ֮ lé⁠ʼmwòr֒ bĕ̇⁠ká֗ yĕbáré֤kĕ yişĕ̂ráʼél֙ lé⁠ʼmò֔r yĕşîֽmĕ⁠ká֣ ʼèlòhi֔ym kĕ̇⁠ʼepĕra֖yim wĕ⁠ki⁠mĕnaşė֑̌h wa⁠yá֥̇şêm ʼeţ-ʼepĕra֖yim li⁠pĕné֥y mĕnaşėֽ̌h׃"],[48,21,"וַ⁠יֹּ֤אמֶר יִשְׂרָאֵל֙ אֶל־יוֹסֵ֔ף הִנֵּ֥ה אָנֹכִ֖י מֵ֑ת וְ⁠הָיָ֤ה אֱלֹהִים֙ עִמָּ⁠כֶ֔ם וְ⁠הֵשִׁ֣יב אֶתְ⁠כֶ֔ם אֶל־אֶ֖רֶץ אֲבֹתֵי⁠כֶֽם׃","wa⁠yò֤̇ʼmer yişĕ̂ráʼél֙ ʼel-ywòsé֔p hiné֥̇h ʼánòki֖y mé֑ţ wĕ⁠háyá֤h ʼèlòhiym֙ ʻimá̇⁠ke֔m wĕ⁠héşǐ֣yb ʼeţĕ⁠ke֔m ʼel-ʼe֖reẕ ʼàbòţéy⁠keֽm׃"],[48,22,"וַ⁠אֲנִ֞י נָתַ֧תִּֽי לְ⁠ךָ֛ שְׁכֶ֥ם אַחַ֖ד עַל־אַחֶ֑י⁠ךָ אֲשֶׁ֤ר לָקַ֨חְתִּי֙ מִ⁠יַּ֣ד הָֽ⁠אֱמֹרִ֔י בְּ⁠חַרְבִּ֖⁠י וּ⁠בְ⁠קַשְׁתִּֽ⁠י׃פ","wa⁠ʼàni֞y náţa֧ţiֽ̇y lĕ⁠ká֛ şĕ̌ke֥m ʼaẖa֖d ʻal-ʼaẖe֑y⁠ká ʼàşě֤r láqa֨ẖĕţi̇y֙ mi⁠yȧ֣d háֽ⁠ʼèmòri֔y bĕ̇⁠ẖarĕbi֖̇⁠y ẇ⁠bĕ⁠qaşĕ̌ţiֽ̇⁠y׃p"],[49,1,"וַ⁠יִּקְרָ֥א יַעֲקֹ֖ב אֶל־בָּנָ֑י⁠ו וַ⁠יֹּ֗אמֶר הֵאָֽסְפוּ֙ וְ⁠אַגִּ֣ידָה לָ⁠כֶ֔ם אֵ֛ת אֲשֶׁר־יִקְרָ֥א אֶתְ⁠כֶ֖ם בְּ⁠אַחֲרִ֥ית הַ⁠יָּמִֽים׃","wa⁠yi̇qĕrá֥ʼ yaʻàqò֖b ʼel-bá̇ná֑y⁠w wa⁠yò̇֗ʼmer héʼáֽsĕpẇ֙ wĕ⁠ʼagi֣̇ydáh lá⁠ke֔m ʼé֛ţ ʼàşěr-yiqĕrá֥ʼ ʼeţĕ⁠ke֖m bĕ̇⁠ʼaẖàri֥yţ ha⁠yá̇miֽym׃"],[49,2,"הִקָּבְצ֥וּ וְ⁠שִׁמְע֖וּ בְּנֵ֣י יַעֲקֹ֑ב וְ⁠שִׁמְע֖וּ אֶל־יִשְׂרָאֵ֥ל אֲבִי⁠כֶֽם׃","hiqá̇bĕẕ֥ẇ wĕ⁠şǐmĕʻ֖ẇ bĕ̇né֣y yaʻàqò֑b wĕ⁠şǐmĕʻ֖ẇ ʼel-yişĕ̂ráʼé֥l ʼàbiy⁠keֽm׃"],[49,3,"רְאוּבֵן֙ בְּכֹ֣רִ⁠י אַ֔תָּה כֹּחִ֖⁠י וְ⁠רֵאשִׁ֣ית אוֹנִ֑⁠י יֶ֥תֶר שְׂאֵ֖ת וְ⁠יֶ֥תֶר עָֽז׃","rĕʼẇbén֙ bĕ̇kò֣ri⁠y ʼa֔ţá̇h kò̇ẖi֖⁠y wĕ⁠réʼşǐ֣yţ ʼwòni֑⁠y ye֥ţer şĕ̂ʼé֖ţ wĕ⁠ye֥ţer ʻáֽz׃"],[49,4,"פַּ֤חַז כַּ⁠מַּ֨יִם֙ אַל־תּוֹתַ֔ר כִּ֥י עָלִ֖יתָ מִשְׁכְּבֵ֣י אָבִ֑י⁠ךָ אָ֥ז חִלַּ֖לְתָּ יְצוּעִ֥⁠י עָלָֽה׃פ","pȧ֤ẖaz kȧ⁠mȧ֨yim֙ ʼal-ţ̇wòţa֔r ki֥̇y ʻáli֖yţá mişĕ̌kĕ̇bé֣y ʼábi֑y⁠ká ʼá֥z ẖilȧ֖lĕţá̇ yĕẕẇʻi֥⁠y ʻáláֽh׃p"],[49,5,"שִׁמְע֥וֹן וְ⁠לֵוִ֖י אַחִ֑ים כְּלֵ֥י חָמָ֖ס מְכֵרֹתֵי⁠הֶֽם׃","şǐmĕʻ֥wòn wĕ⁠léwi֖y ʼaẖi֑ym kĕ̇lé֥y ẖámá֖s mĕkéròţéy⁠heֽm׃"],[49,6,"בְּ⁠סֹדָ⁠ם֙ אַל־תָּבֹ֣א נַפְשִׁ֔⁠י בִּ⁠קְהָלָ֖⁠ם אַל־תֵּחַ֣ד כְּבֹדִ֑⁠י כִּ֤י בְ⁠אַפָּ⁠ם֙ הָ֣רְגוּ אִ֔ישׁ וּ⁠בִ⁠רְצֹנָ֖⁠ם עִקְּרוּ־שֽׁוֹר׃","bĕ̇⁠sòdá⁠m֙ ʼal-ţá̇bò֣ʼ napĕşǐ֔⁠y bi̇⁠qĕhálá֖⁠m ʼal-ţé̇ẖa֣d kĕ̇bòdi֑⁠y ki֤̇y bĕ⁠ʼapá̇⁠m֙ há֣rĕgẇ ʼi֔yş̌ ẇ⁠bi⁠rĕẕòná֖⁠m ʻiqĕ̇rẇ-şֽ̌wòr׃"],[49,7,"אָר֤וּר אַפָּ⁠ם֙ כִּ֣י עָ֔ז וְ⁠עֶבְרָתָ֖⁠ם כִּ֣י קָשָׁ֑תָה אֲחַלְּקֵ֣⁠ם בְּ⁠יַעֲקֹ֔ב וַ⁠אֲפִיצֵ֖⁠ם בְּ⁠יִשְׂרָאֵֽל׃ס","ʼár֤ẇr ʼapá̇⁠m֙ ki֣̇y ʻá֔z wĕ⁠ʻebĕráţá֖⁠m ki֣̇y qáşá֑̌ţáh ʼàẖalĕ̇qé֣⁠m bĕ̇⁠yaʻàqò֔b wa⁠ʼàpiyẕé֖⁠m bĕ̇⁠yişĕ̂ráʼéֽl׃s"],[49,8,"יְהוּדָ֗ה אַתָּה֙ יוֹד֣וּ⁠ךָ אַחֶ֔י⁠ךָ יָדְ⁠ךָ֖ בְּ⁠עֹ֣רֶף אֹיְבֶ֑י⁠ךָ יִשְׁתַּחֲוּ֥וּ לְ⁠ךָ֖ בְּנֵ֥י אָבִֽי⁠ךָ׃","yĕhẇdá֗h ʼaţá̇h֙ ywòd֣ẇ⁠ká ʼaẖe֔y⁠ká yádĕ⁠ká֖ bĕ̇⁠ʻò֣rep ʼòyĕbe֑y⁠ká yişĕ̌ţȧẖàẇ֥ẇ lĕ⁠ká֖ bĕ̇né֥y ʼábiֽy⁠ká׃"],[49,9,"גּ֤וּר אַרְיֵה֙ יְהוּדָ֔ה מִ⁠טֶּ֖רֶף בְּנִ֣⁠י עָלִ֑יתָ כָּרַ֨ע רָבַ֧ץ כְּ⁠אַרְיֵ֛ה וּ⁠כְ⁠לָבִ֖יא מִ֥י יְקִימֶֽ⁠נּוּ׃","ġ֤ẇr ʼarĕyéh֙ yĕhẇdá֔h mi⁠tė֖rep bĕ̇ni֣⁠y ʻáli֑yţá ká̇ra֨ʻ rába֧ẕ kĕ̇⁠ʼarĕyé֛h ẇ⁠kĕ⁠lábi֖yʼ mi֥y yĕqiymeֽ⁠ṅẇ׃"],[49,10,"לֹֽא־יָס֥וּר שֵׁ֨בֶט֙ מִֽ⁠יהוּדָ֔ה וּ⁠מְחֹקֵ֖ק מִ⁠בֵּ֣ין רַגְלָ֑י⁠ו עַ֚ד כִּֽי־יָבֹ֣א שילה וְ⁠ל֖⁠וֹ יִקְּהַ֥ת עַמִּֽים׃","lòֽʼ-yás֥ẇr şé̌֨bet֙ miֽ⁠yhẇdá֔h ẇ⁠mĕẖòqé֖q mi⁠bé֣̇yn ragĕlá֑y⁠w ʻa֚d kiֽ̇y-yábò֣ʼ şylh wĕ⁠l֖⁠wò yiqĕ̇ha֥ţ ʻamiֽ̇ym׃"],[49,11,"אֹסְרִ֤י לַ⁠גֶּ֨פֶן֙ עיר⁠ה וְ⁠לַ⁠שֹּׂרֵקָ֖ה בְּנִ֣י אֲתֹנ֑⁠וֹ כִּבֵּ֤ס בַּ⁠יַּ֨יִן֙ לְבֻשׁ֔⁠וֹ וּ⁠בְ⁠דַם־עֲנָבִ֖ים סות⁠ה׃","ʼòsĕri֤y la⁠gė֨pen֙ ʻyr⁠h wĕ⁠la⁠şò̇̂réqá֖h bĕ̇ni֣y ʼàţòn֑⁠wò ki̇bé֤̇s bȧ⁠yȧ֨yin֙ lĕbuş̌֔⁠wò ẇ⁠bĕ⁠dam-ʻànábi֖ym swţ⁠h׃"],[49,12,"חַכְלִילִ֥י עֵינַ֖יִם מִ⁠יָּ֑יִן וּ⁠לְבֶן־שִׁנַּ֖יִם מֵ⁠חָלָֽב׃פ","ẖakĕliyli֥y ʻéyna֖yim mi⁠yá֑̇yin ẇ⁠lĕben-şǐnȧ֖yim mé⁠ẖáláֽb׃p"],[49,13,"זְבוּלֻ֕ן לְ⁠ח֥וֹף יַמִּ֖ים יִשְׁכֹּ֑ן וְ⁠הוּא֙ לְ⁠ח֣וֹף אֳנִיּ֔וֹת וְ⁠יַרְכָת֖⁠וֹ עַל־צִידֹֽן׃ס","zĕbẇlu֕n lĕ⁠ẖ֥wòp yami֖̇ym yişĕ̌kò֑̇n wĕ⁠hẇʼ֙ lĕ⁠ẖ֣wòp ʼoniẏ֔wòţ wĕ⁠yarĕkáţ֖⁠wò ʻal-ẕiydòֽn׃s"],[49,14,"יִשָּׂשכָ֖ר חֲמֹ֣ר גָּ֑רֶם רֹבֵ֖ץ בֵּ֥ין הַֽ⁠מִּשְׁפְּתָֽיִם׃","yişá̇̂şká֖r ẖàmò֣r gá֑̇rem ròbé֖ẕ bé֥̇yn haֽ⁠mi̇şĕ̌pĕ̇ţáֽyim׃"],[49,15,"וַ⁠יַּ֤רְא מְנֻחָה֙ כִּ֣י ט֔וֹב וְ⁠אֶת־הָ⁠אָ֖רֶץ כִּ֣י נָעֵ֑מָה וַ⁠יֵּ֤ט שִׁכְמ⁠וֹ֙ לִ⁠סְבֹּ֔ל וַ⁠יְהִ֖י לְ⁠מַס־עֹבֵֽד׃ס","wa⁠yȧ֤rĕʼ mĕnuẖáh֙ ki֣̇y t֔wòb wĕ⁠ʼeţ-há⁠ʼá֖reẕ ki֣̇y náʻé֑máh wa⁠yé֤̇t şǐkĕm⁠wò֙ li⁠sĕbò̇֔l wa⁠yĕhi֖y lĕ⁠mas-ʻòbéֽd׃s"],[49,16,"דָּ֖ן יָדִ֣ין עַמּ֑⁠וֹ כְּ⁠אַחַ֖ד שִׁבְטֵ֥י יִשְׂרָאֵֽל׃","dá֖̇n yádi֣yn ʻaṁ֑⁠wò kĕ̇⁠ʼaẖa֖d şǐbĕté֥y yişĕ̂ráʼéֽl׃"],[49,17,"יְהִי־דָן֙ נָחָ֣שׁ עֲלֵי־דֶ֔רֶךְ שְׁפִיפֹ֖ן עֲלֵי־אֹ֑רַח הַ⁠נֹּשֵׁךְ֙ עִקְּבֵי־ס֔וּס וַ⁠יִּפֹּ֥ל רֹכְב֖⁠וֹ אָחֽוֹר׃","yĕhiy-dán֙ náẖá֣ş̌ ʻàléy-de֔rekĕ şĕ̌piypò֖n ʻàléy-ʼò֑raẖ ha⁠nò̇şé̌kĕ֙ ʻiqĕ̇béy-s֔ẇs wa⁠yi̇pò֥̇l ròkĕb֖⁠wò ʼáẖֽwòr׃"],[49,18,"לִֽ⁠ישׁוּעָתְ⁠ךָ֖ קִוִּ֥יתִי יְהוָֽה׃","liֽ⁠yş̌ẇʻáţĕ⁠ká֖ qiwi֥̇yţiy yĕhwáֽh׃"],[49,19,"גָּ֖ד גְּד֣וּד יְגוּדֶ֑⁠נּוּ וְ⁠ה֖וּא יָגֻ֥ד עָקֵֽב׃ס","gá֖̇d gĕ̇d֣ẇd yĕgẇde֑⁠ṅẇ wĕ⁠h֖ẇʼ yágu֥d ʻáqéֽb׃s"],[49,20,"מֵ⁠אָשֵׁ֖ר שְׁמֵנָ֣ה לַחְמ֑⁠וֹ וְ⁠ה֥וּא יִתֵּ֖ן מַֽעֲדַנֵּי־מֶֽלֶךְ׃ס","mé⁠ʼáşé֖̌r şĕ̌méná֣h laẖĕm֑⁠wò wĕ⁠h֥ẇʼ yiţé֖̇n maֽʻàdané̇y-meֽlekĕ׃s"],[49,21,"נַפְתָּלִ֖י אַיָּלָ֣ה שְׁלֻחָ֑ה הַ⁠נֹּתֵ֖ן אִמְרֵי־שָֽׁפֶר׃ס","napĕţá̇li֖y ʼayá̇lá֣h şĕ̌luẖá֑h ha⁠nò̇ţé֖n ʼimĕréy-şáֽ̌per׃s"],[49,22,"בֵּ֤ן פֹּרָת֙ יוֹסֵ֔ף בֵּ֥ן פֹּרָ֖ת עֲלֵי־עָ֑יִן בָּנ֕וֹת צָעֲדָ֖ה עֲלֵי־שֽׁוּר׃","bé֤̇n pò̇ráţ֙ ywòsé֔p bé֥̇n pò̇rá֖ţ ʻàléy-ʻá֑yin bá̇n֕wòţ ẕáʻàdá֖h ʻàléy-şֽ̌ẇr׃"],[49,23,"וַֽ⁠יְמָרֲרֻ֖⁠הוּ וָ⁠רֹ֑בּוּ וַֽ⁠יִּשְׂטְמֻ֖⁠הוּ בַּעֲלֵ֥י חִצִּֽים׃","waֽ⁠yĕmáràru֖⁠hẇ wá⁠rò֑ḃẇ waֽ⁠yi̇şĕ̂tĕmu֖⁠hẇ bȧʻàlé֥y ẖiẕiֽ̇ym׃"],[49,24,"וַ⁠תֵּ֤שֶׁב בְּ⁠אֵיתָן֙ קַשְׁתּ֔⁠וֹ וַ⁠יָּפֹ֖זּוּ זְרֹעֵ֣י יָדָ֑י⁠ו מִ⁠ידֵי֙ אֲבִ֣יר יַעֲקֹ֔ב מִ⁠שָּׁ֥ם רֹעֶ֖ה אֶ֥בֶן יִשְׂרָאֵֽל׃","wa⁠ţé֤̇şěb bĕ̇⁠ʼéyţán֙ qaşĕ̌ţ̇֔⁠wò wa⁠yá̇pò֖żẇ zĕròʻé֣y yádá֑y⁠w mi⁠ydéy֙ ʼàbi֣yr yaʻàqò֔b mi⁠şá֥̇̌m ròʻe֖h ʼe֥ben yişĕ̂ráʼéֽl׃"],[49,25,"מֵ⁠אֵ֨ל אָבִ֜י⁠ךָ וְ⁠יַעְזְרֶ֗⁠ךָּ וְ⁠אֵ֤ת שַׁדַּי֙ וִ⁠יבָ֣רְכֶ֔⁠ךָּ בִּרְכֹ֤ת שָׁמַ֨יִם֙ מֵ⁠עָ֔ל בִּרְכֹ֥ת תְּה֖וֹם רֹבֶ֣צֶת תָּ֑חַת בִּרְכֹ֥ת שָׁדַ֖יִם וָ⁠רָֽחַם׃","mé⁠ʼé֨l ʼábi֜y⁠ká wĕ⁠yaʻĕzĕre֗⁠ká̇ wĕ⁠ʼé֤ţ şǎdȧy֙ wi⁠ybá֣rĕke֔⁠ká̇ bi̇rĕkò֤ţ şá̌ma֨yim֙ mé⁠ʻá֔l bi̇rĕkò֥ţ ţĕ̇h֖wòm ròbe֣ẕeţ ţá֑̇ẖaţ bi̇rĕkò֥ţ şá̌da֖yim wá⁠ráֽẖam׃"],[49,26,"בִּרְכֹ֣ת אָבִ֗י⁠ךָ גָּֽבְרוּ֙ עַל־בִּרְכֹ֣ת הוֹרַ֔⁠י עַֽד־תַּאֲוַ֖ת גִּבְעֹ֣ת עוֹלָ֑ם תִּֽהְיֶ֨ין֙ לְ⁠רֹ֣אשׁ יוֹסֵ֔ף וּ⁠לְ⁠קָדְקֹ֖ד נְזִ֥יר אֶחָֽי⁠ו׃פ","bi̇rĕkò֣ţ ʼábi֗y⁠ká gáֽ̇bĕrẇ֙ ʻal-bi̇rĕkò֣ţ hwòra֔⁠y ʻaֽd-ţȧʼàwa֖ţ gi̇bĕʻò֣ţ ʻwòlá֑m ţiֽ̇hĕye֨yn֙ lĕ⁠rò֣ʼş̌ ywòsé֔p ẇ⁠lĕ⁠qádĕqò֖d nĕzi֥yr ʼeẖáֽy⁠w׃p"],[49,27,"בִּנְיָמִין֙ זְאֵ֣ב יִטְרָ֔ף בַּ⁠בֹּ֖קֶר יֹ֣אכַל עַ֑ד וְ⁠לָ⁠עֶ֖רֶב יְחַלֵּ֥ק שָׁלָֽל׃","bi̇nĕyámiyn֙ zĕʼé֣b yitĕrá֔p bȧ⁠bò֖̇qer yò֣ʼkal ʻa֑d wĕ⁠lá⁠ʻe֖reb yĕẖalé֥̇q şá̌láֽl׃"],[49,28,"כָּל־אֵ֛לֶּה שִׁבְטֵ֥י יִשְׂרָאֵ֖ל שְׁנֵ֣ים עָשָׂ֑ר וְ֠⁠זֹאת אֲשֶׁר־דִּבֶּ֨ר לָ⁠הֶ֤ם אֲבִי⁠הֶם֙ וַ⁠יְבָ֣רֶךְ אוֹתָ֔⁠ם אִ֛ישׁ אֲשֶׁ֥ר כְּ⁠בִרְכָת֖⁠וֹ בֵּרַ֥ךְ אֹתָֽ⁠ם׃","ká̇l-ʼé֛lėh şǐbĕté֥y yişĕ̂ráʼé֖l şĕ̌né֣ym ʻáşá֑̂r wĕ֠⁠zòʼţ ʼàşěr-di̇bė֨r lá⁠he֤m ʼàbiy⁠hem֙ wa⁠yĕbá֣rekĕ ʼwòţá֔⁠m ʼi֛yş̌ ʼàşě֥r kĕ̇⁠birĕkáţ֖⁠wò bé̇ra֥kĕ ʼòţáֽ⁠m׃"],[49,29,"וַ⁠יְצַ֣ו אוֹתָ֗⁠ם וַ⁠יֹּ֤אמֶר אֲלֵ⁠הֶם֙ אֲנִי֙ נֶאֱסָ֣ף אֶל־עַמִּ֔⁠י קִבְר֥וּ אֹתִ֖⁠י אֶל־אֲבֹתָ֑⁠י אֶל־הַ֨⁠מְּעָרָ֔ה אֲשֶׁ֥ר בִּ⁠שְׂדֵ֖ה עֶפְר֥וֹן הַֽ⁠חִתִּֽי׃","wa⁠yĕẕa֣w ʼwòţá֗⁠m wa⁠yò֤̇ʼmer ʼàlé⁠hem֙ ʼàniy֙ neʼèsá֣p ʼel-ʻami̇֔⁠y qibĕr֥ẇ ʼòţi֖⁠y ʼel-ʼàbòţá֑⁠y ʼel-ha֨⁠mĕ̇ʻárá֔h ʼàşě֥r bi̇⁠şĕ̂dé֖h ʻepĕr֥wòn hֽa⁠ẖiţiֽ̇y׃"],[49,30,"בַּ⁠מְּעָרָ֞ה אֲשֶׁ֨ר בִּ⁠שְׂדֵ֧ה הַ⁠מַּכְפֵּלָ֛ה אֲשֶׁ֥ר עַל־פְּנֵי־מַמְרֵ֖א בְּ⁠אֶ֣רֶץ כְּנָ֑עַן אֲשֶׁר֩ קָנָ֨ה אַבְרָהָ֜ם אֶת־הַ⁠שָּׂדֶ֗ה מֵ⁠אֵ֛ת עֶפְרֹ֥ן הַ⁠חִתִּ֖י לַ⁠אֲחֻזַּת־קָֽבֶר׃","bȧ⁠mĕ̇ʻárá֞h ʼàşě֨r bi̇⁠şĕ̂dé֧h ha⁠mȧkĕpé̇lá֛h ʼàşě֥r ʻal-pĕ̇néy-mamĕré֖ʼ bĕ̇⁠ʼe֣reẕ kĕ̇ná֑ʻan ʼàşěr֩ qáná֨h ʼabĕráhá֜m ʼeţ-ha⁠şá̇̂de֗h mé⁠ʼé֛ţ ʻepĕrò֥n ha⁠ẖiţi֖̇y la⁠ʼàẖuzȧţ-qáֽber׃"],[49,31,"שָׁ֣מָּ⁠ה קָֽבְר֞וּ אֶת־אַבְרָהָ֗ם וְ⁠אֵת֙ שָׂרָ֣ה אִשְׁתּ֔⁠וֹ שָׁ֚מָּ⁠ה קָבְר֣וּ אֶת־יִצְחָ֔ק וְ⁠אֵ֖ת רִבְקָ֣ה אִשְׁתּ֑⁠וֹ וְ⁠שָׁ֥מָּ⁠ה קָבַ֖רְתִּי אֶת־לֵאָֽה׃","şá֣̌má̇⁠h qֽábĕr֞ẇ ʼeţ-ʼabĕráhá֗m wĕ⁠ʼéţ֙ şá̂rá֣h ʼişĕ̌ţ̇֔⁠wò şá֚̌má̇⁠h qábĕr֣ẇ ʼeţ-yiẕĕẖá֔q wĕ⁠ʼé֖ţ ribĕqá֣h ʼişĕ̌ţ֑̇⁠wò wĕ⁠şá֥̌má̇⁠h qába֖rĕţi̇y ʼeţ-léʼáֽh׃"],[49,32,"מִקְנֵ֧ה הַ⁠שָּׂדֶ֛ה וְ⁠הַ⁠מְּעָרָ֥ה אֲשֶׁר־בּ֖⁠וֹ מֵ⁠אֵ֥ת בְּנֵי־חֵֽת׃","miqĕné֧h ha⁠şá̇̂de֛h wĕ⁠ha⁠mĕ̇ʻárá֥h ʼàşěr-ḃ֖⁠wò mé⁠ʼé֥ţ bĕ̇néy-ẖéֽţ׃"],[49,33,"וַ⁠יְכַ֤ל יַעֲקֹב֙ לְ⁠צַוֺּ֣ת אֶת־בָּנָ֔י⁠ו וַ⁠יֶּאֱסֹ֥ף רַגְלָ֖י⁠ו אֶל־הַ⁠מִּטָּ֑ה וַ⁠יִּגְוַ֖ע וַ⁠יֵּאָ֥סֶף אֶל־עַמָּֽי⁠ו׃","wa⁠yĕka֤l yaʻàqòb֙ lĕ⁠ẕaẇֺ֣ţ ʼeţ-bá̇ná֔y⁠w wa⁠yėʼèsò֥p ragĕlá֖y⁠w ʼel-ha⁠mi̇tá֑̇h wa⁠yi̇gĕwa֖ʻ wa⁠yé̇ʼá֥sep ʼel-ʻamáֽ̇y⁠w׃"],[50,1,"וַ⁠יִּפֹּ֥ל יוֹסֵ֖ף עַל־פְּנֵ֣י אָבִ֑י⁠ו וַ⁠יֵּ֥בְךְּ עָלָ֖י⁠ו וַ⁠יִּשַּׁק־לֽ⁠וֹ׃","wa⁠yi̇pò֥̇l ywòsé֖p ʻal-pĕ̇né֣y ʼábi֑y⁠w wa⁠yé֥̇bĕkĕ̇ ʻálá֖y⁠w wa⁠yi̇şȧ̌q-lֽ⁠wò׃"],[50,2,"וַ⁠יְצַ֨ו יוֹסֵ֤ף אֶת־עֲבָדָי⁠ו֙ אֶת־הָ⁠רֹ֣פְאִ֔ים לַ⁠חֲנֹ֖ט אֶת־אָבִ֑י⁠ו וַ⁠יַּחַנְט֥וּ הָ⁠רֹפְאִ֖ים אֶת־יִשְׂרָאֵֽל׃","wa⁠yĕẕa֨w ywòsé֤p ʼeţ-ʻàbádáy⁠w֙ ʼeţ-há⁠rò֣pĕʼi֔ym la⁠ẖànò֖t ʼeţ-ʼábi֑y⁠w wa⁠yȧẖanĕt֥ẇ há⁠ròpĕʼi֖ym ʼeţ-yişĕ̂ráʼéֽl׃"],[50,3,"וַ⁠יִּמְלְאוּ־ל⁠וֹ֙ אַרְבָּעִ֣ים י֔וֹם כִּ֛י כֵּ֥ן יִמְלְא֖וּ יְמֵ֣י הַ⁠חֲנֻטִ֑ים וַ⁠יִּבְכּ֥וּ אֹת֛⁠וֹ מִצְרַ֖יִם שִׁבְעִ֥ים יֽוֹם׃","wa⁠yi̇mĕlĕʼẇ-l⁠wò֙ ʼarĕbá̇ʻi֣ym y֔wòm ki֛̇y ké֥̇n yimĕlĕʼ֖ẇ yĕmé֣y ha⁠ẖànuti֑ym wa⁠yi̇bĕk֥̇ẇ ʼòţ֛⁠wò miẕĕra֖yim şǐbĕʻi֥ym yֽwòm׃"],[50,4,"וַ⁠יַּֽעַבְרוּ֙ יְמֵ֣י בְכִית֔⁠וֹ וַ⁠יְדַבֵּ֣ר יוֹסֵ֔ף אֶל־בֵּ֥ית פַּרְעֹ֖ה לֵ⁠אמֹ֑ר אִם־נָ֨א מָצָ֤אתִי חֵן֙ בְּ⁠עֵ֣ינֵי⁠כֶ֔ם דַּבְּרוּ־נָ֕א בְּ⁠אָזְנֵ֥י פַרְעֹ֖ה לֵ⁠אמֹֽר׃","wa⁠yȧֽʻabĕrẇ֙ yĕmé֣y bĕkiyţ֔⁠wò wa⁠yĕdabé֣̇r ywòsé֔p ʼel-bé֥̇yţ pȧrĕʻò֖h lé⁠ʼmò֑r ʼim-ná֨ʼ máẕá֤ʼţiy ẖén֙ bĕ̇⁠ʻé֣ynéy⁠ke֔m dȧbĕ̇rẇ-ná֕ʼ bĕ̇⁠ʼázĕné֥y parĕʻò֖h lé⁠ʼmòֽr׃"],[50,5,"אָבִ֞⁠י הִשְׁבִּיעַ֣⁠נִי לֵ⁠אמֹ֗ר הִנֵּ֣ה אָנֹכִי֮ מֵת֒ בְּ⁠קִבְרִ֗⁠י אֲשֶׁ֨ר כָּרִ֤יתִי לִ⁠י֙ בְּ⁠אֶ֣רֶץ כְּנַ֔עַן שָׁ֖מָּ⁠ה תִּקְבְּרֵ֑⁠נִי וְ⁠עַתָּ֗ה אֶֽעֱלֶה־נָּ֛א וְ⁠אֶקְבְּרָ֥ה אֶת־אָבִ֖⁠י וְ⁠אָשֽׁוּבָה׃","ʼábi֞⁠y hişĕ̌bi̇yʻa֣⁠niy lé⁠ʼmò֗r hiné֣̇h ʼánòkiy֮ méţ֒ bĕ̇⁠qibĕri֗⁠y ʼàşě֨r ká̇ri֤yţiy li⁠y֙ bĕ̇⁠ʼe֣reẕ kĕ̇na֔ʻan şá֖̌má̇⁠h ţi̇qĕbĕ̇ré֑⁠niy wĕ⁠ʻaţá̇֗h ʼeֽʻèleh-ná֛̇ʼ wĕ⁠ʼeqĕbĕ̇rá֥h ʼeţ-ʼábi֖⁠y wĕ⁠ʼáşֽ̌ẇbáh׃"],[50,6,"וַ⁠יֹּ֖אמֶר פַּרְעֹ֑ה עֲלֵ֛ה וּ⁠קְבֹ֥ר אֶת־אָבִ֖י⁠ךָ כַּ⁠אֲשֶׁ֥ר הִשְׁבִּיעֶֽ⁠ךָ׃","wa⁠yò֖̇ʼmer pȧrĕʻò֑h ʻàlé֛h ẇ⁠qĕbò֥r ʼeţ-ʼábi֖y⁠ká kȧ⁠ʼàşě֥r hişĕ̌bi̇yʻeֽ⁠ká׃"],[50,7,"וַ⁠יַּ֥עַל יוֹסֵ֖ף לִ⁠קְבֹּ֣ר אֶת־אָבִ֑י⁠ו וַ⁠יַּֽעֲל֨וּ אִתּ֜⁠וֹ כָּל־עַבְדֵ֤י פַרְעֹה֙ זִקְנֵ֣י בֵית֔⁠וֹ וְ⁠כֹ֖ל זִקְנֵ֥י אֶֽרֶץ־מִצְרָֽיִם׃","wa⁠yȧ֥ʻal ywòsé֖p li⁠qĕbò֣̇r ʼeţ-ʼábi֑y⁠w wa⁠ẏֽaʻàl֨ẇ ʼiţ̇֜⁠wò ká̇l-ʻabĕdé֤y parĕʻòh֙ ziqĕné֣y béyţ֔⁠wò wĕ⁠kò֖l ziqĕné֥y ʼeֽreẕ-miẕĕráֽyim׃"],[50,8,"וְ⁠כֹל֙ בֵּ֣ית יוֹסֵ֔ף וְ⁠אֶחָ֖י⁠ו וּ⁠בֵ֣ית אָבִ֑י⁠ו רַ֗ק טַפָּ⁠ם֙ וְ⁠צֹאנָ֣⁠ם וּ⁠בְקָרָ֔⁠ם עָזְב֖וּ בְּ⁠אֶ֥רֶץ גֹּֽשֶׁן׃","wĕ⁠kòl֙ bé֣̇yţ ywòsé֔p wĕ⁠ʼeẖá֖y⁠w ẇ⁠bé֣yţ ʼábi֑y⁠w ra֗q tapá̇⁠m֙ wĕ⁠ẕòʼná֣⁠m ẇ⁠bĕqárá֔⁠m ʻázĕb֖ẇ bĕ̇⁠ʼe֥reẕ gòֽ̇şěn׃"],[50,9,"וַ⁠יַּ֣עַל עִמּ֔⁠וֹ גַּם־רֶ֖כֶב גַּם־פָּרָשִׁ֑ים וַ⁠יְהִ֥י הַֽ⁠מַּחֲנֶ֖ה כָּבֵ֥ד מְאֹֽד׃","wa⁠yȧ֣ʻal ʻiṁ֔⁠wò gȧm-re֖keb gȧm-pá̇ráşǐ֑ym wa⁠yĕhi֥y haֽ⁠mȧẖàne֖h ká̇bé֥d mĕʼòֽd׃"],[50,10,"וַ⁠יָּבֹ֜אוּ עַד־גֹּ֣רֶן הָאָטָ֗ד אֲשֶׁר֙ בְּ⁠עֵ֣בֶר הַ⁠יַּרְדֵּ֔ן וַ⁠יִּ֨סְפְּדוּ־שָׁ֔ם מִסְפֵּ֛ד גָּד֥וֹל וְ⁠כָבֵ֖ד מְאֹ֑ד וַ⁠יַּ֧עַשׂ לְ⁠אָבִ֛י⁠ו אֵ֖בֶל שִׁבְעַ֥ת יָמִֽים׃","wa⁠yá̇bò֜ʼẇ ʻad-gò֣̇ren háʼátá֗d ʼàşěr֙ bĕ̇⁠ʻé֣ber ha⁠yȧrĕdé̇֔n wa⁠yi̇֨sĕpĕ̇dẇ-şá̌֔m misĕpé֛̇d gá̇d֥wòl wĕ⁠kábé֖d mĕʼò֑d wa⁠yȧ֧ʻaş̂ lĕ⁠ʼábi֛y⁠w ʼé֖bel şǐbĕʻa֥ţ yámiֽym׃"],[50,11,"וַ⁠יַּ֡רְא יוֹשֵׁב֩ הָ⁠אָ֨רֶץ הַֽ⁠כְּנַעֲנִ֜י אֶת־הָ⁠אֵ֗בֶל בְּ⁠גֹ֨רֶן֙ הָֽאָטָ֔ד וַ⁠יֹּ֣אמְר֔וּ אֵֽבֶל־כָּבֵ֥ד זֶ֖ה לְ⁠מִצְרָ֑יִם עַל־כֵּ֞ן קָרָ֤א שְׁמָ⁠הּ֙ אָבֵ֣ל מִצְרַ֔יִם אֲשֶׁ֖ר בְּ⁠עֵ֥בֶר הַ⁠יַּרְדֵּֽן׃","wa⁠yȧ֡rĕʼ ywòşé̌b֩ há⁠ʼá֨reẕ haֽ⁠kĕ̇naʻàni֜y ʼeţ-há⁠ʼé֗bel bĕ̇⁠gò֨ren֙ háֽʼátá֔d wa⁠yò֣̇ʼmĕr֔ẇ ʼéֽbel-ká̇bé֥d ze֖h lĕ⁠miẕĕrá֑yim ʻal-ké̇֞n qárá֤ʼ şĕ̌má⁠ḣ֙ ʼábé֣l miẕĕra֔yim ʼàşě֖r bĕ̇⁠ʻé֥ber ha⁠yȧrĕdéֽ̇n׃"],[50,12,"וַ⁠יַּעֲשׂ֥וּ בָנָ֖י⁠ו ל֑⁠וֹ כֵּ֖ן כַּ⁠אֲשֶׁ֥ר צִוָּֽ⁠ם׃","wa⁠yȧʻàş֥̂ẇ báná֖y⁠w l֑⁠wò ké֖̇n kȧ⁠ʼàşě֥r ẕiwáֽ̇⁠m׃"],[50,13,"וַ⁠יִּשְׂא֨וּ אֹת֤⁠וֹ בָנָי⁠ו֙ אַ֣רְצָ⁠ה כְּנַ֔עַן וַ⁠יִּקְבְּר֣וּ אֹת֔⁠וֹ בִּ⁠מְעָרַ֖ת שְׂדֵ֣ה הַ⁠מַּכְפֵּלָ֑ה אֲשֶׁ֣ר קָנָה֩ אַבְרָהָ֨ם אֶת־הַ⁠שָּׂדֶ֜ה לַ⁠אֲחֻזַּת־קֶ֗בֶר מֵ⁠אֵ֛ת עֶפְרֹ֥ן הַ⁠חִתִּ֖י עַל־פְּנֵ֥י מַמְרֵֽא׃","wa⁠yi̇şĕ̂ʼ֨ẇ ʼòţ֤⁠wò bánáy⁠w֙ ʼa֣rĕẕá⁠h kĕ̇na֔ʻan wa⁠yi̇qĕbĕ̇r֣ẇ ʼòţ֔⁠wò bi̇⁠mĕʻára֖ţ şĕ̂dé֣h ha⁠mȧkĕpé̇lá֑h ʼàşě֣r qánáh֩ ʼabĕráhá֨m ʼeţ-ha⁠şá̇̂de֜h la⁠ʼàẖuzȧţ-qe֗ber mé⁠ʼé֛ţ ʻepĕrò֥n ha⁠ẖiţi֖̇y ʻal-pĕ̇né֥y mamĕréֽʼ׃"],[50,14,"וַ⁠יָּ֨שָׁב יוֹסֵ֤ף מִצְרַ֨יְמָ⁠ה֙ ה֣וּא וְ⁠אֶחָ֔י⁠ו וְ⁠כָל־הָ⁠עֹלִ֥ים אִתּ֖⁠וֹ לִ⁠קְבֹּ֣ר אֶת־אָבִ֑י⁠ו אַחֲרֵ֖י קָבְר֥⁠וֹ אֶת־אָבִֽי⁠ו׃","wa⁠yá̇֨şá̌b ywòsé֤p miẕĕra֨yĕmá⁠h֙ h֣ẇʼ wĕ⁠ʼeẖá֔y⁠w wĕ⁠kál-há⁠ʻòli֥ym ʼiţ֖̇⁠wò li⁠qĕbò֣̇r ʼeţ-ʼábi֑y⁠w ʼaẖàré֖y qábĕr֥⁠wò ʼeţ-ʼábiֽy⁠w׃"],[50,15,"וַ⁠יִּרְא֤וּ אֲחֵֽי־יוֹסֵף֙ כִּי־מֵ֣ת אֲבִי⁠הֶ֔ם וַ⁠יֹּ֣אמְר֔וּ ל֥וּ יִשְׂטְמֵ֖⁠נוּ יוֹסֵ֑ף וְ⁠הָשֵׁ֤ב יָשִׁיב֙ לָ֔⁠נוּ אֵ֚ת כָּל־הָ֣⁠רָעָ֔ה אֲשֶׁ֥ר גָּמַ֖לְנוּ אֹתֽ⁠וֹ׃","wa⁠yi̇rĕʼ֤ẇ ʼàẖéֽy-ywòsép֙ ki̇y-mé֣ţ ʼàbiy⁠he֔m wa⁠yò֣̇ʼmĕr֔ẇ l֥ẇ yişĕ̂tĕmé֖⁠nẇ ywòsé֑p wĕ⁠háşé֤̌b yáşǐyb֙ lá֔⁠nẇ ʼé֚ţ ká̇l-há֣⁠ráʻá֔h ʼàşě֥r gá̇ma֖lĕnẇ ʼòţֽ⁠wò׃"],[50,16,"וַ⁠יְצַוּ֕וּ אֶל־יוֹסֵ֖ף לֵ⁠אמֹ֑ר אָבִ֣י⁠ךָ צִוָּ֔ה לִ⁠פְנֵ֥י מוֹת֖⁠וֹ לֵ⁠אמֹֽר׃","wa⁠yĕẕaẇ֕ẇ ʼel-ywòsé֖p lé⁠ʼmò֑r ʼábi֣y⁠ká ẕiwá̇֔h li⁠pĕné֥y mwòţ֖⁠wò lé⁠ʼmòֽr׃"],[50,17,"כֹּֽה־תֹאמְר֣וּ לְ⁠יוֹסֵ֗ף אָ֣נָּ֡א שָׂ֣א נָ֠א פֶּ֣שַׁע אַחֶ֤י⁠ךָ וְ⁠חַטָּאתָ⁠ם֙ כִּי־רָעָ֣ה גְמָל֔וּ⁠ךָ וְ⁠עַתָּה֙ שָׂ֣א נָ֔א לְ⁠פֶ֥שַׁע עַבְדֵ֖י אֱלֹהֵ֣י אָבִ֑י⁠ךָ וַ⁠יֵּ֥בְךְּ יוֹסֵ֖ף בְּ⁠דַבְּרָ֥⁠ם אֵלָֽי⁠ו׃","kòֽ̇h-ţòʼmĕr֣ẇ lĕ⁠ywòsé֗p ʼá֣ná̇֡ʼ şá֣̂ʼ ná֠ʼ pė֣şǎʻ ʼaẖe֤y⁠ká wĕ⁠ẖatá̇ʼţá⁠m֙ ki̇y-ráʻá֣h gĕmál֔ẇ⁠ká wĕ⁠ʻaţá̇h֙ şá֣̂ʼ ná֔ʼ lĕ⁠pe֥şǎʻ ʻabĕdé֖y ʼèlòhé֣y ʼábi֑y⁠ká wa⁠yé֥̇bĕkĕ̇ ywòsé֖p bĕ̇⁠dabĕ̇rá֥⁠m ʼéláֽy⁠w׃"],[50,18,"וַ⁠יֵּלְכוּ֙ גַּם־אֶחָ֔י⁠ו וַֽ⁠יִּפְּל֖וּ לְ⁠פָנָ֑י⁠ו וַ⁠יֹּ֣אמְר֔וּ הִנֶּ֥⁠נּֽוּ לְ⁠ךָ֖ לַ⁠עֲבָדִֽים׃","wa⁠yé̇lĕkẇ֙ gȧm-ʼeẖá֔y⁠w wֽa⁠yi̇pĕ̇l֖ẇ lĕ⁠páná֑y⁠w wa⁠yò֣̇ʼmĕr֔ẇ hinė֥⁠ṅֽẇ lĕ⁠ká֖ la⁠ʻàbádiֽym׃"],[50,19,"וַ⁠יֹּ֧אמֶר אֲלֵ⁠הֶ֛ם יוֹסֵ֖ף אַל־תִּירָ֑אוּ כִּ֛י הֲ⁠תַ֥חַת אֱלֹהִ֖ים אָֽנִי׃","wa⁠yò֧̇ʼmer ʼàlé⁠he֛m ywòsé֖p ʼal-ţi̇yrá֑ʼẇ ki֛̇y hà⁠ţa֥ẖaţ ʼèlòhi֖ym ʼáֽniy׃"],[50,20,"וְ⁠אַתֶּ֕ם חֲשַׁבְתֶּ֥ם עָלַ֖⁠י רָעָ֑ה אֱלֹהִים֙ חֲשָׁבָ֣⁠הּ לְ⁠טֹבָ֔ה לְמַ֗עַן עֲשֹׂ֛ה כַּ⁠יּ֥וֹם הַ⁠זֶּ֖ה לְ⁠הַחֲיֹ֥ת עַם־רָֽב׃","wĕ⁠ʼaţė֕m ẖàşǎbĕţė֥m ʻála֖⁠y ráʻá֑h ʼèlòhiym֙ ẖàşá̌bá֣⁠ḣ lĕ⁠tòbá֔h lĕma֗ʻan ʻàşò֛̂h kȧ⁠ẏ֥wòm ha⁠zė֖h lĕ⁠haẖàyò֥ţ ʻam-ráֽb׃"],[50,21,"וְ⁠עַתָּה֙ אַל־תִּירָ֔אוּ אָנֹכִ֛י אֲכַלְכֵּ֥ל אֶתְ⁠כֶ֖ם וְ⁠אֶֽת־טַפְּ⁠כֶ֑ם וַ⁠יְנַחֵ֣ם אוֹתָ֔⁠ם וַ⁠יְדַבֵּ֖ר עַל־לִבָּֽ⁠ם׃","wĕ⁠ʻaţá̇h֙ ʼal-ţi̇yrá֔ʼẇ ʼánòki֛y ʼàkalĕké֥̇l ʼeţĕ⁠ke֖m wĕ⁠ʼeֽţ-tapĕ̇⁠ke֑m wa⁠yĕnaẖé֣m ʼwòţá֔⁠m wa⁠yĕdabé֖̇r ʻal-libáֽ̇⁠m׃"],[50,22,"וַ⁠יֵּ֤שֶׁב יוֹסֵף֙ בְּ⁠מִצְרַ֔יִם ה֖וּא וּ⁠בֵ֣ית אָבִ֑י⁠ו וַ⁠יְחִ֣י יוֹסֵ֔ף מֵאָ֥ה וָ⁠עֶ֖שֶׂר שָׁנִֽים׃","wa⁠yé֤̇şěb ywòsép֙ bĕ̇⁠miẕĕra֔yim h֖ẇʼ ẇ⁠bé֣yţ ʼábi֑y⁠w wa⁠yĕẖi֣y ywòsé֔p méʼá֥h wá⁠ʻe֖şêr şá̌niֽym׃"],[50,23,"וַ⁠יַּ֤רְא יוֹסֵף֙ לְ⁠אֶפְרַ֔יִם בְּנֵ֖י שִׁלֵּשִׁ֑ים גַּ֗ם בְּנֵ֤י מָכִיר֙ בֶּן־מְנַשֶּׁ֔ה יֻלְּד֖וּ עַל־בִּרְכֵּ֥י יוֹסֵֽף׃","wa⁠yȧ֤rĕʼ ywòsép֙ lĕ⁠ʼepĕra֔yim bĕ̇né֖y şǐlé̇şǐ֑ym gȧ֗m bĕ̇né֤y mákiyr֙ bėn-mĕnaşė̌֔h yulĕ̇d֖ẇ ʻal-bi̇rĕké֥̇y ywòséֽp׃"],[50,24,"וַ⁠יֹּ֤אמֶר יוֹסֵף֙ אֶל־אֶחָ֔י⁠ו אָנֹכִ֖י מֵ֑ת וֵֽ⁠אלֹהִ֞ים פָּקֹ֧ד יִפְקֹ֣ד אֶתְ⁠כֶ֗ם וְ⁠הֶעֱלָ֤ה אֶתְ⁠כֶם֙ מִן־הָ⁠אָ֣רֶץ הַ⁠זֹּ֔את אֶל־הָ⁠אָ֕רֶץ אֲשֶׁ֥ר נִשְׁבַּ֛ע לְ⁠אַבְרָהָ֥ם לְ⁠יִצְחָ֖ק וּֽ⁠לְ⁠יַעֲקֹֽב׃","wa⁠yò֤̇ʼmer ywòsép֙ ʼel-ʼeẖá֔y⁠w ʼánòki֖y mé֑ţ wéֽ⁠ʼlòhi֞ym pá̇qò֧d yipĕqò֣d ʼeţĕ⁠ke֗m wĕ⁠heʻèlá֤h ʼeţĕ⁠kem֙ min-há⁠ʼá֣reẕ ha⁠zò̇֔ʼţ ʼel-há⁠ʼá֕reẕ ʼàşě֥r nişĕ̌bȧ֛ʻ lĕ⁠ʼabĕráhá֥m lĕ⁠yiẕĕẖá֖q ẇֽ⁠lĕ⁠yaʻàqòֽb׃"],[50,25,"וַ⁠יַּשְׁבַּ֣ע יוֹסֵ֔ף אֶת־בְּנֵ֥י יִשְׂרָאֵ֖ל לֵ⁠אמֹ֑ר פָּקֹ֨ד יִפְקֹ֤ד אֱלֹהִים֙ אֶתְ⁠כֶ֔ם וְ⁠הַעֲלִתֶ֥ם אֶת־עַצְמֹתַ֖⁠י מִ⁠זֶּֽה׃","wa⁠yȧşĕ̌bȧ֣ʻ ywòsé֔p ʼeţ-bĕ̇né֥y yişĕ̂ráʼé֖l lé⁠ʼmò֑r pá̇qò֨d yipĕqò֤d ʼèlòhiym֙ ʼeţĕ⁠ke֔m wĕ⁠haʻàliţe֥m ʼeţ-ʻaẕĕmòţa֖⁠y mi⁠zėֽh׃"],[50,26,"וַ⁠יָּ֣מָת יוֹסֵ֔ף בֶּן־מֵאָ֥ה וָ⁠עֶ֖שֶׂר שָׁנִ֑ים וַ⁠יַּחַנְט֣וּ אֹת֔⁠וֹ וַ⁠יִּ֥ישֶׂם בָּ⁠אָר֖וֹן בְּ⁠מִצְרָֽיִם׃","wa⁠yá֣̇máţ ywòsé֔p bėn-méʼá֥h wá⁠ʻe֖şêr şá̌ni֑ym wa⁠yȧẖanĕt֣ẇ ʼòţ֔⁠wò wa⁠yi֥̇yşêm bá̇⁠ʼár֖wòn bĕ̇⁠miẕĕráֽyim׃"]]}};